window.TX=window.TX||{};window.TX.alab={"Mal":{"1:1":"هذه كلمة الرب التي أوحى بها بشأن إسرائيل على لسان ملاخي:","1:2":"«يقول الرب: إنني أحببتكم، ولكنكم تسألون: كيف أحببتنا؟ ويجيب الرب: أليس عيسو أخا ليعقوب؟ ومع ذلك أحببت يعقوب،","1:3":"وأبغضت عيسو، وحولت جباله إلى أراض موحشة، وجعلت ميراثه لبنات آوى البرية.","1:4":"وإن قال الأدوميون: مع إننا تحطمنا فإننا نبني الخرب، فإن الرب القدير يقول: هم يعمرون وأنا أهدم، ويدعو الناس بلادهم، «أرض النفاق»، وأهلها بالأمة التي سخط الرب عليها إلى الأبد.","1:5":"وتشهد عيونكم هذا، وتقولون ما أعظم الرب الذي يمتد سلطانه إلى ما وراء تخوم إسرائيل.","1:6":"إن الابن يكرم أباه والعبد سيده. فإن كنت أنا حقا أبا فأين كرامتي؟ وإن كنت حقا سيدا فأين مهابتي؟ إن الرب القدير يقول لكم: أيها الكهنة المزدرون باسمي؛ فتسألون: كيف ازدرينا باسمك؟","1:7":"فيجيب: لأنكم تقربون على مذبحي خبزا نجسا. ثم تتساءلون: بم نجسناك؟ فيرد: بظنكم أن مائدة الرب مزدراة.","1:8":"عندما تقربون الحيوان الأعمى ذبيحة، أليس ذلك شرا؟ أو حين تقدمون الحيوان الأعرج والمريض، أليس هذا شرا؟ قدموا مثل هذا القربان هدية لحاكمكم، أفيرضى عنكم ويكرمكم؟ يقول الرب القدير.","1:9":"الآن التمسوا رضى الله ليرأف بنا، ولكن هل بمثل هذه القرابين المعتلة يرضى عنكم؟ يقول الرب القدير.","1:10":"آه، ياليت بينكم من يغلق أبواب الهيكل لئلا توقدوا نارا باطلة على مذبحي، يقول الرب القدير: إذ لا مسرة لي بكم ولا أرضى بتقدمة من أيديكم.","1:11":"لأنه من مشرق الشمس إلى مغربها اسمي عظيم بين الأمم، وفي كل مكان يحرق لاسمي بخور وذبائح طاهرة، لأن اسمي عظيم بين الأمم، يقول الرب القدير.","1:12":"أما أنتم فقد دنستموه، إذ قلتم إن مائدة الرب نجسة، وإن طعامها فاسد ومزدرى.","1:13":"ثم قلتم: ما هذه المشقة التي نتكبدها؟ وتأففتم علي، يقول الرب القدير. وتقربون إلي ما استوليتم عليه ظلما وما هو أعرج أو مريض، فيكون هذا تقدمة قربانكم فهل أقبل هذا من أيديكم؟ يقول الرب.","1:14":"ملعون المنافق الذي ينذر للرب ذكرا سليما من قطيعه، ثم يقرب للرب ما هو مصاب بعيب، لأني ملك عظيم واسمي مهوب بين الأمم، يقول الرب القدير».","2:1":"«والآن هاكم هذه الوصية أيها الكهنة:","2:2":"إن أبيتم الاستماع، ولم تنووا في قلوبكم أن تمجدوا اسمي، أصب عليكم اللعنة، وألعن بركاتكم، بل ها أنا قد حولتها إلى لعنات لأنكم لم تجعلوها في قلوبكم.","2:3":"ها أنا أعاقب أولادكم، وأنثر روث الحيوانات التي تقدمونها لي على وجوهكم، ثم يطرحونكم معها خارجا فوق القمامة الدنسة.","2:4":"فتدركون أني أرسلت إليكم هذه التحذيرات لكي يظل عهدي مع أبناء لاوي قائما.","2:5":"فقد كان عهدي مع لاوي ونسله عهد حياة وسلام، فوهبتهما لهم، ومنحتهم التقوى، فاتقوني ووقفوا خاشعين لاسمي يقول الرب القدير.","2:6":"نطق فمه بشريعة الحق، ولم يكن في شفتيه إثم. وسلك معي سبيل السلام والاستقامة ورد كثيرين عن المعصية.","2:7":"لأن شفتي الكاهن تحفظان العلم، ومن فمه يطلب الناس الشريعة، لأنه رسول الرب القدير.","2:8":"ولكنكم انحرفتم عن الطريق المستقيم، وأعثرتم بتعاليمكم كثيرين، ونقضتم عهدي مع النسل الكهنوتي، يقول الرب القدير.","2:9":"لذلك أحقركم وأذلكم أمام جميع الناس، لأنكم لم تطيعوا طرقي، وحابيتم في تطبيق شريعتي».","2:10":"أليس لنا جميعا أب واحد؟ ألم يخلقنا إله واحد، فما بالنا يغدر أحدنا بالآخر وندنس عهد آبائنا؟","2:11":"لقد غدر يهوذا وارتكب الرجاسة في إسرائيل وفي أورشليم لأن يهوذا قد دنس هيكل الرب المحبوب، وتزوج من بنات يعبدن آلهة غريبة.","2:12":"ليستأصل الرب من شعب إسرائيل كل من فعل هذا، من غير تمييز، وحتى ممن يقدمون قرابين للرب القدير.","2:13":"وهذا أيضا ما ارتكبتم: لقد أغرقتم مذبح الرب بالدموع، فأنتم تبكون وتنوحون لأنه لم يعد يعير تقدماتكم انتباها أو يقبلها منكم بمسرة.","2:14":"وتتساءلون: لماذا؟ لأن الرب كان شاهدا على العهد المقطوع بينك وبين زوجة صباك التي غدرت بها، مع أنها شريكتك وامرأة عهدك.","2:15":"ولكن لم يقدم على ذلك أي واحد مازالت فيه بقية من الروح. وماذا طلب هذا الواحد (أي إبراهيم)؟ ذرية الله. لهذا حافظوا على أرواحكم، ولا يغدر أحد بزوجة صباه.","2:16":"ويقول الرب إله إسرائيل: إني أمقت الطلاق وأمقت أن يغطي الرجل زوجته بجوره، كما يتغطى هو بثوبه. لذلك احترسوا على أنفسكم ولا تنكثوا عهدا.","2:17":"قد أتعبتم الرب بكلامكم، وما برحتم تتساءلون: كيف أتعبناه؟ أتعبتموه بقولكم: كل من يرتكب الشر هو صالح في عيني الرب وهو يسر بهم، أو بسؤالكم: أين هو إله العدل؟»","3:1":"«ها أنا أرسل رسولي فيمهد الطريق أمامي ويأتي الرب الذي تطلبونه فجأة إلى هيكله ويقبل أيضا ملاك العهد الذي تسرون به» يقول الرب القدير","3:2":"ولكن من يحتمل يوم مجيئه؟ ومن يثبت عند ظهوره؟ فإنه مثل نار الممحص أو أشنان القصارين.","3:3":"فيجلس ممحصا ومنقيا للفضة ليطهر أبناء لاوي ويمحصهم كالفضة والذهب، حتى يقربوا للرب تقدمات بقلوب طاهرة.","3:4":"عندئذ تكون تقدمة يهوذا وشعب أورشليم مرضية عند الرب، كالعهد بها في سالف الأيام وفي السنين الغابرة.","3:5":"وأقترب منكم لأكون شاهدا سريعا ضد السحرة والزناة والحالفين بالزور والمستغلين لأجرة العامل ومضطهدي الأرامل والأيتام، والذين يظلمون الغرباء ولا يخافونني","3:6":"فإني أنا الرب لا أتغير، لذلك أنتم أيضا لم تفنوا ياأبناء يعقوب.","3:7":"إن شأنكم كشأن آبائكم. ابتعدتم عن فرائضي ولم تطيعوها. ارجعوا إلي فأرجع إليكم، يقول الرب القدير، ولكنكم تسألون كيف نرجع؟","3:8":"أيسلب الإنسان الله ؟ لقد سلبتموني! وتسألون: بماذا سلبناك؟ في العشور والقرابين.","3:9":"أنتم، بل الأمة كلها، تحت اللعنة لأنكم سلبتموني.","3:10":"هاتوا العشور جميعها إلى بيت الخزينة ليتوافر في هيكلي طعام، واختبروني لتروا إن كنت لا أفتح كوى السماء وأفيض عليكم بركة وفيرة، يقول الرب القدير.","3:11":"وأكف عنكم أذى الجراد الملتهم، فلا يتلف لكم غلات الأرض، ولا تصاب كرومكم بالعقم، يقول الرب القدير.","3:12":"عندئذ تدعوكم جميع الشعوب «بالأمة المباركة» لأن أرضكم تكون أوض بهجة، يقول الرب القدير.","3:13":"لقد قسوتم في كلامكم علي يقول الرب، ومع ذلك تقولون: بماذا تكلمنا ضدك؟","3:14":"لقد قلتم: من العبث عبادة الله، وأي جدوى من حفظنا شعائره، والنواح أمام حضرة الرب القدير؟","3:15":"وها نحن الآن نغبط المستكبرين، ونرى فاعلي الشر يزدهرون، بل إنهم تحدوا الله ونجوا.","3:16":"ثم حدث خائفو الرب بعضهم بعضا. فأصغى الرب إلى كلامهم وسمعهم، فتم تدوين أسماء متقي الرب والمتأملين باسمه أمامه في كتاب تذكرة، ورد فيه:","3:17":"سيكونون لي، يقول الرب القدير، في اليوم الذي أصنع فيه نفائسي، وأحافظ عليهم كما يحافظ الوالد على ابنه الذي يخدمه.","3:18":"فتشرعون ثانية في التمييز بين الصالح والطالح، بين من يعبد الله ومن لا يعبده».","4:1":"«انظروا، ها يوم القضاء مقبل، لاهب كتنور يكون فيه جميع المستكبرين وفاعلي الإثم عصافة، فيحرقهم ذلك اليوم ولا يبقي لهم أصلا ولا فرعا، يقول الرب القدير.","4:2":"أما أنتم أيها المتقون اسمي فتشرق عليكم شمس البر حاملة في أجنحتها الشفاء فتنطلقون متواثبين كعجول المعلف،","4:3":"وتطأون الأشرار، إذ يكونون رمادا تحت بطون أقدامكم، في اليوم الذي أجري فيه أعمالي، يقول الرب القدير.","4:4":"اذكروا شريعة موسى عبدي وسائر فرائضي وأحكامي التي أعطيتها في جبل حوريب لجميع شعب إسرائيل.","4:5":"ها أنا أرسل إليكم إيليا النبي قبل أن يجيء يوم قضاء الرب الرهيب العظيم","4:6":"فيعطف قلب الآباء على أبنائهم وقلب الأبناء على آبائهم، لئلا آتي (إن لم يتوبوا)، وأصيب الأرض باللعنة."},"Mat":{"1:1":"هذا سجل نسب يسوع المسيح ابن داود ابن إبراهيم:","1:2":"إبراهيم أنجب إسحق. وإسحق أنجب يعقوب. ويعقوب أنجب يهوذا وإخوته.","1:3":"ويهوذا أنجب فارص وزارح من ثامار. وفارص أنجب حصرون. وحصرون أنجب أرام.","1:4":"وأرام أنجب عميناداب. وعميناداب أنجب نحشون. ونحشون أنجب سلمون.","1:5":"وسلمون أنجب بوعز من راحاب. وبوعز أنجب عوبيد من راعوث. وعوبيد أنجب يسى.","1:6":"ويسى أنجب داود الملك. وداود أنجب سليمان من التي كانت زوجة لأوريا.","1:7":"وسليمان أنجب رحبعام. ورحبعام أنجب أبيا. وأبيا أنجب آسا.","1:8":"وآسا أنجب يهوشافاط. ويهوشافاط أنجب يورام. ويورام أنجب عزيا.","1:9":"وعزيا أنجب يوثام. ويوثام أنجب أحاز. وأحاز أنجب حزقيا.","1:10":"وحزقيا أنجب منسى. ومنسى أنجب آمون. وآمون أنجب يوشيا.","1:11":"ويوشيا أنجب يكنيا وإخوته في أثناء السبي إلى بابل.","1:12":"وبعد السبي إلى بابل، يكنيا أنجب شألتئيل. وشألتئيل أنجب زربابل.","1:13":"وزربابل أنجب أبيهود. وأبيهود أنجب ألياقيم. وألياقيم أنجب عازور.","1:14":"وعازور أنجب صادوق. وصادوق أنجب أخيم. وأخيم أنجب أليود.","1:15":"وأليود أنجب أليعازر. وأليعازر أنجب متان. ومتان أنجب يعقوب.","1:16":"ويعقوب أنجب يوسف رجل مريم التي ولد منها يسوع الذي يدعى المسيح.","1:17":"فجملة الأجيال من إبراهيم إلى داود أربعة عشر جيلا؛ ومن داود إلى السبي البابلي أربعة عشر جيلا؛ ومن السبي البابلي إلى المسيح أربعة عشر جيلا.","1:18":"أما يسوع المسيح فقد تمت ولادته هكذا: كانت أمه مريم مخطوبة ليوسف؛ وقبل أن يجتمعا معا، وجدت حبلى من الروح القدس.","1:19":"وإذ كان يوسف خطيبها بارا، ولم يرد أن يشهر بها، قرر أن يتركها سرا.","1:20":"وبينما كان يفكر في الأمر، إذا ملاك من الرب قد ظهر له في حلم يقول: «يايوسف ابن داود! لا تخف أن تأتي بمريم عروسك إلى بيتك، لأن الذي هي حبلى به إنما هو من الروح القدس.","1:21":"فستلد ابنا، وأنت تسميه يسوع، لأنه هو الذي يخلص شعبه من خطاياهم».","1:22":"حدث هذا كله ليتم ما قاله الرب بلسان النبي القائل:","1:23":"«ها إن العذراء تحبل، وتلد ابنا، ويدعى عمانوئيل!» أي «الله معنا».","1:24":"ولما نهض يوسف من نومه، فعل ما أمره به الملاك الذي من الرب؛ فأتى بعروسه إلى بيته.","1:25":"ولكنه لم يدخل بها حتى ولدت ابنا، فسماه يسوع.","2:1":"وبعدما ولد يسوع في بيت لحم الواقعة في منطقة اليهودية على عهد الملك هيرودس، جاء إلى أورشليم بعض المجوس القادمين من الشرق،","2:2":"يسألون: «أين هو المولود ملك اليهود؟ فقد رأينا نجمه طالعا في الشرق، فجئنا لنسجد له».","2:3":"ولما سمع الملك هيرودس بذلك، اضطرب واضطربت معه أورشليم كلها.","2:4":"فجمع إليه رؤساء كهنة اليهود وكتبتهم جميعا، واستفسر منهم أين يولد المسيح.","2:5":"فأجابوه: «في بيت لحم باليهودية، فقد جاء في الكتاب على لسان النبي:","2:6":"وأنت يابيت لحم بأرض يهوذا، لست صغيرة الشأن أبدا بين حكام يهوذا، لأنه منك يطلع الحاكم الذي يرعى شعبي إسرائيل! »","2:7":"فاستدعى هيرودس المجوس سرا، وتحقق منهم زمن ظهور النجم.","2:8":"ثم أرسلهم إلى بيت لحم، وقال: «اذهبوا وابحثوا جيدا عن الصبي. وعندما تجدونه أخبروني، لأذهب أنا أيضا وأسجد له».","2:9":"فلما سمعوا ما قاله الملك، مضوا في سبيلهم. وإذا النجم، الذي سبق أن رأوه في الشرق، يتقدمهم حتى جاء وتوقف فوق المكان الذي كان الصبي فيه.","2:10":"فلما رأوا النجم فرحوا فرحا عظيما جدا؛","2:11":"ودخلوا البيت فوجدوا الصبي مع أمه مريم. فجثوا وسجدوا له، ثم فتحوا كنوزهم وقدموا له هدايا، ذهبا وبخورا ومرا.","2:12":"ثم أوحي إليهم في حلم ألا يرجعوا إلى هيرودس، فانصرفوا إلى بلادهم في طريق أخرى.","2:13":"وبعدما انصرف المجوس، إذا ملاك من الرب قد ظهر ليوسف في حلم، وقال له: «قم واهرب بالصبي وأمه إلى مصر، وابق فيها إلى أن آمرك بالرجوع، فإن هيرودس سيبحث عن الصبي ليقتله».","2:14":"فقام يوسف في تلك الليلة، وهرب بالصبي وأمه منطلقا إلى مصر ،","2:15":"وبقي فيها إلى أن مات هيرودس، ليتم ما قاله الرب بلسان النبي القائل: «من مصر دعوت ابني».","2:16":"وعندما أدرك هيرودس أن المجوس سخروا منه، استولى عليه الغضب الشديد، فأرسل وقتل جميع الصبيان في بيت لحم وجوارها، من ابن سنتين فما دون، بحسب زمن ظهور النجم كما تحققه من المجوس.","2:17":"عندئذ تم ما قيل بلسان النبي إرميا القائل:","2:18":"«صراخ سمع من الرامة: بكاء ونحيب شديد! راحيل تبكي على أولادها، وتأبى أن تتعزى، لأنهم قد رحلوا! »","2:19":"لما مات هيرودس، إذا ملاك من الرب قد ظهر في حلم ليوسف في مصر،","2:20":"وقال له: «قم ارجع بالصبي وأمه إلى أرض إسر ائيل، فقد مات الذين كانوا يسعون إلى قتله!»","2:21":"فقام ورجع بالصبي وأمه إلى أرض إسرائيل.","2:22":"ولكنه حين سمع أن أرخيلاوس يملك على منطقة اليهودية خلفا لأبيه هيرودس، خاف أن يذهب إلى هناك. وإذ أوحي إليه في حلم، توجه إلى نواحي منطقة الجليل،","2:23":"فوصل بلدة تسمى «الناصرة» وسكن فيها، ليتم ما قيل بلسان الأنبياء إنه سيدعى ناصريا!","3:1":"في تلك الفترة من الزمان، ظهر يوحنا المعمدان في برية اليهودية، يبشر","3:2":"قائلا: «توبوا، فقد اقترب ملكوت السماوات!»","3:3":"ويوحنا هذا هو الذي قيل عنه بلسان النبي إشعياء القائل: «صوت مناد في البرية: أعدوا طريق الرب، واجعلوا سبله مستقيمة!»","3:4":"وكان يوحنا يلبس ثوبا من وبر الجمال، ويشد وسطه بحزام من جلد، ويقتات الجراد والعسل البري.","3:5":"فخرج إليه أهل أورشليم ومنطقة اليهودية كلها وجميع القرى المجاورة للأردن؛","3:6":"فكانوا يتعمدون على يده في نهر الأردن معترفين بخطاياهم.","3:7":"ولما رأى يوحنا كثيرين من الفر يسيين والصدوقيين يأتون إليه ليتعمدوا، قال لهم: «ياأولاد الأفاعي، من أنذركم لتهربوا من الغضب الآتي؟","3:8":"فأثمروا ثمرا يليق بالتوبة.","3:9":"ولا تعللوا أنفسكم قائلين: لنا إبراهيم أبا! فإني أقول لكم: إن الله قادر أن يطلع من هذه الحجارة أولادا لإبراهيم.","3:10":"وها إن الفأس قد ألقيت على أصل الشجر، فكل شجرة لا تثمر ثمرا جيدا تقطع وتطرح في النار.","3:11":"أنا أعمدكم بالماء لأجل التوبة، ولكن الآتي بعدي هو أقدر مني، وأنا لا أستحق أن أحمل حذاءه. هو سيعمدكم بالروح القدس، وبالنار.","3:12":"فهو يحمل المذرى بيده، وسينقي بيدره تماما: فيجمع قمحه إلى المخزن، وأما التبن فيحرقه بنار لا تطفأ! »","3:13":"ثم جاء يسوع من منطقة الجليل إلى نهر الأردن، وقصد إلى يوحنا ليتعمد على يده.","3:14":"لكن يوحنا أخذ يمانعه قائلا: «أنا المحتاج أن أتعمد على يدك، وأنت تأتي إلي!»","3:15":"ولكن يسوع أجابه: «اسمح الآن بذلك! فهكذا يليق بنا أن نتم كل بر». عندئذ سمح له.","3:16":"فلما تعمد يسوع، صعد من الماء في الحال، وإذا السماوات قد انفتحت له ورأى روح الله هابطا ونازلا عليه كأنه حمامة.","3:17":"وإذا صوت من السماوات يقول: «هذا هو ابني الحبيب، الذي به سررت كل سرور! »","4:1":"ثم صعد الروح بيسوع إلى البرية، ليجرب من قبل إبليس.","4:2":"وبعدما صام أربعين نهارا وأربعين ليلة، جاع أخيرا،","4:3":"فتقدم إليه المجرب وقال له: «إن كنت ابن الله، فقل لهذه الحجارة أن تتحول إلى خبز!»","4:4":"فأجابه قائلا: «قد كتب: ليس بالخبز وحده يحيا الإنسان، بل بكل كلمة تخرج من فم الله!»","4:5":"ثم أخذه إبليس إلى المدينة المقدسة، وأوقفه على حافة سطح الهيكل،","4:6":"وقال له: «إن كنت ابن الله، فاطرح نفسك إلى أسفل، لأنه قد كتب: يوصي ملائكته بك، فيحملونك على أيديهم لكي لا تصدم قدمك بحجر!»","4:7":"فقال له يسوع: «وقد كتب أيضا: لا تجرب الرب إلهك! »","4:8":"ثم أخذه إبليس أيضا إلى قمة جبل عال جدا، وأراه جميع ممالك العالم وعظمتها،","4:9":"وقال له: «أعطيك هذه كلها إن جثوت وسجدت لي!»","4:10":"فقال له يسوع: «اذهب ياشيطان! فقد كتب: للرب إلهك تسجد، وإياه وحده تعبد! »","4:11":"فتركه إبليس، وإذا بعض الملائكة جاءوا إليه وأخذوا يخدمونه.","4:12":"ولما سمع يسوع أنه قد ألقي القبض على يوحنا، عاد إلى منطقة الجليل.","4:13":"وإذ ترك الناصرة، توجه إلى كفرناحوم الواقعة على شاطيء البحيرة ضمن حدود زبولون ونفتاليم، وسكن فيها،","4:14":"ليتم ما قيل بلسان النبي إشعياء القائل:","4:15":"«أرض زبولون وأرض نفتاليم، على طريق البحيرة ما وراء نهر الأردن، بلاد الجليل التي يسكنها الأجانب،","4:16":"الشعب الجالس في الظلمة، أبصر نورا عظيما، والجالسون في أرض الموت وظلاله، أشرق عليهم نور ! »","4:17":"من ذلك الحين بدأ يسوع يبشر قائلا: «توبوا، فقد اقترب ملكوت السماوات! »","4:18":"وبينما كان يسوع يمشي على شاطيء بحيرة الجليل، رأى أخوين، هما سمعان الذي يدعى بطرس وأندراوس أخوه، يلقيان الشبكة في البحيرة، إذ كانا صيادين.","4:19":"فقال لهما: «هيا اتبعاني، فأجعلكما صيادين للناس!»","4:20":"فتركا الشباك وتبعاه حالا.","4:21":"وسار من هناك فرأى أخوين آخرين، هما يعقوب بن زبدي ويوحنا أخوه، في القارب مع أبيهما يصلحان شباكهما، فدعاهما ليتبعاه.","4:22":"فتركا القارب وأباهما، وتبعاه حالا.","4:23":"وكان يسوع يتنقل في منطقة الجليل كلها، يعلم في مجامع اليهود، وينادي ببشارة الملكوت، ويشفي كل مرض وعلة في الشعب،","4:24":"فذاع صيته في سورية كلها. فحمل إليه الناس مرضاهم المعانين من الأمراض والأوجاع على اختلافها، والمسكونين بالشياطين، والمصروعين، والمشلولين، فشفاهم جميعا.","4:25":"فتبعته جموع كبيرة من مناطق الجليل، والمدن العشر، وأورشليم، واليهودية، وما وراء الأردن.","5:1":"وإذ رأى جموع الناس، صعد إلى الجبل. وما إن جلس، حتى اقترب إليه تلاميذه.","5:2":"فتكلم وأخذ يعلمهم. فقال:","5:3":"«طوبى للمساكين بالروح، فإن لهم ملكوت السماوات.","5:4":"طوبى للحزانى، فإنهم سيعزون.","5:5":"طوبى للودعاء، فإنهم سيرثون الأرض.","5:6":"طوبى للجياع والعطاش إلى البر، فإنهم سيشبعون.","5:7":"طوبى للرحماء، فإنهم سيرحمون.","5:8":"طوبى لأنقياء القلب، فإنهم سيرون الله .","5:9":"طوبى لصانعي السلام، فإنهم سيدعون أبناء الله.","5:10":"طوبى للمضطهدين من أجل البر، فإن لهم ملكوت السماوات.","5:11":"طوبى لكم متى أهانكم الناس واضطهدوكم، وقالوا فيكم من أجلي كل سوء كاذبين.","5:12":"افرحوا وتهللوا، فإن مكافأتكم في السماوات عظيمة. فإنهم هكذا اضطهدوا الأنبياء من قبلكم!","5:13":"أنتم ملح الأرض. فإذا فسد الملح، فماذا يعيد إليه ملوحته؟ إنه لا يعود يصلح لشيء إلا لأن يطرح خارجا لتدوسه الناس!","5:14":"أنتم نور العالم. لا يمكن أن تخفى مدينة مبنية على جبل؛","5:15":"ولا يضيء الناس مصباحا ثم يضعونه تحت مكيال، بل يضعونه في مكان مرتفع ليضيء لجميع من في البيت.","5:16":"هكذا، فليضيء نوركم أمام الناس، ليروا أعمالكم الحسنة ويمجدوا أباكم الذي في السماوات.","5:17":"لا تظنوا أني جئت لألغي الشريعة أو الأنبياء. ما جئت لألغي، بل لأكمل.","5:18":"فالحق أقول لكم: إلى أن تزول الأرض والسماء، لن يزول حرف واحد أو نقطة واحدة من الشريعة، حتى يتم كل شيء.","5:19":"فأي من خالف واحدة من هذه الوصايا الصغرى، وعلم الناس أن يفعلوا فعله، يدعى الأصغر في ملكوت السماوات. وأما من عمل بها وعلمها، فيدعى عظيما في ملكوت السماوات.","5:20":"فإني أقول لكم: إن لم يزد بركم على بر الكتبة والفريسيين، لن تدخلوا ملكوت السماوات أبدا.","5:21":"سمعتم أنه قيل للأقدمين: لا تقتل! ومن قتل يستحق المحاكمة.","5:22":"أما أنا فأقول لكم: كل من هو غاضب على أخيه، يستحق المحاكمة؛ ومن يقول لأخيه: ياتافه! يستحق المثول أمام المجلس الأعلى؛ ومن يقول: ياأحمق! يستحق نار جهنم!","5:23":"فإذا جئت بتقدمتك إلى المذبح، وهناك تذكرت أن لأخيك شيئا عليك،","5:24":"فاترك تقدمتك أمام المذبح، واذهب أولا وصالح أخاك، ثم ارجع وقدم تقدمتك.","5:25":"سارع إلى استرضاء خصمك وأنت معه في الطريق إلى المحكمة، قبل أن يسلمك الخصم إلى القاضي، فيسلمك القاضي إلى الشرطي، فيلقيك في السجن.","5:26":"والحق أقول لك إنك لن تخرج من السجن حتى توفي الفلس الأخير!","5:27":"وسمعتم أنه قيل: لا تزن!","5:28":"أما أنا فأقول لكم: كل من ينظر إلى امرأة بقصد أن يشتهيها، فقد زنى بها في قلبه!","5:29":"فإن كانت عينك اليمنى فخا لك، فاقلعها وارمها عنك، فخير لك أن تفقد عضوا من أعضائك ولا يطرح جسدك كله في جهنم!","5:30":"وإن كانت يدك اليمنى فخا لك، فاقطعها وارمها عنك، فخير لك أن تفقد عضوا من أعضائك ولا يطرح جسدك كله في جهنم!","5:31":"وقيل أيضا: من طلق زوجته، فليعطها وثيقة طلاق.","5:32":"أما أنا فأقول لكم: كل من طلق زوجته لغير علة الزنى، فهو يجعلها ترتكب الزنى. ومن تزوج بمطلقة، فهو يرتكب الزنى.","5:33":"وسمعتم أنه قيل للأقدمين: لا تخالف قسمك، بل أوف للرب ما نذرته له.","5:34":"أما أنا فأقول لكم: لا تحلفوا أبدا، لا بالسماء لأنها عرش الله،","5:35":"ولا بالأرض لأنها موطيء قدميه، ولا بأورشليم لأنها مدينة الملك الأعظم.","5:36":"ولا تحلف برأسك لأنك لا تقدر أن تجعل شعرة واحدة فيها بيضاء أو سوداء.","5:37":"ليكن كلامكم: نعم، إن كان نعم؛ أو: لا، إن كان لا. وما زاد على ذلك فهو من الشرير.","5:38":"وسمعتم أنه قيل: عين بعين وسن بسن.","5:39":"أما أنا فأقول لكم: لا تقاوموا الشر بمثله، بل من لطمك على خدك الأيمن، فأدر له الخد الآخر؛","5:40":"ومن أراد محاكمتك ليأخذ ثوبك، فاترك له رداءك أيضا؛","5:41":"ومن سخرك أن تسير ميلا، فسر معه ميلين.","5:42":"من طلب منك شيئا، فأعطه. ومن جاء يقترض منك، فلا ترده خائبا!","5:43":"وسمعتم أنه قيل: تحب قريبك وتبغض عدوك.","5:44":"أما أنا فأقول لكم: أحبوا أعداءكم، وباركوا لاعنيكم، وأحسنوا معاملة الذين يبغضونكم، وصلوا لأجل الذين يسيئون إليكم ويضطهدونكم،","5:45":"فتكونوا أبناء أبيكم الذي في السماوات: فإنه يشرق بشمسه على الأشرار والصالحين، ويمطر على الأبرار وغير الأبرار.","5:46":"فإن أحببتم الذين يحبونكم، فأية مكافأة لكم؟ أما يفعل ذلك حتى جباة الضرائب؟","5:47":"وإن رحبتم بإخوانكم فقط، فأي شيء فائق للعادة تفعلون؟ أما يفعل ذلك حتى الوثنيون؟","5:48":"فكونوا أنتم كاملين، كما أن أباكم السماوي هو كامل!","6:1":"احذروا من أن تعملوا بركم أمام الناس بقصد أن ينظروا إليكم. وإلا، فليس لكم مكافأة عند أبيكم الذي في السماوات.","6:2":"فإذا تصدقت على أحد، فلا تنفخ أمامك في البوق، كما يفعل المراؤون في المجامع والشوارع، ليمدحهم الناس. الحق أقول لكم: إنهم قد نالوا مكافأتهم.","6:3":"أما أنت، فعندما تتصدق على أحد، فلا تدع يدك اليسرى تعرف ما تفعله اليمنى.","6:4":"لتكون صدقتك في الخفاء، وأبوك السماوي الذي يرى في الخفاء، هو يكافئك.","6:5":"وعندما تصلون، لا تكونوا مثل المرائين الذين يحبون أن يصلوا واقفين في المجامع وفي زوايا الشوارع ليراهم الناس. الحق أقول لكم: إنهم قد نالوا مكافأتهم.","6:6":"أما أنت، فعندما تصلي، فادخل غرفتك، وأغلق الباب عليك، وصل إلى أبيك الذي في الخفاء. وأبوك الذي يرى في الخفاء، هو يكافئك.","6:7":"وعندما تصلون، لا تكرروا كلاما فارغا كما يفعل الوثنيون، ظنا منهم أنه بالإكثار من الكلام، يستجاب لهم.","6:8":"فلا تكونوا مثلهم، لأن أباكم يعلم ما تحتاجون إليه قبل أن تسألوه.","6:9":"فصلوا أنتم مثل هذه الصلاة: أبانا الذي في السماوات، ليتقدس اسمك!","6:10":"ليأت ملكوتك! لتكن مشيئتك على الأرض كما هي في السماء!","6:11":"خبزنا كفافنا أعطنا اليوم!","6:12":"واغفر لنا ذنوبنا، كما نغفر نحن للمذنبين إلينا!","6:13":"ولا تدخلنا في تجربة، لكن نجنا من الشرير، لأن لك الملك والقوة والمجد إلى الأبد. آمين.","6:14":"فإن غفرتم للناس زلاتهم، يغفر لكم أبوكم السماوي زلاتكم.","6:15":"وإن لم تغفروا للناس، لا يغفر لكم أبوكم السماوي زلاتكم.","6:16":"وعندما تصومون، لا تكونوا عابسي الوجوه، كما يفعل المراؤون الذين يقطبون وجوههم لكي يظهروا للناس صائمين. الحق أقول لكم إنهم قد نالوا مكافأتهم.","6:17":"أما أنت، فعندما تصوم، فاغسل وجهك، وعطر رأسك،","6:18":"لكي لا تظهر للناس صائما، بل لأبيك الذي في الخفاء. وأبوك الذي يرى في الخفاء، هو يكافئك.","6:19":"لا تكنزوا لكم كنوزا على الأرض، حيث يفسدها السوس والصدأ، وينقب عنها اللصوص ويسرقون.","6:20":"بل اكنزوا لكم كنوزا في السماء، حيث لا يفسدها سوس ولا ينقب عنها لصوص ولا يسرقون.","6:21":"فحيث يكون كنزك، هناك أيضا يكون قلبك !","6:22":"العين مصباح الجسد. فإن كانت عينك سليمة، يكون جسدك كله منورا.","6:23":"وإن كانت عينك سيئة، يكون جسدك كله مظلما. فإذا كان النور الذي فيك ظلاما، فما أشد الظلام!","6:24":"لا يمكن لأحد أن يكون عبدا لسيدين: لأنه إما أن يبغض أحدهما فيحب الآخر، وإما أن يلزم أحدهما فيهجر الآخر. لا يمكنكم أن تكونوا عبيدا لله والمال معا.","6:25":"لذلك أقول لكم: لا تهتموا لمعيشتكم بشأن ما تأكلون وما تشربون، ولا لأجسادكم بشأن ما تكتسون. أليست الحياة أكثر من مجرد طعام، والجسد أكثر من مجرد كساء؟","6:26":"تأملوا طيور السماء: إنها لا تزرع ولا تحصد ولا تجمع في مخازن، وأبوكم السماوي يعولها. أفلستم أنتم أفضل منها كثيرا؟","6:27":"فمن منكم إذا حمل الهموم يقدر أن يطيل عمره ولو ساعة واحدة؟","6:28":"ولماذا تحملون هم الكساء؟ تأملوا زنابق الحقل كيف تنمو: إنها لا تتعب ولا تغزل؛","6:29":"ولكني أقول لكم: حتى سليمان في قمة مجده لم يكتس ما يعادل واحدة منها بهاء!","6:30":"فإن كان الله هكذا يكسو الأعشاب البرية مع أنها توجد اليوم وتطرح غدا في النار، أفلستم أنتم، ياقليلي الإيمان، أحرى جدا بأن يكسوكم؟","6:31":"فلا تحملوا الهم قائلين: ما عسانا نأكل؟ أو: ما عسانا نشرب؟ أو: ما عسانا نكتسي؟","6:32":"فهذه الحاجات كلها تسعى إليها الأمم. فإن أباكم السماوي يعلم حاجتكم إلى هذه كلها.","6:33":"أما أنتم، فاطلبوا أولا ملكوت الله وبره، وهذه كلها تزاد لكم.","6:34":"لا تهتموا بأمر الغد، فإن الغد يهتم بأمر نفسه. يكفي كل يوم ما فيه من سوء!","7:1":"لا تدينوا لئلا تدانوا.","7:2":"فإنكم بالدينونة التي بها تدينون تدانون؛ وبالكيل الذي به تكيلون يكال لكم.","7:3":"لماذا تلاحظ القشة في عين أخيك، ولكنك لا تتنبه إلى الخشبة الكبيرة في عينك؟","7:4":"أو كيف تقول لأخيك: دعني أخرج القشة من عينك، وها هي الخشبة في عينك أنت!","7:5":"يامرائي! أخرج أولا الخشبة من عينك، وعندئذ تبصر جيدا لتخرج القشة من عين أخيك.","7:6":"لا تعطوا ما هو مقدس للكلاب، ولا تطرحوا جواهركم أمام الخنازير، لكي لا تدوسها بأرجلها وتنقلب عليكم فتمزقكم.","7:7":"اسألوا، تعطوا. اطلبوا، تجدوا. اقرعوا، يفتح لكم.","7:8":"فكل من يسأل، ينل؛ ومن يطلب، يجد؛ ومن يقرع، يفتح له.","7:9":"وإلا، فأي إنسان منكم يطلب منه ابنه خبزا، فيعطيه حجرا،","7:10":"أو سمكة، فيعطيه حية؟","7:11":"فإن كنتم وأنتم أشرار، تعرفون أن تعطوا أولادكم عطايا جيدة، فكم بالأحرى جدا يعطي أبوكم السماوي عطايا جيدة للذين يطلبون منه؟","7:12":"إذن، كل ما تريدون أن يعاملكم الناس به، فعاملوهم أنتم به أيضا: هذه خلاصة تعليم الشريعة والأنبياء.","7:13":"ادخلوا من الباب الضيق! فإن الباب المؤدي إلى الهلاك واسع وطريقه رحب؛ وكثيرون هم الذين يدخلون منه.","7:14":"ما أضيق الباب وأعسر الطريق المؤدي إلى الحياة! وقليلون هم الذين يهتدون إليه.","7:15":"احذروا الأنبياء الدجالين الذين يأتون إليكم لابسين ثياب الحملان، ولكنهم من الداخل ذئاب خاطفة!","7:16":"من ثمارهم تعرفونهم. هل يجنى من الشوك عنب، أو من العليق تين؟","7:17":"هكذا، كل شجرة جيدة تثمر ثمرا جيدا. أما الشجرة الرديئة، فإنها تثمر ثمرا رديئا.","7:18":"لا يمكن أن تثمر الشجرة الجيدة ثمرا رديئا، ولا الشجرة الرديئة ثمرا جيدا.","7:19":"وكل شجرة لا تثمر ثمرا جيدا، تقطع وتطرح في النار.","7:20":"إذن من ثمارهم تعرفونهم.","7:21":"ليس كل من يقول لي: يارب، يارب! يدخل ملكوت السماوات، بل من يعمل بإرادة أبي الذي في السماوات.","7:22":"في ذلك اليوم سيقول لي كثيرون: يارب، يارب، أليس باسمك تنبأنا، وباسمك طردنا الشياطين، وباسمك عملنا معجزات كثيرة؟","7:23":"ولكني عندئذ أصرح لهم: إني لم أعرفكم قط! ابتعدوا عني يافاعلي الإثم!","7:24":"فأي من يسمع أقوالي هذه ويعمل بها، أشبهه برجل حكيم بنى بيته على الصخر،","7:25":"فنزلت الأمطار، وجرت السيول، وهبت العواصف، فضربت ذلك البيت، فلم يسقط لأنه مؤسس على الصخر.","7:26":"وأي من يسمع أقوالي هذه ولا يعمل بها، يشبه برجل غبي بنى بيته على الرمل،","7:27":"فنزلت الأمطار، وجرت السيول، وهبت العواصف، فضربت ذلك البيت، فسقط، وكان سقوطه عظيما»","7:28":"ولما أنهى يسوع هذا الكلام، ذهلت الجموع من تعليمه،","7:29":"لأنه كان يعلمهم كصاحب سلطان، وليس مثل كتبتهم.","8:1":"ولما نزل من الجبل، تبعته جموع كثيرة.","8:2":"وإذا رجل مصاب بالبرص، تقدم إليه وسجد له قائلا: «ياسيد، إن كنت تريد، فأنت قادر أن تطهرني!»","8:3":"فمد يده ولمسه وقال: «إني أريد، فاطهر!» وفي الحال طهر الرجل من برصه.","8:4":"وقال له يسوع: «انتبه! لا تخبر أحدا، بل اذهب واعرض نفسك على الكاهن، وقدم القربان الذي أمر به موسى، فيكون ذلك شهادة لهم! »","8:5":"وحالما دخل يسوع مدينة كفرناحوم، جاءه قائد مئة يتوسل إليه","8:6":"قائلا: «ياسيد! إن خادمي مشلول طريح الفراش في البيت، يعاني أشد الآلام».","8:7":"فقال له يسوع: «سأذهب وأشفيه!»","8:8":"فأجاب قائد المئة: «ياسيد، أنا لا أستحق أن تدخل تحت سقف بيتي. إنما قل كلمة، فيشفى خادمي.","8:9":"فأنا أيضا رجل تحت سلطة أعلى مني، ولي جنود تحت إمرتي؛ أقول لأحدهم: اذهب! فيذهب، ولآخر: تعال! فيأتي، ولعبدي: افعل هذا! فيفعل».","8:10":"فلما سمع يسوع ذلك، تعجب وقال لمن يتبعونه: «الحق أقول لكم: لم أجد في أحد من إسرائيل إيمانا عظيما كهذا!","8:11":"وأقول لكم: إن كثيرين سيأتون من المشرق والمغرب ويتكئون مع إبراهيم وإسحق ويعقوب في ملكوت السماوات.","8:12":"أما بنو الملكوت، فيطرحون في الظلمة الخارجية، هناك يكون البكاء وصرير الأسنان!»","8:13":"ثم قال يسوع لقائد المئة: «اذهب، وليكن لك ما آمنت بأن يكون!» وفي تلك الساعة شفي خادمه.","8:14":"وذهب يسوع إلى بيت بطرس، فوجد حماته طريحة الفراش تعاني من الحمى.","8:15":"فلمس يدها، فذهبت عنها الحمى، ونهضت وأخذت تخدمه.","8:16":"وعند حلول المساء، أحضر إليه الناس كثيرين من المسكونين بالشياطين. فكان يطرد الشياطين بكلمة منه. وشفى المرضى جميعا،","8:17":"لكي يتم ما قيل بلسان النبي إشعياء القائل: «هو أخذ أسقامنا، وحمل أمراضنا».","8:18":"وحين رأى يسوع أن الجموع قد احتشدت حوله، أمر تلاميذه أن يعبروا إلى الضفة المقابلة.","8:19":"فتقدم إليه أحد الكتبة وقال: «يامعلم، سأتبعك حيثما تذهب!»","8:20":"فأجابه يسوع: «للثعالب أوجار، ولطيور السماء أوكار؛ أما ابن الإنسان، فليس له مكان يسند إليه رأسه».","8:21":"وقال له آخر من تلاميذه: «ياسيد، اسمح لي أن أذهب أولا فأدفن أبي!»","8:22":"فأجابه يسوع: «اتبعني الآن، ودع الموتى يدفنون موتاهم! »","8:23":"ثم ركب القارب، وتبعه تلاميذه.","8:24":"وإذا عاصفة شديدة قد هبت على البحيرة، حتى كادت المياه أن تبتلع القارب. وكان هو نائما.","8:25":"فأسرع التلاميذ إليه يوقظونه قائلين: «ياسيد، نجنا! إننا نهلك!»","8:26":"فقال لهم: «لماذا أنتم خائفون، ياقليلي الإيمان؟» ثم نهض وزجر الريح والبحر، فساد هدوء تام.","8:27":"فتعجب الناس وقالوا: «ترى، من هذا حتى إن الريح والبحر يطيعانه؟ »","8:28":"ولما وصل يسوع إلى الضفة المقابلة، في بلدة الجدريين، لاقاه رجلان تسكنهما الشياطين، كانا خارجين من بين القبور، وهما شرسان جدا حتى لم يكن أحد يجرؤ على المرور من تلك الطريق.","8:29":"وفجأة صرخا قائلين: «ما شأنك بنا يايسوع ابن الله؟ أجئت إلى هنا قبل الأوان لتعذبنا؟»","8:30":"وكان قطيع كبير من الخنازير يرعى على مسافة منهما،","8:31":"فقالت الشياطين ليسوع: «إن كنت ستطردنا، فأرسلنا إلى قطيع الخنازير».","8:32":"فقال لهم: «اذهبوا!» فخرجوا وانتقلوا إلى قطيع الخنازير، فاندفع القطيع مسرعا من على حافة الجبل إلى البحيرة، ومات فيها غرقا.","8:33":"وهرب رعاة الخنازير إلى المدينة، ونقلوا خبر كل ما جرى، وما حدث للمسكونين.","8:34":"وإذا المدينة كلها قد خرجت للقاء يسوع. ولما وجده أهلها، طلبوا إليه أن يرحل عن ديارهم.","9:1":"ثم ركب يسوع القارب، وعبر البحيرة راجعا إلى بلدته (كفرناحوم)،","9:2":"فجاءه بعضهم يحملون مشلولا مطروحا على فراش. فلما رأى يسوع إيمانهم، قال للمشلول: «اطمئن يابني! قد غفرت لك خطاياك»","9:3":"فقال بعض الكتبة في أنفسهم: «إنه يجدف!»","9:4":"وأدرك يسوع ما يفكرون فيه، فسألهم: «لماذا تفكرون بالشر في قلوبكم؟","9:5":"أيهما الأسهل: أن يقال: قد غفرت لك خطاياك، أم أن يقال: قم وامش؟","9:6":"ولكني (قلت ذلك) لكي تعلموا أن لابن الإنسان على الأرض سلطة غفران الخطايا». عندئذ قال للمشلول: «قم احمل فراشك، واذهب إلى بيتك!»","9:7":"فقام، وذهب إلى بيته.","9:8":"فلما رأت الجموع ذلك، استولى عليهم الخوف، ومجدوا الله الذي أعطى الناس مثل هذه السلطة.","9:9":"وفيما كان يسوع مارا بالقرب من مكتب جباية الضرائب، رأى جابيا اسمه متى جالسا هناك. فقال له: «اتبعني!» فقام وتبعه.","9:10":"وبينما كان يسوع متكئا في بيت متى، حضر كثيرون من الجباة والخاطئين، واتكأوا مع يسوع وتلاميذه.","9:11":"وعندما رأى الفريسيون ذلك، قالوا لتلاميذه: «لماذا يأكل معلمكم مع الجباة والخاطئين؟»","9:12":"وإذ سمع يسوع كلامهم، قال: «ليس الأصحاء هم المحتاجون إلى الطبيب، بل المرضى!","9:13":"اذهبوا وتعلموا معنى القول: إني أطلب رحمة لا ذبيحة. فإني ما جئت لأدعو أبرارا بل خاطئين! »","9:14":"ثم تقدم تلاميذ يوحنا إلى يسوع يسألونه: «لماذا نصوم نحن والفريسيون، ولا يصوم تلاميذك؟»","9:15":"فقال لهم يسوع: «هل يقدر أهل العرس أن يحزنوا مادام العريس بينهم؟ ولكن، ستأتي أيام يكون فيها العريس قد رفع من بينهم، فعندئذ يصومون!","9:16":"لا أحد يرقع ثوبا عتيقا من قماش جديد، لأن الرقعة الجديدة تنكمش، فتأكل من الثوب العتيق، ويصير الخرق أسوأ!","9:17":"ولا يضع الناس الخمر الجديدة في قرب عتيقة؛ وإلا، فإن القرب تنفجر، فتراق الخمر وتتلف القرب. ولكنهم يضعون الخمر الجديدة في قرب جديدة، فتحفظ الخمر والقرب معا! »","9:18":"وبينما كان يقول هذا، إذا رئيس للمجمع قد تقدم وسجد له قائلا:","9:19":"«ابنتي الآن ماتت. ولكن تعال والمسها بيدك فتحيا» فقام يسوع وتبعه ومعه تلاميذه.","9:20":"وإذا امرأة مصابة بنزيف دموي منذ اثنتي عشرة سنة، قد تقدمت إليه من خلف، ولمست طرف ردائه،","9:21":"لأنها قالت في نفسها: «يكفي أن ألمس ولو ثيابه لأشفى!»","9:22":"فالتفت يسوع ورآها، فقال: «اطمئني ياابنة. إيمانك قد شفاك!» فشفيت المرأة من تلك الساعة.","9:23":"ولما دخل يسوع بيت رئيس المجمع، ورأى النادبين بالمزمار والجمع في اضطراب،","9:24":"قال: «انصرفوا! فالصبية لم تمت، ولكنها نائمة!» فضحكوا منه.","9:25":"فلما أخرج الجمع، دخل وأمسك بيد الصبية، فنهضت.","9:26":"وذاع خبر ذلك في تلك البلاد كلها.","9:27":"وفيما كان يسوع راحلا من هناك، تبعه أعميان يصرخان قائلين: «ارحمنا ياابن داود!»","9:28":"وعند دخوله البيت تقدما إليه. فسألهما يسوع: «أتؤمنان بأني أقدر أن أفعل هذا؟» أجابا: «نعم ياسيد!»","9:29":"فلمس أعينهما قائلا: «ليكن لكما بحسب إيمانكما!»","9:30":"فانفتحت أعينهما. وأنذرهما يسوع بشدة قائلا: انتبها! لا تخبرا أحدا!»","9:31":"ولكنهما انطلقا وأذاعا صيته في تلك البلاد كلها.","9:32":"وما إن خرجا، حتى جاءه بعضهم بأخرس يسكنه شيطان.","9:33":"فلما طرد الشيطان، تكلم الأخرس. فتعجبت الجموع، وقالوا: «ما شوهد مثل هذا قط في إسرائيل».","9:34":"أما الفريسيون فقالوا: «إنه يطرد الشياطين برئيس الشياطين! »","9:35":"وأخذ يسوع يتنقل في المدن والقرى كلها، يعلم في مجامع اليهود وينادي ببشارة الملكوت، ويشفي كل مرض وعلة.","9:36":"وعندما رأى الجموع، أخذته الشفقة عليهم، إذ كانوا معذبين ومشردين كغنم لا راعي لها.","9:37":"عندئذ قال لتلاميذه: «الحصاد كثير، والعمال قليلون.","9:38":"فاطلبوا من رب الحصاد أن يرسل عمالا إلى حصاده! »","10:1":"ثم دعا إليه تلاميذه الاثني عشر، وأعطاهم سلطانا على الأرواح النجسة ليطردوها ويشفوا كل مرض وعلة.","10:2":"وهذه أسماء الاثني عشر رسولا: سمعان الذي دعي بطرس، وأندراوس أخوه، ويعقوب بن زبدي، ويوحنا أخوه؛","10:3":"فيلبس، وبرثلماوس؛ توما، ومتى جابي الضرائب؛ يعقوب بن حلفى، وتداوس؛","10:4":"سمعان القانوي؛ ويهوذا الإسخريوطي الذي خانه.","10:5":"هؤلاء الاثنا عشر رسولا، أرسلهم يسوع وقد أوصاهم قائلا: «لا تسلكوا طريقا إلى الأمم، ولا تدخلوا مدينة سامرية.","10:6":"بل اذهبوا بالأحرى إلى الخراف الضالة، إلى بيت إسرائيل.","10:7":"وفيما أنتم ذاهبون، بشروا قائلين: قد اقترب ملكوت السماوات.","10:8":"المرضى اشفوا، والموتى أقيموا، والبرص طهروا، والشياطين اطردوا. مجانا أخذتم، فمجانا أعطوا!","10:9":"لا تحملوا في أحزمتكم ذهبا ولا فضة ولا نحاسا،","10:10":"ولا تأخذوا للطريق زادا ولا ثوبين ولا حذاء ولا عصا: فإن العامل يستحق طعامه.","10:11":"وكلما دخلتم مدينة أو قرية، فابحثوا فيها عمن هو مستحق، وأقيموا هناك حتى ترحلوا.","10:12":"وعندما تدخلون بيتا، ألقوا السلام عليه.","10:13":"فإذا كان ذلك البيت مستحقا فعلا، فليحل سلامكم عليه. وإن لم يكن مستحقا، فليرجع سلامكم لكم","10:14":"وإن كان أحد لا يقبلكم ولا يسمع كلامكم في بيت أو مدينة، فاخرجوا من هناك، وانفضوا الغبار عن أقدامكم.","10:15":"الحق أقول لكم: إن حالة مدينتي سدوم وعمورة سوف تكون في يوم الدينونة أخف وطأة من حالة تلك المدينة.","10:16":"ها أنا أرسلكم مثل الخراف بين الذئاب، فكونوا متنبهين كالحيات ومسالمين كالحمام.","10:17":"احذروا من الناس! فإنهم سيسلمونكم إلى المحاكم، ويجلدونكم في مجامعهم؛","10:18":"وتساقون للمثول أمام الحكام والملوك من أجلي: فيكون ذلك شهادة لي لدى اليهود والأمم على السواء.","10:19":"فحين يسلمونكم، لا تهتموا كيف تتكلمون أو ماذا تقولون. فإنكم في تلك الساعة تلهمون ما تقولون.","10:20":"فلستم أنتم المتكلمين، بل روح أبيكم هو الذي يتكلم فيكم.","10:21":"وسوف يسلم الأخ أخاه إلى الموت، والأب ولده. ويتمرد الأولاد على والديهم، ويقتلونهم!","10:22":"وتكونون مكروهين لدى الجميع من أجل اسمي. ولكن من يثبت إلى النهاية، هو الذي يخلص.","10:23":"فإذا اضطهدوكم في مدينة ما، فاهربوا إلى غيرها. فإني الحق أقول لكم: لن تفرغوا من مدن إسرائيل إلى أن يأتي ابن الإنسان.","10:24":"ليس التلميذ أرفع من المعلم، ولا العبد أرفع من سيده.","10:25":"يكفي التلميذ أن يصير مثل معلمه، والعبد مثل سيده! إن كانوا قد لقبوا رب البيت ببعلزبول، فكم بالأحرى يلقبون أهل بيته؟","10:26":"فلا تخافوهم: لأنه ما من محجوب لن يكشف، وما من خفي لن يعلن!","10:27":"ما أقوله لكم في الظلام، قولوه في النور؛ وما تسمعونه همسا، نادوا به على السطوح.","10:28":"لا تخافوا الذين يقتلون الجسد، ولكنهم يعجزون عن قتل النفس، بل بالأحرى خافوا القادر أن يهلك النفس والجسد جميعا في جهنم.","10:29":"أما يباع عصفوران بفلس واحد؟ ومع ذلك لا يقع واحد منهما إلى الأرض خفية عن أبيكم.","10:30":"وأما أنتم فحتى شعر رؤوسكم كله معدود.","10:31":"فلا تخافوا إذن! أنتم أعز من عصافير كثيرة.","10:32":"كل من يعترف بي أمام الناس، أعترف أنا أيضا به أمام أبي الذي في السماوات.","10:33":"وكل من ينكرني أمام الناس، أنكره أنا أيضا أمام أبي الذي في السماوات.","10:34":"لا تظنوا أني جئت لأرسي سلاما على الأرض. ما جئت لأرسي سلاما، بل سيفا.","10:35":"فإني جئت لأجعل الإنسان على خلاف مع أبيه، والبنت مع أمها، والكنة مع حماتها.","10:36":"وهكذا يصير أعداء الإنسان أهل بيته.","10:37":"من أحب أباه أو أمه أكثر مني، فلا يستحقني. ومن أحب ابنه أو ابنته أكثر مني، فلا يستحقني.","10:38":"ومن لا يحمل صليبه ويتبعني، فهو لا يستحقني.","10:39":"من يتمسك بحياته، يخسرها؛ ومن يخسر حياته من أجلي، فإنه يربحها.","10:40":"من يقبلكم، يقبلني؛ ومن يقبلني، يقبل الذي أرسلني.","10:41":"من يرحب بنبي لكونه نبيا، فإنه ينال مكافأة نبي؛ ومن يرحب برجل بار لكونه بارا، فإنه ينال مكافأة بار.","10:42":"وأي من سقى واحدا من هؤلاء الصغار ولو كأس ماء بارد، فقط لأنه تلميذ لي، فالحق أقول لكم: إن مكافأته لن تضيع أبدا».","11:1":"بعدما انتهى يسوع من توصية تلاميذه الاثني عشر، انتقل من هناك، وذهب يعلم ويبشر في مدنهم.","11:2":"ولما سمع يوحنا، وهو في السجن، بأعمال المسيح، أرسل إليه بعض تلاميذه،","11:3":"يسأله: «أأنت هو الآتي، أم ننتظر غيرك؟»","11:4":"فأجابهم يسوع قائلا: «اذهبوا أخبروا يوحنا بما تسمعون وترون:","11:5":"العمي يبصرون، والعرج يمشون، والبرص يطهرون، والصم يسمعون، والموتى يقامون، والمساكين يبشرون.","11:6":"وطوبى لمن لا يشك في! »","11:7":"وما إن انصرف تلاميذ يوحنا، حتى أخذ يسوع يتحدث إلى الجموع عن يوحنا: «ماذا خرجتم إلى البرية لتروا؟ أقصبة تهزها الرياح؟","11:8":"بل ماذا خرجتم لتروا: أإنسانا يلبس ثيابا ناعمة؟ ها إن لابسي الثياب الناعمة هم في قصور الملوك!","11:9":"إذن، ماذا خرجتم لتروا؟ أنبيا؟ نعم، أقول لكم، وأعظم من نبي.","11:10":"فهذا هو الذي كتب عنه: ها إني مرسل قدامك رسولي الذي يمهد لك طريقك!","11:11":"الحق أقول لكم: إنه لم يظهر بين من ولدتهم النساء أعظم من يوحنا المعمدان. ولكن الأصغر في ملكوت السماوات أعظم منه!","11:12":"فمنذ أن بدأ يوحنا المعمدان خدمته وملكوت السماوات معرض للعنف؛ والعنفاء يختطفونه!","11:13":"فإن الشريعة والأنبياء تنبأوا جميعا حتى ظهور يوحنا.","11:14":"وإن شئتم أن تصدقوا، فإن يوحنا هذا، هو إيليا الذي كان رجوعه منتظرا.","11:15":"ومن له أذنان، فليسمع!","11:16":"ولكن، بمن أشبه هذا الجيل؟ إنهم يشبهون أولادا جالسين في الساحات العامة، ينادون أصحابهم قائلين:","11:17":"زمرنا لكم، فلم ترقصوا! وندبنا لكم، فلم تنتحبوا!","11:18":"فقد جاء يوحنا لا يأكل ولا يشرب، فقالوا: إن شيطانا يسكنه!","11:19":"ثم جاء ابن الإنسان يأكل ويشرب، فقالوا: هذا رجل شره وسكير، صديق لجباة الضرائب والخاطئين. ولكن تختبر الحكمة بأعمالها.»","11:20":"ثم بدأ يسوع يوبخ المدن التي جرت فيها أكثر معجزاته، لكون أهلها لم يتوبوا.","11:21":"فقال: «الويل لك ياكورزين! الويل لك يابيت صيدا! فلو أجري في صور وصيدا ما أجري فيكما من المعجزات، لتاب أهلهما منذ القديم متشحين بالمسوح في وسط الرماد.","11:22":"ولكني أقول لكم: إن حالة صور وصيدا في الدينونة، ستكون أخف وطأة من حالتكما!","11:23":"وأنت ياكفر ناحوم: هل ارتفعت حتى السماء؟ إنك إلى قعر الهاوية ستهبطين. فلو جرى في سدوم ما جرى فيك من المعجزات، لبقيت حتى اليوم.","11:24":"ولكني أقول لكم إن حالة بلاد سدوم في يوم الدينونة، ستكون أخف وطأة من حالتك! »","11:25":"وفي ذلك الوقت، تكلم يسوع فقال: «أحمدك أيها الآب، رب السماء والأرض، لأنك حجبت هذه الأمور عن الحكماء والفهماء، وكشفتها للأطفال!","11:26":"نعم أيها الآب، لأنه هكذا حسن في نظرك.","11:27":"كل شيء قد سلمه إلي أبي. ولا أحد يعرف الابن إلا الآب، ولا أحد يعرف الآب إلا الابن، ومن أراد الابن أن يعلنه له.","11:28":"تعالوا إلي ياجميع المتعبين والرازحين تحت الأحمال الثقيلة، وأنا أريحكم.","11:29":"احملوا نيري عليكم، وتتلمذوا على يدي، لأني وديع ومتواضع القلب، فتجدوا الراحة لنفوسكم.","11:30":"فإن نيري هين، وحملي خفيف!»","12:1":"في ذلك الوقت مر يسوع بين الحقول في يوم سبت. فجاع تلاميذه، فأخذوا يقطفون سنابل القمح ويأكلون.","12:2":"ولما رآهم الفريسيون قالوا له: «ها إن تلاميذك يفعلون ما لا يحل فعله في السبت!»","12:3":"فأجابهم: «أما قرأتم ما فعله داود ومرافقوه عندما جاعوا؟","12:4":"كيف دخل بيت الله وأكل خبز التقدمة الذي لم يكن أكله يحل له ولا لمرافقيه بل للكهنة فقط!","12:5":"أو لم تقرأوا في الشريعة أن الكهنة ينتهكون السبت (بالعمل) في الهيكل أيام السبت ولا يحسبون مذنبين؟","12:6":"ولكني أقول لكم: ها هنا أعظم من الهيكل!","12:7":"ولو فهمتم معنى القول: إني أطلب رحمة لا ذبيحة، لما حكمتم على من لا ذنب عليهم!","12:8":"فإن ابن الإنسان هو رب السبت! »","12:9":"ثم انتقل من هناك ودخل مجمعهم،","12:10":"وإذا هناك رجل يده يابسة. وإذ أراد الفريسيون أن يشتكوا عليه بتهمة ما، سألوه: «أيحل شفاء المرضى في يوم السبت؟»","12:11":"فأجابهم: «أي واحد منكم يكون عنده خروف واحد، فإذا وقع في حفرة يوم سبت، أفلا يمسكه وينتشله؟","12:12":"فكم هو الإنسان أفضل كثيرا من الخروف! إذن يحل فعل الخير يوم السبت».","12:13":"ثم قال للرجل: «مد يدك!» فمدها، فعادت سليمة كاليد الأخرى.","12:14":"ولكن الفريسيين خرجوا وتآمروا على يسوع ليقتلوه.","12:15":"فعلم بذلك وانسحب من هناك. وتبعته جموع كثيرة، فشفاهم جميعا،","12:16":"وحذرهم من أن يذيعوا أمره،","12:17":"ليتم ما قيل بلسان النبي إشعياء القائل:","12:18":"«ها هو فتاي الذي اخترته، حبيبي الذي سرت به نفسي! سأضع روحي عليه، فيعلن العدل للأمم.","12:19":"لا يخاصم ولا يصرخ، ولا يسمع أحد صوته في الشوارع.","12:20":"قصبة مرضوضة لا يكسر، وفتيلة مدخنة لا يطفيء، حتى يقود العدل إلى النصر،","12:21":"وعلى اسمه تعلق الأمم رجاءها! »","12:22":"ثم أحضر إليه رجل أعمى وأخرس يسكنه شيطان، فشفاه حتى أبصر وتكلم.","12:23":"فدهش الجموع كلهم، وقالوا: «لعل هذا هو ابن داود!»","12:24":"أما الفريسيون، فلما سمعوا بهذا قالوا: «إنه لا يطرد الشياطين إلا ببعلزبول رئيس الشياطين!»","12:25":"وعلم يسوع أفكارهم، فقال لهم: «كل مملكة تنقسم على ذاتها تخرب. وكل مدينة أو بيت ينقسم على ذاته، لا يصمد.","12:26":"فإن كان الشيطان يطرد الشيطان، يكون قد انقسم على ذاته، فكيف تصمد مملكته؟","12:27":"وإن كنت أنا أطرد الشيا طين ببعلزبول، فأبناؤكم بمن يطردونهم؟ لذلك هم يحكمون عليكم؟","12:28":"ولكن إن كنت بروح الله أطرد الشياطين، فقد أقبل عليكم ملكوت الله!","12:29":"وإلا، فكيف يقدر أحد أن يدخل بيت القوي وينهب أمتعته إذا لم يربط القوي أولا؛ وبعدئذ ينهب بيته؟","12:30":"من ليس معي، فهو ضدي؛ ومن لا يجمع معي، فهو يفرق.","12:31":"لذلك أقول لكم: إن كل خطيئة وتجديف يغفر للناس.","12:32":"وأما التجديف على الروح (القدس)، فلن يغفر. ومن قال كلمة ضد ابن الإنسان، يغفر له. وأما من قال كلمة ضد الروح القدس، فلن يغفر له، لا في هذا الزمان، ولا في الزمان الآتي.","12:33":"لتكن الشجرة جيدة، فتنتج ثمرا جيدا؛ ولتكن الشجرة رديئة، فتنتج ثمرا رديئا! فمن الثمر، تعرف الشجرة.","12:34":"ياأولاد الأفاعي، كيف تقدرون، وأنتم أشرار، أن تتكلموا كلاما صالحا؟ لأن الفم يتكلم بما يفيض به القلب.","12:35":"فالإنسان الصالح، من الكنز الصالح في قلبه، يصدر ما هو صالح. والإنسان الشرير، يصدر ما هو شرير.","12:36":"على أني أقول لكم: إن كل كلمة باطلة يتكلم بها الناس، سوف يؤدون عنها الحساب في يوم الدينونة.","12:37":"فإنك بكلامك تبرر، وبكلامك تدان ! »","12:38":"عندئذ أجابه بعض الكتبة والفريسيين، قائلين: «يامعلم، نرغب في أن نشاهد آية تجريها!»","12:39":"فأجابهم: «جيل شرير خائن يطلب آية؛ ولن يعطى آية إلا آية يونان النبي.","12:40":"فكما بقي يونان في جوف الحوت ثلاثة أيام وثلاث ليال، هكذا سيبقى ابن الإنسان في جوف الأرض ثلاثة أيام وثلاث ليال.","12:41":"سيقف أهل نينوى يوم الدينونة مع هذا الجيل ويدينونه؛ لأنهم تابوا لما أنذرهم يونان. وها هنا أعظم من يونان!","12:42":"وستقوم ملكة الجنوب يوم الدينونة مع هذا الجيل وتدينه، لأنها جاءت من أقصى الأرض لتسمع حكمة سليمان. وها هنا أعظم من سليمان!","12:43":"ولكن متى خرج الروح النجس من إنسان يسكنه، يهيم في الأماكن القاحلة طالبا الراحة، فلا يجد.","12:44":"فيقول: أرجع إلى مسكني الذي فارقته! ويرجع، فيجده فارغا مكنوسا مزينا.","12:45":"فيذهب، ويحضر معه سبعة أرواح أخرى أكثر منه شرا، فتدخل جميعا وتسكن ذلك الإنسان، فتكون آخرته أسوأ من حالته الأولى. هكذا تكون حال هذا الجيل الشرير! »","12:46":"وبينما كان يكلم الجموع، إذا أمه وإخوته قد وقفوا خارجا، يطلبون أن يكلموه.","12:47":"فقال له واحد من الحاضرين: «ها إن أمك وإخوتك واقفون خارجا يطلبون أن يكلموك!»","12:48":"فأجاب قائلا للذي أخبره: «من هي أمي؟ ومن هم إخوتي؟»","12:49":"ثم أشار بيده إلى تلاميذه، وقال: «هؤلاء هم أمي وإخوتي:","12:50":"لأن كل من يعمل بإرادة أبي الذي في السماوات هو أخي وأختي وأمي ! »","13:1":"في ذلك اليوم خرج من البيت وجلس على شاطيء البحيرة.","13:2":"فاجتمعت إليه جموع كثيرة، حتى إنه صعد إلى القارب وجلس، بينما وقف الجمع كله على الشاطيء.","13:3":"فكلمهم بأمثال في أمور كثيرة، قال: «ها إن الزارع قد خرج ليزر ع.","13:4":"وبينما هو يزرع، وقع بعض البذار على الممرات، فجاءت الطيور والتهمته.","13:5":"ووقع بعضه على أرض صخرية رقيقة التربة، فطلع سريعا لأن تربته لم تكن عميقة؛","13:6":"ولكن لما أشرقت الشمس، احترق ويبس لأنه كان بلا أصل.","13:7":"ووقع بعض البذار بين الأشواك، فطلع الشوك وخنقه.","13:8":"وبعض البذار وقع في الأرض الجيدة، فأثمر بعضه مئة ضعف وبعضه ستين، وبعضه ثلاثين.","13:9":"من له أذنان فليسمع! »","13:10":"فتقدم إليه التلاميذ وسألوه: «لماذا تكلمهم بأمثال؟»","13:11":"فأجاب: «لأنه قد أعطي لكم أن تعرفوا أسرار ملكوت السماوات؛ أما أولئك، فلم يعط لهم ذلك.","13:12":"فإن من عنده، يعطى المزيد فيفيض؛ وأما من ليس عنده، فحتى الذي عنده ينتزع منه.","13:13":"لهذا السبب أكلمهم بأمثال: فهم ينظرون دون أن يبصروا، ويسمعون دون أن يسمعوا أو يفهموا.","13:14":"ففيهم قد تمت نبوءة إشعياء حيث يقول: سمعا تسمعون ولا تفهمون، ونظرا تنظرون ولا تبصرون.","13:15":"لأن قلب هذا الشعب قد صار غليظا، وصارت آذانهم ثقيلة السمع، وأغمضوا عيونهم؛ لئلا يبصروا بعيونهم، ويسمعوا بآذانهم، ويفهموا بقلوبهم، ويرجعوا إلي، فأشفيهم!","13:16":"وأما أنتم، فطوبى لعيونكم لأنها تبصر، ولآذانكم لأنها تسمع.","13:17":"فالحق أقول لكم: كم تمنى أنبياء وأبرار كثيرون أن يروا ما تبصرون ولم يروا، وأن يسمعوا ما تسمعون ولم يسمعوا!","13:18":"فاسمعوا أنتم معنى مثل الزارع:","13:19":"كل من يسمع كلمة الملكوت ولا يفهمها، يأتي الشرير ويخطف ما قد زرع في قلبه: هذا هو المزروع على الممرات.","13:20":"أما المزروع على أرض صخرية، فهو الذي يسمع الكلمة ويقبلها بفرح في الحال،","13:21":"ولكنه لا أصل له في ذاته، وإنما يبقى إلى حين: فحالما يحدث ضيق أو اضطهاد من أجل الكلمة، يتعثر.","13:22":"أما المزروع بين الأشواك، فهو الذي يسمع الكلمة، ولكن هم الزمان الحاضر وخداع الغنى يخنقان الكلمة، فلا يعطي ثمرا.","13:23":"وأما المزروع في الأرض الجيدة فهو الذي يسمع الكلمة ويفهمها، وهو الذي يعطي ثمرا. فينتج الواحد مئة، والآخر ستين، وغيره ثلاثين! »","13:24":"وضرب لهم مثلا آخر، قال: «يشبه ملكوت السماوات بإنسان زرع زرعا جيدا في حقله.","13:25":"وبينما الناس نائمون، جاء عدوه، وبذر زوانا في وسط القمح، ومضى.","13:26":"فلما نما القمح بسنابله، ظهر الزوان معه.","13:27":"فذهب عبيد رب البيت، وقالوا له: ياسيد، أما زرعت حقلك زرعا جيدا؟ فمن أين جاءه الزوان؟","13:28":"أجابهم إنسان عدو فعل هذا! فسألوه: أتريد أن نذهب ونجمع الزوان؟","13:29":"أجابهم: لا، لئلا تقلعوا القمح وأنتم تجمعون الزوان.","13:30":"اتركوهما كليهما ينموان معا حتى الحصاد. وفي أوان الحصاد، أقول للحصادين: اجمعوا الزوان أولا واربطوه حزما ليحرق. أما القمح، فاجمعوه إلى مخزني.»","13:31":"وضرب لهم مثلا آخر، قال: «يشبه ملكوت السماوات ببزرة خردل أخذها إنسان وزرعها في حقله.","13:32":"فمع أنها أصغر البذور كلها، فحين تنمو تصبح أكبر البقول جميعا، ثم تصير شجرة، حتى إن طيور السماء تأتي وتبيت في أغصانها».","13:33":"وضرب لهم مثلا آخر، قال: «يشبه ملكوت السماوات بخميرة أخذتها امرأة وأخفتها في ثلاثة مقادير من الدقيق، حتى اختمر العجين كله».","13:34":"هذه الأمور كلها كلم بها يسوع الجموع بأمثال. وبغير مثل لم يكن يكلمهم،","13:35":"ليتم ما قيل بلسان النبي القائل: «سأفتح فمي بأمثال، وأكشف ما كان مخفيا منذ إنشاء العالم».","13:36":"ثم صرف يسوع الجموع ورجع إلى البيت. فتقدم إليه تلاميذه وقالوا: «فسر لنا مثل زوان الحقل».","13:37":"فأجابهم: «الزارع الزرع الجيد هو ابن الإنسان.","13:38":"والحقل هو العالم. والزرع الجيد هو بنو الملكوت. والزوان هو بنو الشرير.","13:39":"أما العدو الذي زرع الزوان فهو إبليس. والحصاد هو نهاية الزمان. والحصادون هم الملائكة.","13:40":"وكما يجمع الزوان ويحرق بالنار، هكذا يحدث في نهاية الزمان:","13:41":"يرسل ابن الإنسان ملائكته، فيخرجون من ملكوته جميع المفسدين ومرتكبي الإثم،","13:42":"ويطرحونهم في أتون النار، هناك يكون البكاء وصرير الأسنان.","13:43":"عندئذ يضيء الأبرار كالشمس في ملكوت أبيهم. من له أذنان، فليسمع!","13:44":"يشبه ملكوت السماوات بكنز مطمور في حقل، وجده رجل، فعاد وطمره. ومن فرحه، ذهب وباع كل ما كان يملك واشترى ذلك الحقل.","13:45":"ويشبه ملكوت السماوات أيضا بتاجر كان يبحث عن اللآليء الجميلة.","13:46":"فما إن وجد لؤلؤة ثمينة جدا، حتى ذهب وباع كل ما يملك، واشتراها.","13:47":"«ويشبه ملكوت السماوات أيضا بشبكة ألقيت في البحر، فجمعت من كل نوع.","13:48":"ولما امتلأت، جذبها الصيادون إلى الشاطيء وجلسوا، ثم جمعوا ما كان جيدا في سلال، وطرحوا الرديء خارجا.","13:49":"هكذا يحدث في نهاية الزمان: يأتي الملائكة فيخرجون الأشرار من بين الأبرار،","13:50":"ويطرحونهم في أتون النار، هناك يكون البكاء وصرير الأسنان.","13:51":"أفهمتم هذه الأمور كلها؟» أجابوه: «نعم!»","13:52":"فقال: «ولهذا السبب، فأي واحد من الكتبة يصير تلميذا لملكوت السماوات، يشبه بإنسان رب بيت يطلع من كنزه ما هو جديد وما هو عتيق! »","13:53":"وبعدما أنهى يسوع هذه الأمثال، انتقل من هناك.","13:54":"ولما عاد إلى بلدته، أخذ يعلم اليهود في مجامعهم، حتى دهشوا وتساءلوا: «من أين له هذه الحكمة وهذه المعجزات؟","13:55":"أليس هو ابن النجار؟ أليست أمه تدعى مريم وإخوته يعقوب ويوسف وسمعان ويهوذا؟","13:56":"أو ليست أخواته جميعا عندنا؟ فمن أين له هذه كلها؟»","13:57":"وكانوا يشكون فيه. أما هو فقال لهم: «لا يكون النبي بلا كرامة إلا في بلدته وبيته!»","13:58":"ولم يجر هناك إلا معجزات قليلة، بسبب عدم إيمانهم به.","14:1":"في ذلك الوقت سمع هيرودس حاكم الربع بأخبار يسوع.","14:2":"فقال لخدامه: «هذا هو يوحنا المعمدان، وقد قام من بين الأموات. ولذلك تجرى على يده المعجزات! »","14:3":"فإن هيرودس كان قد ألقى القبض على يوحنا وكبله بالقيود، وأودعه السجن من أجل هيروديا زوجة فيلبس أخيه،","14:4":"لأن يوحنا كان يقول له: «ليس حلالا لك أن تتزوج بها!»","14:5":"ولما كان هيرودس يريد أن يقتل يوحنا، خاف من الشعب، لأنهم كانوا يعتبرون يوحنا نبيا.","14:6":"وفي أثناء الاحتفال بذكرى ميلاد هيرودس، رقصت ابنة هيروديا في الوسط، فسرت هيرودس،","14:7":"فأقسم لها واعدا بأن يعطيها أي شيء تطلبه.","14:8":"فبعد استشارة أمها، قالت: «أعطني هنا على طبق رأس يوحنا المعمدان!»","14:9":"فحزن الملك؛ ولكنه أمر بأن تعطى ما تريد، من أجل ما أقسم به أمام المتكئين معه.","14:10":"وأرسل إلى السجن فقطع رأس يوحنا.","14:11":"وجيء بالرأس على طبق، فقدم إلى الصبية، فحملته إلى أمها.","14:12":"وجاء تلاميذ يوحنا، فرفعوا جثمانه، ودفنوه. ثم ذهبوا وأخبروا يسوع.","14:13":"فما إن سمع يسوع بذلك، حتى ركب قاربا ورحل على انفراد إلى مكان خال. فسمعت الجموع بذلك، وتبعوه من المدن سيرا على الأقدام.","14:14":"ولما نزل يسوع إلى الشاطيء، رأى جمعا كبيرا، فأخذته الشفقة عليهم وشفى مرضاهم.","14:15":"وعندما حل المساء، اقترب التلاميذ إليه وقالوا: «هذا المكان مقفر، وقد فات الوقت. فاصرف الجموع ليذهبوا إلى القرى ويشتروا طعاما لأنفسهم».","14:16":"ولكن يسوع قال لهم: «لا حاجة لهم أن يذهبوا. أعطوهم أنتم ليأكلوا!»","14:17":"فقالوا: «ليس عندنا هنا سوى خمسة أرغفة وسمكتين».","14:18":"فقال: «أحضروها إلي هنا!»","14:19":"وأمر الجموع أن يجلسوا على العشب. ثم أخذ الأرغفة الخمسة والسمكتين، ورفع نظره إلى السماء، وبارك وكسر الأرغفة، وأعطاها للتلاميذ، فوزعوها على الجموع.","14:20":"فأكل الجميع وشبعوا. ثم رفع التلاميذ اثنتي عشرة قفة ملأوها بما فضل من الكسر.","14:21":"وكان عدد الآكلين نحو خمسة آلاف رجل، ما عدا النساء والأولاد.","14:22":"وفي الحال ألزم يسوع التلاميذ أن يركبوا القارب ويسبقوه إلى الضفة المقابلة من البحيرة، حتى يصرف هو الجموع.","14:23":"وبعدما صرف الجموع، صعد إلى الجبل ليصلي على انفراد. وحل المساء وهو وحده هناك.","14:24":"وكان قارب التلاميذ قد بلغ وسط البحيرة والأمواج تضربه، لأن الريح كانت معاكسة له.","14:25":"وفي الربع الأخير من الليل جاء يسوع إلى التلاميذ ماشيا على ماء البحيرة.","14:26":"فلما رآه التلاميذ ماشيا على الماء، اضطربوا قائلين: «إنه شبح!» ومن خوفهم صرخوا.","14:27":"وفي الحال كلمهم يسوع قائلا: «تشجعوا! أنا هو. لا تخافوا!»","14:28":"فقال له بطرس: «إن كنت أنت هو، فمرني أن آتي إليك ماشيا على الماء!»","14:29":"فقال له يسوع: «تعال!» فنزل بطرس من القارب ومشى على الماء متجها نحو يسوع.","14:30":"ولكنه عندما شعر بشدة الريح، خاف وبدأ يغرق، فصرخ: «يارب نجني!»","14:31":"فمد يسوع يده في الحال وأمسكه وقال له: «ياقليل الإيمان، لماذا شككت؟»","14:32":"وما إن صعدا إلى القارب، حتى سكنت الريح.","14:33":"فتقدم الذين في القارب، وسجدوا له قائلين: «أنت حقا ابن الله! »","14:34":"ولما عبروا إلى الضفة المقابلة من البحيرة، نزلوا في بلدة جنسارت.","14:35":"فعرفه أهل تلك المنطقة، وأرسلوا الخبر إلى البلاد المجاورة، فأحضروا إليه جميع المرضى،","14:36":"وطلبوا منه أن يسمح لهم بلمس طرف ردائه فقط. وجميع الذين لمسوه نالوا شفاء تاما.","15:1":"وتقدم إلى يسوع بعض الكتبة والفريسيين من أورشليم، وسألوه:","15:2":"«لماذا يخالف تلاميذك تقاليد الشيوخ، فلا يغسلون أيديهم قبل أن يأكلوا؟»","15:3":"فأجابهم «ولماذا تخالفون أنتم وصية الله من أجل المحافظة على تقاليدكم؟","15:4":"فقد أوصى الله قائلا: أكرم أباك وأمك. ومن أهان أباه أو أمه، فليكن الموت عقابا له.","15:5":"ولكنكم أنتم تقولون: من قال لأبيه أو أمه: إن ما أعولك به قد قدمته قربانا للهيكل،","15:6":"فهو في حل من إكرام أبيه وأمه. وأنتم، بهذا، تلغون ما أوصى به الله ، محافظة على تقاليدكم.","15:7":"أيها المراؤون! أحسن إشعياء إذ تنبأ عنكم فقال:","15:8":"هذا الشعب يكرمني بشفتيه، أما قلبه فبعيد عني جدا!","15:9":"إنما باطلا يعبدونني وهم يعلمون تعاليم ليست إلا وصايا الناس.»","15:10":"ثم دعا الجمع إليه وقال لهم: «اسمعوا وافهموا:","15:11":"ليس ما يدخل الفم ينجس الإنسان، بل ما يخرج من الفم هو الذي ينجس الإنسان».","15:12":"فتقدم إليه تلاميذه وقالوا له: «أتعلم أن هذا القول قد أثار استياء الفريسيين؟»","15:13":"فأجابهم: «كل غرسة لم يغرسها أبي السماوي، لابد أن تقلع.","15:14":"دعوهم وشأنهم، فهم عميان يقودون عميانا. وإذا كان الأعمى يقود أعمى، يسقطان معا في حفرة».","15:15":"وقال له بطرس: «فسر لنا ذاك المثل!»","15:16":"فأجاب: «وهل أنتم أيضا بلا فهم؟","15:17":"ألا تدركون بعد أن الطعام الذي يدخل الفم ينزل إلى البطن، ثم يطرح إلى الخلاء؟","15:18":"أما ما يخرج من الفم، فإنه من القلب يصدر، وهو الذي ينجس الإنسان.","15:19":"فمن القلب تنبع الأفكار الشريرة، القتل، الزنى، الفسق، السرقة، شهادة الزور، التجديف.","15:20":"هذه هي الأمور التي تنجس الإنسان. وأما تناول الطعام بأيد غير مغسولة، فلا ينجس الإنسان! »","15:21":"ثم غادر يسوع تلك المنطقة، وذهب إلى نواحي صور وصيدا.","15:22":"فإذا امرأة كنعانية من تلك النواحي، قد تقدمت إليه صارخة: «ارحمني ياسيد، ياابن داود! ابنتي معذبة جدا، يسكنها شيطان».","15:23":"لكنه لم يجبها بكلمة. فجاء تلاميذه يلحون عليه قائلين: «اقض لها حاجتها. فهي تصرخ في إثرنا!»","15:24":"فأجاب: «ما أرسلت إلا إلى الخراف الضالة، إلى بيت إسرائيل!»","15:25":"ولكن المرأة اقتربت إليه، وسجدت له، وقالت: «أعني ياسيد!»","15:26":"فأجاب: «ليس من الصواب أن يؤخذ خبز البنين ويطرح لجراء الكلاب!»","15:27":"فقالت: «صحيح ياسيد؛ ولكن جراء الكلاب تأكل من الفتات الذي يسقط من موائد أصحابها!»","15:28":"فأجابها يسوع: «أيتها المرأة، عظيم إيمانك! فليكن لك ما تطلبين!» فشفيت ابنتها من تلك الساعة.","15:29":"ثم انتقل يسوع من تلك المنطقة، متجها إلى بحيرة الجليل. فصعد إلى الجبل وجلس هناك.","15:30":"فتوافدت إليه جموع كثيرة ومعهم عرج ومشلولون وعمي وخرس وغيرهم كثيرون، وطرحوهم عند قدميه، فشفاهم.","15:31":"فدهشت الجموع إذ رأوا الخرس ينطقون، والمشلولين أصحاء، والعرج يمشون، والعمي يبصرون؛ ومجدوا إله إسرائيل.","15:32":"ولكن يسوع دعا تلاميذه إليه وقال: «إني أشفق على الجمع لأنهم مازالوا معي منذ ثلاثة أيام وليس عندهم ما يأكلون. ولا أريد أن أصرفهم صائمين لئلا تخور قواهم في الطريق».","15:33":"فقال التلاميذ: «من أين لنا في هذه البرية خبز كثير حتى يكفي هذا الجمع الغفير؟»","15:34":"فسألهم: «كم رغيفا عندكم؟» أجابوا: «سبعة وبعض سمكات صغار!»","15:35":"فأمر الجمع أن يجلسوا على الأرض،","15:36":"ثم أخذ الأرغفة السبعة والسمكات، وشكر وكسر، وأعطى التلاميذ، فوزعوها على الجموع.","15:37":"فأكل الجميع حتى شبعوا. ثم رفع التلاميذ سبعة سلال ملأوها بما فضل من الكسر.","15:38":"وكان عدد الآكلين أربعة آلاف رجل، ماعدا النساء والأولاد.","15:39":"ثم صرف يسوع الجموع، وركب القارب، وجاء إلى نواحي مجدان.","16:1":"وجاء بعض الفريسيين والصدوقيين إلى يسوع ليجربوه، فطلبوا إليه أن يريهم آية من السماء.","16:2":"فأجابهم: «إذا كانت السماء حمراء صافية عند الغروب، تقولون: سيكون صحو!","16:3":"وإذا كانت السماء حمراء متجهمة في الصباح، تقولون: اليوم مطر! إنكم تستدلون على حالة الطقس من منظر السماء. أما علامات الأزمنة، فلا تستطيعون الاستدلال عليها!","16:4":"جيل شرير خائن يطلب آية، ولن يعطى آية إلا ما حدث للنبي يونان». ثم فارقهم ومضى.","16:5":"ولما وصل تلاميذه إلى الشاطيء الآخر، كانوا قد نسوا أن يتزودوا خبزا.","16:6":"وقال لهم يسوع: «انتبهوا! خذوا حذركم من خمير الفريسيين والصدوقيين!»","16:7":"فبدأوا يحاجون بعضهم بعضا، قائلين: «هذا لأننا لم نتزود خبزا!»","16:8":"وعلم يسوع بذلك، فقال لهم: «ياقليلي الإيمان، لماذا تحاجون بعضكم بعضا لأنكم لم تتزودوا خبزا؟","16:9":"ألا تفهمون بعد؟ أم نسيتم الأرغفة الخمسة التي أشبعت الخمسة الآلاف، وكم قفة رفعتم منها؟","16:10":"أو نسيتم الأرغفة السبعة التي أشبعت الأربعة الآلاف، وكم سلا رفعتم منها؟","16:11":"كيف لا تفهمون أني لم أكن أعني الخبز حين قلت لكم: خذوا حذركم من خمير الفريسيين والصدوقيين؟»","16:12":"عندئذ أدرك التلاميذ أنه لم يكن يحذرهم من خمير الخبز، بل من تعليم الفريسيين والصدوقيين.","16:13":"ولما وصل يسوع إلى نواحي قيصرية فيلبس، سأل تلاميذه: «من يقول الناس إني أنا، ابن الإنسان؟»","16:14":"فأجابوه: «يقول بعضهم إنك يوحنا المعمدان، وغيرهم إنك النبي إيليا، وآخرون إنك إرميا، أو واحد من الأنبياء».","16:15":"فسألهم: «وأنتم، من تقولون إني أنا؟»","16:16":"فأجاب سمعان بطرس قائلا: «أنت هو المسيح ابن الله الحي!»","16:17":"فقال له يسوع: «طوبى لك ياسمعان بن يونا. فما أعلن لك هذا لحم ودم، بل أبي الذي في السماوات.","16:18":"وأنا أيضا أقول لك: أنت صخر. وعلى هذه الصخرة أبني كنيستي وأبواب الجحيم لن تقوى عليها!","16:19":"وأعطيك مفاتيح ملكوت السماوات: فكل ما تربطه على الأرض، يكون قد ربط في السماء؛ وما تحله على الأرض، يكون قد حل في السماء!»","16:20":"ثم حذر تلاميذه من أن يقولوا لأحد إنه هو المسيح.","16:21":"من ذلك الوقت، بدأ يسوع يعلن لتلاميذه أنه لابد أن يمضي إلى أورشليم، ويتألم على أيدي الشيوخ ورؤساء الكهنة والكتبة، ويقتل، وفي اليوم الثالث يقام.","16:22":"فانتحى به بطرس جانبا، وأخذ يوبخه، قائلا: «حاشا لك يارب أن يحدث لك هذا!»","16:23":"فالتفت يسوع إلى بطرس وقال له: «اغرب من أمامي ياشيطان! أنت عقبة أمامي، لأنك تفكر لا بأمور الله، بل بأمور الناس! »","16:24":"ثم قال يسوع لتلاميذه: «إن أراد أحد أن يسير ورائي، فلينكر نفسه ويحمل صليبه ويتبعني.","16:25":"فأي من أراد أن يخلص نفسه، يخسرها؛ ولكن من يخسر نفسه لأجلي، فإنه يجدها.","16:26":"فماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه؟ أو ماذا يقدم الإنسان فداء عن نفسه؟","16:27":"فإن ابن الإنسان سوف يعود في مجد أبيه مع ملائكته، فيجازي كل واحد حسب أعماله.","16:28":"الحق أقول لكم: إن بعضا من الواقفين هنا لن يذوقوا الموت، قبل أن يروا ابن الإنسان آتيا في ملكوته».","17:1":"وبعد ستة أيام، أخذ يسوع بطرس ويعقوب ويوحنا أخاه، وصعد بهم على انفراد إلى جبل عال،","17:2":"وتجلى أمامهم، فشع وجهه كالشمس، وصارت ثيابه بيضاء كالنور.","17:3":"وإذا موسى وإيليا قد ظهرا لهم يتحدثان معه.","17:4":"فبدأ بطرس يقول ليسوع: «يارب، ما أحسن أن نبقى هنا! فإذا شئت، أنصب هنا ثلاث خيام: واحدة لك، وواحدة لموسى، وواحدة لإيليا».","17:5":"وبينما كان يتكلم، إذا سحابة منيرة قد خيمت عليهم، وصوت من السحابة يهتف: «هذا هو ابني الحبيب الذي سررت به كل سرور. له اسمعوا!»","17:6":"فلما سمع التلاميذ الصوت، وقعوا على وجوههم مرتعبين جدا.","17:7":"فاقترب منهم يسوع ولمسهم وقال: «انهضوا ولا ترتعبوا!»","17:8":"فرفعوا أنظارهم، فلم يروا إلا يسوع وحده.","17:9":"وفيما هم نازلون من الجبل، أوصاهم يسوع قائلا: «لا تخبروا أحدا بما رأيتم حتى يقوم ابن الإنسان من بين الأموات».","17:10":"فسأله تلاميذه: «لماذا إذن يقول الكتبة إن إيليا لابد أن يأتي قبلا؟»","17:11":"فأجابهم قائلا: «حقا، إن إيليا يأتي قبلا ويصلح كل شيء.","17:12":"على أني أقول لكم: قد جاء إيليا، ولم يعرفوه، بل فعلوا به كل ما شاءوا. كذلك ابن الإنسان أيضا على وشك أن يتألم على أيديهم».","17:13":"عندئذ فهم التلاميذ أنه كلمهم عن يوحنا المعمدان.","17:14":"ولما وصلوا إلى الجمع، تقدم رجل إلى يسوع، وجثا أمامه،","17:15":"وقال: «ياسيد، ارحم ابني لأنه مصاب بالصرع، وهو يتعذب عذابا شديدا. وكثيرا ما يسقط في النار أو في الماء.","17:16":"وقد أحضرته إلى تلاميذك، فلم يستطيعوا أن يشفوه».","17:17":"فأجاب يسوع قائلا: «أيها الجيل غير المؤمن والأعوج، إلى متى أبقى معكم؟ إلى متى أحتملكم؟ أحضروه إلي هنا!»","17:18":"وزجر يسوع الشيطان، فخرج من الصبي، وشفي من تلك الساعة.","17:19":"ثم تقدم التلاميذ إلى يسوع على انفراد وسألوه: «لماذا عجزنا نحن أن نطرد الشيطان؟»","17:20":"أجابهم: «لقلة إيمانكم. فالحق أقول لكم: لو كان لكم إيمان مثل بزرة خردل، لكنتم تقولون لهذا الجبل: انتقل من هنا إلى هناك، فينتقل، ولا يستحيل عليكم شيء.","17:21":"أما هذا النوع من الشياطين، فلا يطرد إلا بالصلاة والصوم».","17:22":"وفيما كانوا يتجمعون في الجليل، قال يسوع لتلاميذه: «ابن الإنسان على وشك أن يسلم إلى أيدي الناس،","17:23":"فيقتلونه. وفي اليوم الثالث يقام». فحزنوا حزنا شديدا.","17:24":"ولما وصلوا إلى كفرناحوم، جاء جباة ضريبة الدرهمين للهيكل إلى بطرس، وقالوا: «ألا يؤدي معلمكم الدرهمين؟» فأجاب: «بلى! »","17:25":"وما إن دخل بطرس البيت، حتى بادره يسوع بالسؤال: «مارأيك ياسمعان: ممن يستوفي ملوك الأرض الجزية أو الضريبة؟ أمن أبناء بلادهم، أم من الأجانب؟»","17:26":"أجاب بطرس: «من الأجانب». فقال له يسوع: «إذن الأبناء أحرار …","17:27":"ولكن لكي لا نضع لهم عثرة، اذهب إلى البحيرة، وألق صنارة الصيد؛ وأمسك السمكة التي تطلع أولا، ثم افتح فمها تجد فيه قطعة نقد بقيمة أربعة دراهم، فخذها وأد الضريبة عني وعنك! »","18:1":"في تلك الساعة، تقدم التلاميذ إلى يسوع يسألونه: «من هو الأعظم، إذن، في ملكوت السماوات؟»","18:2":"فدعا إليه ولدا صغيرا وأوقفه وسطهم،","18:3":"وقال: «الحق أقول لكم إن كنتم لا تتحولون وتصيرون مثل الأولاد الصغار، فلن تدخلوا ملكوت السماوات أبدا.","18:4":"فمن اتضع فصار مثل هذا الولد الصغير، فهو الأعظم في ملكوت السماوات.","18:5":"ومن قبل باسمي ولدا صغيرا مثل هذا، فقد قبلني.","18:6":"ومن كان عثرة لأحد هؤلاء الصغار المؤمنين بي، فأفضل له لو علق في عنقه حجر الرحى وأغرق في أعماق البحر.","18:7":"الويل للعالم من العثرات! فلابد أن تأتي العثرات؛ ولكن الويل لمن تأتي العثرات على يده!","18:8":"فإن كانت يدك أو رجلك فخا لك، فاقطعها وألقها عنك: أفضل لك أن تدخل الحياة ويدك أو رجلك مقطوعة، من أن تطرح في النار الأبدية.","18:9":"وإن كانت عينك فخا لك، فاقلعها وألقها عنك: أفضل لك أن تدخل الحياة وعينك مقلوعة، من أن تطرح في جهنم النار ولك عينان.","18:10":"إياكم أن تحتقروا أحدا من هؤلاء الصغار! فإني أقول لكم: إن ملائكتهم في السماء يشاهدون كل حين وجه أبي الذي في السماوات.","18:11":"فإن ابن الإنسان قد جاء لكي يخلص الهالكين.","18:12":"ما رأيكم في إنسان كان عنده مئة خروف، فضل واحد منها: أفلا يترك التسعة والتسعين في الجبال، ويذهب يبحث عن الضال؟","18:13":"الحق أقول لكم: إنه إذا وجده، فإنه يفرح به أكثر من فرحه بالتسعة والتسعين التي لم تضل!","18:14":"وهكذا، لا يشاء أبوكم الذي في السماوات أن يهلك واحد من هؤلاء الصغار.","18:15":"إن أخطأ إليك أخوك، فاذهب إليه وعاتبه بينك وبينه على انفراد. فإذا سمع لك، تكون قد ربحت أخاك.","18:16":"وإذا لم يسمع، فخذ معك أخا آخر أو اثنين، حتى يثبت كل أمر بشهادة شاهدين أو ثلاثة.","18:17":"فإذا لم يسمع لهما، فاعرض الأمر على الكنيسة. فإذا لم يسمع للكنيسة أيضا، فليكن عندك كالوثني وجابي الضرائب.","18:18":"فالحق أقول لكم: إن كل ما تربطونه على الأرض يكون قد ربط في السماء، وما تحلونه على الأرض يكون قد حل في السماء.","18:19":"وأيضا أقول لكم: إذا اتفق اثنان منكم على الأرض في أي أمر، مهما كان ما يطلبانه، فإن ذلك يكون لهما من قبل أبي الذي في السماوات.","18:20":"فإنه حيثما اجتمع اثنان أو ثلاثة باسمي، فأنا أكون في وسطهم».","18:21":"عندئذ تقدم إليه بطرس وسأله: «يارب، كم مرة يخطيء إلي أخي فأغفر له؟ هل إلى سبع مرات؟»","18:22":"فأجابه يسوع: «لا إلى سبع مرات، بل إلى سبعين سبع مرات!","18:23":"لهذا السبب، يشبه ملكوت السماوات بإنسان ملك أراد أن يحاسب عبيده.","18:24":"فلما شرع يحاسبهم، أحضر إليه واحد مديون بعشرة آلاف وزنة.","18:25":"وإذ لم يكن عنده ما يوفي به دينه، أمر سيده بأن يباع هو وزوجته وأولاده وكل ما يملك ليوفي الدين.","18:26":"لكن العبد خر أمامه ساجدا وقائلا: ياسيد، أمهلني فأوفي لك الدين كله.","18:27":"فأشفق سيد ذلك العبد عليه، فأطلق سراحه، وسامحه بالدين.","18:28":"«ولكن لما خرج ذلك العبد، قصد واحدا من زملائه العبيد كان مديونا له بمئة دينار. فقبض عليه وأخذ بخناقه قائلا: أوفني ما عليك!","18:29":"فخر زميله العبد أمامه وقال متوسلا: أمهلني فأوفيك!","18:30":"فلم يقبل بل مضى وألقاه في السجن حتى يوفي ما عليه.","18:31":"وإذ شاهد زملاؤه العبيد ما جرى، حزنوا جدا، فمضوا وأخبروا سيدهم بكل ما جرى.","18:32":"فاستدعاه سيده وقال له: أيها العبد الشرير، ذلك الدين كله سامحتك به لأنك توسلت إلي.","18:33":"أفما كان يجب أن ترحم زميلك العبد كما رحمتك أنا؟","18:34":"وإذ ثار غضب سيده عليه، دفعه إلى الجلادين ليعذبوه حتى يوفي كل ما عليه.","18:35":"هكذا يفعل بكم أبي السماوي إن لم يغفر كل منكم لأخيه من قلبه! »","19:1":"بعدما أنهى يسوع هذا الكلام، انتقل من الجليل ذاهبا إلى نواحي منطقة اليهودية ما وراء نهر الأردن.","19:2":"وتبعته جموع كثيرة، فشفى مرضاهم هناك.","19:3":"وتقدم إليه بعض الفريسيين يجربونه، فسألوه: «هل يحل للرجل أن يطلق زوجته لأي سبب؟»","19:4":"فأجابهم قائلا: «ألم تقرأوا أن الخالق جعل الإنسان منذ البدء ذكرا وأنثى،","19:5":"وقال: لذلك يترك الرجل أباه وأمه ويتحد بزوجته، فيصير الاثنان جسدا واحدا؟","19:6":"فليسا في ما بعد اثنين، بل جسد واحد. فلا يفرقن الإنسان ما قد قرنه الله !»","19:7":"فسألوه: «فلماذا أوصى موسى بأن تعطى الزوجة وثيقة طلاق فتطلق؟»","19:8":"أجاب: «بسبب قساوة قلوبكم، سمح لكم موسى بتطليق زوجاتكم. ولكن الأمر لم يكن هكذا منذ البدء.","19:9":"ولكني أقول لكم: إن الذي يطلق زوجته لغير علة الزنى، ويتزوج بغيرها، فإنه يرتكب الزنى. والذي يتزوج بمطلقة، يرتكب الزنى».","19:10":"فقال له تلاميذه: «إن كانت هذه حالة الزوج مع الزوجة، فعدم الزواج أفضل!»","19:11":"فأجابهم: «هذا الكلام لا يقبله الجميع، بل الذين أنعم عليهم بذلك.","19:12":"فإن بعض الخصيان يولدون من بطون أمهاتهم خصيانا؛ وبعضهم قد خصاهم الناس؛ وغيرهم قد خصوا أنفسهم من أجل ملكوت السماوات. فمن استطاع أن يقبل هذا، فليقبله! »","19:13":"ثم قدم إليه بعضهم أولادا صغارا ليضع يديه عليهم ويصلي، فزجرهم التلاميذ.","19:14":"ولكن يسوع قال: «دعوا الصغار يأتون إلي ولا تمنعوهم، لأن لمثل هؤلاء ملكوت السماوات !»","19:15":"ووضع يديه عليهم، ثم ارتحل من هناك.","19:16":"وإذا شاب يتقدم إليه ويسأل: «أيها المعلم الصالح، أي صلاح أعمل لأحصل على الحياة الأبدية؟»","19:17":"فأجابه: «لماذا تسألني عن الصالح؟ واحد هو الصالح. ولكن، إن أردت أن تدخل الحياة، فاعمل بالوصايا».","19:18":"فسأل: «أية وصايا؟» أجابه يسوع: «لا تقتل؛ لا تزن؛ لا تسرق؛ لا تشهد بالزور؛","19:19":"أكرم أباك وأمك؛ وأحب قريبك كنفسك...»","19:20":"قال له الشاب: «هذه كلها عملت بها منذ صغري، فماذا ينقصني بعد؟»","19:21":"فأجابه يسوع: «إن أردت أن تكون كاملا، فاذهب وبع كل ما تملك، ووزع على الفقراء، فيكون لك كنز في السماوات. وتعال اتبعني!»","19:22":"فلما سمع الشاب هذا الكلام، مضى حزينا لأنه كان صاحب ثروة كبيرة.","19:23":"فقال يسوع لتلاميذه: «الحق أقول لكم: إنه من الصعب على الغني أن يدخل ملكوت السماوات.","19:24":"وأيضا أقول: إنه لأسهل أن يدخل الجمل في ثقب إبرة من أن يدخل الغني ملكوت الله».","19:25":"فدهش التلاميذ جدا لما سمعوا ذلك، وسألوا: «إذن، من يقدر أن يخلص؟»","19:26":"فنظر إليهم وقال لهم: «هذا مستحيل عند الناس. أما عند الله، فكل شيء مستطاع! »","19:27":"عندئذ قال بطرس: «ها نحن قد تركنا كل شيء وتبعناك، فماذا يكون نصيبنا؟»","19:28":"فأجابهم يسوع: «الحق أقول لكم: إنه عندما يجلس ابن الإنسان على عرش مجده في زمن التجديد، تجلسون أنتم الذين تبعتموني على اثني عشر عرشا لتدينوا أسباط إسرائيل الاثني عشر.","19:29":"فأي من ترك بيوتا أو إخوة أو أخوات أو أبا أو أما أو أولادا أو أراضي من أجل اسمي، ينال مئة ضعف ويرث الحياة الأبدية.","19:30":"ولكن أولون كثيرون يصيرون آخرين، وآخرون كثيرون يصيرون أولين..","20:1":"فإن ملكوت السماوات يشبه بإنسان رب بيت خرج في الصباح الباكر ليستأجر عمالا لكرمه،","20:2":"واتفق مع العمال على أن يدفع لكل منهم دينارا في اليوم، وأرسلهم إلى كرمه.","20:3":"ثم خرج نحو الساعة التاسعة صباحا، فلقي في ساحة المدينة عمالا آخرين بلا عمل،","20:4":"فقال لهم: اذهبوا أنتم أيضا واعملوا في كرمي فأعطيكم ما يحق لكم! فذهبوا.","20:5":"ثم خرج إلى الساحة أيضا نحو الساعة الثانية عشرة ظهرا. ثم نحو الثالثة بعد الظهر، أرسل مزيدا من العمال إلى كرمه.","20:6":"ونحو الساعة الخامسة بعد الظهر، خرج أيضا فلقي عمالا آخرين بلا عمل، فسألهم: لماذا تقفون هنا طول النهار بلا عمل؟","20:7":"أجابوه: لأنه لم يستأجرنا أحد. فقال: اذهبوا أنتم أيضا إلى كرمي!","20:8":"وعندما حل المساء، قال رب الكرم لوكيله: ادع العمال وادفع الأجرة مبتدئا بالآخرين ومنتهيا إلى الأولين.","20:9":"فجاء الذين عملوا من الساعة الخامسة وأخذ كل منهم دينارا.","20:10":"فلما جاء الأولون، ظنوا أنهم سيأخذون أكثر. ولكن كل واحد منهم نال دينارا واحدا.","20:11":"وفيما هم يقبضون الدينار، تذمروا على رب البيت،","20:12":"قائلين: هؤلاء الآخرون عملوا ساعة واحدة فقط، وأنت قد ساويتهم بنا نحن الذين عملنا طول النهار تحت حر الشمس!","20:13":"فأجاب واحدا منهم: ياصاحبي، أنا ما ظلمتك؛ ألم تتفق معي على دينار؟","20:14":"خذ ما هو لك وامض في سبيلك: فأنا أريد أن أعطي هذا الأخير مثلك.","20:15":"أما يحق لي أن أتصرف بمالي كما أريد؟ أم أن عينك شريرة لأنني أنا صالح؟","20:16":"فهكذا يصير الآخرون أولين، والأولون آخرين. »","20:17":"وفيما كان يسوع صاعدا إلى أورشليم، انفرد بالتلاميذ الاثني عشر في الطريق، وقال لهم:","20:18":"«ها نحن صاعدون إلى أورشليم، حيث يسلم ابن الإنسان إلى رؤساء الكهنة، والكتبة، فيحكمون عليه بالموت،","20:19":"ويسلمونه إلى أيدي الأمم، فيسخرون منه ويجلدونه ويصلبونه. ولكنه في اليوم الثالث يقوم».","20:20":"فتقدمت إليه أم ابني زبدي وهما معها، وسجدت له تطلب منه معروفا.","20:21":"فقال لها: «ماذا تريدين؟» أجابت: «قل أن يجلس ابناي هذان: أحدهما عن يمينك، والآخر عن يسارك، في مملكتك!»","20:22":"فأجاب يسوع قائلا ليعقوب ويوحنا: «أنتما لا تدريان ما تطلبان! أتقدران أن تشربا الكأس التي سأشربها؟» أجاباه: «نعم، نقدر!»","20:23":"فقال لهما: «كأسي سوف تشربان. أما الجلوس عن يميني وعن يساري، فليس لي أن أمنحه إلا للذين أعده أبي لهم! »","20:24":"وعندما سمع التلاميذ العشرة بذلك، استاؤوا من الأخوين","20:25":"فاستدعاهم يسوع جميعا وقال: «تعلمون أن حكام الأمم يسودونهم، وعظماءهم يتسلطون عليهم.","20:26":"وأما أنتم، فلا يكن ذلك بينكم، وإنما أي من أراد أن يصير عظيما بينكم، فليكن لكم خادما،","20:27":"وأي من أراد أن يصير أولا فيكم، فليكن لكم عبدا،","20:28":"فهكذا ابن الإنسان: قد جاء لا ليخدم، بل ليخدم ويبذل نفسه فدية عن كثيرين. »","20:29":"وفيما كان يسوع وتلاميذه يغادرون أريحا، تبعه جمع كبير.","20:30":"وإذا أعميان كانا جالسين على جانب الطريق، ما إن سمعا أن يسوع يمر من هناك، حتى صرخا: «ارحمنا يارب، ياابن داود!»","20:31":"ولكن الجمع زجرهما ليسكتا، فأخذا يزيدان الصراخ: «ارحمنا يارب، ياابن داود!»","20:32":"فتوقف يسوع ودعاهما إليه، وسألهما: «ماذا تريدان أن أفعل لكما؟»","20:33":"أجاباه: «أن تفتح لنا أعيننا، يارب».","20:34":"فأخذته الشفقة عليهما، ولمس أعينهما، ففي الحال عادت أعينهما تبصر وانطلقا يتبعانه.","21:1":"ولما اقتربوا من أورشليم، ووصلوا إلى قرية بيت فاجي عند جبل الزيتون، أرسل يسوع اثنين من تلاميذه،","21:2":"قائلا لهما: «ادخلا القرية المقابلة لكما، تجدا في الحال أتانا مربوطة ومعها جحش، فحلا رباطهما وأحضراهما إلي.","21:3":"فإن اعترضكما أحد، قولا: الرب بحاجة إليهما. وفي الحال يرسلهما».","21:4":"وقد حدث هذا ليتم ما قيل بلسان النبي القائل:","21:5":"«بشروا ابنة صهيون: ها هو ملكك قادم إليك وديعا يركب على أتان وجحش ابن أتان !»","21:6":"فذهب التلميذان، وفعلا ما أمرهما به يسوع،","21:7":"فأحضرا الأتان والجحش، ووضعا عليهما ثيابهما، فركب.","21:8":"وأخذ الجمع الكبير جدا يفرشون الطريق بثيابهم، وأخذ آخرون يقطعون أغصان الشجر ويفرشون بها الطريق.","21:9":"وكانت الجموع التي تقدمت يسوع والتي مشت خلفه تهتف قائلة: «أوصنا لابن داود! مبارك الآتي باسم الرب! أوصنا في الأعالي!»","21:10":"ولما دخل يسوع أورشليم، ضجت المدينة كلها، وتساءل أهلها: «من هو هذا؟»","21:11":"فأجابت الجموع: «هذا هو يسوع النبي الذي من الناصرة بالجليل».","21:12":"ثم دخل يسوع الهيكل، وطرد من ساحته جميع الذين كانوا يبيعون ويشترون؛ وقلب موائد الصيارفة ومقاعد باعة الحمام.","21:13":"وقال لهم: «مكتوب: إن بيتي بيتا للصلاة يدعى. أما أنتم فجعلتموه مغارة لصوص!»","21:14":"وبينما هو في الهيكل، تقدم إليه عمي وعرج، فشفاهم.","21:15":"فتضايق رؤساء الكهنة، والكتبة، عندما رأوا العجائب التي أجراها، والأولاد في الهيكل يهتفون: «أوصنا لابن داود!»","21:16":"فسألوه: «أتسمع ما يقوله هؤلاء؟» فأجابهم يسوع: «نعم! ألم تقرأوا قط: من أفواه الأطفال والرضعاء أعددت تسبيحا؟»","21:17":"ثم فارقهم وانطلق خارجا من المدينة إلى قرية بيت عنيا، وبات فيها.","21:18":"وفي صباح اليوم التالي، وهو راجع إلى المدينة، جاع.","21:19":"وإذ رأى شجرة تين على جانب الطريق اتجه إليها، ولكنه لم يجد عليها إلا الورق، فقال لها: «لا يكن منك ثمر بعد إلى الأبد!» فيبست التينة في الحال.","21:20":"فلما رأى التلاميذ ذلك، دهشوا وقالوا: «ما أسرع ما يبست التينة!»","21:21":"فأجابهم: «الحق أقول لكم: إن كان لكم إيمان ولا تشكون، فإنكم تعملون لا مثل ما عملت بالتينة وحسب، بل إن كنتم تقولون لهذا الجبل: انقلع وانطرح في البحر، فإن ذلك يحدث.","21:22":"وكل ما تطلبونه في الصلاة بإيمان، تنالونه».","21:23":"ولما وصل إلى الهيكل وأخذ يعلم، تقدم إليه رؤساء الكهنة وشيوخ الشعب، وسألوه: «بأية سلطة تفعل ما تفعله؟ ومن منحك هذه السلطة؟»","21:24":"فأجابهم يسوع قائلا: «وأنا أيضا أسألكم أمرا واحدا، فإن أجبتموني، أقول لكم أنا كذلك بأية سلطة أفعل ما أفعله:","21:25":"من أين كانت معمودية يوحنا؟ من السماء أم من الناس؟» فتشاوروا فيما بينهم قائلين: «إن قلنا له إنها من السماء، يقول لنا: فلماذا لم تصدقوه؟","21:26":"وإن قلنا: من الناس، نخشى أن يثور علينا جمهور الشعب، لأنهم كلهم يعتبرون يوحنا نبيا».","21:27":"فأجابوه: «لا ندري!» فرد قائلا: «ولا أنا أقول لكم بأية سلطة أفعل ما أفعله…","21:28":"«.. ولكن، ما رأيكم؟ كان لإنسان ولدان. فقصد أولهما وقال له: ياولدي، اذهب اليوم واعمل في كرمي!","21:29":"فأجاب: لا أريد. ولكنه بعد ذلك ندم وذهب.","21:30":"ثم قصد الرجل ولده الثاني وقال له ما قاله للأول. فأجاب: لبيك ياسيدي! ولكنه لم يذهب.","21:31":"فأي الاثنين عمل بإرادة الأب؟» فقالوا: «الأول!» فقال لهم يسوع: «الحق أقول لكم: إن جباة الضرائب والزانيات سيسبقونكم في الدخول إلى ملكوت الله.","21:32":"فقد جاء يوحنا إليكم سالكا طريق الحق، فلم تصدقوه. أما جباة الضرائب والزانيات فصدقوه. ولما رأيتم أنتم هذا، لم تندموا بعد ذلك لتصدقوه!","21:33":"اسمعوا مثلا آخر: غرس إنسان رب بيت كرما، وأقام حوله سياجا، وحفر فيه معصرة، وبنى فيه برج حراسة. ثم سلم الكرم إلى مزارعين وسافر.","21:34":"ولما حان أوان القطاف، أرسل عبيده إلى المزارعين ليتسلم ثمر الكرم.","21:35":"فقبض المزارعون على العبيد، فضربوا أحدهم، وقتلوا غيره، ورجموا الآخر بالحجارة.","21:36":"ثم أرسل رب البيت ثانية عبيدا آخرين أكثر عددا من الأولين. ففعل المزارعون بهؤلاء ما فعلوه بأولئك.","21:37":"وأخيرا أرسل إليهم ابنه، قائلا: سيهابون ابني!","21:38":"فما إن رأى المزارعون الابن حتى قال بعضهم لبعض: هذا هو الوريث! تعالوا نقتله فنستولي على ميراثه.","21:39":"ثم قبضوا عليه، وطرحوه خارج الكرم، وقتلوه!","21:40":"فعندما يعود رب الكرم، ماذا يفعل بأولئك المزارعين؟»","21:41":"أجابوه: «أولئك الأشرار، يهلكهم شر هلاك. ثم يسلم الكرم إلى مزارعين آخرين يؤدون له الثمر في أوانه».","21:42":"فقال لهم يسوع: «ألم تقرأوا في الكتاب: الحجر الذي رفضه البناة، هو نفسه صار حجر الزاوية الأساسي. من الرب كان هذا، وهو عجيب في أنظارنا!","21:43":"لذلك أقول لكم: إن ملكوت الله سينزع من أيديكم ويسلم إلى شعب يؤدي ثمره.","21:44":"فأي من يقع على هذا الحجر يتكسر، ومن يقع الحجر عليه يسحقه سحقا! »","21:45":"ولما سمع رؤساء الكهنة والفريسيون المثلين اللذين ضربهما يسوع، أدركوا أنه كان يعنيهم هم.","21:46":"ومع أنهم كانوا يسعون إلى القبض عليه، فقد كانوا خائفين من الجموع لأنهم كانوا يعتبرونه نبيا.","22:1":"وعاد يسوع يتكلم بالأمثال، فقال:","22:2":"«يشبه ملكوت السماوات بإنسان ملك أقام وليمة في عرس ابنه،","22:3":"وأرسل عبيده يستدعي المدعوين إلى العرس، فلم يرغبوا في الحضور.","22:4":"فأرسل الملك ثانية عبيدا آخرين قائلا لهم: قولوا للمدعوين: ها أنا قد أعددت وليمتي؛ ثيراني وعجولي المسمنة قد ذبحت وكل شيء جاهز، فتعالوا إلى العرس!","22:5":"ولكن المدعوين تهاونوا، فذهب واحد إلى حقله، وآخر إلى متجره؛","22:6":"والباقون قبضوا على عبيد الملك وأهانوهم وقتلوهم.","22:7":"فغضب الملك وأرسل جيوشه، فأهلك أولئك القتلة وأحرق مدينتهم.","22:8":"ثم قال لعبيده: إن وليمة العرس جاهزة، ولكن المدعوين لم يكونوا مستحقين.","22:9":"فاذهبوا إلى مفارق الطرق، وكل من تجدونه ادعوه إلى وليمة العرس!","22:10":"فخرج العبيد إلى الطرق، وجمعوا كل من وجدوا، أشرارا وصالحين، حتى امتلأت قاعة العرس بالضيوف.","22:11":"ودخل الملك لينظر الضيوف، فرأى إنسانا لا يلبس ثوب العرس.","22:12":"فقال له: ياصاحبي، كيف دخلت إلى هنا وأنت لا تلبس ثوب العرس؟ فظل صامتا.","22:13":"فأمر الملك خدامه قائلا: قيدوا رجليه ويديه، واطرحوه في الظلام الخارجي، هنالك يكون البكاء وصرير الأسنان!","22:14":"لأن المدعوين كثيرون، ولكن المختارين قليلون! »","22:15":"فذهب الفريسيون وتآمروا كيف يوقعونه بكلمة يقولها.","22:16":"فأرسلوا إليه بعض تلاميذهم مع أعضاء حزب هيرودس، يقولون له: «يامعلم، نعلم أنك صادق وتعلم الناس طريق الله في الحق، ولا تبالي بأحد لأنك لا تراعي مقامات الناس،","22:17":"فقل لنا إذن ما رأيك؟ أيحل أن تدفع الجزية للقيصر أم لا؟»","22:18":"فأدرك يسوع مكرهم وقال: «أيها المراؤون، لماذا تجربونني؟","22:19":"أروني عملة الجزية!» فقدموا له دينارا.","22:20":"فسألهم: «لمن هذه الصورة وهذا النقش؟»","22:21":"أجابوه: «للقيصر!» فقال لهم: «إذن، أعطوا ما للقيصر للقيصر، وما لله لله»","22:22":"فتركوه ومضوا، مدهوشين مما سمعوا.","22:23":"في ذلك اليوم تقدم إليه بعض الصدوقيين الذين لا يؤمنون بالقيامة، وسألوه","22:24":"قائلين: «يامعلم، قال موسى: إن مات رجل دون أن يخلف أولادا، فعلى أخيه أن يتزوج بأرملته، ويقيم نسلا على اسم أخيه.","22:25":"فقد كان عندنا سبعة إخوة، تزوج أولهم ثم مات وليس له نسل، فترك زوجته لأخيه؛","22:26":"وكذلك الثاني ثم الثالث ... حتى السابع.","22:27":"ومن بعدهم جميعا، ماتت المرأة أيضا.","22:28":"ففي القيامة، لمن من السبعة تكون المرأة زوجة، لأنها كانت زوجة لكل منهم؟»","22:29":"فرد عليهم يسوع قائلا: «أنتم في ضلال لأنكم لا تفهمون الكتاب ولا قدرة الله.","22:30":"فالناس في القيامة لا يتزوجون ولا يزوجون، بل يكونون كملائكة الله في السماء.","22:31":"أما عن قيامة الأموات، أفما قرأتم ما قيل لكم على لسان الله:","22:32":"أنا إله إبراهيم وإله إسحاق وإله يعقوب؟ وليس الله بإله أموات، بل هو إله أحياء».","22:33":"فلما سمع الجموع، ذهلوا من تعليمه.","22:34":"ولكن لما سمع الفريسيون أن يسوع أفحم الصدوقيين، اجتمعوا معا،","22:35":"وسأله واحد منهم، وهو من علماء الشريعة، يحاول أن يستدرجه:","22:36":"«يامعلم، ما هي الوصية العظمى في الشريعة؟»","22:37":"فأجابه: «أحب الرب إلهك بكل قلبك وكل نفسك وكل فكرك!","22:38":"هذه هي الوصية العظمى الأولى.","22:39":"والثانية مثلها: أحب قريبك كنفسك!","22:40":"بهاتين الوصيتين تتعلق الشريعة وكتب الأنبياء! »","22:41":"وفيما كان الفريسيون مجتمعين، سألهم يسوع:","22:42":"«ما رأيكم في المسيح: ابن من هو؟» أجابوه: «ابن داود!»","22:43":"فسألهم: «إذن، كيف يدعوه داود بالروح ربا له إذ يقول:","22:44":"قال الرب لربي: اجلس عن يميني حتى أضع أعداءك موطئا لقدميك؟","22:45":"فإن كان داود يدعوه ربه، فكيف يكون ابنه؟»","22:46":"فلم يقدر واحد منهم أن يجيبه ولو بكلمة. ومن ذلك اليوم، لم يجرؤ أحد أن يستدرجه بأي سؤال.","23:1":"عندئذ خاطب يسوع الجموع وتلاميذه،","23:2":"وقال: «اعتلى الكتبة والفريسيون كرسي موسى:","23:3":"فافعلوا كل ما يقولونه لكم واعملوا به. ولكن لا تعملوا مثل ما يعملون: لأنهم يقولون ولا يفعلون،","23:4":"بل يحزمون أحمالا ثقيلة لا تطاق ويضعونها على أكتاف الناس، ولكنهم هم لا يريدون أن يحركوها بطرف الإصبع.","23:5":"وكل ما يعملونه، فإنما يعملونه لكي يلفتوا نظر الناس إليهم. فهم يعرضون عصائبهم ويطيلون أطراف أثوابهم؛","23:6":"ويحبون أماكن الصدارة في الولائم، وصدور المجالس في المجامع،","23:7":"وأن تلقى عليهم التحيات في الساحات، وأن يدعوهم الناس: يامعلم، يامعلم.","23:8":"أما أنتم، فلا تقبلوا أن يدعوكم أحد: يامعلم! لأن معلمكم واحد، وأنتم جميعا إخوة.","23:9":"ولا تدعوا أحدا على الأرض أبا لكم: لأن أباكم واحد، وهو الآب الذي في السماوات.","23:10":"ولا تقبلوا أن يدعوكم أحد رؤساء، لأن رئيسكم واحد، وهو المسيح.","23:11":"وليكن أكبركم خادما لكم.","23:12":"فإن كل من يرفع نفسه يوضع، ومن يضع نفسه يرفع.","23:13":"لكن الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم تغلقون ملكوت السماوات في وجوه الناس، فلا أنتم تدخلون، ولا تدعون الداخلين يدخلون!","23:14":"الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم تلتهمون بيوت الأرامل وتتذرعون بإطالة صلواتكم. لذلك ستنزل بكم دينونة أقسى!","23:15":"الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم تطوفون البحر والبر لتكسبوا متهودا واحدا؛ فإذا تهود جعلتموه أهلا لجهنم ضعف ما أنتم عليه!","23:16":"الويل لكم أيها القادة العميان! تقولون: من أقسم بالهيكل، فقسمه غير ملزم؛ أما من أقسم بذهب الهيكل، فقسمه ملزم!","23:17":"أيها الجهال والعميان! أي الاثنين أعظم: الذهب أم الهيكل الذي يجعل الذهب مقدسا؟","23:18":"وتقولون: من أقسم بالمذبح، فقسمه غير ملزم؛ أما من أقسم بالقربان الذي على المذبح، فقسمه ملزم!","23:19":"أيها العميان! أي الاثنين أعظم: القربان أم المذبح الذي يجعل القربان مقدسا؟","23:20":"فإن من أقسم بالمذبح، فقد أقسم به وبكل ما عليه؛","23:21":"ومن أقسم بالهيكل، فقد أقسم به وبالساكن فيه؛","23:22":"ومن أقسم بالسماء، فقد أقسم بعرش الله وبالجالس عليه!","23:23":"الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم تؤدون حتى عشور النعنع والشبث والكمون، وقد أهملتم أهم ما في الشريعة: العدل والرحمة والأمانة. كان يجب أن تفعلوا هذه ولا تغفلوا تلك!","23:24":"أيها القادة العميان! إنكم تصفون الماء من البعوضة، ولكنكم تبلعون الجمل!","23:25":"الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم تنظفون الكأس والصحفة من الخارج، ولكنهما من الداخل ممتلئتان بما كسبتم بالنهب والطمع!","23:26":"أيها الفريسي الأعمى، نظف أولا داخل الكأس ليصير خارجها أيضا نظيفا!","23:27":"الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم كالقبور المطلية بالكلس: تبدو جميلة من الخارج، ولكنها من الداخل ممتلئة بعظام الموتى وكل نجاسة!","23:28":"كذلك أنتم أيضا، تبدون للناس أبرارا، ولكنكم من الداخل ممتلئون بالرياء والفسق!","23:29":"«الويل لكم أيها الكتبة والفريسيون المراؤون! فإنكم تبنون قبور الأنبياء وتزينون مدافن الأبرار،","23:30":"وتقولون: لو عشنا في زمن آبائنا لما شاركناهم في سفك دم الأنبياء.","23:31":"فبهذا تشهدون على أنفسكم بأنكم أبناء قاتلي الأنبياء!","23:32":"فأكملوا ما بدأه آباؤكم ليطفح الكيل!","23:33":"أيها الحيات، أولاد الأفاعي! كيف تفلتون من عقاب جهنم؟","23:34":"لذلك: ها أنا أرسل إليكم أنبياء وحكماء ومعلمين، فبعضهم تقتلون وتصلبون، وبعضهم تجلدون في مجامعكم، وتطاردونهم من مدينة إلى أخرى.","23:35":"وبهذا يقع عليكم كل دم زكي سفك على الأرض: من دم هابيل البار إلى دم زكريا بن برخيا الذي قتلتموه بين الهيكل والمذبح.","23:36":"الحق أقول لكم: إن عقاب ذلك كله سينزل بهذا الجيل.","23:37":"ياأورشليم، ياأورشليم، ياقاتلة الأنبياء وراجمة المرسلين إليها! كم مرة أردت أن أجمع أولادك كما تجمع الدجاجة فراخها تحت جناحيها، فلم تريدوا!","23:38":"ها إن بيتكم يترك لكم خرابا!","23:39":"فإني أقول لكم إنكم لن تروني من الآن، حتى تقولوا: مبارك الآتي باسم الرب! »","24:1":"ثم خرج يسوع من الهيكل، ولما غادره تقدم إليه تلاميذه، ولفتوا نظره إلى مباني الهيكل.","24:2":"فقال لهم: «أما ترون هذه المباني كلها؟ الحق أقول لكم: لن يترك هنا حجر فوق حجر إلا ويهدم! »","24:3":"وبينما كان جالسا على جبل الزيتون، تقدم إليه التلاميذ على انفراد وقالوا له: «أخبرنا متى يحدث هذا. وما هي علامة رجوعك وانتهاء الزمان؟»","24:4":"فأجاب يسوع: «انتبهوا! لا يضللكم أحد!","24:5":"فإن كثيرين سيأتون باسمي قائلين إني أنا هو المسيح، فيضللون كثيرين.","24:6":"وسوف تسمعون بحروب وأخبار حروب. فإياكم أن ترتعبوا! فلابد أن يحدث هذا كله، ولكن ليست النهاية بعد.","24:7":"فسوف تنقلب أمة على أمة، ومملكة على مملكة، وتحدث مجاعات وزلازل في عدة أماكن.","24:8":"ولكن هذه كلها ليست إلا أول المخاض.","24:9":"عندئذ يسلمكم الناس إلى العذاب، ويقتلونكم، وتكونون مكروهين لدى جميع الأمم من أجل اسمي؛","24:10":"فيرتد كثيرون ويسلمون بعضهم بعضا ويبغضون بعضهم بعضا،","24:11":"ويظهر كثيرون من الأنبياء الدجالين ويضللون كثيرين.","24:12":"وإذ يعم الإثم، تبرد المحبة لدى الكثيرين.","24:13":"ولكن الذي يثبت حتى النهاية، فهو يخلص.","24:14":"فسوف ينادى ببشارة الملكوت هذه في العالم كله، شهادة لي لدى الأمم جميعا. وبعد ذلك تأتي النهاية.","24:15":"فعندما ترون رجاسة الخراب، التي قيل عنها بلسان دانيآل النبي، قائمة في المكان المقدس، ليفهم القاريء!","24:16":"عندئذ ليهرب الذين في منطقة اليهودية إلى الجبال؛","24:17":"ومن كان على السطح، فلا ينزل ليأخذ ما في بيته؛","24:18":"ومن كان في الحقل، فلا يرجع ليأخذ ثوبه!","24:19":"والويل للحبالى والمرضعات في تلك الأيام!","24:20":"فصلوا لكي لا يكون هربكم في شتاء أو في سبت،","24:21":"فسوف تحدث عندئذ ضيقة عظيمة لم يحدث مثلها منذ بدء العالم إلى الآن، ولن يحدث.","24:22":"ولولا أن تلك الأيام ستختصر، لما كان أحد من البشر ينجو. ولكن من أجل المختارين ستختصر تلك الأيام.","24:23":"فإن قال لكم أحد عندئذ: ها إن المسيح هنا، أو هناك، فلا تصدقوا!","24:24":"فسوف يبرز أكثر من مسيح دجال ونبي دجال، ويقدمون آيات عظيمة وأعاجيب، ليضللوا حتى المختارين، لو استطاعوا.","24:25":"ها أنا قد أخبرتكم بالأمر قبل حدوثه.","24:26":"فإذا قال لكم الناس: ها هو المسيح في البرية! فلا تخرجوا إليها؛ أو: ها هو في الغرف الداخلية! فلا تصدقوا.","24:27":"فكما أن البرق يومض من الشرق فيضيء في الغرب، هكذا يكون رجوع ابن الإنسان.","24:28":"فحيث توجد الجيفة، تتجمع النسور!","24:29":"وحالا بعد الضيقة في تلك الأيام، تظلم الشمس، ويحجب القمر ضوءه، وتتهاوى النجوم من السماء، وتتزعزع قوات السماوات.","24:30":"وعندئذ تظهر آية ابن الإنسان في السماء، فتنتحب قبائل الأرض كلها، ويرون ابن الإنسان آتيا على سحب السماء بقدرة ومجد عظيم.","24:31":"ويرسل ملائكته بصوت بوق عظيم ليجمعوا مختاريه من الجهات الأربع، من أقاصي السماوات إلى أقاصيها.","24:32":"«وتعلموا هذا المثل من شجرة التين: عندما تلين أغصانها، وتطلع ورقا، تعرفون أن الصيف قريب.","24:33":"هكذا أيضا حين ترون هذه الأمور جميعها تحدث، فاعلموا أنه قريب بل على الأبواب!","24:34":"الحق أقول لكم: لا يزول هذا الجيل أبدا، حتى تحدث هذه الأمور كلها.","24:35":"إن السماء والأرض تزولان؛ ولكن كلامي لا يزول أبدا.","24:36":"أما ذلك اليوم وتلك الساعة، فلا يعرفهما أحد، ولا ملائكة السماوات، إلا الآب وحده.","24:37":"وكما كانت الحال في زمن نوح، كذلك ستكون عند رجوع ابن الإنسان:","24:38":"فقد كان الناس في الأيام السابقة للطوفان يأكلون ويشربون ويتزوجون ويزوجون، حتى فاجأهم اليوم الذي دخل فيه نوح السفينة،","24:39":"ونزل الطوفان وهم لاهون فأخذ الجميع. هكذا ستكون الحال عند رجوع ابن الإنسان:","24:40":"عندئذ يكون رجلان في الحقل، فيؤخذ أحدهما ويترك الآخر،","24:41":"وامرأتان تطحنان على الرحى، فتؤخذ إحداهما، وتترك الأخرى.","24:42":"فاسهروا إذن، لأنكم لا تعرفون في أية ساعة يرجع ربكم.","24:43":"واعلموا أنه لو عرف رب البيت في أي ربع من الليل يدهمه اللص، لظل ساهرا ولم يدع بيته ينقب.","24:44":"فكونوا أنتم أيضا على استعداد، لأن ابن الإنسان سيرجع في ساعة لا تتوقعونها!","24:45":"فمن هو إذن ذلك العبد الأمين والحكيم الذي أقامه سيده على أهل بيته ليقدم لهم الطعام في أوانه؟","24:46":"طوبى لذلك العبد الذي يأتي سيده فيجده يقوم بعمله.","24:47":"الحق أقول لكم: إنه سيقيمه على ممتلكاته كلها.","24:48":"ولكن إذا قال ذلك العبد الشرير في قلبه: سيتأخر سيدي في رجوعه!","24:49":"وبدأ يضرب زملاءه العبيد ويأكل ويشرب مع السكيرين،","24:50":"فإن سيد ذلك العبد لابد أن يرجع في يوم لا يتوقعه، وساعة لا يعرفها،","24:51":"فيفصله ويجعل نصيبه مع المرائين، هناك يكون البكاء وصرير الأسنان!","25:1":"حينئذ يشبه ملكوت السماوات بعشر عذارى أخذن مصابيحهن وانطلقن لملاقاة العريس.","25:2":"وكانت خمس منهن حكيمات، وخمس جاهلات.","25:3":"فأخذت الجاهلات مصابيحهن دون زيت.","25:4":"وأما الحكيمات، فأخذن مع مصابيحهن زيتا وضعنه في أوعية.","25:5":"وإذ أبطأ العريس، نعسن جميعا ونمن.","25:6":"وفي منتصف الليل، دوى الهتاف: ها هو العريس آت؛ فانطلقن لملاقاته!","25:7":"فنهضت العذارى جميعا وجهزن مصابيحهن.","25:8":"وقالت الجاهلات للحكيمات: أعطيننا بعض الزيت من عندكن، فإن مصابيحنا تنطفىء!،","25:9":"فأجابت الحكيمات: ربما لا يكفي لنا ولكن. فاذهبن بالأحرى إلى بائعي الزيت واشترين لكن!","25:10":"وبينما الجاهلات ذاهبات للشراء، وصل العريس، فدخلت المستعدات معه إلى قاعة العرس، وأغلق الباب.","25:11":"وبعد حين، رجعت العذارى الأخريات، وقلن: ياسيد، ياسيد، افتح لنا!","25:12":"فأجاب العريس: الحق أقول لكن: إني لا أعرفكن!","25:13":"فاسهروا إذن، لأنكم لا تعرفون اليوم ولا الساعة!","25:14":"فذلك أشبه بإنسان مسافر، استدعى عبيده وسلمهم أمواله،","25:15":"فأعطى واحدا منهم خمس وزنات (من الفضة)، وأعطى آخر وزنتين، وأعطى الثالث وزنة واحدة، كل واحد على قدر طاقته، ثم سافر.","25:16":"وفي الحال مضى الذي أخذ الوزنات الخمس وتاجر بها، فربح خمس وزنات أخرى.","25:17":"وعمل مثله الذي أخذ الوزنتين، فربح وزنتين أخريين.","25:18":"ولكن الذي أخذ الوزنة الواحدة، مضى وحفر حفرة في الأرض وطمر مال سيده.","25:19":"وبعد مدة طويلة، رجع سيد أولئك العبيد واستدعاهم ليحاسبهم.","25:20":"فجاءه الذي أخذ الوزنات الخمس، وقدم الوزنات الخمس الأخرى، وقال: ياسيد، أنت سلمتني خمس وزنات، فهذه خمس وزنات غيرها ربحتها !","25:21":"فقال له سيده: حسنا فعلت أيها العبد الصالح والأمين! كنت أمينا على القليل، فسأقيمك على الكثير. ادخل إلى فرح سيدك!","25:22":"ثم جاءه أيضا الذي أخذ الوزنتين وقال: ياسيد أنت سلمتني وزنتين، فهاتان وزنتان غيرهما ربحتهما!","25:23":"فقال له سيده: حسنا فعلت أيها العبد الصالح والأمين! كنت أمينا على القليل، فسأقيمك على الكثير. ادخل إلى فرح سيدك!","25:24":"ثم جاءه أيضا الذي أخذ الوزنة الواحدة، وقال: ياسيد، عرفتك رجلا قاسيا، تحصد من حيث لم تزرع، وتجمع من حيث لم تبذر،","25:25":"فخفت، فذهبت وطمرت وزنتك في الأرض. فهذا هو مالك!","25:26":"فأجابه سيده: أيها العبد الشرير الكسول! عرفت أني أحصد من حيث لم أزرع، وأجمع من حيث لم أبذر،","25:27":"فكان يحسن بك أن تودع مالي عند الصيارفة لكي أسترده لدى عودتي مع فائدته!»","25:28":"ثم قال لعبيده: «خذوا منه الوزنة، وأعطوها لصاحب الوزنات العشر:","25:29":"فإن كل من عنده، يعطى المزيد فيفيض؛ ومن ليس عنده، فحتى الذي عنده ينتزع منه.","25:30":"أما هذا العبد الذي لا نفع منه، فاطرحوه في الظلمة الخارجية، هناك يكون البكاء وصرير الأسنان!","25:31":"وعندما يعود ابن الإنسان في مجده ومعه جميع ملائكته، فإنه يجلس على عرش مجده،","25:32":"وتجتمع أمامه الشعوب كلها، فيفصل بعضهم عن بعض كما يفصل الراعي الغنم عن المعاز،","25:33":"فيوقف الغنم عن يمينه، والمعاز عن يساره؛","25:34":"ثم يقول الملك للذين عن يمينه: تعالوا يامن باركهم أبي، رثوا الملكوت الذي أعد لكم منذ إنشاء العالم:","25:35":"لأني جعت فأطعمتموني، عطشت فسقيتموني، كنت غريبا فآويتموني،","25:36":"عريانا فكسوتموني، مريضا فزرتموني، سجينا فأتيتم إلي!","25:37":"فيرد الأبرار قائلين: يارب، متى رأيناك جائعا فأطعمناك، أو عطشانا فسقيناك؟","25:38":"ومتى رأيناك غريبا فآويناك، أو عريانا فكسوناك؟","25:39":"ومتى رأيناك مريضا أو سجينا فزرناك؟","25:40":"فيجيبهم الملك: الحق أقول لكم: بما أنكم فعلتم ذلك بأحد إخوتي هؤلاء الصغار، فبي فعلتم!","25:41":"ثم يقول للذين عن يساره: ابتعدوا عني ياملاعين إلى النار الأبدية المعدة لإبليس وأعوانه!","25:42":"لأني جعت فلم تطعموني، وعطشت فلم تسقوني،","25:43":"كنت غريبا فلم تأووني، عريانا فلم تكسوني، مريضا وسجينا فلم تزوروني!","25:44":"فيرد هؤلاء أيضا قائلين: يارب، متى رأيناك جائعا أو عطشانا أو غريبا أو عريانا أو مريضا أو سجينا، ولم نخدمك؟","25:45":"فيجيبهم: الحق أقول لكم: بما أنكم لم تفعلوا ذلك بأحد إخوتي هؤلاء الصغار، فبي لم تفعلوا!","25:46":"فيذهب هؤلاء إلى العقاب الأبدي، والأبرار إلى الحياة الأبدية! »","26:1":"ولما أنهى يسوع هذه الأقوال كلها، قال لتلاميذه:","26:2":"«أنتم تعرفون أنه بعد يومين يأتي الفصح. فسوف يسلم ابن الإنسان ليصلب».","26:3":"وعندئذ اجتمع رؤساء الكهنة وشيوخ الشعب في دار رئيس الكهنة المدعو قيافا،","26:4":"وتآمروا ليقبضوا على يسوع بمكر ويقتلوه.","26:5":"ولكنهم قالوا: «لا نفعل ذلك في العيد، لئلا يحدث اضطراب بين الشعب! »","26:6":"وإذ كان يسوع في بيت عنيا عند سمعان الأبرص،","26:7":"جاءت إليه امرأة تحمل قارورة عطر غالي الثمن، وسكبته على رأسه وهو متكىء.","26:8":"فاستاء التلاميذ لما رأوا ذلك، وقالوا: «لماذا هذا التبذير؟","26:9":"فقد كان يمكن أن يباع هذا العطر بمال كثير، ويوهب الثمن للفقراء؟»","26:10":"وإذ علم يسوع بذلك، قال لهم: «لماذا تضايقون هذه المرأة؟ إنها عملت بي عملا حسنا.","26:11":"فإن الفقراء عندكم في كل حين؛ أما أنا فلن أكون عندكم في كل حين.","26:12":"فإنها إذ سكبت العطر على جسمي، فقد فعلت ذلك إعدادا لدفني.","26:13":"والحق أقول لكم: إنه حيث ينادى بهذا الإنجيل في العالم أجمع، يحدث أيضا بما عملته هذه المرأة، إحياء لذكرها».","26:14":"عندئذ ذهب واحد من الاثني عشر، وهو المدعو يهوذا الإسخريوطي، إلى رؤساء الكهنة،","26:15":"وقال: «كم تعطونني لأسلمه إليكم؟» فوزنوا له ثلاثين قطعة من الفضة.","26:16":"ومن ذلك الوقت، أخذ يهوذا يتحين الفرصة لتسليمه.","26:17":"وفي اليوم الأول من أيام الفطير، تقدم التلاميذ إلى يسوع يسألون: «أين تريد أن نجهز لك الفصح لتأكل؟»","26:18":"أجابهم: «ادخلوا المدينة، واذهبوا إلى فلان وقولوا له: المعلم يقول إن ساعتي قد اقتربت، وعندك سأعمل الفصح مع تلاميذي».","26:19":"ففعل التلاميذ ما أمرهم به يسوع، وجهزوا الفصح هناك.","26:20":"وعند المساء اتكأ مع الاثني عشر.","26:21":"وبينما كانوا يأكلون، قال: «الحق أقول لكم: إن واحدا منكم سيسلمني».","26:22":"فاستولى عليهم الحزن الشديد، وأخذ كل منهم يسأله: «هل أنا يارب؟»","26:23":"فأجاب: «الذي يغمس يده معي في الصحفة هو الذي يسلمني.","26:24":"إن ابن الإنسان لابد أن يمضي كما قد كتب عنه، ولكن الويل لذلك الرجل الذي على يده يسلم ابن الإنسان. كان خيرا لذلك الرجل لو لم يولد!»","26:25":"فسأله يهوذا مسلمه: «هل أنا هو يامعلم؟» أجابه: «أنت قلت! »","26:26":"وبينما كانوا يأكلون، أخذ يسوع رغيفا، وبارك، وكسر وأعطى التلاميذ وقال: «خذوا، كلوا: هذا هو جسدي!»","26:27":"ثم أخذ الكأس، وشكر، وأعطاهم قائلا: «اشربوا منها كلكم.","26:28":"فإن هذا هو دمي الذي للعهد الجديد والذي يسفك من أجل كثيرين لمغفرة الخطايا.","26:29":"على أني أقول لكم: إني لا أشرب بعد اليوم من نتاج الكرمة هذا حتى يأتي اليوم الذي فيه أشربه معكم جديدا في ملكوت أبي».","26:30":"ثم رتلوا، وانطلقوا خارجا إلى جبل الزيتون.","26:31":"عندئذ قال لهم يسوع: «في هذه الليلة ستشكون في كلكم. لأنه قد كتب: سأضرب الراعي، فتتشتت خراف القطيع.","26:32":"ولكن بعد قيامتي أسبقكم إلى الجليل».","26:33":"فرد عليه بطرس قائلا: «ولو شك فيك الجميع، فأنا لن أشك!»","26:34":"أجابه يسوع: «الحق أقول لك: إنك في هذه الليلة، قبل أن يصيح الديك، تكون قد أنكرتني ثلاث مرات!»","26:35":"فقال بطرس: «ولو كان علي أن أموت معك، لا أنكرك أبدا!» وقال التلاميذ كلهم مثل هذا القول.","26:36":"ثم ذهب يسوع وتلاميذه إلى بستان يدعى جثسيماني، وقال لهم: «اجلسوا هنا ريثما أذهب إلى هناك وأصلي».","26:37":"وقد أخذ معه بطرس وابني زبدي وبدأ يشعر بالحزن والكآبة.","26:38":"فقال لهم: «نفسي حزينة جدا حتى الموت! ابقوا هنا واسهروا معي!»","26:39":"وابتعد عنهم قليلا وارتمى على وجهه يصلي، قائلا: «ياأبي، إن كان ممكنا، فلتعبر عني هذه الكأس: ولكن، لا كما أريد أنا، بل كما تريد أنت!»","26:40":"ورجع إلى التلاميذ فوجدهم نائمين، فقال لبطرس: «أهكذا لم تقدروا أن تسهروا معي ساعة واحدة؟","26:41":"اسهروا وصلوا لكي لا تدخلوا في تجربة. إن الروح نشيط؛ أما الجسد فضعيف».","26:42":"وذهب ثانية يصلي، فقال: «ياأبي، إن كان لا يمكن أن تعبر عني هذه الكأس إلا بأن أشربها، فلتكن مشيئتك!»","26:43":"ورجع إلى التلاميذ، فوجدهم نائمين أيضا لأن النعاس أثقل أعينهم.","26:44":"فتركهم، وعاد يصلي مرة ثالثة، وردد الكلام نفسه.","26:45":"ثم رجع إلى تلاميذه وقال: «ناموا الآن واستريحوا! حانت الساعة، وسوف يسلم ابن الإنسان إلى أيدي الخاطئين.","26:46":"قوموا لنذهب! ها قد اقترب الذي يسلمني. »","26:47":"وفيما هو يتكلم، إذا يهوذا، أحد الاثني عشر، قد وصل ومعه جمع عظيم يحملون السيوف والعصي، وقد أرسلهم رؤساء الكهنة وشيوخ الشعب.","26:48":"وكان مسلمه قد أعطاهم علامة قائلا: «الذي أقبله فهو هو؛ فاقبضوا عليه!»","26:49":"فتقدم في الحال إلى يسوع وقال: «سلام ياسيدي!» وقبله.","26:50":"فقال له يسوع: «ياصاحبي، لماذا أنت هنا؟» فتقدم الجمع وألقوا القبض على يسوع.","26:51":"وإذا واحد من الذين كانوا مع يسوع قد مد يده واستل سيفه، وضرب عبد رئيس الكهنة، فقطع أذنه.","26:52":"فقال يسوع له: «رد سيفك إلى غمده! فإن الذين يلجأون إلى السيف، بالسيف يهلكون!","26:53":"أم تظن أني لا أقدر الآن أن أطلب إلى أبي فيرسل لي أكثر من اثني عشر جيشا من الملائكة؟","26:54":"ولكن كيف يتم الكتاب حيث يقول إن ما يحدث الآن لابد أن يحدث؟ »","26:55":"ثم وجه يسوع كلامه إلى الجموع قائلا: «أكما على لص خرجتم بالسيوف والعصي لتقبضوا علي؟ كنت كل يوم بينكم أعلم في الهيكل، ولم تقبضوا علي!","26:56":"ولكن، قد حدث هذا كله لتتم كتابات الأنبياء!» عندئذ تركه التلاميذ كلهم وهربوا!","26:57":"وأما الذين قبضوا على يسوع، فساقوه إلى قيافا رئيس الكهنة، وقد اجتمع عنده الكتبة والشيوخ.","26:58":"وتبعه بطرس من بعيد إلى دار رئيس الكهنة، ثم تقدم إلى الداخل، وجلس بين الحراس ليرى النهاية.","26:59":"وانعقد المجلس من رؤساء الكهنة والشيوخ كلهم، وبحثوا عن شهادة زور على يسوع، ليحكموا عليه بالموت،","26:60":"ولكنهم لم يجدوا، مع أنه حضر شهود زور كثيرون. أخيرا تقدم اثنان","26:61":"وقالا: «هذا قال: إني أقدر أن أهدم هيكل الله وأبنيه في ثلاثة أيام».","26:62":"فوقف رئيس الكهنة وسأله: «أما تجيب بشيء على ما يشهد به هذان عليك؟»","26:63":"ولكن يسوع ظل صامتا. فعاد رئيس الكهنة يسأله: قال: «أستحلفك بالله الحي أن تقول لنا: هل أنت المسيح ابن الله؟»","26:64":"فأجابه يسوع: «أنت قلت! وأقول لكم أيضا إنكم منذ الآن سوف ترون ابن الإنسان جالسا عن يمين القدرة ثم آتيا على سحب السماء!»","26:65":"فشق رئيس الكهنة ثيابه وصرخ: «قد جدف! لا حاجة بنا بعد إلى شهود. وها أنتم قد سمعتم تجديفه.","26:66":"فما رأيكم؟» أجابوا: «يستحق عقوبة الموت!»","26:67":"فبصقوا في وجهه، وضربوه، ولطمه بعضهم","26:68":"قائلين: «تنبأ لنا، أيها المسيح، من ضربك! »","26:69":"في تلك الأثناء كان بطرس جالسا في الدار الخارجية، فتقدمت إليه خادمة وقالت: «وأنت كنت مع يسوع الجليلي».","26:70":"فأنكر بطرس أمام الجميع وقال: «لا أدري ما تقولين!»","26:71":"ثم خرج إلى مدخل الدار، فعرفته خادمة أخرى، فقالت للحاضرين هناك: «وهذا كان مع يسوع الناصري!»","26:72":"فأنكر بطرس مرة ثانية وأقسم: «إني لا أعرف ذلك الرجل!»","26:73":"وبعد قليل تقدم الواقفون هناك إلى بطرس وقالوا له: «بالحق إنك واحد منهم، فإن لهجتك تدل عليك!»","26:74":"فابتدأ بطرس يلعن ويحلف، قائلا: «إني لا أعرف ذلك الرجل!» وفي الحال صاح الديك،","26:75":"فتذكر بطرس كلمة يسوع إذ قال له: «قبل أن يصيح الديك تكون قد أنكرتني ثلاث مرات». فخرج إلى الخارج، وبكى بكاء مرا.","27:1":"ولما طلع الصباح، عقد رؤساء الكهنة وشيوخ الشعب اجتماعا آخر، وتآمروا على يسوع لينزلوا به عقوبة الموت.","27:2":"ثم قيدوه وساقوه فسلموه إلى بيلاطس الحاكم.","27:3":"فلما رأى يهوذا مسلمه أن الحكم عليه قد صدر، ندم ورد الثلاثين قطعة من الفضة إلى رؤساء الكهنة والشيوخ،","27:4":"وقال: «قد أخطأت إذ سلمتكم دما بريئا». فأجابوه: «ليس هذا شأننا نحن، بل هو شأنك أنت!»","27:5":"فألقى قطع الفضة في الهيكل وانصرف، ثم ذهب وشنق نفسه.","27:6":"فأخذ رؤساء الكهنة قطع الفضة وقالوا: «هذا المبلغ ثمن دم، فلا يحل لنا إلقاؤه في صندوق الهيكل!»","27:7":"وبعد التشاور اشتروا بالمبلغ حقل الفخاري ليكون مقبرة للغرباء،","27:8":"ولذلك مازال هذا الحقل يدعى حتى اليوم حقل الدم.","27:9":"عندئذ تم ما قيل بلسان النبي إرميا القائل: «وأخذوا الثلاثين قطعة من الفضة، ثمن الكريم الذي ثمنه بنو إسرائيل،","27:10":"ودفعوها لقاء حقل الفخاري، كما أمرني الرب».","27:11":"ووقف يسوع أمام الحاكم. فسأله الحاكم: «أأنت ملك اليهود؟» أجابه: «أنت قلت!»","27:12":"وكان رؤساء الكهنة والشيوخ يوجهون ضده الاتهامات، وهو صامت لا يرد.","27:13":"فقال له بيلاطس: «أما تسمع ما يشهدون به عليك؟»","27:14":"لكن يسوع لم يجب الحاكم ولو بكلمة، حتى تعجب الحاكم كثيرا.","27:15":"وكان من عادة الحاكم في كل عيد أن يطلق لجمهور الشعب أي سجين يريدونه.","27:16":"وكان عندهم وقتئذ سجين مشهور اسمه باراباس؛","27:17":"ففيما هم مجتمعون، سألهم بيلاطس: «من تريدون أن أطلق لكم: باراباس، أم يسوع الذي يدعى المسيح؟»","27:18":"إذ كان يعلم أنهم سلموه عن حسد.","27:19":"وفيما هو جالس على منصة القضاء، أرسلت إليه زوجته تقول: «إياك وذلك البار! فقد تضايقت اليوم كثيرا في حلم بسببه».","27:20":"ولكن رؤساء الكهنة والشيوخ حرضوا الجموع أن يطالبوا بإطلاق باراباس وقتل يسوع.","27:21":"فسألهم بيلاطس: «أي الاثنين تريدون أن أطلق لكم؟» أجابوا: «باراباس».","27:22":"فعاد يسأل: «فماذا أفعل بيسوع الذي يدعى المسيح؟» أجابوا جميعا: «ليصلب!»","27:23":"فسأل الحاكم: «وأي شر فعل؟» فازدادوا صراخا: «ليصلب!»","27:24":"فلما رأى بيلاطس أنه لا فائدة، وأن فتنة تكاد تنشب بالأحرى، أخذ ماء وغسل يديه أمام الجمع، وقال: «أنا بريء من دم هذا البار. فانظروا أنتم في الأمر!»","27:25":"فأجاب الشعب بأجمعه: «ليكن دمه علينا وعلى أولادنا!»","27:26":"فأطلق لهم باراباس؛ وأما يسوع فجلده، ثم سلمه إلى الصلب.","27:27":"فاقتاد جنود الحاكم يسوع إلى دار الحكومة، وجمعوا عليه جنود الكتيبة كلها،","27:28":"فجردوه من ثيابه، وألبسوه رداء قرمزيا،","27:29":"وجدلوا إكليلا من شوك وضعوه على رأسه، ووضعوا قصبة في يده اليمنى، وركعوا أمامه يسخرون منه وهم يقولون: «سلام ياملك اليهود!»","27:30":"وبصقوا عليه، وأخذوا القصبة منه، وضربوه بها على رأسه.","27:31":"وبعدما أوسعوه سخرية، نزعوا عنه الرداء، وألبسوه ثيابه، وساقوه إلى الصلب.","27:32":"وبينما كان الجنود يسوقونه إلى الصلب، وجدوا رجلا من القيروان اسمه سمعان، فسخروه أن يحمل عنه الصليب.","27:33":"ولما وصلوا إلى المكان المعروف بالجلجثة، وهو الذي يدعى مكان الجمجمة،","27:34":"أعطوا يسوع خمرا ممزوجة بمرارة ليشرب فلما ذاقها، رفض أن يشربها.","27:35":"فصلبوه، ثم تقاسموا ثيابه فيما بينهم مقترعين عليها.","27:36":"وجلسوا هناك يحرسونه؛","27:37":"وقد علقوا فوق رأسه لافتة تحمل تهمته، مكتوبا عليها: «هذا هو يسوع، ملك اليهود».","27:38":"وصلبوا معه لصين، واحدا عن اليمين، وواحدا عن اليسار.","27:39":"وكان المارة يشتمونه، وهم يهزون رؤوسهم","27:40":"ويقولون: «ياهادم الهيكل وبانيه في ثلاثة أيام، خلص نفسك! إن كنت ابن الله فانزل عن الصليب!»","27:41":"وسخر منه أيضا رؤساء الكهنة والكتبة والشيوخ، قائلين:","27:42":"«خلص غيره؛ أما نفسه فلا يقدر أن يخلص! أهو ملك إسرائيل؟ فلينزل الآن عن الصليب فنؤمن به!","27:43":"توكل على الله، فليخلصه الآن إن كان يريده! فهو قد قال: أنا ابن الله!»","27:44":"وكان اللصان المصلوبان معه يسخران منه بمثل هذا الكلام!","27:45":"ومن الساعة الثانية عشرة ظهرا إلى الساعة الثالثة بعد الظهر، حل الظلام على الأرض كلها.","27:46":"ونحو الساعة الثالثة صرخ يسوع بصوت عظيم: «إيلي، إيلي، لما شبقتني؟» أي: «إلهي، إلهي، لماذا تركتني؟»","27:47":"فلما سمعه بعض الواقفين هناك، قالوا: «إنه ينادي إيليا!»","27:48":"فركض واحد منهم، وأخذ إسفنجة غمسها في الخل، وثبتها على قصبة وقدم إليه ليشرب؛","27:49":"ولكن الباقين قالوا: «دعه وشأنه! لنر هل يأتي إيليا ليخلصه!»","27:50":"فصرخ يسوع مرة أخرى بصوت عظيم، وأسلم الروح.","27:51":"وإذا ستار الهيكل قد انشق شطرين، من الأعلى إلى الأسفل، وتزلزلت الأرض، وتشققت الصخور،","27:52":"وتفتحت القبور، وقامت أجساد كثيرة لقديسين كانوا قد رقدوا؛","27:53":"وإذ خرجوا من القبور، دخلوا المدينة المقدسة بعد قيامة يسوع، ورآهم كثيرون.","27:54":"وأما قائد المئة، وجنوده الذين كانوا يتولون حراسة يسوع، فقد استولى عليهم خوف شديد حينما رأوا الزلزال وكل ما جرى، فقالوا: «حقا كان هذا ابن الله!»","27:55":"ومن بعيد، كانت نساء كثيرات يراقبن ما يجري، وكن قد تبعن يسوع من الجليل ليخدمنه،","27:56":"وبينهن مريم المجدلية، ومريم أم يعقوب ويوسي، وأم ابني زبدي.","27:57":"ولما حل المساء، جاء رجل غني من بلدة الرامة، اسمه يوسف، وكان أيضا تلميذا ليسوع.","27:58":"فتقدم إلى بيلاطس يطلب جثمان يسوع. فأمر بيلاطس أن يعطى له","27:59":"فأخذ يوسف الجثمان، وكفنه بكتان نقي،","27:60":"ودفنه في قبره الجديد الذي كان قد حفره في الصخر؛ ودحرج حجرا كبيرا على باب القبر، ثم ذهب.","27:61":"وكانت هناك مريم المجدلية ومريم الأخرى جالستين تجاه القبر.","27:62":"وفي اليوم التالي، أي بعد الإعداد للسبت، تقدم رؤساء الكهنة والفريسيون معا إلى بيلاطس،","27:63":"وقالوا: «ياسيد. تذكرنا أن ذلك المضلل قال وهو حي: إني بعد ثلاثة أيام أقوم.","27:64":"فأصدر أمرا بحراسة القبر بإحكام إلى اليوم الثالث، لئلا يأتي تلاميذه ويسرقوه، ويقولوا للشعب: إنه قام من بين الأموات، فيكون التضليل الأخير أسوأ من الأول».","27:65":"فأجابهم بيلاطس: «عندكم حراس! فاذهبوا واحرسوه كما ترون».","27:66":"فذهبوا وأحكموا إغلاق القبر، وختموا الحجر، وأقاموا حراسا.","28:1":"وفي اليوم الأول من الأسبوع، بعد انتهاء السبت، ذهبت مريم المجدلية ومريم الأخرى تتفقدان القبر.","28:2":"فإذا زلزال عنيف قد حدث، لأن ملاكا من عند الرب نزل من السماء، وجاء فدحرج الحجر وجلس عليه.","28:3":"وكان منظر الملاك كالبرق، وثوبه أبيض كالثلج.","28:4":"ولما رآه الجنود الذين كانوا يحرسون القبر، أصابهم الذعر وصاروا كأنهم موتى.","28:5":"فطمأن الملاك المرأتين قائلا: «لا تخافا. فأنا أعلم أنكما تبحثان عن يسوع الذي صلب.","28:6":"إنه ليس هنا، فقد قام، كما قال. تعاليا وانظرا المكان الذي كان موضوعا فيه.","28:7":"واذهبا بسرعة وأخبرا تلاميذه أنه قد قام من بين الأموات، وها هو يسبقكم إلى الجليل، هناك ترونه. ها أنا قد أخبرتكما!»","28:8":"فانطلقت المرأتان من القبر مسرعتين، وقد استولى عليهما خوف شديد وفرح عظيم، وركضتا إلى التلاميذ تحملان البشرى.","28:9":"وفيما هما منطلقتان لتبشرا التلاميذ، إذا يسوع نفسه قد التقاهما وقال: «سلام!» فتقدمتا وأمسكتا بقدميه، وسجدتا له.","28:10":"فقال لهما يسوع: «لا تخافا! اذهبا قولا لإخوتي أن يوافوني إلى الجليل، وهناك يرونني! »","28:11":"وبينما كانت المرأتان ذاهبتين، إذا بعض الحراس قد ذهبوا إلى المدينة وأخبروا رؤساء الكهنة بكل ما جرى.","28:12":"فاجتمع رؤساء الكهنة والشيوخ وتشاوروا في الأمر. ثم رشوا الجنود بمال كثير،","28:13":"وقالوا لهم: «قولوا: إن تلاميذه جاءوا ليلا وسرقوه ونحن نائمون!","28:14":"فإذا بلغ الخبر الحاكم، فإننا ندافع عنكم، فتكونون في مأمن من أي سوء».","28:15":"فأخذ الجنود المال، وعملوا كما لقنوا. وقد انتشرت هذه الإشاعة بين اليهود إلى اليوم.","28:16":"وأما التلاميذ الأحد عشر، فذهبوا إلى منطقة الجليل، إلى الجبل الذي عينه لهم يسوع.","28:17":"فلما رأوه، سجدوا له. ولكن بعضهم شكوا،","28:18":"فتقدم يسوع وكلمهم قائلا: «دفع إلي كل سلطان في السماء وعلى الأرض.","28:19":"فاذهبوا إذن، وتلمذوا جميع الأمم، وعمدوهم باسم الآب والابن والروح القدس؛","28:20":"وعلموهم أن يعملوا بكل ما أوصيتكم به. وها أنا معكم كل الأيام إلى انتهاء الزمان! »."},"Mar":{"1:1":"هذه بداية إنجيل يسوع المسيح ابن الله:","1:2":"كما كتب في كتاب إشعياء:«ها أنا أرسل قدامك رسولي الذي يعد لك الطريق؛","1:3":"صوت مناد في البرية: أعدوا طريق الرب، واجعلوا سبله مستقيمة!»","1:4":"فقد ظهر يوحنا المعمدان في البرية ينادي بمعمودية التوبة لمغفرة الخطايا.","1:5":"وخرج إليه أهل منطقة اليهودية وأهل أورشليم جميعا، فكانوا يتعمدون على يده في نهر الأردن معترفين بخطاياهم.","1:6":"وكان يوحنا يلبس ثوبا من وبر الجمال، ويلف وسطه بحزام من جلد، ويقتات الجراد والعسل البري.","1:7":"وكان يعظ قائلا: «سيأتي بعدي من هو أقدر مني، من لا أستحق أن أنحني لأحل رباط حذائه.","1:8":"أنا عمدتكم بالماء؛ أما هو فسوف يعمدكم بالروح القدس».","1:9":"في تلك الأيام جاء يسوع من الناصرة بمنطقة الجليل، وتعمد في نهر الأردن على يد يوحنا.","1:10":"وحالما صعد من الماء، رأى السماوات قد انفتحت، والروح القدس هابطا عليه كأنه حمامة،","1:11":"وإذا صوت من السماوات يقول: «أنت ابني الحبيب، بك سررت كل سرور! »","1:12":"وفي الحال اقتاد الروح يسوع إلى البرية،","1:13":"فقضى فيها أربعين يوما والشيطان يجربه. وكان بين الوحوش وملائكة تخدمه.","1:14":"وبعدما ألقي القبض على يوحنا، انطلق يسوع إلى منطقة الجليل، يبشر بإنجيل الله قائلا:","1:15":"«قد اكتمل الزمان واقترب ملكوت الله. فتوبوا وآمنوا بالإنجيل! »","1:16":"وفيما كان يسوع يمشي على شاطيء بحيرة الجليل، رأى سمعان وأخاه أندراوس يلقيان الشبكة في البحيرة، فقد كانا صيادين.","1:17":"فقال لهما يسوع: «هيا اتبعاني، فأجعلكما صيادين للناس!»","1:18":"فتركا شباكهما وتبعاه.","1:19":"ثم سار من هناك قليلا، فرأى يعقوب بن زبدي ويوحنا أخاه في القارب يصلحان الشباك،","1:20":"فدعاهما في الحال ليتبعاه، فتركا أباهما زبدي في القارب مع الأجراء، وتبعاه.","1:21":"ثم ذهبوا إلى كفرناحوم. فدخل حالا، في يوم السبت، إلى المجمع وأخذ يعلم.","1:22":"فذهل الحاضرون من تعليمه، لأنه كان يعلمهم كصاحب سلطان وليس كالكتبة.","1:23":"وكان في مجمعهم رجل يسكنه روح نجس، فصر خ","1:24":"وقال: «ما شأنك بنا يايسوع الناصري؟ أجئت لتهلكنا؟ أنا أعرف من أنت. أنت قدوس الله!»","1:25":"فزجره يسوع قائلا: «اخرس واخرج منه!»","1:26":"فطرح الروح النجس الرجل، وصرخ صرخة عالية، وخرج منه.","1:27":"فدهش الجميع حتى أخذوا يتساءلون فيما بينهم: «ما هذا؟ إنه تعليم جديد، يلقى بسلطان، فحتى الأرواح النجسة يأمرها فتطيعه!»","1:28":"وفي الحال انتشر خبر يسوع في كل مكان من المنطقة المجاورة للجليل.","1:29":"وحالما غادروا المجمع، دخلوا بيت سمعان وأندراوس، ومعهم يعقوب ويوحنا.","1:30":"وكانت حماة سمعان طريحة الفراش، تعاني من الحمى. ففي الحال كلموا يسوع بشأنها.","1:31":"فاقترب إليها، وأمسك بيدها وأنهضها. فذهبت عنها الحمى حالا، وقامت تخدمهم.","1:32":"وعند حلول المساء، لما غربت الشمس، أحضر الناس إليه جميع من كانوا مرضى ومسكونين بالشياطين،","1:33":"حتى احتشد أهل المدينة كلهم عند الباب.","1:34":"فشفى كثيرين كانوا يعانون من أمراض مختلفة، وطرد شياطين كثيرة، ولكنه لم يسمح للشياطين بأن يتكلموا، لأنهم عرفوا من هو.","1:35":"وفي اليوم التالي، نهض باكرا قبل الفجر، وخرج إلى مكان مقفر وأخذ يصلي هناك.","1:36":"فذهب سمعان ومن معه يبحثون عنه. فلما وجدوه قالوا له:","1:37":"«إن الجميع يطلبونك!»","1:38":"فقال لهم: «لنذهب إلى مكان آخر في القرى المجاورة لأبشر هناك أيضا. فلأجل هذا جئت","1:39":"وذهب يبشر في مجامع اليهود في منطقة الجليل كلها، ويطرد الشياطين.","1:40":"وجاءه رجل مصاب بالبرص يتوسل إليه. فارتمى على ركبتيه أمامه وقال: «إن أردت، فأنت تقدر أن تطهرني!»","1:41":"فتحنن يسوع ومد يده ولمسه قائلا: «إني أريد، فاطهر!»","1:42":"فحالما تكلم زال البرص عنه وطهر.","1:43":"وفي الحال صرفه يسوع بعدما أنذره بشدة","1:44":"قائلا: «انتبه! لا تخبر أحدا بشيء، بل اذهب واعرض نفسك على الكاهن، وقدم لقاء تطهيرك ما أمر به موسى، فيكون ذلك شهادة لهم!»","1:45":"أما هو، فانطلق ينادي كثيرا ويذيع الخبر، حتى لم يعد يسوع يقدر أن يدخل أية بلدة علنا، بل كان يقيم في أماكن مقفرة، والناس يتوافدون إليه من كل مكان.","2:1":"وبعد بضعة أيام، رجع يسوع إلى بلدة كفرناحوم. وانتشر الخبر أنه في البيت،","2:2":"فاجتمع عدد كبير من الناس، حتى لم يبق مكان لأحد، ولا أمام الباب. فأخذ يلقي عليهم كلمة الله.","2:3":"وجاءه بعضهم بمشلول يحمله أربعة رجال.","2:4":"ولكنهم لم يقدروا أن يقتربوا إليه بسبب الزحام. فنقبوا السقف فوق المكان الذي كان يسوع فيه حتى كشفوه، ثم دلوا الفراش الذي كان المشلول راقدا عليه.","2:5":"فلما رأى يسوع إيمانهم، قال للمشلول: «يابني، قد غفرت لك خطاياك!»","2:6":"وكان بين الجالسين بعض الكتبة، فأخذوا يفكرون في قلوبهم:","2:7":"«لماذا يتكلم هذا الرجل هكذا؟ إنه يجدف! من يقدر أن يغفر الخطايا إلا الله وحده؟»","2:8":"وفي الحال أدرك يسوع بروحه ما يفكرون فيه في قلوبهم، فسألهم: «لماذا تفكرون بهذا الأمر في قلوبكم؟","2:9":"أي الأمرين أسهل أن يقال للمشلول: قد غفرت لك خطاياك، أو أن يقال له: قم احمل فراشك وامش؟","2:10":"ولكني قلت ذلك لتعلموا أن لابن الإنسان على الأرض سلطة غفران الخطايا». ثم قال للمشلول:","2:11":"«لك أقول: قم احمل فراشك، واذهب إلى بيتك!»","2:12":"فقام في الحال، وحمل فراشه، ومشى أمام الجميع. فذهلوا جميعا وعظموا الله قائلين: «ما رأينا مثل هذا قط!»","2:13":"وخرج يسوع ثانية إلى شاطيء البحيرة، فلحق به الجمع كله. فأخذ يعلمهم.","2:14":"وفيما هو سائر، رأى لاوي بن حلفى جالسا في مكتب الجباية، فقال له: «اتبعني!» فقام وتبعه.","2:15":"وبينما كان يسوع متكئا في بيت لاوي، أخذ كثيرون من الجباة والخاطئين يتكئون معه ومع تلاميذه، لأن كثيرين منهم كانوا هناك فلحقوا به.","2:16":"فلما رأى الكتبة والفريسيون يسوع يأكل مع الجباة والخاطئين، قالوا لتلاميذه: «لماذا يأكل مع الجباة والخاطئين؟»","2:17":"فسمع يسوع، وأجاب: «ليس الأصحاء هم المحتاجون إلى الطبيب، بل المرضى. ما جئت لأدعو أبرارا بل خاطئين! »","2:18":"وكان تلاميذ يوحنا والفريسيون صائمين، فجاء بعضهم إلى يسوع يسألونه: «لماذا يصوم تلاميذ يوحنا وتلاميذ الفريسيين، وأما تلاميذك فلا يصومون؟»","2:19":"فأجابهم: «هل يقدر أهل العرس أن يصوموا والعريس بينهم؟ مادام العريس بينهم لا يقدرون أن يصوموا.","2:20":"ولكن ستأتي أيام يكون العريس فيها قد رفع من بينهم. فيومذاك يصومون.","2:21":"لا أحد يرقع ثوبا عتيقا برقعة من قماش جديد وإلا، فإن الرقعة الجديدة تنكمش فتأكل من الثوب العتيق، ويصير الخرق أسوأ!","2:22":"ولا أحد يضع خمرا جديدة في قرب عتيقة، حتى لا تفجر الخمر الجديدة القرب، فتراق الخمر وتتلف القرب. إنما الخمر الجديدة توضع في قرب جديدة».","2:23":"ومر يسوع ذات سبت بين الحقول، فأخذ التلاميذ يشقون طريقهم وهم يقطفون السنابل.","2:24":"فقال الفريسيون ليسوع: «انظر! لماذا يفعل تلاميذك ما لا يحل فعله يوم السبت؟»","2:25":"فأجابهم: «أما قرأتم ما فعله داود ومرافقوه عندما احتاجوا وجاعوا؟","2:26":"كيف دخل بيت الله، في زمان أبيأثار رئيس الكهنة، وأكل خبز التقدمة الذي لا يحل الأكل منه إلا للكهنة وحدهم، بل أعطى مرافقيه أيضا فأكلوا؟»","2:27":"ثم قال لهم: «إنما جعل السبت لفائدة الإنسان، ولم يجعل الإنسان عبدا للسبت.","2:28":"فابن الإنسان هو رب السبت أيضا! »","3:1":"ودخل يسوع المجمع مرة أخرى. وكان هنالك رجل يده يابسة.","3:2":"فأخذوا يراقبونه ليروا هل يشفي ذلك الرجل في السبت، فيتمكنوا من أن يتهموه.","3:3":"فقال للرجل الذي يده يابسة: «قم وقف في الوسط!»","3:4":"ثم سألهم: «هل يحل في السبت فعل الخير أم فعل الشر؟ تخليص نفس أو قتلها؟» فظلوا صامتين.","3:5":"فأدار يسوع نظره فيهم غاضبا وقد تضايق من صلابة قلوبهم، وقال للرجل: «مد يدك!» فمدها، فإذا هي قد عادت صحيحة.","3:6":"وفي الحال خرج الفريسيون من المجمع، ومعهم أعضاء حزب هيرودس، وتآمروا عليه ليقتلوه.","3:7":"فانسحب يسوع وتلاميذه نحو البحيرة. وتبعه جمع كبير من مناطق الجبل واليهودية","3:8":"وأورشليم وأدومية وما وراء الأردن، وجمع كبير من نواحي صور وصيدا، جاءوا إليه إذ كانوا قد سمعوا بما فعل.","3:9":"فأمر يسوع تلاميذه أن يعدوا له قاربا صغيرا يلازمه، لئلا يزحمه الجمع،","3:10":"لأنه كان قد شفى كثيرين، فصار كل من به مرض يسارع إليه ليلمسه.","3:11":"وكانت الأرواح النجسة حين تراه تخر ساجدة له، صارخة: «أنت ابن الله!»","3:12":"فكان يحذرها بشدة من أن تذيع أمره.","3:13":"ثم صعد إلى الجبل، ودعا الذين أرادهم، فأقبلوا إليه.","3:14":"فعين اثني عشر ليلازموه ويرسلهم ليبشروا،","3:15":"وتكون لهم سلطة على طرد الشياطين.","3:16":"والاثنا عشر الذين عينهم، هم: سمعان، وقد سماه بطرس،","3:17":"ويعقوب بن زبدي، ويوحنا أخوه، وقد سماهما بوانرجس، أي ابني الرعد،","3:18":"وأندراوس، وفيلبس، وبرثلماوس، ومتى وتوما، ويعقوب بن حلفى، وتداوس، وسمعان القانوي،","3:19":"ويهوذا الإسخريوطي الذي خانه.","3:20":"ثم رجعوا إلى البيت، فاحتشد الجمع أيضا، ولم يقدر يسوع وتلاميذه حتى على أكل الطعام.","3:21":"فلما سمع أقرباؤه، جاؤا ليأخذوه، إذ كان أشيع أنه فقد صوابه.","3:22":"وأما الكتبة الذين نزلوا من أورشليم، فقالوا: «إن بعلزبول يسكنه، وإنه برئيس الشياطين يطرد الشياطين!»","3:23":"فدعاهم إليه وكلمهم بالأمثال، قال: «كيف يقدر شيطان أن يطرد شيطانا؟","3:24":"فإذا انقسمت مملكة ما على ذاتها، فإنها لا تقدر أن تصمد.","3:25":"وإذا انقسم بيت ما على ذاته، فإنه لا يقدر أن يصمد.","3:26":"فإذا انقلب الشيطان على نفسه وانقسم، فإنه لا يقدر أن يصمد، بل ينتهي أمره!","3:27":"لا يقدر أحد أن يدخل بيت قوي وينهب أمتعته إلا إذا قيد القوي أولا. وبعدئذ ينهب بيته.","3:28":"الحق أقول لكم: إن جميع الخطايا تغفر لبني البشر، حتى التجاديف التي يجدفونها.","3:29":"ولكن من يجدف على الروح القدس، فلا غفران له أبدا، بل إنه يقع تحت عقاب خطيئة أبدية».","3:30":"ذلك لأنهم قالوا: «إن روحا نجسا يسكنه!»","3:31":"وجاء إخوته وأمه، فوقفوا خارج البيت وأرسلوا إليه يدعونه.","3:32":"وكان قد جلس حوله جمع كبير، فقالوا له: «ها إن أمك وإخوتك في الخارج يطلبونك!»","3:33":"فأجابهم: «من أمي وإخوتي؟»","3:34":"ثم أدار نظره في الجالسين حوله وقال: «هؤلاء هم أمي وإخوتي،","3:35":"لأن من يعمل بإرادة الله هو أخي وأختي وأمي! »","4:1":"ثم أخذ يعلم ثانية عند شاطيء البحيرة، وقد احتشد حوله جمع كبير، حتى إنه صعد إلى القارب وجلس فيه فوق الماء، فيما كان الجمع كله على شاطيء البحيرة.","4:2":"فعلمهم أمورا كثيرة بالأمثال. ومما قاله لهم في تعليمه:","4:3":"«اسمعوا! ها إن الزارع قد خرج ليزرع.","4:4":"وبينما هو يزرع، وقع بعض البذار على الممرات، فجاءت الطيور والتهمته.","4:5":"ووقع بعضه على أرض صخرية رقيقة التربة، فنما سريعا لأن تربته لم تكن عميقة.","4:6":"ولكن لما أشرقت الشمس، احتر ق ويبس لأنه كان بلا أصل.","4:7":"ووقع بعض البذار بين الأشواك، فنبت الشوك وخنقه، فلم يثمر.","4:8":"وبعض البذار وقع في الأرض الجيدة، فنبت ونما وأثمر، فأعطى بعضه ثلاثين ضعفا، وبعضه ستين، وبعضه مئة».","4:9":"ثم قال: «من له أذنان للسمع، فليسمع! »","4:10":"وعندما كان يسوع وحده، سأله الذين حوله والاثنا عشر عن مغزى المثل.","4:11":"فقال لهم: «قد أعطي لكم أن تعرفوا سر ملكوت الله. أما الذين من خارج، فكل شيء يقدم لهم بالأمثال،","4:12":"حتى إنهم: نظرا ينظرون ولا يبصرون، وسمعا يسمعون ولا يفهمون، لئلا يتوبوا فتغفر لهم خطاياهم! »","4:13":"وقال لهم: «ألم تفهموا هذا المثل؟ فكيف تفهمون جميع الأمثال الأخرى؟","4:14":"إن الزارع يزرع كلمة الله.","4:15":"وهؤلاء الذين على الممرات حيث تزرع الكلمة، هم الذين حالما يسمعون يأتي الشيطان ويخطف الكلمة التي زرعت فيهم.","4:16":"وكذلك هؤلاء الذين تزرع فيهم الكلمة على أرض صخرية، وهم الذين حالما يسمعون الكلمة يقبلونها بفرح،","4:17":"ولا أصل لهم في ذواتهم، وإنما هم إلى حين. فحالما يحدث ضيق أو اضطهاد من أجل الكلمة، يتعثرون.","4:18":"والآخرون الذين تزرع فيهم الكلمة بين الأشواك، هؤلاء هم الذين قد سمعوا الكلمة،","4:19":"ولكن هموم الزمان الحاضر وخداع الغنى واشتهاء الأمور الأخرى، تدخل إليهم وتخنق الكلمة، فتصير بلا ثمر.","4:20":"وأما الذين تزرع فيهم الكلمة في الأرض الجيدة، فهؤلاء هم الذين يسمعون الكلمة ويقبلونها فيثمرون، بعضهم ثلاثين ضعفا وبعضهم ستين، وبعضهم مئة».","4:21":"وقال لهم: «هل يؤتى بالمصباح ليوضع تحت المكيال أو تحت السرير؟ أليس ليوضع على المنارة؟","4:22":"فليس من محجوب إلا سيكشف، وما كتم شيء إلا ليعلن!","4:23":"من له أذنان للسمع، فليسمع! »","4:24":"وقال لهم: «تنبهوا لما تسمعون. فبأي كيل تكيلون، يكال لكم ويزاد لكم.","4:25":"فإن من عنده يعطى المزيد، ومن ليس عنده، فحتى الذي عنده ينتزع منه».","4:26":"وقال: «إن ملكوت الله يشبه بإنسان يلقي البذار على الأرض،","4:27":"ثم ينام ليلا ويقوم نهارا فيما البذار يطلع وينمو، وهو لا يدري كيف يحدث الأمر.","4:28":"فالأرض من ذاتها تعطي الثمر، فتطلع أولا عشبة، ثم سنبلة، ثم قمحا ملء السنبلة.","4:29":"ولكن حالما ينضج الثمر، يعمل فيه المنجل إذ يكون الحصاد قد حان».","4:30":"وقال: «بماذا نشبه ملكوت الله، وبأي مثل نمثله؟","4:31":"إنه يشبه ببزرة خردل، تكون عند بذرها على الأرض أصغر من كل ما على الأرض من بزور،","4:32":"ولكن متى تم زرعها، تطلع أغصانا كبيرة، حتى إن طيور السماء تستطيع أن تبيت في ظلها».","4:33":"بكثير من مثل هذه الأمثال كان يسوع يكلم الجمع بالكلمة، على قدر ما كانوا يطيقون أن يسمعوا.","4:34":"وبغير مثل لم يكن يكلمهم. ولكنه كان يفسر لتلاميذه كل شيء حين ينفرد بهم.","4:35":"وفي ذلك اليوم، عندما حل المساء، قال لتلاميذه: «لنعبر إلى الضفة المقابلة!»","4:36":"فلما صرفوا الجمع، أخذوه معهم في القارب الذي كان فيه. وكان معه أيضا قوارب أخرى.","4:37":"فهبت عاصفة ريح شديدة، وأخذت الأمواج تضرب القارب حتى كاد يمتلىء ماء.","4:38":"وكان هو في مؤخر القارب نائما على وسادة. فأيقظوه وقالوا له: «يامعلم، أما يهمك أننا نهلك؟»","4:39":"فنهض، وزجر الريح، وقال للبحر: «اصمت. اخرس!» فسكنت الريح وساد هدوء تام.","4:40":"ثم قال لهم: «لماذا أنتم خائفون هكذا؟ كيف لا إيمان لكم؟»","4:41":"فخافوا خوفا شديدا، وقال بعضهم لبعض: «من هو هذا، حتى إن الريح والبحر يطيعانه؟ »*","5:1":"ثم وصلوا إلى الضفة المقابلة من البحيرة، إلى بلدة الجراسيين.","5:2":"وحالما نزل من القارب، لاقاه من بين القبور إنسان يسكنه روح نجس،","5:3":"كان يقيم في القبور. ولم يكن أحد يقدر أن يقيده ولو بالسلاسل.","5:4":"فإنه كثيرا ما ربط بالقيود والسلاسل، فكان يقطع السلاسل ويحطم القيود، ولم يقدر أحد أن يخضعه.","5:5":"وكان في القبور وفي الجبال دائما، ليلا ونهارا، يصيح ويجرح جسمه بالحجارة.","5:6":"ولكنه لما رأى يسوع من بعيد، ركض وسجد له،","5:7":"وصرخ بأعلى صوته: «ما شأنك بي يايسوع ابن الله العلي؟ أستحلفك بالله ألا تعذبني!»","5:8":"فإن يسوع كان قد قال له؟ «أيها الروح النجس، اخرج من الإنسان!»","5:9":"وسأله يسوع: «ما اسمك؟» فأجاب: «اسمي لجيون لأننا جيش كبير!»","5:10":"وتوسل إليه بإلحاح ألا يطرد الأرواح النجسة إلى خارج تلك المنطقة.","5:11":"وكان هناك قطيع كبير من الخنازير يرعى عند الجبل،","5:12":"فتوسلت الأرواح النجسة إلى يسوع قائلة: «أرسلنا إلى الخنازير لندخل فيها!»","5:13":"فأذن لها بذلك. فخرجت الأرواح النجسة ودخلت في الخنازير، فاندفع قطيع الخنازير من على حافة الجبل إلى البحيرة، فغرق فيها. وكان عدده نحو ألفين.","5:14":"أما رعاة الخنازير فهربوا وأذاعوا الخبر في المدينة وفي المزارع. فخرج الناس ليروا ما قد جرى،","5:15":"وجاءوا إلى يسوع، فرأوا الذي كان مسكونا بالشياطين جالسا ولابسا وصحيح العقل، فاستولى عليهم الخوف.","5:16":"فحدثهم الذين رأوا ما جرى بما حدث للمجنون وللخنازير","5:17":"فأخذوا يرجون من يسوع أن يرحل عن ديارهم.","5:18":"وفيما كان يركب القارب، توسل إليه الإنسان الذي كانت الشياطين تسكنه أن يرافقه.","5:19":"فلم يسمح له، بل قال له: «اذهب إلى بيتك، وإلى أهلك، وأخبرهم بما عمله الرب بك ورحمك».","5:20":"فانطلق وأخذ ينادي في المدن العشر بما عمله يسوع به. فتعجب الجميع.","5:21":"ولما عاد يسوع وعبر في القارب إلى الضفة المقابلة من البحيرة، اجتمع إليه وهو عند الشاطيء جمع كبير.","5:22":"وإذا واحد من رؤساء المجمع، واسمه يايرس، قد جاء إليه. وما إن رآه، حتى ارتمى عند قدميه،","5:23":"وتوسل إليه بإلحاح، قائلا: «ابنتي الصغيرة مشرفة على الموت. فتعال والمسها بيدك لتشفى فتحيا!»","5:24":"فذهب معه، يتبعه جمع كبير وهم يزحمونه.","5:25":"وكانت هناك امرأة مصابة بنزيف دموي منذ اثنتي عشرة سنة،","5:26":"وقد عانت الكثير من الألم على أيدي أطباء كثيرين، وأنفقت في سبيل علاجها كل ما تملك، فلم تجن أية فائدة، بل بالأحرى ازدادت حالتها سوءا.","5:27":"فإذ كانت قد سمعت عن يسوع، جاءت في زحمة الجمع من خلفه ولمست رداءه،","5:28":"لأنها قالت: «يكفي أن ألمس ثيابه لأشفى».","5:29":"وفي الحال انقطع نزيف دمها وأحست في جسمها أنها شفيت من علتها.","5:30":"وحالما شعر يسوع في نفسه بالقوة التي خرجت منه، أدار نظره في الجمع وسأل: «من لمس ثيابي؟»","5:31":"فقال له تلاميذه: «أنت ترى الجمع يزحمونك، وتسأل: من لمسني؟»","5:32":"ولكنه ظل يتطلع حوله ليرى التي فعلت ذلك.","5:33":"فما كان من المرأة، وقد علمت بما حدث لها، إلا أن جاءت وهي خائفة ترتجف، وارتمت أمامه وأخبرته بالحقيقة كلها.","5:34":"فقال لها: «ياابنة، إيمانك قد شفاك. فاذهبي بسلام وتعافي من علتك !»","5:35":"وبينما يسوع يتكلم، جاء بعضهم من بيت رئيس المجمع قائلين: «ابنتك قد ماتت. فلماذا تكلف المعلم بعد؟»","5:36":"ولكن يسوع، ما إن سمع بذلك الخبر، حتى قال لرئيس المجمع: «لا تخف؛ آمن فقط!»","5:37":"ولم يدع أحدا يرافقه إلا بطرس ويعقوب ويوحنا أخا يعقوب.","5:38":"ووصل إلى بيت رئيس المجمع، فرأى الجلبة والناس يبكون ويولولون كثيرا.","5:39":"فلما دخل، قال لهم: «لماذا تضجون وتبكون؟ لم تمت الصبية، بل هي نائمة».","5:40":"فضحكوا منه. أما هو، فأخرجهم جميعا، ثم أخذ معه أبا الصبية وأمها والذين كانوا يرافقونه، ودخل حيث كانت الصبية.","5:41":"وإذ أمسك بيدها قال: «طليثا قومي!» أي: «ياصبية، لك أقول: قومي».","5:42":"فنهضت الصبية حالا وأخذت تمشي، إذ كان عمرها اثنتي عشر ة سنة. فدهش الجميع دهشة عظيمة.","5:43":"فأمرهم بشدة أن لا يعلم أحد بذلك، وطلب أن تعطى ما تأكله.","6:1":"وغادر يسوع ذلك المكان وعاد إلى بلدته، وتلاميذه يتبعونه.","6:2":"ولما حل السبت، أخذ يعلم في المجمع، فدهش كثيرون حين سمعوه، وقالوا: «من أين له هذا؟ وما هذه الحكمة الموهوبة له، وهذه المعجزات الجارية على يديه؟","6:3":"أليس هذا هو النجار ابن مريم، وأخا يعقوب ويوسي ويهوذا وسمعان؟ أوليست أخواته عندنا هنا؟» هكذا كانوا يشكون فيه.","6:4":"ولكن يسوع قال لهم: «لا يكون النبي بلا كرامة إلا في بلدته، وبين أقربائه، وفي بيته!»","6:5":"ولم يقدر أن يعمل هناك أية معجزة، غير أنه لمس بيديه عددا قليلا من المرضى فشفاهم.","6:6":"وتعجب من عدم إيمانهم. ثم أخذ يطوف بالقرى المجاورة وهو يعلم.","6:7":"ثم استدعى الاثني عشر تلميذا، وأخذ يرسلهم اثنين اثنين، وقد أعطاهم سلطة على الأرواح النجسة،","6:8":"وأوصاهم أن لا يحملوا للطريق شيئا إلا عصا، لا خبزا ولا زادا ولا مالا ضمن أحزمتهم،","6:9":"بل ينتعلوا حذاء ويلبسوا رداء واحدا.","6:10":"وقال لهم: «أينما دخلتم بيتا، فأقيموا فيه إلى أن ترحلوا من هناك.","6:11":"وإن كان أحد لا يقبلكم ولا يسمع لكم في مكان ما، فاخرجوا من هناك، وانفضوا التراب عن أقدامكم شهادة عليهم».","6:12":"فانطلقوا يبشرون داعين إلى التوبة،","6:13":"وطردوا شياطين كثيرة، ودهنوا كثيرين من المرضى بزيت، وشفوهم.","6:14":"وسمع الملك هيرودس عن يسوع، لأن اسمه كان قد صار مشهورا، إذ قال بعضهم: «هذا يوحنا المعمدان وقد قام من بين الأموات، ولذلك تجرى على يده المعجزات!»","6:15":"وآخرون قالوا: «هذا إيليا» وغيرهم قالوا: «هذا نبي كباقي الأنبياء!»","6:16":"وأما هيرودس، فلما سمع قال «ما هو إلا يوحنا الذي قطعت أنا رأسه، وقد قام! »","6:17":"فإن هيرودس هذا كان قد أرسل وقبض على يوحنا وقيده في السجن. وذلك من أجل هيروديا التي تزوجها هيرودس وهي زوجة أخيه فيلبس.","6:18":"فإن يوحنا كان يقول له: «ليس حلالا لك أن تتزوج بزوجة أخيك!»","6:19":"فكانت هيروديا ناقمة على يوحنا، وتتمنى أن تقتله، ولكنها لم تستطع.","6:20":"فقد كان هيرودس يرهب يوحنا لعلمه أنه رجل بار وقديس، وكان يحافظ على سلامته. ومع أنه كان يتضايق كثيرا من كلامه، إلا أنه كان يحب الاستماع إليه.","6:21":"ثم سنحت الفرصة عندما أقام هيرودس بمناسبة ذكرى مولده وليمة لعظمائه وقادة الألوف وأعيان منطقة الجليل.","6:22":"فقد دخلت ابنة هيروديا ورقصت، فسرت هيرودس والمتكئين معه. فقال الملك للصبية: «اطلبي مني ما تريدين، فأعطيك إياه!»","6:23":"وأقسم لها قائلا: «لأعطينك مهما طلبت مني، ولو نصف مملكتي!»","6:24":"فخرجت وسألت أمها: «ماذا أطلب؟» فأجابت: «رأس يوحنا المعمدان!»","6:25":"فعادت في الحال إلى الداخل وطلبت من الملك قائلة: «أريد أن تعطيني حالا رأس يوحنا المعمدان على طبق!»","6:26":"فحزن الملك جدا. ولكنه لأجل ما أقسم به ولأجل المتكئين معه، لم يرد أن يخلف وعده لها.","6:27":"وفي الحال أرسل الملك سيافا وأمر أن يؤتى برأس يوحنا. فذهب السياف وقطع رأس يوحنا في السجن،","6:28":"ثم جاء بالرأس على طبق وقدمه إلى الصبية فحملته إلى أمها.","6:29":"ولما سمع تلاميذ يوحنا بذلك، جاءوا ورفعوا جثمانه، ودفنوه في قبر.","6:30":"واجتمع الرسل إلى يسوع، وأخبروه بكل شيء: بما عملوه وما علموه.","6:31":"فقال لهم: «تعالوا أنتم على انفراد إلى مكان خال، واستريحوا قليلا». فقد كان القادمون والذاهبون كثيرين حتى لم يدعوا لهم فرصة للأكل.","6:32":"فذهب التلاميذ في القارب إلى مكان مقفر منفردين.","6:33":"ولكن كثيرين رأوهم منطلقين، فعرفوا وجهتهم، وأخذوا يتراكضون معا إلى هناك سيرا على الأقدام، خارجين من جميع المدن، فسبقوهم.","6:34":"فلما نزل يسوع من القارب، رأى الجمع الكثير وتحنن عليهم، لأنهم كانوا كغنم لا راعي لها. فأخذ يعلمهم أمورا كثيرة.","6:35":"ولما مضى جزء كبير من النهار، تقدم إليه تلاميذه، وقالوا: «المكان مقفر، والنهار كاد ينقضي.","6:36":"فاصرف الجمع ليذهبوا إلى القرى والمزارع المجاورة ويشتروا لأنفسهم ما يأكلون».","6:37":"فرد قائلا: «أعطوهم أنتم ليأكلوا!» فقالوا له: «هل نذهب ونشتري بمئتي دينار خبزا ونعطيهم ليأكلوا؟»","6:38":"فسألهم: «كم رغيفا عندكم؟ اذهبوا وانظروا». فلما تحققوا، قالوا: «خمسة، وسمكتان!»","6:39":"فأمرهم أن يجلسوا الجمع جماعات جماعات على العشب الأخضر.","6:40":"فجلسوا في حلقات تتألف كل منها من مئة أو خمسين.","6:41":"ثم أخذ يسوع الأرغفة الخمسة والسمكتين، ورفع نظره إلى السماء وبارك، وكسر الأرغفة، وأعطى تلاميذه ليقدموا للجمع والسمكتان قسمهما للجميع.","6:42":"فأكلوا جميعا وشبعوا.","6:43":"ثم رفعوا اثنتي عشرة قفة مملوءة من كسر الخبز وبقايا السمك.","6:44":"وأما الذين أكلوا من الخبز، فكانوا خمسة آلاف رجل.","6:45":"وفي الحال ألزم تلاميذه أن يركبوا القارب ويسبقوه إلى الضفة المقابلة، إلى بيت صيدا، ريثما يصرف الجمع.","6:46":"وبعدما صرفهم ذهب إلى الجبل ليصلي.","6:47":"ولما حل المساء، كان القارب في وسط البحيرة، ويسوع وحده على البر.","6:48":"وإذ رآهم يتعذبون في التجذيف، لأن الريح كانت معاكسة لهم، جاء إليهم ماشيا على ماء البحيرة، نحو الربع الأخير من الليل، وكاد أن يتجاوزهم.","6:49":"ولكنهم لما رأوه ماشيا على الماء، ظنوه شبحا فصرخوا.","6:50":"فقد رأوه كلهم وذعروا. إلا أنه كلمهم في الحال وقال لهم: «تشجعوا، أنا هو، لا تخافوا!»","6:51":"وصعد إليهم في القارب فسكنت الريح. فدهشوا دهشة فائقة، وتعجبوا جدا،","6:52":"لأنهم لم يفهموا بمعجزة الأرغفة، فقد كانت قلوبهم قاسية.","6:53":"ولما عبروا إلى الضفة المقابلة، جاءوا إلى أرض جنيسارت، وأرسوا القارب.","6:54":"وحالما نزلوا من القارب، عرفه الناس،","6:55":"فطافوا في أنحاء تلك البلاد المجاورة، وأخذوا يحملون من كانوا مرضى على فرش إلى كل مكان يسمعون أنه فيه.","6:56":"وأينما دخل، إلى القرى أو المدن أو المزارع، وضعوا المرضى في الساحات العامة، متوسلين إليه أن يلمسوا ولو طرف ردائه. فكان كل من يلمسه يشفى.","7:1":"واجتمع إليه الفريسيون وبعض الكتبة، قادمين من أورشليم.","7:2":"ورأوا بعض تلاميذه يتناولون الطعام بأيد نجسة، أي غير مغسولة.","7:3":"فقد كان الفريسيون، واليهود عامة، لا يأكلون ما لم يغسلوا أيديهم مرارا، متمسكين بتقليد الشيوخ.","7:4":"وإذا عادوا من السوق، لا يأكلون ما لم يغتسلوا. وهناك طقوس أخرى كثيرة تسلموها ليتمسكوا بها، كغسل الكؤوس والأباريق وأوعية النحاس.","7:5":"عندئذ سأله الفريسيون والكتبة: «لماذا لا يسلك تلاميذك وفقا لتقليد الشيوخ، بل يتناولون الطعام بأيد نجسة؟»","7:6":"فرد عليهم قائلا: «أحسن إشعياء إذ تنبأ عنكم أيها المراؤون، كما جاء في الكتاب: هذا الشعب يكرمني بشفتيه، وأما قلبه فبعيد عني جدا.","7:7":"إنما باطلا يعبدونني وهم يعلمون تعاليم ليست إلا وصايا الناس !","7:8":"فقد أهملتم وصية الله وتمسكتم بتقليد الناس!»","7:9":"وقال لهم: «حقا أنكم رفضتم وصية الله لتحافظوا على تقليدكم أنتم!","7:10":"فإن موسى قال: أكرم أباك وأمك! وأيضا: من أهان أباه أو أمه، فليكن الموت عقابا له!","7:11":"ولكنكم أنتم تقولون: إذا قال أحد لأبيه أو أمه: إن ما كنت أعولك به قد جعلته قربانا، أي تقدمة (للهيكل)،","7:12":"فهو في حل من إعانة أبيه أو أمه!","7:13":"وهكذا تبطلون كلمة الله بتعليمكم التقليدي الذي تتناقلونه. وهناك أمور كثيرة مثل هذه تفعلونها! »","7:14":"وإذ دعا الجمع إليه ثانية، قال لهم: «اسمعوا لي كلكم وافهموا!","7:15":"لا شيء من خارج الإنسان إذا دخله يمكن أن ينجسه. أما الأشياء الخارجة من الإنسان، فهي التي تنجسه.","7:16":"من له أذنان للسمع، فليسمع».","7:17":"ولما غادر الجمع ودخل البيت، استفسره التلاميذ مغزى المثل،","7:18":"فقال لهم: «أهكذا أنتم أيضا لا تفهمون؟ ألا تدركون أن كل ما يدخل الإنسان من الخارج لا يمكن أن ينجسه،","7:19":"لأنه لا يدخل إلى قلبه بل إلى البطن، ثم يخرج إلى الخلاء؟» مما يجعل الأطعمة كلها طاهرة.","7:20":"ثم قال: «إن الذي يخرج من الإنسان، هو ينجس الإنسان.","7:21":"فإنه من الداخل، من قلوب الناس، تنبع الأفكار الشريرة، الفسق، السرقة، القتل،","7:22":"الزنى، الطمع، الخبث، الخداع، العهارة، العين الشريرة، التجديف، الكبرياء، الحماقة","7:23":"هذه الأمور الشريرة كلها تنبع من داخل الإنسان وتنجسه».","7:24":"ثم ترك يسوع تلك المنطقة وذهب إلى نواحي صور. فدخل بيتا وهو لا يريد أن يعلم به أحد. ومع ذلك، لم يستطع أن يظل مختفيا.","7:25":"فإن امرأة كان بابنتها روح نجس، ما إن سمعت بخبره حتى جاءت وارتمت على قدميه،","7:26":"وكانت المرأة يونانية، من أصل سوري فينيقي، وتوسلت إليه أن يطرد الشيطان من ابنتها.","7:27":"ولكنه قال لها: «دعي البنين أولا يشبعون! فليس من الصواب أن يؤخذ خبز البنين ويطرح للكلاب».","7:28":"فأجابت قائلة له: «صحيح ياسيد! ولكن الكلاب تحت المائدة تأكل من فتات البنين!»","7:29":"فقال لها: «لأجل هذه الكلمة اذهبي، فقد خرج الشيطان من ابنتك!»","7:30":"فلما رجعت إلى بيتها، وجدت ابنتها على السرير وقد خرج منها الشيطان.","7:31":"ثم غادر يسوع نواحي صور وعاد إلى بحيرة الجليل، مرورا بصيدا وعبر حدود المدن العشر.","7:32":"فأحضروا إليه أصم معقود اللسان، وتوسلوا إليه أن يضع يده عليه.","7:33":"فانفرد به بعيدا عن الجمع. ووضع إصبعيه في أذني الرجل، ثم تفل ولمس لسانه،","7:34":"ورفع نظره إلى السماء، وتنهد وقال له: «افتح!» أي انفتح.","7:35":"وفي الحال انفتحت أذناه وانحلت عقدة لسانه، وتكلم بطلاقة.","7:36":"وأوصاهم أن لا يخبروا أحدا بذلك. ولكن كلما أوصاهم أكثر، كانوا يكثرون من إعلان الخبر.","7:37":"وذهلوا إلى الغاية، قائلين: «إنه يبدع في كل ما يفعل. فهو يجعل الصم يسمعون والخرس يتكلمون».","8:1":"في تلك الأيام، إذ احتشد أيضا جمع كبير، ولم يكن عندهم ما يأكلون، دعا يسوع تلاميذه إليه وقال لهم:","8:2":"«إني أشفق على الجمع لأنهم ما زالوا معي منذ ثلاثة أيام، وليس عندهم ما يأكلون.","8:3":"وإن صرفتهم إلى بيوتهم صائمين، تخور قواهم في الطريق، لأن بعضا منهم جاءوا من أماكن بعيدة».","8:4":"فقال له التلاميذ: «من أين يستطيع أحد أن يشبع هؤلاء خبزا هنا في هذا المكان المقفر؟»","8:5":"فسألهم: «كم رغيفا عندكم؟» أجابوا: «سبعة!»","8:6":"فأمر الجمع أن يجلسوا على الأرض. ثم أخذ الأرغفة السبعة، وشكر، وأعطى تلاميذه ليقدموا للجمع، ففعلوا","8:7":"وكان معهم أيضا بعض سمكات صغار، فباركها وأمر بتقديمها أيضا إلى الجمع.","8:8":"فأكل الجميع حتى شبعوا. ثم رفع التلاميذ سبعة سلال ملأوها بما فضل من الكسر.","8:9":"وكان الآكلون نحو أربعة آلاف. ثم صرفهم،","8:10":"وفي الحال ركب القارب مع تلاميذه، وجاء إلى نواحي دلمانوثة.","8:11":"فأقبل الفريسيون وأخذوا يجادلونه، طالبين منه آية من السماء ليجربوه.","8:12":"فتنهد متضايقا، وقال: «لماذا يطلب هذا الجيل آية؟ الحق أقول لكم: لن يعطى هذا الجيل آية! »","8:13":"ثم تركهم وعاد فركب القارب وعبر إلى الضفة المقابلة.","8:14":"وكانوا قد نسوا أن يتزودوا خبزا، ولم يكن معهم في القارب إلا رغيف واحد.","8:15":"وأوصاهم قائلا: «انتبهوا! خذوا حذركم من خمير الفريسيين وخمير هيرودس».","8:16":"فأخذوا يحاجون بعضهم بعضا، قائلين: «ذلك لأنه ليس عندنا خبز».","8:17":"فعلم يسوع بذلك، وقال لهم: «لماذا يحاج بعضكم بعضا لأنه ليس عندكم خبز؟ ألا تدركون بعد ولا تفهمون؟ أما زالت قلوبكم متقسية؟","8:18":"لكم عيون، ألا تبصرون؟ لكم آذان، ألا تسمعون؟ أولستم تذكرون؟","8:19":"عندما كسرت الأرغفة الخمسة للخمسة الآلاف، كم قفة ملأى بالكسر رفعتم؟» قالوا له: «اثنتي عشرة!»","8:20":"«وعندما كسرت الأرغفة السبعة للأربعة الآلاف، كم سلا مليئا بالكسر رفعتم؟» قالوا: «سبعة!»","8:21":"فقال لهم: «وكيف لا تفهمون بعد؟ »","8:22":"وجاءوا إلى بلدة بيت صيدا، فأحضر بعضهم إليه أعمى وتوسلوا إليه أن يضع يده عليه.","8:23":"فأمسك بيد الأعمى واقتاده إلى خارج القرية، وبعدما تفل على عينيه، وضع يديه عليه وسأله: «هل ترى شيئا؟»","8:24":"فتطلع، وقال: «أرى أناسا، كأنهم أشجار، يمشون».","8:25":"فوضع يديه ثانية على عينيه، فتطلع بانتباه، وعاد صحيحا يرى كل شيء واضحا.","8:26":"فأرسله إلى بيته قائلا: «لا تدخل ولا إلى القرية! »","8:27":"ثم توجه يسوع وتلاميذه إلى قرى قيصرية فيلبس. وفي الطريق، سأل تلاميذه: «من يقول الناس إني أنا؟»","8:28":"فأجابوه: «(يقول بعضهم) إنك يوحنا المعمدان، وغيرهم إنك إيليا، وآخرون إنك واحد من الأنبياء».","8:29":"فسألهم: «وأنتم، من تقولون إني أنا؟» فأجابه بطرس: «أنت المسيح!»","8:30":"فحذرهم من أن يخبروا أحدا بأمره.","8:31":"وأخذ يعلمهم أن ابن الإنسان لابد أن يتألم كثيرا، ويرفضه الشيوخ ورؤساء الكهنة والكتبة، ويقتل، وبعد ثلاثة أيام يقوم.","8:32":"وقد تحدث عن هذا الأمر صراحة. فانتحى به بطرس جانبا وأخذ يوبخه.","8:33":"ولكنه التفت ونظر إلى تلاميذه وزجر بطرس قائلا: «اغرب من أمامي ياشيطان، لأنك تفكر لا بأمور الله بل بأمور الناس! »","8:34":"ثم دعا الجمع مع تلاميذه، وقال لهم: «إن أراد أحد أن يسير ورائي، فلينكر نفسه، ويحمل صليبه، ويتبعني.","8:35":"فأي من أراد أن يخلص نفسه، يخسرها. ولكن من يخسر نفسه من أجلي ومن أجل الإنجيل، فهو يخلصها.","8:36":"فماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه؟","8:37":"أو ماذا يقدم الإنسان فداء عن نفسه؟","8:38":"فإن أي من يستحي بي وبكلامي في هذا الجيل الفاسق الخاطيء، به يستحي ابن الإنسان عندما يعود في مجد أبيه مع الملائكة المقدسين».","9:1":"وقال لهم: «الحق أقول لكم: إن بعضا من الواقفين هنا، لن يذوقوا الموت إلا بعد أن يروا ملكوت الله وقد أتى بقدرة. »","9:2":"وبعد ستة أيام، أخذ يسوع بطرس ويعقوب ويوحنا وحدهم، وصعد بهم على انفراد إلى جبل عال، حيث تجلى أمامهم،","9:3":"وصارت ثيابه لماعة تفوق الثلج بياضا، يعجز أي قصار على الأرض أن يبيض ما يماثلها.","9:4":"وظهر لهم إيليا وموسى يتحدثان مع يسوع.","9:5":"فبدأ بطرس يقول ليسوع: «ياسيد، ما أحسن أن نبقى هنا. فلننصب ثلاث خيام: واحدة لك، وواحدة لموسى، وواحدة لإيليا!»","9:6":"فإنه لم يكن يدري ما يقول، إذ كان الخوف قد استولى عليهم.","9:7":"وجاءت سحابة فخيمت عليهم، وانطلق صوت من السحابة يقول: «هذا هو ابني الحبيب. له اسمعوا!»","9:8":"وفجأة نظروا حولهم فلم يروا أحدا معهم إلا يسوع وحده.","9:9":"وفيما هم نازلون من الجبل، أوصاهم ألا يخبروا أحدا بما رأوا، إلا بعد أن يكون ابن الإنسان قد قام من بين الأموات.","9:10":"فعملوا بهذه الوصية، متسائلين فيما بينهم «ماذا يعني بالقيامة من بين الأموات؟»","9:11":"وسألوه: «لماذا يقول الكتبة إن إيليا لابد أن يأتي قبلا؟»","9:12":"فأجابهم: «حقا، إن إيليا يأتي قبلا ويصلح كل شيء. كذلك جاء في الكتاب أن ابن الإنسان لابد أن يتألم كثيرا ويهان.","9:13":"على أني أقول لكم: إن إيليا قد أتى فعلا، وقد عملوا به أيضا كل ما شاءوا، كما جاء عنه في الكتاب! »","9:14":"ولما وصلوا إلى باقي التلاميذ، رأوا جمعا عظيما حولهم وبعض الكتبة يجادلونهم.","9:15":"وحالما رآه الجمع، ذهلوا كلهم وأسرعوا إليه يسلمون عليه.","9:16":"فسألهم: «فيم تجادلونهم؟»","9:17":"فرد عليه واحد من الجمع قائلا: «يامعلم، أحضرت إليك ابني وبه روح أخرس،","9:18":"حيثما تملكه يصرعه، فيزبد ويصر بأسنانه ويتيبس. وقد طلبت من تلاميذك أن يطردوه، فلم يقدروا».","9:19":"فأجابهم قائلا: «أيها الجيل غير المؤمن! إلى متى أبقى معكم؟ إلى متى أحتملكم؟ أحضروه إلي!»","9:20":"فأحضروه إلى يسوع. فما إن رآه الروح، حتى صرع الصبي، فوقع على الأرض يتمرغ مزبدا.","9:21":"وسأل أباه: «منذ متى يصيبه هذا؟» فأجاب: «منذ طفولته.","9:22":"وكثيرا ما ألقاه في النار وفي الماء ليهلكه. ولكن إن كنت تقدر على شيء، فأشفق علينا وأعنا!»","9:23":"فقال له يسوع: «بل إن كنت أنت تقدر أن تؤمن، فكل شيء مستطاع لدى المؤمن!»","9:24":"فصرخ أبو الصبي في الحال: «أنا أومن، فأعن عدم إيماني».","9:25":"فلما رأى يسوع الجمع يركضون معا، زجر الروح النجس قائلا له: «أيها الروح الأخرس الأصم، إني آمرك، فاخرج منه ولا تعد تدخله بعد!»","9:26":"فصرخ الروح وصرع الصبي بشدة، ثم خرج. وصار الصبي كأنه ميت، حتى قال أكثر الجمع: «إنه مات!»","9:27":"ولكن لما أمسكه يسوع بيده وأنهضه، نهض.","9:28":"وبعدما دخل يسوع البيت، سأله تلاميذه على انفراد: «لماذا لم نقدر نحن أن نطرد الروح؟»","9:29":"فأجاب: «هذا النوع لا يطرد بشيء إلا بالصلاة والصوم! »","9:30":"ثم انصرفوا من هناك واجتازوا منطقة الجليل، ولم يرد أن يعلم به أحد،","9:31":"لأنه كان يعلم تلاميذه فيقول لهم: «إن ابن الإنسان سيسلم إلى أيدي الناس، فيقتلونه، وبعد قتله يقوم في اليوم الثالث».","9:32":"ولكنهم لم يفهموا هذا القول، وخافوا أن يسألوه.","9:33":"ثم جاء إلى كفرناحوم. وبينما هو في البيت، سأل تلاميذه: «فيم كنتم تتجادلون في الطريق؟».","9:34":"فسكتوا، إذ كانوا في الطريق قد تجادلوا في من هو الأعظم بينهم.","9:35":"فجلس، ودعا الاثني عشر تلميذا، وقال لهم: «إن أراد أحد أن يكون الأول، فليجعل نفسه آخر الجميع وخادما للجميع!»","9:36":"ثم أخذ ولدا صغيرا وأوقفه في وسطهم، وضمه بذراعيه، وقال لهم:","9:37":"«أي من قبل باسمي واحدا مثل هذا من الأولاد الصغار، فقد قبلني. ومن قبلني، فلا يقبلني أنا، بل ذاك الذي أرسلني».","9:38":"فتكلم يوحنا قائلا: «يامعلم، رأينا واحدا يطرد شياطين باسمك، وهو لا يتبعنا، فمنعناه لأنه لا يتبعنا!»","9:39":"فقال يسوع: «لا تمنعوه! فما من أحد يعمل معجزة باسمي ويمكنه أن يتكلم علي بالسوء سريعا بعد ذلك.","9:40":"فإن من ليس ضدنا فهو معنا.","9:41":"فإن من سقاكم كأس ماء باسمي لأنكم خاصة المسيح، فالحق أقول لكم إن مكافأته لن تضيع!","9:42":"ومن كان عثرة لأحد الصغار المؤمنين بي، فأفضل له لو علق في عنقه حجر الرحى وطرح في البحر.","9:43":"فإن كانت يدك فخا لك، فاقطعها: أفضل لك أن تدخل الحياة ويدك مقطوعة من أن تكون لك يدان وتذهب إلى جهنم، إلى النار التي لا تطفأ","9:44":"حيث دودهم لا يموت، والنار لا تطفأ","9:45":"وإن كانت رجلك فخا لك، فاقطعها: أفضل لك أن تدخل الحياة ورجلك مقطوعة من أن تكون لك رجلان وتطرح في جهنم، في النار التي لا تطفأ.","9:46":"حيث دودهم لا يموت، والنار لا تطفأ.","9:47":"وإن كانت عينك فخا لك، فاقلعها: أفضل لك أن تدخل ملكوت الله وعينك مقلوعة من أن تكون لك عينان وتطرح في جهنم النار.","9:48":"حيث دودهم لا يموت، والنار لا تطفأ.","9:49":"فإن كل واحد سوف تملحه النار.","9:50":"الملح جيد، ولكن إذا فقد الملح ملوحته، فبماذا تعيدون إليه طعمه؟ فليكن لكم ملح في أنفسكم، وكونوا مسالمين بعضكم لبعض! »","10:1":"ثم غادر تلك المنطقة وجاء إلى نواحي منطقة اليهودية وما وراء الأردن. فاجتمعت إليه الجموع ثانية وأخذ يعلمهم كعادته.","10:2":"وتقدم إليه بعض الفريسيين وسألوه ليجربوه: «هل يحل للرجل أن يطلق زوجته؟»","10:3":"فرد عليهم سائلا:","10:4":"«بماذا أوصاكم موسى؟» فقالوا: «سمح موسى بأن تكتب وثيقة طلاق ثم تطلق الزوجة».","10:5":"فأجابهم يسوع: «بسبب قساوة قلوبكم كتب لكم موسى هذه الوصية.","10:6":"ولكن منذ بدء الخليقة جعل الله الإنسان ذكرا وأنثى.","10:7":"لذلك يترك الرجل أباه وأمه ويتحد بزوجته،","10:8":"فيصير الاثنان جسدا واحدا. فلا يكونان بعد اثنين بل جسدا واحدا.","10:9":"فما جمعه الله لا يفرقه إنسان».","10:10":"وفي البيت، عاد تلاميذه فسألوه عن الأمر.","10:11":"فقال لهم: «أي من طلق زوجته وتزوج بأخرى، يرتكب معها الزنى.","10:12":"وإن طلقت الزوجة زوجها وتزوجت من آخر، ترتكب الزنى! »","10:13":"وقدم إليه بعضهم أولادا صغارا لكي يلمسهم. فزجرهم التلاميذ.","10:14":"فلما رأى يسوع ذلك، غضب وقال لهم: «دعوا الصغار يأتون إلي، ولا تمنعوهم، لأن لمثل هؤلاء ملكوت الله!","10:15":"الحق أقول لكم: من لا يقبل ملكوت الله كأنه ولد صغير، لن يدخله أبدا!»","10:16":"ثم ضم الأولاد بذراعيه وأخذ يباركهم واضعا يديه عليهم.","10:17":"وبينما كان خارجا إلى الطريق، أسرع إليه رجل وجثا له يسأله: «أيها المعلم الصالح، ماذا أعمل لأرث الحياة الأبدية؟»","10:18":"ولكن يسوع قال له: «لماذا تدعوني الصالح؟ ليس أحد صالحا إلا واحد، وهو الله .","10:19":"أنت تعرف الوصايا: لا تقتل؛ لا تزن؛ لا تسرق؛ لا تشهد بالزور؛ لا تظلم؛ أكرم أباك وأمك!»","10:20":"فأجابه قائلا: «هذه كلها عملت بها منذ صغري»","10:21":"وإذ نظر يسوع إليه، أحبه، وقال له: «ينقصك شيء واحد: اذهب، بع كل ما عندك، ووزع على الفقراء، فيكون لك كنز في السماء، ثم تعال اتبعني».","10:22":"وأما هو فمضى حزينا وقد اكتأب من هذا القول، لأنه كان صاحب ثروة كبير ة.","10:23":"فتطلع يسوع حوله وقال لتلاميذه: «ما أصعب دخول الأغنياء إلى ملكوت الله!»","10:24":"فدهش التلاميذ لهذا الكلام. فعاد يسوع يقول لهم: «يابني، ما أصعب دخول المتكلين على المال إلى ملكوت الله!»","10:25":"فأسهل أن يدخل الجمل في ثقب إبرة، من أن يدخل الغني إلى ملكوت الله».","10:26":"فذهلوا إلى الغاية، وقال بعضهم لبعض: «ومن يقدر أن يخلص؟»","10:27":"فقال لهم يسوع وهو ناظر إليهم: «هذا مستحيل عند الناس، ولكن ليس عند الله. فإن كل شيء مستطاع عند الله! »","10:28":"فأخذ بطرس يقول له: «ها نحن قد تركنا كل شيء وتبعناك.»","10:29":"فأجاب يسوع: «الحق أقول لكم: ما من أحد ترك لأجلي ولأجل الإنجيل بيتا أو إخوة أو أخوات أو أما أو أبا أو أولادا أو حقولا،","10:30":"إلا وينال مئة ضعف الآن في هذا الزمان، وفي الزمان الآتي الحياة الأبدية.","10:31":"ولكن أولون كثيرون يصيرون آخرين، والآخرون يصيرون أولين! »","10:32":"وكانوا في الطريق صاعدين إلى أورشليم، ويسوع يتقدمهم، وهم يتبعونه مذهولين خائفين. فانفرد بالاثني عشر، مرة أخرى، وأخذ يطلعهم على ما سيحدث له، فقال:","10:33":"«ها نحن صاعدون إلى أورشليم، وسوف يسلم ابن الإنسان إلى رؤساء الكهنة وإلى الكتبة، فيحكمون عليه بالموت، ويسلمونه إلى أيدي الأمم،","10:34":"فيسخرون منه، ويبصقون عليه، ويجلدونه، ويقتلونه. وفي اليوم الثالث يقوم! »","10:35":"عندئذ تقدم إليه يعقوب ويوحنا ابنا زبدي، وقالا له: «يامعلم، نرغب في أن تفعل لنا كل ما نطلب منك».","10:36":"فسألهما: «ماذا ترغبان في أن أفعل لكما؟»","10:37":"قالا له: «هبنا أن نجلس في مجدك: واحد عن يمينك، وواحد عن يسارك!»","10:38":"فقال لهما يسوع: «أنتما لا تدريان ما تطلبان: أتقدران أن تشربا الكأس التي سأشربها أنا، أو تتعمدا بالمعمودية التي سأتعمد بها أنا؟»","10:39":"فقالا له: «إننا نقدر!» فأجابهما يسوع: «الكأس التي سأشربها سوف تشربان، وبالمعمودية التي سأتعمد بها سوف تتعمدان.","10:40":"أما الجلوس عن يميني وعن يساري، فليس لي أن أمنحه إلا للذين أعد لهم».","10:41":"ولما سمع التلاميذ العشرة بذلك، أخذوا يستاءون من يعقوب ويوحنا.","10:42":"ولكن يسوع دعاهم إليه وقال لهم: «تعرفون أن المعتبرين حكاما على الأمم يسودونهم، وأن عظماءهم يتسلطون عليهم.","10:43":"وأما أنتم فلا يكن ذلك بينكم، وإنما أي من أراد أن يصير عظيما بينكم، فليكن لكم خادما،","10:44":"وأي من أراد أن يصير أولا فيكم، فليكن للجميع عبدا.","10:45":"فحتى ابن الإنسان قد جاء لا ليخدم، بل ليخدم ويبذل نفسه فدية عن كثيرين».","10:46":"ثم وصلوا إلى أريحا. وبينما كان خارجا من أريحا، ومعه تلاميذه وجمع كبير، كان ابن تيماوس، بارتيماوس الأعمى، جالسا على جانب الطريق يستعطي.","10:47":"وإذ سمع أن ذاك هو يسوع الناصري، أخذ يصرخ قائلا: «يايسوع ابن داود، ارحمني!»","10:48":"فزجره كثيرون ليسكت، ولكنه أخذ يزيد صراخا أكثر: «ياابن داود، ارحمني».","10:49":"فتوقف يسوع وقال: «ادعوه!» فدعوا الأعمى قائلين: «تشجع، انهض! إنه يدعوك!»","10:50":"فهب متجها إلى يسوع طارحا عنه رداءه.","10:51":"وسأله يسوع: «ماذا تريد أن أفعل لك؟» فأجابه الأعمى: «ياسيدي، أن أبصر!»","10:52":"فقال له يسوع: «اذهب ! إيمانك قد شفاك». وفي الحال أبصر، وتبع يسوع في الطريق.","11:1":"ولما اقتربوا من أورشليم، إذ وصلوا إلى قرية بيت فاجي وقرية بيت عنيا، عند جبل الزيتون، أرسل يسوع اثنين من تلاميذه،","11:2":"قائلا لهما: «اذهبا إلى القرية المقابلة لكما، وحالما تدخلان إليها، تجدان جحشا مربوطا لم يركب عليه أحد من الناس بعد: فحلا رباطه وأحضراه إلى هنا.","11:3":"وإن قال لكما أحد: لماذا تفعلان هذا؟ فقولا: الرب بحاجة إليه، وفي الحال يرسله إلى هنا».","11:4":"وانطلقا، فوجدا الجحش مربوطا عند الباب خارجا على الطريق، فحلا رباطه.","11:5":"فقال لهما بعض الواقفين هناك: «ماذا تفعلان؟ لماذا تحلان رباط الجحش؟»","11:6":"فأجاباهم كما أوصاهما يسوع فتركوهما.","11:7":"فأحضرا الجحش إلى يسوع، ووضعا ثيابهما عليه، فركب عليه.","11:8":"وفرش كثيرون الطريق بثيابهم وآخرون بأغصان قطعوها من الحقول.","11:9":"وأخذ السائرون أمامه والسائرون خلفه يهتفون: «أوصنا! مبارك الآتي باسم الرب !","11:10":"مباركة مملكة أبينا داود الآتية! أوصنا في الأعالي! »","11:11":"ثم دخل يسوع أورشليم، حتى وصل إلى الهيكل، وراقب كل ما كان يجري فيه. وإذ كان المساء قد أقبل، خرج إلى بيت عنيا مع الاثني عشر.","11:12":"وفي الغد، بعدما غادروا بيت عنيا، جاع.","11:13":"وإذ رأى من بعيد شجرة تين مورقة، توجه إليها لعله يجد فيها بعض الثمر. فلما وصل إليها لم يجد فيها إلا الورق، لأنه ليس أوان التين.","11:14":"فتكلم وقال لها: «لا يأكلن أحد ثمرا منك بعد إلى الأبد!» وسمع تلاميذه ذلك.","11:15":"ووصلوا إلى أورشليم، فدخل يسوع الهيكل وأخذ يطرد الذين كانوا يبيعون والذين كانوا يشترون في الهيكل، وقلب موائد الصيارفة ومقاعد باعة الحمام.","11:16":"ولم يدع أحدا يمر عبر الهيكل وهو يحمل متاعا.","11:17":"وعلمهم قائلا: «أما كتب: إن بيتي بيتا للصلاة يدعى عند جميع الأمم؟ أما أنتم فقد جعلتموه مغارة لصوص!»","11:18":"وسمع بذلك رؤساء الكهنة، والكتبة، فأخذوا يبحثون كيف يقتلونه: فإنهم خافوه، لأن الجمع كله كان مذهولا من تعليمه.","11:19":"ولما حل المساء، انطلقوا إلى خارج المدينة.","11:20":"وبينما كانوا عابرين في صباح الغد باكرا، رأوا شجرة التين وقد يبست من أصلها.","11:21":"فتذكر بطرس وقال له: «يامعلم، انظر! إن التينة التي لعنتها قد يبست!»","11:22":"فرد يسوع قائلا لهم: «ليكن لكم إيمان بالله!","11:23":"فالحق أقول لكم: إن أي من قال لهذا الجبل: انقلع وانطرح في البحر! ولا يشك في قلبه، بل يؤمن أن ما يقوله سيحدث، فما يقوله يتم له.","11:24":"لهذا السبب أقول لكم: إن ما تطلبونه وتصلون لأجله، فآمنوا أنكم قد نلتموه، فيتم لكم.","11:25":"ومتى وقفتم تصلون، وكان لكم على أحد شيء، فاغفروا له، لكي يغفر لكم أبوكم الذي في السماوات زلاتكم أيضا.","11:26":"ولكن، إن لم تغفروا، لا يغفر لكم أيضا أبوكم الذي في السماوات زلاتكم».","11:27":"ثم عادوا إلى أورشليم مرة أخرى. وبينما كان يتجول في الهيكل، تقدم إليه رؤساء الكهنة، والكتبة، والشيوخ،","11:28":"وسألوه: «بأية سلطة تفعل ما فعلته؟ ومن منحك هذه السلطة لتفعل ذلك؟»","11:29":"فأجابهم يسوع قائلا: «وأنا أيضا أسألكم أمرا واحدا. أجيبوني، فأقول لكم بأية سلطة أفعل تلك الأمور:","11:30":"أمن السماء كانت معمودية يوحنا أم من الناس؟ أجيبوني!»","11:31":"فتشاوروا فيما بينهم، قائلين: «إن قلنا: من السماء، يقول: إذن لماذا لم تؤمنوا به؟","11:32":"فهل نقول: من الناس؟» فإنهم كانوا يخافون الشعب لأنهم كانوا جميعا يعتبرون أن يوحنا نبي حقا.","11:33":"فأجابوا يسوع قائلين: «لا ندري!» فقال لهم يسوع: «ولا أنا أقول لكم بأية سلطة أفعل تلك الأمور! »","12:1":"وأخذ يخاطبهم بأمثال، فقال: «غرس إنسان كرما، وأقام حوله سياجا، وحفر فيه حوض معصرة، وبنى فيه برج حراسة. ثم سلم الكرم إلى مزارعين، وسافر.","12:2":"وفي الأوان، أرسل إلى المزارعين عبدا ليتسلم منهم حصته من ثمر الكرم.","12:3":"إلا أنهم أمسكوه وضربوه وردوه فارغ اليدين.","12:4":"فعاد وأرسل إليهم عبدا آخر، فشجوا رأسه وردوه مهانا.","12:5":"ثم أرسل آخر أيضا فقتلوه. ثم أرسل آخرين كثيرين، فضربوا بعضا وقتلوا بعضا.","12:6":"وإذ كان له بعد ابن وحيد حبيب، أرسله أيضا إليهم أخيرا، قائلا: إنهم سيهابون ابني!","12:7":"ولكن أولئك المزارعين قالوا بعضهم لبعض: هذا هو الوريث؛ تعالوا نقتله فنحصل على الميراث!","12:8":"فأمسكوه وقتلوه وطرحوه خارج الكرم.","12:9":"فماذا يفعل رب الكرم؟ إنه يأتي ويهلك المزارعين، ويسلم الكرم إلى غيرهم.","12:10":"أفما قرأ تم هذه الآية المكتوبة: الحجر الذي رفضه البناة، هو نفسه صار حجر الزاوية.","12:11":"من الرب كان هذا، وهو عجيب في أنظارنا!»","12:12":"فسعوا إلى القبض عليه، ولكنهم خافوا الجمع، لأنهم أدركوا أنه كان يعنيهم بهذا المثل. فتركوه وانصرفوا.","12:13":"ثم أرسلوا إليه بعضا من الفريسيين وأعضاء حزب هيرودس، لكي يوقعوه بكلمة يقولها.","12:14":"فجاءوا وقالوا له: «يامعلم، نحن نعلم أنك صادق، ولا تبالي بأحد، لأنك لا تراعي مقامات الناس، بل تعلم طريق الله بالحق: أيحل أن تدفع الجزية للقيصر أم لا؟ أندفعها أم لا ندفع؟»","12:15":"ولكنه إذ علم رياءهم قال لهم: «لماذا تجربونني؟ أحضروا إلي دينارا لأراه!»","12:16":"فأحضروا إليه دينارا، فسألهم: «لمن هذه الصورة وهذا النقش؟» فقالوا له: «للقيصر».","12:17":"فرد عليهم قائلا: «أعطوا ما للقيصر للقيصر، وما لله لله!» فذهلوا منه.","12:18":"وتقدم إليه بعض الصدوقيين الذين لا يؤمنون بالقيامة، وسألوه قائلين:","12:19":"«يامعلم، كتب لنا موسى: إن مات لأحد أخ وترك زوجته من بعده دون أن يخلف أولادا، فعلى أخيه أن يتزوج بأرملته ويقيم نسلا على اسم أخيه.","12:20":"فقد كان هنالك سبعة إخوة، اتخذ أولهم زوجة ثم مات دون أن يخلف نسلا،","12:21":"فاتخذها الثاني ثم مات هو أيضا دون أن يخلف نسلا، ففعل الثالث كذلك.","12:22":"وهكذا اتخذها السبعة دون أن يخلفوا نسلا. ومن بعدهم جميعا، ماتت المرأة أيضا.","12:23":"ففي القيامة، عندما يقومون، لمن منهم تكون المرأة زوجة، فقد كانت زوجة لكل من السبعة؟»","12:24":"فرد عليهم يسوع قائلا: «ألستم في ضلال لأنكم لا تفهمون الكتاب ولا قدرة الله؟","12:25":"فعندما يقوم الناس من بين الأموات، لا يتزوجون ولا يزوجون، بل يكونون كالملائكة الذين في السماوات.","12:26":"وأما عن الأموات أنهم يقومون، أفما قرأتم في كتاب موسى، في الحديث عن العليقة، كيف كلمه الله قائلا: أنا إله إبراهيم وإله إسحق وإله يعقوب؟","12:27":"فإنه ليس بإله أموات، بل هو إله أحياء. فأنتم إذن في ضلال عظيم! »","12:28":"وتقدم إليه واحد من الكتبة كان قد سمعهم يتجادلون، ورأى أنه أحسن الرد عليهم، فسأله: «أية وصية هي أولى الوصايا جميعا؟»","12:29":"فأجابه يسوع: «أولى الوصايا جميعا هي: اسمع ياإسرائيل، الرب إلهنا رب واحد","12:30":"فأحب الرب إلهك بكل قلبك وبكل نفسك وبكل فكرك وبكل قوتك. هذه هي الوصية الأولى.","12:31":"وهناك ثانية مثلها، وهي أن تحب قريبك كنفسك. فما من وصية أخرى أعظم من هاتين».","12:32":"فقال له الكاتب: «صحيح، يامعلم! حسب الحق تكلمت. فإن الله واحد وليس آخر سواه.","12:33":"ومحبته بكل القلب وبكل الفهم وبكل القوة، ومحبة القريب كالنفس، أفضل من جميع المحرقات والذبائح!»","12:34":"فلما رأى يسوع أنه أجاب بحكمة، قال له: «لست بعيدا عن ملكوت الله!» ولم يجرؤ أحد بعد ذلك أن يوجه إليه أي سؤال.","12:35":"وتكلم يسوع فيما هو يعلم في الهيكل، فقال: «كيف يقول الكتبة إن المسيح هو ابن داود؟","12:36":"فإن داود نفسه قال بالروح القدس: قال الرب لربي: اجلس عن يميني حتى أضع أعداءك موطئا لقدميك!","12:37":"فمادام داود نفسه يدعوه الرب فمن أين يكون ابنه؟» وكان الجمع العظيم يسمعه بسرور.","12:38":"وقال لهم في تعليمه: «خذوا حذركم من الكتبة الذين يحبون التجول بالأثواب الفضفاضة، وتلقي التحيات في الساحات العامة،","12:39":"وصدور المقاعد في المجامع، وأماكن الصدارة في الولائم.","12:40":"يلتهمون بيوت الأرامل، ويتذرعون بإطالة الصلوات. هؤلاء ستنزل بهم دينونة أقسى! »","12:41":"وإذ جلس يسوع مقابل صندوق الهيكل، رأى كيف كان الجمع يلقون النقود في الصندوق. وألقى كثيرون من الأغنياء مالا كثيرا.","12:42":"ثم جاءت أرملة فقيرة وألقت فلسين يساويان ربعا واحدا.","12:43":"فدعا تلاميذه وقال لهم: «الحق أقول لكم: إن هذه الأرملة الفقيرة قد ألقت أكثر من جميع الذين ألقوا في الصندوق:","12:44":"لأن جميعهم ألقوا من الفاضل عن حاجتهم، ولكنها هي ألقت من حاجتها كل ما عندها ألقت معيشتها كلها ! »","13:1":"وبينما كان يغادر الهيكل، قال له أحد تلاميذه: «يامعلم، انظر ما أجمل هذه الحجارة وهذه المباني!»","13:2":"فأجابه يسوع: «أترى هذه المباني العظيمة؟ لن يترك منها حجر فوق حجر إلا ويهدم! »","13:3":"وفيما هو جالس على جبل الزيتون مقابل الهيكل، سأله بطرس ويعقوب ويوحنا وأندراوس على انفراد:","13:4":"«أخبرنا متى يحدث هذا، وما هي العلامة عندما توشك هذه الأمور أن تتم؟»","13:5":"فأخذ يسوع يجيبهم قائلا: «انتبهوا! لا يضللكم أحد!","13:6":"فإن كثيرين سيأتون باسمي قائلين، إني أنا هو ويضللون كثيرين.","13:7":"ولكن، عندما تسمعون بالحروب وأخبار الحروب لا ترتعبوا؛ فإن ذلك لابد أن يحدث، ولكن ليست النهاية بعد.","13:8":"فسوف تنقلب أمة على أمة، ومملكة على مملكة، وتحدث زلازل في عدة أماكن، كما تحدث مجاعات ولكن هذا أول المخاض.","13:9":"فانتبهوا لأنفسكم، لأنهم سوف يسلمونكم إلى المحاكم والمجامع، فتضربون وتمثلون أمام حكام وملوك من أجلي، شهادة عندهم.","13:10":"ويجب أن يبشر أولا بالإنجيل في جميع الأمم.","13:11":"فعندما يسوقونكم ليسلموكم، لا تنشغلوا مسبقا بما تقولون: وإنما كل ما تلهمون في تلك الساعة، فبه تكلموا، لأنكم لستم أنتم المتكلمين بل الروح القدس.","13:12":"وسوف يسلم الأخ أخاه إلى الموت، والأب ولده، وينقلب الأولاد على والديهم ويقتلونهم.","13:13":"وتكونون مكروهين لدى الجميع من أجل اسمي. ولكن الذي يثبت حتى النهاية، فهو يخلص.","13:14":"فعندما ترون رجاسة الخراب قائمة حيث لا ينبغي، ليفهم القاريء! عندئذ ليهرب الذين في منطقة اليهودية إلى الجبال؛","13:15":"ومن كان على السطح، فلا ينزل إلى البيت ولا يدخل ليأخذ ما في بيته؛","13:16":"ومن كان في الحقل، فلا يرجع ليأخذ ثوبه.","13:17":"والويل للحبالى والمرضعات في تلك الأيام!","13:18":"فصلوا لكي لا يقع ذلك في شتاء:","13:19":"فسوف تحدث في تلك الأيام ضيقة لم يحدث مثلها منذ بدء الخليقة التي خلقها الله إلى الآن ولن يحدث.","13:20":"ولولا أن الرب قد اختصر تلك الأيام، لما كان أحد من البشر ينجو. ولكنه لأجل المختارين الذين اختارهم، قد اختصر تلك الأيام.","13:21":"فإن قال لكم أحد عندئذ: ها إن المسيح هنا! أو: ها هو هناك! فلا تصدقوا.","13:22":"فسوف يبرز أكثر من مسيح دجال ونبي دجال، ويقدمون آيات وأعاجيب، ليضللوا حتى المختارين، لو استطاعوا.","13:23":"فانتبهوا إذن! ها أنا قد أخبرتكم بالأمور كلها قبل حدوثها.","13:24":"ولكن في تلك الأيام، بعد تلك الضيقة، تظلم الشمس ويحجب القمر ضوءه،","13:25":"وتتهاوى نجوم السماء، وتتزعزع القوات التي في السماوات.","13:26":"وعندئذ سوف يبصرون ابن الإنسان آتيا في السحب بقدرة عظيمة ومجد.","13:27":"فيرسل عندئذ ملائكته ويجمع مختاريه من الجهات الأربع، من أقصى الأرض إلى أقصى السماء.","13:28":"فمن شجرة التين تعلموا هذا المثل: عندما تلين أغصانها وتطلع أوراقها، تعلمون أن الصيف قريب.","13:29":"فكذلك أنتم أيضا، حينما ترون هذه الأمور تحدث، فاعلموا أنه قريب، بل على الأبواب.","13:30":"الحق أقول لكم: لا يزول هذا الجيل أبدا حتى تحدث هذه الأمور كلها.","13:31":"إن السماء والأرض تزولان، ولكن كلامي لا يزول أبدا.","13:32":"وأما ذلك اليوم وتلك الساعة فلا يعرفهما أحد، لا الملائكة الذين في السماء ولا الابن، إلا الآب.","13:33":"فانتبهوا واسهروا لأنكم لا تعرفون متى يحين الوقت!","13:34":"فالأمر أشبه بإنسان مسافر، ترك بيته، وأعطى عبيده السلطة معينا لكل واحد عمله، وأوصى حارس الباب أن يسهر.","13:35":"إذن اسهروا، لأنكم لا تعرفون متى يعود رب البيت: أمساء، أم في منتصف الليل، أم عند صياح الديك، أم صباحا،","13:36":"لئلا يعود فجأة ويجدكم نائمين.","13:37":"وما أقوله لكم، أقوله للجميع: اسهروا! »","14:1":"وكان الفصح وعيد الفطير سيحلان بعد يومين، ومازال رؤساء الكهنة والكتبة يسعون كي يقبضوا عليه بمكر ويقتلوه.","14:2":"فإ نهم قد قالوا: «لا يكون ذلك في العيد، لئلا يحدث اضطراب بين الشعب! »","14:3":"وفيما كان يسوع في بيت عنيا، متكئا في بيت سمعان الأبرص، جاءت امرأة تحمل قارورة عطر من الناردين الخالص الغالي الثمن، فكسرت القارورة وسكبت العطر على رأسه.","14:4":"فاستاء بعضهم في أنفسهم وقالوا: «لماذا هذا التبذير للعطر؟","14:5":"فقد كان يمكن أن يباع هذا العطر بأكثر من ثلاث مئة دينار، ويوهب الثمن للفقراء». وأخذوا يؤنبون المرأة.","14:6":"غير أن يسوع قال: «اتركوها! لماذا تضايقونها؟ إنها عملت بي عملا حسنا.","14:7":"فإن الفقراء عندكم في كل حين، ومتى شئتم تستطيعون أن تحسنوا إليهم. أما أنا فلن أكون عندكم في كل حين.","14:8":"إنها عملت ما تقدر عليه. فقد سبقت فعطرت جسدي إعدادا للدفن.","14:9":"والحق أقول لكم: إنه حيث يبشر بالإنجيل في العالم أجمع، يحدث أيضا بما عملته هذه المرأة، إحياء لذكرها! »","14:10":"ثم ذهب يهوذا الإسخريوطي، أحد الاثني عشر، إلى رؤساء الكهنة ليسلم يسوع إليهم.","14:11":"فلما سمعوا بذلك، فرحوا، ووعدوه أن يعطوه مالا. فأخذ يتحين تسليمه في فرصة مناسبة.","14:12":"وفي اليوم الأول من أيام الفطير، وفيه كان يذبح (حمل) الفصح، سأله تلاميذه: «أين تريد أن نذهب ونجهز لك الفصح لتأكل؟»","14:13":"فأرسل اثنين من تلاميذه، قائلا لهما: «اذهبا إلى المدينة، وسيلاقيكما هناك رجل يحمل جرة ماء، فاتبعاه.","14:14":"وحيث يدخل، قولا لرب البيت: إن المعلم يقول: أين غرفتي التي فيها سآكل الفصح مع تلاميذي؟","14:15":"فيريكما غرفة كبيرة في الطبقة العليا، مفروشة مجهزة. هناك جهزا لنا!»","14:16":"فانطلق التلميذان ودخلا المدينة، ووجدا كما قال لهما. وهناك جهزا للفصح.","14:17":"ولما حل المساء، جاء يسوع مع الاثني عشر.","14:18":"وبينما كانوا متكئين يأكلون، قال يسوع: «الحق أقول لكم: إن واحدا منكم سيسلمني، وهو يأكل الآن معي».","14:19":"فأخذ الحزن يستولي عليهم، وبدأوا يسألونه واحدا بعد الآخر: «هل أنا؟»","14:20":"ولكنه أجابهم قائلا: «إنه واحد من الاثني عشر، وهو الذي يغمس معي في الصحفة.","14:21":"إن ابن الإنسان لابد أن يمضي كما قد كتب عنه، ولكن الويل لذلك الرجل الذي على يده يسلم ابن الإنسان. كان خيرا لذلك الرجل لو لم يولد! »","14:22":"وبينما كانوا يأكلون، أخذ يسوع رغيفا، وبارك، وكسر، وأعطاهم قائلا: «خذوا: هذا هو جسدي».","14:23":"ثم أخذ الكأس، وشكر، وأعطاهم، فشربوا منها كلهم،","14:24":"وقال لهم: «هذا هو دمي الذي للعهد الجديد والذي يسفك من أجل كثيرين.","14:25":"الحق أقول لكم: لا أشرب بعد من نتاج الكرمة أبدا، إلى ذلك اليوم الذي أشربه فيه جديدا في ملكوت الله».","14:26":"ثم رتلوا، وانطلقوا خارجا إلى جبل الزيتون.","14:27":"وقال لهم يسوع: «كلكم ستشكون، لأنه قد كتب: سأضرب الراعي، فتتشتت الخراف.","14:28":"ولكن بعد قيامتي، سأسبقكم إلى الجليل».","14:29":"ولكن بطرس قال له: «ولو شك الجميع، فأنا لن أشك».","14:30":"فقال له يسوع: «الحق أقول لك: إنك اليوم، في هذه الليلة، قبل أن يصيح الديك مرتين، تكون قد أنكرتني ثلاث مرات».","14:31":"إلا أن بطرس قال بأكثر تأكيد: «ولو كان علي أن أموت معك، لا أنكرك أبدا!» وقال التلاميذ كلهم مثل هذا القول.","14:32":"ووصلوا إلى بستان اسمه جثسيماني، فقال لتلاميذه: «اجلسوا هنا ريثما أصلي».","14:33":"وقد أخذ معه بطرس ويعقوب ويوحنا، وبدأ يشعر بالرهبة والكآبة.","14:34":"وقال لهم: «نفسي حزينة جدا حتى الموت. ابقوا هنا واسهروا».","14:35":"ثم ابتعد قليلا، وخر على الأرض، وأخذ يصلي لكي تعبر عنه الساعة إن كان ممكنا.","14:36":"وقال «أبا، ياأبي، كل شيء مستطاع لديك. فأبعد عني هذه الكأس، ولكن ليكن لا ما أريد أنا، بل ما تريد أنت! »","14:37":"ثم رجع فوجد تلاميذه نائمين، فقال لبطرس: «هل أنت نائم ياسمعان؟ ألم تقدر أن تسهر ساعة واحدة؟","14:38":"اسهروا وصلوا لئلا تدخلوا في تجربة. إن الروح نشيط، وأما الجسد فضعيف».","14:39":"ثم ذهب وصلى ثانية، فردد الكلام نفسه.","14:40":"ولما رجع، وجدهم أيضا نائمين لأن النعاس أثقل أعينهم، ولم يدروا بماذا يجيبونه.","14:41":"ثم رجع في المرة الثالثة وقال لهم: «ناموا الآن واستريحوا. يكفي! أقبلت الساعة. ها إن ابن الإنسان يسلم إلى أيدي الخاطئين.","14:42":"قوموا لنذهب. ها قد اقترب الذي يسلمني! »","14:43":"وفي الحال، فيما هو يتكلم، وصل يهوذا، أحد الاثني عشر، ومعه جمع عظيم يحملون السيوف والعصي، وقد أرسلهم رؤساء الكهنة والكتبة والشيوخ.","14:44":"وكان مسلمه قد أعطاهم علامة قائلا: «الذي أقبله، فهو هو. فاقبضوا عليه وسوقوه بحذر».","14:45":"فما إن وصل يهوذا، حتى تقدم إليه، وقال: «سيدي!» وقبله بحرارة.","14:46":"فألقوا القبض عليه.","14:47":"ولكن واحدا من الواقفين هناك، استل سيفه وضرب عبد رئيس الكهنة فقطع أذنه.","14:48":"وكلمهم يسوع قائلا: «أكما على لص خرجتم بالسيوف والعصي لتقبضوا علي؟","14:49":"كنت كل يوم بينكم أعلم في الهيكل، ولم تقبضوا علي. ولكن هذا يجري إتماما للكتاب».","14:50":"عندئذ تركه الجميع وهربوا.","14:51":"وتبعه شاب لا يلبس غير إزار على عريه، فأمسكوه.","14:52":"فترك الإزار وهرب منهم عريانا.","14:53":"وساقوا يسوع إلى رئيس الكهنة. فاجتمع إليه جميع رؤساء الكهنة والشيوخ والكتبة.","14:54":"وتبعه بطرس من بعيد إلى داخل دار رئيس الكهنة، وكان جالسا مع الحراس يستدفيء عند النار.","14:55":"وأخذ رؤساء الكهنة والمجلس الأعلى كله يبحثون عن شهادة على يسوع ليقتلوه، فلم يجدوا.","14:56":"فقد شهد كثيرون عليه زورا، ولكن شهاداتهم كانت متناقضة.","14:57":"ثم قام بعضهم وشهدوا عليه زورا قائلين:","14:58":"«سمعناه يقول: سأهدم هذا الهيكل الذي صنعته الأيادي، وفي ثلاثة أيام أبني هيكلا آخر لم تصنعه الأيادي».","14:59":"ولكن في هذا أيضا، كانت شهاداتهم متناقضة.","14:60":"فوقف رئيس الكهنة في وسط المجلس وسأل يسوع: «أما ترد شيئا؟ بماذا يشهد هؤلاء عليك؟»","14:61":"ولكنه ظل صامتا ولم يرد شيئا. فعاد رئيس الكهنة يسأله، فقال: «أأنت المسيح، ابن المبارك؟»","14:62":"فقال يسوع: «أنا هو. وسوف ترون ابن الإنسان جالسا عن يمين القدرة، ثم آتيا على سحب السماء! »","14:63":"فشق رئيس الكهنة ثيابه، وقال: «لا حاجة بنا بعد إلى شهود.","14:64":"قد سمعتم تجديفه: فما رأيكم؟» فحكم الجميع بأنه يستحق الموت.","14:65":"فبدأ بعضهم يبصقون عليه، ويغطون وجهه ويلطمونه ويقولون له: «تنبأ!» وأخذ الحراس يصفعونه.","14:66":"وبينما كان بطرس تحت في ساحة الدار، جاءت إحدى خادمات رئيس الكهنة،","14:67":"فلما رأت بطرس يستدفيء، نظرت إليه وقالت: «وأنت كنت مع يسوع الناصري!»","14:68":"ولكنه أنكر قائلا: «لا أدري ولا أفهم ما تقولين!» ثم ذهب خارجا إلى مدخل الدار. فصاح الديك","14:69":"وإذ رأته الخادمة ثانية، أخذت تقول للواقفين هناك: «هذا واحد منهم!»","14:70":"فأنكر ثانية. وبعد قليل أيضا، قال الواقفون هناك لبطرس: «حقا أنت واحد منهم، لأنك جليلي».","14:71":"ولكنه بدأ يلعن ويحلف: «إني لا أعرف هذا الرجل الذي تتحدثون عنه».","14:72":"وصاح الديك مرة ثانية فتذكر بطرس ما قاله يسوع له: «قبل أن يصيح الديك مرتين، تكون قد أنكرتني ثلاث مرات». وإذ تفكر بذلك أخذ يبكي.","15:1":"وحالما طلع الصباح، تشاور رؤساء الكهنة والشيوخ والكتبة والمجلس الأعلى كله، ثم قيدوا يسوع، وساقوه، وسلموه إلى بيلاطس.","15:2":"فسأله بيلاطس: «أأنت ملك اليهود؟» فأجابه: «أنت قلت».","15:3":"وأخذ رؤساء الكهنة يوجهون إليه اتهامات كثيرة.","15:4":"فسأله بيلاطس ثانية: «أما ترد شيئا؟ انظر ما يشهدون به عليك!»","15:5":"ولكن يسوع لم يرد شيئا، حتى تعجب بيلاطس.","15:6":"وكان من عادته أن يطلق لهم في العيد أي سجين يطلبونه.","15:7":"وكان المدعو باراباس مسجونا عندئذ مع رفاقه المشاغبين الذين ارتكبوا القتل في أثناء الشغب.","15:8":"فصعد الجمع وأخذوا يطالبون بأن يفعل بيلاطس ما كان يفعله لهم دائما.","15:9":"فكلمهم بيلاطس سائلا: «هل تريدون أن أطلق لكم ملك اليهود؟»","15:10":"لأنه علم أن رؤساء الكهنة كانوا قد سلموه عن حسد.","15:11":"ولكن رؤساء الكهنة حرضوا الجمع على أن يطالبوا، بالأحرى، بإطلاق باراباس.","15:12":"فعاد بيلاطس يسألهم: «فماذا تريدون أن أفعل بمن تدعونه ملك اليهود؟»","15:13":"فراحوا يصرخون مرة بعد مرة: «اصلبه !»","15:14":"فسألهم بيلاطس: «وأي شر فعل؟» إلا أنهم أخذوا يزدادون صراخا: «اصلبه!»","15:15":"وإذ كان بيلاطس يريد أن يرضي الجمع، أطلق لهم باراباس، وبعد ما جلد يسوع، سلمه ليصلب.","15:16":"فاقتاده الجنود إلى داخل الدار، أي دار الحكومة، وجمعوا جنود الكتيبة كلهم.","15:17":"وألبسوه رداء أرجوان، ووضعوا على رأسه إكليلا جدلوه من الشوك.","15:18":"وبدأوا يحيونه قائلين: «سلام، ياملك اليهود!»","15:19":"ويضربون رأسه بقصبة، ويبصقون عليه، ويسجدون له جاثين على ركبهم.","15:20":"وبعدما أوسعوه سخرية، نزعوا رداء الأرجوان، وألبسوه ثيابه، وساقوه إلى الخارج ليصلبوه.","15:21":"وسخروا واحدا من المارة ليحمل صليبه، وهو سمعان من القيروان، أبو إسكندر وروفس، وكان آتيا من الحقل.","15:22":"وساروا به إلى مكان الجلجثة، أي مكان الجمجمة.","15:23":"وقدموا له خمرا ممزوجة بمر، فرفض أن يشرب.","15:24":"وبعدما صلبوه تقاسموا ثيابه، مقترعين عليها لمعرفة نصيب كل منهم.","15:25":"وكانت الساعة التاسعة صباحا حينما صلبوه.","15:26":"وكان عنوان تهمته مكتوبا: «ملك اليهود».","15:27":"وصلبوا معه لصين، واحدا عن يمينه، وواحدا عن يساره.","15:28":"فتمت الآية القائلة: «وأحصي مع المجرمين».","15:29":"وكان المارة يشتمونه، وهم يهزون رؤوسهم قائلين: «هه! ياهادم الهيكل وبانيه في ثلاثة أيام،","15:30":"خلص نفسك، وانزل عن الصليب!»","15:31":"كذلك كان رؤساء الكهنة أيضا يسخرون منه مع الكتبة قائلين بعضهم لبعض: «خلص غيره، وأما نفسه فلا يقدر أن يخلص.","15:32":"لينزل الآن المسيح ملك إسرائيل من على الصليب، لنرى ونؤمن!» وعيره أيضا اللصان المصلوبان معه.","15:33":"ولما جاءت الساعة الثانية عشرة ظهرا، حل الظلام على الأرض كلها حتى الساعة الثالثة بعد الظهر.","15:34":"وفي الساعة الثالثة، صرخ يسوع بصوت عظيم: «ألوي ألوي، لما شبقتني؟» أي: «إلهي إلهي، لماذا تركتني؟»","15:35":"فقال بعض الواقفين هناك لما سمعوا ذلك: «ها إنه ينادي إيليا!»","15:36":"وإذا واحد قد ركض وغمس إسفنجة في الخل وثبتها على قصبة وقدمها إليه ليشرب، قائلا: «دعوه! لنر هل يأتي إيليا لينزله! »","15:37":"فصرخ يسوع بصوت عظيم، وأسلم الروح.","15:38":"فانشق ستار الهيكل شطرين من أعلى إلى أسفل.","15:39":"فلما رأى قائد المئة الواقف مقابله أنه صرخ وأسلم الروح، قال: «حقا، كان هذا الإنسان ابن الله!»","15:40":"ومن بعيد كانت نساء كثيرات يراقبن ما يجري، وبينهن مريم المجدلية ومريم أم يعقوب الصغير ويوسى، وسالومة،","15:41":"اللواتي كن يتبعنه ويخدمنه عندما كان في الجليل، وغيرهن كثيرات كن قد صعدن معه إلى أورشليم.","15:42":"وإذ كان المساء قد حل، واليوم يوم الإعداد، أي ما قبل السبت،","15:43":"جاء يوسف الذي من الرامة، وهو عضو محترم في المجلس الأعلى، وكان هو أيضا ينتظر ملكوت الله، فتجرأ ودخل إلى بيلاطس، وطلب جثمان يسوع.","15:44":"فدهش بيلاطس من أنه قد مات، واستدعى قائد المئة واستفسره: هل مات منذ وقت طويل","15:45":"ولما أعلمه قائد المئة بذلك وهب يوسف الجثمان.","15:46":"وإذ اشترى يوسف كتانا وأنزل الجثمان، لفه بالكتان، ودفنه في قبر كان قد نحت في الصخر، ثم دحرج حجرا على باب القبر.","15:47":"وكانت مريم المجدلية ومريم أم يوسي تنظران أين دفن.","16:1":"ولما انتهى السبت، اشترت مريم المجدلية ومريم أم يعقوب وسالومة طيوبا عطرية ليأتين ويدهنه.","16:2":"وفي اليوم الأول من الأسبوع، أتين إلى القبر باكرا جدا مع طلوع الشمس.","16:3":"وكن يقلن بعضهن لبعض: «من يدحرج لنا الحجر من على باب القبر؟»","16:4":"لكنهن تطلعن فرأين أن الحجر قد دحرج، مع أنه كان كبيرا جدا.","16:5":"وإذ دخلن القبر، رأين في الجهة اليمنى شابا جالسا، لابسا ثوبا أبيض، فتملكهن الخوف.","16:6":"فقال لهن: «لا تخفن. أنتن تبحثن عن يسوع الناصري الذي صلب. إنه قام! ليس هو هنا. ها هو المكان الذي كان موضوعا فيه.","16:7":"لكن اذهبن وقلن لتلاميذه، ولبطرس، إنه سيسبقكم إلى الجليل؛ هناك ترونه كما قال لكم».","16:8":"فخرجن هاربات من القبر، وقد استولت عليهن الرعدة والدهشة الشديدة. ولم يقلن شيئا لأحد، لأنهن كن خائفات.","16:9":"وبعدما قام يسوع باكرا في اليوم الأول من الأسبوع، ظهر أولا لمريم المجدلية التي كان قد طرد منها سبعة شياطين.","16:10":"فذهبت وبشرت الذين كانوا معه، وقد كانوا ينوحون ويبكون.","16:11":"فلما سمع هؤلاء أنه حي وأنها قد شاهدته، لم يصدقوا.","16:12":"وبعد ذلك ظهر بهيئة أخرى لاثنين منهم وهما سائران منطلقين إلى إحدى القرى.","16:13":"فذهبا وبشرا الباقين، فلم يصدقوهما أيضا.","16:14":"أخيرا ظهر للأحد عشر تلميذا فيما كانوا متكئين، ووبخهم على عدم إيمانهم وقساوة قلوبهم، لأنهم لم يصدقوا الذين شاهدوه بعد قيامته.","16:15":"وقال لهم: «اذهبوا إلى العالم أجمع، وبشروا الخليقة كلها بالإنجيل:","16:16":"من آمن وتعمد، خلص، ومن لم يؤمن فسوف يدان.","16:17":"وأولئك الذين آمنوا، تلازمهم هذه الآيات: باسمي يطردون الشياطين ويتكلمون بلغات جديدة عليهم،","16:18":"ويقبضون على الحيات، وإن شربوا شرابا قاتلا لا يتأذون البتة، ويضعون أيديهم على المرضى فيتعافون».","16:19":"ثم إن الرب، بعدما كلمهم، رفع إلى السماء، وجلس عن يمين الله.","16:20":"وأما هم، فانطلقوا يبشرون في كل مكان، والرب يعمل معهم ويؤيد الكلمة بالآيات الملازمة لها."},"Luk":{"1:1":"لما كان كثيرون قد أقدموا على تدوين قصة في الأحداث التي تمت بيننا،","1:2":"كما سلمها إلينا أولئك الذين كانوا من البداية شهود عيان، ثم صاروا خداما للكلمة،","1:3":"رأيت أنا أيضا، بعدما تفحصت كل شيء من أول الأمر تفحصا دقيقا، أن أكتبها إليك مرتبة ياصاحب السمو ثاوفيلس","1:4":"لتتأكد لك صحة الكلام الذي تلقيته.","1:5":"كان في زمن هيرودس ملك اليهودية كاهن اسمه زكريا، من فرقة أبيا، وزوجته من نسل هارون، واسمها أليصابات.","1:6":"وكان كلاهما بارين أمام الله، يسلكان وفقا لوصايا الرب وأحكامه كلها بغير لوم.","1:7":"ولكن لم يكن لهما ولد، إذ كانت أليصابات عاقرا وكلاهما قد تقدما في السن كثيرا.","1:8":"وبينما كان زكريا يؤدي خدمته الكهنوتية أمام الله في دور فرقته،","1:9":"وقعت عليه القرعة التي ألقيت حسب عادة الكهنوت ليدخل هيكل الرب ويحرق البخور.","1:10":"وكان جمهور الشعب جميعا يصلون خارجا في وقت إحراق البخور.","1:11":"فظهر له ملاك من عند الرب واقفا عن يمين مذبح البخور.","1:12":"فاضطرب زكريا لما رآه واستولى عليه الخوف.","1:13":"فقال له الملاك: «لا تخف يازكريا، لأن طلبتك قد سمعت، وزوجتك أليصابات ستلد لك ابنا، وأنت تسميه يوحنا،","1:14":"ويكون لك فرح وابتهاج وكثيرون سيفرحون بولادته.","1:15":"وسوف يكون عظيما أمام الرب، ولا يشرب خمرا ولا مسكرا، ويمتليء بالروح القدس وهو بعد في بطن أمه،","1:16":"ويرد كثيرين من بني إسرائيل إلى الرب إلههم،","1:17":"فيتقدم أمامه وله روح إيليا وقدرته، ليرد قلوب الآباء إلى الأولاد، والعصاة إلى حكمة الأبرار، ليهييء للرب شعبا معدا!»","1:18":"فسأل زكريا الملاك: «بم يتأكد لي هذا، فأنا شيخ كبير وزوجتي متقدمة في السن؟»","1:19":"فأجابه الملاك: «أنا جبرائيل، الواقف أمام الله، وقد أرسلت لأكلمك وأبشرك بهذا.","1:20":"وها أنت ستبقى صامتا لا تستطيع الكلام، إلى اليوم الذي يحدث فيه هذا، لأنك لم تصدق كلامي، وهو سيتم في حينه».","1:21":"وكان الشعب منتظرين زكريا، وهم متعجبون من تأخره داخل الهيكل.","1:22":"ولكنه لما خرج لم يقدر أن يكلمهم، فأدركوا أنه رأى رؤيا داخل الهيكل. فأخذ يشير لهم وظل أخرس.","1:23":"ولما أتم أيام خدمته، رجع إلى بيته.","1:24":"وبعد تلك الأيام، حبلت أليصابات زوجته، فكتمت أمرها خمسة أشهر، قائلة:","1:25":"«هكذا فعل الرب بي، في الأيام التي فيها نظر إلي لينزع عني العار من بين الناس! »","1:26":"وفي شهرها السادس، أرسل الملاك جبر ائيل من قبل الله إلى مدينة بالجليل اسمها الناصرة،","1:27":"إلى عذراء مخطوبة لرجل اسمه يوسف، من بيت داود، واسم العذراء مريم.","1:28":"فدخل الملاك وقال لها: «سلام، أيتها المنعم عليها! الرب معك: مباركة أنت بين النساء».","1:29":"فاضطربت لكلام الملاك، وساءلت نفسها: «ما عسى أن تكون هذه التحية!»","1:30":"فقال لها الملاك: «لا تخافي يامريم، فإنك قد نلت نعمة عند الله!","1:31":"وها أنت ستحبلين وتلدين ابنا، وتسمينه يسوع.","1:32":"إنه يكون عظيما، وابن العلي يدعى، ويمنحه الرب الإله عرش داود أبيه،","1:33":"فيملك على بيت يعقوب إلى الأبد، ولن يكون لملكه نهاية».","1:34":"فقالت مريم للملاك: «كيف يحدث هذا، وأنا لست أعرف رجلا؟»","1:35":"فأجابها الملاك: «الروح القدس يحل عليك، وقدرة العلي تظللك. لذلك أيضا فالقدوس المولود منك يدعى ابن الله.","1:36":"وها هي نسيبتك أليصابات أيضا قد حبلت بابن في سنها المتقدمة. وهذا هو الشهر السادس لتلك التي كانت تدعى عاقرا.","1:37":"فليس لدى الله وعد يستحيل عليه إتمامه».","1:38":"فقالت مريم: «ها أنا عبدة الرب. ليكن لي كما تقول!» ثم انصرف الملاك من عندها.","1:39":"وفي تلك الأيام، قامت مريم وذهبت مسرعة إلى الجبال، قاصدة إلى مدينة من مدن يهوذا.","1:40":"فدخلت بيت زكريا وسلمت على أليصابات.","1:41":"ولما سمعت أليصابات سلام مريم، قفز الجنين داخل بطنها. وامتلأت أليصابات من الروح القدس،","1:42":"وهتفت بصوت عال قائلة: «مباركة أنت بين النساء! ومباركة ثمرة بطنك!","1:43":"فمن أين لي هذا: أن تأتي إلي أم ربي؟","1:44":"فإنه ما إن وقع صوت سلامك في أذني حتى قفز الجنين ابتهاجا في بطني:","1:45":"فطوبى للتي آمنت أنه سيتم ما قيل لها من قبل الرب! »","1:46":"فقالت مريم: «تعظم نفسي الرب،","1:47":"وتبتهج روحي بالله مخلصي.","1:48":"فإنه نظر إلى تواضع أمته، وها إن جميع الأجيال من الآن فصاعدا سوف تطوبني.","1:49":"فإن القدير قد فعل بي أمورا عظيمة، قدوس اسمه،","1:50":"ورحمته للذين يتقونه جيلا بعد جيل.","1:51":"عمل بذراعه قوة؛ شتت المتكبرين في نيات قلوبهم.","1:52":"أنزل المقتدرين عن عروشهم، ورفع المتواضعين.","1:53":"أشبع الجياع خيرات، وصرف الأغنياء فارغين.","1:54":"أعان إسرائيل فتاه، متذكرا الرحمة،","1:55":"كما تكلم إلى آبائنا، لإبراهيم ونسله إلى الأبد».","1:56":"وأقامت مريم عند أليصابات نحو ثلاثة أشهر، ثم رجعت إلى بيتها.","1:57":"وأما أليصابات فتم زمانها لتلد فولدت ابنا.","1:58":"وسمع جيرانها وأقاربها أن الرب أفاض رحمته عليها، ففرحوا معها.","1:59":"وفي اليوم الثامن حضروا ليختنوا الصبي، وكادوا يسمونه زكريا على اسم أبيه.","1:60":"ولكن أمه قالت: «لا، بل يسمى يوحنا!»","1:61":"فقالوا لها: «ليس في عشيرتك أحد تسمى بهذا الاسم».","1:62":"وأشاروا لأبيه، ماذا يريد أن يسمى.","1:63":"فطلب لوحا وكتب فيه: «اسمه يوحنا». فتعجبوا جميعا.","1:64":"وانفتح فم زكريا في الحال وانطلق لسانه، فتكلم مباركا الله .","1:65":"فاستولى الخوف على جميع الساكنين في جوارهم، وصارت هذه الأمور موضوع الحديث في جبال اليهودية كلها.","1:66":"وكان جميع السامعين يضعونها في قلوبهم، قائلين: «ترى، ماذا سيصير هذا الطفل؟» فقد كانت يد الرب معه.","1:67":"وامتلأ زكريا أبوه من الروح القدس، فتنبأ قائلا:","1:68":"«تبارك الرب إله إسرائيل، لأنه تفقد شعبه وعمل له فداء،","1:69":"وأقام لنا قرن خلاص في بيت داود فتاه،","1:70":"كما تكلم بلسان أنبيائه القديسين الذين جاءوا منذ القديم:","1:71":"خلاص من أعدائنا ومن أيدي جميع مبغضينا،","1:72":"ليتم الرحمة نحو آبائنا ويتذكر عهده المقدس","1:73":"ذلك القسم الذي أقسم لإبراهيم أبينا: بأن يمنحنا،","1:74":"بعد تخليصنا من أيدي أعدائنا، أن نعبده بلا خوف،","1:75":"بقداسة وبر أمامه، طوال حياتنا.","1:76":"وأنت، أيها الطفل، سوف تدعى نبي العلي، لأنك ستتقدم أمام الرب لتعد طرقه،","1:77":"لتعطي شعبه المعرفة بأن الخلاص هو بمغفرة خطاياهم","1:78":"بفضل عواطف الرحمة لدى إلهنا، تلك التي تفقدنا بها الفجر المشرق من العلاء،","1:79":"ليضيء على القابعين في الظلام وظل الموت، ويهدي خطانا في طريق السلام».","1:80":"وكان الطفل ينمو ويتقوى بالروح؛ وأقام في البراري إلى يوم ظهوره لإسرائيل.","2:1":"وفي ذلك الزمان، أصدر القيصر أغسطس مرسوما يقضي بإحصاء سكان الإمبراطورية.","2:2":"وقد تم هذا الإحصاء الأول عندما كان كيرينيوس حاكما لسورية.","2:3":"فذهب الجميع ليسجلوا، كل واحد إلى بلدته.","2:4":"وصعد يوسف أيضا من مدينة الناصرة بمنطقة الجليل إلى مدينة داود المدعوة بيت لحم بمنطقة اليهودية، لأنه كان من بيت داود وعشيرته،","2:5":"ليتسجل هناك مع مريم المخطوبة له، وهي حبلى.","2:6":"وبينما كانا هناك، تم زمانها لتلد،","2:7":"فولدت ابنها البكر، ولفته بقماط، وأنامته في مذود، إذ لم يكن لهما متسع في المنزل.","2:8":"وكان في تلك المنطقة رعاة يبيتون في العراء، يتناوبون حراسة قطيعهم في الليل.","2:9":"وإذا ملاك من عند الرب قد ظهر لهم، ومجد الرب أضاء حولهم، فخافوا أشد الخوف.","2:10":"فقال لهم الملاك: «لا تخافوا! فها أنا أبشركم بفرح عظيم يعم الشعب كله:","2:11":"فقد ولد لكم اليوم في مدينة داود مخلص هو المسيح الرب.","2:12":"وهذه هي العلامة لكم. تجدون طفلا ملفوفا بقماط ونائما في مذود».","2:13":"وفجأة ظهر مع الملاك جمهور من الجند السماوي، يسبحون الله قائلين:","2:14":"«المجد لله في الأعالي، وعلى الأرض السلام؛ وبالناس المسرة! »","2:15":"ولما انصرف الملائكة عن الرعاة إلى السماء، قال بعضهم لبعض: «لنذهب إذن إلى بيت لحم، وننظر هذا الأمر الذي حدث وقد أعلمنا به الرب!»","2:16":"وجاءوا مسرعين، فوجدوا مريم ويوسف، والطفل نائما في المذود.","2:17":"فلما رأوا ذلك، أخذوا يخبرون بما قيل لهم بخصوص هذا الطفل.","2:18":"وجميع الذين سمعوا بذلك دهشوا مما قاله لهم الرعاة.","2:19":"وأما مريم، فكانت تحفظ هذه الأمور جميعا، وتتأملها في قلبها.","2:20":"ثم رجع الرعاة يمجدون الله ويسبحونه على كل ما سمعوه ورأوه كما قيل لهم.","2:21":"ولما تمت ثمانية أيام ليختن الطفل، سمي يسوع، كما كان قد سمي بلسان الملاك قبل أن يحبل به في البطن.","2:22":"ثم لما تمت الأيام لتطهيرها حسب شريعة موسى، صعدا به إلى أورشليم ليقدماه إلى الرب،","2:23":"كما كتب في شريعة الرب: «كل بكر من الذكور يدعى قدسا للرب»،","2:24":"وليقدما ذبيحة كما يوصى في شريعة الرب: «زوجي يمام، أو فرخي حمام».","2:25":"وكان في أورشليم رجل اسمه سمعان، وهو رجل بار تقي ينتظر العزاء لإسرائيل وكان الروح القدس عليه.","2:26":"وكان الروح القدس قد أوحى إليه أنه لا يرى الموت قبل أن يرى مسيح الرب،","2:27":"وقد جاء إلى الهيكل بدافع من الروح. فلما أحضر الأبوان الطفل يسوع ليقدما عنه ما سن في الشريعة،","2:28":"حمله على ذراعيه وبارك الله ، وقال:","2:29":"«أيها السيد، الآن تطلق عبدك بسلام حسب وعدك!","2:30":"فإن عيني قد أبصرتا خلاصك","2:31":"الذي هيأته لتقدمه إلى الشعوب كلها،","2:32":"نور هداية للأمم ومجدا لشعبك إسر ائيل».","2:33":"وكان أبوه وأمه يتعجبان من هذا الكلام الذي قيل فيه.","2:34":"فباركهما سمعان، وقال لمريم أم الطفل: «ها إن هذا الطفل قد جعل لسقوط كثيرين وقيام كثيرين في إسرائيل، وآية تقاوم","2:35":"حتى أنت سيخترق نفسك سيف لكي تنكشف نيات قلوب كثيرة! »","2:36":"وكانت هناك نبية، هي حنة بنت فنوئيل من سبط أشير، وهي متقدمة في السن، وكانت قد عاشت مع زوجها سبع سنين بعد عذراويتها،","2:37":"وهي أرملة نحو أربع وثمانين سنة. لم تكن تفارق الهيكل وكانت تتعبد ليلا ونهارا بالصوم والدعاء.","2:38":"فإذ حضرت في تلك الساعة، أخذت تسبح الرب وتتحدث عن يسوع مع جميع الذين كانوا ينتظرون فداء في أورشليم.","2:39":"وبعد إتمام كل ما تقتضيه شريعة الرب، رجعوا إلى مدينتهم الناصرة بالجليل.","2:40":"وكان الطفل ينمو ويتقوى، ممتلئا حكمة، وكانت نعمة الله عليه.","2:41":"وكان أبواه يذهبان كل سنة إلى أورشليم في عيد الفصح.","2:42":"فلما بلغ سن الثانية عشرة، صعدوا إلى أورشليم كالعادة في العيد.","2:43":"وبعد انتهاء أيام العيد، رجعا، وبقي الصبي يسوع في أورشليم، وهما لا يعلمان.","2:44":"ولكنهما إذ ظناه بين الرفاق، سارا مسيرة يوم واحد ثم أخذا يبحثان عنه بين الأقارب والمعارف.","2:45":"ولما لم يجداه، رجعا إلى أورشليم يبحثان عنه.","2:46":"وبعد ثلاثة أيام وجداه في الهيكل، جالسا وسط المعلمين يستمع إليهم ويطرح عليهم الأسئلة.","2:47":"وجميع الذين سمعوه ذهلوا من فهمه وأجوبته.","2:48":"فلما رأياه دهشا، وقالت له أمه: «يابني، لماذا عملت بنا هكذا؟ فقد كنا، أبوك وأنا، نبحث عنك متضايقين!»","2:49":"فأجابهما: «لماذا كنتما تبحثان عني؟ ألم تعلما أن علي أن أكون في ما يخص أبي؟»","2:50":"فلم يفهما ما قاله لهما.","2:51":"ثم نزل معهما ورجع إلى الناصرة، وكان خاضعا لهما. وكانت أمه تحفظ هذه الأمور كلها في قلبها.","2:52":"أما يسوع، فكان يتقدم في الحكمة والقامة، وفي النعمة عند الله والناس.","3:1":"وفي السنة الخامسة عشرة من ملك القيصر طيباريوس؛ حين كان بيلاطس البنطي حاكما على منطقة اليهودية، وهيرودس حاكم ربع على الجليل وأخوه فيلبس حاكم ربع على إيطورية وإقليم تراخونيتس، وليسانيوس حاكم ربع على الأبلية؛","3:2":"في زمان رئاسة حنان وقيافا للكهنة؛ كانت كلمة الله على يوحنا بن زكريا وهو في البرية.","3:3":"فانطلق إلى جميع النواحي المحيطة بنهر الأردن ينادي بمعمودية التوبة لمغفرة الخطايا،","3:4":"كما كتب في كتاب أقوال النبي إشعياء: «صوت مناد في البرية: أعدوا طريق الرب واجعلوا سبله مستقيمة.","3:5":"كل واد سيردم، وكل جبل وتل سيخفض، وتصير الأماكن الملتوية مستقيمة والأماكن الوعرة طرقا مستوية،","3:6":"فيبصر كل بشر الخلاص الإلهي! »","3:7":"فقد كان يقول للجموع الذين خرجوا إليه ليتعمدوا على يده: «ياأولاد الأفاعي، من أنذركم لتهربوا من الغضب الآتي؟","3:8":"فأثمروا أثمارا تليق بالتوبة، ولا تبتدئوا تقولون في أنفسكم: لنا إبراهيم أبا! فإني أقول لكم إن الله قادر أن يطلع من هذه الحجارة أولادا لإبراهيم.","3:9":"وها إن الفأس أيضا قد وضعت على أصل الشجر: فكل شجرة لا تثمر ثمرا جيدا تقطع وتطرح في النار».","3:10":"وسألته الجموع: «فماذا نفعل إذن؟»","3:11":"فأجابهم: «من كان عنده ثوبان، فليعط من لا ثوب عنده؛ ومن كان عنده طعام، فليعمل كذلك أيضا».","3:12":"وجاء أيضا جباة ضرائب ليتعمدوا، فسألوه: «يامعلم، ماذا نفعل؟»","3:13":"فقال لهم: «لا تجبوا أكثر مما فرض لكم».","3:14":"وسأله أيضا بعض الجنود: «ونحن، ماذا نفعل؟» فأجابهم: «لا تظلموا أحدا ولا تشتكوا كذبا على أحد، واقنعوا بمرتباتكم! »","3:15":"وإذ كان الشعب منتظرين (المسيح)، والجميع يسائلون أنفسهم عن يوحنا: «هل هو المسيح؟»","3:16":"أجاب يوحنا الجميع قائلا: «أنا أعمدكم بالماء، ولكن سيأتي من هو أقدر مني، من لا أستحق أن أحل رباط حذائه: هو سيعمدكم بالروح القدس، وبالنار.","3:17":"فهو يحمل المذرى بيده لينقي بيدره تماما، فيجمع القمح إلى مخزنه، وأما التبن فيحرقه بنار لا تطفأ».","3:18":"وكان يبشر الشعب ويعظهم بأشياء أخرى كثيرة.","3:19":"ولكن هيرودس حاكم الربع، إذ كان يوحنا قد وبخه بسبب هيروديا زوجة أخيه وبسبب جميع ما ارتكبه من الشرور،","3:20":"أضاف إلى شروره السابقة هذا الشر: أنه حبس يوحنا في السجن.","3:21":"ولما تعمد الشعب جميعا، تعمد يسوع، وإذ كان يصلي، انفتحت السماء،","3:22":"وهبط عليه الروح القدس متخذا هيئة جسمية مثل حمامة، وانطلق صوت من السماء يقول: «أنت ابني الحبيب بك سررت كل سرور! »","3:23":"ولما بدأ يسوع (خدمته)، كان في الثلاثين من العمر تقريبا، وكان معروفا أنه ابن يوسف بن هالي،","3:24":"بن متثات بن لاوي، بن ملكي بن ينا، بن يوسف","3:25":"بن متاثيا، بن عاموص بن ناحوم، بن حسلي بن نجاي،","3:26":"بن مآث بن متاثيا، بن شمعي بن يوسف، بن يهوذا","3:27":"بن يوحنا، بن ريسا بن زربابل، بن شألتئيل بن نيري،","3:28":"بن ملكي بن أدي، بن قصم بن ألمودام، بن عير","3:29":"بن يوسي، بن أليعازر بن يوريم، بن متثات بن لاوي،","3:30":"بن شمعون بن يهوذا، بن يوسف بن يونان، بن ألياقيم","3:31":"بن مليا بن مينان، بن متاثا بن ناثان، بن داود","3:32":"بن يسى، بن عوبيد بن بوعز، بن سلمون بن نحشون،","3:33":"بن عميناداب بن أرام بن حصرون، بن فارص بن يهوذا،","3:34":"بن يعقوب بن إسحاق، بن إبراهيم بن تارح، بن ناحور","3:35":"بن سروج، بن رعو بن فالج، بن عابر بن شالح،","3:36":"بن قينان بن أرفكشاد، بن سام بن نوح، بن لامك","3:37":"بن متوشالح، بن أخنوخ بن يارد، بن مهللئيل بن قينان،","3:38":"بن أنوش بن شيث، بن آدم ابن الله.","4:1":"أما يسوع، فعاد من الأردن ممتلئا من الروح القدس. فاقتاده الروح في البرية","4:2":"أربعين يوما، وإبليس يجربه، ولم يأكل شيئا طوال تلك الأيام. فلما تمت، جاع.","4:3":"فقال له إبليس: «إن كنت ابن الله، فقل لهذا الحجر أن يتحول إلى خبز».","4:4":"فرد عليه يسوع قائلا: «قد كتب: ليس بالخبز وحده يحيا الإنسان، بل بكل كلمة من الله!»","4:5":"ثم أصعده إبليس إلى جبل عال، وأراه ممالك العالم كلها في لحظة من الزمن،","4:6":"وقال له: «أعطيك السلطة على هذه الممالك كلها وما فيها من عظمة، فإنها قد سلمت إلى وأنا أعطيها لمن أشاء.","4:7":"فإن سجدت أمامي، تصير كلها لك!»","4:8":"فر د عليه يسوع قائلا: «قد كتب: للرب إلهك تسجد، وإياه وحده تعبد!»","4:9":"ثم اقتاده إبليس إلى أورشليم، وأوقفه على حافة سطح الهيكل، وقال له: «إن كنت ابن الله، فاطرح نفسك من هنا إلى الأسفل","4:10":"فإنه قد كتب: يوصي ملائكته بك لكي يحفظوك،","4:11":"فعلى أيديهم يحملونك، لئلا تصدم قدمك بحجر».","4:12":"فرد عليه يسوع قائلا: «قد قيل: لا تجرب الرب إلهك!»","4:13":"وبعدما أكمل إبليس كل تجربة، انصرف عن يسوع إلى أن يحين الوقت.","4:14":"وعاد يسوع إلى منطقة الجليل بقدرة الروح؛ وذاع صيته في القرى المجاورة كلها.","4:15":"وكان يعلم في مجامع اليهود، والجميع يمجدونه.","4:16":"وجاء إلى الناصرة حيث كان قد نشأ، ودخل المجمع، كعادته، يوم السبت، ووقف ليقرأ.","4:17":"فقدم إليه كتاب النبي إشعياء، فلما فتحه وجد المكان الذي كتب فيه:","4:18":"«روح الرب علي، لأنه مسحني لأبشر الفقراء؛ أرسلني لأنادي للمأسورين بالإطلاق وللعميان بالبصر، لأطلق المسحوقين أحرارا،","4:19":"وأبشر بسنة القبول عند الرب».","4:20":"ثم طوى الكتاب وسلمه إلى الخادم، وجلس. وكانت عيون جميع الحاضرين في المجمع شاخصة إليه.","4:21":"فأخذ يخاطبهم قائلا: «اليوم تم ما قد سمعتم من آيات...»","4:22":"وشهد له جميع الحاضرين، متعجبين من كلام النعمة الخارج من فمه، وتساءلوا: «أليس هذا ابن يوسف؟»","4:23":"فقال لهم: «لا شك أنكم تقولون لي هذا المثل: أيها الطبيب اشف نفسك! فاصنع هنا في بلدتك ما سمعنا أنه جرى في كفرناحوم...»","4:24":"ثم أضاف: «الحق أقول لكم: ما من نبي يقبل في بلدته.","4:25":"وبالحقيقة أقول لكم: كان في إسرائيل أرامل كثيرات في زمان إيليا، حين أغلقت السماء ثلاث سنين وستة أشهر، حتى حدثت مجاعة عظيمة في الأرض كلها؛","4:26":"ولكن إيليا لم يرسل إلى أية واحدة منهن بل إلى امرأة أرملة في صرفة صيدا.","4:27":"وكان في إسرائيل، في زمان النبي أليشع، كثيرون مصابون بالبرص؛ ولكن لم يطهر أي واحد منهم، بل نعمان السوري!»","4:28":"فامتلأ جميع من في المجمع غضبا لما سمعوا هذه الأمور،","4:29":"وقاموا يدفعونه إلى خارج المدينة وساقوه إلى حافة الجبل الذي بنيت عليه مدينتهم ليطرحوه إلى الأسفل.","4:30":"إلا أنه اجتاز من وسطهم، وانصرف.","4:31":"ونزل إلى كفرناحوم، وهي مدينة بمنطقة الجليل، وأخذ يعلم الشعب أيام السبت.","4:32":"فذهلوا من تعليمه، لأن كلمته كانت ذات سلطة.","4:33":"وكان في المجمع رجل يسكنه روح شيطان نجس. فصرخ بصوت عال:","4:34":"«آه! ما شأنك بنا يايسوع الناصري؟ أجئت لتهلكنا؟ أنا أعرف من أنت: أنت قدوس الله».","4:35":"فزجره يسوع قائلا: «اخرس، واخرج منه». وإذ طرحه الشيطان في الوسط، خرج منه ولم يصبه بأذى.","4:36":"فاستولت الدهشة على الجميع، وأخذوا يتساءلون في ما بينهم: «أي كلمة هي هذه؟ فإنه بسلطان وقدرة يأمر الأرواح النجسة فتخرج!»","4:37":"وذاع صيته في كل مكان من المنطقة المجاورة.","4:38":"ثم غادر المجمع، ودخل بيت سمعان. وكانت حماة سمعان تعاني حمى شديدة، فطلبوا إليه إعانتها.","4:39":"فوقف بجانب فراشها، وزجر الحمى، فذهبت عنها. فوقفت في الحال وأخذت تخدمهم.","4:40":"ولما غربت الشمس، أخذ جميع الذين كان عندهم مرضى مصابون بعلل مختلفة يحضرونهم إليه، فوضع يديه على كل واحد منهم، وشفاهم.","4:41":"وخرجت أيضا شياطين من كثيرين، وهي تصرخ قائلة: «أنت ابن الله!» فكان يزجرهم ولا يدعهم يتكلمون، إذ عرفوا أنه المسيح.","4:42":"ولما طلع النهار، خرج وذهب إلى مكان مقفر. فبحثت الجموع عنه حتى وجدوه، وتمسكوا به لئلا يرحل عنهم.","4:43":"ولكنه قال لهم: «لابد لي من أن أبشر المدن الأخرى أيضا بملكوت الله، لأني لهذا قد أرسلت».","4:44":"ومضى يبشر في مجامع اليهودية.","5:1":"وبينما كان الجمع محتشدين حوله ليسمعوا كلمة الله، كان هو واقفا على شاطيء بحيرة جنيسارت.","5:2":"فرأى قاربين راسيين على جانب البحيرة وقد غادرهما الصيادون، وكانوا يغسلون الشباك.","5:3":"فركب أحد القاربين، وكان لسمعان، وطلب إليه أن يبتعد قليلا عن البر، ثم جلس يعلم الجموع من القارب.","5:4":"ولما أنهى كلامه، قال لسمعان: «ابتعد إلى حيث العمق، واطرحوا شباككم للصيد».","5:5":"فأجابه سمعان: «ياسيد قد جاهدنا طوال الليل ولم نصد شيئا. ولكن لأجل كلمتك سأطرح الشباك !»","5:6":"ولما فعلوا ذلك، صادوا سمكا كثيرا جدا، حتى تخرقت شباكهم.","5:7":"فأشاروا إلى شركائهم الذين في القارب الآخر أن يأتوا ويساعدوهم. فأتوا، وملأوا القاربين كليهما حتى كادا يغرقان.","5:8":"ولكن لما رأى سمعان بطرس ذلك، جثا عند ركبتي يسوع وقال: «اخرج من قاربي يارب، لأني إنسان خاطيء».","5:9":"فقد استولت الدهشة عليه وعلى جميع الذين كانوا معه، لكثرة الصيد الذي صادوه،","5:10":"وكذلك على يعقوب ويوحنا ابني زبدي اللذين كانا شريكين لسمعان. وقال يسوع لسمعان: «لا تخف! منذ الآن تكون صائدا للناس».","5:11":"وبعدما رجعوا بالقاربين إلى البر، تركوا كل شيء وتبعوا يسوع.","5:12":"وإذ كان يسوع في إحدى المدن، إذا إنسان يغطي البرص جسمه، ما إن رأى يسوع حتى خر على وجهه وتوسل إليه قائلا: «ياسيد، إن شئت فأنت قادر أن تطهرني!»","5:13":"فمد يسوع يده ولمسه قائلا: «إني أريد، فاطهر!» وفي الحال زال عنه البرص.","5:14":"فأوصاه: «لا تخبر أحدا، بل اذهب واعرض نفسك على الكاهن، وقدم لقاء تطهيرك ما أمر به موسى، فيكون ذلك شهادة لهم».","5:15":"على أن خبر يسوع زاد انتشارا، حتى توافدت إليه جموع كثيرة ليستمعوا إليه وينالوا الشفاء من أمراضهم.","5:16":"أما هو، فكان ينسحب إلى الأماكن المقفرة حيث يصلي.","5:17":"وفي ذات يوم، كان يعلم، وكان بين الجالسين بعض الفريسيين ومعلمي الشريعة، وقد أتوا من كل قرية في الجليل واليهودية، ومن أورشليم. وظهرت قدرة الرب لتشفيهم.","5:18":"وإذا بعضهم يحملون على فراش إنسانا مشلولا، حاولوا أن يدخلوا به ويضعوه أمامه.","5:19":"ولما لم يجدوا طريقا لإدخاله بسبب الزحام، صعدوا به إلى السطح ودلوه من بين اللبن على فراشه إلى الوسط قدام يسوع.","5:20":"فلما رأى إيمانهم، قال: «أيها الإنسان، قد غفرت لك خطاياك!»","5:21":"فأخذ الكتبة والفريسيون يفكرون قائلين: «من هذا الذي ينطق بكلام التجديف؟ من يقدر أن يغفر الخطايا إلا الله وحده؟»","5:22":"ولكن يسوع أدرك ما يفكرون فيه، فأجابهم قائلا: «فيم تفكرون في قلوبكم؟","5:23":"أي الأمرين أسهل: أن أقول: قد غفرت لك خطاياك! أم أن أقول: قم وامش؟","5:24":"ولكني (قلت ذلك) لكي تعلموا أن لابن الإنسان على الأرض سلطة غفران الخطايا...» وقال للمشلول: «لك أقول: قم احمل فراشك، واذهب إلى بيتك».","5:25":"وفي الحال قام أمامهم وذهب إلى بيته ممجدا الله ، وقد حمل ما كان راقدا عليه.","5:26":"فأخذت الحيرة الجميع، ومجدوا الله؛ وقد تملكهم الخوف، وقالوا: «رأينا اليوم عجائب! »","5:27":"وخرج بعد ذلك فرأى جابي ضرائب، اسمه لاوي، جالسا في مكتب الجباية، فقال له: «اتبعني!»","5:28":"فقام لاوي وتبعه تاركا كل شيء.","5:29":"وأقام له وليمة عظيمة في بيته، وكان متكئا معهم جمع كبير من الجباة وغيرهم.","5:30":"فتذمر كتبة اليهود والفريسيون على تلاميذه، قائلين: «لماذا تأكلون وتشربون مع جباة ضرائب وخاطئين؟»","5:31":"فرد عليهم يسوع قائلا: «ليس الأصحاء هم المحتاجين إلى الطبيب، بل المرضى!","5:32":"ما جئت لأدعو إلى التوبة أبرارا بل خاطئين! »","5:33":"وقالوا له: «إن تلاميذ يوحنا يصومون كثيرا ويرفعون الطلبات، وكذلك يفعل أيضا تلاميذ الفريسيين؛ وأما تلاميذك فيأكلون ويشر بون!»","5:34":"فقال لهم: «هل تقدرون أن تجعلوا أهل العرس يصومون مادام العريس بينهم؟","5:35":"ولكن أياما ستأتي يكون العريس فيها قد رفع من بينهم، فحينئذ، في تلك الأيام، يصومون».","5:36":"وضرب لهم أيضا مثلا: «لا أحد ينتزع قطعة من ثوب جديد ليرقع بها ثوبا عتيقا، وإلا فإنه يمزق الجديد، والرقعة المأخوذة من الجديد لا توافق العتيق.","5:37":"ولا أحد يضع خمرا جديدة في قرب عتيقة، وإلا، فإن الخمر الجديدة تفجر القرب، فتراق الخمر وتتلف القرب.","5:38":"وإنما يجب أن توضع الخمر الجديدة في قرب جديدة.","5:39":"وما من أحد إذا شرب الخمر العتيقة، يرغب في الجديدة، لأنه يقول: العتيقة أطيب! »","6:1":"وذات سبت مر يسوع بين الحقول، فأخذ تلاميذه يقطفون سنابل القمح ويفركونها بأيديهم ثم يأكلون.","6:2":"ولكن بعض الفريسيين قالوا لهم: «لماذا تفعلون ما لا يحل فعله في السبت؟»","6:3":"فرد عليهم يسوع قائلا: «أما قرأتم ما فعله داود حينما جاع مع مرافقيه؟","6:4":"كيف دخل بيت الله وأخذ خبز التقدمة وأكل منه، وأعطى مرافقيه، مع أن الأكل من هذا الخبز لا يحل إلا للكهنة وحدهم؟»","6:5":"ثم قال لهم: «إن ابن الإنسان هو رب السبت! »","6:6":"وفي سبت آخر، دخل المجمع وأخذ يعلم. وكان هنالك رجل يده اليمنى يابسة.","6:7":"فأخذ الكتبة والفريسيون يراقبون يسوع: هل يشفي في السبت، لكي يجدوا ما يتهمونه به.","6:8":"إلا أنه علم نياتهم، وقال للرجل الذي يده يابسة: «قم، وقف في الوسط!» فقام، ووقف هناك.","6:9":"فقال لهم يسوع: «أسألكم سؤالا: أيحل في السبت فعل الخير أم فعل الشر؟ تخليص النفس أو إهلاكها؟»","6:10":"وبعدما أدار نظره فيهم جميعا، قال له: «مد يدك!» فمد يده، فعادت يده صحيحة.","6:11":"ولكن الحماقة استولت عليهم حتى أخذوا يتشاورون في ما بينهم ماذا يفعلون بيسوع.","6:12":"وفي تلك الأيام، خرج إلى الجبل ليصلي، وقضى الليل كله في الصلاة لله.","6:13":"ولما طلع النهار، استدعى تلاميذه، واختار منهم اثني عشر سماهم أيضا رسلا.","6:14":"وهم: سمعان، وقد سماه أيضا بطرس، وأندراوس أخوه؛ يعقوب، ويوحنا؛ فيلبس، وبرثلماوس؛","6:15":"متى، وتوما؛ يعقوب بن حلفى، وسمعان المعروف بالغيور؛","6:16":"يهوذا أخو يعقوب، ويهوذا الإسخريوطي الذي خانه في ما بعد.","6:17":"ثم نزل معهم، ووقف في مكان سهل، هو وجماعة من تلاميذه، وجمهور كبير من الشعب، من جميع اليهودية وأورشليم وساحل صور وصيدا،","6:18":"جاءوا ليسمعوه وينالوا الشفاء من أمراضهم. والذين كانت تعذبهم الأرواح النجسة كانوا يشفون.","6:19":"وكان الجمع كله يسعون إلى لمسه، لأن قدرة كانت تخرج منه وتشفيهم جميعا.","6:20":"ثم رفع عينيه إلى تلاميذه وقال: «طوبى لكم أيها المساكين، فإن لكم ملكوت الله!","6:21":"طوبى لكم أيها الجائعون الآن، فإنكم سوف تشبعون. طوبى لكم أيها الباكون الآن، فإنكم سوف تضحكون.","6:22":"طوبى لكم متى أبغضكم الناس، وعزلوكم، وأهانوا اسمكم ونبذوه كأنه شرير، من أجل ابن الإنسان.","6:23":"افرحوا في ذلك اليوم وتهللوا، فها إن مكافأتكم في السماء عظيمة: لأنه هكذا عامل آباؤهم الأنبياء.","6:24":"«ولكن الويل لكم أنتم الأغنياء، فإنكم قد نلتم عزاءكم!","6:25":"الويل لكم أيها المشبعون الآن، فإنكم سوف تجوعون. الويل لكم أيها الضاحكون الآن، فإنكم سوف تنوحون وتبكون.","6:26":"الويل لكم إذا امتدحكم جميع الناس، فإنه هكذا عامل آباؤهم الأنبياء الدجالين.","6:27":"«وأما لكم أيها السامعون، فأقول: أحبوا أعداءكم؛ أحسنوا معاملة الذين يبغضونكم؛","6:28":"باركوا لاعنيكم؛ صلوا لأجل الذين يسيئون إليكم.","6:29":"ومن ضربك على خدك، فاعرض له الخد الآخر أيضا. ومن انتزع رداءك، فلا تمنع عنه ثوبك أيضا.","6:30":"أي من طلب منك شيئا فأعطه؛ ومن اغتصب مالك، فلا تطالبه.","6:31":"وبمثل ما تريدون أن يعاملكم الناس عاملوهم أنتم أيضا.","6:32":"فإن أحببتم الذين يحبونكم، فأي فضل لكم؟ فحتى الخاطئون يحبون الذين يحبونهم!","6:33":"وإن أحسنتم معاملة الذين يحسنون معاملتكم، فأي فضل لكم؟ فحتى الخاطئون يفعلون هكذا!","6:34":"وإن أقرضتم الذين تأملون أن تستوفوا منهم، فأي فضل لكم؟ فحتى الخاطئون يقرضون الخاطئين لكي يستوفوا منهم ما يساوي قرضهم.","6:35":"ولكن، أحبوا أعداءكم، وأحسنوا المعاملة، وأقرضوا دون أن تأملوا استيفاء القرض، فتكون مكافأتكم عظيمة، وتكونوا أبناء العلي، لأنه ينعم على ناكري الجميل والأشرار.","6:36":"فكونوا أنتم رحماء، كما أن أباكم رحيم.","6:37":"ولا تدينوا، فلا تدانوا. لا تحكموا على أحد، فلا يحكم عليكم. اغفروا، يغفر لكم.","6:38":"أعطوا، تعطوا: فإنكم تعطون في أحضانكم كيلا جيدا ملبدا مهزوزا فائضا، لأنه بالكيل الذي به تكيلون، يكال لكم».","6:39":"وأخذ يضرب لهم المثل، فقال: «هل يقدر الأعمى أن يقود أعمى؟ ألا يسقطان معا في حفرة؟","6:40":"ليس التلميذ أرفع من معلمه، بل كل من يتكمل يصير مثل معلمه!","6:41":"ولماذا تلاحظ القشة في عين أخيك، ولكنك لا تتنبه إلى الخشبة الكبيرة في عينك؟","6:42":"أو كيف تقدر أن تقول لأخيك: ياأخي، دعني أخرج القشة التي في عينك! وأنت لا تلاحظ الخشبة التي في عينك أنت. يامرائي، أخرج أولا الخشبة من عينك، وعندئذ تبصر جيدا لتخرج القشة التي في عين أخيك.","6:43":"فإنه ما من شجرة جيدة تنتج ثمرا رديئا، ولا شجرة رديئة تنتج ثمرا جيدا:","6:44":"لأن كل شجرة تعرف من ثمرها. فلا يجنى من الشوك تين، ولا يقطف من العليق عنب.","6:45":"إن الإنسان الصالح، من كنزه الصالح في قلبه يطلع ما هو صالح. أما الشرير، فمن كنزه الشرير يطلع ما هو شرير: لأنه من فيض القلب يتكلم فمه.","6:46":"ولماذا تدعونني: يارب، يارب! ولا تعملون بما أقوله؟","6:47":"كل من يأتي إلي، فيسمع كلامي ويعمل به، أريكم من يشبه.","6:48":"إنه يشبه إنسانا يبني بيتا، فحفر وعمق ووضع الأساس على الصخر. ثم هطل مطر غزير وصدم السيل ذلك البيت، فلم يقدر أن يزعزعه، لأنه كان مؤسسا على الصخر.","6:49":"وأما من سمع ولم يعمل، فهو يشبه إنسانا بنى بيتا على الأرض دون أساس. فلما صدمه السيل، انهار في الحال؛ وكان خراب ذلك البيت جسيما! »","7:1":"وبعدما أتم إلقاء أقواله كلها في مسامع الشعب، دخل بلدة كفرناحوم.","7:2":"وكان عند قائد مئة عبد مريض قد أشرف على الموت، وكان عزيزا عليه.","7:3":"فلما سمع بيسوع، أرسل إليه شيوخ اليهود، متوسلا إليه أن يأتي وينقذ عبده.","7:4":"ولما أدركوا يسوع، طلبوا إليه بإلحاح قائلين: «إنه يستحق أن تمنحه طلبه،","7:5":"فهو يحب أمتنا، وقد بنى لنا المجمع».","7:6":"فرافقهم يسوع. ولكن ما إن أصبح على مقربة من البيت، حتى أرسل إليه قائد المئة بعض أصدقائه، يقول له: «ياسيد، لا تكلف نفسك، لأني لا أستحق أن تدخل تحت سقف بيتي.","7:7":"ولذلك لا أعتبر نفسي أهلا لأن ألاقيك. إنما قل كلمة، فيشفى خادمي:","7:8":"فأنا أيضا رجل موضوع تحت سلطة أعلى مني، ولي جنود تحت إمرتي، أقول لأحدهم: اذهب! فيذهب؛ ولغيره: تعال! فيأتي؛ ولعبدي: افعل هذا! فيفعل».","7:9":"فلما سمع يسوع ذلك، تعجب منه، ثم التفت إلى الجمع الذي يتبعه، وقال: «أقول لكم: لم أجد حتى في إسرائيل إيمانا عظيما كهذا!»","7:10":"ولما رجع المرسلون إلى البيت، وجدوا العبد المريض قد تعافى.","7:11":"وفي اليوم التالي، ذهب إلى مدينة اسمها نايين، يرافقه كثيرون من تلاميذه وجمع عظيم.","7:12":"ولما اقترب من باب المدينة، إذا ميت محمول، وهو ابن وحيد لأمه التي كانت أرملة، وكان معها جمع كبير من المدينة.","7:13":"فلما رآها الرب، تحنن عليها، وقال لها: «لا تبكي!»","7:14":"ثم تقدم ولمس النعش، فتوقف حاملوه. وقال: «أيها الشاب، لك أقول: قم!»","7:15":"فجلس الميت وبدأ يتكلم، فسلمه إلى أمه.","7:16":"فاستولى الخوف على الجميع، ومجدوا الله، قائلين: «قد قام فينا نبي عظيم وتفقد الله شعبه !»","7:17":"وذاع هذا الخبر عنه في منطقة اليهودية كلها وفي جميع النواحي المجاورة.","7:18":"ونقل تلاميذ يوحنا إليه خبر هذه كلها. فدعا يوحنا اثنين من تلاميذه،","7:19":"وأرسلهما إلى الرب، يسأله: «أأنت هو الآتي، أم ننتظر آخر؟»","7:20":"فلما جاء الرجلان إلى الرب، قالا: «أرسلنا إليك يوحنا المعمدان، يسأل: أأنت هو الآتي، أم ننتظر آخر ؟»","7:21":"وفي تلك الساعة شفى كثيرين من أمراض وعلل وأرواح شريرة، ووهب البصر لعميان كثيرين.","7:22":"فرد يسوع على المرسلين قائلا: «اذهبا وأخبرا يوحنا بما قد رأيتما وسمعتما: أن العميان يبصرون، والعرج يمشون، والبرص يطهرون، والصم يسمعون، والموتى يقامون، والمساكين يبشرون.","7:23":"وطوبى لكل من لا يشك في! »","7:24":"وما إن انصرف مرسلا يوحنا حتى أخذ يسوع يتحدث إلى الجموع عن يوحنا «ماذا خرجتم إلى البرية لتروا؟ أقصبة تهزها الرياح؟","7:25":"بل ماذا خرجتم لتروا؟ أإنسانا يلبس ثيابا ناعمة؟ ها إن لابسي الثياب الفاخرة والمترفهين هم في قصور الملوك.","7:26":"إذن، ماذا خرجتم لتروا؟ أنبيا؟ نعم، أقول لكم، وأعظم من نبي!","7:27":"فهذا هو الذي كتب عنه: إني مرسل قدامك رسولي الذي يمهد لك طريقك.","7:28":"فإني أقول لكم: إنه ليس بين من ولدتهم النساء أعظم من يوحنا، ولكن الأصغر في ملكوت الله أعظم منه!»","7:29":"ولما سمع ذلك جميع الشعب، حتى جباة الضرائب، اعترفوا ببر الله إذ كانوا قد تعمدوا بمعمودية يوحنا؛","7:30":"وأما الفريسيون وعلماء الشريعة؛ فقد رفضوا قصد الله من نحوهم إذ لم يكونوا قد تعمدوا على يده.","7:31":"«فبمن أشبه إذن أهل هذا الجيل؟ ومن يشبهون؟","7:32":"إنهم يشبهون أولادا جالسين في الساحة العامة، ينادي بعضهم بعضا قائلين: زمرنا لكم، فلم ترقصوا؛ ثم ندبنا لكم، فلم تبكوا!","7:33":"فقد جاء يوحنا المعمدان لا يأكل ولا يشرب خمرا، فقلتم: إن شيطانا يسكنه.","7:34":"ثم جاء ابن الإنسان يأكل ويشرب، فقلتم: هذا رجل شره سكير، صديق لجباة الضرائب والخاطئين؛","7:35":"ولكن الحكمة قد بررها جميع أبنائها. ».","7:36":"ولكن واحدا من الفريسيين طلب إليه أن يأكل عنده. فدخل بيت الفريسي واتكأ.","7:37":"وكان في المدينة امرأة خاطئة، فما إن علمت أنه متكيء في بيت الفريسي، حتى جاءت تحمل قارورة عطر،","7:38":"ووقفت من ورائه عند قدميه باكية، وأخذت تبل قدميه بالدموع وتمسحهما بشعر رأسها، وتقبل قدميه بحرارة وتدهنهما بالعطر.","7:39":"فلما رأى الفريسي الذي دعاه ذلك، حدث نفسه قائلا: «لو كان هذا نبيا، لعلم من هي هذه المرأة التي تلمسه، وما حالها؛ فإنها خاطئة!»","7:40":"فرد عليه يسوع قائلا: «ياسمعان، عندي شيء أقوله لك». أجاب: «قل يامعلم!»","7:41":"فقال: «كان لأحد المتعاملين بالدين، دين على اثنين: على أحدهما خمس مئة دينار، وعلى الآخر خمسون.","7:42":"ولكن إذ لم يكن عندهما ما يدفعانه وفاء للدين، سامحهما كليهما. فأيهما يكون أكثر حبا له؟»","7:43":"فأجاب سمعان: «أظن الذي سامحه بالدين الأكبر». فقال له: «حكمت حكما صحيحا!»","7:44":"ثم التفت إلى المرأة، وقال لسمعان: «أترى هذه المرأة؟ إني دخلت بيتك ولم تقدم لي ماء لغسل قدمي! أما هي، فقد غسلت قدمي بالدموع ومسحتهما بشعرها.","7:45":"أنت لم تقبلني قبلة واحدة! أما هي، فمنذ دخولي لم تتوقف عن تقبيل قدمي.","7:46":"أنت لم تدهن رأسي بزيت! أما هي، فقد دهنت قدمي بالعطر.","7:47":"لهذا السبب أقول لك: إن خطاياها الكثيرة قد غفرت، لهذا أحبت كثيرا. ولكن الذي يغفر له القليل، يحب قليلا!»","7:48":"ثم قال لها: «مغفورة لك خطاياك!»","7:49":"فأخذ المتكئون يسائلون أنفسهم: «من هو هذا الذي يغفر الخطايا أيضا؟»","7:50":"وقال للمرأة: «إيمانك قد خلصك. اذهبي بسلام!»","8:1":"بعد ذلك أخذ يجول في كل مدينة وقرية واعظا ومبشرا بملكوت الله وكان يرافقه تلاميذه الاثنا عشر،","8:2":"وبعض النساء اللواتي كن قد شفين من أرواح شريرة وأمراض، وهن: مريم المعروفة بالمجدلية التي طرد منها سبعة شياطين،","8:3":"ويونا زوجة خوزي وكيل هيرودس، وسوسنة، وغيرهن كثيرات ممن كن يساعدنه بأموالهن.","8:4":"فلما اجتمع حوله جمع عظيم من الذين خرجوا إليه من كل بلدة، خاطبهم بمثل:","8:5":"«خرج الزارع ليزرع بذاره. وبينما هو يزرع، وقع بعض البذار على الممرات، فداسته الأقدام، والتهمته طيور السماء.","8:6":"ووقع بعضه على الصخر، فلما طلع يبس لأنه كان بلا رطوبة.","8:7":"ووقع بعضه في وسط الأشواك، فطلع الشوك معه وخنقه.","8:8":"وبعض البذار وقع في الأرض الصالحة. ولما نبت، أنتج ثمرا مئة ضعف». قال هذا ونادى «من له أذنان للسمع، فليسمع!»","8:9":"وسأله تلاميذه: «ما هو مغزى هذا المثل؟»","8:10":"فقال: «لكم قد أعطي أن تعرفوا أسرار ملكوت الله. أما الآخرون، فأكلمهم بأمثال، حتى إنهم: ينظرون ولا يبصرون، ويسمعون ولا يفهمون.","8:11":"وهذا مغزى المثل: البذار هو كلمة الله.","8:12":"وما وقع على الممرات هم الذين يسمعون (الكلمة)، ثم يأتي إبليس ويخطف الكلمة من قلوبهم لئلا يؤمنوا فيخلصوا.","8:13":"وما وقع على الصخر هم الذين يقبلون الكلمة بفر ح لدى سماعها، وهؤلاء لا أصل لهم، فيؤمنون إلى حين، وفي وقت التجربة يتراجعون.","8:14":"وما وقع حيث الأشواك هم الذين يسمعون ثم يمضون فتخنقهم هموم الحياة وغناها ولذاتها، فلا ينتجون ثمرا ناضجا.","8:15":"وأما الذي وقع في الأرض الجيدة، فهم الذين يسمعون الكلمة ويحفظونها في قلب جيد مستقيم، وينتجون ثمرا بالصبر.","8:16":"ولا أحد يشعل مصباحا ثم يغطيه بوعاء، أو يضعه تحت سرير، بل يرفعه على منارة ليرى الداخلون النور.","8:17":"فما من محجوب لن يكشف، ولا سر لن يعلم ويعلن.","8:18":"فتنبهوا إذن كيف تسمعون. فإن من عنده، يعطى المزيد؛ ومن لم يكن عنده، فحتى الذي يظنه له، ينتزع منه!»","8:19":"وجاءت إليه أمه وإخوته، ولم يتمكنوا من الوصول إليه بسبب الزحام.","8:20":"فقيل له: «إن أمك وإخوتك واقفون خارجا، يريدون أن يروك!»","8:21":"ولكنه أجابهم قائلا: «أمي وإخوتي هم الذين يسمعون كلمة الله ويعملون بها».","8:22":"وذات يوم ركب قاربا هو وتلاميذه، وقال لهم: «لنعبر إلى الضفة المقابلة من البحيرة!» فأقلعوا.","8:23":"وفيما هم مبحرون، نام. وهبت على البحيرة عاصفة ريح مفاجئة، فأخذ الماء يملأ القارب، وأحاط بهم الخطر.","8:24":"فتقدموا إليه وأيقظوه قائلين: «ياسيد، ياسيد، إننا نهلك!» فنهض وزجر الريح والماء الهائج، فسكنا وساد الهدوء.","8:25":"ثم قال لهم: «أين إيمانكم؟» وإذ خافوا، ذهلوا، وقال أحدهم للآخر: «من هو هذا إذن حتى إنه يأمر الرياح والماء فتطيعه؟ »","8:26":"ووصلوا إلى بلدة الجراسيين، وهي تقع مقابل الجليل.","8:27":"فلما نزل إلى البر، لاقاه رجل من المدينة تسكنه الشياطين منذ مدة طويلة، وكان لا يلبس ثوبا ولا يسكن بيتا بل يقيم بين القبور.","8:28":"فما إن رأى يسوع، حتى صرخ وانطرح أمامه، وقال بصوت عال: «ما شأنك بي يايسوع ابن الله العلي؟ أتوسل إليك ألا تعذبني؟»","8:29":"فإن يسوع كان قد أمر الروح النجس أن يخرج من الرجل. فكثيرا ما كان يتمكن منه، وكلما ربط بالسلاسل والقيود ليضبط، حطم القيود وساقه الشيطان إلى القفار.","8:30":"فسأله يسوع: «ما اسمك؟» فقال: «لجيون!» لأن جيشا كبيرا من الشياطين كانوا قد دخلوا فيه،","8:31":"وقد توسلوا إليه ألا يأمرهم بالذهاب إلى الهاوية.","8:32":"وكان هنالك قطيع كبير من الخنازير يرعى في الجبل، فالتمسوا منه أن يأذن لهم بالدخول في الخنازير، فأذن لهم.","8:33":"فخرجت الشياطين من الإنسان، ودخلت في الخنازير، فاندفع القطيع من على حافة الجبل إلى البحيرة ومات غرقا.","8:34":"فلما رأى الرعاة ما حدث، هربوا إلى المدينة والمزارع ينشرون الخبر.","8:35":"فخرج الناس ليروا ما حدث، وجاءوا إلى يسوع، فوجدوا الرجل الذي خرجت منه الشياطين جالسا عند قدمي يسوع وهو لابس وسليم العقل. فخافوا.","8:36":"وأخبرهم أيضا الذين شاهدوا ما حدث، كيف شفي المسكون.","8:37":"فطلب جميع أهالي بلدة الجراسيين من يسوع أن يرحل عنهم، لأن خوفا عظيما استولى عليهم. فركب القارب، ورجع.","8:38":"وأما الرجل الذي خرجت منه الشياطين، فتوسل إليه أن يرافقه. ولكنه صرفه قائلا:","8:39":"«ارجع إلى بيتك، وحدث بما عمله الله بك!» فمضى سائرا في المدينة كلها، وهو ينادي بما عمله به يسوع.","8:40":"ولما عاد يسوع، رحب به الجمع، لأنهم كانوا كلهم يترقبون عودته.","8:41":"وإذا رجل اسمه يايرس، وهو رئيس للمجمع، قد جاء وانطرح عند قدمي يسوع وتوسل إليه أن يرافقه إلى بيته،","8:42":"لأن له ابنة وحيدة، عمرها حوالي اثنتي عشرة سنة، وقد أشرفت على الموت. وفيما هو ذاهب، كانت الجموع تزحمه.","8:43":"وكانت هناك امرأة مصابة بنزيف دموي منذ اثنتي عشرة سنة ومع أنها كانت قد أنفقت كل ما تملكه أجرا للأطباء، فلم تتمكن من الشفاء على يد أحد.","8:44":"فتقدمت إلى يسوع من خلفه، ولمست طرف ردائه؛ وفي الحال توقف نزيف دمها.","8:45":"وقال يسوع: «من لمسني؟» فلما أنكر الجميع ذلك، قال بطرس ورفاقه: «ياسيد، الجموع يضيقون عليك ويزحمونك، وتسأل: من لمسني؟»","8:46":"فقال يسوع: «إن شخصا ما قد لمسني، لأني شعرت بأن قدرة قد خرجت مني».","8:47":"فلما رأت المرأة أن أمرها لم يكتم، تقدمت مرتجفة، وارتمت أمامه معلنة أمام جميع الناس لأي سبب لمسته، وكيف نالت الشفاء في الحال.","8:48":"فقال لها: «ياابنة، إيمانك قد شفاك؛ اذهبي بسلام! »","8:49":"وبينما كان يتكلم، جاء مبعوث من بيت رئيس المجمع، يقول له: «ماتت ابنتك. لا تكلف المعلم بعد!»","8:50":"وإذ سمع يسوع ذلك، كلمه قائلا: «لا تخف، آمن فقط، فتنجو ابنتك!»","8:51":"ولما وصل إلى البيت، لم يدع أحدا يدخل معه إلا بطرس ويوحنا ويعقوب وأبا الفتاة وأمها.","8:52":"وكان الجميع يبكونها ويندبونها. فقال: «لا تبكوا. إنها لم تمت، بل هي نائمة!»","8:53":"فضحكوا منه، لعلمهم أنها ماتت.","8:54":"ولكنه، بعدما أخرجهم جميعا، أمسك بيدها، ونادى قائلا: «ياصبية، قومي!»","8:55":"فعادت إليها روحها، ونهضت في الحال. وأمر أن يقدم لها طعام.","8:56":"فدهش والداها؛ ولكنه أوصاهما ألا يخبرا أحدا بما جرى.","9:1":"ثم جمع يسوع الاثني عشر، ومنحهم قدر ة وسلطة على جميع الشياطين وعلى الأمراض لشفائها،","9:2":"وأرسلهم ليبشروا بملكوت الله ويشفوا.","9:3":"وقال لهم: «لا تحملوا للطريق شيئا: لا عصا، ولا زادا، ولا خبزا، ولا مالا، ولا يحمل الواحد ثوبين.","9:4":"وأي بيت دخلتم فهناك أقيموا ومن هناك ارحلوا.","9:5":"وإن كان أحد لا يقبلكم في مدينة ما، فاخرجوا من هناك، وانفضوا الغبار عن أقدامكم، شهادة عليهم».","9:6":"فانطلقوا يجتازون في القرى وهم يبشرون ويشفون في كل مكان.","9:7":"وسمع هيرودس حاكم الربع بكل ما كان يجري، فوقع في الحيرة، لأن بعضا كانوا يقولون: «إن يوحنا قام من بين الأموات!»","9:8":"وبعضا يقولون: «إن إيليا ظهر!» وآخرين: «إن واحدا من الأنبياء القدامى قام!»","9:9":"فقال هيرودس: «يوحنا، أنا قطعت رأسه، ولكن من هو هذا الذي أسمع عنه مثل هذه الأمور؟» وكان يرغب في أن يراه.","9:10":"وبعدما رجع الرسل، أخبروه بجميع ما فعلوا، فأخذهم وذهب بهم على انفراد إلى مدينة اسمها بيت صيدا.","9:11":"ولكن الجموع علموا بذلك فلحقوا به، فاستقبلهم وحدثهم عن ملكوت الله، وشفى منهم من كانوا محتاجين إلى الشفاء.","9:12":"ولما كاد النهار ينقضي، تقدم إليه الاثنا عشر وقالوا له: «اصرف الجمع ليذهبوا إلى القرى المجاورة، وإلى المزارع، فيبيتوا هناك ويجدوا طعاما، لأننا هنا في مكان مقفر!»","9:13":"فقال لهم: «أعطوهم أنتم ليأكلوا!» أجابوا: «ليس عندنا أكثر من خمسة أرغفة وسمكتين، إلا إذا ذهبنا واشترينا طعاما لهذا الشعب كله».","9:14":"فقد كانوا نحو خمسة آلاف رجل. ثم قال لتلاميذه: «أجلسوهم في جماعات تتألف كل منها من خمسين».","9:15":"ففعلوا، وأجلسوا الجميع.","9:16":"فأخذ الأرغفة الخمسة والسمكتين، ورفع عينيه نحو السماء، ثم باركها وكسرها وأعطى التلاميذ ليقدموا إلى الجمع.","9:17":"فأكل الجميع وشبعوا. ثم رفع من الكسر الفاضلة عنهم اثنتا عشرة قفة.","9:18":"وفيما كان يصلي على انفراد والتلاميذ معه، سألهم: «من يقول الجموع إني أنا؟»","9:19":"فأجابوه: «يقول بعضهم إنك يوحنا المعمدان، وآخرون إنك إيليا، وآخرون إنك واحد من الأنبياء القدامى وقد قام!»","9:20":"فسألهم: «وأنتم، من تقولون إني أنا؟» فأجابه بطرس: «أنت مسيح الله!»","9:21":"ولكنه حذرهم، موصيا ألا يخبروا أحدا بذلك.","9:22":"وقال: «لابد أن يتألم ابن الإنسان كثيرا ويرفضه الشيوخ ورؤساء الكهنة والكتبة، ويقتل، وفي اليوم الثالث يقام».","9:23":"ثم قال للجميع: «إن أراد أحد أن يسير ورائي، فلينكر نفسه ويحمل صليبه كل يوم ويتبعني.","9:24":"فأي من أراد أن يخلص نفسه، يخسرها؛ ولكن من يخسر نفسه من أجلي، فهو يخلصها.","9:25":"فماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه أو أهلكها؟","9:26":"فإن من يستحي بي وبكلامي، فبه يستحي ابن الإنسان لدى عودته في مجده ومجد الآب والملائكة المقدسين.","9:27":"ولكني أقول لكم بحق إن بين الواقفين هنا بعضا لن يذوقوا الموت حتى يكونوا قد رأوا ملكوت الله ... »","9:28":"وحدث بعد هذا الكلام بثمانية أيام تقريبا أن أخذ يسوع بطرس ويوحنا ويعقوب، وصعد إلى جبل ليصلي.","9:29":"وبينما هو يصلي، تجلت هيئة وجهه وصارت ثيابه بيضاء لماعة.","9:30":"وإذا رجلان يتحدثان معه، وهما موسى وإيليا،","9:31":"وقد ظهرا بمجد وتكلما عن رحيله الذي كان على وشك إتمامه في أورشليم.","9:32":"ومع أن بطرس ورفيقيه قد غالبهم النوم، فإنهم حين استيقظوا تماما، شاهدوا مجده والرجلين الواقفين معه.","9:33":"وفيما كانا يفارقانه، قال بطرس ليسوع: «يامعلم، ما أحسن أن نبقى هنا! فلننصب ثلاث خيام: واحدة لك، وواحدة لموسى، وواحدة لإيليا...» وهو لا يدري ما يقول.","9:34":"ولكنه فيما كان يقول ذلك، جاءت سحابة فخيمت عليهم، فخافوا عندما طوقتهم السحابة،","9:35":"وانطلق صوت من السحابة يقول: «هذا هو ابني الذي اخترته. له اسمعوا!»","9:36":"وفيما انطلق الصوت، وجد يسوع وحده. وقد كتموا الخبر فلم يخبروا أحدا في تلك الأيام بأي شيء مما رأوه.","9:37":"وفي اليوم التالي، لما نزلوا من الجبل، لاقاه جمع عظيم.","9:38":"وإذا في الجمع رجل نادى قائلا: «يامعلم، أتوسل إليك أن تنظر إلى ابني، فإنه ولدي الوحيد.","9:39":"وها إن روحا يتملكه، فيصرخ فجأة، ويخبطه الروح فيزبد، وبالجهد يفارقه بعد أن يرضضه.","9:40":"وقد التمست من تلاميذك أن يطردوه، فلم يقدروا».","9:41":"فأجاب يسوع قائلا: «أيها الجيل غير المؤمن والمنحرف! إلى متى أبقى معكم وأحتملكم؟» (وقال للرجل): «أحضر ابنك إلى هنا!»","9:42":"وفيما الولد آت، صرعه الشيطان وخبطه بعنف. فزجر يسوع الروح النجس، وشفى الولد وسلمه إلى أبيه.","9:43":"فذهل الجميع من عظمة الله.","9:44":"«لتدخل هذه الكلمات آذانكم: إن ابن الإنسان على وشك أن يسلم إلى أيدي الناس!»","9:45":"إلا أنهم لم يفهموا هذا القول، وقد أغلق عليهم فلم يدركوه، وخافوا أن يسألوه عنه.","9:46":"وحدث بينهم جدال في من هو الأعظم فيهم.","9:47":"فإذ علم يسوع نيات قلوبهم، أخذ ولدا صغيرا وأوقفه بجانبه،","9:48":"وقال لهم: «أي من قبل باسمي هذا الولد الصغير، فقد قبلني؛ ومن قبلني، يقبل الذي أرسلني. فإن من كان الأصغر بينكم جميعا، فهو العظيم».","9:49":"وتكلم يوحنا فقال: «ياسيد، رأينا واحدا يطرد الشياطين باسمك، فمنعناه لأنه لا يتبعك معنا».","9:50":"فقال له يسوع: «لا تمنعوه: لأن من ليس ضدكم، فهو معكم! »","9:51":"ولما تمت الأيام لارتفاعه، صمم بعزم على المضي إلى أورشليم.","9:52":"فأرسل قدامه بعض الرسل. فذهبوا ودخلوا قرية للسامريين، ليعدوا له (منزلا فيها).","9:53":"ولكنهم رفضوا استقباله لأنه كان متجها صوب أورشليم.","9:54":"فلما رأى ذلك تلميذاه يعقوب ويوحنا، قالا: «يارب، أتريد أن نأمر بأن تنزل النار من السماء وتلتهمهم؟»","9:55":"فالتفت إليهما ووبخهما قائلا: «لا تعلمان من أي روح أنتما،","9:56":"لأن ابن الإنسان أتى لا ليهلك نفوس الناس، بل ليخلصها.» ثم ذهبوا إلى قرية أخرى.","9:57":"وبينما كانوا سائرين في الطريق، قال له أحد الناس: «ياسيد، سأتبعك أينما تذهب!»","9:58":"فقال له يسوع: «للثعالب أوجار، ولطيور السماء أوكار؛ وأما ابن الإنسان فليس له مكان يسند إليه رأسه».","9:59":"وقال لغيره: «اتبعني!» ولكن هذا قال: «ياسيد، اسمح لي أن أذهب أولا وأدفن أبي!»","9:60":"فقال له يسوع: «دع الموتى يدفنون موتاهم، وأما أنت فاذهب وبشر بملكوت الله».","9:61":"وقال له آخر: «ياسيد، سأتبعك، ولكن اسمح لي أولا أن أودع أهل بيتي!»","9:62":"فقال له يسوع: «ما من أحد يضع يده على المحراث ويلتفت إلى الوراء، يصلح لملكوت الله».","10:1":"وبعد ذلك عين الرب أيضا اثنين وسبعين آخرين، وأرسلهم اثنين اثنين، ليسبقوه إلى كل مدينة ومكان كان على وشك الذهاب إليه.","10:2":"وقال لهم: «إن الحصاد كثير، ولكن العمال قليلون، فتضرعوا إلى رب الحصاد أن يبعث عمالا إلى حصاده.","10:3":"فاذهبوا! ها إني أرسلكم كحملان بين ذئاب.","10:4":"لا تحملوا صرة مال ولا كيس زاد ولا حذاء؛ ولا تسلموا في الطريق على أحد.","10:5":"وأي بيت دخلتم، فقولوا أولا: سلام لهذا البيت!","10:6":"فإن كان في البيت ابن سلام، يحل سلامكم عليه. وإلا، فسلامكم يعود لكم.","10:7":"وانزلوا في ذلك البيت تأكلون وتشربون مما عندهم: لأن العامل يستحق أجرته. لا تنتقلوا من بيت إلى بيت.","10:8":"وأية مدينة دخلتم وقبلكم أهلها، فكلوا مما يقدم لكم،","10:9":"واشفوا المرضى الذين فيها، وقولوا لهم: قد اقترب منكم ملكوت الله!","10:10":"وأية مدينة دخلتم ولم يقبلكم أهلها، فاخرجوا إلى شوارعها، وقولوا:","10:11":"حتى غبار مدينتكم العالق بأقدامنا ننفضه عليكم، ولكن اعلموا هذا: أن ملكوت الله قد اقترب!","10:12":"أقول لكم: إن سدوم ستكون حالتها في ذلك اليوم أخف وطأة من حالة تلك المدينة…","10:13":"الويل لك ياكورزين! الويل لك يابيت صيدا! فلو أجري في صور وصيدا ما أجري فيكما من المعجزات، لتاب أهلهما منذ القديم متشحين بالمسوح قاعدين في الرماد.","10:14":"ولكن صور وصيدا ستكون حالتهما في الدينونة أخف وطأة من حالتكما.","10:15":"وأنت ياكفرناحوم، هل ارتفعت حتى السماء؟ إنك إلى قعر الهاوية ستهبطين!","10:16":"من يسمع لكم يسمع لي، ومن يرفضكم يرفضني؛ ومن يرفضني يرفض الذي أرسلني! »","10:17":"وبعدئذ رجع الاثنان والسبعون فرحين، وقالوا: «يارب، حتى الشياطين تخضع لنا باسمك!»","10:18":"فقال لهم: «قد رأيت الشيطان وهو يهوي من السماء مثل البرق.","10:19":"وها أنا قد أعطيتكم سلطة لتدوسوا الحيات والعقارب وقدرة العدو كلها، ولن يؤذيكم شيء أبدا.","10:20":"إنما لا تفرحوا بهذا: بأن الأرواح تخضع لكم، بل افرحوا بأن أسماءكم قد كتبت في السماوات».","10:21":"في تلك الساعة ابتهج يسوع بالروح وقال: «أحمدك أيها الآب، رب السماء والأرض، لأنك حجبت هذه الأمور عن الحكماء والفهماء، وكشفتها للأطفال. نعم، أيها الآب، لأنه هكذا حسن في نظرك!","10:22":"كل شيء قد سلم إلي من قبل أبي، ولا أحد يعرف من هو الابن إلا الآب، ولا من هو الآب إلا الابن ومن أراد الابن أن يعلنه له!»","10:23":"ثم التفت إلى التلاميذ وقال لهم على حدة: «طوبى للعيون التي ترى ما أنتم ترون.","10:24":"فإني أقول لكم إن كثيرين من الأنبياء والملوك تمنوا أن يروا ما تبصرون ولكنهم لم يروا، وأن يسمعوا ما تسمعون ولكنهم لم يسمعوا».","10:25":"وتصدى له أحد علماء الشريعة ليجربه، فقال: «يامعلم، ماذا أعمل لأرث الحياة الأبدية؟»","10:26":"فقال له: «ماذا كتب في الشريعة؟ وكيف تقرأها؟»","10:27":"فأجاب: «أحب الرب إلهك بكل قلبك وكل نفسك وكل قدرتك وكل فكرك، وأحب قريبك كنفسك».","10:28":"فقال له: «جوابك صحيح. فإن عملت بهذا، تحيا!»","10:29":"لكنه إذ كان راغبا في تبرير نفسه، سأل يسوع: «ومن هو قريبي؟»","10:30":"فرد عليه يسوع قائلا:","10:31":"وحدث أن كاهنا كان نازلا في تلك الطريق، فرآه ولكنه جاوزه إلى الجانب الآخر.","10:32":"وكذلك مر أيضا واحد من اللاويين، فلما وصل إلى ذلك المكان، نظر إليه، ولكنه جاوزه إلى الجانب الآخر.","10:33":"إلا أن سامريا مسافرا جاء إليه، ولما رآه، أخذته الشفقة عليه،","10:34":"فتقدم إليه وربط جراحه بعدما صب عليها زيتا وخمرا. ثم أركبه على دابته وأوصله إلى الخان واعتنى به.","10:35":"وعند مغادرته الخان في اليوم التالي، أخرج دينارين ودفعهما إلى صاحب الخان، وقال له: اعتن به! ومهما تنفق أكثر، فإني أفيك ذلك عند رجوعي.","10:36":"فأي هؤلاء الثلاثة يبدو لك قريبا للذي وقع بأيدي اللصوص؟»","10:37":"فأجاب: «إنه الذي عامله بالرحمة!» فقال له يسوع: «اذهب، واعمل أنت هكذا! »","10:38":"وبينما هم في الطريق، دخل إحدى القر ى، فاستقبلته امرأة اسمها مرثا في بيتها.","10:39":"وكان لها أخت اسمها مريم، جلست عند قدمي يسوع تسمع كلمته.","10:40":"أما مرثا فكانت منهمكة بشؤون الخدمة الكثيرة. فأقبلت وقالت: «يارب، أما تبالي بأن أختي قد تركتني أخدم وحدي؟ فقل لها أن تساعدني!»","10:41":"ولكن يسوع رد عليها قائلا: «مرثا، مرثا! أنت مهتمة وقلقة لأمور كثيرة.","10:42":"ولكن الحاجة هي إلى واحد، ومريم قد اختارت النصيب الصالح الذي لن يؤخذ منها! »","11:1":"وكان يصلي في أحد الأماكن، فلما انتهى، قال له أحد تلاميذه: «يارب، علمنا أن نصلي كما علم يوحنا تلاميذه».","11:2":"فقال لهم: «عندما تصلون، قولوا: أبانا الذي في السماوات! ليتقدس اسمك، ليأت ملكوتك. لتكن مشيئتك كما في السماء كذلك على الأرض.","11:3":"خبزنا كفافنا أعطنا كل يوم؛","11:4":"واغفر لنا خطايانا، لأننا نحن أيضا نغفر لكل من يذنب إلينا؛ ولا تدخلنا في تجربة لكن نجنا من الشرير! »","11:5":"ثم قال لهم: «من منكم يكون له صديق، فيذهب إليه في منتصف الليل ويقول له: ياصديقي، أقرضني ثلاثة أرغفة،","11:6":"فقد جاءني صديق من سفر، وليس عندي ما أقدم له!","11:7":"لكن صديقه يجيبه من الداخل: لا تزعجني! فقد أقفلت الباب، وها أنا وأولادي في الفراش. لا أقدر أن أقوم وأعطيك!","11:8":"أقول لكم: إن كان لا يقوم ويعطيه لأنه صديقه، فلابد أن يقوم ويعطيه قدر ما يحتاج إليه، لأنه ألح في الطلب.","11:9":"فإني أقول لكم: اطلبوا، تعطوا؛ اسعوا، تجدوا؛ اقرعوا، يفتح لكم:","11:10":"فإن كل من يطلب ينال، ومن يسعى يجد، ومن يقرع يفتح له.","11:11":"فأي أب منكم يطلب منه ابنه خبزا فيعطيه حجرا؟ أو يطلب سمكة فيعطيه بدل السمكة حية؟","11:12":"أو يطلب بيضة، فيعطيه عقربا؟","11:13":"فإن كنتم، أنتم الأشرار، تعرفون أن تعطوا أولادكم عطايا جيدة، فكم بالأحرى الآب، الذي من السماء يهب الروح القدس لمن يسألونه؟ »","11:14":"وكان يطرد شيطانا (من رجل) كان ذلك الشيطان قد أخرسه. فلما طرد الشيطان، نطق الأخرس. فتعجبت الجموع.","11:15":"ولكن بعضا منهم قالوا: «إنما يطرد الشياطين ببعلزبول رئيس الشياطين».","11:16":"وطلب منه آخرون، ليجربوه، آية من السماء.","11:17":"ولكنه علم أفكارهم وقال لهم: «كل مملكة تنقسم على ذاتها تخرب، وكل بيت (ينقسم) على بيت يسقط.","11:18":"فإن كان الشيطان كذلك قد انقسم على ذاته، فكيف تصمد مملكته؟ فقد قلتم إني أطرد الشياطين ببعلزبول.","11:19":"ولكن، إن كنت أنا أطرد الشياطين ببعلزبول، فأبناؤكم بمن يطردونهم؟ لذلك هم يحكمون عليكم.","11:20":"أما إذا كنت أطرد الشياطين بإصبع الله، فقد أقبل عليكم ملكوت الله.","11:21":"عندما يحرس القوي بيته وهو بكامل سلاحه، تكون أمتعته في مأمن.","11:22":"ولكن عندما يغزوه من هو أقوى منه فيغلبه، فإنه يجرده من كامل سلاحه الذي اعتمد عليه، ثم يوزع غنائمه.","11:23":"من ليس معي، فهو ضدي؛ ومن لا يجمع معي، فهو يفرق.","11:24":"بعد أن يخرج الروح النجس من الإنسان، يهيم في الأماكن القاحلة طلبا للراحة، وإذ لا يجد، يقول: سأرجع إلى بيتي الذي غادرته!","11:25":"وعندما يأتي، يجده مكنوسا مزينا.","11:26":"فيذهب ويصطحب سبعة أرواح أخر أردأ منه، فتدخل ذلك الإنسان وتسكنه، فتصير الحالة الأخيرة لذلك الإنسان أردأ من الأولى! »","11:27":"وبينما هو يتكلم بهذا، رفعت امرأة من بين الجمع صوتها قائلة له: «طوبى للبطن الذي حملك، والثديين اللذين رضعتهما!»","11:28":"إلا أنه قال: «بل طوبى للذين يسمعون كلمة الله ويعملون بها».","11:29":"وإذ كانت الجموع تزدحم عليه، أخذ يقول: «هذا الجيل جيل شرير، يطلب آية ولن يعطى آية إلا آية يونان.","11:30":"فإنه كما كان يونان آية لأهل نينوى، فهكذا أيضا يكون ابن الإنسان لهذا الجيل.","11:31":"إن ملكة الجنوب ستقوم في الدينونة مع هذا الجيل وتدينه لأنها جاءت من أقاصي الأرض لتسمع حكمة سليمان. وها هنا أعظم من سليمان!","11:32":"وأهل نينوى سيقفون في الدينونة مع هذا الجيل ويدينونه: لأنهم تابوا لدى وعظ يونان لهم. وها هنا أعظم من يونان.","11:33":"ولكن، لا أحد يشعل مصباحا ويضعه في مكان مخفي أو تحت المكيال، بل يرفعه على المنارة ليرى الداخلون النور.","11:34":"عينك هي مصباح الجسد: فعندما تكون عينك سليمة، يكون جسدك كله منورا؛ أما عندما تكون عينك شريرة، فيكون جسدك أيضا مظلما.","11:35":"فتنبه إذن لئلا يكون النور الذي فيك ظلاما.","11:36":"إذن، إن كان جسدك كله منورا وليس فيه جانب مظلم، فإنه يكون منورا بكامله، كأنما أنار لك المصباح بإشعاعه! »","11:37":"وبينما هو يتكلم، طلب إليه أحد الفريسيين أن يتغدى عنده. فدخل (بيته) واتكأ.","11:38":"ولكن الفريسي تعجب لما رأى أنه لم يغتسل قبل الغداء.","11:39":"فقال له الرب: «أنتم الفريسيين تنظفون الكأس والصحفة من الخارج، ولكنكم من الداخل مملوؤون نهبا وخبثا.","11:40":"أيها الأغبياء، أليس الذي صنع الخارج قد صنع الداخل أيضا؟","11:41":"أحرى بكم أن تتصدقوا بما عندكم، فإذا كل شيء يكون طاهرا لكم.","11:42":"ولكن الويل لكم أيها الفريسيون فإنكم تدفعون عشر النعنع والسذاب والبقول الأخرى، وتتجاوزون عن العدل ومحبة الله: كان يجب أن تعملوا هذا ولا تهملوا ذاك!","11:43":"الويل لكم أيها الفريسيون، فإنكم تحبون تصدر المقاعد الأولى في المجامع وتلقي التحيات في الساحات العامة!","11:44":"الويل لكم، فإنكم تشبهون القبور المخفية، يمشي الناس عليها وهم لا يعلمون!»","11:45":"وتكلم أحد علماء الشريعة، قائلا له: «يامعلم، إنك بقولك هذا تهيننا نحن أيضا».","11:46":"فقال: «والويل أيضا لكم ياعلماء الشريعة، فإنكم تحملون الناس أحمالا مرهقة، وأنتم لا تمسونها بإصبع من أصابعكم!","11:47":"الويل لكم، فإنكم تبنون قبور الأنبياء وآباؤكم قتلوهم.","11:48":"فأنتم إذن تشهدون موافقين على أعمال آبائكم: فهم قتلوا الأنبياء، وأنتم تبنون قبورهم.","11:49":"لهذا السبب أيضا قالت حكمة الله: سأرسل إليهم أنبياء ورسلا، فيقتلون منهم ويضطهدون،","11:50":"حتى إن دماء جميع الأنبياء المسفوكة منذ تأسيس العالم، يطالب بها هذا الجيل،","11:51":"من دم هابيل إلى دم زكريا الذي قتل بين المذبح والقدس! أقول لكم: نعم، إن تلك الدماء يطالب بها هذا الجيل.","11:52":"الويل لكم ياعلماء الشريعة، فإنكم خطفتم مفتاح المعرفة، فلا أنتم دخلتم ولا تركتم الداخلين يدخلون! »","11:53":"وفيما هو خارج من هناك، بدأ الكتبة والفريسيون يضيقون عليه كثيرا، وأخذوا يستدرجونه إلى الكلام في أمور كثيرة،","11:54":"وهم يراقبونه سعيا إلى اصطياده بكلام يقوله.","12:1":"وفي تلك الأثناء، إذ احتشد عشرات الألوف من الشعب حتى داس بعضهم بعضا، أخذ يقول لتلاميذه أولا: «احذروا لأنفسكم من خمير الفريسيين الذي هو الريا ء!","12:2":"فما من مستور لن يكشف، ولا من سر لن يعرف.","12:3":"لذلك كل ما قلتموه في الظلام سوف يسمع في النور، وما تحدثتم به همسا في الغرف الداخلية سوف يذاع على سطوح البيوت.","12:4":"على أني أقول لكم ياأحبائي: لا تخافوا من الذين يقتلون الجسد ثم لا يستطيعون أن يفعلوا أكثر من ذلك.","12:5":"ولكني أريكم ممن تخافون: خافوا من القادر أن يلقي في جهنم بعد القتل. نعم، أقول لكم، من هذا خافوا!","12:6":"أما تباع خمسة عصافير بفلسين؟ ومع ذلك لا ينسى الله واحدا منها.","12:7":"بل إن شعر رؤوسكم كله معدود. فلا تخافوا إذن، أنتم أفضل من عصافير كثيرة!","12:8":"«ولكن أقول لكم: كل من يعترف بي أمام الناس، يعترف به ابن الإنسان أيضا أمام ملائكة الله.","12:9":"ومن أنكرني أمام الناس، ينكر أمام ملائكة الله.","12:10":"ومن قال كلمة بحق ابن الإنسان، يغفر له. وأما من جدف على الروح القدس، فلن يغفر له!","12:11":"وعندما يؤتى بكم للمثول أمام المجامع والحكام والسلطات، فلا تهتموا كيف أو بماذا تردون، ولا بما تقولون!","12:12":"فإن الروح القدس سيلقنكم في تلك الساعة عينها ما يجب أن تقولوا».","12:13":"وقال له واحد من بين الجمع: «يامعلم، قل لأخي أن يقاسمني الإرث!»","12:14":"ولكنه قال له: «ياإنسان، من أقامني عليكما قاضيا أو مقسما؟»","12:15":"وقال للجمع: «احذروا وتحفظوا من الطمع. فمتى كان الإنسان في سعة، لا تكون حياته في أمواله».","12:16":"وضرب لهم مثلا، قال «إنسان غني غلت له أرضه محاصيل وافرة.","12:17":"ففكر في نفسه قائلا: ماذا أعمل وليس عندي مكان أخزن فيه محاصيلي؟","12:18":"وقال: أعمل هذا: أهدم مخازني وأبني أعظم منها، وهناك أخزن جميع غلالي وخيراتي.","12:19":"وأقول لنفسي: يانفس، عندك خيرات كثيرة مخزونة لسنين عديدة، فاستريحي وكلي واشربي واطر بي!","12:20":"ولكن الله قال له: ياغبي، هذه الليلة تطلب نفسك منك، فلمن يبقى ما أعددته؟","12:21":"هذه هي حالة من يخزن الكنوز لنفسه ولا يكون غنيا عند الله!»","12:22":"ثم قال لتلاميذه: «لهذا السبب أقول لكم: لا تهتموا لحياتكم بما تأكلون، ولا لأجسادكم بما تكتسون.","12:23":"إن الحياة أكثر من مجرد طعام، والجسد أكثر من مجرد كساء.","12:24":"تأملوا الغربان! فهي لا تزرع ولا تحصد، وليس عندها مخزن ولا مستودع، بل يعولها الله. فكم أنتم أفضل كثيرا من الطيور.","12:25":"ولكن، أي منكم، إذا اهتم يقدر أن يطيل عمره ولو ساعة واحدة؟","12:26":"فما دمتم غير قادرين ولو على أصغر الأمور، فلماذا تهتمون بالأمور الأخرى؟","12:27":"تأملوا الزنابق كيف تنمو! فهي لا تتعب ولا تغزل، ولكني أقول لكم: حتى سليمان في قمة مجده لم يكتس ما يعادل واحدة منها بهاء؟","12:28":"فإن كان الله يكسو العشب ثوبا كهذا، مع أنه يكون اليوم في الحقل وغدا يطرح في التنور، فكم أنتم أولى من العشب (بأن يكسوكم الله ) ياقليلي الإيمان؟","12:29":"فعليكم أنتم ألا تسعوا إلى ما تأكلون وتشربون، ولا تكونوا قلقين.","12:30":"فهذه الحاجات كلها تسعى إليها أمم العالم، وأبوكم يعلم أنكم تحتاجون إليها.","12:31":"إنما اسعوا إلى ملكوته، فتزاد لكم هذه كلها.","12:32":"لا تخافوا، أيها القطيع الصغير، لأن أباكم قد سر أن يعطيكم الملكوت.","12:33":"بيعوا ما تملكون وأعطوا صدقة، واجعلوا لكم أكياسا لا تبلى، كنزا في السماوات لا ينفد، حيث لا يقترب لص ولا يفسد سوس.","12:34":"لأنه حيث يكون كنزكم، يكون قلبكم أيضا.","12:35":"لتكن أوساطكم مشدودة بالأحزمة ومصابيحكم مضاءة،","12:36":"وكونوا مثل أناس ينتظرون رجوع سيدهم من وليمة العرس، حتى إذا وصل وقرع الباب يفتحون له حالا.","12:37":"طوبى لأولئك العبيد الذين يجدهم سيدهم لدى عودته ساهرين. الحق أقول لكم: إنه يشد وسطه بالحزام ويجعلهم يتكئون ويقوم يخدمهم.","12:38":"فطوبى لهم إذا رجع في الربع الثاني أو الثالث من الليل ووجدهم على تلك الحال.","12:39":"ولكن اعلموا هذا: أنه لو كان رب البيت يعرف في أية ساعة يدهمه اللص، لكان سهر وما ترك بيته ينقب.","12:40":"فكونوا أنتم مستعدين، لأن ابن الإنسان سيعود في ساعة لا تتوقعونها».","12:41":"وسأله بطرس: «يارب، ألنا تضرب هذا المثل أم للجميع على السواء؟»","12:42":"فقال الرب: «من هو إذن الوكيل الأمين العاقل الذي يقيمه سيده على أهل بيته ليقدم لهم حصتهم من الطعام في حينها؟","12:43":"طوبى لذلك العبد الذي يجده سيده ، لدى رجوعه ، يقوم بهذا العمل.","12:44":"الحق أقول لكم: إنه يقيمه على جميع ممتلكاته.","12:45":"ولكن إذا قال ذلك العبد في نفسه: سيدي سيتأخر في رجوعه؛ وأخذ يضرب الخادمين والخادمات ويأكل ويشرب ويسكر،","12:46":"فإن سيد ذلك العبد يرجع في يوم لا يتوقعه وساعة لا يعرفها، فيمزقه ويجعل مصيره مع الخائنين.","12:47":"وأما ذلك العبد الذي يعمل بإرادة سيده، فإنه سيضرب كثيرا.","12:48":"ولكن الذي لا يعلمها ويعمل ما يستوجب الضرب، فإنه سيضرب قليلا. فكل من أعطي كثيرا، يطلب منه كثير؛ ومن أودع كثيرا، يطالب بأكثر.","12:49":"جئت لألقي على الأرض نارا، فلكم أود أن تكون قد اشتعلت؟","12:50":"ولكن لي معمودية علي أن أتعمد بها، وكم أنا متضايق حتى تتم!","12:51":"أتظنون أني جئت لأرسي السلام على الأرض؟ أقول لكم: لا، بل بالأحرى الانقسام:","12:52":"فإنه منذ الآن يكون في البيت الواحد خمسة فينقسمون: ثلاثة على اثنين، واثنان على ثلاثة،","12:53":"فالآب ينقسم على ابنه، والابن على أبيه، والأم على بنتها، والبنت على أمها، والحماة على كنتها، والكنة على حماتها!»","12:54":"وقال أيضا للجموع: «عندما ترون سحابة تطلع من الغرب، تقولون حالا: المطر آت! وهكذا يكون.","12:55":"وعندما تهب ريح الجنوب، تقولون: سيكون حر! وهكذا يكون.","12:56":"يا مراؤون! تعرفون أن تميزوا منظر الأرض والسماء، قكيف لا تميزون هذا الزمان؟","12:57":"ولماذا لا تميزون ما هو حق من تلقاء أنفسكم؟","12:58":"ففيما أنت ذاهب مع خصمك إلى المحاكمة، اجتهد في الطريق لتتصالح معه، لئلا يجرك إلى القاضي، فيسلمك القاضي إلى الشرطي، ويلقيك الشرطي في السجن.","12:59":"أقول لك: إنك لن تخرج من هناك أبدا حتى تكون قد وفيت ما عليك إلى آخر فلس!»","13:1":"وفي ذلك الوقت عينه، حضر بعضهم وأخبروه عن أهل الجليل الذين قتلهم بيلاطس فخلط دماءهم بدماء ذبائحهم.","13:2":"فرد عليهم قائلا: «أتظنون أن هؤلاء الجليليين كانوا خاطئين أكثر من أهل الجليل الباقين حتى لاقوا هذا المصير؟","13:3":"أقول لكم: لا، ولكن إن لم تتوبوا أنتم فجميعكم كذلك تهلكون!","13:4":"أم تظنون أن الثمانية عشر الذين سقط عليهم البرج في سلوام فقتلهم، كانوا مذنبين أكثر من جميع الساكنين في أورشليم؟","13:5":"أقول لكم: لا، ولكن إن لم تتوبوا أنتم فجميعكم كذلك تهلكون!»","13:6":"ثم ضرب هذا المثل: «كان عند أحدهم شجرة تين مغروسة في كرمه. فجاءها طلبا للثمر، فما وجد شيئا.","13:7":"فقال للمزارع: هذه ثلاث سنين وأنا أقصد هذه التينة طلبا للثمر فلا أجد شيئا: اقطعها، لماذا نتركها تعطل الأرض؟","13:8":"ولكن المزارع أجابه قائلا: ياسيد اتركها هذه السنة أيضا، حتى أنقب التربة من حولها وأضع سمادا.","13:9":"فلعلها تنتج ثمرا! وإلا، فبعد ذلك تقطعها!»","13:10":"وكان يعلم في أحد المجامع ذات سبت.","13:11":"وإذا هناك امرأة كان قد سكنها روح فأمرضها طيلة ثماني عشرة سنة. وكانت حدباء لا تقدر أن تنتصب أبدا.","13:12":"فلما رآها يسوع، دعاها، وقال لها: «ياامرأة، أنت في حل من دائك!»","13:13":"ووضع يديه عليها، فعادت مستقيمة في الحال، ومجدت الله !","13:14":"إلا أن رئيس المجمع، وقد ثار غضبه لأن يسوع شفى في السبت، قال للجمع: «في الأسبوع ستة أيام يسمح فيها بالعمل. ففي هذه الأيام تعالوا واستشفوا، لا في يوم السبت!»","13:15":"فرد عليه الرب قائلا: «يامراؤون! ألا يحل كل واحد منكم يوم السبت رباط ثوره أو حماره من المذود ويذهب به فيسقيه!","13:16":"وأما هذه المرأة، وهي ابنة لإبراهيم قد ربطها الشيطان طيلة ثماني عشرة سنة، أفما كان يجب أن تحل من هذا الرباط في يوم السبت؟»","13:17":"وإذ قال هذا، خجل جميع معارضيه، وفرح الجمع كله بجميع الأعمال المجيدة التي كان يجريها.","13:18":"وقال الرب: «ماذا يشبه ملكوت الله؟ وبماذا أشبهه؟","13:19":"إنه يشبه بزرة خردل أخذها إنسان وألقاها في بستانه، فنبتت وصارت شجرة عظيمة، وتآوت طيور السماء في أغصانها».","13:20":"وقال أيضا: «بماذا أشبه ملكوت الله؟","13:21":"إنه يشبه خميرة أخذتها امرأة وأخفتها في ثلاثة مقادير من الدقيق حتى اختمر العجين كله!»","13:22":"واجتاز في المدن والقرى واحدة بعد واحدة، يعلم فيها وهو مسافر إلى أورشليم.","13:23":"وسأله أحدهم: «ياسيد، أقليل عدد الذين سيخلصون؟» ولكنه قال للجميع:","13:24":"«ابذلوا الجهد للدخول من الباب الضيق، فإني أقول لكم إن كثيرين سيسعون إلى الدخول، فلا يتمكنون.","13:25":"فمن بعد ما يكون رب البيت قد قام وأغلق الباب، وتبدأون بالوقوف خارجا تقرعون الباب قائلين: يارب افتح لنا! فيجيبكم قائلا: لا أعرف من أين أنتم!","13:26":"عندئذ تبدأون تقولون: أكلنا وشربنا بحضورك، وعلمت في شوارعنا!","13:27":"وسوف يقول: أقول لكم، لا أعرف من أين أنتم؛ اغربوا من أمامي ياجميع فاعلي الإثم!","13:28":"هناك سيكون البكاء وصرير الأسنان، عندما ترون إبراهيم وإسحاق ويعقوب وجميع الأنبياء في ملكوت الله وأنتم مطروحون خارجا.","13:29":"وسيأتي أناس من الشرق والغرب، ومن الشمال والجنوب، ويتكئون في ملكوت الله.","13:30":"فإذا آخرون يصيرون أولين، وأولون يصيرون آخرين».","13:31":"في تلك الساعة نفسها، تقدم إليه بعض الفريسيين، قائلين له: «انج بنفسك! اهرب من هنا، فإن هيرودس عازم على قتلك».","13:32":"فقال لهم: «اذهبوا، قولوا لهذا الثعلب: ها أنا أطرد الشياطين وأشفي المرضى اليوم وغدا. وفي اليوم الثالث يتم بي كل شيء.","13:33":"ولكن لابد أن أكمل مسيرتي اليوم وغدا وما بعدهما، لأنه لا يمكن أن يهلك نبي إلا في أورشليم!","13:34":"ياأورشليم، ياأورشليم، ياقاتلة الأنبياء وراجمة المرسلين إليها؛ كم مرة أردت أن أجمع أولادك معا كما تجمع الدجاجة فراخها تحت جناحيها، ولكنكم لم تريدوا!","13:35":"ها إن بيتكم يترك لكم خرابا! وأقول لكم: إنكم لن تروني أبدا، حتى يأتي وقت تقولون فيه: مبارك الآتي باسم الرب!»","14:1":"وإذ دخل بيت واحد من رؤساء الفريسيين في ذات سبت ليتناول الطعام، كانوا يراقبونه.","14:2":"وإذا أمامه إنسان مصاب بالاستسقاء.","14:3":"فخاطب يسوع علماء الشريعة والفريسيين، وسألهم: «أيحل إجراء الشفاء يوم السبت أم لا؟»","14:4":"ولكنهم ظلوا صامتين. فأخذه وشفاه وصرفه.","14:5":"وعاد يسألهم: «من منكم يسقط حماره أو ثوره في بئر يوم السبت ولا ينتشله حالا؟»","14:6":"فلم يقدروا أن يجيبوه عن هذا.","14:7":"وضرب للمدعوين مثلا بعدما لاحظ كيف اختاروا أماكن الصدارة، فقال لهم:","14:8":"«عندما يدعوك أحد إلى وليمة عرس، فلا تتكيء في مكان الصدارة، إذ ربما كان قد دعا إليه من هو أرفع منك مقاما،","14:9":"فيأتي الذي دعاك ودعاه ويقول لك: أخل المكان لهذا الرجل! وعندئذ تنسحب بخجل لتأخذ المكان الأخير.","14:10":"ولكن، عندما تدعى، فاذهب واتكيء في المكان الأخير، حتى إذا جاء الذي دعاك، يقول لك: ياصديقي، قم إلى الصدر! وعندئذ يرتفع قدرك في نظر المتكئين معك.","14:11":"فإن كل من يرفع نفسه يوضع، ومن يضع نفسه يرفع».","14:12":"وقال أيضا للذي دعاه: «عندما تقيم غداء أو عشاء، فلا تدع أصدقاءك ولا إخوتك ولا أقرباءك ولا جيرانك الأغنياء، لئلا يدعوك هم أيضا بالمقابل، فتكون قد كوفئت.","14:13":"ولكن، عندما تقيم وليمة ادع الفقراء والمعاقين والعرج والعمي؛","14:14":"فتكون مباركا لأن هؤلاء لا يملكون ما يكافئونك به، فإنك تكافأ في قيامة الأبرار».","14:15":"فلما سمع هذا أحد المتكئين، قال له: «طوبى لمن سيتناول الطعام في ملكوت الله!»","14:16":"فقال له: «أقام إنسان عشاء عظيما، ودعا كثيرين.","14:17":"ثم أرسل عبده ساعة العشاء ليقول للمدعوين: تعالوا، فكل شيء جاهز!","14:18":"فبدأ الجميع يعتذرون على السواء. فقال له أولهم: اشتريت حقلا، وعلي أن أذهب وأراه أرجو منك أن تعذرني!","14:19":"وقال غيره: اشتريت خمسة أزواج بقر، وأنا ذاهب لأجربها أرجو منك أن تعذرني!","14:20":"وقال آخر: تزوجت بامرأة، ولذلك لا أقدر أن أحضر!","14:21":"فرجع العبد وأخبر سيده بذلك. عندئذ غضب رب البيت وقال لعبده: اخرج سريعا إلى شوارع المدينة وأزقتها، وأحضر الفقراء والمعاقين والعرج والعمي إلى هنا!","14:22":"(فرجع) الخادم يقول: ياسيد، قد جرى ما أمرت به، ويوجد بعد مكان.","14:23":"فقال السيد للعبد: اخرج إلى الطرق والسياجات وأجبر الناس على الدخول حتى يمتليء بيتي،","14:24":"فإني أقول لكم: إن واحدا من أولئك المدعوين لن يذوق عشائي!»","14:25":"وكانت جموع كثيرة تسير معه، فالتفت وقال لهم:","14:26":"«إن جاء إلي أحد، ولم يبغض أباه وأمه وزوجته وأولاده وإخوته وأخواته، بل نفسه أيضا، فلا يمكنه أن يكون تلميذا لي.","14:27":"ومن لا يحمل صليبه ويتبعني، فلا يمكنه أن يكون تلميذا لي.","14:28":"فأي منكم، وهو راغب في أن يبني برجا، لا يجلس أولا ويحسب الكلفة ليرى هل عنده ما يكفي لإنجازه؟","14:29":"وذلك لئلا يضع له الأساس ولا يقدر أن ينجزه. أفلا يأخذ جميع الناظرين يسخرون منه.","14:30":"قائلين: هذا الإنسان شرع يبني وعجز عن الإنجاز؟","14:31":"أم أي ملك ذاهب لمحاربة آخر، لا يجلس أولا ويستشير ليرى هل يقدر أن يواجه بعشرة آلاف ذلك الزاحف عليه بعشرين ألفا.","14:32":"وإلا فإنه، والعدو مازال بعيدا، يرسل إليه وفدا، طالبا ما يؤول إلى الصلح.","14:33":"هكذا إذن، كل واحد منكم لا يهجر كل ما يملكه، لا يمكنه أن يكون تلميذا لي.","14:34":"إنما الملح جيد. ولكن إذا فقد الملح طعمه، فبماذا تعاد إليه ملوحته؟","14:35":"إنه لا يصلح لا للتربة ولا للسماد، فيطرح خارجا. من له أذنان للسمع، فليسمع!»","15:1":"وكان جميع جباة الضرائب والخاطئين يتقدمون إليه ليسمعوه.","15:2":"فتذمر الفريسيون والكتبة قائلين: «هذا الإنسان يرحب بالخاطئين ويأكل معهم!»","15:3":"فضرب لهم هذا المثل قائلا:","15:4":"«أي إنسان منكم عنده مئة خروف وأضاع واحدا منها، ألا يترك التسعة والتسعين في البرية ويذهب يبحث عن الخروف الضائع حتى يجده؟","15:5":"وبعد أن يجده، يحمله على كتفيه فرحا،","15:6":"ثم يعود إلى البيت، ويدعو الأصدقاء والجيران، قائلا لهم: افرحوا معي، لأني وجدت خروفي الضائع !","15:7":"أقول لكم إنه هكذا يكون في السماء فرح بخاطيء واحد تائب أكثر من تسعة وتسعين بارا لا يحتاجون إلى توبة!","15:8":"أم أية امرأة عندها عشرة دراهم، إذا أضاعت درهما واحدا، ألا تشعل مصباحا وتكنس البيت وتبحث بانتباه حتى تجده؟","15:9":"وبعد أن تجده، تدعو الصديقات والجارات قائلة: افرحن معي، لأني وجدت الدرهم الذي أضعته.","15:10":"أقول لكم: هكذا يكون بين ملائكة الله فرح بخاطيء واحد يتوب».","15:11":"وقال: «كان لإنسان ابنان.","15:12":"فقال أصغرهما لأبيه: ياأبي، أعطني الحصة التي تخصني من الميراث! فقسم لهما كل ما يملكه.","15:13":"وبعد بضعة أيام، جمع الابن الأصغر كل ما عنده، ومضى إلى بلد بعيد. وهنالك بذر حصته من المال في عيشة الخلاعة.","15:14":"ولكن لما أنفق كل شيء، اجتاحت ذلك البلد مجاعة قاسية، فأخذ يشعر بالحاجة.","15:15":"فذهب والتحق بواحد من مواطني ذلك البلد، فأرسله إلى حقوله ليرعى خنازير.","15:16":"وكم اشتهى لو يملأ بطنه من الخرنوب الذي كانت الخنازير تأكله، فما أعطاه أحد!","15:17":"ثم رجع إلى نفسه، وقال: ما أكثر خدام أبي المأجورين الذين يفضل عنهم الخبز، وأنا هنا أكاد أهلك جوعا!","15:18":"سأقوم وأرجع إلى أبي، وأقول له: ياأبي، أخطأت إلى السماء وأمامك؛","15:19":"ولا أستحق بعد أن أدعى ابنا لك: اجعلني كواحد من خدامك المأجورين!","15:20":"فقام ورجع إلى أبيه. ولكن أباه رآه وهو مازال بعيدا، فتحنن، وركض إليه وعانقه وقبله بحرارة.","15:21":"فقال له الابن. ياأبي، أخطأت إلى السماء وأمامك، ولا أستحق بعد أن أدعى ابنا لك…","15:22":"أما الأب فقال لعبيده: أحضروا سريعا أفضل ثوب وألبسوه، وضعوا في إصبعه خاتما وفي قدميه حذاء.","15:23":"وأحضروا العجل المسمن واذبحوه؛ ولنأكل ونفرح:","15:24":"فإن ابني هذا كان ميتا فعاش، وكان ضائعا فوجد. فأخذوا يفرحون!","15:25":"وكان ابنه الأكبر في الحقل. فلما جاء واقترب من البيت، سمع موسيقى ورقصا.","15:26":"فدعا واحدا من الخدام واستفسره ما عسى أن يكون ذلك.","15:27":"فأجابه: رجع أخوك، فذبح أبوك العجل المسمن لأنه استعاده سالما!","15:28":"ولكنه غضب ورفض أن يدخل. فخرج أبوه وتوسل إليه.","15:29":"غير أنه رد على أبيه قائلا: ها أنا أخدمك هذه السنين العديدة، ولم أخالف لك أمرا، ولكنك لم تعطني ولو جديا واحدا لأفرح مع أصدقائي.","15:30":"ولكن لما عاد ابنك هذا الذي أكل مالك مع الفاجرات، ذبحت له العجل المسمن!","15:31":"فقال له: يابني، أنت معي دائما، وكل ما أملكه هو لك!","15:32":"ولكن كان من الصواب أن نفرح ونبتهج، لأن أخاك هذا كان ميتا فعاش، وكان ضالا فوجد!»","16:1":"وقال أيضا لتلاميذه: «كان لإنسان غني وكيل. فاتهم لديه بأنه يبذر أمواله.","16:2":"فاستدعاه وسأله: ما هذا الذي أسمع عنك؟ قدم حساب وكالتك، فإنك لا يمكن أن تكون وكيلا لي بعد!","16:3":"فقال الوكيل في نفسه: ما عسى أن أعمل، مادام سيدي سينزع عني الوكالة؟ لا أقوى على نقب الأرض؛ وأستحي أن أستعطي!","16:4":"قد علمت ماذا أعمل، حتى إذا عزلت عن الوكالة، يستقبلني الأصدقاء في بيوتهم.","16:5":"فاستدعى مديوني سيده واحدا فواحدا. وسأل أولهم: كم عليك لسيدي؟","16:6":"فأجاب: مئة بث من الزيت. فقال له: خذ صكك، واجلس سريعا، واكتب خمسين!","16:7":"ثم قال للآخر: وأنت، كم عليك؟ فأجاب: مئة كر من القمح. فقال له: خذ صكك، واكتب ثمانين!","16:8":"فامتدح السيد وكيله الخائن لأنه تصرف بحكمة. فإن أبناء هذا العالم أحكم مع أهل جيلهم من أبناء النور.","16:9":"وأقول لكم: اكسبوا لكم أصدقاء بمال الظلم، حتى إذا فني مالكم، تقبلون في المنازل الأبدية!","16:10":"إن الأمين في القليل أمين أيضا في الكثير، والخائن في القليل خائن أيضا في الكثير.","16:11":"فإن لم تكونوا أمناء في مال الظلم، فمن يأتمنكم على مال الحق؟","16:12":"وإن لم تكونوا أمناء في ما يخص غيركم، فمن يعطيكم ما يخصكم؟","16:13":"ما من خادم يقدر أن يكون عبدا لسيدين: فإنه إما أن يبغض أحدهما، فيحب الآخر؛ وإما أن يلتحق بأحدهما، فيهجر الآخر. لا تستطيعون أن تكونوا عبيدا لله والمال معا».","16:14":"وكان الفريسيون أيضا، وهم محبون للمال، يسمعون ذلك كله، فاستهزأوا به.","16:15":"فقال لهم: «إنكم تبررون أنفسكم أمام الناس، ولكن الله يعرف قلوبكم. فما يعتبره الناس رفيع القدر، هو رجس عند الله.","16:16":"ظلت الشريعة والأنبياء حتى زمن يوحنا: ومنذ ذلك الوقت يبشر بملكوت الله، وكل واحد يشق طريقه باجتهاد للدخول إليه.","16:17":"على أن زوال السماء والأرض أسهل من سقوط نقطة واحدة من الشريعة:","16:18":"كل من يطلق زوجته ويتزوج بأخرى، يرتكب الزنى. وكل من يتزوج بمطلقة من زوجها يرتكب الزنى.","16:19":"كان هنالك إنسان غني، يلبس الأرجوان وناعم الثياب، ويقيم الولائم المترفة، متنعما كل يوم.","16:20":"وكان إنسان مسكين اسمه لعازر، مطروحا عند بابه وهو مصاب بالقروح،","16:21":"يشتهي أن يشبع من الفتات المتساقط من مائدة الغني. حتى الكلاب كانت تأتاي وتلحس قروحه.","16:22":"ومات المسكين، وحملته الملائكة إلى حضن إبراهيم. ثم مات الغني أيضا ودفن.","16:23":"وإذ رفع عينيه وهو في الهاوية يتعذب، رأى إبراهيم من بعيد ولعازر في حضنه.","16:24":"فنادى قائلا: ياأباي إبراهيم! ارحمني، وأرسل لعازر ليغمس طرف إصبعه في الماء ويبرد لساني: فإني معذب في هذا اللهيب.","16:25":"ولكن إبراهيم قال: يابني، تذكر أنك نلت خيراتك كاملة في أثناء حياتك، ولعازر نال البلايا. ولكنه الآن يتعزى هنا، وأنت هناك تتعذب.","16:26":"وفضلا عن هذا كله، فإن بيننا وبينكم هوة عظيمة قد أثبتت، حتى إن الذين يريدون العبور من هنا لا يقدرون، ولا الذين من هناك يستطيعون العبور إلينا!","16:27":"فقال: ألتمس منك إذن، ياأبي، أن ترسله إلى بيت أبي،","16:28":"فإن عندي خمسة إخوة، حتى يشهد لهم منذرا، لئلا يأتوا هم أيضا إلى مكان العذاب هذا.","16:29":"ولكن إبراهيم قال له: عندهم موسى والأنبياء: فليسمعوا لهم!","16:30":"فقال له: لا ياأبي إبراهيم، بل إذا ذهب إليهم واحد من بين الأموات يتوبون!","16:31":"فقال له: إن كانوا لا يسمعون لموسى والأنبياء، فلا يقتنعون حتى لو قام واحد من بين الأموات!»","17:1":"وقال لتلاميذه: «لابد من أن تأتي العثرات. ولكن الويل لمن تأتي على يده!","17:2":"كان أنفع له لو علق حول عنقه حجر رحى وطرح في البحر، من أن يكون عثرة لأحد هؤلاء الصغار.","17:3":"خذوا الحذر لأنفسكم: إن أخطأ أخوك، فعاتبه. فإذا تاب، فاغفر له.","17:4":"وإن أخطأ إليك سبع مرات في اليوم، وعاد إليك سبع مرات قائلا: أنا تائب! فعليك أن تغفر له».","17:5":"وقال الرسل للرب: «زدنا إيمانا!»","17:6":"ولكن الرب قال: «لو كان عندكم إيمان مثل بزرة الخردل، لكنتم تقولون لشجرة التوت هذه: انقلعي وانغرسي في البحر ! فتطيعكم!","17:7":"«ولكن، أي واحد منكم يكون عنده عبد يحرث أو يرعى، فيقول له لدى رجوعه من الحقل: تقدم في الحال واتكيء؟","17:8":"ألا يقول له بالأحرى: أحضر لي ما أتعشى به، وشد وسطك بالحزام واخدمني حتى آكل وأشرب وبعد ذلك تأكل وتشرب أنت؟","17:9":"وهل يشكر العبد لأنه عمل ما أمر به؟","17:10":"هكذا أنتم أيضا، عندما تعملون كل ما تؤمرون به، قولوا: إنما نحن عبيد غير نافعين، قد عملنا ما كان واجبا علينا!»","17:11":"وفيما هو صاعد إلى أورشليم، مر في وسط منطقتي السامرة والجليل.","17:12":"ولدى دخوله إحدى القرى، لاقاه عشرة رجال مصابين بالبرص. فوقفوا من بعيد،","17:13":"ورفعوا الصوت قائلين: «يايسوع، ياسيد، ارحمنا!»","17:14":"فرآهم، وقال لهم: «اذهبوا واعرضوا أنفسكم على الكهنة!» وفيما كانوا ذاهبين، طهروا.","17:15":"فلما رأى واحد منهم أنه قد طهر، عاد وهو يمجد الله بصوت عال،","17:16":"وخر على وجهه عند قدميه مقدما له الشكر. وكان هذا سامريا.","17:17":"فتكلم يسوع قائلا: «أما طهر العشرة؟ فأين التسعة؟","17:18":"ألم يوجد من يعود ويقدم المجد لله سوى هذا الأجنبي؟»","17:19":"ثم قال له: «قم وامض في سبيلك: إن إيمانك قد خلصك!»","17:20":"وإذ سأله الفريسيون: «متى يأتي ملكوت الله؟» أجابهم قائلا: «إن ملكوت الله لا يأتي بعلامة منظورة.","17:21":"ولا يقال: ها هو هنا، أو: ها هو هناك! فها إن ملكوت الله في داخلكم!»","17:22":"ثم قال لتلاميذه: «سيأتي زمان تتشوقون فيه أن تروا ولو يوما واحدا من أيام ابن الإنسان، ولن تروا.","17:23":"وسوف يقول بعضهم لكم: ها هو هناك، أو: ها هو هنا؛ فلا تذهبوا ولا تتبعوهم:","17:24":"فكما أن البرق الذي يلمع تحت السماء من إحدى الجهات يضيء في جهة أخرى، هكذا يكون ابن الإنسان يوم يعود.","17:25":"ولكن لابد له أولا من أن يعاني آلاما كثيرة وأن يرفضه هذا الجيل!","17:26":"وكما حدث في زمان نوح، هكذا أيضا سوف يحدث في زمان ابن الإنسان:","17:27":"كان الناس يأكلون ويشربون ويتزوجون ويزوجون، إلى اليوم الذي فيه دخل نوح السفينة وجاء الطوفان فأهلك الجميع.","17:28":"وكذلك، كما حدث في زمان لوط: كانوا يأكلون ويشربون ويشترون ويبيعون ويغرسون ويبنون،","17:29":"ولكن في اليوم الذي فيه خرج لوط من سدوم، أمطر (الله ) من السماء نارا وكبريتا، فأهلك الجميع","17:30":"هكذا سيحدث في يوم ظهور ابن الإنسان.","17:31":"فمن كان في ذلك اليوم على السطح وأمتعته في البيت، فلا ينزل ليأخذها؛ ومن كان في الحقل كذلك، فلا يرجع إلى الوراء.","17:32":"تذكروا زوجة لوط!","17:33":"من يسعى لإنقاذ حياته يفقدها، ومن فقدها يحافظ عليها.","17:34":"أقول لكم: في تلك الليلة يكون اثنان نائمين على سرير واحد، فيؤخذ الواحد ويترك الآخر؛","17:35":"وتكون اثنتان تطحنان معا، فتؤخذ الواحدة وتترك الأخرى؛","17:36":"ويكون اثنان في الحقل، فيؤخذ الواحد ويترك الآخر».","17:37":"فردوا سائلين: «أين، يارب؟» فقال لهم: «حيث تكون الجيفة، هناك تتجمع النسور!»","18:1":"وضرب لهم مثلا في وجوب الصلاة دائما ودون ملل،","18:2":"قال: «كان في مدينة قاض لا يخاف الله ولا يحترم إنسانا.","18:3":"وكان في تلك المدينة أرملة كانت تأتي إليه قائلة: أنصفني من خصمي!","18:4":"فظل يرفض طلبها مدة من الزمن. ولكنه بعد ذلك قال في نفسه: حتى لو كنت لا أخاف الله ولا أحترم إنسانا،","18:5":"فمهما يكن، فلأن هذه الأرملة تزعجني سأنصفها، لئلا تأتي دائما فتصدع رأسي!»","18:6":"وقال الرب: «اسمعوا ما يقوله القاضي الظالم.","18:7":"أفلا ينصف الله مختاريه الذين يصرخون إليه نهارا وليلا؟ أما يسرع في الاستجابة لهم؟","18:8":"أقول لكم: إنه ينصفهم سريعا. ولكن، عندما يعود ابن الإنسان، أيجد إيمانا على الأرض؟»","18:9":"وضرب أيضا هذا المثل لأناس يثقون في أنفسهم بأنهم أبرار ويحتقرون الآخرين:","18:10":"«صعد إنسانان إلى الهيكل ليصليا، أحدهما فريسي والآخر جابي ضرائب.","18:11":"فوقف الفريسي يصلي في نفسه هكذا: أشكرك، ياالله ، لأني لست مثل باقي الناس الطماعين الظالمين الزناة، ولا مثل جابي الضرائب هذا:","18:12":"أصوم مرتين في الأسبوع، وأقدم عشر كل ما أجنيه!","18:13":"ولكن جابي الضرائب، وقف من بعيد وهو لا يجرؤ أن يرفع عينيه نحو السماء، بل قرع صدره قائلا: ارحمني، ياالله ، أنا الخاطيء!","18:14":"أقول لكم: إن هذا الإنسان نزل إلى بيته مبررا، بعكس الآخر. فإن كل من يرفع نفسه يوضع؛ ومن يضع نفسه يرفع».","18:15":"وأحضر بعضهم أطفالا أيضا ليلمسهم. ولكن التلاميذ لما رأوهم زجروهم.","18:16":"أما يسوع فدعاهم إليه وقال: «دعوا الصغار يأتون إلي، ولا تمنعوهم: لأن لمثل هؤلاء ملكوت الله !","18:17":"الحق أقول لكم: من لا يقبل ملكوت الله كأنه ولد صغير، فلن يدخله أبدا!»","18:18":"وسأله واحد من الرؤساء قائلا: «أيها المعلم الصالح، ماذا أعمل لأرث الحياة الأبدية؟»","18:19":"ولكن يسوع قال له: «لماذا تدعوني الصالح؟ ليس أحد صالحا إلا واحد، وهو الله !","18:20":"أنت تعرف الوصايا: لا تزن؛ لا تقتل؛ لا تسرق؛ لا تشهد بالزور؛ أكرم أباك وأمك!»","18:21":"فقال: «هذه كلها عملت بها منذ صغري!»","18:22":"فلما سمع يسوع هذا، قال له: «ينقصك شيء واحد: بع كل ما عندك، ووزع على الفقراء، فيكون لك كنز في السماوات. ثم تعال اتبعني!»","18:23":"ولكنه لما سمع ذلك، حزن حزنا شديدا، لأنه كان غنيا جدا.","18:24":"فلما رأى يسوع ذلك منه، قال: «ما أصعب دخول الأغنياء إلى ملكوت الله!","18:25":"فإن مرور جمل في ثقب إبرة أسهل من دخول غني إلى ملكوت الله».","18:26":"فقال الذين سمعوا ذلك: «إذن، من يقدر أن يخلص؟»","18:27":"فقال: «إن المستحيل عند الناس مستطاع عند الله!»","18:28":"فقال بطرس: «ها نحن قد تركنا كل شيء وتبعناك!»","18:29":"فقال لهم: «الحق أقول لكم: ما من أحد ترك بيتا، أو زوجة، أو إخوة أو والدين، أو أولادا، من أجل ملكوت الله،","18:30":"إلا وينال أضعاف ذلك في هذا الزمان، وينال في الزمان الآتي الحياة الأبدية!»","18:31":"ثم انتحى بالاثني عشر وقال لهم: «ها نحن صاعدون إلى أورشليم، وسوف تتم جميع الأمور التي كتبها الأنبياء عن ابن الإنسان.","18:32":"فإنه سيسلم إلى أيدي الأمم، فيستهزأ به ويهان ويبصق عليه.","18:33":"وبعد أن يجلدوه يقتلونه. وفي اليوم الثالث يقوم!»","18:34":"ولكنهم لم يفهموا شيئا من ذلك. وكان هذا الأمر خافيا عنهم، ولم يدركوا ما قيل.","18:35":"ولما وصل إلى جوار أريحا، كان أحد العميان جالسا على جانب الطريق يستعطي.","18:36":"فلما سمع مرور الجمع، استخبر عما عسى أن يكون ذلك.","18:37":"فقيل له: «إن يسوع الناصري مار من هناك».","18:38":"فنادى قائلا «يايسوع ابن داود، ارحمني!","18:39":"فزجره السائرون في المقدمة ليسكت. ولكنه أخذ يزيد صراخا أكثر: «يا ابن داود، ارحمني!»","18:40":"فتوقف يسوع وأمر أن يؤتى به إليه. فلما اقترب سأله:","18:41":"«ماذا تريد أن أفعل لك؟» فقال: «يارب، أن ترد لي البصر!»","18:42":"فقال له يسوع: «أبصر! إيمانك قد شفاك».","18:43":"وفي الحال أبصر، وتبعه وهو يمجد الله. ولما رأى جميع الشعب ذلك، سبحوا الله.","19:1":"ثم دخل أريحا واجتاز فيها.","19:2":"وإذا هناك رجل اسمه زكا، رئيس لجباة الضرائب، وكان غنيا.","19:3":"وقد سعى أن يرى من هو يسوع، فلم يقدر بسبب الزحام، لأنه كان قصير القامة.","19:4":"فتقدم راكضا وتسلق شجرة جميز لعله يرى يسوع، فقد كان سيمر من هناك.","19:5":"فلما وصل يسوع إلى ذلك المكان، رفع نظره ورآه، فقال له: «يا زكا، أسرع وانزل، لأنه لابد أن أقيم اليوم في بيتك!»","19:6":"فأسرع ونزل واستقبله بفرح.","19:7":"فلما رأى الجميع ذلك، تذمروا قائلين: «قد دخل ليبيت عند رجل خاطيء!»","19:8":"ولكن زكا وقف وقال للرب: «يارب، ها أنا أعطي نصف أموالي للفقراء. وإن كنت قد اغتصبت شيئا من أحد، أرد له أربعة أضعاف!»","19:9":"فقال له يسوع: «اليوم تم الخلاص لهذا البيت، إذ هو أيضا ابن إبراهيم.","19:10":"فإن ابن الإنسان قد جاء ليبحث عن الهالكين ويخلصهم».","19:11":"وبينما هم يستمعون إلى هذا الكلام، عاد فضرب مثلا، لأنه كان قد اقترب من أورشليم وكانوا يظنون أن ملكوت الله على وشك أن يعلن حالا،","19:12":"فقال: «ذهب إنسان نبيل إلى بلد بعيد ليتسلم له ملكا ثم يعود.","19:13":"فاستدعى عبيده العشرة، وأودعهم عشر وزنات، وقال لهم: تاجروا إلى أن أعود.","19:14":"ولكن أهل بلده كانوا يبغضونه، فأرسلوا في إثره وفدا، قائلين: لا نريد أن يملك هذا علينا!","19:15":"ولدى عودته بعدما تسلم الملك، أمر أن يدعى إليه هؤلاء العبيد الذين أودعهم المال، ليعرف ما ربحه كل واحد منهم بتجارته.","19:16":"فتقدم الأول قائلا: ياسيد، إن وزنتك ربحت عشر وزنات!","19:17":"فقال له: حسنا فعلت أيها العبد الصالح. فلأنك كنت أمينا في ما هو قليل، فكن واليا على عشر مدن!","19:18":"وتقدم الثاني قائلا: ياسيد، إن وزنتك ربحت خمس وزنات!","19:19":"فقال لهذا أيضا: وكن أنت واليا على خمس مدن!","19:20":"ثم تقدم عبد آخر قائلا: ياسيد، ها هي وزنتك التي حفظتها مطوية في منديل.","19:21":"فقد كنت أخاف منك لأنك إنسان قاس، تستوفي ما لم تستودعه، وتحصد ما لم تزرعه!","19:22":"فقال له: من فمك سأحكم عليك أيها العبد الشرير: عرفت أني إنسان قاس، أستوفي ما لم أستودعه، وأحصد ما لم أزر عه.","19:23":"فلماذا لم تودع مالي في المصرف، فكنت أستوفيه مع الفائدة عند عودتي؟","19:24":"ثم قال للواقفين هناك: خذوا منه الوزنة وأعطوها لصاحب الوزنات العشر ..","19:25":"فقالوا له: ياسيد، إن عنده عشر وزنات! فقال:","19:26":"إني أقول لكم إن كل من عنده يعطى المزيد؛ وأما من ليس عنده، فحتى الذي عنده ينتزع منه.","19:27":"وأما أعدائي أولئك الذين لم يريدوا أن أملك عليهم، فأحضروهم إلى هنا واذبحوهم قدامي!»","19:28":"وبعدما قال هذا الكلام، تقدم صاعدا إلى أورشليم.","19:29":"ولما اقترب من بيت فاجي وبيت عنيا، عند الجبل المعروف بجبل الزيتون، أرسل اثنين من تلاميذه، قائلا:","19:30":"«اذهبا إلى القرية المقابلة لكما، وعندما تدخلانها تجدان جحشا مربوطا لم يركب عليه أحد من الناس قط، فحلا رباطه، وأحضراه إلى هنا.","19:31":"وإن سألكما أحد: لماذا تحلان رباطه؟ فقولا له هكذا: لأن الرب بحاجة إليه!»","19:32":"فذهب التلميذان اللذان أرسلا في طريقهما ووجدا كما قال الرب لهما.","19:33":"وفيما كانا يحلان رباط الجحش، سألهما أصحابه: «لماذا تحلان رباط الجحش؟»","19:34":"فقالا: «لأن الرب بحاجة إليه!»","19:35":"ثم أحضراه إلى يسوع؛ ووضعا ثيابهما على الجحش وأركبا يسوع.","19:36":"وبينما هو سائر، أخذوا يفرشون الطريق بثيابهم.","19:37":"ولما اقترب (من أورشليم) إذ وصل إلى منحدر جبل الزيتون، أخذ جماعة التلاميذ يهتفون جميعا بفرح مسبحين الله بصوت عال على جميع المعجزات التي شاهدوها،","19:38":"فيقولون: «مبارك الملك الآتي باسم الرب! سلام في السماء ومجد في الأعالي!»","19:39":"ولكن بعض الفريسيين من الجمع قالوا له: «يامعلم، ازجر تلاميذك!»","19:40":"فأجابهم قائلا: «أقول لكم: إن سكت هؤلاء، هتفت الحجارة!»","19:41":"ولما اقترب، ورأى المدينة، بكى عليها،","19:42":"قائلا: «ليتك أنت أيضا، في يومك هذا، عرفت ما فيه سلامك! ولكن ذلك محجوب الآن عن عينيك.","19:43":"فستأتي عليك أيام يحاصرك فيها أعداؤك بالمتاريس، ويطبقون عليك، ويشددون عليك الحصار من كل جهة،","19:44":"ويهدمونك على أبنائك الذين فيك، فلا يتركون فيك حجرا فوق حجر: لأنك لم تعرفي وقت افتقاد الله لك».","19:45":"ولدى دخوله الهيكل، أخذ يطرد الذين كانوا يبيعون فيه ويشترون،","19:46":"قائلا لهم: «قد كتب: إن بيتي هو بيت للصلاة. أما أنتم، فقد جعلتموه مغارة لصوص!»","19:47":"وكان يعلم يوما فيوما في الهيكل. وسعى رؤساء الكهنة والكتبة ووجهاء الشعب إلى قتله.","19:48":"ولكنهم لم يهتدوا إلى ما يفعلون، لأن الشعب كله كان ملتصقا به للاستماع إليه.","20:1":"وفيما كان يعلم الشعب في الهيكل ذات يوم، ويبشر، تصدى له رؤساء الكهنة والكتبة مع الشيوخ،","20:2":"وخاطبوه قائلين: «قل لنا بأية سلطة تفعل ما فعلت؟ أو من منحك هذه السلطة؟»","20:3":"فأجابهم يسوع قائلا: «وأنا أيضا أسألكم أمرا واحدا، فأجيبوني عنه:","20:4":"أمن السماء كانت معمودية يوحنا أم من الناس؟»","20:5":"فتشاوروا فيما بينهم قائلين: «إن قلنا: من السماء، يقول: ولماذا لم تؤمنوا به؟","20:6":"وإن قلنا: من الناس، يرجمنا الشعب كله، لأنهم مقتنعون أن يوحنا كان نبيا».","20:7":"فأجابوا أنهم لا يعرفون من أين هي.","20:8":"فقال لهم يسوع: «وأنا لا أقول لكم بأية سلطة أفعل ما فعلت!»","20:9":"وأخذ يكلم الشعب بهذا المثل: «غرس إنسان كرما وسلمه إلى مزارعين، وسافر مدة طويلة.","20:10":"وفي موسم القطاف أرسل إلى المزارعين عبدا، لكي يعطوه من ثمر الكرم. ولكن المزارعين ضربوه وردوه فارغ اليدين.","20:11":"فعاد وأرسل عبدا آخر. إلا أنهم ضربوه أيضا وأهانوه وردوه فارغ اليدين.","20:12":"ثم عاد وأرسل عبدا ثالثا، فجرحوه وطرحوه خارج الكرم.","20:13":"فقال رب الكرم: ماذا أفعل؟ سأرسل ابني الحبيب، لعلهم يهابونه!","20:14":"ولكن ما إن رآه المزارعون، حتى تشاوروا فيما بينهم قائلين: هذا هو الوريث. فلنقتله ليصير الميراث لنا.","20:15":"فطرحوه خارج الكرم وقتلوه. فماذا إذن يفعل رب الكرم بهم؟","20:16":"إنه يأتي ويهلك أولئك المزارعين، ويسلم الكرم إلى غيرهم».","20:17":"ولكنه نظر إليهم وقال: «إذن ما معنى هذه الآية المكتوبة: الحجر الذي رفضه البناة، هو نفسه صار حجر الزاوية؟","20:18":"من يقع على هذا الحجر يتكسر، ومن يقع الحجر عليه يسحقه سحقا؟»","20:19":"فسعى رؤساء الكهنة والكتبة إلى إلقاء القبض عليه في تلك الساعة عينها، ولكنهم خافوا الشعب، فقد أدركوا أنه عناهم بهذا المثل.","20:20":"فجعلوا يراقبونه، وبثوا حوله جواسيس يتظاهرون أنهم أبرار، لكي يمسكوه بكلمة يقولها، فيسلموه إلى قضاء الحاكم وسلطته.","20:21":"فقالوا يسألونه: «يامعلم، نعلم أنك تتكلم وتعلم بالصدق، فلا تراعي مقامات الناس، بل تعلم طريق الله بالحق:","20:22":"أفيحل لنا أن ندفع الجزية للقيصر، أم لا؟»","20:23":"فأدرك مكرهم، وقال لهم:","20:24":"«أروني دينارا: لمن الصورة والنقش عليه؟» فأجابوا: «للقيصر!»","20:25":"فقال لهم: «إذن، أعطوا ما للقيصر للقيصر، وما لله لله».","20:26":"فلم يتمكنوا من الإيقاع به أمام الشعب بكلمة يقولها، فسكتوا مدهوشين مما سمعوا.","20:27":"وتصدى له بعض الصدوقيين الذين ينكرون أمر القيامة، وسألوه قائلين:","20:28":"«يامعلم، كتب لنا موسى: إن مات لأحد أخ متزوج وليس له ولد، فعلى أخيه أن يتزوج بأرملته ويقيم نسلا على اسم أخيه.","20:29":"فقد كان هناك سبعة إخوة، اتخذ أولهم زوجة ثم مات دون ولد،","20:30":"فتزوج الثاني بالأرملة،","20:31":"ثم اتخذها الثالث ... حتى تزوج بها السبعة وماتوا دون أن يخلفوا ولدا.","20:32":"ومن بعدهم جميعا ماتت المرأة أيضا.","20:33":"ففي القيامة لمن منهم تكون المرأة زوجة، فقد كانت زوجة لكل من السبعة».","20:34":"فرد عليهم يسوع قائلا: «أبناء الزمان الحاضر يزوجون ويزوجون.","20:35":"أما الذين حسبوا أهلا للمشاركة في الزمان الآتي والقيامة من بين الأموات، فلا يزوجون ولا يزوجون.","20:36":"إذ لا يمكن أن يموتوا أيضا بعد ذلك، لأنهم يكونون مثل الملائكة، وهم أبناء الله لكونهم أبناء القيامة.","20:37":"وأما أن الموتى يقومون، فحتى موسى أشار إلى ذلك في الحديث عن العليقة، حيث يدعو الرب إله إبراهيم وإله إسحق وإله يعقوب.","20:38":"ولكن الله ليس إله أموات بل هو إله أحياء، فإن الجميع يحيون لديه!»","20:39":"فقال بعض الكتبة: «يامعلم، أحسنت الكلام!»","20:40":"ولم يجرؤ أحد بعد ذلك أن يسأله شيئا.","20:41":"وقال لهم: «كيف يقال إن المسيح هو ابن داود،","20:42":"فيما يقول داود نفسه في كتاب المزامير: قال الرب لربي: اجلس عن يميني","20:43":"حتى أضع أعداءك موطئا لقدميك؟","20:44":"إذن، داود يدعوه ربا، فكيف يكون ابنه؟»","20:45":"وفيما كان جميع الشعب يصغون، قال لتلاميذه:","20:46":"«احذروا من الكتبة الذين يرغبون التجول بالأثواب الفضفاضة، ويحبون تلقي التحيات في الساحات العامة، وصدور المجالس في المجامع، وأماكن الصدارة في الولائم؛","20:47":"يلتهمون بيوت الأرامل ويتذرعون بإطالة الصلوات. هؤلاء ستنزل بهم دينونة أقسى!»","21:1":"وتطلع فرأى الأغنياء يلقون تقدماتهم في صندوق الهيكل.","21:2":"ورأى أيضا أرملة فقيرة تلقي فيه فلسين.","21:3":"فقال: «الحق أقول لكم إن هذه الأرملة الفقيرة قد ألقت أكثر منهم جميعا.","21:4":"لأن هؤلاء جميعا قد ألقوا في التقدمات من الفائض عنهم. وأما هي، فمن حاجتها ألقت كل ما تملكه لمعيشتها!»","21:5":"وإذ تحدث بعضهم عن الهيكل بأنه مزين بالحجارة الجميلة وتحف النذور،","21:6":"قال: «إن هذا الذي ترونه، ستأتي أيام لا يبقى فيها حجر منه فوق حجر إلا ويهدم».","21:7":"فسألوه قائلين: «يامعلم، متى يحدث هذا؟ وما هي العلامة التي تظهر حين يقترب وقوعه؟»","21:8":"فقال: «انتبهوا! لا تضلوا! فإن كثيرين سيأتون باسمي قائلين إني أنا هو وإن الزمان قد اقترب: فلا تتبعوهم!","21:9":"وعندما تسمعون بالحروب والاَضطرابات، فلا ترتعبوا، لأن هذه الأمور لابد من حدوثها أولا، ولكن النهاية لا تأتي حالا بعدها!»","21:10":"ثم قال لهم: «ستنقلب أمة على أمة ومملكة على مملكة،","21:11":"وتحدث في عدة أماكن زلازل شديدة ومجاعات وأوبئة، وتظهر علامات مخيفة وآيات عظيمة من السماء.","21:12":"ولكن قبل هذه الأمور كلها يمد الناس أيديهم إليكم ويضطهدونكم، فيسلمونكم إلى المجامع والسجون، ويسوقونكم للمثول أمام الملوك والحكام، من أجل اسمي.","21:13":"ولكن ذلك سيتيح لكم فرصة للشهادة.","21:14":"فضعوا في قلوبكم ألا تعدوا دفاعكم مسبقا،","21:15":"لأني سوف أعطيكم كلاما وحكمة لا يقدر جميع مقاوميكم أن يردوها أو يناقضوها.","21:16":"وسوف يسلمكم حتى الوالدون والإخوة والأقرباء والأصدقاء، ويقتلون بعضا منكم،","21:17":"وتكونون مكروهين لدى الجميع من أجل اسمي.","21:18":"ولكن شعرة من رؤوسكم لا تهلك البتة.","21:19":"فباحتمالكم تربحون أنفسكم!","21:20":"وعندما ترون أورشليم محاصرة بالجيوش، فاعلموا أن خرابها قد اقترب.","21:21":"عندئذ، ليهرب الذين في منطقة اليهودية إلى الجبال، وليرحل من المدينة من هم فيها، ولا يدخلها من هم في الأرياف:","21:22":"فإن هذه الأيام أيام انتقام يتم فيها كل ما قد كتب.","21:23":"ولكن الويل للحبالى والمرضعات في تلك الأيام، لأن ضيقة عظيمة سوف تقع على الأرض وغضبا شديدا سينزل بهذا الشعب،","21:24":"فيسقطون بحد السيف ويساقون أسرى إلى جميع الأمم، وتبقى أورشليم تدوسها الأمم إلى أن تكتمل أزمنة الأمم.","21:25":"وستظهر علامات في الشمس والقمر والنجوم، وتكون على الأرض ضيقة على الأمم الواقعة في حيرة، لأن البحر والأمواج تعج وتجيش،","21:26":"ويغمى على الناس من الرعب ومن توقع ما سوف يجتاح المسكونة، إذ تتزعزع قوات السماوات.","21:27":"عندئذ يرون ابن الإنسان آتيا في السحاب بقوة ومجد عظيم.","21:28":"ولكن عندما تبدأ هذه الأمور تحدث، فانتصبوا وارفعوا رؤوسكم لأن فداءكم يقترب».","21:29":"وضرب لهم مثلا: «انظروا إلى التينة وباقي الأشجار!","21:30":"عندما ترونها قد أورقت تعلمون من تلقاء أنفسكم أن الصيف بات قريبا.","21:31":"فهكذا أنتم أيضا، عندما ترون هذه الأمور حادثة، فاعلموا أن ملكوت الله بات قريبا.","21:32":"الحق أقول لكم: لا يزول هذا الجيل أبدا حتى تحدث هذه كلها.","21:33":"إن السماء والأرض تزولان، ولكن كلامي لا يزول أبدا.","21:34":"ولكن احذروا لأنفسكم لئلا تتثقل قلوبكم بالانغماس في اللذات وبالسكر وهموم الحياة، فيدهمكم ذلك اليوم فجأة؛","21:35":"فإنه سوف يطبق كالفخ على جميع الساكنين على وجه الأرض كلها.","21:36":"فاسهروا إذن وتضرعوا في كل حين، لكي تتمكنوا من أن تنجوا من جميع هذه الأمور التي هي على وشك أن تحدث، وتقفوا أمام ابن الإنسان».","21:37":"وكان في النهار يعلم في الهيكل، وفي الليل يخرج ويبيت في الجبل المعروف بجبل الزيتون.","21:38":"وكان جميع الشعب يبكرون إليه في الهيكل ليستمعوا إليه.","22:1":"واقترب عيد الفطير، المعروف بالفصح","22:2":"ومازال رؤساء الكهنة والكتبة يسعون كي يقتلوا يسوع، لأنهم كانوا خائفين من الشعب.","22:3":"ودخل الشيطان في يهوذا الملقب بالإسخريوطي، وهو في عداد الاثني عشر.","22:4":"فمضى وتكلم مع رؤساء الكهنة وقواد حرس الهيكل كيف يسلمه إليهم.","22:5":"ففرحوا، واتفقوا أن يعطوه بعض المال.","22:6":"فرضى، وأخذ يتحين فرصة ليسلمه إليهم بعيدا عن الجمع.","22:7":"وجاء يوم الفطير الذي كان يجب أن يذبح فيه (حمل) الفصح.","22:8":"فأرسل بطرس ويوحنا قائلا: «اذهبا وجهزا لنا الفصح، لنأكل!»","22:9":"فسألاه: «أين تريد أن نجهز؟»","22:10":"فقال لهما: «حالما تدخلان المدينة، يلاقيكما إنسان يحمل جرة ماء، فالحقا به إلى البيت الذي يدخله.","22:11":"وقولا لرب ذلك البيت: يقول لك المعلم: أين غرفة الضيوف التي آكل فيها (حمل) الفصح مع تلاميذي؟","22:12":"فيريكما غرفة في الطبقة العليا، كبيرة ومفروشة. هناك تجهزان!»","22:13":"فانطلقا، ووجدا كما قال لهما، وجهزا الفصح.","22:14":"ولما حانت الساعة، اتكأ ومعه الرسل،","22:15":"وقال لهم: «اشتهيت بشوق أن آكل هذا الفصح معكم قبل أن أتألم.","22:16":"فإني أقول لكم: لن آكل منه بعد، حتى يتحقق في ملكوت الله».","22:17":"وإذ تناول كأسا وشكر، قال: «خذوا هذه واقتسموها بينكم.","22:18":"فإني أقول لكم إني لا أشرب من نتاج الكرمة حتى يأتي ملكوت الله!»","22:19":"وإذ أخذ رغيفا، شكر، وكسر، وأعطاهم قائلا: «هذا جسدي الذي يبذل لأجلكم. هذا افعلوه لذكري!»","22:20":"وكذلك أخذ الكأس أيضا بعد العشاء، وقال: «هذه الكأس هي العهد الجديد بدمي الذي يسفك لأجلكم.","22:21":"ثم إن يد الذي يسلمني هي معي على المائدة.","22:22":"فابن الإنسان لابد أن يمضي كما هو محتوم، ولكن الويل لذلك الرجل الذي يسلمه!»","22:23":"فأخذوا يتساءلون فيما بينهم: من منهم يوشك أن يفعل هذا.","22:24":"وقام بينهم أيضا جدال في أيهم يحسب الأعظم.","22:25":"فقال لهم: «إن ملوك الأمم يسودونهم، وأصحاب السلطة عندهم يدعون محسنين.","22:26":"وأما أنتم، فلا يكن ذلك بينكم، بل ليكن الأعظم بينكم كالأصغر، والقائد كالخادم.","22:27":"فمن هو أعظم: الذي يتكيء أم الذي يخدم؟ أليس الذي يتكيء؟ ولكني أنا في وسطكم كالذي يخدم.","22:28":"أنتم هم الذين صمدوا معي في تجاربي.","22:29":"وأنا أعين لكم، كما عين لي أبي، ملكوتا،","22:30":"لكي تأكلوا وتشربوا على مائدتي في ملكوتي، وتجلسوا على عروش تدينون أسباط إسرائيل الاثني عشر.","22:31":"وقال الرب «سمعان، سمعان! ها إن الشيطان قد طلبكم لكي يغربلكم كما يغربل القمح،","22:32":"ولكني تضرعت لأجلك لكي لا يخيب إيمانك. وأنت، بعد أن تسترد، ثبت إخوتك».","22:33":"فقال له: «يارب، إني مستعد أن أذهب معك إلى السجن وإلى الموت معا!»","22:34":"فقال: «إني أقول لك يابطرس إن الديك لا يصيح اليوم حتى تكون قد أنكرت ثلاث مرات أنك تعرفني!»","22:35":"ثم قال لهم: «حين أرسلتكم بلا صرة مال ولا كيس زاد ولا حذاء، هل احتجتم إلى شيء؟» فقالوا: «لا!»","22:36":"فقال لهم: «أما الآن، فمن عنده صرة مال، فليأخذها؛ وكذلك من عنده حقيبة زاد. ومن ليس عنده، فليبع رداءه ويشتر سيفا.","22:37":"فإني أقول لكم: إن هذا الذي كتب عد مع المجرمين لابد أن يتم في، لأن كل نبوءة تختص بي لها إتمام!»","22:38":"فقالوا: «يارب ها هنا سيفان». فقال لهم: «كفى!»","22:39":"ثم انطلق وذهب كعادته إلى جبل الزيتون، وتبعه التلاميذ أيضا.","22:40":"ولما وصل إلى المكان، قال لهم: «صلوا لكي لا تدخلوا في تجربة».","22:41":"وابتعد عنهم مسافة تقارب رمية حجر، وركع يصلي","22:42":"قائلا: «ياأبي، إن شئت أبعد عني هذه الكأس. ولكن، لتكن لا مشيئتي بل مشيئتك».","22:43":"وظهر له ملاك من السماء يشدده.","22:44":"وإذ كان في صراع، أخذ يصلي بأشد إلحاح؛ حتى إن عرقه صار كقطرات دم نازلة على الأرض.","22:45":"ثم قام من الصلاة وجاء إلى التلاميذ، فوجدهم نائمين من الحزن.","22:46":"فقال لهم: «ما بالكم نائمين؟ قوموا وصلوا لكي لا تدخلوا في تجربة!»","22:47":"وفيما هو يتكلم، إذا جمع يتقدمهم المدعو يهوذا، وهو واحد من الاثني عشر. فتقدم إلى يسوع ليقبله.","22:48":"فقال له يسوع: «يايهوذا، أبقبلة تسلم ابن الإنسان؟»","22:49":"فلما رأى الذين حوله ما يوشك أن يحدث، قالوا: «يارب، أنضرب بالسيف؟»","22:50":"وضرب أحدهم عبد رئيس الكهنة فقطع أذنه اليمنى.","22:51":"فأجاب يسوع قائلا: «قفوا عند هذا الحد!» ولمس أذنه فشفاه.","22:52":"وقال يسوع لرؤساء الكهنة وقواد حرس الهيكل والشيوخ، الذين أقبلوا عليه: «أكما على لص خرجتم بالسيوف والعصي؟","22:53":"عندما كنت معكم كل يوم في الهيكل، لم تمدوا أيديكم علي. ولكن هذه الساعة لكم، والسلطة الآن للظلام!»","22:54":"وإذ قبضوا عليه، ساقوه حتى دخلوا به قصر رئيس الكهنة. وتبعه بطرس من بعيد.","22:55":"ولما أشعلت نار في ساحة الدار وجلس بعضهم حولها، جلس بطرس بينهم.","22:56":"فرأته خادمة جالسا عند الضوء، فدققت النظر فيه، وقالت: «وهذا كان معه!»","22:57":"ولكنه أنكر قائلا: «ياامرأة، لست أعرفه!»","22:58":"وبعد وقت قصير رآه آخر فقال: «وأنت منهم!» ولكن بطرس قال: «ياإنسان، ليس أنا!»","22:59":"وبعد مضي ساعة تقريبا، قال آخر مؤكدا: «حقا إن هذا كان معه أيضا، لأنه أيضا من الجليل!»","22:60":"فقال بطرس: «ياإنسان، لست أدري ما تقول!» وفي الحال وهو مازال يتكلم، صاح الديك.","22:61":"فالتفت الرب ونظر إلى بطرس. فتذكر بطرس كلمة الرب إذ قال له: «قبل أن يصيح الديك تكون قد أنكرتني ثلاث مرات».","22:62":"وانطلق إلى الخارج، وبكى بكاء مرا.","22:63":"أما الرجال الذين كانوا يحرسون يسوع، فقد أخذوا يسخرون منه ويضربونه،","22:64":"ويغطون وجهه ويسألونه: «تنبأ! من الذي ضربك؟»","22:65":"ووجهوا إليه شتائم أخرى كثيرة.","22:66":"ولما طلع النهار، اجتمع مجلس شيوخ الشعب المؤلف من رؤساء الكهنة والكتبة، وساقوه أمام مجلسهم.","22:67":"وقالوا: «إن كنت أنت المسيح، فقل لنا!» فقال لهم: «إن قلت لكم، لا تصدقون،","22:68":"وإن سألتكم، لا تجيبونني.","22:69":"إلا أن ابن الإنسان من الآن سيكون جالسا عن يمين قدرة الله!»","22:70":"فقالوا كلهم: «أأنت إذن ابن الله؟» قال لهم: «أنتم قلتم، إني أنا هو!»","22:71":"فقالوا: «أية حاجة بنا بعد إلى شهود؟ فها نحن قد سمعنا (شهادة) من فمه !»","23:1":"فقامت جماعتهم كلها، وساقوا يسوع إلى بيلاطس.","23:2":"وبدأوا يتهمونه قائلين: «تبين لنا أن هذا يضلل أمتنا، ويمنع أن تدفع الجزية للقيصر ويدعي أنه المسيح الملك!»","23:3":"فسأله بيلاطس: «أأنت ملك اليهود؟» فأجابه: «أنت قلت!»","23:4":"فقال بيلاطس لرؤساء الكهنة والجموع: «لا أجد ذنبا في هذا الإنسان!»","23:5":"ولكنهم ألحوا قائلين: «إنه يثير الشعب، معلما في اليهودية كلها، ابتداء من الجليل حتى هنا!»","23:6":"فلما سمع بيلاطس ذكر الجليل، استفسر: «هل الرجل من الجليل؟».","23:7":"وإذ علم أنه تابع لسلطة هيرودس، أحاله على هيرودس، إذ كان هو أيضا في أورشليم في تلك الأيام.","23:8":"ولما رأى هيرودس يسوع، فرح جدا، لأنه كان يتمنى من زمان طويل أن يراه بسبب سماعه الكثير عنه، ويرجو أن يرى آية تجرى على يده.","23:9":"فسأله في قضايا كثيرة، أما هو فلم يجبه عن شيء.","23:10":"ووقف رؤساء الكهنة والكتبة يتهمونه بعنف.","23:11":"فاحتقره هيرودس وجنوده، وسخر منه، إذ ألبسه ثوبا براقا ورده إلى بيلاطس.","23:12":"وصار بيلاطس وهيرودس صديقين في ذلك اليوم، وقد كانت بينهما عداوة سابقة.","23:13":"فدعا بيلاطس رؤساء الكهنة والقواد والشعب.","23:14":"وقال لهم: «أحضرتم إلي هذا الإنسان على أنه يضلل الشعب. وها أنا، بعدما فحصت الأمر أمامكم، لم أجد في هذا الإنسان أي ذنب مما تتهمونه به،","23:15":"ولا وجد هيرودس أيضا، إذ رده إلينا. وها إنه لم يفعل شيئا يستوجب الموت.","23:16":"فسأجلده إذن وأطلقه.","23:17":"وكان عليه أن يطلق لهم في كل عيد سجينا واحدا.","23:18":"ولكنهم صرخوا بجملتهم: «اقتل هذا، وأطلق لنا باراباس!»","23:19":"وكان ذاك قد ألقي في السجن بسبب فتنة حدثت في المدينة وبسبب قتل.","23:20":"فخاطبهم بيلاطس ثانية وهو راغب في إطلاق يسوع.","23:21":"فردوا صارخين: «اصلبه! اصلبه!»","23:22":"فسألهم ثالثة: «فأي شر فعل هذا؟ لم أجد فيه ذنبا عقوبته الموت. فسأجلده إذن وأطلقه!»","23:23":"فأخذوا يلحون صارخين بأصوات عالية، طالبين أن يصلب! فتغلبت أصواتهم،","23:24":"وحكم بيلاطس أن ينفذ طلبهم.","23:25":"فأطلق الذي كان قد ألقي في السجن بسبب الفتنة والقتل، ذاك الذي طلبوا إطلاقه. وأما يسوع فسلمه إلى إرادتهم.","23:26":"وفيما هم يسوقونه (إلى الصلب)، أمسكوا رجلا من القيروان اسمه سمعان، كان راجعا من الحقل، ووضعوا عليه الصليب ليحمله خلف يسوع.","23:27":"وقد تبعه جمع كبير من الشعب ومن نساء كن يولولن ويندبنه.","23:28":"فالتفت إليهن يسوع، وقال: «يابنات أورشليم، لا تبكين علي، بل ابكين على أنفسكن وعلى أولادكن!","23:29":"فها إن أياما ستأتي فيها يقول الناس: طوبى للعواقر اللواتي ما حملت بطونهن ولا أرضعت أثداؤهن!","23:30":"عندئذ يقولون للجبال: اسقطي علينا، وللتلال: غطينا!","23:31":"فإن كانوا قد فعلوا هذا بالغصن الأخضر، فماذا يجري لليابس؟»","23:32":"وسيق إلى القتل مع يسوع أيضا اثنان من المجرمين.","23:33":"ولما وصلوا إلى المكان الذي يدعى الجمجمة، صلبوه هناك مع المجرمين، أحدهما عن اليمين والآخر عن اليسار.","23:34":"وقال يسوع: «ياأبي، اغفر لهم، لأنهم لا يدرون ما يفعلون!» واقتسموا ثيابه مقترعين عليها.","23:35":"ووقف الشعب هناك يراقبونه، وكذلك الرؤساء يتهكمون قائلين: «خلص آخرين! فليخلص نفسه إن كان هو المسيح المختار عند الله!»","23:36":"وسخر منه الجنود أيضا، فكانوا يتقدمون إليه ويقدمون له خلا،","23:37":"قائلين: «إن كنت أنت ملك اليهود، فخلص نفسك»","23:38":"وكان معلقا فوقه لافتة كتب فيها: «هذا هو ملك اليهود».","23:39":"وأخذ واحد من المجرمين المصلوبين يجدف عليه فيقول: «ألست أنت المسيح؟ إذن خلص نفسك وخلصنا!»","23:40":"ولكن الآخر كلمه زاجرا فقال: «أحتى أنت لا تخاف الله ، وأنت تعاني العقوبة نفسها؟","23:41":"أما نحن فعقوبتنا عادلة لأننا ننال الجزاء العادل لقاء ما فعلنا. وأما هذا الإنسان، فلم يفعل شيئا في غير محله!»","23:42":"ثم قال: «يايسوع، اذكرني عندما تجيء في ملكوتك!»","23:43":"فقال له يسوع: «الحق أقول لك: اليوم ستكون معي في الفردوس!»","23:44":"ونحو الساعة السادسة (الثانية عشرة ظهرا)، حل الظلام على الأرض كلها حتى الساعة التاسعة (الثالثة بعد الظهر).","23:45":"وأظلمت الشمس، وانشطر ستار الهيكل من الوسط.","23:46":"وقال يسوع صارخا بصوت عظيم: «ياأبي، في يديك أستودع روحي!» وإذ قال هذا، أسلم الروح.","23:47":"فلما رأى قائد المئة ما حدث، مجد الله قائلا: «بالحقيقة كان هذا الإنسان بارا».","23:48":"كذلك الجموع الذين احتشدوا ليراقبوا مشهد الصلب، لما رأوا ما حدث، رجعوا قارعين الصدور.","23:49":"أما جميع معارفه، بمن فيهم النساء اللواتي تبعنه من الجليل، فقد كانوا واقفين من بعيد يراقبون هذه الأمور.","23:50":"وكان في المجلس الأعلى إنسان اسمه يوسف، وهو إنسان صالح وبار","23:51":"لم يكن موافقا على قرار أعضاء المجلس وفعلتهم، وهو من الرامة إحدى مدن اليهود، وكان من منتظري ملكوت الله.","23:52":"فإذا به قد تقدم إلى بيلاطس وطلب جثمان يسوع.","23:53":"ثم أنزله (من على الصليب) وكفنه بكتان، ووضعه في قبر منحوت (في الصخر) لم يدفن فيه أحد من قبل.","23:54":"وكان ذلك النهار يوم الإعداد للسبت الذي كان قد بدأ يقترب.","23:55":"وتبعت يوسف النساء اللواتي خرجن من الجليل مع يسوع، فرأين القبر وكيف وضع جثمانه.","23:56":"ثم رجعن وهيأن حنوطا وطيبا، واسترحن يوم السبت حسب الوصية.","24:1":"ولكن في اليوم الأول من الأسبوع، باكرا جدا، جئن إلى القبر حاملات الحنوط الذي هيأنه.","24:2":"فوجدن أن الحجر قد دحرج عن القبر.","24:3":"ولكن لما دخلن لم يجدن جثمان الرب يسوع.","24:4":"وفيما هن متحيرات في ذلك، إذا رجلان بثياب براقة قد وقفا بجانبهن.","24:5":"فتملكهن الخوف ونكسن وجوههن إلى الأرض. عندئذ قال لهن الرجلان: «لماذا تبحثن عن الحي بين الأموات؟","24:6":"إنه ليس هنا، ولكنه قد قام! اذكرن ما كلمكم به إذ كان بعد في الجليل","24:7":"فقال: إن ابن الإنسان لابد أن يسلم إلى أيدي أناس خاطئين، فيصلب، وفي اليوم الثالث يقوم».","24:8":"فتذكرن كلامه.","24:9":"وإذ رجعن من القبر، أخبرن الأحد عشر والآخرين كلهم بهذه الأمور جميعا.","24:10":"وكانت اللواتي أخبرن الرسل بذلك هن مريم المجدلية، ويونا، ومريم أم يعقوب، والأخريات اللواتي ذهبن معهن.","24:11":"فبدا كلامهن في نظر الرسل كأنه هذيان، ولم يصدقوهن.","24:12":"إلا أن بطرس قام وركض إلى القبر، وإذ انحنى رأى الأكفان الملفوفة وحدها، ثم مضى متعجبا مما حدث.","24:13":"وكان اثنان منهم منطلقين في ذلك اليوم إلى قرية تبعد ستين غلوة (نحو سبعة أميال) عن أورشليم، اسمها عمواس.","24:14":"وكانا يتحدثان عن جميع ما حدث","24:15":"وبينما هما يتحدثان ويتباحثان، إذا يسوع نفسه قد اقترب إليهما وسار معهما.","24:16":"ولكن أعينهما حجبت عن معرفته.","24:17":"وسألهما: «أي حديث يجري بينكما وأنتما سائران؟» فتوقفا عابسين.","24:18":"وأجاب أحدهما، واسمه كليوباس، فقال له: «أأنت وحدك الغريب النازل في أورشليم، ولا تعلم بما حدث فيها في هذه الأيام؟»","24:19":"فقال لهما: «ماذا حدث؟» فقالا: «ما حدث ليسوع الناصري الذي كان نبيا مقتدرا في الفعل والقول أمام الله والشعب كله،","24:20":"وكيف سلمه رؤساء الكهنة وحكامنا إلى عقوبة الموت وصلبوه.","24:21":"ولكننا كنا نرجو أنه الموشك أن يفدي إسرائيل. ومع هذا كله، فاليوم هو اليوم الثالث منذ حدوث ذلك.","24:22":"على أن بعض النساء منا أذهلننا، إذ قصدن إلى القبر باكرا","24:23":"ولم يجدن جثمانه، فرجعن وقلن لنا إنهن شاهدن رؤيا: ملاكين يقولان إنه حي.","24:24":"فذهب بعض الذين معنا إلى القبر فوجدوا الأمر صحيحا على حد ما قالت النساء أيضا، وأما هو فلم يروه!»","24:25":"فقال لهما: «ياقليلي الفهم وبطيئي القلب في الإيمان بجميع ما تكلم به الأنبياء!","24:26":"أما كان لابد أن يعاني المسيح هذه الآلام ثم يدخل إلى مجده؟»","24:27":"ثم أخذ يفسر لهما، منطلقا من موسى ومن الأنبياء جميعا، ما ورد عنه في جميع الكتب.","24:28":"ثم اقتربوا من القرية التي كان التلميذان يقصدانها، وتظاهر هو بأنه ذاهب إلى مكان أبعد.","24:29":"فألحا عليه قائلين: «انزل عندنا، فقد مال النهار واقترب المساء». فدخل لينزل عندهما.","24:30":"ولما اتكأ معهما، أخذ الخبز، وبارك، وكسر، وأعطاهما.","24:31":"فانفتحت أعينهما وعرفاه. ثم اختفى عنهما.","24:32":"فقال أحدهما للآخر: «أما كان قلبنا يلتهب في صدورنا فيما كان يحدثنا في الطريق ويشرح لنا الكتب؟»","24:33":"ثم قاما في تلك الساعة عينها، ورجعا إلى أورشليم، فوجدا الأحد عشر والذين معهم مجتمعين،","24:34":"وكانوا يقولون: «حقا إن الرب قام، وقد ظهر لسمعان».","24:35":"فأخبراهم بما حدث في الطريق، وكيف عرفا الرب عند كسر الخبز.","24:36":"وفيما هما يتكلمان بذلك، وقف يسوع نفسه في وسطهم، وقال لهم: «سلام لكم!»","24:37":"ولكنهم، لذعرهم وخوفهم، توهموا أنهم يرون شبحا.","24:38":"فقال لهم: «ما بالكم مضطربين؟ ولماذا تنبعث الشكوك في قلوبكم؟","24:39":"انظروا يدي وقدمي، فأنا هو بنفسي. المسوني وتحققوا، فإن الشبح ليس له لحم وعظام كما ترون لي».","24:40":"وإذ قال ذلك، أراهم يديه وقدميه.","24:41":"وإذ مازالوا غير مصدقين من الفرح ومتعجبين، قال لهم: «أعندكم هنا ما يؤكل؟»","24:42":"فناولوه قطعة سمك مشوي.","24:43":"فأخذها أمامهم وأكل.","24:44":"ثم قال لهم: «هذا هو الكلام الذي كلمتكم به وأنا مازلت بينكم: أنه لابد أن يتم كل ما كتب عني في شريعة موسى وكتب الأنبياء والمزامير».","24:45":"ثم فتح أذهانهم ليفهموا الكتب،","24:46":"وقال لهم: «هكذا قد كتب، وهكذا كان لابد أن يتألم المسيح ويقوم من بين الأموات في اليوم الثالث،","24:47":"وأن يبشر باسمه بالتوبة وغفران الخطايا في جميع الأمم انطلاقا من أورشليم.","24:48":"وأنتم شهود على هذه الأمور.","24:49":"وها أنا سأرسل إليكم ما وعد به أبي. ولكن أقيموا في المدينة حتى تلبسوا القوة من الأعالي!»","24:50":"ثم اقتادهم إلى خارج المدينة إلى بيت عنيا. وباركهم رافعا يديه.","24:51":"وبينما كان يباركهم، انفصل عنهم وأصعد إلى السماء","24:52":"فسجدوا له، ثم رجعوا إلى أورشليم بفرح عظيم،","24:53":"وكانوا يذهبون دائما إلى الهيكل، حيث يسبحون الله ويباركونه."},"Joh":{"1:1":"في البدء كان الكلمة، والكلمة كان عند الله. وكان الكلمة هو الله .","1:2":"هو كان في البدء عند الله.","1:3":"به تكون كل شيء، وبغيره لم يتكون أي شيء مما تكون.","1:4":"فيه كانت الحياة. والحياة هذه كانت نور الناس.","1:5":"والنور يضيء في الظلام، والظلام لم يدرك النور.","1:6":"ظهر إنسان أرسله الله ، اسمه يوحنا،","1:7":"جاء يشهد للنور، من أجل أن يؤمن الجميع بواسطته.","1:8":"لم يكن هو النور، بل كان شاهدا للنور،","1:9":"فالنور الحق الذي ينير كل إنسان كان آتيا إلى العالم.","1:10":"كان في العالم، وبه تكون العالم، ولم يعرفه العالم.","1:11":"وقد جاء إلى من كانوا خاصته، ولكن هؤلاء لم يقبلوه.","1:12":"أما الذين قبلوه، أي الذين آمنوا باسمه، فقد منحهم الحق في أن يصيروا أولاد الله،","1:13":"وهم الذين ولدوا ليس من دم، ولا من رغبة جسد، ولا من رغبة بشر، بل من الله.","1:14":"والكلمة صار بشرا، وخيم بيننا، ونحن رأينا مجده، مجد ابن وحيد عند الآب، وهو ممتلىء بالنعمة والحق.","1:15":"شهد له يوحنا فهتف قائلا: «هذا هو الذي قلت عنه: إن الآتي بعدي متقدم علي، لأنه كان قبل أن أوجد».","1:16":"فمن امتلائه أخذنا جميعنا ونلنا نعمة على نعمة،","1:17":"لأن الشريعة أعطيت على يد موسى، أما النعمة والحق فقد تواجدا بيسوع المسيح.","1:18":"ما من أحد رأى الله قط. ولكن الابن الوحيد، الذي في حضن الآب، هو الذي كشف عنه.","1:19":"وهذه شهادة يوحنا حين أرسل اليهود من أورشليم بعض الكهنة واللاويين يسألونه: «من أنت؟»","1:20":"فاعترف ولم ينكر، بل أكد قائلا: «لست أنا المسيح».","1:21":"فسألوه: «ماذا إذن؟ هل أنت إيليا؟» قال: «لست إياه!»؛ «أو أنت النبي؟» فأجاب: «لا!»","1:22":"فقالوا: «فمن أنت، لنحمل الجواب إلى الذين أرسلونا؟ ماذا تقول عن نفسك؟»","1:23":"فقال «أنا صوت مناد في البرية: اجعلوا الطريق مستقيمة أمام الرب، كما قال النبي إشعياء».","1:24":"وكان هؤلاء مرسلين من قبل الفريسيين،","1:25":"فعادوا يسألونه: «إن لم تكن أنت المسيح، ولا إيليا، ولا النبي، فلماذا تعمد إذن؟»","1:26":"أجاب: «أنا أعمد بالماء! ولكن بينكم من لا تعرفونه،","1:27":"وهو الآتي بعدي، وأنا لا أستحق أن أحل رباط حذائه».","1:28":"هذا جرى في بيت عنيا، في ما وراء نهر الأردن، حيث كان يوحنا يعمد.","1:29":"وفي اليوم التالي رأى يوحنا يسوع آتيا نحوه، فهتف قائلا: «هذا هو حمل الله الذي يزيل خطيئة العالم.","1:30":"هذا هو الذي قلت عنه إن الرجل الآتي بعدي متقدم علي لأنه كان قبل أن أوجد.","1:31":"ولم أكن أعرفه ولكني جئت أعمد بالماء لكي يعلن لإسرائيل».","1:32":"ثم شهد يوحنا فقال: «رأيت الروح ينزل من السماء بهيئة حمامة ويستقر عليه.","1:33":"ولم أكن أعرفه، ولكن الذي أرسلني لأعمد بالماء هو قال لي: الذي ترى الروح ينزل ويستقر عليه هو الذي سيعمد بالروح القدس.","1:34":"فإذ شاهدت هذا، أشهد أنه هو ابن الله».","1:35":"وفي اليوم التالي كان يوحنا واقفا هناك أيضا ومعه اثنان من تلاميذه،","1:36":"فنظر إلى يسوع وهو سائر فقال: «هذا هو حمل الله».","1:37":"فلما سمع التلميذان كلامه تبعا يسوع.","1:38":"والتفت يسوع فرآهما يتبعانه، فسألهما: «ماذا تريدان؟» فقالا: «رابي، أي يامعلم، أين تقيم؟»","1:39":"أجابهما: «تعاليا وانظر ا». فرافقاه ورأيا محل إقامته، وأقاما معه ذلك اليوم؛ وكانت الساعة نحو الرابعة بعد الظهر.","1:40":"وكان أندراوس أخو سمعان بطرس أحد هذين اللذين تبعا يسوع، بعدما سمعا كلام يوحنا،","1:41":"فما إن وجد أخاه سمعان، حتى قال له: «وجدنا المسيا» أي المسيح.","1:42":"واقتاده إلى يسوع. فنظر يسوع مليا إلى سمعان وقال: «أنت سمعان بن يونا، ولكني سأدعوك: صفا» أي صخرا.","1:43":"وفي اليوم التالي نوى يسوع أن يذهب إلى منطقة الجليل، فوجد فيلبس، فقال له: «اتبعني!»","1:44":"وكان فيلبس من بيت صيدا، بلدة أندراوس وبطرس.","1:45":"ثم وجد فيلبس نثنائيل، فقال له: «وجدنا الذي كتب عنه موسى في الشريعة، والأنبياء في كتبهم وهو يسوع ابن يوسف من الناصرة».","1:46":"فقال نثنائيل: «وهل يطلع من الناصرة شيء صالح؟» أجابه فيلبس: «تعال وانظر!»","1:47":"ورأى يسوع نثنائيل قادما نحوه فقال عنه: «هذا إسرائيلي أصيل لا شك فيه!»","1:48":"فسأله نثنائيل: «ومن أين تعرفني؟» فأجابه يسوع: «رأيتك تحت التينة قبل أن يدعوك فيلبس».","1:49":"فهتف نثنائيل قائلا: «يامعلم، أنت ابن الله! أنت ملك إسرائيل!»","1:50":"فقال له يسوع: «هل آمنت لأني قلت لك إني رأيتك تحت التينة؟ سوف ترى أعظم من هذا!»","1:51":"ثم قال له: «الحق الحق أقول لكم: إنكم سترون السماء مفتوحة، وملائكة الله يصعدون وينزلون على ابن الإنسان!»","2:1":"وفي اليوم الثالث كان عرس في قانا بمنطقة الجليل، وكانت هناك أم يسوع.","2:2":"ودعي إلى العرس أيضا يسوع وتلاميذه.","2:3":"فلما نفدت الخمر، قالت أم يسوع له: «لم يبق عندهم خمر!»","2:4":"فأجابها: «ما شأنك بي ياامرأة؟ ساعتي لم تأت بعد!»","2:5":"فقالت أمه للخدم: «افعلوا كل ما يأمركم به».","2:6":"وكانت هناك ستة أجران حجرية، يستعمل اليهود ماءها للتطهر، يسع الواحد منها ما بين مكيالين أو ثلاثة (أي ما بين ثمانين إلى مئة وعشرين لترا).","2:7":"فقال يسوع للخدم: «املأوا الأجران ماء». فملأوها حتى كادت تفيض.","2:8":"ثم قال لهم: «والآن اغرفوا منها وقدموا إلى رئيس الوليمة!» ففعلوا.","2:9":"ولما ذاق رئيس الوليمة الماء الذي كان قد تحول إلى خمر، ولم يكن يعرف مصدره، أما الخدم الذين قدموه فكانوا يعرفون، استدعى العريس،","2:10":"وقال له: «الناس جميعا يقدمون الخمر الجيدة أولا، وبعد أن يسكر الضيوف يقدمون لهم ما كان دونها جودة. أما أنت فقد أبقيت الخمر الجيدة حتى الآن!»","2:11":"هذه المعجزة هي الآية الأولى التي أجراها يسوع في قانا بالجليل، وأظهر مجده، فآمن به تلاميذه.","2:12":"وبعد هذا، نزل يسوع وأمه وإخوته وتلاميذه إلى مدينة كفرناحوم، حيث أقاموا بضعة أيام.","2:13":"وإذ اقترب عيد الفصح اليهودي، صعد يسوع إلى أورشليم،","2:14":"فوجد في الهيكل باعة البقر والغنم والحمام، والصيارفة جالسين إلى موائدهم،","2:15":"فجدل سوطا من حبال، وطردهم جميعا من الهيكل، مع الغنم والبقر، وبعثر نقود الصيارفة وقلب مناضدهم،","2:16":"وقال لبائعي الحمام: «أخرجوا هذه من هنا. لا تجعلوا بيت أبي بيتا للتجارة!»","2:17":"فتذكر تلاميذه أنه جاء في الكتاب: «الغيرة على بيتك تلتهمني».","2:18":"فتصدى اليهود ليسوع وقالوا له: «هات آية تثبت سلطتك لفعل ما فعلت!»","2:19":"أجابهم يسوع: «اهدموا هذا الهيكل، وفي ثلاثة أيام أقيمه».","2:20":"فقال له اليهود: «اقتضى بناء هذا الهيكل ستة وأربعين عاما، فهل تقيمه أنت في ثلاثة أيام؟»","2:21":"ولكنه كان يشير إلى هيكل جسده.","2:22":"فلما قام من بين الأموات فيما بعد تذكر تلاميذه قوله هذا، فآمنوا بالكتاب وبالكلام الذي قاله يسوع.","2:23":"وبينما كان في أورشليم في عيد الفصح، آمن باسمه كثيرون إذ شهدوا الآيات التي أجراها.","2:24":"ولكنه هو لم يأتمنهم على نفسه، لأنه كان يعرف الجميع","2:25":"ولم يكن بحاجة إلى من يشهد له عن الإنسان، لأنه يعرف دخيلة الإنسان.","3:1":"غير أن إنسانا من الفريسيين، اسمه نيقوديموس، وهو عضو في المجلس اليهودي،","3:2":"جاء إلى يسوع ليلا وقال له: «يامعلم، نعلم أنك جئت من الله معلما، لأنه لا يقدر أحد أن يعمل ما تعمل من آيات إلا إذا كان الله معه».","3:3":"فأجابه يسوع: «الحق الحق أقول لك: لا أحد يمكنه أن يرى ملكوت الله إلا إذا ولد من جديد».","3:4":"فسأله نيقوديموس: «كيف يمكن الإنسان أن يولد وهو كبير السن؟ ألعله يستطيع أن يدخل بطن أمه ثانية ثم يولد؟»","3:5":"أجابه يسوع: «الحق الحق أقول لك: لا يمكن أن يدخل أحد ملكوت الله إلا إذا ولد من الماء والروح.","3:6":"فالمولود من الجسد هو جسد، والمولود من الروح هو روح.","3:7":"فلا تتعجب إذا قلت لك إنكم بحاجة إلى الولادة من جديد.","3:8":"الريح تهب حيث تشاء وتسمع صفيرها، ولكنك لا تعلم من أين تأتي ولا إلى أين تذهب. هكذا كل من ولد من الروح».","3:9":"فعاد نيقوديموس يسأل: «كيف يمكن أن يتم هذا؟»","3:10":"أجابه يسوع: «أنت معلم إسرائيل ولا تعلم هذا!","3:11":"الحق الحق أقول لك: إننا نتكلم بما نعلم ونشهد بما رأينا، ومع ذلك لا تقبلون شهادتنا.","3:12":"إن كنت حدثتكم بأمور الأرض ولم تؤمنوا، فكيف تؤمنون إن حدثتكم بأمور السماء؟","3:13":"وما صعد أحد إلى السماء إلا الذي نزل من السماء، وهو ابن الإنسان الذي هو في السماء.","3:14":"وكما علق موسى الحية في البر ية، فكذلك لا بد من أن يعلق ابن الإنسان،","3:15":"لتكون الحياة الأبدية لكل من يؤمن به.","3:16":"لأنه هكذا أحب الله العالم حتى بذل ابنه الوحيد، لكي لا يهلك كل من يؤمن به، بل تكون له الحياة الأبدية.","3:17":"فإن الله لم يرسل ابنه إلى العالم ليدين العالم، بل ليخلص العالم به،","3:18":"فالذي يؤمن به لا يدان، أما الذي لا يؤمن به فقد صدر عليه حكم الدينونة، لأنه لم يؤمن باسم ابن الله الوحيد.","3:19":"وهذا هو الحكم: إن النور قد جاء إلى العالم، ولكن الناس أحبوا الظلمة أكثر من النور، لأن أعمالهم كانت شريرة.","3:20":"فكل من يعمل الشر يبغض النور، ولا يأتي إليه مخافة أن تفضح أعماله.","3:21":"وأما الذي يسلك في الحق فيأتي إلى النور لتظهر أعماله ويتبين أنها عملت بقوة الله».","3:22":"وذهب يسوع وتلاميذه بعد ذلك إلى بلاد اليهودية وأقام فيها معهم، وأخذ يعمد.","3:23":"وكان يوحنا أيضا يعمد في عين نون بالقرب من ساليم، لأن المياه هناك كانت كثيرة فكان الناس يأتون ويتعمدون.","3:24":"فإن يوحنا لم يكن قد ألقي بعد في السجن.","3:25":"وحدث جدال بين تلاميذ يوحنا وأحد اليهود في شأن التطهر.","3:26":"فذهبوا إلى يوحنا وقالوا له: «يامعلم، الرجل الذي رأيناه معك في ما وراء نهر الأردن، والذي شهدت له، هو أيضا يعمد، والجميع يتحولون إليه!»","3:27":"فأجاب يوحنا: «لا يقدر أحد أن ينال شيئا إلا إذا أعطي له من السماء!","3:28":"أنتم تشهدون أني قلت: لست المسيح، بل أنا رسول يمهد له الطريق.","3:29":"ومن له العروس، يكون هو العريس! أما صديق العريس، الذي يقف قربه ويسمعه، فيبتهج لفرحه بصوت العريس. وها إن فرحي هذا قد تم.","3:30":"فلابد أن يزيد هو وأنقص أنا»","3:31":"إنه هو الآتي من السماء، ولذلك فهو متقدم على الجميع. أما من كان من الأرض، فإنه أرضي ويتكلم كلاما أرضيا. الآتي من السماء متقدم على الجميع،","3:32":"وهو يشهد بما سمع ورأى، ولا أحد يقبل شهادته!","3:33":"على أن الذي يقبل شهادته، يصادق على أن الله حق،","3:34":"لأن الذي أرسله الله يتكلم بكلام الله فإن الله يعطي الروح ليس بالمكيال.","3:35":"فالآب يحب الابن، وقد جعل في يده كل شيء.","3:36":"من يؤمن بالابن، فله الحياة الأبدية. ومن يرفض أن يؤمن بالابن، فلن يرى الحياة. بل يستقر عليه غضب الله».","4:1":"ولما عرف الرب أن الفريسيين سمعوا أنه يتخذ تلاميذ ويعمد أكثر من يوحنا،","4:2":"مع أن يسوع نفسه لم يكن يعمد بل تلاميذه،","4:3":"ترك منطقة اليهودية ورجع إلى منطقة الجليل.","4:4":"وكان لابد له أن يمر بمنطقة السامرة،","4:5":"فوصل إلى بلدة فيها، تدعى سوخار، قريبة من الأرض التي وهبها يعقوب لابنه يوسف،","4:6":"حيث بئر يعقوب. ولما كان يسوع قد تعب من السفر، جلس على حافة البئر، وكانت الساعة حوالي السادسة.","4:7":"وجاءت امرأة سامرية إلى البئر لتأخذ ماء، فقال لها يسوع: «اسقيني!»","4:8":"فإن تلاميذه كانوا قد ذهبوا إلى البلدة ليشتروا طعاما.","4:9":"فقالت له المرأة السامرية: «أنت يهودي وأنا سامرية، فكيف تطلب مني أن أسقيك؟» فإن اليهود كانوا لا يتعاملون مع أهل السامرة.","4:10":"فأجابها يسوع: «لو كنت تعرفين عطية الله، ومن هو الذي يقول لك: اسقيني، لطلبت أنت منه فأعطاك ماء حيا!»","4:11":"فقالت المرأة: «ولكن ياسيد، ليس معك دلو، والبئر عميقة. فمن أين لك الماء الحي؟","4:12":"هل أنت أعظم من أبينا يعقوب الذي أورثنا هذه البئر، وقد شرب منها هو وبنوه ومواشيه؟»","4:13":"فقال لها يسوع: «كل من يشرب من هذا الماء يعود فيعطش.","4:14":"ولكن الذي يشرب من الماء الذي أعطيه أنا، لن يعطش بعد ذلك أبدا، بل إن ما أعطيه من ماء يصبح في داخله نبعا يفيض فيعطي حياة أبدية».","4:15":"فقالت له المرأة: «ياسيد، أعطني هذا الماء فلا أعطش ولا أعود إلى هنا لآخذ ماء».","4:16":"فقال لها: «اذهبي وادعي زوجك، وارجعي إلى هنا».","4:17":"فأجابت: «ليس لي زوج!» فقال: «صدقت إذ قلت: ليس لي زوج","4:18":"فقد كان لك خمسة أزواج، والذي تعيشين معه الآن ليس زوجك. هذا قلته بالصدق!»","4:19":"فقالت له المرأة: «ياسيد، أرى أنك نبي.","4:20":"آباؤنا عبدوا الله في هذا الجبل، وأنتم اليهود تصرون على أن أورشليم يجب أن تكون المركز الوحيد للعبادة».","4:21":"فأجابها يسوع: «صدقيني ياامرأة، ستأتي الساعة التي فيها تعبدون الآب لا في هذا الجبل ولا في أورشليم.","4:22":"أنتم تعبدون ما تجهلون، ونحن نعبد ما نعلم، لأن الخلاص هو من عند اليهود.","4:23":"فستأتي ساعة، لا بل هي الآن، حين يعبد العابدون الصادقون الآب بالروح وبالحق. لأن الآب يبتغي مثل هؤلاء العابدين.","4:24":"الله روح، فلذلك لابد لعابديه من أن يعبدوه بالروح وبالحق».","4:25":"فقالت له المرأة: «إني أعلم أن المسيا، الذي يدعى المسيح، سيأتي، ومتى جاء فهو يعلن لنا كل شيء».","4:26":"فأجابها: «إني أنا هو؛ هذا الذي يكلمك!»","4:27":"وعند ذلك وصل التلاميذ، ودهشوا لما رأوه يحادث امرأة. ومع ذلك لم يقل له أحد منهم: «ماذا تريد منها؟» أو «لماذا تحادثها؟»","4:28":"فتركت المرأة جرتها وعادت إلى البلدة، وأخذت تقول للناس:","4:29":"«تعالوا انظروا إنسانا كشف لي كل ما فعلت! فلعله هو المسيح؟»","4:30":"فخرج أهل سوخار وأقبلوا إليه.","4:31":"وفي أثناء ذلك كان التلاميذ يقولون له بإلحاح: «يامعلم، كل»","4:32":"فأجابهم: «عندي طعام آكله لا تعرفونه أنتم».","4:33":"فأخذ التلاميذ يتساءلون: «هل جاءه أحد بما يأكله؟»","4:34":"فقال لهم يسوع: «طعامي هو أن أعمل مشيئة الذي أرسلني وأن أنجز عمله.","4:35":"أما تقولون: بعد أربعة أشهر يأتي الحصاد! ولكني أقول لكم: انظروا مليا إلى الحقول، فهي قد نضجت وحان حصادها.","4:36":"والحاصد يأخذ أجرته، ويجمع الثمر للحياة الأبدية، فيفرح الزارع والحاصد معا،","4:37":"حتى يصدق القول: واحد يزرع، وآخر يحصد.","4:38":"إني أرسلتكم لتحصدوا ما لم تتعبوا فيه، فغيركم تعبوا، وأنتم تجنون ثمر أتعابهم».","4:39":"فآمن به كثيرون من السامريين أهل تلك البلدة بسبب كلام المرأة التي كانت تشهد قائلة: «كشف لي كل ما فعلت».","4:40":"وعندما قابلوه عند البئر دعوه أن يقيم عندهم، فأقام هنالك يومين،","4:41":"وتكاثر جدا عدد الذين آمنوا به بسبب كلامه،","4:42":"وقالوا للمرأة: «إننا لا نؤمن بعد الآن بسبب كلامك، بل نؤمن لأننا سمعناه بأنفسنا، وعرفنا أنه مخلص العالم حقا!»","4:43":"وبعد قضاء اليومين في سوخار، غادرها يسوع وسافر إلى منطقة الجليل،","4:44":"وهو نفسه كان قد شهد قائلا: «لا كرامة لنبي في وطنه!»","4:45":"فلما وصل إلى الجليل رحب به أهلها، وكانوا قد رأوا كل ما فعله في أورشليم في أثناء عيد الفصح، إذ ذهبوا هم أيضا إلى العيد.","4:46":"ووصل يسوع إلى قانا بالجليل، حيث كان قد حول الماء إلى خمر. وكان في كفرناحوم رجل من حاشية الملك، له ابن مريض.","4:47":"فلما سمع أن يسوع ترك اليهودية وجاء إلى الجليل، ذهب إليه وطلب منه أن ينزل معه إلى كفرناحوم ليشفي ابنه المشرف على الموت.","4:48":"فقال يسوع: «لا تؤمنون إلا إذا رأيتم الآيا ت والعجائب!»","4:49":"فتوسل إليه الرجل وقال: «ياسيد، انزل معي قبل أن يموت ابني!»","4:50":"أجابه يسوع: «اذهب! إن ابنك حي!» فآمن الرجل بكلمة يسوع التي قالها له، وانصرف.","4:51":"وبينما كان نازلا في الطريق لاقاه بعض عبيده وبشروه بأن ابنه حي،","4:52":"فسألهم في أية ساعة تعافى، أجابوه: «في الساعة السابعة مساء البارحة، ولت عنه الحمى».","4:53":"فعلم الأب أنها الساعة التي قال له يسوع فيها: «إن ابنك حي». فآمن هو وأهل بيته جميعا.","4:54":"هذه المعجزة هي الآية الثانية التي أجراها يسوع بعد خروجه من اليهودية إلى الجليل.","5:1":"وبعد ذلك صعد يسوع إلى أورشليم في أحد الأعياد اليهودية،","5:2":"وكان بالقرب من باب الغنم في أورشليم بركة اسمها بالعبرية بيت حسدا، حولها خمس قاعات.","5:3":"يرقد فيها جمع كبير من المرضى من عميان وعرج ومشلولين، ينتظرون أن تتحرك مياه البركة،","5:4":"لأن ملاكا كان يأتي من حين لآخر إلى البركة ويحرك ماءها، فكان الذي ينزل أولا يشفى، مهما كان مرضه.","5:5":"وكان عند البركة مريض منذ ثمان وثلاثين سنة،","5:6":"رآه يسوع راقدا هناك فعرف أن مدة طويلة انقضت وهو على تلك الحال، فسأله: «أتريد أن تشفى؟»","5:7":"فأجابه المريض: «ياسيد، ليس لي إنسان يلقيني في البركة متى تحرك الماء. وكم من مرة حاولت النزول، فكان غيري ينزل قبلي دائما».","5:8":"فقال له يسوع: «قم احمل فراشك وامش».","5:9":"وفي الحال شفي الرجل وحمل فراشه ومشى. وكان ذلك يوم سبت.","5:10":"فقال اليهود للرجل الذي شفي: «اليوم سبت. لا يحل لك أن تحمل فراشك!»","5:11":"فأجابهم: «الذي أعاد إلي الصحة هو قال لي: احمل فراشك وامش».","5:12":"فسألوه: «ومن هو الذي قال لك: احمل فراشك وامش؟»","5:13":"ولكن المريض الذي شفي لم يكن يعرف من هو، لأن يسوع كان قد انسحب، إذ كان في المكان جمع.","5:14":"وبعد ذلك وجده يسوع في الهيكل، فقال له: «ها أنت قد عدت صحيحا فلا ترجع إلى الخطيئة لئلا يصيبك ما هو أسوأ!»","5:15":"فلما عرف الرجل أن يسوع هو الذي شفاه، أسرع يخبر اليهود بذلك.","5:16":"فأخذ اليهود يضايقون يسوع لأنه كان يعمل هذه الأعمال يوم السبت.","5:17":"ولكن يسوع قال لهم: «ما زال أبي يعمل إلى الآن. وأنا أيضا أعمل!»","5:18":"لهذا ازداد سعي اليهود إلى قتله، ليس فقط لأنه خالف سنة السبت، بل أيضا لأنه قال إن الله أبوه، مساويا نفسه بالله.","5:19":"فقال لهم يسوع: «الحق الحق أقول لكم إن الابن لا يقدر أن يفعل شيئا من تلقاء نفسه، بل يفعل ما يرى الآب يفعله. فكل ما يعمله الآب، يعمله الابن كذلك،","5:20":"لأن الآب يحب الابن، ويريه جميع ما يفعله، وسيريه أيضا أعمالا أعظم من هذا العمل، فتدهشون.","5:21":"فكما يقيم الآب الموتى ويحييهم، كذلك يحيي الابن من يشاء.","5:22":"والآب لا يحاكم أحدا، بل أعطى الابن سلطة القضاء كلها،","5:23":"ليكرم الجميع الابن كما يكرمون الآب. ومن لا يكرم الابن لا يكرم الآب الذي أرسله.","5:24":"الحق الحق أقول لكم إن من يسمع كلامي ويؤمن بالذي أرسلني تكون له الحياة الأبدية، ولا يحاكم في اليوم الأخير، لأنه قد انتقل من الموت إلى الحياة.","5:25":"الحق الحق أقول لكم: إن الساعة التي يسمع فيها الأموات صوت ابن الله ستأتي بل هي الآن والذين يسمعونه يحيون.","5:26":"لأنه كما أن للآب حياة في ذاته، فقد أعطى الابن أيضا أن تكون له حياة في ذاته،","5:27":"وأعطاه سلطة أن يدين، لأنه ابن الإنسان.","5:28":"لا تتعجبوا من هذا: فسوف تأتي ساعة يسمع فيها جميع من في القبور صوته،","5:29":"فيخرجون منها: فالذين عملوا الصالحات يخرجون في القيامة المؤدية إلى الحياة، وأما الذين عملوا السيئات ففي القيامة المؤدية إلى الدينونة.","5:30":"وأنا لا يمكن أن أفعل شيئا من تلقاء ذاتي، بل أحكم حسبما أسمع، وحكمي عادل، لأني لا أسعى لتحقيق إرادتي بل إرادة الذي أرسلني.","5:31":"لو كنت أشهد لنفسي، لكانت شهادتي غير صادقة،","5:32":"ولكن غيري يؤدي الشهادة لي، وأنا أعلم أن شهادته لي هي حق.","5:33":"وقد بعثتم رسلا إلى يوحنا فشهد للحق.","5:34":"وأنا أقول هذا لا لأني أعتمد على شهادة إنسان، بل من أجل خلاصكم،","5:35":"فقد كان يوحنا مصباحا متوهجا مضيئا، وشئتم أن تستمتعوا بنوره فترة من الزمن.","5:36":"ولكن لي شهادة أعظم من شهادة يوحنا، وهي شهادة الأعمال التي كلفني الآب أن أنجزها والتي أعملها، فهي تشهد لي مبينة أن الآب أرسلني،","5:37":"والآب الذي أرسلني هو نفسه أيضا يشهد لي. وأنتم لم تسمعوا صوته قط، ولا رأيتم هيئته،","5:38":"ولا ثبتت كلمته في قلوبكم، بدليل أنكم لا تصدقون الذي أرسله.","5:39":"أنتم تدرسون الكتب لأنكم تعتقدون أنها ستهديكم إلى الحياة الأبدية. هذه الكتب تشهد لي،","5:40":"ولكنكم ترفضون أن تأتوا إلي لتكون لكم الحياة.","5:41":"لست أقبل مجدا من عند الناس.","5:42":"ولكني أعرفكم، وأعرف أن محبة الله ليست في نفوسكم.","5:43":"فقد جئت باسم أبي ولم تقبلوني، ولكنكم ترحبون بمن يجيء باسم نفسه.","5:44":"من أين لكم أن تؤمنوا بي وأنتم تقبلون المجد بعضكم من بعض، دون أن تسعوا في طلب المجد الذي لا يمنحه إلا الله !","5:45":"لا تظنوا أني أشكوكم إلى الآب، فإن هنالك من يشكوكم، وهو موسى الذي علقتم عليه رجاءكم.","5:46":"فلو كنتم صدقتم موسى، لكنتم صدقتموني، لأنه هو كتب عني.","5:47":"وإذا كنتم لا تصدقون ما كتبه موسى، فكيف تصدقون كلامي؟»","6:1":"بعد ذلك عبر يسوع بحيرة الجليل، أي بحيرة طبرية، إلى الضفة المقابلة،","6:2":"وتبعه جمع كبير بعدما رأوا آيات شفائه للمرضى.","6:3":"وصعد يسوع وتلاميذه إلى الجبل وجلسوا.","6:4":"وكان عيد الفصح اليهودي قد اقترب.","6:5":"وإذ تطلع يسوع ورأى جمعا كبيرا قادما نحوه، قال لفيلبس: «من أين نشتري خبزا لنطعم هؤلاء كلهم؟»","6:6":"وقد قال هذا ليمتحنه، لأن يسوع كان يعرف ما سيفعله.","6:7":"فأجابه فيلبس: «حتى لو اشترينا خبزا بمئتي دينار، لما كان يكفي ليحصل الواحد منهم على قطعة صغيرة!»","6:8":"فقال له أندراوس، أخو سمعان بطرس، وهو أحد التلاميذ:","6:9":"«هنا ولد معه خمسة أرغفة شعير وسمكتان صغيرتان. ولكن ما هذه لمثل هذا الجمع الكبير؟»","6:10":"فقال يسوع: «أجلسوهم!» وكان هناك عشب كثير. فجلس الرجال، وكان عددهم نحو خمسة آلاف.","6:11":"فأخذ يسوع الأرغفة وشكر، ثم وزع منها على الجالسين، بقدر ما أرادوا. وكذلك فعل بالسمكتين.","6:12":"فلما شبعوا، قال لتلاميذه: «اجمعوا كسر الخبز التي فضلت لكي لا يضيع شيء!»","6:13":"فجمعوها، وملأوا اثنتي عشرة قفة من كسر الخبز الفاضلة عن الآكلين من خمسة أرغفة الشعير.","6:14":"فلما رأى الناس الآية التي صنعها يسوع قالوا: «حقا، هذا هو النبي الآتي إلى العالم».","6:15":"وعلم يسوع أنهم على وشك أن يختطفوه ليقيموه ملكا، فعاد إلى الجبل وحده.","6:16":"ولما حل المساء نزل تلاميذه إلى البحيرة،","6:17":"وركبوا قاربا متجهين إلى كفرناحوم في الضفة المقابلة من البحيرة. وخيم الظلام ولم يكن يسوع قد لحق بهم.","6:18":"وهبت عاصفة قوية، فاضطربت البحيرة.","6:19":"وبعدما جذف التلاميذ نحو ثلاثة أميال أو أربعة، رأوا يسوع يقترب من القارب ماشيا على ماء البحيرة، فاستولى عليهم الخوف،","6:20":"فشجعهم قائلا: «أنا هو لا تخافوا!»","6:21":"فما كادوا يطلبون منه أن يصعد إلى القارب، حتى وصل القارب إلى المكان المقصود.","6:22":"وفي اليوم التالي، لم يجد الجمع الذين باتوا على الضفة المقابلة من البحيرة إلا قاربا واحدا. وكانوا يعرفون أن يسوع لم يركب القارب مع تلاميذه (بالأمس)، بل استقله التلاميذ وحدهم.","6:23":"ثم جاءت قوارب أخرى من طبرية، ورست بالقرب من المكان الذي أكلوا فيه الخبز بعدما شكر الرب عليه.","6:24":"فلما لم يجد الجمع يسوع ولا تلاميذه هناك، ركبوا تلك القوارب وجاءوا إلى كفرناحوم باحثين عن يسوع.","6:25":"فلما وجدوه على الضفة المقابلة من البحيرة، قالوا له: «يامعلم، متى وصلت إلى هنا؟»","6:26":"أجابهم يسوع: «الحق الحق أقول لكم: أنتم تبحثون عني لا لأنكم رأيتم الآيات، بل لأنكم أكلتم وشبعتم من تلك الأرغفة.","6:27":"لا تسعوا وراء الطعام الفاني، بل وراء الطعام الباقي إلى الحياة الأبدية، والذي يعطيكم إياه ابن الإنسان، لأن هذا الطعام قد وضع الله الآب ختمه عليه».","6:28":"فسألوه: «ماذا نفعل لنعمل ما يطلبه الله ؟»","6:29":"أجاب يسوع: «العمل الذي يطلبه الله هو أن تؤمنوا بمن أرسله».","6:30":"فقالوا له: «ما الآية التي تعملها لنراها ونؤمن بك؟ ماذا تقدر أن تعمل؟","6:31":"فإن أباءنا أكلوا المن في البرية كما جاء في الكتاب: أعطاهم من السماء خبزا ليأكلوا!»","6:32":"فأجابهم يسوع: «الحق الحق أقول لكم: إن موسى لم يعطكم خبزا من السماء، وإنما أبي هو الذي يعطيكم الآن خبز السماء الحقيقي،","6:33":"فخبز الله هو النازل من السماء الواهب حياة للعالم».","6:34":"قالوا له: «ياسيد، أعطنا في كل حين هذا الخبز».","6:35":"فأجابهم يسوع: «أنا هو خبز الحياة. فالذي يقبل إلي لا يجوع، والذي يؤمن بي لا يعطش أبدا.","6:36":"ولكن قلت لكم إنكم رأيتموني ولا تؤمنون،","6:37":"ولكن كل ما يهبه الآب لي سيأتي إلي، ومن يأت إلي لا أطرحه إلى الخارج أبدا،","6:38":"فقد نزلت من السماء، لا لأتم مشيئتي، بل مشيئة الذي أرسلني.","6:39":"ومشيئته هي أن لا أدع أحدا ممن وهبهم لي يهلك، بل أقيمه في اليوم الأخير.","6:40":"نعم! إن مشيئة أبي هي أن كل من يرى الابن ويؤمن به تكون له الحياة الأبدية، وسأقيمه أنا في اليوم الأخير».","6:41":"فأخذ اليهود يتذمرون على يسوع لأنه قال: «أنا الخبز الذي نزل من السماء».","6:42":"وقالوا: «أليس هذا يسوع ابن يوسف، الذي نعرف نحن أباه وأمه، فكيف يقول: إني نزلت من السماء؟»","6:43":"فأجابهم يسوع: «لا تتذمروا فيما بينكم!","6:44":"لا يقدر أحد أن يأتي إلي إلا إذا اجتذبه الآب الذي أرسلني. وأنا أقيمه في اليوم الأخير.","6:45":"جاء في كتب الأنبياء: سيتعلم الجميع من الله. وكل من يسمع الآب ويتعلم منه يأتي إلي.","6:46":"وليس معنى هذا أن أحدا رأى الآب: فما رآه إلا الذي كان مع الله. هو وحده رأى الآب.","6:47":"الحق الحق أقول لكم: إن الذي يؤمن بي فله حياة أبدية.","6:48":"أنا هو خبز الحياة.","6:49":"أكل أباؤكم المن في البرية ثم ماتوا،","6:50":"ولكن ها هنا الخبز النازل من السماء ليأكل منه الإنسان فلا يموت.","6:51":"أنا الخبز الحي الذي نزل من السماء. إن أكل أحد من هذا الخبز يحيا إلى الأبد. والخبز الذي أقدمه أنا، هو جسدي، أبذله من أجل أن يحيا العالم».","6:52":"فأثار هذا الكلام جدالا عنيفا بين اليهود، وتساءلوا: «كيف يقدر هذا أن يعطينا جسده لنأكله؟»","6:53":"فأجابهم يسوع: «الحق الحق أقول لكم: إذا لم تأكلوا جسد ابن الإنسان وتشربوا دمه فلا حياة لكم في داخلكم.","6:54":"من يأكل جسدي ويشر ب دمي، فله حياة أبدية، وأنا أقيمه في اليوم الأخير،","6:55":"لأن جسدي هو الطعام الحقيقي، ودمي هو الشراب الحقيقي.","6:56":"وكل من يأكل جسدي ويشرب دمي، يثبت في وأنا فيه.","6:57":"وكما أني أحيا بالآب الحي الذي أرسلني، فكذلك يحيا بي من يأكلني.","6:58":"هذا هو الخبز الذي نزل من السماء، وهو ليس كالمن الذي أكله أباؤكم ثم ماتوا. فالذي يأكل هذا الخبز يحيا إلى الأبد».","6:59":"هذا كله قاله يسوع في المجمع وهو يعلم في كفرناحوم.","6:60":"فلما سمعه كثيرون من تلاميذه قالوا: «ما أصعب هذا الكلام! من يطيق سماعه؟»","6:61":"فعلم يسوع في نفسه أن تلاميذه يتذمرون، فسألهم: «أهذا يبعث الشكوك في نفوسكم؟","6:62":"فماذا لو رأيتم ابن الإنسان صاعدا إلى حيث كان قبلا؟","6:63":"الروح هو الذي يعطي الحياة، أما الجسد فلا يفيد شيئا. الكلام الذي كلمتكم به هو روح وحيا ة.","6:64":"ولكن بعضا منكم لا يؤمنون!» فقد كان يسوع منذ البدء يعرف من هم الذين لا يؤمنون به، ومن هو الذي سيخونه.","6:65":"ثم قال: «لذلك قلت لكم: لا يقدر أحد أن يأتي إلي إلا إذا وهبه الآب ذلك».","6:66":"من ذلك الوقت هجره كثيرون من أتباعه، ولم يعودوا يتبعونه!","6:67":"فقال للاثني عشر تلميذا: «وأنتم أتريدون أن تذهبوا مثلهم؟»","6:68":"فأجابه سمعان بطرس: «إلى من نذهب يار ب وعندك كلام الحياة الأبدية.","6:69":"نحن آمنا وعرفنا أنك قدوس الله!»","6:70":"فقال يسوع: «أليس أنا اخترتكم أنتم الاثني عشر، ومع ذلك فواحد منكم شيطان؟»","6:71":"أشار بهذا إلى يهوذا بن سمعان الإسخريوطي، لأنه من الاثني عشر!","7:1":"بعد ذلك بدأ يسوع يتنقل في منطقة الجليل، متجنبا التجول في منطقة اليهودية، لأن اليهود كانوا يسعون إلى قتله.","7:2":"وعندما اقترب عيد المظال اليهودي،","7:3":"قال له إخوته: «اترك هذه المنطقة واذهب إلى اليهودية ليرى أتباعك ما تعمله من أعمال،","7:4":"فلا أحد يعمل في الخفاء إذا كان يبتغي الشهرة. وما دمت تعمل هذه الأعمال، فأظهر نفسك للعالم».","7:5":"فإن إخوته لم يكونوا مؤمنين به.","7:6":"فأجابهم يسوع: «ما حان وقتي بعد، أما وقتكم فهو مناسب كل حين.","7:7":"لا يقدر العالم أن يبغضكم، ولكنه يبغضني أنا، لأني أشهد عليه أن أعماله شريرة.","7:8":"اصعدوا أنتم إلى العيد، أما أنا فلن أصعد الآن إلى هذا العيد لأن وقتي ما جاء بعد».","7:9":"قال لهم هذا وبقي في الجليل.","7:10":"وبعدما ذهب إخوته إلى العيد، ذهب هو أيضا كما لو كان متخفيا، لا ظاهرا.","7:11":"فأخذ اليهود يبحثون عنه في العيد، ويسألون: «أين ذاك الرجل؟»","7:12":"وثارت بين الجموع مناقشات كثيرة حوله، فقال بعضهم: «إنه صالح» وقال آخرون: «لا! بل إنه يضلل الشعب»","7:13":"ولكن لم يجرؤ أحد أن يتكلم عنه علنا، خوفا من اليهود.","7:14":"ولما مضى من العيد نصفه، صعد يسوع إلى الهيكل وبدأ يعلم الناس.","7:15":"فدهش اليهود وتساءلوا «كيف يعرف هذا الكتب وهو لم يتعلم؟»","7:16":"فأجابهم يسوع: «ليس تعليمي من عندي، بل من عند الذي أرسلني","7:17":"ومن أراد أن يعمل مشيئة الله يعرف ما إذا كان تعليمي من عند الله، أو أنني أتكلم من عندي.","7:18":"من يتكلم من عنده يطلب المجد لنفسه؛ أما الذي يطلب المجد لمن أرسله فهو صادق لا إثم فيه.","7:19":"أما أعطاكم موسى الشريعة؟ ولكن ما من أحد منكم يعمل بالشريعة! لماذا تسعون إلى قتلي؟»","7:20":"أجابه الجمع: «بك شيطان! من يريد أن يقتلك؟»","7:21":"فقال يسوع: «عملت يوم السبت عملا واحدا فاستغربتم جميعا.","7:22":"إن موسى أوصاكم بالختان وهذا لا يعني أن الختان يرجع إلى موسى بل إلى الآباء ولذلك تختنون الإنسان ولو يوم السبت.","7:23":"فإن كنتم تجرون الختان للإنسان يوم السبت لكي لا تخالفوا شريعة موسى، فهل تغضبون علي لأني شفيت إنسانا بكامله في السبت؟","7:24":"لا تحكموا بحسب الظاهر، بل احكموا حكما عادلا».","7:25":"عند ذلك قال بعض أهل أورشليم: «أليس هذا هو الذي يريدون أن يقتلوه؟","7:26":"ها هو يتكلم علنا ولا أحد يعترضه بشيء. ترى، هل تأكد رؤساؤنا أنه هو المسيح حقا؟","7:27":"إن المسيح عندما يأتي لن يعرف أحد من أين جاء، أما هذا فإننا نعرف أصله!»","7:28":"فرفع يسوع صوته، وهو يعلم في الهيكل، قائلا: «أنتم تعرفونني وتعرفون من أين أنا! وأنا لم آت من عند ذاتي، ولكن الذي أرسلني هو حق وأنتم لا تعرفونه.","7:29":"أما أنا فأعرفه، لأني منه وهو الذي أرسلني».","7:30":"فسعى اليهود للقبض عليه، ولكن أحدا لم يلق عليه يدا، لأن ساعته لم تكن قد حانت.","7:31":"على أن كثيرين من الجمع آمنوا به، وقالوا: «ألعل المسيح، عندما يأتي، يجري آيات أكثر من هذه التي يجريها هذا الرجل؟»","7:32":"وسمع الفريسيون ما يتهامس به الجمع عنه، فأرسلوا هم ورؤساء الكهنة بعض الحراس ليلقوا القبض عليه.","7:33":"فقال لهم يسوع: «أنا باق معكم وقتا قليلا، ثم أعود إلى الذي أرسلني.","7:34":"عندئذ تسعون في طلبي ولا تجدونني، ولا تقدرون أن تذهبوا إلى حيث أكون».","7:35":"فتساءل اليهود فيما بينهم: «إلى أين ينوي أن يذهب فلا نجده؟ أيذهب إلى المدن اليونانية التي تشتت فيها اليهود، ويعلم اليونانيين؟","7:36":"وماذا يعني بقوله: تسعون في طلبي فلا تجدونني، ولا تقدرون أن تذهبوا إلى حيث أكون؟»","7:37":"وفي آخر يوم من العيد، وهو أعظم أيامه، وقف يسوع وقال بأعلى صوته: «إن عطش أحد فليأت إلي ويشرب.","7:38":"وكما قال الكتاب، فمن آمن بي تجري من داخله أنهار ماء حي».","7:39":"قال يسوع هذا عن الروح القدس الذي كان المؤمنون به سيقبلونه. ولم يكن الروح قد أعطي بعد لأن يسوع لم يكن قد تمجد بعد.","7:40":"ولما سمع الحاضرون هذا الكلام قال بعضهم: «هذا هو النبي حقا».","7:41":"وقال آخرون: «هذا هو المسيح». ولكن بعضهم قالوا: «وهل يطلع المسيح من الجليل؟","7:42":"أما قال الكتاب إن المسيح سيأتي من نسل داود، ومن قرية بيت لحم حيث كان داود؟»","7:43":"وهكذا حصل بسببه بين الجمع انقسام في الرأي.","7:44":"وأراد بعضهم أن يلقوا القبض عليه؛ ولكن أحدا لم يلق عليه يدا.","7:45":"ورجع حراس الهيكل إلى الفريسيين ورؤساء الكهنة، فسألوهم: «لماذا لم تحضروه؟»","7:46":"فأجابوا: «لم نسمع قط إنسانا يتكلم بمثل كلامه!»","7:47":"فردوا غاضبين: «وهل ضللتم أنتم أيضا؟","7:48":"أرأيتم أحدا من الرؤساء أو من الفريسيين آمن به؟","7:49":"أما عامة الشعب الذين يجهلون الشريعة، فاللعنة عليهم!»","7:50":"ولكن واحدا منهم، وهو نيقوديموس الذي كان قد جاء إلى يسوع ليلا،","7:51":"قال لهم: «أتسمح شريعتنا بأن يحكم على أحد دون سماع دفاعه أولا لمعرفة ذنبه؟»","7:52":"فأجابوه: «ألعلك أنت أيضا من الجليل؟ ادرس الكتاب تعلم أنه لم يطلع قط نبي من الجليل!»","7:53":"ثم انصرف كل واحد إلى بيته.","8:1":"وأما يسوع، فذهب إلى جبل الزيتون.","8:2":"وعند الفجر عاد إلى الهيكل، فاجتمع حوله جمهور الشعب، فجلس يعلمهم.","8:3":"وأحضر إليه معلمو الشريعة والفر يسيون امرأة ضبطت تزني، وأوقفوها في الوسط،","8:4":"وقالوا له: «يامعلم، هذه المرأة ضبطت وهي تزني.","8:5":"وقد أوصانا موسى في شريعته بإعدام أمثالها رجما بالحجارة، فما قولك أنت؟»","8:6":"سألوه ذلك لكي يحرجوه فيجدوا تهمة يحاكمونه بها. أما هو فانحنى وبدأ يكتب بإصبعه على الأرض.","8:7":"ولكنهم ألحوا عليه بالسؤال، فاعتدل وقال لهم: «من كان منكم بلا خطيئة فليرمها أولا بحجر!»","8:8":"ثم انحنى وعاد يكتب على الأرض.","8:9":"فلما سمعوا هذا الكلام انسحبوا جميعا واحدا تلو الآخر، ابتداء من الشيوخ. وبقي يسوع وحده، والمرأة واقفة في مكانها.","8:10":"فاعتدل وقال لها: «أين هم أيتها المرأة؟ ألم يحكم عليك أحد منهم؟»","8:11":"أجابت: «لا أحد ياسيد». فقال لها: «وأنا لا أحكم عليك. اذهبي ولا تعودي تخطئين!»","8:12":"وخاطبهم يسوع أيضا فقال: «أنا نور العالم. من يتبعني فلا يتخبط في الظلام بل يكون له نور الحياة».","8:13":"فاعترضه الفريسيون قائلين: «أنت الآن تشهد لنفسك، فشهادتك لا تصح».","8:14":"فأجاب: «مع أني أشهد لنفسي فإن شهادتي صحيحة، لأنني أعرف من أين أتيت وإلى أين أذهب؛ أما أنتم فلا تعرفون لا من أين أتيت ولا إلى أين أذهب.","8:15":"ولذلك تحكمون علي بحسب البشر، أما أنا فلا أحكم على أحد،","8:16":"مع أنه لو حكمت لجاء حكمي عادلا، لأني لا أحكم بمفردي، بل أنا والآب الذي أرسلني.","8:17":"ومكتوب في شريعتكم أن شهادة شاهدين صحيحة:","8:18":"فأنا أشهد لنفسي، ويشهد لي الآب الذي أرسلني».","8:19":"فسألوه: «أين أبوك؟» فأجاب: «أنتم لا تعرفونني، ولا تعرفون أبي. ولو عرفتموني لعرفتم أبي أيضا».","8:20":"قال يسوع هذا الكلام في الهيكل عند صندوق التقدمات. ولم يلق أحد القبض عليه، لأن ساعته لم تكن قد حانت بعد.","8:21":"ثم قال لهم يسوع: «سوف أذهب فتسعون في طلبي، ولكنكم لا تقدرون أن تأتوا إلى حيث أكون، بل تموتون في خطيئتكم».","8:22":"فأخذ اليهود يتساءلون: «ترى، ماذا يعني قوله لا تقدرون أن تأتوا إلى حيث أكون؟ هل سينتحر؟»","8:23":"فكان رده: «أنتم من تحت. أما أنا فمن فوق. أنتم من هذا العالم. وأنا لست منه.","8:24":"لذلك قلت لكم: ستموتون في خطاياكم، لأنكم إذا لم تؤمنوا بأني أنا هو، تموتون في خطاياكم».","8:25":"فسألوه: «من أنت؟» أجاب يسوع: «قلت لكم من البداية!","8:26":"وعندي أشياء كثيرة أقولها وأحكم بها عليكم. ولكن الذي أرسلني هو حق، وما أقوله للعالم هو ما سمعته منه».","8:27":"ولم يفهموا أن يسوع، بقوله هذا، كان يشير إلى الآب.","8:28":"لذلك قال لهم يسوع: «عندما تعلقون ابن الإنسان تعرفون أني أنا هو، وأني لا أعمل شيئا من نفسي، بل أقول الكلام الذي علمني إياه أبي.","8:29":"إن الذي أرسلني هو معي، ولم يتركني وحدي، لأني دوما أعمل ما يرضيه».","8:30":"وبينما يسوع يتكلم بهذا، آمن به كثيرون.","8:31":"فقال لليهود الذين آمنوا به: «إن ثبتم في كلمتي، كنتم حقا تلاميذي.","8:32":"وتعرفون الحق، والحق يحرركم».","8:33":"فرد اليهود: «نحن أحفاد إبراهيم، ولم نكن قط عبيدا لأحد! كيف تقول لنا: إنكم ستصيرون أحرارا؟»","8:34":"أجابهم يسوع: «الحق الحق أقول لكم: إن من يرتكب الخطيئة يكون عبدا لها.","8:35":"والعبد لا يبقى في بيت سيده دائما؛ أما الابن فيعيش فيه أبدا.","8:36":"فإن حرركم الابن تصيرون بالحق أحرارا.","8:37":"أنا أعرف أنكم أحفاد إبراهيم. ولكنكم تسعون إلى قتلي، لأن كلمتي لا تجد لها مكانا في قلوبكم.","8:38":"إني أتكلم بما رأيته عند الآب، وأنتم تعملون بما سمعتم من أبيكم».","8:39":"فاعترضوه قائلين: «أبونا هو إبراهيم!» فقال لو كنتم أولاد إبراهيم لعملتم أعمال إبراهيم.","8:40":"ولكنكم تسعون إلى قتلي وأنا إنسان كلمتكم بالحق الذي سمعته من الله. وهذا لم يفعله إبراهيم.","8:41":"أنتم تعملون أعمال أبيكم!» فقالوا له: «نحن لم نولد من زنا! لنا أب واحد هو الله ».","8:42":"فقال يسوع: «لو كان الله أباكم لكنتم تحبونني، لأني خرجت من الله وجئت. لم آت من نفسي، بل هو الذي أرسلني.","8:43":"لماذا لا تفهمون كلامي؟ لأنكم لا تطيقون سماع كلمتي!","8:44":"إنكم أولاد أبيكم إبليس، وترغبون أن تعملوا شهوات أبيكم. فهو من البدء كان قاتلا للناس، ولم يثبت في الحق لأنه خال من الحق! وعندما ينطق بالكذب فهو ينضح بما فيه، لأنه كذاب وأبو الكذب!","8:45":"أما أنا فلأني أقول الحق، لستم تصدقونني.","8:46":"من منكم يثبت علي خطيئة؟ فما دمت أقول الحق، فلماذا لا تصدقونني؟","8:47":"من كان من الله حقا، يسمع كلام الله. ولكنكم ترفضون كلام الله، لأنكم لستم من الله!»","8:48":"فقال اليهود: «ألسنا نقول الحق عندما نقول إنك سامري وإن فيك شيطانا؟»","8:49":"أجابهم: «لا شيطان في، لكني أكرم أبي وأنتم تهينونني.","8:50":"أنا لا أطلب مجد نفسي، فهناك من يطالب ويقضي لي.","8:51":"الحق الحق أقول لكم: إن من يطيع كلامي لن يرى الموت أبدا».","8:52":"فقال اليهود: «الآن تأكد لنا أن فيك شيطانا. مات إبراهيم ومات الأنبيا ء، وأنت تقول إن الذي يطيع كلامك لن يذوق الموت أبدا.","8:53":"أأنت أعظم من أبينا إبراهيم الذي مات؟ حتى الأنبياء ماتوا؛ فمن تجعل نفسك؟»","8:54":"أجابهم: «إن كنت أمجد نفسي، فليس مجدي بشيء. لكن أبي هو الذي يمجدني. وأنتم تقولون إنه إلهكم،","8:55":"مع أنكم لا تعرفونه. أما أنا فأعرفه. ولو قلت لكم إني لا أعرفه لكنت مثلكم كاذبا. لكني أعرفه وأعمل بكلمته.","8:56":"أبوكم إبراهيم ابتهج لرجائه أن يرى يومي، فرآه وفرح»","8:57":"فقال له اليهود: «ليس لك من العمر خمسون سنة بعد فكيف رأيت إبراهيم؟»","8:58":"أجابهم: الحق الحق أقول لكم: إنني كائن من قبل أن يكون إبراهيم».","8:59":"فرفعوا حجارة ليرجموه، ولكنه أخفى نفسه وخرج من الهيكل.","9:1":"وفيما كان يسوع مارا، رأى رجلا أعمى منذ ولادته،","9:2":"فسأله تلاميذه: «يامعلم، من أخطأ: هذا أم والداه، حتى ولد أعمى؟»","9:3":"فأجابهم يسوع: «لا هو أخطأ ولا والداه، ولكن حتى تظهر فيه أعمال الله.","9:4":"فعلي أن أعمل أعمال الذي أرسلني مادام الوقت نهارا. فسيأتي الليل، ولا أحد يقدر أن يعمل فيه.","9:5":"وما دمت في العالم، فأنا نور العالم».","9:6":"قال هذا، وتفل في التراب، وجبل من التفل طينا، ثم وضعه على عيني الأعمى،","9:7":"وقال له: «اذهب اغتسل في بركة سلوام» (أي الرسول). فذهب واغتسل وعاد بصيرا.","9:8":"فتساءل الجيران والذين كانوا يرونه من قبل يستعطي: «أليس هذا هو نفسه الذي كان يجلس ليستعطي؟»","9:9":"قال بعضهم: «هذا هو». وآخرون: «لا ... ولكنه يشبهه!» أما هو فرد قائلا: «بل أنا هو!»","9:10":"فقالوا له: «وكيف انفتحت عيناك؟»","9:11":"أجاب: «الرجل الذي اسمه يسوع جبل طينا دهن به عيني، وقال لي: اذهب إلى بركة سلوام واغتسل فيها. فذهبت واغتسلت فأبصرت!»","9:12":"فسألوه: «وأين هو الآن؟» فقال: «لا أعرف!»","9:13":"فذهبوا بالرجل الذي كان أعمى إلى الفريسيين.","9:14":"وكان اليوم الذي جبل فيه يسوع الطين وفتح عيني الأعمى، يوم سبت.","9:15":"فسأله الفريسيون أيضا كيف أبصر. فأجاب: «وضع طينا على عيني، واغتسلت، وها أنا أبصر!»","9:16":"فقال بعض الفريسيين: «لا يمكن أن يكون هذا الرجل من الله، لأنه يخالف سنة السبت». ولكن بعضهم قالوا: «كيف يقدر رجل خاطيء أن يعمل مثل هذه الآيات؟» فوقع الخلاف بينهم.","9:17":"وعادوا يسألون الذي كان أعمى: «وما رأيك أنت فيه مادام قد فتح عينيك؟» فأجابهم: «إنه نبي!»","9:18":"ورفض اليهود أن يصدقوا أنه كان أعمى فأبصر، فاستدعوا والديه","9:19":"وسألوهما: «أهذا ابنكما المولود أعمى كما تقولان؟ فكيف يبصر الآن؟»","9:20":"أجابهم الوالدان: «نعلم أن هذا ابننا وأنه ولد أعمى.","9:21":"ولكننا لا نعلم كيف يبصر الآن، ولا من فتح عينيه. إنه بالغ الرشد، يجيبكم عن نفسه، فاسألوه!»","9:22":"وقد قال والداه هذا لخوفهما من اليهود، لأن اليهود كانوا قد اتفقوا أن يطردوا من المجمع كل من يعترف أن يسوع هو المسيح.","9:23":"لذلك قالا: «إنه بالغ الرشد فاسألوه».","9:24":"ثم استدعى الفريسيون، مرة ثانية الرجل الذي كان أعمى، وقالوا له: «مجد الله ! نحن نعلم أن هذا الرجل خاطيء».","9:25":"فأجاب: «أخاطيء هو، لست أعلم! إنما أعلم شيئا واحدا: أني كنت أعمى والآن أبصر!»","9:26":"فسألوه ثانية: «ماذا فعل بك؟ كيف فتح عينيك؟»","9:27":"أجابهم: «قد قلت لكم ولم تسمعوا لي، فلماذا تريدون أن تسمعوا مرة ثانية؟ ألعلكم تريدون أنتم أيضا أن تصيروا تلاميذ له؟»","9:28":"فشتموه وقالوا له: «بل أنت تلميذه ! أما نحن فتلاميذ موسى.","9:29":"نحن نعلم أن موسى كلمه الله ؛ أما هذا، فلا نعلم له أصلا!»","9:30":"فأجابهم الرجل: «إن في ذلك عجبا! إنه فتح عيني، وتقولون إنكم لا تعلمون له أصلا!","9:31":"نحن نعلم أن الله لا يستجيب للخاطئين، ولكنه يستمع لمن يتقيه ويعمل بإرادته،","9:32":"ولم يسمع على مدى الأجيال أن أحدا فتح عيني مولود أعمى!","9:33":"فلو لم يكن هو من الله، لما استطاع أن يعمل شيئا».","9:34":"فصاحوا به: «أنت بكاملك ولدت في الخطيئة وتعلمنا؟!» ثم طردوه خارج المجمع.","9:35":"وعرف يسوع بطرده خارجا، فقصد إليه وسأله: «أتؤمن بابن الله؟»","9:36":"أجاب: «من هو ياسيد حتى أومن به؟»","9:37":"فقال له يسوع: «الذي قد رأيته، والذي يكلمك، هو نفسه!»","9:38":"فقال: «أنا أومن ياسيد!» وسجد له.","9:39":"فقال يسوع: «لدينونة أتيت إلى هذا العالم: ليبصر العميان، ويعمى المبصرون!»","9:40":"فسمع ذلك بعض الفريسيين الذين كانوا معه فسألوه: «وهل نحن أيضا عميان؟»","9:41":"فأجابهم يسوع: «لو كنتم عميانا بالفعل، لما كانت عليكم خطيئة. ولكنكم تدعون أنكم تبصرون، ولذلك فإن خطيئتكم باقية...»","10:1":"الحق الحق أقول لكم: إن من يدخل إلى حظيرة الخراف من غير بابها فيتسلق إليها من طريق آخر، فهو سارق ولص.","10:2":"أما الذي يدخل من الباب فهو راعي الخراف،","10:3":"والبواب يفتح له، والخراف تصغي إلى صوته، فينادي خرافه الخاصة كل واحد باسمه، ويقودها إلى خارج الحظيرة.","10:4":"ومتى أخرجها كلها، يسير أمامها وهي تتبعه، لأنها تعرف صوته.","10:5":"وهي لا تتبع من كان غريبا، بل تهرب منه، لأنها لا تعرف صوت الغرباء».","10:6":"ضرب يسوع لهم هذا المثل، ولكنهم لم يفهموا مغزى كلامه.","10:7":"لذلك عاد فقال: «الحق الحق أقول لكم: أنا باب الخراف.","10:8":"جميع الذين جاءوا قبلي كانوا لصوصا وسراقا، ولكن الخر اف لم تصغ إليهم.","10:9":"أنا الباب. من دخل بي يخلص، فيدخل ويخرج ويجد المرعى.","10:10":"السارق لا يأتي إلا ليسرق ويذبح ويهلك. أما أنا فقد أتيت لتكون لهم حياة، بل ملء الحياة!","10:11":"أنا الراعي الصالح، والراعي الصالح يبذل حياته فدى خرافه.","10:12":"وليس الأجير كالراعي، لأن الخراف ليست ملكه. فعندما يرى الذئب قادما، يترك الخراف لينجو بنفسه، فيخطف الذئب الخراف ويبددها.","10:13":"إنه يهرب لأنه أجير ولا يبالي بالخراف!","10:14":"أما أنا فإني الراعي الصالح، وأعرف خرافي، وخر افي تعرفني،","10:15":"مثلما يعرفني الآب وأنا أعرفه. وأنا أبذل حياتي فدى خرافي.","10:16":"ولي خراف أخرى لا تنتمي إلى هذه الحظيرة، لا بد أن أجمعها إلي أيضا، فتصغي لصوتي؛ فيكون هناك قطيع واحد وراع واحد.","10:17":"إن الآب يحبني لأني أبذل حياتي لكي أستردها.","10:18":"لا أحد ينتزع حياتي مني، بل أنا أبذلها باختياري. فلي السلطة أن أبذلها ولي السلطة أن أستردها. هذه الوصية تلقيتها من أبي».","10:19":"فانقسم اليهود في الرأي حول هذا الكلام.","10:20":"فقال كثيرون منهم: «إن شيطانا يسكنه، وهو يهذي. فلماذا تستمعون إليه؟»","10:21":"وقال آخرون: «ليس هذا كلام من يسكنه شيطان. أيستطيع الشيطان أن يفتح عيون العميان؟»","10:22":"وفي أثناء الاحتفال بعيد تجديد الهيكل، في الشتاء،","10:23":"كان يسوع يتمشى في الهيكل في قاعة سليمان.","10:24":"فتجمع حوله اليهود وقالوا له: «حتى متى تبقينا حائرين بشأنك؟ إن كنت أنت المسيح حقا، فقل لنا صراحة».","10:25":"فأجابهم يسوع: «قلت لكم، ولكنكم لا تصدقون. والأعمال التي أعملها باسم أبي، هي تشهد لي.","10:26":"ولكنكم لا تصدقون لأنكم لستم خرافي.","10:27":"فخرافي تصغي لصوتي، وأنا أعرفها وهي تتبعني،","10:28":"وأعطيها حياة أبدية، فلا تهلك إلى الأبد، ولا ينتزعها أحد من يدي.","10:29":"إن الآب الذي أعطاني إياها هو أعظم من الجميع، ولا يقدر أحد أن ينتزع من يد الآب شيئا.","10:30":"أنا والآب واحد!»","10:31":"فرفع اليهود، مرة ثانية، حجارة ليرجموه.","10:32":"فقال لهم يسوع: «أريتكم أعمالا صالحة كثيرة من عند أبي، فبسبب أي عمل منها ترجمونني؟»","10:33":"أجابوه: «لا نرجمك بسبب أي عمل صالح، بل بسبب تجديفك: لأنك تجعل نفسك الله ، وأنت إنسان!»","10:34":"فقال لهم يسوع: «أليس مكتوبا في شريعتكم: أنا قلت إنكم آلهة؟","10:35":"فإذا كانت الشريعة تدعو أولئك الذين نزلت إليهم كلمة الله آلهة والكتاب لا يمكن أن ينقض","10:36":"فهل تقولون لمن قدسه الآب وبعثه إلى العالم: أنت تجدف، لأني قلت: أنا ابن الله؟","10:37":"إن كنت لا أعمل أعمال أبي، فلا تصدقوني.","10:38":"أما إن كنت أفعل ذلك، فصدقوا تلك الأعمال، إن كنتم لا تصدقونني أنا. عندئذ تعرفون ويتأكد لكم أن الآب في وأنا فيه».","10:39":"فأرادوا ثانية أن يلقوا القبض عليه، ولكنه أفلت من أيديهم،","10:40":"ورجع إلى الضفة المقابلة من نهر الأردن، حيث كان يوحنا يعمد من قبل، وأقام هناك.","10:41":"فجاء إليه كثيرون وهم يقولون: «ما عمل يوحنا آية واحدة، ولكن كل ما قاله عن هذا الرجل كان حقا!»","10:42":"وآمن به كثيرون هناك.","11:1":"ولكن، مرض إنسان اسمه لعازر، وهو من بيت عنيا قرية مريم ومرثا أختها.","11:2":"ومريم هذه هي التي دهنت الرب بالعطر ومسحت قدميه بشعرها وكان لعازر المريض أخاها.","11:3":"فأرسلت الأختان إلى يسوع تقولان: «ياسيد، إن الذي تحبه مريض».","11:4":"فلما سمع بذلك قال: «لن ينتهي هذا المرض بالموت، بل سيؤدي إلى تمجيد الله، إذ به سيتمجد ابن الله».","11:5":"ومع أن يسوع كان يحب مرثا وأختها ولعازر،","11:6":"فقد مكث حيث كان مدة يومين بعد علمه بمرض لعازر .","11:7":"وبعد ذلك قال لتلاميذه: «لنرجع إلى اليهودية!»","11:8":"فقال التلاميذ: «يامعلم، أترجع إلى اليهودية، ومنذ وقت قريب أراد اليهود أن يرجموك؟»","11:9":"فأجاب يسوع: «أليست ساعات النهار اثنتي عشرة؟ فالذي يمشي في النهار لا يتعثر لأنه يرى نور هذا العالم.","11:10":"أما الذي يمشي في الليل فإنه يتعثر، لأن النور ليس فيه».","11:11":"ثم قال يسوع: «لعازر حبيبنا قد رقد، ولكني سأذهب لأنهضه».","11:12":"فقال التلَاميذ: «ياسيد، إن كان قد رقد، فإنه سينهض معافى».","11:13":"وكان يسوع يعني موت لعازر ؛ أما التلاميذ فظنوه يعني رقاد النوم.","11:14":"عندئذ قال لهم صراحة: «لعازر قد مات.","11:15":"ولأجلكم أنا أفرح بأني لم أكن هناك، حتى تؤمنوا. فلنذهب إليه!»","11:16":"فقال توما، المعروف بالتوأم، للتلاميذ الآخرين: «لنذهب نحن أيضا فنقتل معه!» (أي مع يسوع).","11:17":"وعندما وصل يسوع إلى بيت عنيا كان لعازر قد دفن منذ أربعة أيام.","11:18":"وكانت بيت عنيا لا تبعد عن أورشليم إلا حوالي ميلين.","11:19":"وكان كثيرون من اليهود قد توافدوا إلى مرثا ومريم يعزونهما عن أخيهما.","11:20":"فلما عرفت مرثا أن يسوع قادم خرجت للقائه، وبقيت مريم جالسة في البيت.","11:21":"وقالت مرثا ليسوع: «ياسيد، لو كنت هنا، لما مات أخي.","11:22":"فأنا واثقة تماما بأن الله يعطيك كل ما تطلب منه».","11:23":"فأجاب يسوع: «سيقوم أخوك».","11:24":"قالت مرثا: «أعرف أنه سيقوم في القيامة، في اليوم الأخير!»","11:25":"فرد يسوع: «أنا هو القيامة والحياة. من آمن بي، وإن مات فسيحيا.","11:26":"ومن كان حيا وآمن بي فلن يموت إلى الأبد. أتؤمنين بهذا؟»","11:27":"أجابته: «نعم ياسيد. أنا قد آمنت أنك أنت المسيح ابن الله الذي جاء إلى العالم!»","11:28":"قالت هذا، وذهبت تدعو أختها مريم، فقالت لها سرا: «المعلم هنا، وهو يطلبك!»","11:29":"فلما سمعت مريم هبت واقفة، وأسرعت إلى يسوع.","11:30":"ولم يكن قد وصل بعد إلى القرية، بل كان لايزال في المكان الذي لاقته فيه مرثا.","11:31":"فلما رآها اليهود، الذين كانوا معها في البيت يعزونها، تهب واقفة وتسرع بالخروج، لحقوا بها، لأنهم ظنوا أنها ذاهبة لتبكي عند القبر.","11:32":"وما إن وصلت مريم إلى حيث كان يسوع ورأته، حتى ارتمت على قدميه تقول: «ياسيد، لو كنت هنا، لما مات أخي!»","11:33":"فلما رآها يسوع تبكي ويبكي معها اليهود الذين رافقوها، فاض قلبه بالأسى الشديد،","11:34":"وسأل: «أين دفنتموه؟» فأجابوا: «تعال، ياسيد، وانظر!»","11:35":"عندئذ بكى يسوع.","11:36":"فقال اليهود بعضهم لبعض: «انظروا كم كان يحبه!»","11:37":"وتساءل بعضهم: «ألم يقدر هذا الذي فتح عيني الأعمى أن يرد الموت عن لعازر؟»","11:38":"ففاض قلب يسوع بالأسى الشديد مرة ثانية. ثم اقترب إلى القبر، وكان كهفا على بابه حجر كبير.","11:39":"وقال: «ارفعوا الحجر!» فقالت مرثا: «ياسيد، هذا يومه الرابع، وقد أنتن».","11:40":"فقال يسوع: «ألم أقل لك: إن آمنت ترين مجد الله؟»","11:41":"فرفعوا الحجر، ورفع يسوع عينيه إلى السماء وقال: «أيها الآب، أشكرك لأنك سمعت لي،","11:42":"وقد علمت أنك دوما تسمع لي. ولكني قلت هذا لأجل الجمع الواقف حولي ليؤمنوا أنك أنت أرسلتني».","11:43":"ثم نادى بصوت عال: «لعازر اخرج!»","11:44":"فخرج الميت والأكفان تشد يديه ورجليه، والمنديل يلف رأسه. فقال يسوع لمن حوله: «حلوه ودعوه يذهب!»","11:45":"وآمن بيسوع كثيرون من اليهود الذين جاءوا ليعزوا مريم، عندما رأوه يعمل ذلك.","11:46":"على أن جماعة منهم ذهبوا إلى الفر يسيين وأخبروهم بما عمله يسوع.","11:47":"فعقد رؤساء الكهنة والفريسيون مجلسا، وقالوا: «ماذا نفعل؟ هذا الرجل يعمل آيات كثيرة.","11:48":"فإذا تركناه وشأنه يؤمن به الجميع، فيأتي الرومانيون ويدمرون هيكلنا المقدس وأمتنا!»","11:49":"فقال واحد منهم، وهو قيافا الذي كان رئيسا للكهنة في تلك السنة: «إنكم لا تعرفون شيئا!","11:50":"ألا تفهمون أنه من الأفضل أن يموت رجل واحد فدى الأمة، بدلا من أن تهلك الأمة كلها».","11:51":"ولم يقل قيافا هذا الكلام من عنده، ولكن إذ كان رئيسا للكهنة في تلك السنة تنبأ أن يسوع سيموت فدى الأمة،","11:52":"وليس فدى الأمة وحسب بل أيضا ليجمع أبناء الله المشتتين فيجعلهم واحدا.","11:53":"من ذلك اليوم قرر اليهود أن يقتلوا يسوع.","11:54":"فلم يعد يتجول بينهم جهارا، بل ذهب إلى مدينة اسمها أفرايم، تقع في بقعة قريبة من البرية، حيث أقام مع تلاميذه.","11:55":"وكان عيد الفصح اليهودي قد اقترب، فتوافد كثيرون من القرى إلى أورشليم ليقوموا بطقوس التطهر السابقة للعيد.","11:56":"وكانوا يبحثون عن يسوع، ويتساءلون وهم مجتمعون في الهيكل: «ما رأيكم؟ ألعله لا يأتي إلى العيد؟»","11:57":"وكان رؤساء الكهنة والفريسيون قد أصدروا أمرا بأن على كل من يجد يسوع أن يبلغ عنه ليلقوا القبض عليه.","12:1":"وقبل الفصح بستة أيام جاء يسوع إلى بيت عنيا، بلدة لعازر الذي أقامه من بين الأموات.","12:2":"فأقيمت له وليمة عشاء، وأخذت مرثا تخدم، وكان لعازر أحد المتكئين معه.","12:3":"فأخذت مريم منا (أي ثلث لتر) من عطر الناردين الخالص الغالي الثمن، ودهنت به قدمي يسوع، ثم مسحتهما بشعرها، فملأت الرائحة الطيبة أرجاء البيت كله.","12:4":"فقال أحد التلاميذ، وهو يهوذا الإسخريوطي، الذي كان سيخون يسوع:","12:5":"«لماذا لم يبع هذا العطر بثلاث مئة دينار توزع على الفقر اء؟»","12:6":"ولم يقل هذا لأنه كان يعطف على الفقراء، بل لأنه كان لصا، فقد كان أمينا للصندوق وكان يختلس مما يودع فيه.","12:7":"فأجابه يسوع: «دعها! فقد احتفظت بهذا العطر ليوم دفني،","12:8":"لأن الفقراء عندكم في كل حين؛ أما أنا فلن أكون عندكم في كل حين».","12:9":"وعلم كثيرون من اليهود أن يسوع في بيت عنيا، فجاءوا لا ليروا يسوع فقط، بل ليروا أيضا لعازر الذي أقامه من بين الأموات.","12:10":"فقرر رؤساء الكهنة أن يقتلوا لعازر أيضا،","12:11":"لأن كثيرين من اليهود كانوا يهجرونهم بسببه ويؤمنون بيسوع.","12:12":"وفي اليوم التالي، عرف الجمهور الكبير الذي جاء إلى العيد أن يسوع قادم إلى أورشليم.","12:13":"فحملوا سعف النخل وخر جوا لاستقباله هاتفين: «أوصنا! تبارك الآتي باسم الرب! إنه ملك إسرائيل!»","12:14":"ووجد يسوع جحشا فركب عليه، كما قد كتب:","12:15":"«لا تخافي يابنت صهيون، فإن ملكك قادم إليك راكبا على جحش أتان».","12:16":"ولم يدرك تلاميذ يسوع أول الأمر أن هذا إتمام للنبوءة. ولكن بعدما تمجد يسوع تذكروا أن الكتاب قال هذا عنه، وأنهم فعلوا هذا من أجله.","12:17":"والجمع الذين كانوا معه حين دعا لعازر من القبر وأقامه من بين الأموات، كانوا يشهدون له بذلك.","12:18":"ولذلك خرجت الجموع لاستقباله، لأنهم سمعوا أنه أجرى تلك الآية.","12:19":"فقال الفريسيون بعضهم لبعض: «أرأيتم كيف أنكم لم تستفيدوا شيئا؟ ها قد انطلق العالم كله وراءه!»","12:20":"وكان بين الذين قصدوا أورشليم للعبادة في أثناء العيد بعض اليونانيين،","12:21":"فذهبوا إلى فيلبس، وهو من بيت صيدا في منطقة الجليل، وقالوا له: «ياسيد، نريد أن نرى يسوع».","12:22":"فجاء فيلبس وأخبر أندراوس، ثم ذهبا معا وأخبرا يسوع.","12:23":"فقال يسوع لهما: «قد اقتربت ساعة تمجيد ابن الإنسان.","12:24":"الحق الحق أقول لكم: إن حبة الحنطة تبقى وحيدة إن لم تقع في الأرض وتمت. أما إذا ماتت، فإنها تنتج حبا كثيرا.","12:25":"من يتمسك بحياته، يخسرها. ومن نبذها في هذا العالم يوفرها للحياة الأبدية.","12:26":"من أراد أن يخدمني فليتبعني. وحيث أكون أنا يكون خادمي أيضا. وكل من يخدمني يكرمه أبي.","12:27":"نفسي الآن مضطربة، فماذا أقول؟ أيها الآب أنقذني من الساعة القادمة علي؟ لا! فمن أجل هذه الساعة أتيت.","12:28":"أيها الآب، مجد اسمك!»","12:29":"فقال بعض الحاضرين ممن سمعوا الصوت: «هذا صوت رعد!» ولكن غيرهم قالوا: «حدثه ملاك».","12:30":"فأجاب يسوع: «لم يكن هذا الصوت لأجلي بل لأجلكم.","12:31":"الآن وقت الحكم على هذا العالم! الآن يطرد سيد هذا العالم خارجا!","12:32":"وحين أعلق مرفوعا عن الأرض أجذب إلي الجميع».","12:33":"قال هذا مشيرا إلى الميتة التي سيموتها.","12:34":"فقال بعض الحاضرين: «علمتنا الشريعة أن المسيح يبقى حيا إلى الأبد، فكيف تقول إن ابن الإنسان لابد أن يعلق؟ من هو ابن الإنسان هذا؟»","12:35":"فقال لهم يسوع: «النور باق معكم وقتا قصيرا. فواصلوا سيركم مادام النور يشرق عليكم، لئلا يطبق عليكم الظلام، فإن الذي يمشي في الظلام لا يعلم أين يذهب.","12:36":"آمنوا بالنور مادام النور معكم، فتصيروا أبناء النور».","12:37":"ومع أنه أجرى أمامهم آيات كثيرة جدا، لم يؤمنوا به،","12:38":"ليتم قول النبي إشعياء: «يارب من آمن بكلامنا؟ ولمن ظهرت يد الرب؟»","12:39":"فلم يستطيعوا أن يؤمنوا، لأن إشعياء قال أيضا:","12:40":"«أعمى عيونهم وقسى قلوبهم، لئلا يبصروا بعيونهم ويفهموا بقلوبهم، ويتوبوا فأشفيهم».","12:41":"وقد قال إشعياء هذا عندما رأى مجد الرب فتحدث عنه.","12:42":"ومع ذلك فإن كثيرين من الرؤساء آمنوا بيسوع، دون أن يجاهروا بإيمانهم، مخافة أن يحكم عليهم بالطرد من المجمع،","12:43":"مفضلين المجد الآتي من الناس على المجد الآتي من الله.","12:44":"فقال يسوع بصوت عال: «من يؤمن بي، فهو يؤمن لا بي أنا بل بالذي أرسلني،","12:45":"ومن رآني، رأى الذي أرسلني","12:46":"جئت إلى العالم نورا، فمن آمن بي لا يبقى في الظلام.","12:47":"وإذا سمع أحد كلامي ولم يؤمن به، فأنا لا أحكم عليه، فقد جئت لا لأحكم على العالم، بل لأخلص العالم.","12:48":"فالذي يرفضني ولا يقبل كلامي، له من يحكم عليه: فإن الكلمة التي قلتها هي تحكم عليه في اليوم الأخير؛","12:49":"لأني لم أتكلم بشيء من عندي، بل أقول ما أوصاني به الآب الذي أرسلني","12:50":"وأنا أعلم أن وصيته هي حياة أبدية: فإن ما أقوله من كلام، أقوله كما قاله لي الآب».","13:1":"وقبيل عيد الفصح، ويسوع عالم أن ساعته قد حانت ليرحل من هذا العالم إلى الآب، فإذ كان قد أحب خاصته الذين في العالم، أحبهم الآن أقصى المحبة:","13:2":"ففي أثناء العشاء، وكان الشيطان قد وضع في قلب يهوذا بن سمعان الإسخريوطي أن يخون يسوع،","13:3":"وكان يسوع عالما أن الآب قد جعل كل شيء في يديه وأنه من الله خرج وإلى الله سيعود،","13:4":"نهض عن مائدة العشاء، وخلع رداءه وأخذ منشفة لفها على وسطه،","13:5":"ثم صب ماء في وعاء للغسل، وبدأ يغسل أقدام التلاميذ ويمسحها بالمنشفة التي على وسطه.","13:6":"فلما وصل إلى سمعان بطرس، قال له سمعان: «ياسيد، أنت تغسل قدمي!»","13:7":"فأجابه يسوع: «أنت الآن لا تفهم ما أعمله، ولكنك ستفهم فيما بعد».","13:8":"ولكن بطرس أصر قائلا: «لا، لن تغسل قدمي أبدا!» فأجابه يسوع: «إن كنت لا أغسلك، فلا يكون لك نصيب معي!»","13:9":"عندئذ قال له سمعان بطرس: «ياسيد، لا قدمي فقط، بل يدي ورأسي أيضا!»","13:10":"فقال يسوع: «من اغتسل صار كله نقيا، ولا يحتاج إلا لغسل قدميه. وأنتم أنقياء، ولكن ليس كلكم».","13:11":"فإن يسوع كان يعلم من الذي سيخونه، ولذلك قال: «لستم كلكم أنقياء».","13:12":"وبعدما انتهى من غسل أقدامهم، أخذ رداءه واتكأ من جديد، وسألهم: «أفهمتم ما عملته لكم؟","13:13":"أنتم تدعونني معلما وسيدا، وقد صدقتم، فأنا كذلك.","13:14":"فإن كنت، وأنا السيد والمعلم، قد غسلت أقدامكم، فعليكم أنتم أيضا أن يغسل بعضكم أقدام بعض.","13:15":"فقد قدمت لكم مثالا لكي تعملوا مثل ما عملت أنا لكم.","13:16":"الحق الحق أقول لكم: ليس عبد أعظم من سيده، ولا رسول أعظم من مرسله.","13:17":"فإن كنتم قد عرفتم هذا، فطوبى لكم إذا عملتم به.","13:18":"وأنا لا أقول هذا عن جميعكم، فأنا أعرف الذين اخترتهم. ولكن لابد أن يتم الكتاب حيث يقول: الآكل من خبزي، رفع علي عقبه!","13:19":"وإني أقول لكم ما سيحدث، قبل حدوثه، حتى متى حدث تؤمنون أني أنا هو.","13:20":"الحق الحق أقول لكم: من يقبل الذي أرسله، يقبلني؛ ومن يقبلني، يقبل الذي أرسلني».","13:21":"ولما قال يسوع هذا اضطربت نفسه وأعلن قائلا: «الحق الحق أقول لكم: إن واحدا منكم سيسلمني!»","13:22":"فتبادل التلاميذ نظرات الحيرة وهم لا يدرون من هو الذي يعنيه.","13:23":"وكان التلميذ الذي يحبه يسوع متكئا على حضنه،","13:24":"فأشار إليه سمعان بطرس أن يسأل يسوع من هو الذي يعنيه.","13:25":"فمال على صدر يسوع وسأله: «من هو ياسيد؟»","13:26":"فأجاب يسوع: «هو الذي أعطيه اللقمة التي أغمسها». ثم غمس اللقمة وأعطاها ليهوذا بن سمعان الإسخريوطي.","13:27":"وبعد اللقمة، دخله الشيطان. فقال له يسوع: «أسرع في ما نويت أن تعمله!»","13:28":"ولم يفهم أحد من المتكئين لماذا قال له ذلك،","13:29":"بل ظن بعضهم أنه يأمره أن يشتري ما يحتاجون إليه في العيد، أو أن يعطي الفقراء بعض المال، لأنه كان أمينا للصندوق.","13:30":"وما إن تناول يهوذا اللقمة، حتى خرج وكان الليل قد أظلم.","13:31":"ولما خرج يهوذا، قال يسوع: «الآن تمجد ابن الإنسان وتمجد الله فيه.","13:32":"وما دام الله قد تمجد فيه، فإنه سيمجده في ذاته، وسريعا سيمجده.","13:33":"ياأولادي الصغار، سأبقى عندكم وقتا قصيرا بعد، ثم تطلبونني، ولكني أقول لكم ما سبق أن قلته لليهود: إنكم لا تقدرون أن تأتوا حيث أنا ذاهب.","13:34":"وصية جديدة أنا أعطيكم: أحبوا بعضكم بعضا، كما أحببتكم أنا، تحبون بعضكم.","13:35":"بهذا يعرف الجميع أنكم تلاميذي: إن كنتم تحبون بعضكم بعضا».","13:36":"فسأله سمعان بطرس: «ياسيد، أين تذهب؟» أجابه يسوع: «لا تقدر أن تتبعني الآن حيث أذهب، ولكنك ستتبعني فيما بعد».","13:37":"فعاد بطرس يسأل: «ياسيد، لماذا لا أقدر أن أتبعك الآن؟ إني أبذل حياتي عوضا عنك!»","13:38":"أجابه يسوع: «أتبذل حياتك عوضا عني؟ الحق الحق أقول لك: لا يصيح الديك حتى تكون قد أنكرتني ثلاث مرات!»","14:1":"«لا تضطرب قلوبكم. أنتم تؤمنون بالله، فآمنوا بي أيضا.","14:2":"في بيت أبي منازل كثيرة، ولو لم يكن الأمر كذلك لقلت لكم! فإني ذاهب لأعد لكم مكانا.","14:3":"وبعدما أذهب وأعد لكم المكان أعود إليكم وآخذكم إلي، لتكونوا حيث أكون أنا.","14:4":"أنتم تعرفون أين أنا ذاهب، وتعرفون الطريق».","14:5":"فقال توما: «ياسيد، لا نعرف أين أنت ذاهب، فكيف نعرف الطريق؟»","14:6":"فأجابه يسوع: «أنا هو الطريق والحق والحياة. لا يأتي أحد إلى الآب إلا بي.","14:7":"إن كنتم قد عرفتموني، فقد عرفتم أبي أيضا، ومنذ الآن تعرفونه وقد رأيتموه».","14:8":"فقال له فيلبس: «ياسيد، أرنا الآب وكفانا!»","14:9":"فأجابه يسوع: «مضت هذه المدة الطويلة وأنا معكم ولم تعرفني يافيلبس؟ الذي رآني رأى الآب، فكيف تقول: أرنا الآب؟","14:10":"ألا تؤمن أني أنا في الآب، وأن الآب في؟ الكلام الذي أقوله لا أقوله من عندي، وإنما الآب الحال في هو يعمل أعماله هذه.","14:11":"صدقوا قولي: إني أنا في الآب وإن الآب في، وإلا فصدقوني بسبب تلك الأعمال.","14:12":"الحق الحق أقول لكم: إن من يؤمن بي يعمل الأعمال التي أنا أعملها، بل يعمل أعظم منها، لأني ذاهب إلى أبي.","14:13":"فأي شيء تطلبونه باسمي أفعله لكم، ليتمجد الآب في الابن.","14:14":"إن طلبتم شيئا باسمي، فإني أفعله.","14:15":"إن كنتم تحبونني فاعملوا بوصاياي.","14:16":"وسوف أطلب من الآب أن يعطيكم معينا آخر يبقى معكم إلى الأبد،","14:17":"وهو روح الحق، الذي لا يقدر العالم أن يتقبله لأنه لا يراه ولا يعرفه، وأما أنتم فتعرفونه لأنه في وسطكم، وسيكون في داخلكم.","14:18":"لن أترككم يتامى، بل سأعود إليكم.","14:19":"بعد قليل لا يراني العالم. أما أنتم فسوف ترونني. ولأني أنا حي، فأنتم أيضا ستحيون.","14:20":"في ذلك اليوم تعلمون أني أنا في أبي، وأنتم في، وأنا فيكم.","14:21":"من كانت عنده وصاياي، ويعمل بها، فذاك يحبني. والذي يحبني، يحبه أبي، وأنا أحبه وأعلن له ذاتي».","14:22":"فسأله يهوذا، غير الإسخريوطي: «ياسيد، ماذا جرى حتى تعلن لنا ذاتك ولا تعلنها للعالم؟»","14:23":"أجابه يسوع: «من يحبني يعمل بكلمتي، ويحبه أبي، وإليه نأتي، وعنده نجعل لنا منزلا.","14:24":"والذي لا يحبني لا يعمل بكلامي. وليس هذا الكلام الذي تسمعونه من عندي، بل من الآب الذي أرسلني،","14:25":"وقد قلت لكم هذه الأمور وأنا مازلت عندكم.","14:26":"وأما الروح القدس، المعين الذي سيرسله الآب باسمي، فإنه يعلمكم كل شيء، ويذكركم بكل ما قلته لكم.","14:27":"سلاما أترك لكم. سلامي أعطيكم. ليس كما يعطي العالم أعطيكم أنا. فلا تضطرب قلوبكم، ولا ترتعب.","14:28":"سمعتم أني قلت لكم: إني ذاهب عنكم ثم أعود إليكم. فلو كنتم تحبونني، لكنتم تبتهجون لأني ذاهب إلى الآب، لأن الآب أعظم مني.","14:29":"ها قد أخبرتكم بالأمر قبل حدوثه، حتى متى حدث تؤمنون.","14:30":"لن أكلمكم كثيرا بعد، فإن سيد هذا العالم قادم علي، ولا شيء له في.","14:31":"إلا أن هذا سيحدث ليعرف العالم أني أحب الآب، وأني مثلما أوصاني الآب هكذا أفعل. قوموا! لنذهب من هنا!","15:1":"«أنا الكرمة الحقيقية، وأبي هو الكرام.","15:2":"كل غصن في لا ينتج ثمرا يقطعه؛ وكل غصن ينتج ثمرا ينقيه لينتج مزيدا من الثمر.","15:3":"أنتم الآن أنقياء بسبب الكلمة التي خاطبتكم بها.","15:4":"فاثبتوا في وأنا فيكم. كما أن الغصن لا يقدر أن ينتج ثمرا إلا إذا ثبت في الكرمة؛ فكذلك أنتم، إلا إذا ثبتم في.","15:5":"أنا الكرمة وأنتم الأغصان. من يثبت في وأنا فيه، فذاك ينتج ثمرا كثيرا. فإنكم بمعزل عني لا تقدرون أن تفعلوا شيئا.","15:6":"إن كان أحد لا يثبت في يطرح خارجا كالغصن فيجف؛ ثم تجمع الأغصان الجافة، وتطرح في النار فتحترق.","15:7":"ولكن، إن ثبتم في، وثبت كلامي فيكم، فاطلبوا ما تريدون يكن لكم.","15:8":"بهذا يتمجد أبي: أن تنتجوا ثمرا كثيرا فتكونون حقا تلاميذي.","15:9":"مثلما أحبني الآب، أحببتكم أنا، فاثبتوا في محبتي.","15:10":"إن عملتم بوصاياي، تثبتون في محبتي، كما عملت أنا بوصايا أبي وأثبت في محبته!","15:11":"قلت لكم هذا ليكون فيكم فرحي، ويكون فرحكم كاملا.","15:12":"وصيتي لكم هي هذه: أن يحب بعضكم بعضا كما أنا أحببتكم.","15:13":"ليس لأحد محبة أعظم من هذه: أن يبذل أحد حياته فدى أحبائه.","15:14":"وأنتم أحبائي إن عملتم بما أوصيكم به.","15:15":"لا أسميكم عبيدا بعد، لأن العبد لا يطلعه سيده على ما يفعله. ولكني قد سميتكم أحباء لأني أطلعتكم على كل ما سمعته من أبي.","15:16":"ليس أنتم اخترتموني، بل أنا اخترتكم وعينتكم لتنطلقوا وتنتجوا ثمرا ويدوم ثمركم، فيعطيكم الآب كل ما تطلبونه باسمي.","15:17":"فبهذا أوصيكم إذن: أن تحبوا بعضكم بعضا.","15:18":"إن أبغضكم العالم، فاعلموا أنه قد أبغضني من قبلكم.","15:19":"لو كنتم من أهل العالم، لكان العالم يحب أهله، ولكن لأنكم لستم من أهل العالم، بل إني اخترتكم من وسط العالم، لذلك يبغضكم العالم.","15:20":"اذكروا الكلمة التي قلتها لكم: ليس عبد أعظم من سيده. فإن كان أهل العالم قد اضطهدوني، فسوف يضطهدونكم؛ وإن كانوا قد عملوا بكلمتي، فسوف يعملون بكلمتكم.","15:21":"ولكنهم سيفعلون هذا كله بكم من أجل اسمي، لأنهم لا يعرفون الذي أرسلني.","15:22":"لو لم آت وأكلمهم، لما كانت لهم خطيئة؛ ولكن لا عذر لهم الآن في خطيئتهم.","15:23":"الذي يبغضني، يبغض أبي أيضا.","15:24":"ولو لم أعمل بينهم أعمالا لم يعملها أحد غيري، لما كانت لهم خطيئة. ولكنهم أبغضوني وأبغضوا أبي، مع أنهم رأوا تلك الأعمال.","15:25":"وقد صار ذلك لتتم الكلمة المكتوبة في شريعتهم: أبغضوني بلا سبب!","15:26":"وعندما يأتي المعين، الذي سأرسله لكم من عند الآب، روح الحق الذي ينبثق من الآب، فهو يشهد لي،","15:27":"وتشهدون لي أنتم أيضا، لأنكم معي من البداية.","16:1":"قلت لكم هذا لكي لا تتزعزعوا.","16:2":"ستطردون خارج المجامع، بل سيأتي وقت يظن فيه من يقتلكم أنه يؤدي خدمة لله.","16:3":"وهم يفعلون هذا بكم لأنهم لم يعرفوا أبي، ولا عرفوني.","16:4":"قلت لكم هذا حتى متى جاء وقت حدوثه تذكرون أنه سبق أن أخبرتكم به. ولم أقل لكم هذا منذ البداية لأني كنت معكم؛","16:5":"أما الآن فإني عائد إلى الذي أرسلني، ولا أحد منكم يسألني: أين تذهب؟","16:6":"عندما أخبرتكم بهذا ملأ الحزن قلوبكم.","16:7":"ولكني أقول لكم الحق: من الأفضل لكم أن أذهب، لأني إن كنت لا أذهب، لا يأتيكم المعين. ولكني إذا ذهبت أرسله إليكم.","16:8":"وعندما يجيء يبكت العالم على الخطيئة وعلى البر وعلى الدينونة:","16:9":"أما على الخطيئة، فلأنهم لا يؤمنون بي،","16:10":"وأما على البر، فلأني عائد إلى الآب فلا ترونني بعد؛","16:11":"وأما على الدينونة، فلأن سيد هذا العالم قد صدر عليه حكم الدينونة.","16:12":"مازال عندي أمور كثيرة أقولها لكم، ولكنكم الآن تعجزون عن احتمالها.","16:13":"ولكن، عندما يأتيكم روح الحق يرشدكم إلى الحق كله، لأنه لا يقول شيئا من عنده، بل يخبركم بما يسمعه، ويطلعكم على ما سوف يحدث.","16:14":"وهو سيمجدني لأن كل ما سيحدثكم به صادر عني.","16:15":"كل ما هو للآب، فهو لي. ولذلك قلت لكم إن ما سيحدثكم به صادر عني.","16:16":"بعد قليل لا ترونني، وبعد ذلك بقليل ترونني!»","16:17":"فتساءل بعض التلاميذ: «ترى، ما معنى قوله: بعد قليل لا ترونني، وبعد ذلك بقليل ترونني، وأيضا: لأني عائد إلى الآب؟»","16:18":"وقالوا: «ما هو هذا القليل الذي يتحدث عنه؟ لسنا نفهم ما يقوله!»","16:19":"وعلم يسوع أنهم يرغبون في أن يسألوه، فقال لهم: «تتساءلون عن معنى قولي: بعد قليل لا ترونني ثم بعد قليل ترونني أيضا.","16:20":"الحق الحق أقول لكم: إنكم ستبكون وتنوحون، أما العالم فيفرح. إنكم ستحزنون، ولكن حزنكم سيتحول إلى فرح.","16:21":"المرأة تحزن إذا حانت ساعتها لتلد. ولكنها حالما تلد طفلها، لا تعود تتذكر عناءها، لفرحها بأن إنسانا قد ولد في العالم.","16:22":"فكذلك أنتم، تحزنون الآن؛ ولكن عندما أعود للقائكم، تبتهج قلوبكم، ولا أحد يسلبكم فرحكم.","16:23":"وفي ذلك اليوم لا تسألونني عن شيء. الحق الحق أقول لكم: إن الآب سيعطيكم كل ما تطلبون منه باسمي.","16:24":"حتى الآن لم تطلبوا باسمي شيئا. اطلبوا تنالوا، فيكون فرحكم كاملا.","16:25":"ضربت لكم أمثالا في كلامي عن هذه الأمور، ولكن سيأتي وقت أحدثكم فيه عن الآب بكلام صريح، دون أمثال.","16:26":"في ذلك اليوم تطلبون من الآب باسمي. ولست أقول لكم إني أطلب إليه عنكم.","16:27":"فإن الآب نفسه يحبكم، لأنكم أحببتموني، وآمنتم بأني من عند الله خرجت.","16:28":"خرجت من عند الآب، وأتيت إلى العالم. وها أنا أترك العالم وأعود إلى الآب».","16:29":"فقال له تلاميذه: «ها أنت الآن تكلمنا كلاما صريحا بغير أمثال.","16:30":"فالآن نعرف أنك تعلم كل شيء، ولا تحتاج إلى أن يسألك أحد. لذلك نؤمن أنك جئت من عند الله».","16:31":"فرد يسوع: «أفالآن تؤمنون؟","16:32":"ستأتي ساعة وها قد حانت الآن فيها تتفرقون كل واحد إلى بيته، وتتركونني وحدي. ولكني لست وحدي، لأن الآب معي.","16:33":"أخبرتكم بهذا كله ليكون لكم في سلام. فإنكم في العالم ستقاسون الضيق. ولكن تشجعوا، فأنا قد انتصرت على العالم!»","17:1":"ولما أنهى يسوع هذا الحديث رفع عينيه نحو السماء، وقال: «أيها الآب، قد حانت الساعة! مجد ابنك، ليمجدك ابنك أيضا،","17:2":"فقد أوليته السلطة على جميع البشر، ليمنح جميع الذين قد وهبتهم له حياة أبدية.","17:3":"والحياة الأبدية هي أن يعرفوك أنت الإله الحق وحدك، والذي أرسلته: يسوع المسيح.","17:4":"أنا مجدتك على الأرض، وأنجزت العمل الذي كلفتني.","17:5":"فمجدني في حضرتك الآن، أيها الآب، بما كان لي من مجد عندك قبل تكوين العالم.","17:6":"أظهرت اسمك للناس الذين وهبتهم لي من العالم. كانوا لك، فوهبتهم لي. وقد عملوا بكلمتك،","17:7":"وعرفوا الآن أن كل ما وهبته لي فهو منك،","17:8":"لأني نقلت إليهم الوصايا التي أوصيتني بها، فقبلوها، وعرفوا حقا أني خرجت من عندك، وآمنوا أنك أنت أرسلتني.","17:9":"من أجل هؤلاء أصلي إليك. لست أصلي الآن من أجل العالم، بل من أجل الذين وهبتهم لي، لأنهم لك.","17:10":"وكل ما هو لي فهو لك، وكل ما هو لك فهو لي؛ وأنا قد تمجدت فيهم.","17:11":"هؤلاء باقون في العالم؛ أما أنا فلست باقيا فيه، لأني عائد إليك. أيها الآب القدوس احفظ في اسمك الذين وهبتهم لي، ليكونوا واحدا، كما نحن واحد.","17:12":"حين كنت معهم، كنت أحفظهم في اسمك. فالذين وهبتهم لي، رعيتهم، ولم يهلك منهم أحد إلا ابن الهلاك، ليتم الكتاب.","17:13":"أما الآن فإني عائد إليك، وأتكلم بهذا وأنا بعد في العالم، ليكون لهم فرحي كاملا فيهم.","17:14":"أبلغتهم كلمتك، فأبغضهم العالم لأنهم ليسوا من العالم.","17:15":"وأنا لا أطلب أن تأخذهم من العالم، بل أن تحفظهم من الشرير.","17:16":"فهم ليسوا من أهل العالم كما أني لست من العالم.","17:17":"قدسهم بالحق؛ إن كلمتك هي الحق.","17:18":"وكما أرسلتني أنت إلى العالم، أرسلتهم أنا أيضا إليه.","17:19":"ومن أجلهم أنا أقدس ذاتي، ليتقدسوا هم أيضا في الحق.","17:20":"ولست أصلي من أجل هؤلاء فقط، بل أيضا من أجل الذين سوف يؤمنون بي بسبب كلمة هؤلاء،","17:21":"ليكون الجميع واحدا؛ أيها الآب، كما أنك أنت في وأنا فيك، ليكونوا هم أيضا واحدا فينا، لكي يؤمن العالم أنك أنت أرسلتني.","17:22":"إني أعطيتهم المجد الذي أعطيتني، ليكونوا واحدا كما نحن واحد.","17:23":"أنا فيهم، وأنت في، ليكتملوا فيصيروا واحدا، حتى يعرف العالم أنك أرسلتني وأنك أحببتهم كما أحببتني.","17:24":"أيها الآب، أريد لهؤلاء الذين وهبتهم لي أن يكونوا معي حيث أكون أنا، فيشاهدوا مجدي الذي أعطيتني، لأنك أحببتني قبل إنشاء العالم.","17:25":"أيها الآب البار، إن العالم لم يعرفك، أما أنا فعرفتك، وهؤلاء عرفوا أنك أنت أرسلتني،","17:26":"وقد عرفتهم اسمك، وسأعرفهم أيضا، لتكون فيهم المحبة التي أحببتني بها، وأكون أنا فيهم».","18:1":"بعدما انتهى يسوع من صلاته هذه، خرج مع تلاميذه وعبروا وادي قدرون. وكان هنالك بستان، فدخله هو وتلاميذه.","18:2":"وكان يهوذا الذي خانه يعرف ذلك المكان لأن يسوع كان يجتمع فيه كثيرا مع تلاميذه.","18:3":"فذهب يهوذا إلى هناك آخذا معه فرقة الجنود وحرس الهيكل، الذين أرسلهم رؤساء الكهنة والفريسيون، وهم يحملون المشاعل والمصابيح والسلاح.","18:4":"وكان يسوع يعرف كل ما سيحدث له، فتقدم نحوهم وقال: «من تريدون؟»","18:5":"فأجابوه: «يسوع الناصري». فقال لهم: «أنا هو». وكان يهوذا الذي خانه واقفا معهم.","18:6":"فلما قال لهم: «أنا هو»، تراجعوا وسقطوا على الأرض!","18:7":"فعاد يسوع يسألهم: «من تريدون؟» أجابوه: «يسوع الناصري».","18:8":"فقال: «قلت لكم: أنا هو، فإن كنتم تريدونني أنا، فدعوا هؤلاء يذهبون».","18:9":"وذلك لتتم الكلمة التي قالها: «إن الذين وهبتهم لي لم يهلك منهم أحد!»","18:10":"وكان مع سمعان بطرس سيف فاستله وضرب به عبد رئيس الكهنة، فقطع أذنه اليمنى. وكان اسم العبد ملخس.","18:11":"فقال يسوع لبطرس: «أعد السيف إلى غمده! الكأس التي أعطاني الآب، ألا أشربها؟»","18:12":"فقبضت الفرقة والقائد وحرس الهيكل على يسوع وقيدوه.","18:13":"وساقوه أولا إلى حنان وهو حمو قيافا رئيس الكهنة في تلك السنة.","18:14":"وقيافا هو الذي أشار على اليهود بأنه من الأفضل أن يموت رجل واحد فدى الأمة.","18:15":"وتبع يسوع سمعان بطرس وتلميذ آخر كان رئيس الكهنة يعرفه. فدخل ذلك التلميذ مع يسوع إلى دار رئيس الكهنة.","18:16":"أما بطرس فوقف بالباب خارجا. فخرج التلميذ الآخر الذي كان رئيس الكهنة يعرفه، وكلم البوابة فأدخل بطرس.","18:17":"فسألت الخادمة البوابة بطرس: «ألست أنت أحد تلاميذ هذا الرجل؟» أجابها: «لا، لست منهم!»","18:18":"وكان الطقس باردا، وقد أوقد العبيد والحراس نارا ووقفوا يستدفئون حولها، فوقف بطرس يستدفيء معهم.","18:19":"وسأل رئيس الكهنة يسوع عن تلاميذه، وعن تعليمه.","18:20":"فأجابه يسوع: «علنا تكلمت إلى العالم، ودائما علمت في المجمع والهيكل حيث يجتمع اليهود كلهم، ولم أقل شيئا في السر.","18:21":"فلماذا تسألني أنا؟ اسأل الذين سمعوا ما تكلمت به إليهم، فهم يعرفون ما قلته!»","18:22":"فلما قال يسوع هذا لطمه أحد الحراس وقال له: «أهكذا تجيب رئيس الكهنة؟»","18:23":"أجابه يسوع: «إن كنت أسأت الكلام فاشهد على الإساءة، أما إذا كنت أحسنت، فلماذا تضربني؟»","18:24":"ثم أرسله حنان مقيدا إلى قيافا رئيس الكهنة.","18:25":"وكان بطرس لايزال واقفا هناك يستدفيء، فسأ لوه: «ألست أنت أيضا من تلاميذه؟» فأنكر وقال: «لست أنا».","18:26":"فقال واحد من عبيد رئيس الكهنة، وهو نسيب العبد الذي قطع بطرس أذنه: «أما رأيتك معه في البستان؟»","18:27":"فأنكر بطرس مرة أخرى. وفي الحال صاح الديك!","18:28":"ثم أخذوا يسوع من دار قيافا إلى قصر الحاكم الروماني، وكان ذلك في الصباح الباكر. ولم يدخل اليهود إلى القصر لئلا يتنجسوا فلا يتمكنوا من الأكل من خروف الفصح.","18:29":"فخرج بيلاطس إليهم وسألهم: «بماذا تتهمون هذا الرجل؟»","18:30":"أجابوه: «لو لم يكن مذنبا، لما سلمناه إليك!»","18:31":"فقال بيلاطس: «خذوه أنتم وحاكموه حسب شريعتكم». فأجابوه: «لا يحق لنا أن نقتل أحدا!»","18:32":"وقد حدث هذا لتتم الكلمة التي قالها يسوع إشارة إلى الميتة التي سيموتها.","18:33":"فدخل بيلاطس قصره واستدعى يسوع وسأله: «أأنت ملك اليهود؟»","18:34":"فرد يسوع: «أتقول لي هذا من عندك، أم قاله لك عني آخرون؟»","18:35":"فقال بيلاطس: «وهل أنا يهودي؟ إن أمتك ورؤساء الكهنة سلموك إلي. ماذا فعلت؟»","18:36":"أجاب يسوع: «ليست مملكتي من هذا العالم. ولو كانت مملكتي من هذا العالم، لكان حراسي يجاهدون لكي لا أسلم إلى اليهود. أما الآن فمملكتي ليست من هنا».","18:37":"فسأله بيلاطس: «فهل أنت ملك إذن؟» أجابه: «أنت قلت، إني ملك. ولهذا ولدت وجئت إلى العالم: لأشهد للحق، وكل من هو من الحق يصغي لصوتي».","18:38":"فقال له بيلاطس: «ما هو الحق!» ثم خرج إلى اليهود وقال: «إني لا أجد فيه ذنبا!","18:39":"وقد جرت العادة عندكم أن أطلق لكم أحد السجناء في عيد الفصح. فهل تريدون أن أطلق لكم ملك اليهود؟»","18:40":"فصرخوا جميعا قائلين: «لا تطلق هذا، بل باراباس». وكان باراباس لصا!","19:1":"عندئذ أمر بيلاطس بأن يؤخذ يسوع ويجلد.","19:2":"وجدل الجنود إكليلا من الشوك وضعوه على رأسه، وألبسوه رداء أرجوان.","19:3":"وأخذوا يتقدمون إليه ويقولون: «سلام، ياملك اليهود!»، ويلطمونه.","19:4":"وخرج بيلاطس مرة أخرى إلى الجمهور وقال لهم: «سأخرجه إليكم لتروا أني لا أجد فيه ذنبا!»","19:5":"فخرج يسوع وعليه إكليل الشوك ورداء الأرجوان. فقال لهم بيلاطس: «ها هو الإنسان!»","19:6":"فلما رآه رؤساء الكهنة والحرس صرخوا: «اصلبه! اصلبه!» فقال لهم بيلاطس: «بل خذوه أنتم واصلبوه، فإني لا أجد فيه ذنبا!»","19:7":"فأجابه اليهود: «لنا شريعة. وبحسب شريعتنا يتحتم عليه الموت، لأنه جعل نفسه ابن الله».","19:8":"فعندما سمع بيلاطس هذا الكلام، اشتد خوفه،","19:9":"ودخل إلى قصره وسأل يسوع: «من أين أنت؟» فلم يجبه يسوع بشيء.","19:10":"فقال له بيلاطس: «أما تكلمني؟ ألا تعلم أن لي سلطة أن أطلقك، وسلطة أن أصلبك؟»","19:11":"فأجابه يسوع «ما كان لك علي سلطة قط، لو لم تكن قد أعطيت لك من فوق. لذلك فالذي سلمني إليك له خطيئة أعظم...»","19:12":"من أجل ذلك سعى بيلاطس أن يطلقه، ولكن اليهود صرخوا: «إن أطلقت هذا، فلست محبا للقيصر. فإن كل من يجعل نفسه ملكا، يعادي القيصر».","19:13":"فلما سمع بيلاطس هذا الكلام، أمر بإخراج يسوع، وجلس على كرسي القضاء في مكان يسمى «البلاط»، وبالعبرية: «جباثا».","19:14":"وكان الوقت نحو السادسة في يوم الإعداد للفصح. وقال بيلاطس لليهود: «ها هو ملككم!»","19:15":"فصرخوا: «خذه! خذه ! اصلبه!» فسألهم بيلاطس: «أأصلب ملككم؟» فأجابه رؤساء الكهنة: «لا ملك لنا إلا القيصر».","19:16":"فسلمه بيلاطس إليهم ليصلب.","19:17":"فخرج وهو حامل صليبه إلى المكان المعروف بمكان الجمجمة، وبالعبرية: «جلجثة»،","19:18":"وهناك صلبوه وصلبوا معه رجلين، واحدا من كل جانب، ويسوع في الوسط.","19:19":"وعلق بيلاطس لافتة على الصليب مكتوبا عليها: «يسوع الناصري ملك اليهود».","19:20":"فقرأ اللافتة كثيرون من اليهود، لأن المكان الذي صلب يسوع فيه كان قريبا من المدينة. وكانت اللافتة مكتوبة بالعبرية واللاتينية واليونانية.","19:21":"فقال رؤساء كهنة اليهود لبيلاطس: «لا تكتب: ملك اليهود، بل إن هذا الإنسان قال: أنا ملك اليهود».","19:22":"فرد بيلاطس: «ما كتبت فقد كتبت!»","19:23":"ولما صلب الجنود يسوع أخذوا ثيابه وقسموها إلى أربعة أقسام، فأخذ كل جندي قسما. وأخذوا القميص أيضا، وكان منسوجا كله من قطعة واحدة، بغير خياطة.","19:24":"فقال الجنود بعضهم لبعض: «لا داعي لتمزيقه، بل لنقترع عليه فنرى من يكسبه!» وقد حدث ذلك ليتم ما جاء في الكتاب: «اقتسموا ثيا بي بينهم، وعلى قميصي اقترعوا». وهذا هو ما فعله الجنود.","19:25":"وهناك، عند صليب يسوع، وقفت مريم أمه، وأخت أمه مريم زوجة كلوبا؛ ومريم المجدلية.","19:26":"فلما رأى يسوع أمه، والتلميذ الذي كان يحبه واقفا بالقرب منها، قال لأمه: «أيتها المرأة، هذا ابنك!»","19:27":"ثم قال للتلميذ: «هذه أمك». ومنذ ذلك الحين أخذها التلميذ إلى بيته.","19:28":"بعد هذا رأى يسوع أن كل شيء قد اكتمل، فقال: «أنا عطشان»، ليتم ما جاء في الكتاب.","19:29":"وكان هناك وعاء مليء بالخل، فغمسوا في الخل إسفنجة وضعوها على زوفا، ورفعوها إلى فمه.","19:30":"فلما ذاق يسوع الخل، قال: «قد أكمل!» ثم نكس رأسه وأسلم الروح.","19:31":"ولما كان الإعداد يتم في ذلك اليوم، طلب اليهود من بيلاطس أن تكسر سيقان المصلوبين، فتؤخذ جثثهم لئلا تبقى معلقة على الصليب يوم السبت، ولا سيما لأن ذلك السبت كان يوما عظيما.","19:32":"فجاء الجنود وكسروا ساقي كلا الرجلين المصلوبين مع يسوع.","19:33":"أما يسوع، فلما وصلوا إليه وجدوه قد مات، فلم يكسروا ساقيه.","19:34":"وإنما طعنه أحد الجنود بحربة في جنبه، فخرج في الحال دم وماء.","19:35":"والذي رأى هذا هو يشهد، وشهادته حق وهو يعلم تماما أنه يقول الحق، لكي تؤمنوا أنتم أيضا.","19:36":"وقد حدث هذا ليتم ما جاء في الكتاب: «لن يكسر منه عظم!»","19:37":"وقد جاء أيضا في موضع آخر من الكتاب: «سينظرون إلى ذاك الذي طعنوه».","19:38":"بعد ذلك طلب يوسف الذي من الرامة إلى بيلاطس أن يأذن له بأخذ جثمان يسوع، وكان يوسف هذا تلميذا ليسوع ولكن في السر، لأنه كان خائفا من اليهود، فأذن له بيلاطس. فجاء يوسف وأخذ جثمان يسوع.","19:39":"وجاء أيضا نيقوديموس الذي كان قد أتى من قبل إلى يسوع ليلا، وأحضر معه حوالي ثلاثين لترا من طيب المر المخلوط بالعود.","19:40":"فأخذا جثمان يسوع ولفاه بأكفان مع الطيب، كما كانت عادة اليهود في الدفن.","19:41":"وكان في المكان الذي صلب يسوع فيه بستان، وفي البستان قبر جديد، لم يسبق أن دفن فيه أحد.","19:42":"فدفنا يسوع في ذلك القبر لأنه كان قريبا، ولأن ذلك اليوم كان يوم الإعداد عند اليهود.","20:1":"وفي اليوم الأول من الأسبوع، بكرت مريم المجدلية إلى قبر يسوع، وكان الظلام لايزال مخيما، فرأت الحجر قد رفع عن باب القبر.","20:2":"فأسر عت وجاءت إلى سمعان بطرس والتلميذ الآخر الذي كان يسوع يحبه وقالت لهما: «أخذوا الرب من القبر، ولا ندري أين وضعوه!»","20:3":"فخرج بطرس والتلميذ الآخر وتوجها إلى القبر.","20:4":"وكانا يركضان معا. ولكن التلميذ الآخر سبق بطرس فوصل إلى القبر قبله،","20:5":"وانحنى فرأى الأكفان ملقاة على الأرض، ولكنه لم يدخل.","20:6":"ثم وصل سمعان بطرس في إثره إلى القبر ودخله، فرأى أيضا الأكفان ملقاة على الأرض.","20:7":"والمنديل الذي كان على رأس يسوع وجده ملفوفا وحده في مكان منفصل عن الأكفان.","20:8":"عند ذلك دخل التلميذ الآخر، الذي كان قد وصل إلى القبر أولا، ورأى فآمن.","20:9":"فإن التلاميذ لم يكونوا حتى ذلك الوقت قد فهموا أن الكتاب تنبأ بأنه لابد أن يقوم من بين الأموات.","20:10":"ثم رجع التلميذان إلى بيتهما.","20:11":"أما مريم فظلت واقفة في الخارج تبكي عند القبر. وفيما هي تبكي، انحنت إلى القبر.","20:12":"فرأت ملاكين بثياب بيض، جالسين حيث كان جثمان يسوع موضوعا، واحدا عند الرأس والآخر عند القدمين.","20:13":"فسألاها: «ياامرأة، لماذا تبكين؟» أجابت: «أخذوا سيدي، ولا أدري أين وضعوه».","20:14":"قالت هذا والتفتت إلى الوراء، فرأت يسوع واقفا، ولكنها لم تعلم أنه يسوع.","20:15":"فسألها: «ياامرأة، لماذا تبكين؟ عمن تبحثين؟» فظنت أنه البستاني، فقالت له: «ياسيد، إن كنت أنت قد أخذته فقل لي أين وضعته لآخذه».","20:16":"فناداها يسوع: «يامريم!» فالتفتت وهتفت بالعبرية: «ربوني»، أي: يامعلم.","20:17":"فقال لها: «لا تمسكي بي! فإني لم أصعد بعد إلى الآب، بل اذهبي إلى إخوتي وقولي لهم: إني سأصعد إلى أبي وأبيكم، وإلهي وإلهكم!»","20:18":"فر جعت مريم المجدلية وبشرت التلاميذ قائلة: «إني رأيت الرب!» وأخبرتهم بما قال لها.","20:19":"ولما حل مساء ذلك اليوم، وهو اليوم الأول من الأسبوع، كان التلاميذ مجتمعين في بيت أغلقوا أبوابه خوفا من اليهود، وإذا يسوع يحضر وسطهم قائلا: «سلام لكم!»","20:20":"وإذ قال هذا، أراهم يديه وجنبه، ففرح التلاميذ إذ أبصروا الرب.","20:21":"فقال لهم يسوع: «سلام لكم. كما أن الآب أرسلني، أرسلكم أنا».","20:22":"قال هذا ونفخ فيهم وقال لهم: «اقبلوا الروح القدس.","20:23":"من غفرتم خطاياهم غفرت لهم، ومن أمسكتم خطاياهم، أمسكت!»","20:24":"ولكن توما، أحد التلاميذ الاثني عشر، وهو المعروف بالتوأم، لم يكن مع التلاميذ، حين حضر يسوع.","20:25":"فقال له التلاميذ الآخرون: «إننا رأينا الرب!» فأجاب: «إن كنت لا أرى أثر المسامير في يديه، وأضع إصبعي في مكان المسامير، وأضع يدي في جنبه، فلا أومن!»","20:26":"وبعد ثمانية أيام، إذ كان تلاميذه مجتمعين ثانية داخل البيت وتوما معهم، حضر يسوع والأبواب مغلقة، ووقف في الوسط وقال: «سلام لكم!»","20:27":"ثم قال لتوما: «هات إصبعك إلى هنا، وانظر يدي، وهات يدك وضعها في جنبي. ولا تكن غير مؤمن بل كن مؤمنا!»","20:28":"فهتف توما: «ربي وإلهي».","20:29":"فقال له يسوع: «ألأنك رأيتني آمنت؟ طوبى للذين يؤمنون دون أن يروا»","20:30":"وقد أجرى يسوع أمام تلاميذه آيات أخرى كثيرة لم تدون في الكتاب.","20:31":"وأما هذه الآيات فقد دونت لتؤمنوا بأن يسوع هو المسيح ابن الله، ولكي تكون لكم حياة باسمه إذ تؤمنون.","21:1":"بعد ذلك أظهر يسوع نفسه للتلاميذ مرة أخرى عند شاطيء بحيرة طبرية. وقد أظهر نفسه هكذا:","21:2":"اجتمع سمعان بطرس وتوما، المعروف بالتوأم، ونثنائيل، وهو من قانا بمنطقة الجليل، وابنا زبدي، وتلميذان آخران.","21:3":"فقال لهم سمعان بطرس: «أنا ذاهب للصيد!» فقالوا: «ونحن أيضا نذهب معك». فذهبوا وركبوا القارب، ولكنهم لم يصيدوا شيئا في تلك الليلة.","21:4":"ولما طلع الفجر، وقف يسوع على الشاطيء، ولكن التلاميذ لم يعرفوا أنه يسوع.","21:5":"فسألهم يسوع: «يافتيان، أما عندكم سمك؟» أجابوه: «لا!»","21:6":"فقال لهم: «ألقوا الشبكة إلى يمين القارب، تجدوا!» فألقوها، ولم يعودوا يقدرون أن يجذبوها لكثرة ما فيها من السمك!","21:7":"فقال التلميذ الذي كان يسوع يحبه، لبطرس: «إنه الرب!» وكان بطرس عريانا، فما إن سمع أن ذلك هو الرب، حتى تستر بردائه، وألقى نفسه في الماء سابحا.","21:8":"وجاء باقي التلاميذ بالقارب وهم يجرون شبكة السمك، إذ كانوا غير بعيدين عن الشاطيء إلا نحو مئتي ذراع.","21:9":"فلما نزلوا إلى الشاطيء، رأوا هناك جمرا وسمكا موضوعا عليه، وخبزا.","21:10":"فقال لهم يسوع: «هاتوا من السمك الذي صدتموه الآن!»","21:11":"فصعد سمعان بطرس إلى القارب وجذب الشبكة إلى البر، فإذا فيها مئة وثلاث وخمسون سمكة من السمك الكبير، ومع هذه الكثرة لم تتمزق الشبكة.","21:12":"وقال يسوع للتلاميذ: «تعالوا كلوا». ولم يجرؤ أحد من التلاميذ أن يسأله: من أنت؟ لأنهم عرفوا أنه الرب.","21:13":"ثم تقدم يسوع وأخذ الخبز وناولهم، وكذلك السمك.","21:14":"هذه هي المرة الثالثة التي أظهر فيها يسوع نفسه لتلاميذه بعدما قام من الأموات.","21:15":"وبعدما أكلوا سأل يسوع سمعان بطرس: «ياسمعان بن يونا، أتحبني أكثر مما يحبني هؤلاء؟» فأجابه «نعم يارب، أنت تعلم أني أحبك!» فقال له: «أطعم حملاني!»","21:16":"ثم سأله ثانية: «ياسمعان بن يونا، أتحبني؟» فأجابه: «نعم يارب. أنت تعلم أني أحبك!» قال له: «ارع خرافي»","21:17":"فسأله مرة ثالثة: «ياسمعان بن يونا، أتحبني؟» فحزن بطرس لأن يسوع قال له في المرة الثالثة: «أتحبني». وقال له: «يارب، أنت تعلم كل شيء. أنت تعلم أني أحبك!» فقال له يسوع: «أطعم خرافي!","21:18":"الحق الحق أقول لك: إنك لما كنت شابا كنت تربط حزامك على وسطك وتذهب حيث تريد. ولكن عندما تصير شيخا فإنك تمد يديك، وآخر يربط حزامك ويذهب بك حيث لا تريد!»","21:19":"وقد قال يسوع هذا إشارة إلى الميتة التي سوف يموتها بطرس فيمجد بها الله . ولما قال له ذلك، قال له: «اتبعني».","21:20":"ونظر بطرس وراءه، فرأى التلميذ الذي كان يسوع يحبه يتبعهما، وهو التلميذ الذي مال إلى صدر يسوع في أثناء العشاء وقال له: «ياسيد، من هو الذي سيخونك؟»","21:21":"فلما رآه بطرس سأل يسوع: «يارب وهذا، ماذا يكون له؟»","21:22":"أجابه يسوع: «لو شئت أن يبقى حتى أرجع، فما شأنك؟ اتبعني أنت!»","21:23":"فشاع خبر بين الإخوة أن ذلك التلميذ لن يموت. ولكن يسوع لم يقل لبطرس: «إنه لن يموت!» بل قال: «لو شئت أن يبقى حتى أرجع، فما شأنك؟»","21:24":"هذا التلميذ هو الذي يشهد بهذه الأمور، وقد دونها هنا. ونحن نعلم أن شهادته حق.","21:25":"وهناك أمور أخرى كثيرة عملها يسوع، أظن أنها لو دونت واحدة فواحدة، لما كان العالم كله يسع ما دون من كتب!"},"Act":{"1:1":"رويت لك في كتابي الأول، ياثاوفيلس، جميع أعمال يسوع وتعاليمه، منذ بدء رسالته","1:2":"حتى اليوم الذي ارتفع فيه إلى السماء، بعدما قدم وصاياه، بالروح القدس، إلى الرسل الذين اختارهم.","1:3":"وخلال فترة أربعين يوما بعد آلامه، ظهر لهم مرات عديدة، وأثبت لهم أنه حي ببراهين كثيرة قاطعة، وحدثهم عن ملكوت الله.","1:4":"وبينما كان مجتمعا معهم، قال: «لا تتركوا أورشليم، بل ابقوا فيها منتظرين إتمام وعد الآب، الذي سبق أن حدثتكم عنه.","1:5":"فإن يوحنا عمد الناس بالماء؛ أما أنتم فستتعمدون بعد أيام قليلة بالروح القدس!»","1:6":"وقد سأله المجتمعون: «يار ب، أفي هذا الوقت تعيد الملك إلى إسرائيل؟»","1:7":"فأجابهم: «ليس لكم أن تعرفوا المواعيد والأوقات التي حددها الآب بسلطته.","1:8":"ولكن حينما يحل الروح القدس عليكم تنالون القوة، وتكونون لي شهودا في أورشليم واليهودية كلها، وفي السامرة، وإلى أقاصي الأرض».","1:9":"قال هذا وارتفع إلى السماء بمشهد منهم. ثم حجبته سحابة عن أنظارهم.","1:10":"وبينما هم يحدقون إلى السماء وهو ينطلق إليها، إذا رجلان قد ظهرا لهم بثياب بيض،","1:11":"وقالا لهم: «أيها الجليليون، لماذا تقفون ناظرين إلى السماء؟ إن يسوع، هذا الذي ارتفع عنكم إلى السماء، سيعود منها مثلما رأيتموه منطلقا إليها!»","1:12":"ثم رجع الرسل إلى أورشليم من الجبل المعروف بجبل الزيتون، وهو بالقرب من أورشليم على مسافة يجوز قطعها يوم السبت.","1:13":"ولما وصلوا صعدوا إلى غرفة في الطبقة العليا كانوا يقيمون فيها، وهم: بطرس ويوحنا، ويعقوب وأندراوس، وفيلبس وتوما، وبرثلماوس ومتى، ويعقوب بن حلفى وسمعان الغيور، ويهوذا أخو يعقوب.","1:14":"وكانوا جميعا يداومون على الصلاة بقلب واحد، ومعهم بعض النساء، ومريم أم يسوع، وإخوته.","1:15":"وكان قد اجتمع ذات يوم نحو مئة وعشرين من الإخوة فوقف بطرس بينهم وخاطبهم قائلا:","1:16":"«أيها الإخوة، كان لابد من أن تتم النبوءة التي قالها الروح القدس بلسان النبي داود، عن يهوذا الذي انقلب دليلا للذين قبضوا على يسوع.","1:17":"وكان يهوذا يعتبر واحدا منا، وقد شاركنا في خدمتنا.","1:18":"ثم إنه اشترى حقلا بالمال الذي تقاضاه ثمنا للخيانة، وفيه وقع على وجهه، فانشق من وسطه واندلقت أمعاؤه كلها.","1:19":"وعلم أهل أورشليم جميعا بهذه الحادثة، فأطلقوا على حقله اسم ¢حقل دمخ¢ بلغتهم، أي حقل الدم.","1:20":"فتمت النبوءة الواردة في كتاب المزامير: لتصر داره خرابا، ولا يسكنها ساكن. وأيضا: ليستلم وظيفته آخر!","1:21":"فعلينا إذن أن نختار واحدا من الرجال الذين رافقونا طوال المدة التي قضاها الرب يسوع معنا،","1:22":"منذ أن عمده يوحنا إلى يوم ارتفاعه عنا إلى السماء، ليكون معنا شاهدا بقيامة يسوع».","1:23":"فرشح الحاضرون رجلين هما: يوسف الذي يدعى بارسابا ويلقب بيستس، ومتياس.","1:24":"ثم صلوا قائلين: «أيها الرب العارف قلوب الناس جميعا، بين لنا أي هذين الرجلين تختار","1:25":"ليشاركنا في الخدمة والرسالة بدلا من يهوذا الذي ذهب إلى المكان الذي يستحقه».","1:26":"ثم ألقوا القرعة، فوقعت على متياس، فضموه إلى الرسل الأحد عشر .","2:1":"ولما جاء اليوم الخمسون، كان الإخوة مجتمعين معا في مكان واحد،","2:2":"وفجأة حدث صوت من السماء كأنه دوي ريح عاصفة، فملأ البيت الذي كانوا جالسين فيه.","2:3":"ثم ظهرت لهم ألسنة كأنها من نار، وقد توزعت وحلت على كل واحد منهم،","2:4":"فامتلأوا جميعا من الروح القدس، وأخذوا يتكلمون بلغات أخرى، مثلما منحهم الروح أن ينطقوا.","2:5":"وكانت أورشليم في ذلك الوقت مزدحمة باليهود الأتقياء الذين جاءوا إليها من أمم العالم كلها.","2:6":"فلما دوى الصوت، توافدت إليهم الجموع، وقد أخذتهم الحيرة لأن كل واحد كان يسمعهم يتكلمون بلغته.","2:7":"واستولت الدهشة عليهم. فأخذوا يتساءلون: «أليس هؤلاء المتكلمون جميعا من أهل الجليل؟","2:8":"فكيف يسمع كل واحد منا لغة البلد الذي ولد فيه؟","2:9":"فبعضنا فرتيون، وماديون، وعيلاميون. وبعضنا من سكان ما بين النهرين واليهودية، وكبدوكية، وبنتس، وأسيا،","2:10":"وفريجية، وبمفيلية، ومصر، ونواحي ليبيا المواجهة للقيروان. وبيننا كثيرون من الرومانيين الزائرين،","2:11":"يهودا ومتهودين، وبعض الكريتيين والعرب. وها نحن نسمعهم يكلموننا بلغاتنا عن أعمال الله العظيمة».","2:12":"وأخذ الجميع يسألون بعضهم بعضا في دهشة وحيرة: «ما معنى هذا كله؟»","2:13":"أما بعضهم فقالوا ساخرين: «ما هم إلا سكارى!»","2:14":"فوقف بطرس مع الرسل الأحد عشر، وخاطب الحاضرين بصوت عال، وقال:","2:15":"ليس هؤلاء سكارى كما تتوهمون، فالناس لا يسكرون في الساعة التاسعة صباحا.","2:16":"ولكن هذا ما قيل بلسان النبي يوئيل:","2:17":"يقول الله : في الأيام الأخيرة سأسكب روحي على جميع البشر، فيتنبأ بنوكم وبناتكم، ويرى شبابكم رؤى، ويحلم شيوخكم أحلاما.","2:18":"في تلك الأيام أفيض من روحي على عبيدي كلهم، رجالا ونساء، فيتنبأون.","2:19":"سأجري عجائب فوق في السماء وعلامات تحت على الأرض، حيث يكون دم ونار ودخان كثيف!","2:20":"وقبل أن يأتي يوم الرب، ذلك اليوم العظيم الشهير، ستظلم الشمس، ويتحول القمر إلى لون الدم.","2:21":"ولكن كل من يدعو باسم الرب يخلص!","2:22":"فيا بني إسرائيل، اسمعوا هذا الكلام: إن يسوع الناصري رجل أيده الله بمعجزات وعجائب وعلامات أجراها على يده بينكم، كما تعلمون.","2:23":"ومع ذلك فقد سمح الله ، وفقا لمشيئته المحتومة وعلمه السابق، أن تقبضوا عليه وتصلبوه وتقتلوه بأيدي الأثمة.","2:24":"ولكن الله أقامه من بين الأموات ناقضا أوجاع الموت، فما كان يمكن للموت أن يبقيه في قبضته!","2:25":"فإن داود يقول فيه: كنت أرى الرب أمامي دائما فإنه عن يميني لئلا أتزعزع.","2:26":"لذلك فرح قلبي وتهلل لساني. حتى إن جسدي سيرقد على رجاء.","2:27":"لأنك لن تترك نفسي في هوة الأموات، ولن تدع وحيدك القدوس يرى فسادا،","2:28":"هديتني سبل الحياة، وستملأني سرورا برؤية وجهك!","2:29":"أيها الإخوة، دعوني أقول لكم صراحة إن أبانا داود مات ودفن، وقبره مازال عندنا حتى اليوم.","2:30":"لأن داود كان نبيا، وعارفا أن الله أقسم له يمينا بأن يجيء المسيح من نسله ويجلس على عرشه،","2:31":"فقد تكلم عن قيامة المسيح كما رآها مسبقا، فقال إن نفسه لم تترك في هوة الأموات، ولم ينل من جسده الفساد.","2:32":"فيسوع هذا أقامه الله من الموت، ونحن جميعا شهود لذلك.","2:33":"وإذ رفع إلى يمين الله، وأخذ من الآب الروح القدس الموعود به، أفاضه علينا. وما ترونه الآن وتسمعونه هو نتيجة لذلك.","2:34":"فإن داود لم يرتفع بجسده إلى السماء. ثم إنه هو نفسه يقول: قال الرب لربي: اجلس عن يميني","2:35":"حتى أجعل أعداءك موطئا لقدميك.","2:36":"فليعلم يقينا بنو إسر ائيل جميعا، أن الله قد جعل يسوع، هذا الذي صلبتموه أنتم، ربا ومسيحا!»","2:37":"فلما سمع الحاضرون هذا الكلام، وخزتهم قلوبهم، فسألوا بطرس وباقي الرسل: «ماذا نعمل أيها الإخوة؟»","2:38":"أجابهم بطرس: «توبوا، وليتعمد كل واحد منكم باسم يسوع المسيح، فيغفر الله خطاياكم وتنالوا هبة الروح القدس،","2:39":"لأن الوعد هو لكم ولأولادكم وللبعيدين جميعا، يناله كل من يدعوه الرب إلهنا!»","2:40":"ثم شهد بطرس للحاضرين ووعظهم بكلام كثير آخر، قائلا: «اخلصوا من هذا الجيل المنحرف!»","2:41":"فالذين قبلوا كلامه منهم تعمدوا. وانضم في ذلك اليوم نحو ثلاثة آلاف نفس.","2:42":"وكان الجميع يداومون على تلقي تعليم الرسل، وعلى حياة الشركة، وكسر الخبز، والصلوات.","2:43":"ولما أجريت عجائب وعلامات كثيرة على أيدي الرسل، استولت الرهبة على كل نفس.","2:44":"وكان المؤمنون كلهم متحدين معا، فكانوا يتشاركون في كل ما يملكون،","2:45":"ويبيعون أملاكهم ومقتنياتهم ويتقاسمون الثمن على قدر احتياج كل منهم،","2:46":"ويداومون على الحضور إلى الهيكل يوميا بقلب واحد، ويكسرون الخبز في البيوت، ويتناولون الطعام معا بابتهاج وبساطة قلب،","2:47":"مسبحين الله ، وكانوا يلاقون استحسانا لدى الشعب كله. وكان الرب، كل يوم، يضم إلى الكنيسة الذين يخلصون.","3:1":"وذات يوم ذهب بطرس ويوحنا إلى الهيكل لصلاة الساعة الثالثة بعد الظهر.","3:2":"وعند باب الهيكل الذي يسمى الباب الجميل، كان يجلس رجل كسيح منذ ولادته، يحملونه كل يوم ويضعونه هناك ليطلب صدقة من الذين يدخلون الهيكل.","3:3":"فلما رأى بطرس ويوحنا داخلين، طلب منهما صدقة،","3:4":"فنظرا إليه مليا، وقال له بطرس: «انظر إلينا!»","3:5":"فتعلقت عيناه بهما، منتظرا أن يتصدقا عليه بشيء.","3:6":"فقال بطرس: «لا فضة عندي ولا ذهب، ولكني أعطيك ما عندي: باسم يسوع المسيح الناصري قم وامش!»","3:7":"وأمسكه بيده اليمنى وأقامه، فدبت القوة حالا في رجليه وكعبيه،","3:8":"فوقف قافزا وبدأ يمشي، ودخل معهما إلى الهيكل وهو يمشي ويقفز فرحا ويسبح الله.","3:9":"ورآه جميع الحاضرين ماشيا يسبح الله ،","3:10":"وعرفوا أنه المستعطي الكسيح الذي تعود أن يقعد أمام الباب الجميل، فأخذتهم الدهشة والحيرة مما حدث له!","3:11":"وبينما كان في قاعة الهيكل المعروفة بقاعة سليمان ملازما بطرس ويوحنا، أسرع كثيرون من الشعب واجتمعوا حولهم مدهوشين،","3:12":"فقال لهم بطرس إذ رأى ذلك: «يابني إسرائيل، لماذا تتعجبون مما حدث، ولماذا تحدقون إلينا كأننا بقدرتنا أو بتقوانا جعلنا هذا الرجل يمشي؟","3:13":"إن إله إبراهيم وإسحاق ويعقوب، إله آبائنا، قد مجد فتاه يسوع، الذي أسلمتموه أنتم للموت وأنكرتموه أمام بيلاطس، في حين كان يريد أن يطلقه.","3:14":"أنتم أنكرتم القدوس البار وطلبتم العفو عن رجل قاتل،","3:15":"وقتلتم واهب الحياة. ولكن الله أقامه من بين الأموات ونحن شهود لذلك.","3:16":"وبفضل الإيمان باسمه، أعاد اسمه القوة إلى هذا الرجل الذي ترونه وتعرفونه. فالإيمان بيسوع هو الذي أعطاه هذه الصحة الكاملة بمشهد منكم جميعا.","3:17":"إني أعلم أيها الإخوة أنكم ورؤساءكم عاملتم المسيح بجهل،","3:18":"ولكن الله أتم بذلك ما كان قد أوحى به إلى جميع أنبيائه من أن المسيح سيلاقي الآلام.","3:19":"فتوبوا وارجعوا ليمحو الله خطاياكم،","3:20":"وتأتيكم أيام الفرج من قبل الرب، إذ يرسل إليكم يسوع المسيح ثانية، الذي سبق أن عينه لكم،","3:21":"إذ لابد أن يبقى المسيح في السماء حتى يأتي الزمن الذي يتم فيه الإصلاح الشامل لكل شيء كما أوحى الله إلى أنبيائه الأتقياء منذ القدم.","3:22":"وقد قال موسى: سيبعث الله فيكم من بين إخوتكم نبيا مثلي فاسمعوا له في كل ما يكلمكم به.","3:23":"أما من لا يسمع له فيباد من وسط الشعب.","3:24":"وكذلك تنبأ بهذه الأزمنة جميع الأنبياء، من صموئيل إلى الذين جاءوا بعده.","3:25":"وأنتم أحفاد هؤلاء الأنبياء، وأبناء العهد الذي أبرمه الله لآبائنا عندما قال لإبراهيم: بنسلك تنال البركة شعوب الأرض كلها.","3:26":"فمن أجلكم أولا أقام الله فتاه يسوع وأرسله ليبارككم برد كل واحد منكم عن شروره».","4:1":"وبينما كان بطرس ويوحنا يخاطبان الحاضرين، أقبل إليهما بعض الكهنة، وقائد حرس الهيكل والصدوقيين،","4:2":"متضايقين لأنهما كانا يعلمان الناس ويعلنان أن قيامة الأموات حقيقة تؤكدها قيامة يسوع،","4:3":"فقبضوا عليهما وألقوهما في السجن إلى اليوم التالي، لأن المساء كان قد حل.","4:4":"وكان كثيرون ممن سمعوا الكلمة قد آمنوا فصار عدد المؤمنين من الرجال نحو خمسة آلاف.","4:5":"وفي صباح اليوم التالي اجتمع في أورشليم رؤساء اليهود والشيوخ والكتبة،","4:6":"ومعهم حنان رئيس الكهنة، وقيافا، ويوحنا، والإسكندر، وجميع المنتمين إلى عشيرة رؤساء الكهنة.","4:7":"واستدعوا بطرس ويوحنا وسألوهما: «بأية قوة، وباسم من فعلتما هذا؟»","4:8":"فامتلأ بطرس من الروح القدس وأجابهم: «يارؤساء الشعب وياشيوخه،","4:9":"إن كنتم تستجوبوننا اليوم بسبب الإحسان إلى إنسان مريض لتعرفوا كيف شفي،","4:10":"فاعلموا جميعا، وليعرف شعب إسرائيل كله، أنه باسم يسوع المسيح الناصري الذي صلبتموه أنتم، والذي أقامه الله من بين الأموات، باسمه يقف هذا الكسيح أمامكم في تمام الصحة!","4:11":"يسوع هذا هو الحجر الذي رفضتموه أيها البناة، وهو نفسه صار حجر الزاوية الأساسي،","4:12":"وليس بأحد غيره الخلاص، إذ ليس تحت السماء اسم آخر قدمه الله للبشر به يجب أن نخلص!»","4:13":"فتعجب المجتمعون من جرأة بطرس ويوحنا، لما عرفوا أنهما غير متعلمين وأنهما من عامة الشعب، فأدركوا أنهما كانا مع يسوع.","4:14":"ولكن إذ رأوا الكسيح الذي شفي واقفا معهما، لم يجدوا شيئا يعارضون به!","4:15":"فأمروهما بالخروج من المجلس، ليتشاوروا فيما بينهم.","4:16":"وقالوا: «ماذا نعمل بهذين الرجلين؟ فمن الواضح أمام أهل أورشليم جميعا أن معجزة عظيمة قد جرت على أيديهما، ولا نستطيع أن ننكر!","4:17":"ولكن لئلا يزداد هذا الأمر انتشارا بين الشعب، فلنهددهما ألا يذكرا هذا الاسم لأحد من الناس بعد الآن».","4:18":"ثم أحضروهما وأمروهما ألا ينطقا باسم يسوع ولا يعلما الناس به.","4:19":"ولكن بطرس ويوحنا قالا: «احكموا أنتم: أمن الحق أمام الله أن نطيع أمركم لا أمر الله؟","4:20":"لا نستطيع أن نكف عن التحدث بما رأينا وسمعنا».","4:21":"فشدد المجلس إنذاره لهما، دون أن يجد طريقة لمعاقبتهما، وأمر بإطلاقهما خوفا من ثورة الشعب، فقد كان الجميع يمجدون الله على تلك المعجزة،","4:22":"لأن الرجل الذي جرت فيه علامة الشفاء هذه قد جاوز الأربعين عاما!","4:23":"وما إن أطلق بطرس ويوحنا حتى رجعا إلى رفاقهما، وأخبراهم بكل ما قاله لهما رؤساء الكهنة والشيوخ،","4:24":"فتوجهوا بقلب واحد إلى الله بالدعاء، قائلين: «يارب، ياخالق السماء والأرض والبحر وكل ما فيها،","4:25":"يامن قلت بالروح القدس على لسان عبدك داود: لماذا ضجت الأمم؟ ولماذا تآمرت الشعوب باطلا؟","4:26":"اجتمع ملوك الأرض ورؤساؤها، وتحالفوا ليقاوموا الرب ومسيحه!","4:27":"وقد تحققت هذه الكلمات فعلا، إذ تحالف هيرودس، وبيلاطس البنطي، والوثنيون وأسباط إسرائيل، لمقاومة فتاك القدوس يسوع، الذي جعلته مسيحا،","4:28":"وعملوا به كل ما سبق أن رسمت يدك وقضت مشيئتك أن يكون.","4:29":"والآن انظر، يارب، إلى تهديدهم، وهبنا نحن عبيدك أن نعلن كلامك بكل جرأة،","4:30":"ومد يدك للشفاء، كي تجرى معجزات وعجائب باسم فتاك القدوس يسوع».","4:31":"وفيما هم يصلون ارتج المكان الذي كانوا مجتمعين فيه، وامتلأوا جميعا بالروح القدس، فأخذوا يعلنون كلمة الله بكل جرأة!","4:32":"وكانت جماعة المؤمنين قلبا واحدا ونفسا واحدة، ولم يكن أحد يقول إن شيئا مما عنده هو له وحده، بل كان كل شيء عندهم مشتركا.","4:33":"وكان الرسل يؤدون الشهادة بقيامة الرب يسوع وقوة عظيمة تصحبها، ونعمة عظيمة تحل على جميعهم.","4:34":"فلم يكن فيهم محتاج، لأن جميع من كان لهم حقول أو بيوت كانوا يبيعونها ويأتون بثمنها،","4:35":"فيضعونه عند أقدام الرسل، وهم يوزعونه على كل محتاج بقدر حاجته.","4:36":"ومن هؤلاء يوسف، الذي دعاه الرسل برنابا أي ابن التشجيع، وهو من سبط لاوي، ويحمل الجنسية القبرصية.","4:37":"فإنه كان يملك حقلا، فباعه وجاء بثمنه ووضعه عند أقدام الرسل!","5:1":"ولكن رجلا اسمه حنانيا، اتفق مع زوجته سفيرة فباع حقلا كان يملكه،","5:2":"واحتفظ لنفسه بجزء من الثمن بعلم من زوجته، وجاء بما تبقى ووضعه عند أقدام الرسل.","5:3":"فقال له بطرس: «ياحنانيا، لماذا سمحت للشيطان أن يملأ قلبك، فكذبت على الروح القدس، واحتفظت لنفسك بجزء من ثمن الحقل؟","5:4":"أما كان بقي لك لو لم تبعه؟ وبعد بيعه أما كان لك حق الاحتفاظ بثمنه؟ لماذا قصدت في قلبك أن تغش؟ إنك لم تكذب على الناس، بل على الله!»","5:5":"فما إن سمع حنانيا هذا الكلام حتى سقط أرضا ومات! فاستولت الرهبة الشديدة على جميع الذين عرفوا ذلك.","5:6":"وقام بعض الشبان وكفنوا حنانيا، وحملوه إلى حيث دفنوه.","5:7":"وبعد نحو ثلاث ساعات حضرت زوجة حنانيا وهي لا تدري بما حدث،","5:8":"فسألها بطرس: «قولي لي: أبهذا المبلغ بعتما الحقل؟» فأجابت: «نعم، بهذا المبلغ».","5:9":"فقال لها بطرس: «لماذا اتفقت مع زوجك على امتحان روح الرب؟ ها قد وصل الشبان الذين دفنوا زوجك إلى الباب، وسيحملونك أيضا!»","5:10":"فوقعت حالا عند قدمي بطرس وماتت! ولما دخل الشبان وجدوها ميتة، فحملوا جثتها ودفنوها إلى جوار زوجها.","5:11":"فاستولت الرهبة الشديدة على الكنيسة كلها، وعلى كل من سمعوا ذلك الخبر.","5:12":"وجرت على أيدي الرسل معجزات وعجائب كثيرة بين الشعب. وكانوا كلهم يجتمعون بقلب واحد في قاعة سليمان بالهيكل.","5:13":"ولم يجرؤ أحد من خارج على الانضمام إليهم، بل كان الشعب يشيد بهم.","5:14":"وأخذ عدد المؤمنين بالرب يزداد بانضمام جماعات من الرجال والنساء.","5:15":"وكان الناس يحملون المرضى على فرشهم وأسرتهم إلى الشوارع، لعل ظل بطرس عند مروره يقع على أحد منهم فينال الشفاء.","5:16":"بل كانت الجموع من المدن والقرى المجاورة يأتون إلى أورشليم حاملين المرضى والمعذبين بالأرواح النجسة، فكانوا جميعا يبرأون.","5:17":"إلا أن رئيس الكهنة وجماعته المنتمين إلى مذهب الصدوقيين ملأتهم الغيرة من الرسل،","5:18":"فقبضوا عليهم وألقوهم في السجن العام.","5:19":"ولكن ملاكا من الرب فتح أبواب السجن في الليل وأطلقهم، وقال لهم:","5:20":"«اذهبوا إلى الهيكل، وقفوا معلنين للناس بشارة الحياة الجديدة كاملة!»","5:21":"فأطاعوا وذهبوا إلى الهيكل باكرا عند الفجر وبدأوا يعلمون. بينما عقد المجلس اجتماعا، بدعوة من رئيس الكهنة وجماعته، حضره شيوخ إسرائيل جميعا، وأمروا بإحضار الرسل من السجن،","5:22":"ولكن الحرس لم يجدوهم! فرجعوا يخبرون","5:23":"قائلين: «وجدنا أبواب السجن مغلقة بإحكام، والحراس واقفين أمامها، ولكن لما فتحناها لم نجد في الداخل أحدا!»","5:24":"فسيطر الذهول على قائد حرس الهيكل وعلى رؤساء الكهنة عندما سمعوا هذا الكلام، وتساءلوا: «إلام سينتهي هذا الأمر؟»","5:25":"ثم جاء رجل إلى المجلس يقول: «إن الرجال الذين ألقيتم في السجن هم الآن واقفون في الهيكل يعلمون الناس».","5:26":"فذهب قائد الحرس ورجاله، وجاءوا بالرسل بغير عنف، خوفا من أن يرجمهم الشعب.","5:27":"فلما مثلوا أمام المجلس استجوبهم رئيس الكهنة","5:28":"قائلا: «أمرناكم بشدة ألا تعلموا بهذا الاسم، ولكنكم قد ملأتم أورشليم بتعليمكم، وتريدون أن تحملونا مسئولية سفك دمه!»","5:29":"فأجاب بطرس والرسل: «ينبغي أن يطاع الله لا الناس!","5:30":"إن إله آبائنا أقام يسوع، الذي قتلتموه أنتم معلقين إياه على الخشبة!","5:31":"ولكن الله رفعه إلى يمينه وجعله رئيسا ومخلصا ليمنح إسرائيل التوبة وغفران الخطايا؛","5:32":"ونحن نشهد على هذا، وكذلك يشهد الروح القدس الذي وهبه الله للذين يطيعونه».","5:33":"ولما سمع المجتمعون هذا الكلام اشتد غضبهم، وقرروا أن يقتلوا الرسل.","5:34":"ولكن أحد أعضاء المجلس، واسمه غمالائيل، وهو معلم للشريعة يتبع المذهب الفريسي، ويحترمه جميع الشعب، وقف وأمر أن يخرج الرسل بعض الوقت،","5:35":"ثم قال للمجتمعين: «يابني إسرائيل، حذار أن تنفذوا ما تنوون أن تعملوه بهؤلاء الرجال.","5:36":"فمنذ مدة قصيرة قام ثوداس وادعى أنه شخص عظيم، فتبعه نحو أربع مئة رجل، ولكنه قتل وتفرق أتباعه، وانتهى أمره.","5:37":"ثم قام يهوذا الجليلي في زمن الإحصاء واستمال عددا كبيرا من الناس ليتبعوه، ولكنه هلك أيضا وتشتت أتباعه.","5:38":"فالآن أنصحكم أن تبتعدوا عن هؤلاء الرجال وتتركوهم وشأنهم. فإن كان هذا المبدأ أو هذا العمل من عند الناس، فلابد أن يتهدم،","5:39":"ولكن إن كان من عند الله فلن تتمكنوا أبدا من الوقوف في وجهه، وإلا جعلتم من أنفسكم أعداء لله أيضا».","5:40":"فعمل أعضاء المجلس بهذه النصيحة، واستدعوا الرسل، فجلدوهم وأمروهم ألا يعلموا باسم يسوع، ثم أطلقوهم.","5:41":"ولكن الرسل خرجوا من المجلس فرحين، لأنهم اعتبروا أهلا لأن يلقوا الإهانة من أجل اسم يسوع.","5:42":"وكانوا كل يوم، في الهيكل وفي البيوت، يعلمون ويبشرون بالمسيح يسوع بلا انقطاع.","6:1":"وإذ تكاثر التلاميذ في تلك الأيام، احتج اليهود اليونانيون على العبرانيين، لأن أراملهم لم يكن يحصلن على نصيب من الإعانات اليومية.","6:2":"فدعا الرسل الاثنا عشر جماعة التلاميذ وقالوا لهم: «لا يصح أن نترك نحن كلمة الله لنقوم بتوزيع الإعانات!","6:3":"فاختاروا، أيها الإخوة، سبعة رجال منكم، لهم شهادة حسنة، ممتلئين من الروح القدس والحكمة، فنعينهم ليقوموا بهذه المهمة.","6:4":"أما نحن، فنداوم على الصلاة وخدمة الكلمة».","6:5":"فاستحسنت الجماعة كلها هذا الرأي؛ ووقع الاختيار على استفانوس، وهو رجل مملوء من الإيمان والروح القدس، وفيلبس، وبروخورس، ونيكانور، وتيمون، وبرميناس، ونيقولاوس الأنطاكي المتهود.","6:6":"وقدموهم للرسل، فصلوا ووضعوا أيديهم عليهم.","6:7":"فزادت كلمة الله انتشارا، وتكاثر عدد التلاميذ في أورشليم، وأذعن للإيمان مجموعة كبيرة من الكهنة.","6:8":"وإذ كان استفانوس مملوءا بالإيمان والقوة، كان يعمل عجائب ومعجزات عظيمة بين الشعب.","6:9":"فعارضه بعض المنتمين إلى جماعة العبيد المحررين، يساندهم بعض اليهود من القيروان والإسكندرية، وغيرهم من مقاطعتي كيليكيا وأسيا، وأخذوا يجادلونه.","6:10":"ولكنهم لم يتمكنوا من مقاومة حكمته والروح الذي كان يتكلم به.","6:11":"فما كان منهم إلا أن دفعوا رشوة لبعض الأشخاص ليقولوا: «سمعنا استفانوس يتكلم بالتجديف على موسى وعلى الله!»","6:12":"فأثارت هذه التهمة الشعب والشيوخ والكتبة على استفانوس، فألقوا القبض عليه وجاءوا به إلى المجلس،","6:13":"وأقاموا عليه شهود زور ادعوا أنه: «لا يكف عن التعرض بكلامه للهيكل المقدس وللشريعة","6:14":"فقد سمعناه يقول إن يسوع الناصري سيهدم هذا الهيكل ويغير الطقوس التي تسلمناها من موسى».","6:15":"فلما نظر إليه جميع الحاضرين في المجلس رأوا وجهه كأنه وجه ملاك.","7:1":"وسأل رئيس الكهنة استفانوس: «هل هذه الاتهامات صحيحة؟»","7:2":"فأجاب: «أيها الإخوة والآباء، اسمعوا: ظهر إله المجد لأبينا إبراهيم وهو في بلاد ما بين النهرين، قبل أن يرحل ليسكن في حاران،","7:3":"وقال له: اترك أرضك وعشيرتك، وارحل إلى الأرض التي أرشدك إليها.","7:4":"فأطاع ورحل من بلاد الكلدانيين، وسكن في حاران، وبقي فيها إلى أن مات أبوه، فجاء الله به إلى هذا البلد الذي تسكنون فيه الآن،","7:5":"ولم يعطه هنا ملكا، ولا موطيء قدم. ومع أنه كان وقتئذ بلا ولد، فإن الله وعده بأن يعطي هذا البلد له ولنسله من بعده.","7:6":"فقد قال الله : إن أحفاده سيقاسون الغربة في بلاد ليست لهم، مدة أربع مئة سنة يلاقون خلالها العبودية وسوء المعاملة؛","7:7":"ولكني أنزل العقاب بالشعب الذي يستعبدهم. وبعد ذلك يخرجون ويجيئون ليعبدوني في هذا المكان.","7:8":"وطلب الله إلى إبراهيم أن يختن الذكور في عائلته علامة على العهد الذي أبرمه له. فختن إبراهيم إسحاق في اليوم الثامن من عمره. وختن إسحاق ابنه يعقوب، وختن يعقوب أولاده الاثني عشر، الذين هم الآباء الأولون.","7:9":"وحسد الآباء الأولون يوسف وباعوه، فأصبح عبدا في مصر. ولكن الله كان معه،","7:10":"وأنقذه من جميع المحن التي مر بها، ووهبه نعمة وحكمة عند فرعون ملك مصر، فولاه على مصر، وعلى شؤون بيته.","7:11":"وحدثت بعد ذلك مجاعة في مصر وكنعان، فقاسى آباؤنا من ضيق شديد، إذ لم يجدوا الطعام.","7:12":"ولما سمع يعقوب أن في مصر قمحا أرسل إليها آباءنا أول مرة.","7:13":"وعندما أرسلهم مرة ثانية عرفهم يوسف بنفسه، وتبين لفرعون أصل يوسف.","7:14":"واستدعى يوسف والده يعقوب، وإخوته وعائلاتهم، إلى مصر وكانوا خمسة وسبعين شخصا.","7:15":"فجاء يعقوب وآباؤنا إلى مصر، وأقاموا فيها إلى أن ماتوا،","7:16":"فنقلوا إلى شكيم حيث دفنوا في القبر الذي اشتراه إبراهيم من قبيلة حمور أبي شكيم ببعض الفضة.","7:17":"وفيما كان يقترب إتمام الوعد الذي قطعه الله لإبراهيم، كان الشعب في مصر يتكاثرون ويزدادون عددا.","7:18":"ثم قام على مصر ملك جديد لم يكن يعرف أمر يوسف.","7:19":"فغدر بشعبنا، وأساء معاملة آبائنا، حتى أجبرهم على التخلي عن أطفالهم ليموتوا.","7:20":"في تلك الفترة ولد موسى. وكان جميلا جدا، فرباه والداه في بيتهما ثلاثة أشهر،","7:21":"ولكنهما اضطرا أخيرا إلى التخلي عنه، فأنقذته ابنة فرعون وتبنته وربته.","7:22":"فتثقف موسى بعلوم مصر كلها، حتى صار مقتدرا في القول والعمل.","7:23":"ولما بلغ الأربعين من العمر خطر بقلبه أن يتفقد أحوال إخوته من بني إسرائيل،","7:24":"فرأى واحدا منهم يعتدي عليه مصري، فتدخل ليدافع عن المظلوم، وانتقم له فقتل المصري،","7:25":"على أمل أن يدرك إخوته أن الله سينقذهم على يده. غير أنهم لم يدركوا!","7:26":"وفي اليوم التالي وجد اثنين من إخوته يتعاركان، فحاول أن يصلح بينهما، قائلا: أنتما أخوان، فلماذا يعتدي أحدكما على الآخر؟","7:27":"فما كان من المعتدي على قريبه إلا أن دفعه بعيدا، وقال: من أقامك رئيسا وقاضيا علينا؟","7:28":"أتريد أن تقتلني كما قتلت المصري أمس؟","7:29":"وهنا هرب موسى من مصر إلى بلاد مديان، وعاش فيها غريبا. وهناك أنجب ولدين.","7:30":"وبعدما مضت أربعون سنة كان موسى في صحراء جبل سيناء، عندما ظهر له ملاك الرب في لهيب نار من عليقة تشتعل","7:31":"وأثار المنظر دهشة موسى، فاقترب ليستطلع الأمر، وإذا صوت الرب يناديه:","7:32":"أنا إله آبائك، إله إبراهيم وإسحاق ويعقوب! فارتعد موسى ولم يعد يجرؤ على أن ينظر.","7:33":"فقال له الرب: اخلع نعليك لأن المكان الذي تقف عليه هو أرض مقدسة!","7:34":"إني رأيت العذاب الذي يعانيه شعبي في مصر، وسمعت أنينهم، فنزلت لأنقذهم. والآن، هيا أرسلك إلى مصر!","7:35":"فموسى الذي رفضه شعبه قائلين: من أقامك رئيسا وقاضيا علينا؟ هو نفسه أرسله الله رئيسا ومحررا، يؤيده الملاك الذي ظهر له في العليقة!","7:36":"وقد أخرج الشعب من مصر وهو يجري عجائب ومعجزات فيها، وفي البحر الأحمر، وفي الصحراء مدة أربعين سنة.","7:37":"وموسى هذا هو الذي قال لبني إسرائيل: سيبعث الله لكم من بين إخوتكم نبيا مثلي.","7:38":"وهو الذي كان يقود جماعة الشعب في الصحراء، وقد قام بدور الوسيط بين الملاك الذي كلمه على جبل سيناء وآبائنا، فنقل إليكم وصايا الله الحية.","7:39":"ولكن آباءنا رفضوا أن يطيعوا موسى، ولم يعترفوا بقيادته، وحنت قلوبهم للرجوع إلى مصر،","7:40":"وقالوا لهرون: اصنع لنا آلهة تهدينا في سيرنا، فإننا لا نعلم ماذا جرى لموسى هذا الذي أخرجنا من بلاد مصر!","7:41":"فصنعوا صنما على صورة عجل في تلك الأيام وقدموا له ذبيحة، وابتهجوا بما صنعت أيديهم.","7:42":"فتحول الله عنهم وتركهم يعبدون كواكب السماء، كما جاء في كتاب الأنبياء:","7:43":"لا، بل حملتم خيمة الصنم مولوك، وكوكب الإله رمفان، التمثالين اللذين صنعتم لتسجدوا لهما! لذلك سأنفيكم إلى أبعد من بابل!","7:44":"وقد حمل آباؤنا معهم في الصحراء خيمة الشهادة. وكان الله قد أوصى موسى أن يقيمها على المثال الذي أطلعه عليه؛","7:45":"ثم دخلوا بها إلى هذه البلاد التي فتحوها بقيادة يشوع، بعدما طرد الله من أمامهم الشعوب الساكنة فيها. وظل آباؤنا يعبدون الله في الخيمة حتى أيام داود،","7:46":"الذي نال قبولا لدى الله، فسعى أن يجد بيتا لإله يعقوب.","7:47":"وتحققت هذه الرغبة على يد سليمان الذي بنى الهيكل.","7:48":"إلا أن العلي لا يسكن في هياكل تصنعها أيدي البشر، كما قال النبي:","7:49":"السماء عرشي، والأرض موطيء قدمي ... فأي بيت تبنون لي؟ يقول الرب، وأي مكان تعدون لراحتي؟","7:50":"أليست يدي قد صنعت هذه الأشياء كلها؟»","7:51":"ثم قال استفانوس: «ياأصحاب الرقاب الصلبة والقلوب والآذان غير المختونة! إنكم دائما تقاومون الروح القدس. وكما فعل آباؤكم تفعلون!","7:52":"فأي نبي نجا من اضطهادهم وقد قتلوا الذين أنبأوا بمجيء البار الذي سلمتموه أنتم وقتلتموه!","7:53":"فأنتم أخذتم الشريعة من أيدي الملائكة، ولكنكم لم تطيعوها!»","7:54":"فلما سمع المجتمعون كلام استفانوس، ملأ الغيظ قلوبهم، وأخذوا يصرون بأسنانهم توعدا.","7:55":"فرفع استفانوس نظره إلى السماء، وهو ممتليء من الروح القدس، فرأى مجد الله ويسوع واقفا عن يمين الله،","7:56":"فقال: «إني أرى السماء مفتوحة وابن الإنسان واقفا عن يمين الله!»","7:57":"فصاحوا صياحا شديدا، وسدوا آذانهم وهجموا عليه هجمة واحدة،","7:58":"ودفعوه إلى خارج المدينة، وأخذوا يرجمونه بالحجارة. وخلع الشهود ثيابهم عند قدمي شاب اسمه شاول لكي يحرسها.","7:59":"وبينما كانوا يرجمون استفانوس، كان يدعو: «أيها الرب يسوع، اقبل روحي!»","7:60":"ثم ركع وصرخ بصوت عال: «يارب، لا تحسب عليهم هذه الخطيئة!» وإذ قال هذا رقد.","8:1":"وكان شاول موافقا على قتل استفانوس. وفي ذلك اليوم نفسه وقع اضطهاد شديد على الكنيسة التي في أورشليم. فتشتت الإخوة جميعا في نواحي اليهودية والسامرة، ولم يبق في أورشليم إلا الرسل.","8:2":"وأما استفانوس فقد دفنه بعض الرجال الأتقياء، وناحوا عليه كثيرا.","8:3":"أما شاول فكان يحاول إبادة الكنيسة، فيذهب من بيت إلى بيت ويجر الرجال والنساء ويلقيهم في السجن.","8:4":"والذين تشتتوا كانوا ينتقلون من مكان إلى مكان مبشرين بالكلمة.","8:5":"فذهب فيلبس إلى مدينة في منطقة السامرة، وأخذ يبشر أهلها بالمسيح.","8:6":"فأصغت الجموع إلى كلامه بقلب واحد، إذ سمعوا بالعلامات التي أجراها، أو رأوها بأنفسهم،","8:7":"فقد كان يأمر الأرواح النجسة، فتصرخ بصوت عال وتخرج من المسكونين بها، كما شفى كثيرين من المشلولين والعرج،","8:8":"فعمت الفرحة أنحاء المدينة.","8:9":"وكان قبل ذلك في تلك المدينة ساحر اسمه سيمون، يمارس السحر فيذهل أهل السامرة ويدعي أنه رجل عظيم.","8:10":"فأصغى إليه الجميع من الصغير إلى الكبير، قائلين: «هذا الرجل هو قدرة الله العظمى!»","8:11":"وإنما أصغوا إليه لأنهم كانوا قد انخدعوا مدة طويلة بحيله السحرية!","8:12":"فلما آمنوا بكلام فيلبس الذي بشرهم بملكوت الله وباسم يسوع، تعمدوا رجالا ونساء.","8:13":"وسيمون نفسه آمن وتعمد، فألصق نفسه بفيلبس، وإذ شاهد الآيات والمعجزات التي أجريت على يده، استولت عليه الدهشة.","8:14":"وسمع الرسل في أورشليم أن أهل السامرة قبلوا كلمة الله، فأرسلوا إليهم بطرس ويوحنا.","8:15":"فصليا لأجلهم لكي ينالوا الروح القدس،","8:16":"لأنه لم يكن قد حل بعد على أحد منهم، إلا أنهم كانوا قد تعمدوا باسم الرب يسوع.","8:17":"ثم وضعا أيديهما عليهم، فنالوا الروح القدس.","8:18":"ولما رأى سيمون أن الروح القدس قد حل على المؤمنين لما وضع الرسولان أيديهما عليهم، عرض على بطرس ويوحنا بعض المال، وقال لهما:","8:19":"«أعطياني أنا أيضا هذه السلطة لكي ينال الروح القدس من أضع عليه يدي».","8:20":"فقال له بطرس: «لتبق لك فضتك لهلاكك! لأنك ظننت أنك تقدر أن تشتري هبة الله بالمال!","8:21":"لا قسمة لك في هذا الأمر ولا نصيب، لأن قلبك ليس مخلصا تجاه الله.","8:22":"فتب عن شرك هذا واطلب إلى الله، عسى أن يغفر لك نية قلبك،","8:23":"لأني أراك تتخبط في مرارة العلقم وقيود الخطيئة!»","8:24":"فقال سيمون: «صليا أنتما إلى الرب من أجلي حتى لا ينزل بي شيء مما تشيران إليه».","8:25":"وبعدما شهد بطرس ويوحنا بكلمة الرب وأعلناها هناك، رجعا إلى أورشليم وقد بشرا قرى كثيرة في منطقة السامرة.","8:26":"ثم إن ملاكا من عند الرب كلم فيلبس فقال له: «قم اذهب نحو الجنوب، ماشيا على الطريق البرية بين أورشليم وغزة».","8:27":"فقام وذهب. وإذا رجل حبشي، خصي، يعمل وزيرا للشؤون المالية عند كنداكة ملكة الحبشة، كان قد حج إلى أورشليم للسجود فيها،","8:28":"وهو راجع إلى الحبشة راكبا في عربته، يقرأ في كتاب النبي إشعياء.","8:29":"فقال الروح لفيلبس: «تقدم ورافق هذه العربة!»","8:30":"فأسرع فيلبس وسمع الخصي يقرأ نبوءة إشعياء، فسأله: «أتفهم ما تقرأ؟»","8:31":"فأجاب: «كيف يمكنني ذلك إن لم يشرح لي أحد؟» ودعا فيلبس أن يصعد إلى العربة ويجلس معه.","8:32":"وكان الخصي قد وصل في فصل الكتاب الذي يقرأه إلى القول: «مثل شاة سيق إلى الذبح، ومثل الحمل الصامت بين يدي من يجزه، هكذا لم يفتح فاه!","8:33":"في أثناء تواضعه عومل بغير عدل. من يخبر عن نسله؟ فإن حياته قد انتزعت من الأرض!»","8:34":"وسأل الخصي فيلبس: «قل لي: إلى من يشير النبي بهذا القول؟ إلى نفسه أو إلى شخص آخر؟»","8:35":"فتكلم وأخذ يبشره بيسوع انطلاقا من كتاب النبي هذا.","8:36":"وبينما كانت العربة تسير بهما، وصلا إلى مكان فيه ماء، فقال الخصي: «ها هو الماء، فماذا يمنع أن أتعمد؟»","8:37":"فأجابه فيلبس: «هذا جائز إن كنت تؤمن من كل قلبك». فقال الخصي: «إني أومن بأن يسوع المسيح هو ابن الله».","8:38":"وأمر أن تقف العربة، فنزلا إلى الماء معا، وعمد فيلبس الخصي.","8:39":"وما إن طلعا من الماء حتى خطف روح الرب فيلبس، فلم يعد الخصي يراه. فتابع سفره بفرح.","8:40":"أما فيلبس فقد شوهد في أشدود، ثم سار يبشر كل مدينة حتى وصل إلى قيصرية.","9:1":"أما شاول فكان لايزال يفور بالتهديد والقتل على تلاميذ الرب. فذهب إلى رئيس الكهنة،","9:2":"وطلب منه رسائل إلى مجامع اليهود في دمشق لتسهيل القبض على أتباع هذا الطريق من الرجال والنساء، حيثما يجدهم، ليسوقهم مقيدين إلى أورشليم.","9:3":"وفيما هو منطلق إلى دمشق، وقد اقترب منها، لمع حوله فجأة نور من السماء،","9:4":"فوقع إلى الأرض وسمع صوتا يقول له: «شاول! شاول! لماذا تضطهدني؟»","9:5":"فسأل: «من أنت ياسيد؟» فجاءه الجواب: «أنا يسوع الذي أنت تضطهده، صعب عليك أن ترفس المناخس».","9:6":"فقال وهو مرتعد ومتحير؛ «يارب ماذا تريد أن أفعل؟» فقال له الرب: «قم، وادخل المدينة فيقال لك ما يجب أن تفعله».","9:7":"وأما مرافقو شاول فوقفوا مذهولين لا ينطقون، فقد سمعوا الصوت ولكنهم لم يروا أحدا.","9:8":"وعندما نهض شاول عن الأرض، فتح عينيه فوجد أنه لا يبصر، فاقتادوه بيده وأدخلوه إلى دمشق،","9:9":"حيث بقي ثلاثة أيام لا يبصر ولا يأكل ولا يشرب.","9:10":"وكان في دمشق تلميذ للرب اسمه حنانيا، ناداه الرب في رؤيا: «يا حنانيا!» فقال: «لبيك يارب!»","9:11":"فقال له الرب: «اذهب إلى الشارع المعروف بالمستقيم واسأل في بيت يهوذا، عن رجل من طرسوس اسمه شاول. إنه يصلي هناك الآن.","9:12":"وقد رأى في رؤيا رجلا اسمه حنانيا يدخل إليه ويضع يده عليه، فيبصر».","9:13":"فقال حنانيا للرب: «ولكني، يارب، قد سمعت من كثيرين بالفظائع التي ارتكبها هذا الرجل بقديسيك في أورشليم،","9:14":"وقد خوله رؤساء الكهنة السلطة ليلقي القبض على كل من يدعو باسمك».","9:15":"فأمره الرب: «اذهب! فقد اخترت هذا الرجل ليكون إناء يحمل اسمي إلى الأمم والملوك وبني إسرائيل.","9:16":"وسأريه كم ينبغي أن يتألم من أجل اسمي!»","9:17":"فذهب حنانيا ودخل بيت يهوذا، ووضع يديه على شاول وقال: «أيها الأخ شاول، إن الرب يسوع، الذي ظهر لك في الطريق التي جئت فيها، أرسلني إليك لكي تبصر وتمتليء من الروح القدس».","9:18":"وفي الحال تساقط من عيني شاول ما يشبه القشور، فأبصر ، ثم قام وتعمد.","9:19":"وتناول طعاما فاستعاد قوته وبقي بضعة أيام مع التلاميذ في دمشق.","9:20":"وفي الحال بدأ يبشر في المجامع بأن يسوع هو ابن الله.","9:21":"وأثار كلامه دهشة السامعين، فتساءلوا: «أليس هذا هو الذي كان يبيد جميع الداعين بهذا الاسم في أورشليم؟ أما جاء إلى هنا ليلقي القبض عليهم ويسوقهم مقيدين إلى رؤساء الكهنة؟»","9:22":"وأما شاول فقد صار أكثر حماسة في وعظه، فكان يفحم اليهود الساكنين في دمشق ببراهينه التي كان يبين بها أن يسوع هو المسيح.","9:23":"وبعد عدة أيام، حاك اليهود في دمشق مؤامرة لقتل شاول،","9:24":"فعلم بها. وكانوا يراقبون أبواب المدينة نهارا وليلا ليقتلوه وهو يخرج منها.","9:25":"فأخذه بعض التلاميذ ليلا ووضعوه في سل، وأنزلوه بالحبال من على سور المدينة.","9:26":"ولما وصل شاول إلى أورشليم، حاول أن ينضم إلى التلاميذ هناك، فخافوا منه، إذ لم يصدقوا أنه صار تلميذا للرب.","9:27":"فتولى برنابا أمره وأحضره إلى الرسل، وحدثهم كيف ظهر الرب له في الطريق وكلمه، وكيف بشر بجرأة باسم يسوع في دمشق.","9:28":"فأخذ يذهب ويجيء معهم في أورشليم، مبشرا باسم الرب بجرأة.","9:29":"وكان يخاطب اليهود اليونانيين ويجادلهم، فحاولوا أن يقتلوه.","9:30":"فلما علم الإخوة بذلك أنزلوه إلى ميناء قيصرية. ومن هناك أرسلوه إلى طرسوس.","9:31":"في أثناء ذلك كانت الكنيسة في مناطق اليهودية والجليل والسامرة تتمتع بالسلام. وكانت تنمو وتسير في تقوى الر ب، بمساندة الروح القدس.","9:32":"وبينما كان بطرس ينتقل من مكان إلى مكان، زار الساكنين في مدينة لدة،","9:33":"ووجد هناك مشلولا اسمه إينياس، مضت عليه ثماني سنوات وهو طريح الفراش.","9:34":"فقال له: «ياإينياس، شفاك يسوع المسيح. قم ورتب سريرك بنفسك!» فقام في الحال.","9:35":"ورآه سكان لدة وشارون جميعا، فرجعوا إلى الرب.","9:36":"وكان في مدينة يافا تلميذة اسمها طابيثا، ومعنى اسمها: غزالة، كان يشغلها دائما فعل الخير ومساعدة الفقراء.","9:37":"وحدث في ذلك الوقت أنها مرضت وماتت، فغسلوها ووضعوها في غرفة بالطبقة العليا.","9:38":"وسمع التلاميذ في يافا أن بطرس في لدة. وإذ كانت يافا قريبة من لدة، أرسلوا إليه رجلين يطلبان إليه قائلين: «تعال إلينا ولا تتأخر!»","9:39":"فقام وذهب. ولما وصل قادوه إلى الطبقة العليا، فتقدمت إليه جميع الأرامل باكيات، يعرضن بعض الأقمصة والثياب مما كانت غزالة تخيطه وهي معهن.","9:40":"فطلب بطرس إلى جميع الحاضرين أن يخرجوا من الغرفة، وركع وصلى، ثم التفت إلى الجثة وقال: «ياطابيثا، قومي!» ففتحت عينيها. ولما رأت بطرس جلست،","9:41":"فمد يده إليها وساعدها على النهوض، ثم دعا القديسين والأر امل، وردها إليهم حية.","9:42":"وانتشر خبر هذه المعجزة في يافا كلها، فآمن بالرب كثيرون.","9:43":"وبقي بطرس في يافا عدة أيام عند دباغ اسمه سمعان.","10:1":"وكان يسكن في قيصرية قائد مئة اسمه كرنيليوس، ينتمي إلى الكتيبة الإيطالية،","10:2":"وكان تقيا يخاف الله ، هو وأهل بيته جميعا، يتصدق على الشعب كثيرا، ويصلي إلى الله دائما.","10:3":"وذات نهار نحو الساعة الثالثة بعد الظهر، رأى كرنيليوس في رؤيا واضحة ملاكا من عند الله يدخل إليه ويقول: «ياكرنيليوس!»","10:4":"فنظر إلى الملاك وقد استولى عليه الخوف، وسأل: «ماذا ياسيد؟» فأجابه: «صلواتك صعدت أمام الله تذكارا.","10:5":"والآن أرسل بعض الرجال إلى يافا واستدع سمعان الملقب بطرس.","10:6":"إنه يقيم في بيت سمعان الدباغ عند البحر».","10:7":"فما إن ذهب الملاك الذي كان يكلم كرنيليوس، حتى دعا اثنين من خدمه، وجنديا تقيا من مرافقيه الدائمين،","10:8":"وروى لهم الخبر كله، وأرسلهم إلى يافا.","10:9":"وفي اليوم التالي، بينما كان الرجال الثلاثة يقتربون من مدينة يافا، صعد بطرس نحو الظهر إلى السطح ليصلي.","10:10":"وأحس جوعا شديدا، فاشتهى أن يأكل. وبينما الطعام يعد له، وقعت عليه غيبوبة،","10:11":"فرأى رؤيا: السماء مفتوحة، ووعاء يشبه قطعة كبيرة من القماش مربوطة بأطرافها الأربعة يتدلى إلى الأرض،","10:12":"وهو مليء بأنواع الحيوانات الدابة على الأرض والوحوش والزواحف وطيور السماء جميعا.","10:13":"وناداه صوت: «يابطرس، قم اذبح وكل!»","10:14":"ولكن بطرس أجاب: «كلا يارب، فأنا لم آكل قط شيئا محرما أو نجسا».","10:15":"فقال له الصوت أيضا: «ما طهره الله لا تحسبه أنت نجسا!»","10:16":"وتكرر هذا ثلاث مرات، ثم ارتفع الوعاء إلى السماء.","10:17":"تحير بطرس وأخذ يسائل نفسه عن معنى الرؤيا التي رآها. وإذا الرجال الذين أرسلهم كرنيليوس قد سألوا عن بيت سمعان الدباغ ووقفوا بالباب","10:18":"يستخبرون: «هل سمعان الملقب بطرس مقيم هنا؟»","10:19":"في هذه الأثناء كان بطرس يواصل التفكير في معنى الرؤيا، فقال له الروح: «بالباب ثلاثة رجال يطلبونك","10:20":"فانزل إليهم ورافقهم بلا تردد، فإني أنا أرسلتهم».","10:21":"فنزل إليهم وقال: «أنا الذي تطلبون. فما سبب حضوركم؟»","10:22":"فأجابوه: «قائد المئة كرنيليوس رجل صالح يتقي الله ، ويشهد له بذلك شعب اليهود جميعا. وقد أوحى الله إليه بواسطة ملاك طاهر أن يستدعيك إلى بيته ليسمع ما عندك من كلام».","10:23":"فدعاهم بطرس ليمضوا الليلة ضيوفا بذلك البيت. وفي الصباح ذهب معهم، يرافقه بعض الإخوة من يافا،","10:24":"فوصلوا قيصرية في اليوم الثاني. وكان كرنيليوس ينتظر وصولهم، وقد دعا أقاربه وأصدقاءه المقربين.","10:25":"فما إن دخل بطرس حتى استقبله كرنيليوس ساجدا له،","10:26":"فأنهضه بطرس وقال: «قم! ما أنا إلا إنسان مثلك!»","10:27":"ودخل بطرس وهو يحادثه، فرأى جمعا كبيرا من الناس،","10:28":"فقال لهم: «أنتم تعلمون أنه محرم على اليهودي أن يتعامل مع الأجنبي أو يزوره في بيته. غير أن الله أراني ألا أقول عن إنسان ما إنه دنس أو نجس.","10:29":"فلذلك جئت من غير اعتراض، تلبية لدعوتكم. فما هو سبب دعوتكم لي؟»","10:30":"فأجاب كرنيليوس: «منذ أربعة أيام، في مثل هذه الساعة كنت أصلي في بيتي صلاة الساعة الثالثة بعد الظهر فظهر أمامي فجأة رجل يلبس ثوبا براقا","10:31":"وقال لي: ياكرنيليوس، سمع الله صلاتك وذكر صدقاتك.","10:32":"والآن أرسل رجالا إلى يافا، واستدع سمعان الملقب بطرس. إنه يقيم في بيت سمعان الدباغ عند البحر.","10:33":"فأرسلت حالا أدعوك، وقد أحسنت بمجيئك. ونحن الآن جميعا حاضرون أمام الله لنسمع كل ما أمرك به الرب».","10:34":"فبدأ بطرس كلامه قائلا: «تبين لي فعلا أن الله لا يفضل أحدا على أحد،","10:35":"بل يقبل من يتقيه ويعمل الصلاح مهما كانت جنسيته.","10:36":"وقد أرسل كلمته إلى بني إسرائيل، وبشرهم بالسلام بواسطة يسوع المسيح، رب الجميع.","10:37":"ولابد أنكم عرفتم بكل ما جرى في بلاد اليهود، وكان بدء الأمر في الجليل بعد المعمودية التي نادى بها يوحنا.","10:38":"فقد مسح الله يسوع الناصري بالروح القدس وبالقدرة، فكان ينتقل من مكان إلى مكان يعمل الخير، ويشفي جميع الذين تسلط عليهم إبليس، لأن الله كان معه.","10:39":"ونحن شهود على كل ما قام به في بلاد اليهود وفي أورشليم، وقد قتلوه حقا، معلقا على خشبة.","10:40":"ولكن الله أقامه من الموت في اليوم الثالث، وجعله يظهر،","10:41":"لا للشعب كله، بل للشهود الذين اختارهم الله من قبل، لنا نحن الذين أكلنا وشربنا معه بعد قيامته من بين الأموات.","10:42":"ثم أمرنا أن نبشر شعبنا به، ونشهد أنه هو الذي عينه الله ديانا للأحياء وللأموات.","10:43":"له يشهد جميع الأنبياء أن كل من يؤمن به ينال باسمه غفران الخطايا».","10:44":"وبينما كان بطرس يتكلم بهذا الكلام، حل الروح القدس على جميع الذين كانوا يسمعون.","10:45":"فدهش المؤمنون اليهود الذين جاءوا برفقة بطرس، لأن هبة الروح القدس فاضت أيضا على غير اليهود،","10:46":"إذ سمعوهم يتكلمون بلغات، ويسبحون الله . فقال بطرس:","10:47":"«أيستطيع أحد أن يمنع الماء فلا يتعمد أيضا هؤلاء الذين نالوا الروح القدس مثلنا؟»","10:48":"وأمر أن يتعمدوا باسم يسوع المسيح. ثم دعوه أن يقيم عندهم بضعة أيام.","11:1":"وسمع الرسل والإخوة في اليهودية أن غير اليهود أيضا قبلوا كلمة الله،","11:2":"فما إن عاد بطرس إلى أورشليم حتى جادله دعاة الختان، وعارضوه قائلين:","11:3":"«كيف دخلت بيت رجال غير مختونين، وأكلت معهم؟»","11:4":"فشرح لهم بطرس ما حدث على التوالي، وقال:","11:5":"«كنت أصلي في مدينة يافا، فوقعت علي غيبوبة، فرأيت في رؤيا وعاء يشبه قطعة كبيرة من القماش مربوطة بأطرافها الأربعة، وقد تدلى إلي من السماء.","11:6":"وعندما تأملته مليا وجدت فيه أنواع الحيوانات الدابة على الأرض والوحوش والزواحف وطيور السماء جميعا،","11:7":"وسمعت صوتا يقول لي: يابطرس، قم اذبح وكل!","11:8":"فأجبت: كلا يارب، فلم يدخل فمي قط شيء محرم أو نجس.","11:9":"فقال لي الصوت السماوي أيضا: ما طهره الله لا تحسبه أنت نجسا.","11:10":"وتكرر هذا ثلاث مرات، ثم سحب الوعاء بما فيه إلى السماء.","11:11":"وإذا ثلاثة رجال مرسلون إلي من قيصرية وصلوا إلى البيت الذي كنت مقيما فيه،","11:12":"فأمرني الروح أن أذهب معهم بلا تردد، فذهبت، ورافقني هؤلاء الإخوة الستة. وعند دخولنا بيت الرجل،","11:13":"أخبرنا كيف رأى الملاك في بيته واقفا وقائلا له: أرسل رجالا إلى يافا، واستدع سمعان الملقب بطرس،","11:14":"وهو يكلمك كلاما به تخلص أنت وأهل بيتك جميعا.","11:15":"ولما ابتدأت أتكلم، حل الروح القدس عليهم كما حل علينا في البداية","11:16":"فتذكرت ما قاله الرب لنا: إن يوحنا عمد بالماء، وأما أنتم فستتعمدون بالروح القدس.","11:17":"فإن كان الله قد ساواهم بنا فأعطاهم الهبة التي أعطانا، إذ آمنا بالرب يسوع المسيح، فمن أكون أنا حتى أعيق الله ؟»","11:18":"فلما سمع المعارضون هذا، سكتوا، ومجدوا الله قائلين: «إذن، قد أنعم الله أيضا على غير اليهود بالتوبة لنوال الحياة».","11:19":"أما المؤمنون الذين تشتتوا بسبب الاضطهاد الذي وقع عليهم بعد موت استفانوس، فمروا بفينيقية وقبرص وأنطاكية، وهم لا يبشرون بالكلمة إلا اليهود.","11:20":"غير أن بعضا منهم، وهم أصلا من قبرص والقيروان، وصلوا أنطاكية، وأخذوا يبشرون اليونانيين أيضا بالرب يسوع.","11:21":"فكانت يد الرب معهم، فآمن عدد كبير واهتدوا إلى الرب.","11:22":"ووصل خبر ذلك إلى الكنيسة في أورشليم، فأرسلوا برنابا إلى أنطاكية.","11:23":"فلما وصل ورأى النعمة التي منحها الله ، امتلأ فرحا، وحث الجميع على الثبات في الرب بعزم القلب.","11:24":"فقد كان برنابا رجلا صالحا ممتلئا من الروح القدس والإيمان. وانضم إلى الرب جمع كبير.","11:25":"وتوجه برنابا إلى طرسوس يبحث عن شاول.","11:26":"ولما وجده جاء به إلى أنطاكية، فكانا يجتمعان مع الكنيسة هناك سنة كاملة، ويعلمان جمعا كبيرا. وفي أنطاكية أطلق على تلاميذ الرب أول مرة اسم المسيحيين.","11:27":"وفي تلك الأيام جاء إلى أنطاكية بعض الأنبياء من أورشليم،","11:28":"وبينهم نبي اسمه أغابوس، تنبأ بوحي من الروح أن مجاعة عظيمة ستحدث في البلاد كلها. وقد وقعت هذه المجاعة فعلا في عهد القيصر كلوديوس.","11:29":"لذلك قرر التلاميذ في أنطاكية أن يتبرع كل منهم بما يتيسر له، ويرسلوا إعانة إلى الإخوة المقيمين في اليهودية.","11:30":"ففعلوا ذلك، وأرسلوا الإعانة إلى الشيوخ بيد برنابا وشاول.","12:1":"في ذلك الوقت بدأ الملك هيرودس يضطهد بعض أفراد الكنيسة،","12:2":"فقتل يعقوب شقيق يوحنا بالسيف.","12:3":"ولما رأى أن هذا يرضي اليهود، قرر أن يقبض على بطرس أيضا، وكان ذلك في أيام عيد الفطير.","12:4":"فلما قبض عليه، أودعه السجن تحت حراسة أربع مجموعات من الحراس، تتكون كل مجموعة منها من أربعة جنود. وكان ينوي أن يسلمه إلى اليهود بعد عيد الفصح،","12:5":"فأبقاه في السجن. أما الكنيسة فكانت ترفع الصلاة الحارة إلى الله من أجله.","12:6":"وفي الليلة التي كان هيرودس قد نوى أن يسلم بطرس بعدها، كان بطرس نائما بين جنديين، مقيدا بسلسلتين، وأمام الباب جنود يحرسون السجن.","12:7":"وفجأة حضر ملاك من عند الرب، فامتلأت غرفة السجن نورا. وضرب الملاك بطرس على جنبه وأيقظه وقال: «قم سريعا!» فسقطت السلسلتان من يديه.","12:8":"فقال له الملاك: «شد حزامك، والبس حذاءك!» ففعل. ثم قال له: «البس رداءك واتبعني!»","12:9":"فخرج بطرس يتبع الملاك وهو يظن أنه يرى رؤيا، ولا يدري أن ما يجري على يد الملاك أمر حقيقي.","12:10":"واجتازا نقطة الحراسة الأولى ثم الثانية. ولما وصلا إلى باب السجن الحديدي الذي يؤدي إلى المدينة انفتح لهما من ذاته، فخرجا. وبعدما عبرا شارعا واحدا، فارقه الملاك حالا.","12:11":"عندئذ استعاد بطرس وعيه، فهتف: «الآن أيقنت أن الرب أرسل ملاكه فأنقذني من قبضة هيرودس، ومن توقعات شعب اليهود!»","12:12":"وإذ أدرك ذلك، اتجه إلى بيت مريم أم يوحنا الملقب مرقس، حيث كان عدد كبير من المؤمنين مجتمعين يصلون.","12:13":"ولما وصل قرع الباب الخارجي، فجاءت خادمة اسمها رودا لتتسمع.","12:14":"فلما عرفت صوت بطرس لم تفتح لشدة الفرح، بل أسرعت إلى داخل البيت تبشر الحاضرين بأن بطرس بالباب.","12:15":"فقالوا لها: «أنت تهذين!» ولكنها أكدت لهم الخبر، فقالوا: «لعله ملاك بطرس!»","12:16":"أما بطرس فواصل قرع الباب حتى فتحوا له. فلما رأوه استولت عليهم الدهشة!","12:17":"فأشار بيده أن يسكتوا، وحدثهم كيف أخر جه الرب من السجن، وقال: «أخبروا يعقوب والإخوة بهذا». ثم خرج وذهب إلى مكان آخر.","12:18":"ولما طلع الصباح حدثت بلبلة عظيمة بين الجنود، وأخذوا يتساءلون: «ما الذي جرى لبطرس؟»","12:19":"ولما أمر هيرودس باستدعائه ولم يجده، أجرى تحقيقا مع الحر اس، وأمر بإعدامهم.","12:20":"وكان ناقما على أهل صور وصيدا. فاتفقوا وأرسلوا وفدا منهم يستعطفون بلاستس حاجب الملك طالبين الأمان، لأن منطقتهم كانت تكسب رزقها من مملكة هيرودس.","12:21":"وفي اليوم المعين لمقابلة الوفد، ارتدى هيرودس ثوبه الملوكي، وجلس على عرشه يخاطبهم.","12:22":"فهتف الشعب قائلين: «هذا صوت إله لا صوت إنسان!»","12:23":"فضربه ملاك من عند الرب في الحال لأنه لم يعط المجد لله، فأكله الدود ومات!","12:24":"أما كلمة الرب فكانت تنمو وتزداد انتشارا.","12:25":"وكان برنابا وشاول قد أنجزا المهمة في أورشليم، فرجعا إلى أنطاكية ومعهما يوحنا الملقب مرقس.","13:1":"وكان في الكنيسة التي في أنطاكية بعض الأنبياء والمعلمين؛ ومنهم برنابا؛ وسمعان الذي يدعى الأسود؛ ولوكيوس من القيروان؛ ومناين الذي تربى في طفولته مع هيرودوس حاكم الربع؛ وشاول.","13:2":"وذات يوم، وهم صائمون يتعبدون للرب، قال لهم الروح القدس: «خصصوا لي برنابا وشاول لأجل العمل الذي دعوتهما إليه».","13:3":"فبعدما صاموا وصلوا ووضعوا عليهما أيديهم أطلقوهما.","13:4":"وإذ أرسل الروح القدس برنابا وشاول، توجها إلى ميناء سلوكية، وسافرا بحرا باتجاه قبرص.","13:5":"ولما وصلا الجزيرة نزلا في سلاميس، وأخذا يبشران بكلمة الله في مجامع اليهود، وكان يرافقهما يوحنا معاونا لهما.","13:6":"واجتازا الجزيرة كلها حتى وصلا بافوس. وهناك قابلا ساحرا يهوديا نبيا دجالا، اسمه باريشوع،","13:7":"وكان مقربا من سرجيوس بولس حاكم قبرص. وكان الحاكم ذكيا، فاستدعى برنابا وشاول، وطلب إليهما أن يكلماه بكلمة الله.","13:8":"فعارضهما الساحر عليم، وهذا معنى اسمه، ساعيا أن يحول الحاكم عن الإيمان.","13:9":"أما شاول، وقد صار اسمه بولس، فامتلأ من الروح القدس، ونظر إلى الساحر وقال:","13:10":"«أيها الممتليء غشا وخبثا! ياابن إبليس! ياعدو كل بر! أما تكف عن تعويج طرق الرب المستقيمة؟","13:11":"الآن ستمتد يد الرب عليك، فتصير أعمى لا تبصر النور إلى حين». وفي الحال سقطت على عينيه غمامة مظلمة، فأخذ يدور طالبا من يقوده بيده!","13:12":"ولما رأى الحاكم ما جرى آمن مدهوشا من تعليم الرب.","13:13":"وأبحر بولس ورفيقاه من بافوس إلى برجة في بمفيلية. وهناك فارق يوحنا بولس وبرنابا ورجع إلى أورشليم.","13:14":"أما هما فسافرا من برجة إلى أنطاكية التابعة لمقاطعة بيسيدية. ودخلا المجمع اليهودي يوم السبت، وجلسا.","13:15":"وبعد قراءة من الشريعة وكتب الأنبياء، أرسل إليهما رؤساء المجمع يقولون: «أيها الأخوان، إن كان عندكما ما تعظان به المجتمعين، فتكلما».","13:16":"فوقف بولس، وأشار بيده، وقال:","13:17":"إن إله شعب إسرائيل هذا اختار آباءنا، ورفع من شأن شعبنا طوال غربتهم في مصر، ثم أخرجهم منها بقدرة ذراعه الفائقة.","13:18":"وعالهم في الصحراء نحو أربعين سنة،","13:19":"ثم أزال سبعة شعوب من بلاد كنعان، وأورثهم أرضها،","13:20":"نحو أربع مئة وخمسين سنة. بعد ذلك، أقام لهم قضاة كان آخرهم النبي صموئيل.","13:21":"فطلب إليه بنو إسرائيل أن يولي عليهم ملكا، فأقام الله عليهم شاول بن قيس، من سبط بنيامين، فملك عليهم أربعين سنة.","13:22":"ثم عزله الله ، وعين بدلا منه داود الذي شهد له بقوله: إني وجدت داود بن يسى رجلا يوافق قلبي، سيعمل كل ما أشاء.","13:23":"وقد بعث الله إلى إسرائيل من نسل داود مخلصا هو يسوع، إتماما لوعده.","13:24":"وقد سبق يوحنا مجيء يسوع، فدعا شعب إسرائيل جميعا إلى معمودية التوبة.","13:25":"ولما أوشك يوحنا أن ينهي مهمته، قال: من تظنونني؟ لست أنا (المخلص)، بل إنه آت بعدي. ولست أستحق أن أحل رباط حذائه!","13:26":"أيها الإخوة، يابني جنس إبراهيم، ويا كل من يتقي الله من الحاضرين هنا: إلينا أرسل الله كلمة هذا الخلاص!","13:27":"فإن أهل أورشليم ورؤساءهم عملوا على إتمام ما يقرأ عليكم كل يوم سبت من نبوءات، وهم لا يعلمون. إذ حكموا على يسوع بالموت،","13:28":"ومع أنهم لم يثبتوا عليه أي جرم يستحق الموت، طلبوا من بيلاطس أن يقتله.","13:29":"وبعدما نفذوا فيه كل ما كتب عنه، أنزلوه عن الصليب، ودفنوه في قبر.","13:30":"ولكن الله أقامه من بين الأموات،","13:31":"فظهر عدة أيام للذين رافقوه من منطقة الجليل إلى أورشليم. وهم الآن يشهدون بذلك أمام الشعب.","13:32":"وها نحن الآن نبشركم بأن ما وعد الله به آباءنا،","13:33":"قد أتمه لنا نحن أبناءهم، إذ أقام يسوع من الموت وفقا لما كتب في المزمور الثاني: أنت ابني؛ أنا اليوم ولدتك.","13:34":"وأما أن الله قد أقام يسوع من بين الأموات ولن يدع الفساد ينال منه فيما بعد، فقد ورد في قوله: سأمنحكم البركات المقدسة الصادقة التي وعدت بها داود.","13:35":"ويقول داود في مزمور آخر: لن تدع وحيدك القدوس يرى فسادا.","13:36":"وقد مات داود بعدما خدم شعبه في عصره وفقا لمشيئة الله، ودفن فلحق بآبائه، ونال منه الفساد.","13:37":"أما الذي أقامه الله فلم ينل منه الفساد قط.","13:38":"فاعلموا، أيها الإخوة، أنه بيسوع تبشرون بغفران الخطايا ،","13:39":"وأنه به يتبرر كل من يؤمن من كل ما عجزت شريعة موسى أن تبرره منه.","13:40":"فاحذروا لئلا يحل بكم ما قيل في كتب الأنبياء:","13:41":"انظروا أيها المتهاونون، وتعجبوا واهلكوا! فإني أعمل في أيامكم عملا لو حدثكم به أحد لما صدقتم!»‍","13:42":"وفيما الحاضرون ينصرفون، طلبوا إلى بولس وبرنابا أن يعودا في السبت التالي ويحدثاهم بهذا الأمر.","13:43":"وتبعهما بعد الاجتماع كثيرون من اليهود والمتهودين العابدين، فأخذا يكلمانهم ويشجعانهم على الثبات في نعمة الله.","13:44":"وفي السبت التالي اجتمع أهل المدينة كلهم تقريبا ليسمعوا كلمة الله.","13:45":"فلما رأى اليهود الجموع ملأت الغيرة صدورهم، وأخذوا يعارضون كلام بولس مجدفين.","13:46":"فخاطبهم بولس وبرنابا بجرأة قائلين: «كان يجب أن نبلغكم أنتم أولا كلمة الله، ولكنكم رفضتموها فأظهرتم أنكم لا تستحقون الحياة الأبدية. وها نحن نتوجه إلى غير اليهود!","13:47":"فقد أوصانا الرب قائلا: قد جعلتك نورا للأمم، لتكون سبيل خلاص إلى أقصى الأرض!»","13:48":"فلما سمع غير اليهود ذلك، فرحوا جدا، ومجدوا كلمة الرب. وآمن جميع من أعدهم الله للحياة الأبدية.","13:49":"وهكذا انتشرت كلمة الرب في المنطقة كلها.","13:50":"ولكن اليهود حرضوا النساء النبيلات والمتعبدات ووجهاء المدينة، وأثاروا الاضطهاد على بولس وبرنابا، حتى طردوهما من بلدهم،","13:51":"فنفضا عليهم غبار أقدامهما وتوجها إلى مدينة إيقونية.","13:52":"أما التلاميذ، فقد امتلأوا من الفرح ومن الروح القدس.","14:1":"وفي إيقونية دخل بولس وبرنابا إلى المجمع اليهودي كعادتهما، وأخذا يتكلمان حتى آمن جمع كبير من اليهود واليونانيين.","14:2":"ولكن اليهود الذين لم يؤمنوا أثاروا غير اليهود على الإخوة، وأفسدوا عقولهم.","14:3":"إلا أن بولس وبرنابا بقيا هناك فترة طويلة يبشران بالرب بكل جرأة، وأيدهما الرب شاهدا لكلمة نعمته بما أجراه على أيديهما من آيات وعجائب.","14:4":"فانقسم أهل إيقونية فريقين: فمنهم من كان مع اليهود، ومنهم من كان مع الرسولين.","14:5":"ولما أوشك غير اليهود واليهود ورؤساؤهم أن يهينوا الرسولين ويرجموهما بالحجارة،","14:6":"علما بذلك فهربا إلى مدينتي لسترة ودربة الواقعتين في مقاطعة ليكأونية، وإلى المنطقة المحيطة بهما،","14:7":"وأخذا يبشران هناك.","14:8":"وكان يقيم في مدينة لسترة كسيح مقعد منذ ولادته لم يمش قط.","14:9":"فإذ كان يصغي إلى حديث بولس فرأى فيه إيمانا بأنه سيشفى،","14:10":"فناداه بأعلى صوته: «انهض واقفا على رجليك!» فقفز الرجل وبدأ يمشي.","14:11":"فلما رأى الحاضرون ما قام به بولس هتفوا باللغة الليكأونية: «اتخذ الآلهة صورة بشر ونزلوا بيننا!»","14:12":"ثم دعوا برنابا زفس وبولس هرمس، لأنه كان يدير الحديث.","14:13":"وكان عند مدخل المدينة معبد للصنم زفس، فجاء كاهنه على رأس جمع من المدينة، وهم يحملون أكاليل الزهور ويجرون الثيران ليقدموها ذبيحة لبولس وبرنابا.","14:14":"فلما سمع الرسولان بذلك مزقا ثيابهما، وأسرعا إلى المجتمعين","14:15":"وهما يصرخان: «لماذا تفعلون هذا أيها الناس؟ ما نحن إلا بشر ضعفاء مثلكم، نبشركم بأن ترجعوا عن هذه الأشياء الباطلة إلى الله الحي صانع السماء والأرض والبحر، وكل ما فيها،","14:16":"وقد ترك الأمم في العصور الماضية يسلكون في طرقهم،","14:17":"مع أنه لم يتركهم دون شاهد يدلهم عليه. فهو مازال ينعم عليكم بالخير، ويرزقكم من السماء أمطارا ومواسم مثمرة، ويشبعكم طعاما ويملأ قلوبكم سرورا».","14:18":"بهذا الكلام تمكنا بعد جهد من إقناع الجموع بعدم تقديم الذبائح لهما.","14:19":"بعد ذلك جاء بعض اليهود من أنطاكية وإيقونية، واستمالوا الجموع، فرجموا بولس حتى ظنوا أنه مات، وجروه إلى خارج المدينة.","14:20":"ولما أحاط به التلاميذ، قام وعاد إلى المدينة. وفي اليوم التالي سافر مع برنابا إلى دربة،","14:21":"وبشرا أهلها، فصار كثيرون منهم تلاميذ للرب. ثم رجعا إلى لسترة، ومنها إلى إيقونية، وأخيرا إلى أنطاكية.","14:22":"وفي هذه الأماكن كلها كانا يشددان عزيمة التلاميذ، ويحثانهم على الثبات في الإيمان، مؤكدين لهم أن دخول ملكوت الله يقتضي أن نقاسي صعوبات كثيرة.","14:23":"وعينا للتلاميذ شيوخا في كل كنيسة. ثم صليا بأصوام وأسلما الجميع وديعة بين يدي الرب الذي آمنوا به.","14:24":"ثم سافرا من مقاطعة بيسيدية، ووصلا إلى بمفيلية.","14:25":"وبشرا بكلمة الله في برجة، ثم سافرا إلى أتالية.","14:26":"ومن هناك عادا بحرا إلى مدينة أنطاكية، حيث كان المؤمنون قد أسلموهما إلى نعمة الله ليقوما بالعمل الذي قد أنجزاه.","14:27":"ولما وصلا، استدعيا الكنيسة إلى الاجتماع، وأخبرا بكل ما فعل الله بواسطتهما، وبأنه فتح باب الإيمان لغير اليهود.","14:28":"وأقاما مع التلاميذ هناك مدة طويلة.","15:1":"وجاء بعض اليهود (الذين كانوا قد آمنوا بالمسيح) من منطقة اليهودية إلى أنطاكية، وأخذوا يعلمون الإخوة قائلين: «لا يمكنكم أن تخلصوا ما لم تختنوا حسب شريعة موسى»","15:2":"فجادلهم بولس وبرنابا جدالا عنيفا. وبعد المناقشة قرر مؤمنو أنطاكية أن يذهب بولس وبرنابا مع بعض المؤمنين ليقابلوا الرسل والشيوخ في أورشليم، ويبحثوا معهم في هذه القضية.","15:3":"وبعدما ودعتهم الكنيسة، سافروا إلى أورشليم مرورا بمدن فينيقية والسامرة، مخبرين الإخوة فيها بأن غير اليهود أيضا قد اهتدوا إلى المسيح، فأشاعوا بذلك فرحا كبيرا بين الإخوة جميعا.","15:4":"ولما وصلوا إلى أورشليم، رحبت بهم الكنيسة بمن فيها من رسل وشيوخ، فأخبروهم بكل ما فعل الله بواسطتهم.","15:5":"ولكن بعض الذين كانوا على مذهب الفريسيين، ثم آمنوا، وقفوا وقالوا: «يجب أن يختن المؤمنون من غير اليهود ويلزموا أن يعملوا بشريعة موسى».","15:6":"فعقد الرسل والشيوخ اجتماعا لدراسة هذه القضية.","15:7":"وبعد نقاش كثير، وقف بطرس وقال:","15:8":"وقد شهد الله العليم بما في القلوب على قبوله لهم إذ وهبهم الروح القدس كما وهبنا إياه.","15:9":"فهو لم يفرق بيننا وبينهم في شيء، إذ طهر بالإيمان قلوبهم.","15:10":"فلماذا تعارضون الله فتحملون تلاميذ الرب عبئا ثقيلا عجز الآباء وعجزنا نحن عن حمله؟","15:11":"فنحن نؤمن بأننا نخلص، كما يخلصون هم، بنعمة الرب يسوع.","15:12":"»عندئذ توقف الجدال بين الحاضرين، وأخذوا يستمعون إلى برنابا وبولس وهما يخبرانهم بما أجراه الله بواسطتهما من علامات وعجائب بين غير اليهود.","15:13":"وبعد انتهائهما من الكلام، قال يعقوب:","15:14":"»استمعوا لي أيها الإخوة: أخبر كم سمعان كيف تفقد الله منذ البداية غير اليهود ليتخذ من بينهم شعبا يحمل اسمه؛","15:15":"وتوافق هذا أقوال الأنبياء، كما جاء في الكتاب.","15:16":"سأعود من بعد هذا وأبني خيمة داود المنهدمة ثم أقيم أنقاضها وأبنيها من جديد،","15:17":"لكي يسعى إلى الرب باقي الناس وجميع الشعوب التي تحمل اسمي، يقول الرب، فاعل هذه الأمور","15:18":"المعروفة لديه منذ الأزل.","15:19":"لذلك أرى أن لا نضع عبئا على المهتدين إلى الله من غير اليهود،","15:20":"بل نكتب إليهم رسالة نوصيهم فيها بأن يمتنعوا عن الأكل من الذبائح النجسة المقربة للأصنام، وعن ارتكاب الزنى، وعن تناول لحوم الحيوانات المخنوقة، وعن الدم.","15:21":"فإن لموسى، منذ القدم، أتباعا في كل مدينة، يقرأون شريعته ويبشرون بها في المجامع كل سبت».","15:22":"عند ذلك أجمع الرسل والشيوخ والجماعة كلها على اختيار رجلين من الإخوة يرسلونهما إلى أنطاكية مع بولس وبرنابا. فاختاروا يهوذا، الملقب برسابا، وسيلا، وكان لهما مكانة رفيعة بين الإخوة.","15:23":"وسلموهم هذه الرسالة:","15:24":"علمنا أن بعض الأشخاص ذهبوا من عندنا إليكم، دون تفويض منا فأثاروا بكلامهم الاضطراب بينكم وأقلقوا أفكاركم.","15:25":"،","15:26":"فأجمعنا برأي واحد على أن نختار رجلين قد كرسا حياتهما لاسم ربنا يسوع المسيح نرسلهما إليكم مع أخوينا الحبيبين برنابا وبولس.","15:27":"فأرسلنا يهوذا وسيلا، ليبلغاكم الرسالة نفسها شفاها.","15:28":"فقد رأى الروح القدس ونحن، أن لا نحملكم أي عبء فوق ما يتوجب عليكم.","15:29":"إنما عليكم أن تمتنعوا عن الأكل من الذبائح المقربة للأصنام، وعن تناول الدم ولحوم الحيوانات المخنوقة، وعن ارتكاب الزنى. وتحسنون عملا إن حفظتم أنفسكم من هذه الأمور. عافاكم الله !»","15:30":"فانطلق حاملو الرسالة، وسافروا إلى أنطاكية، حيث دعوا الجماعة إلى الاجتماع، وقدموا إليهم الرسالة.","15:31":"ولما قرأوها فرحوا بما فيها من تشجيع.","15:32":"وكان يهوذا وسيلا نبيين أيضا، فوعظا الإخوة كثيرا، وشددا عزيمتهم.","15:33":"وبعد مدة من الزمن صرفهما الإخوة في أنطاكية بسلام إلى الذين أرسلوهما.","15:34":"ولكن سيلا استحسن البقاء في أنطاكية، فعاد يهوذا وحده.","15:35":"وبقي هناك أيضا بولس وبرنابا يعلمان ويبشران بكلمة الرب، يعاونهما آخرون كثيرون.","15:36":"وبعد بضعة أيام قال بولس لبرنابا: «هيا نرجع لنتفقد الإخوة ونطلع على أحوالهم في كل مدينة بشرنا فيها بكلمة الرب».","15:37":"فاقترح برنابا أن يأخذا معهما يوحنا الملقب مرقس.","15:38":"ولكن بولس رفض أن يأخذاه معهما، لأنه كان قد فارقهما في بمفيلية، ولم يرافقهما في الخدمة.","15:39":"فوقعت بينهما مشاجرة حتى انفصل أحدهما عن الآخر. فأخذ برنابا مرقس وسافر بحرا إلى قبرص،","15:40":"واختار بولس أن يرافقه سيلا. فأسلمه الإخوة إلى نعمة الله،","15:41":"فسافر في مقاطعتي سورية وكيليكية يشدد الكنائس.","16:1":"ووصل بولس إلى دربة، ثم إلى لسترة، وكان فيها تلميذ اسمه تيموثاوس، أمه يهودية كانت قد آمنت بالمسيح، وأبوه يوناني.","16:2":"وكان الإخوة في لسترة وإيقونية يشهدون لتيموثاوس شهادة حسنة.","16:3":"فأحب بولس أن يصحبه في التبشير. ولأن يهود تلك المنطقة كانوا يعرفون أن أباه يوناني، فقد أخذه بولس وختنه.","16:4":"وأخذ بولس ورفاقه ينتقلون من مدينة إلى أخرى، يبلغون المؤمنين التوصيات التي أقرها الرسل والشيوخ في أورشليم، لكي يعملوا بها.","16:5":"فكانت الكنائس تتقوى في الإيمان، ويزداد عددها يوما بعد يوم.","16:6":"ومنعهم الروح القدس من التبشير في مقاطعة أسيا، فسافروا في مقاطعتي فريجية وغلاطية.","16:7":"ولما وصلوا حدود مقاطعة ميسيا، اتجهوا نحو مقاطعة بيثينية، ولكن روح يسوع لم يسمح لهم بالدخول إليها،","16:8":"فتوجهوا إلى مدينة ترواس مرورا بميسيا.","16:9":"وفي تلك الليلة رأى بولس في رؤيا رجلا من أهل مقدونية يتوسل إليه ويقول: «اعبر إلى مقدونية وأنجدنا!»","16:10":"عندئذ تأكدنا أن الرب دعانا للتبشير في مقدونية. فاتجهنا إليها في الحال.","16:11":"فأبحرنا من ميناء ترواس إلى جزيرة ساموثراكي. وفي اليوم التالي تابعنا السفر إلى ميناء نيابوليس،","16:12":"ومنها إلى مدينة فيلبي، وهي كبرى مدن مقاطعة مقدونية، ومستعمرة للرومان. فبقينا فيها بضعة أيام.","16:13":"وفي يوم السبت ذهبنا إلى ضفة نهر في إحدى ضواحي المدينة حيث جرت العادة أن تقام الصلاة. فجلسنا نكلم النساء المجتمعات،","16:14":"ومن بينهن تاجرة أرجوان من مدينة ثياتيرا، متعبدة لله، اسمها ليدية، كانت تسمع ففتح الله قلبها لتقبل كلام بولس.","16:15":"فلما تعمدت هي وأهل بيتها، دعتنا بإلحاح لقبول ضيافتها قائلة: «إن كنتم قد حكمتم أني مؤمنة بالرب، فانزلوا ضيوفا ببيتي». فاضطرتنا إلى قبول دعوتها.","16:16":"وذات يوم كنا ذاهبين إلى الصلاة، فالتقت بنا خادمة يسكنها روح عرافة، كانت تكسب سادتها ربحا كثيرا من عرافتها،","16:17":"فأخذت تسير وراء بولس ووراءنا صارخة: «هؤلاء الناس هم عبيد الله العلي، يعلنون لكم طريق الخلاص».","16:18":"وظلت تفعل هذا أياما كثيرة، حتى تضايق بولس كثيرا، فالتفت وقال للروح الذي فيها: «باسم يسوع المسيح، آمرك أن تخرج منها!» فخرج حالا.","16:19":"ولما رأى سادتها أن مورد رزقهم قد انقطع، قبضوا على بولس وسيلا، وجروهما إلى ساحة المدينة للمحاكمة،","16:20":"وقدموهما إلى الحكام قائلين: «هذان الرجلان يثيران الفوضى في المدينة؛ فهما يهوديان","16:21":"يناديان بتقاليد لا يجوز لنا نحن الرومانيين أن نقبلها أو نعمل بها!»","16:22":"فثار الجمع عليهما، ومزق الحكام ثيابهما وأمروا بجلدهما،","16:23":"فجلدوهما كثيرا وألقوهما في السجن، وأمروا ضابط السجن بتشديد الحراسة عليهما.","16:24":"ونفذ ضابط السجن هذا الأمر المشدد. فزج بهما في السجن الداخلي، وأدخل أرجلهما في مقطرة خشبية.","16:25":"ونحو منتصف الليل كان بولس وسيلا يصليان ويسبحان الله، والمسجونون يسمعونهما،","16:26":"وفجأة حدث زلزال شديد هز أركان السجن، فانفتحت جميع أبوابه حالا، وسقطت قيود السجناء كلهم.","16:27":"وأيقظ الزلزال ضابط السجن. فلما رأى الأبواب مفتوحة ظن أن السجناء هربوا، فاستل سيفه ليقتل نفسه،","16:28":"ولكن بولس صاح به بأعلى صوته: «لا تمس نفسك بسوء، فنحن جميعا هنا!»","16:29":"فطلب ضوءا، واندفع إلى الداخل وهو يرتجف خوفا، وارتمى أمام بولس وسيلا،","16:30":"ثم أخرجهما خارجا وسألهما: «ياسيدي، ماذا ينبغي أن أفعل لكي أخلص؟»","16:31":"فأجاباه: «آمن بالرب يسوع فتخلص أنت وأهل بيتك!»","16:32":"ثم بشراه وأهل بيته جميعا بكلمة الرب.","16:33":"فأخذهما في تلك الساعة من الليل وغسل جراحهما وتعمد حالا هو وأهل بيِته جميعا.","16:34":"ثم ذهب بهما إلى بيته وبسط لهما مائدة. وابتهج مع أهل بيته جميعا، إذ كان قد آمن بالله.","16:35":"ولما طلع الصباح أرسل الحكام بعض رجال الشرطة ليبلغوا ضابط السجن أمر الإفراج عن بولس وسيلا.","16:36":"فأخبر الضابط بولس بالأمر، قائلا: «أرسل الحكام أمرا بالإفراج عنكما فاخرجا الآن واذهبا بسلام!»","16:37":"فاحتج بولس قائلا: «جلدونا أمام الناس بغير محاكمة، مع أننا نحمل الجنسية الرومانية، وزجوا بنا في السجن. فكيف يطلقون سراحنا الآن سرا! كلا! بل ليأتوا هم ويطلقوا سراحنا!»","16:38":"وأخبر رجال الشرطة الحكام بهذا الاعتراض، فخافوا حين علموا أنهما رومانيان،","16:39":"فجاءوا يعتذرون إليهما، وأطلقوهما طالبين إليهما أن يغادرا المدينة.","16:40":"فخرج بولس وسيلا من السجن وتوجها إلى بيت ليدية، حيث قابلا الإخوة وشجعاهم، ثم غادرا المدينة.","17:1":"وصل بولس وسيلا إلى تسالونيكي بعدما مرا بأمفيبوليس وأبولونية. وكان في تسالونيكي مجمع لليهود.","17:2":"فذهب إليه كعادته، وناقشهم لثلاثة سبوت، مستندا إلى الكتاب،","17:3":"وشرح لهم مبينا أن المسيح كان لابد أن يتألم ويقوم من بين الأموات، وأن «المسيح الذي تنتظرونه هو يسوع الذي أبشركم به الآن!»","17:4":"فاقتنع بعض الحاضرين وانضموا إلى بولس وسيلا. وكان بينهم عدد كبير من اليونانيين المتعبدين لله وكثيرات من النساء النبيلات.","17:5":"فأثار ذلك حسد اليهود الذين لم يؤمنوا، فأتوا ببعض الأشرار من أبناء الشارع، وجمعوا جمهورا وأخذوا يحرضون الناس حتى أثاروا الفوضى في المدينة، ثم هجموا على بيت ياسون مطالبين بتسليم بولس وسيلا إلى الجمع.","17:6":"ولما لم يجدوهما هناك جروا ياسون وبعض الإخوة واقتادوهم إلى حكام المدينة، واشتكوا عليهم صارخين: «إن هذين الرجلين اللذين قلبا الدنيا ، قد جاءا إلى مدينتنا أيضا،","17:7":"فاستضافهما ياسون. وهم جميعا يخالفون أوامر القيصر، وينادون بملك آخر اسمه يسوع».","17:8":"فأحدثوا انزعاجا لدى الجمع والحكام عندما سمعوا هذا.","17:9":"فقبض الحكام كفالة من ياسون ومن معه ثم أفرجوا عنهم.","17:10":"وفي الليل رحل الإخوة بولس وسيلا حالا إلى بيرية. ولما وصلا إليها، ذهبا إلى مجمع اليهود فيها.","17:11":"وكان يهود بيرية أشرف من يهود تسالونيكي، فقبلوا كلمة الله برغبة شديدة، وأخذوا يدرسون الكتاب يوميا ليتأكدوا من صحة التعليم.","17:12":"فآمن عدد كبير منهم، كما آمن من اليونانيين نساء نبيلات وعدد كبير من الرجال.","17:13":"وعرف يهود تسالونيكي أن بولس يبشر بكلمة الله في بيرية، فلحقوا به وبدأوا يحرضون الجموع ليثوروا عليه.","17:14":"وفي الحال أخذ بعض الإخوة بولس نحو البحر ليسافر، وبقي سيلا وتيموثاوس هناك.","17:15":"ورافق الإخوة بولس حتى أوصلوه إلى أثينا، ثم رجعوا بعدما أوصاهم بولس بأن يلحق به سيلا وتيموثاوس بأسرع ما يمكن.","17:16":"وبينما كان بولس ينتظرهما في أثينا رأى المدينة مملوءة أصناما فتضايقت روحه.","17:17":"وأخذ يخاطب اليهود والمتعبدين في المجمع، ومن يلقاهم كل يوم في ساحة المدينة.","17:18":"وجرت مناقشة بينه وبين بعض الفلاسفة الأبيقوريين والرواقيين. ولما وجدوا أنه يبشر بيسوع والقيامة من الموت قال بعضهم: «ماذا يعني هذا المدعي الأحمق بكلامه؟» وقال آخرون: «يبدو أنه ينادي بآلهة غريبة».","17:19":"ثم قادوه إلى تلة أريوباغوس (حيث مجلس المدينة) وسألوه: «هل لنا أن نعرف ما هو المذهب الجديد الذي تنادي به؟","17:20":"إننا نسمع منك أقوالا غريبة نريد أن نعرف معناها».","17:21":"وكان أهل أثينا والأجانب الساكنون فيها لا يمضون أوقات فراغهم إلا في مناقشة الأفكار الجديدة.","17:22":"فوقف بولس في وسط الأريوباغوس، وقال:","17:23":"فبينما كنت أتجول في مدينتكم وأنظر إلى معابدكم وجدت معبدا مكتوبا عليه «إلى الإله المجهول». فبهذا الإله الذي تعبدونه ولا تعرفونه، أنا أبشركم.","17:24":"إنه الله الذي خلق الكون وكل ما فيه، وهو الذي لا يسكن في معابد بنتها أيدي البشر، لأنه رب السماء والأرض،","17:25":"وليس بحاجة إلى خدمة يقدمها له الناس. فإنه يهب جميع الخلق الحياة والنفس وكل شيء.","17:26":"وقد أخرج الشعوب جميعا من أصل واحد، وأسكنهم بلاد الأرض كلها، وحدد مسبقا أزمنة وجودهم وحدود أوطانهم،","17:27":"لكي يبحثوا عن الله لعلهم يتلمسونه فيهتدوا إليه! فإنه ليس بعيدا عن كل واحد منا،","17:28":"لأننا به نحيا ونتحرك ونوجد، أو كما قال بعض شعرائكم: نحن أيضا ذريته!","17:29":"فما دمنا ذرية الله، فيجب ألا ننظر إلى الألوهية كأنها صنم من ذهب أو فضة أو حجر يستطيع إنسان أن ينحته أو يصوغه كما يتخيل!","17:30":"فالله الآن يدعو جميع الناس في كل مكان أن يرجعوا إليه تائبين، وقد غض النظر عن أزمنة الجهل التي مرت،","17:31":"لأنه حدد يوما يدين فيه العالم بالعدل على يد رجل اختاره لذلك. وقد قدم للجميع برهانا، إذ أقامه من بين الأموات».","17:32":"وما إن سمع الحاضرون بالقيامة من بين الأموات حتى بدأ بعضهم يستهزئون. ولكن آخرين قالوا لبولس: «نود أن تحدثنا في هذا الموضوع ثانية».","17:33":"وهكذا خرج بولس من بينهم.","17:34":"ولكن بعضهم انضموا إلى بولس وآمنوا ومنهم ديونيسيوس، وكان عضوا في مجلس أريوباغوس، وامرأة اسمها داماريس، وآخرون غيرهما.","18:1":"بعد ذلك ترك بولس أثينا، وسافر إلى مدينة كورنثوس.","18:2":"فالتقى هناك بيهودي اسمه أكيلا، من مواليد بنطس، كان قد جاء حديثا مع زوجته بريسكلا من إيطالية، لأن القيصر كلوديوس أمر بطرد اليهود من روما، فقصد بولس إليهما.","18:3":"وإذ كان من أهل مهنتهما، وهي صناعة الخيام، أقام عندهما وكان يشتغل معهما.","18:4":"وكان في كل سبت يناقش الحاضرين في المجمع لإقناع اليهود واليونانيين.","18:5":"ولما وصل سيلا وتيموثاوس من مقاطعة مقدونية، تفرغ بولس تماما للتبشير، شاهدا لليهود أن يسوع هو المسيح.","18:6":"ولكنهم عارضوا شهادته وأخذوا يجدفون. فما كان منه إلا أن نفض ثوبه وقال لهم: «دمكم على رؤوسكم. أنا بريء! ومنذ الآن أتوجه لتبشير غير اليهود».","18:7":"ثم ترك بولس مكان إقامته، ونزل ضيفا ببيت رجل غير يهودي يتعبد لله، اسمه تيطس يوستس، كان بيته ملاصقا للمجمع.","18:8":"فآمن كريسبس رئيس المجمع بالرب، هو وأهل بيته جميعا. وسمع كثيرون من أهل كورنثوس تبشير بولس، فآمنوا وتعمدوا.","18:9":"وذات ليلة رأى بولس الرب في رؤيا يقول له: «لا تخف، بل تكلم ولا تسكت،","18:10":"فأنا معك، ولن يقدر أحد أن يؤذيك، لأن لي شعبا كثيرا في هذه المدينة».","18:11":"فبقي بولس في كورنثوس سنة وستة أشهر يعلم الناس كلمة الله.","18:12":"ولما كان الحاكم الروماني غاليون يتولى الحكم على بلاد أخائية، تجمع اليهود ضد بولس برأي واحد، وساقوه إلى المحكمة،","18:13":"واشتكوا عليه قائلين: «هذا الرجل يحاول إقناع الناس بأن يعبدوا الله بطريقة تخالف شريعتنا».","18:14":"وكاد بولس أن يبدأ دفاعه لولا أن غاليون قال لليهود: «أيها اليهود، لو كانت القضية جريمة أو ذنبا، لكنت أحتملكم كما يقضي العدل.","18:15":"ولكن مادامت القضية جدلا في ألفاظ وأسماء وفي شريعتكم، فعليكم أن تعالجوها بأنفسكم. أنا لا أريد أن أحكم في هذه القضايا!»","18:16":"ثم طردهم من المحكمة،","18:17":"فأخذوا سوستانيس رئيس المجمع وضربوه أمام المحكمة، ولكن غاليون لم يهمه شيء من ذلك!","18:18":"وبقي بولس في كورنثوس فترة طويلة، ثم ودع الإخوة وسافر بحرا متجها إلى سورية ومعه بريسكلا وأكيلا، بعدما حلق رأسه في مدينة كنخريا، إذ كان عليه نذر.","18:19":"فلما وصلوا إلى أفسس تركهما بولس فيها، ودخل مجمع اليهود وخطب فيهم.","18:20":"فطلبوا منه أن يقضي عندهم فترة أطول، فلم يقبل،","18:21":"وودعهم قائلا: «سأعود إليكم إن شاء الله !» ثم سافر بحرا من أفسس،","18:22":"ونزل في ميناء قيصرية فصعد وسلم على الكنيسة، ثم نزل إلى مدينة أنطاكية،","18:23":"فأمضى فيها بعض الوقت. ثم طاف مقاطعتي غلاطية وفريجية منتقلا من بلدة إلى أخرى وهو يشدد عزيمة التلاميذ جميعا.","18:24":"وجاء إلى أفسس يهودي اسمه أبلوس، إسكندري المولد، فصيح اللسان، خبير في الكتاب.","18:25":"كان قد تلقن طريق الرب. فبدأ يخطب بحماسة شديدة، ويعلم الحقائق المختصة بيسوع تعليما صحيحا. ومع أنه لم يكن يعرف سوى معمودية يوحنا،","18:26":"فقد أخذ يتكلم في المجمع بجرأة. فسمعه أكيلا وبريسكلا، فأخذاه إليهما وأوضحا له طريق الله بأكثر دقة.","18:27":"وقرر أبلوس أن يسافر إلى بلاد أخائية فشجعه الإخوة وكتبوا إلى التلاميذ هناك أن يرحبوا به. ولما وصل إلى هناك أعان الذين كانوا قد آمنوا إعانة كبرى بما له من النعمة:","18:28":"فقد كان جريئا في مجادلاته العلنية مع اليهود، وكان يفحمهم مستندا إلى الكتاب فيثبت أن يسوع هو المسيح.","19:1":"وبينما كان أبلوس في كورنثوس وصل بولس إلى أفسس، بعدما مر بالمناطق الداخلية من البلاد. وهناك وجد بعض التلاميذ،","19:2":"فسألهم: «هل نلتم الروح القدس عندما آمنتم؟» أجابوه: «لا! حتى إننا لم نسمع بوجود الروح القدس!»","19:3":"فسأل: «إذن على أي أساس قد تعمدتم؟» أجابوا: «على أساس معمودية يوحنا!»","19:4":"فقال بولس: «كان يوحنا يعمد بمعمودية التوبة، ويدعو الشعب إلى الإيمان بالآتي بعده، أي بيسوع».","19:5":"فلما سمعوا هذا تعمدوا باسم الرب يسوع.","19:6":"وما إن وضع بولس يديه عليهم حتى حل عليهم الروح القدس، وأخذوا يتكلمون بلغات أخرى ويتنبأون.","19:7":"وكان عددهم نحو اثني عشر رجلا.","19:8":"وأخذ بولس يداوم على الذهاب إلى المجمع مدة ثلاثة أشهر، يتكلم بجرأة فيناقش الحاضرين ويحاول إقناعهم بالحقائق المختصة بملكوت الله.","19:9":"ولكن بعضهم عاندوا ولم يقتنعوا، وأخذوا يشتمون الطريق أمام المجتمعين. فانفصل بولس عنهم، وانفرد بالتلاميذ، وبدأ يعقد مناقشات كل يوم في مدرسة رجل اسمه تيرانوس،","19:10":"وداوم على ذلك مدة سنتين. وهكذا وصلت كلمة الرب إلى جميع سكان مقاطعة أسيا من اليهود واليونانيين.","19:11":"وكان الله يجري معجزات خارقة على يد بولس،","19:12":"حتى صار الناس يأخذون المناديل أو المآزر التي مست جسده، ويضعونها على المرضى، فتزول أمراضهم وتخرج الأرواح الشريرة منهم.","19:13":"وحاول بعض اليهود الجوالين الذين يحترفون طرد الأرواح الشرير ة، أن يستغلوا اسم الرب يسوع، قائلين: «نطردك باسم يسوع الذي يبشر به بولس!»","19:14":"وكان بين هؤلاء سبعة أبناء لواحد من الكهنة اسمه سكاوا،","19:15":"فأجابهم الروح الشرير: «يسوع أنا أعرفه، وبولس أفهمه. ولكن، من أنتم؟»","19:16":"ثم هجم عليهم الرجل الذي به الروح الشرير، فتمكن منهم وغلبهم، فهربوا من البيت الذي كانوا فيه، عراة مجرحين.","19:17":"فانتشر خبر ذلك بين اليهود واليونانيين الساكنين في أفسس، فاستولت الرهبة على الجميع. وتمجد اسم الرب يسوع.","19:18":"فجاء كثيرون من الذين كانوا قد آمنوا يعترفون ويخبرون بما كانوا يعملون.","19:19":"وأخذ كثيرون من المشتغلين بالسحر يجمعون كتبهم ويحرقونها أمام الجميع. وقد حسب ثمنها، فتبين أنه خمسون ألف قطعة من الفضة.","19:20":"بهذه الصورة كانت كلمة الرب تنتشر وتقوى باقتدار.","19:21":"وبعد حدوث هذه الأمور، عزم بولس على السفر إلى أورشليم مرورا بمقاطعتي مقدونية وأخائية، قائلا: «لابد لي بعد إقامتي فيها من زيارة روما أيضا!»","19:22":"فأرسل إلى مقدونية اثنين من معاونيه، هما تيموثاوس وأرسطوس، وبقي مدة من الزمن في مقاطعة أسيا.","19:23":"في تلك المدة وقع اضطراب خطير في أفسس بسبب الطريق.","19:24":"فإن صائغا اسمه ديمتريوس كان يصنع نماذج فضية صغيرة لمعابد الإلهة أرطاميس، فيعود ذلك عليه وعلى عماله بربح وفير،","19:25":"دعا عماله وأهل مهنته، وقال لهم: «تعلمون أيها الرجال أن عيشنا الرغيد يعتمد على صناعتنا هذه،","19:26":"وقد رأيتم وسمعتم أن بولس هذا أضل عددا كبيرا من الناس، لا في أفسس وحدها، بل في مقاطعة أسيا كلها تقريبا، وأقنعهم بأن الآلهة التي تصنعها الأيدي ليست بآلهة.","19:27":"وهذا لا يهدد صناعتنا بالكساد وحسب، بل يعرض معبد أرطاميس إلهتنا العظمى لفقدان هيبته. فنخشى أن تتلاشى كرامتها وتنهار عظمتها، وهي التي يتعبد لها سكان أسيا جميعا، بل العالم كله!»","19:28":"فلما سمع العمال هذا الكلام تملكهم الغضب وبدأوا يصرخون: «عظيمة أرطاميس إلهة أهل أفسس!»","19:29":"وعم الاضطراب المدينة كلها. وهجم حشد كبير من الناس على غايوس وأرسترخس المقدونيين رفيقي بولس في السفر، وجروهما إلى ساحة الملعب.","19:30":"وأراد بولس أن يواجه الجمهور، ولكن التلاميذ منعوه من ذلك،","19:31":"كما أرسل إليه أصدقاؤه من وجهاء أسيا يرجون منه ألا يعرض نفسه لخطر الذهاب إلى الملعب،","19:32":"فقد كان الأمر مختلطا على الجمهور، بعضهم يصرخ بشيء، وبعضهم يصرخ بشيء آخر، حتى إن أكثرهم لم يكونوا يعرفون سبب تجمعهم.","19:33":"وكان بين الجمهور يهودي اسمه إسكندر، دفعه اليهود إلى الأمام، ودعاه بعضهم إلى الكلام. فأشار بيده يريد أن يلقي على الشعب كلمة دفاع.","19:34":"لكن المحتشدين عرفوا أنه يهودي، فأخذوا يهتفون معا هتافا واحدا ظلوا يرددونه نحو ساعتين: «عظيمة أرطاميس إلهة أهل أفسس!»","19:35":"أخيرا تمكن كاتب المدينة من تهدئة الحشود، وقال: «ياأهل أفسس، من ينكر أن أفسس هي المدينة الحارسة لهيكل أرطاميس الإلهة العظيمة، ولصنمها الذي هبط من السماء؟","19:36":"فلأنه لا خلاف في هذا الأمر، يجب أن تهدأوا ولا تفعلوا شيئا بتسرع.","19:37":"فقد أحضرتم هذين الرجلين، مع أنهما لم يسرقا المعبد ولم يشتما إلهتكم.","19:38":"أما إذا كان لديمتريوس وزملاء مهنته شكوى، فإن عندنا محاكم وقضاة. فليتقدموا بشكواهم إلى القضاة.","19:39":"وإذا كان لكم شكوى أخرى، فإن النظر فيها يتم في جلسة قانونية.","19:40":"أما الآن فكلنا معرضون للمحاكمة بتهمة افتعال الاضطراب، بسبب ما حدث اليوم، ونحن لا نملك حجة نبرر بها التجمع!»","19:41":"وبقوله هذا صرف المحتشدين.","20:1":"بعدما انتهى الاضطراب، دعا بولس التلاميذ وشجعهم، ثم ودعهم وسافر إلى مقاطعة مقدونية،","20:2":"وتجول فيها يعظ ويشجع التلاميذ في كل مكان. وأخيرا وصل إلى اليونان،","20:3":"وقضى فيها ثلاثة أشهر. وبينما كان يستعد للسفر بحرا إلى سورية، عرف أن اليهود يدبرون مؤامرة لقتله. فقرر أن يعود بطريق مقدونية.","20:4":"ورافقه في السفر سوباترس بن برس من بيرية؛ وأرسترخس وسكوندس من تسالونيكي؛ وغايوس وتيموثاوس من دربة، وتيخيكس وتروفيمس من مقاطعة أسيا.","20:5":"هؤلاء سبقونا مع بولس وانتظرونا في ترواس.","20:6":"وبعد عيد الفطير اليهودي سافرنا نحن من فيلبي، بطريق البحر، فوصلنا ترواس بعد خمسة أيام، فلحقنا بهم، وبقينا هناك سبعة أيام.","20:7":"وفي أول يوم من الأسبوع، إذ اجتمعنا لنكسر الخبز، أخذ بولس يعظ المجتمعين. ولما كان ينوي السفر في اليوم التالي، أطال وعظه إلى منتصف الليل.","20:8":"وكان اجتماعنا في غرفة بالطبقة العليا، وقد أشعلت فيها مصابيح كثيرة.","20:9":"وكان شاب اسمه أفتيخوس قد جلس على النافذة، فغلب عليه النوم العميق، وبولس ماض في حديثه الطويل، فسقط من الطبقة الثالثة وحمل ميتا.","20:10":"فنزل بولس وارتمى عليه، وطوقه بذراعيه وقال: «لا تقلقوا! ماتزال حياته فيه!»","20:11":"وبعدما صعد بولس وكسر الخبز وأكل، ثم تابع حديثه إلى الفجر، سافر برا (إلى أسوس).","20:12":"أما الشاب فجاءوا به حيا، فكان لهم في ذلك عزاء عظيم.","20:13":"وأما نحن فسبقنا بولس وتوجهنا إلى أسوس بطريق البحر، حيث انتظرنا وصوله حسب الخطة التي كان قد رسمها بأن يوافينا سيرا على قدميه.","20:14":"فلما لحق بنا، أصعدناه إلى السفينة، وأبحرنا إلى ميناء ميتيليني","20:15":"وتابعنا السفر فوصلنا في اليوم التالي أمام جزيرة خيوس. وفي اليوم الثالث مررنا بالقرب من جزيرة ساموس، ووصلنا ميليتس في اليوم الرابع.","20:16":"وكان بولس قد قرر أن يتجاوز أفسس في البحر لكي لا يتأخر في مقاطعة أسيا، فقد كان يريد السرعة لعله يتمكن من الوصول إلى أورشليم في يوم الخمسين.","20:17":"ومن ميليتس أرسل بولس إلى أفسس يستدعي شيوخ الكنيسة.","20:18":"فلما جاءوا إليه، قال لهم:","20:19":"فقد كنت أخدم الرب بكل تواضع، وبكثير من الدموع، وأنا أعاني المحن التي أصابتني بها مؤامرات اليهود.","20:20":"وما قصرت في شيء يمكن أن يعود عليكم بالفائدة إلا وكنت أعلنه لكم وأعلمكم به علنا ومن بيت إلى بيت.","20:21":"فكنت أحث اليهود واليونانيين على أن يتوبوا إلى الله ويؤمنوا بربنا يسوع.","20:22":"وأنا اليوم ذاهب إلى أورشليم، مدفوعا بالروح، ولا أعلم ماذا ينتظرني هناك.","20:23":"إلا أن الروح القدس كان يعلن لي في كل مدينة أذهب إليها أن السجن والمصاعب تنتظرني","20:24":"ولكني لا أحسب لحياتي أية قيمة، ما دمت أسعى إلى بلوغ غايتي وإتمام الخدمة التي كلفني إياها الرب يسوع: أن أشهد ببشارة نعمة الله.","20:25":"وأنا أعلم أنكم لن تروا وجهي بعد اليوم، أنتم الذين تجولت بينكم جميعا مبشرا بملكوت الله.","20:26":"لذلك أشهد لكم اليوم أني بريء من دمكم جميعا،","20:27":"لأني لم أمتنع عن إبلاغكم جميع مقاصد الله.","20:28":"فاسهروا إذن على أنفسكم وعلى جميع القطيع الذي عينكم بينه الروح القدس نظارا، لترعوا كنيسة الله التي اشتراها بدمه.","20:29":"فإني أعلم أنه بعد رحيلي سيندس بينكم ذئاب خاطفة، لا تشفق على القطيع.","20:30":"بل إن قوما منكم أنتم سيقومون ويعلمون تعاليم منحرفة، ليجروا التلاميذ وراءهم.","20:31":"لذلك كونوا متيقظين، وتذكروا أني، مدة ثلاث سنين، لم أتوقف ليلا ونهارا عن نصح كل واحد منكم وأنا أذرف الدموع.","20:32":"وا لآن أسلمكم إلى الله وإلى كلمة نعمته القادرة أن تبنيكم وتعطيكم ميراثا تشتركون فيه مع جميع المقدسين لله.","20:33":"ما اشتهيت يوما فضة ولا ذهبا ولا ثوبا من عند أحد.","20:34":"وأنتم تعلمون أني اشتغلت بيدي هاتين لأسد حاجاتي وحاجات مرافقي.","20:35":"وقد أظهرت لكم بوضوح كيف يجب أن نبذل الجهد لنساعد المحتاجين، متذكرين كلمات الرب يسوع، إذ قال: الغبطة في العطاء أكثر مما في الأخذ!»","20:36":"وبعد هذا الكلام ركع بولس معهم جميعا وصلى.","20:37":"وبكى الجميع كثيرا، وعانقوا بولس وقبلوه بحرارة.","20:38":"وقد حزنوا كثيرا، خاصة لأنه قال لهم إنهم لن يروا وجهه مرة أخرى. ثم رافقوه إلى السفينة مودعين.","21:1":"وبعدما انسلخنا عنهم، أبحرنا على خط مستقيم باتجاه كوس. وفي اليوم التالي وصلنا إلى جزيرة رودس، ومنها اتجهنا إلى ميناء باترا،","21:2":"حيث وجدنا سفينة مسافرة إلى ساحل فينيقية، فركبناها وأقلعنا.","21:3":"ولاحت لنا جزيرة قبرص فجاوزناها عن شمالنا، وتابعنا السفر باتجاه سورية، فوصلنا إلى ميناء صور ونزلنا فيها، لأن السفينة كانت ستفرغ حمولتها هناك.","21:4":"عندئذ بحثنا عن التلاميذ، وأقمنا عندهم سبعة أيام، وكانوا ينصحون بولس، بإلهام من الروح، ألا يصعد إلى أورشليم.","21:5":"وعندما انتهت مدة إقامتنا عندهم خرجنا لنكمل سفرنا، فرافقونا مع نسائهم وأولادهم إلى خارج المدينة مودعين. فركعنا على الشاطيء وصلينا،","21:6":"ثم ودعنا بعضنا بعضا، وركبنا السفينة، فعادوا هم إلى بيوتهم.","21:7":"وتابعنا السفر بحرا من صور إلى بتولمايس، فسلمنا على الإخوة هناك وقضينا معهم يوما واحدا.","21:8":"وفي اليوم التالي ذهبنا إلى مدينة قيصرية ونزلنا ضيوفا ببيت المبشر فيلبس، وهو واحد من المدبرين السبعة،","21:9":"وله أربع بنات عذارى كن يتنبأن.","21:10":"فبقينا عنده عدة أيام. وبينما نحن هناك جاءنا من منطقة اليهودية نبي اسمه أغابوس.","21:11":"فأخذ حزام بولس، وقيد نفسه رابطا يديه ورجليه وقال: «يقول الروح القدس إن صاحب هذا الحزام سيقيده اليهود هكذا في أورشليم، ويسلمونه إلى أيدي الأجانب».","21:12":"فلما سمعنا هذا بدأنا جميعا، نحن مرافقي بولس والمؤمنين من أهل البلدة، نرجو من بولس ألا يذهب إلى أورشليم،","21:13":"ولكنه قال لنا: «ما لكم تبكون وتحطمون قلبي؟ إني مستعد ليس فقط لأن أقيد في أورشليم، بل أيضا لأن أموت من أجل اسم الرب يسوع!»","21:14":"ولما لم نتمكن من إقناعه سكتنا، وقلنا: «فلتكن مشيئة الرب!»","21:15":"وبعد مدة تأهبنا للسفر واتجهنا إلى أورشليم","21:16":"بصحبة بعض التلاميذ من قيصرية، فأخذونا إلى بيت مناسون القبرصي، وهو تلميذ قديم، فنزلنا عليه ضيوفا.","21:17":"ولدى وصولنا إلى أورشليم، رحب بنا الإخوة فرحين.","21:18":"وفي اليوم التالي لوصولنا رافقنا بولس للاجتماع بيعقوب، وكان الشيوخ كلهم مجتمعين عنده.","21:19":"فسلم بولس عليهم وأخذ يخبرهم على التوالي بكل ما فعله الله بين غير اليهود بواسطة خدمته.","21:20":"فلما سمعوا أخباره مجدوا الله ، وقالوا له: «أنت ترى أيها الأخ أن الذين آمنوا بالرب من اليهود يعدون بالآلاف، وهم متحمسون للشريعة،","21:21":"وقد سمعوا بأنك تدعو اليهود الذين يسكنون بين الأجانب إلى الارتداد عن موسى، وتوصيهم بألا يختنوا أولادهم ولا يتبعوا العادات المتوارثة،","21:22":"فما العمل إذن، لأنهم لابد أن يسمعوا بقدومك؟","21:23":"فاعمل ما نقوله لك: عندنا أربعة رجال عليهم نذر،","21:24":"فخذهم إلى الهيكل وتطهر معهم، وادفع نفقة حلق رؤوسهم، فيعرف الجميع أن ما سمعوه عنك غير صحيح، وأنك تسلك مثلهم طريق العمل بالشريعة.","21:25":"أما المؤمنون الذين من غير اليهود، فقد أرسلنا إليهم رسالة نوصيهم فيها بأن يمتنعوا عن الأكل من الذبائح المقربة للأصنام، وعن تناول الدم، وعن الأكل من لحوم الحيوانات المخنوقة، وعن الزنى».","21:26":"وهكذا كان. ففي اليوم التالي أخذ بولس الرجال الأربعة؛ وبعدما تطهر معهم، دخل الهيكل لكي يسجل التاريخ الذي ينتهي فيه أسبوع التطهر، حتى تقدم عن كل واحد منهم التقدمة الواجبة.","21:27":"ولما كادت الأيام السبعة أن تنقضي، رأى بعض اليهود من مقاطعة أسيا بولس في الهيكل، فحرضوا الجمع كله، وقبضوا عليه،","21:28":"وهم يصرخون: «النجدة يابني إسرائيل! هذا هو الرجل الذي يدعو الناس في كل مكان إلى عقيدة تشكل خطرا على شعبنا وشريعتنا وعلى هذا المكان، حتى إنه أدخل اليونانيين إلى الهيكل ودنس هذا المكان المقدس!»","21:29":"فإنهم كانوا قد رأوا تروفيمس الأفسسي مع بولس في المدينة، فظنوا أنه أدخله معه إلى الهيكل.","21:30":"عندئذ هاج أهل المدينة جميعا، وهجم الناس على بولس وجروه إلى خارج الهيكل، ثم أغلقت الأبواب حالا.","21:31":"وبينما هم يحاولون أن يقتلوه سمع قائد الكتيبة الرومانية أن الاضطراب عم أورشليم كلها.","21:32":"فأخذ في الحال جماعة من الجنود وقواد المئات وحضر مسرعا. ولما رأى اليهود القائد وجنوده كفوا عن ضرب بولس.","21:33":"فاقترب القائد وألقى القبض عليه، وأمر جنوده أن يقيدوه بسلسلتين، وأخذ يسأل: «من هو، وماذا فعل؟»","21:34":"فأخذ بعضهم ينادون بشيء وبعضهم بشيء آخر. ولما لم يقدر أن يتبين حقيقة الأمر بسبب الهياج، أمر أن يؤخذ بولس إلى الثكنة.","21:35":"ولما وصل به الجنود إلى الدرج اضطروا أن يحملوه ليخلصوه من عنف المحتشدين.","21:36":"فقد كان جمهور المحتشدين يتبعونه صارخين: «ليعدم!»","21:37":"وقبل أن يدخل بولس إلى الثكنة قال للقائد باللغة اليونانية: «أيمكن أن أقول لك شيئا؟» فقال القائد: «أتتكلم اليونانية؟","21:38":"إذن لست أنت ذلك المصري الذي أحدث اضطرابا في المدينة منذ مدة، وتزعم أربعة آلاف رجل من القتلة خرج بهم إلى البرية!»","21:39":"فقال بولس: «إنما أنا يهودي من طرسوس، وهي مدينة مشهورة في مقاطعة كيليكية. فأرجو منك أن تسمح لي بأن أكلم الشعب».","21:40":"فأذن له القائد. ووقف بولس على الدرج، وأشار بيده إلى الشعب. فلما ساد السكوت، أخذ يخاطبهم باللغة العبرية، قائلا:","22:1":"»أيها الإخوة والآباء، اسمعوا الآن دفاعي عن نفسي».","22:2":"فلما سمعوه يخاطبهم باللغة العبرية ازدادوا هدوءا فقال:","22:3":"»أنا رجل يهودي، ولدت في طرسوس الواقعة في مقاطعة كيليكية، ولكني نشأت في هذه المدينة وتعلمت عند قدمي غمالائيل التربية الموافقة تماما لشريعة آبائنا. وكنت غيورا في أمور الله، مثلكم جميعا اليوم.","22:4":"فاضطهدت هذا الطريق حتى الموت، فكنت أعتقل أتباعه من الرجال والنساء، وأزج بهم في السجون.","22:5":"ويشهد رئيس الكهنة ومجلس الشيوخ على صدق كلامي هذا. فقد أخذت منهم رسائل إلى إخوانهم في دمشق ليعاونوني في القبض على الذين هناك، لأسوقهم إلى أورشليم فينالوا عقابهم.","22:6":"ولما وصلت إلى مقربة من دمشق، وكان الوقت نحو الظهر، أضاء حولي فجأة نور باهر،","22:7":"فوقعت على الأرض، وسمعت صوتا يقول لي: شاول، شاول، لماذا تضطهدني؟","22:8":"فأجبت: من أنت ياسيد؟ فقال: أنا يسوع الناصري الذي أنت تضطهده.","22:9":"وقد رأى مرافقي النور، ولكنهم لم يسمعوا صوت مخاطبي.","22:10":"فسألت: ماذا أفعل يارب؟ فأجابني الرب: قم وادخل دمشق، وهناك يقال لك ما يجب عليك أن تفعله.","22:11":"واقتادني مرافقي بيدي حتى أوصلوني إلى دمشق، لأني لم أكن أبصر بسبب شدة ذلك النور الباهر.","22:12":"وكان في دمشق رجل اسمه حنانيا، تقي كما تقضي الشريعة، يشهد له يهود دمشق جميعا شهادة حسنة.","22:13":"جاء إلي ووقف وقال: أيها الأخ شاول، أبصر. فعاد إلي بصري حالا، ورأيته أمامي،","22:14":"فقال: إله آبائنا اختارك مسبقا لتعرف إرادته، وترى البار وتسمع صوتا من فمه.","22:15":"فإنك ستكون شاهدا له، أمام جميع الناس، بما رأيت وسمعت.","22:16":"والآن لماذا تبطيء؟ قم تعمد واغتسل من خطايا ك، داعيا باسم الرب.","22:17":"بعد ذلك رجعت إلى أورشليم. وبينما كنت أصلي في الهيكل غبت عن الوعي،","22:18":"فرأيت الرب يقول لي: عجل واترك أورشليم بسرعة، لأن أهلها يرفضون أن تشهد لي فيها.","22:19":"فقلت: يارب، إنهم يعرفون أني كنت أبحث في المجامع عن المؤمنين بك، لأسجنهم وأجلدهم.","22:20":"وكنت حاضرا عندما قتل شهيدك استفانوس، وكنت راضيا بقتله، وحارسا لثياب قاتليه.","22:21":"ولكنه قال لي: اذهب ... سأرسلك بعيدا: إلى الأمم!»","22:22":"ظل المجتمعون يصغون حتى وصل بولس إلى ذكر الأمم، فصرخوا بقائد الكتيبة: «انزع هذا الرجل من الأرض! إنه لا يستحق الحياة!»","22:23":"ثم أخذوا يصيحون ويلوحون بثيابهم، ويذرون الغبار في الهواء.","22:24":"فأمر القائد جنوده أن يدخلوا بولس إلى الثكنة وأن يستجوبوه تحت جلد السياط ليعرف سبب الهتافات الصاخبة ضده.","22:25":"فلما ربطه الجنود ليجلدوه قال لقائد المئة الذي كان واقفا بقربه: «أيسمح لكم القانون بجلد مواطن روماني قبل محاكمته؟»","22:26":"فما إن سمع الضابط ذلك حتى ذهب إلى القائد وأخبره بالأمر، وقال: «أتعلم أية مخالفة كنا سنرتكب لو جلدنا هذا الرجل؟ إنه روماني الجنسية !»","22:27":"فذهب القائد بنفسه إلى بولس وسأله: «أأنت حقا روماني؟» فأجاب: «نعم!»","22:28":"فقال القائد: «أنا دفعت مبلغا كبيرا من المال لأحصل على الجنسية الرومانية». فقال بولس: «وأنا حاصل عليها بالولادة!»","22:29":"وفي الحال ابتعد عنه الجنود المكلفون باستجوابه تحت جلد السياط، ووقع الخوف في نفس القائد من عاقبة تقييده بالسلاسل، بعدما تحقق أنه روماني.","22:30":"وفي اليوم التالي أراد القائد أن ينظر في حقيقة التهمة التي وجهها اليهود إلى بولس، ففك قيوده، وأمر بإحضار رؤساء الكهنة وأعضاء المجلس اليهودي جميعا، واستدعى بولس وأوقفه أمامهم.","23:1":"فحدق بولس إلى المجلس، وقال: «أيها الإخوة، إني عشت لله بضمير صالح حتى هذا اليوم».","23:2":"فأمر حنانيا، رئيس الكهنة، واحدا من الواقفين لديه أن يضرب بولس على فمه،","23:3":"فقال له بولس: «ضربك الله ، ياحائط المقبرة المطلي بالكلس! كيف تجلس لتحاكمني وفقا للشريعة، ثم تخالف الشريعة فتأمر بضربي؟»","23:4":"فقال له الواقفون هناك: «أتشتم رئيس كهنة الله؟»","23:5":"فأجاب بولس: «لم أكن أعرف أيها الإخوة أنه رئيس كهنة فقد جاء في الكتاب: لا تشتم رئيس شعبك!»","23:6":"وإذ كان بولس يعلم أن بعض أعضاء المجلس من مذهب الصدوقيين، وبعضهم من مذهب الفريسيين، نادى في المجلس: «أيها الإخوة، أنا فريسي ابن فريسي، وإني أحاكم الآن لأنني أعتقد أن للموتى رجاء بالقيامة!»","23:7":"وهنا دب الخلاف بين الفريسيين والصدوقيين من أعضاء المجلس، فانقسم الحاضرون.","23:8":"فإن الصدوقيين ينكرون القيامة والملائكة والأرواح، أما الفريسيون فيقرون بها كلها.","23:9":"وعلا الصياح، فوقف بعض علماء الشريعة الموالين للفريسيين، يحتجون بحماسة، فقالوا: «لا نجد على هذا الرجل ذنبا، فلربما كلمه روح أو ملاك!»","23:10":"وتفاقم الخلاف حتى خاف القائد أن يشقوا بولس شقين، فأمر الجنود أن ينزلوا ويخطفوه من بينهم ويعيدوه إلى الثكنة.","23:11":"وفي الليلة التالية ظهر الرب لبولس وقال له: «تشجع، فكما أديت لي الشهادة في أورشليم، لابد أن تؤديها لي في روما أيضا».","23:12":"ولما طلع الصباح حاك بعض اليهود مؤامرة لقتل بولس، وحرموا على أنفسهم الطعام والشراب إلى أن يقتلوه.","23:13":"وكان عدد الذين حاكوا هذه المؤامرة نحو أربعين رجلا.","23:14":"وذهبوا إلى رؤساء الكهنة والشيوخ وقالوا: «حرام علينا الطعام والشراب حتى نقتل بولس.","23:15":"فاطلبوا من القائد بصفتكم أعضاء المجلس، أن يحضر بولس بحجة إعادة النظر في قضيته، ونحن مستعدون لاغتياله قبل وصوله إلى المجلس!»","23:16":"ولكن خبر هذه المؤامرة تسرب إلى ابن أخت بولس، فتوجه إلى الثكنة وأخبره بذلك.","23:17":"فاستدعى بولس أحد قواد المئات وطلب إليه أن يأخذ ابن أخته إلى القائد ليخبره بأمر هام.","23:18":"فأخذه إلى القائد وقال: «استدعاني السجين بولس وطلب أن أحضر هذا الشاب إليك، لأن عنده أمرا هاما يريد أن يخبرك به».","23:19":"فأمسك القائد الشاب بيده، وانفرد به، وسأله: «ما الأمر الذي تريد أن تخبرني به؟»","23:20":"فقال: «حاك اليهود مؤامرة على بولس، وسيطلبون منك أن تحضره إلى مجلسهم، بحجة إعادة النظر في قضيته،","23:21":"فلا تقبل طلبهم، لأن أكثر من أربعين رجلا منهم حرموا على أنفسهم الطعام والشراب ونصبوا كمينا لاغتياله، وهم الآن مستعدون لذلك، وينتظرون تلبية طلبهم!»","23:22":"فصرف القائد الشاب بعدما قال له: «لا تخبر أحدا بما أعلمتني به!»","23:23":"ودعا اثنين من قواد المئات لديه، وأمرهما قائلا: «جهزا مئتي جندي ليذهبوا إلى قيصرية الساعة التاسعة مساء الليلة ومعهم سبعون فارسا ومئتا حامل رمح،","23:24":"وبعض الدواب لتحمل بولس وتوصله سالما إلى الحاكم فيلكس».","23:25":"وكتب إلى الحاكم رسالة يقول فيها:","23:26":"»من كلوديوس ليسياس إلى سمو الحاكم فيلكس: سلام!","23:27":"هذا الرجل قبض عليه اليهود وحاولوا أن يقتلوه. وقد علمت أنه مواطن روماني فأسرعت إليه مع بعض الجنود وأنقذته.","23:28":"وأردت أن أعرف التهمة التي يتهمونه بها، فقدمته إلى مجلسهم،","23:29":"فتبين لي أن تهمته تختص بقضايا تتعلق بشريعتهم. ووجدت أنه لم يرتكب ذنبا يستحق عقوبة الموت أو السجن.","23:30":"ثم تبين لي أن جماعة من اليهود حاكوا مؤامرة لقتله، فأرسلته إليك بسرعة، وأمرت المدعين عليه أن يقدموا شكواهم لديك».","23:31":"وهكذا نقل الجنود بولس ليلا إلى أنتيباتريس، تنفيذا للأوامر الصادرة إليهم.","23:32":"وفي الصباح عادوا إلى الثكنة، وتركوا الفرسان يرافقون بولس إلى قيصرية.","23:33":"وهناك سلموه إلى الحاكم مع الرسالة.","23:34":"فقرأ الحاكم الرسالة، وسأل عن المقاطعة التي ينتمي بولس إليها. ولما علم أنه من كيليكية","23:35":"قال له: «سأنظر في قضيتك عندما يحضر المدعون عليك». وأمر بوضع بولس في قصر هيرودس، تحت الحراسة.","24:1":"وبعد خمسة أيام حضر إلى قيصرية وفد يضم حنانيا، رئيس الكهنة، وبعض الشيوخ، ومحاميا اسمه ترتلس، ليقدموا الدعوى للحاكم ضد بولس.","24:2":"فاستدعى الحاكم بولس، وبدأ ترتلس يوجه إليه الاتهام، فقال:","24:3":"ياسمو الحاكم فيلكس نرحب به، بجملته وفي كل مكان، بالشكر الجزيل.","24:4":"ولأني لا أريد أن أطيل الكلام عليك، أرجو أن تتلطف فتسمع عرضا موجزا لدعوانا:","24:5":"وجدنا هذا المتهم مخربا، يثير الفتنة بين جميع اليهود في البلاد كلها، وهو يتزعم مذهب النصارى.","24:6":"فلما حاول تدنيس هيكلنا أيضا، قبضنا عليه وأردنا أن نحاكمه بحسب شريعتنا.","24:7":"ولكن القائد ليسياس جاء وأخذه بالقوة من أيدينا،","24:8":"ثم أمر المدعين عليه بالترافع أمامك. وتستطيع الآن أن تتأكد من صحة دعوانا إذا قمت باستجوابه في هذا الأمر!»","24:9":"وأيد اليهود أعضاء الوفد ادعاء المحامي زاعمين أنه صحيح.","24:10":"وأشار الحاكم إلى بولس أن يقدم دفاعه، فقال: «أنا أعلم أنك تحكم في قضايا أمتنا منذ سنوات عديدة، ولذلك يسرني تقديم دفاعي عن نفسي بكل ارتياح.","24:11":"ويمكنك أن تتأكد أنه لم يمض على وصولي إلى أورشليم، للعبادة، أكثر من اثني عشر يوما.","24:12":"ولم يرني أحد من اليهود مرة واحدة في الهيكل أو المجامع أجادل أحدا أو أحرض الشعب على الفوضى.","24:13":"وهم لا يقدرون أن يثبتوا اتهامهم لي أمامك الآن.","24:14":"ولكني أعترف أمامك بأني أعبد إله آبائي بحسب المذهب الذي يصفونه بأنه بدعة، وأومن بكل ما كتب في الشريعة وكتب الأنبياء،","24:15":"ولي بالله ما لهم من رجاء ينتظرون تحقيقه: وهو أن القيامة ستحدث للأموات، الأبرار منهم والأشرار.","24:16":"لذلك أنا أيضا أدرب نفسي لكي أحيا دائما بضمير نقي أمام الله والناس.","24:17":"وبعد غياب عدة سنوات عن أورشليم، رجعت إليها أحمل بعض التبرعات إلى شعبي، وأقرب تقدمات.","24:18":"وبينما كنت أقوم بذلك، رآني في الهيكل بعض يهود مقاطعة أسيا، وكنت قد تطهرت. لم أكن وقتئذ وسط أي تجمع، ولا كنت أثير الفوضى.","24:19":"ولو كان عندهم دليل ضدي، لكانوا حضروا أمامك وشكوني حسب الأصول.","24:20":"والآن، ليذكر الحاضرون هنا الذنب الذي وجدوه علي عندما حاكموني أمام مجلسهم،","24:21":"غير ما أعلنته أمامهم حين قلت: أنتم تحاكمونني اليوم بسبب إيماني بقيامة الأموات».","24:22":"وكان فيلكس يعرف عن كثب أمور الطريق، فلما سمع دفاع بولس أرجأ إصدار الحكم، وقال للوفد المدعي: «سأحكم في دعواكم عندما يحضر القائد ليسياس».","24:23":"ثم أمر قائد المئة بوضع بولس تحت الحراسة، على أن تكون له بعض الحرية، وأن يسمح لأصدقائه بزيارته والقيام بخدمته.","24:24":"وبعد بضعة أيام جاء فيلكس ومعه زوجته دروسلا، وكانت يهودية، فاستدعى بولس واستمع إلى حديثه عن الإيمان بالمسيح يسوع.","24:25":"ولما تحدث بولس عن البر وضبط النفس والدينونة الآتية ارتعب فيلكس، وقال لبولس: «اذهب الآن، ومتى توفر لي الوقت أستدعيك ثانية».","24:26":"وكان فيلكس يأمل أن يدفع له بولس بعض المال ليطلقه، فأخذ يكثر من استدعائه والحديث معه.","24:27":"ومرت سنتان وبولس على هذه الحال. وأخيرا تعين بوركيوس فستوس حاكما خلفا لفيلكس. وإذ أراد فيلكس أن يكسب رضى اليهود ترك بولس في السجن.","25:1":"بعد ثلاثة أيام لتولي فستوس منصبه، ذهب من قيصرية إلى أورشليم.","25:2":"فجاءه رئيس الكهنة ووجهاء اليهود وعرضوا له دعواهم ضد بولس، وطلبوا منه","25:3":"بإلحاح أن يكرمهم بإحضار بولس إلى أورشليم. وكانوا قد نصبوا له كمينا على الطريق ليغتالوه.","25:4":"فأجابهم فستوس بأن بولس سيبقى محتجزا في قيصرية وأنه هو سيعود إليها بعد فترة قصيرة.","25:5":"وقال: «ليذهب معي أصحاب النفوذ منكم؛ فإن كان على هذا الرجل ذنب ما، فليتهموه به أمامي!»","25:6":"وقضى فستوس في أورشليم أياما لا تزيد على الثمانية أو العشرة، ثم عاد إلى قيصرية. وفي اليوم التالي لوصوله جلس على منصة القضاء، وأمر بإحضار بولس.","25:7":"فلما حضر اجتمع حوله اليهود الذين جاءوا من أورشليم، ووجهوا إليه تهما كثيرة وخطيرة عجزوا عن إثبات صحتها.","25:8":"فدافع بولس عن نفسه قائلا: «لم أرتكب ذنبا في حق شريعة اليهود، أو الهيكل، أو القيصر».","25:9":"ومع ذلك فقد أراد فستوس أن يكسب رضى اليهود، فسأل بولس: «هل تريد أن تذهب إلى أورشليم حيث تجري محاكمتك بحضوري على هذه التهم؟»","25:10":"فأجاب بولس: «أنا ماثل الآن في محكمة القيصر، وأمامها يجب أن تجري محاكمتي. لم أرتكب ذنبا في حق اليهود، وأنت تعلم هذا جيدا.","25:11":"ولو كنت ارتكبت جريمة أستحق عليها عقوبة الإعدام، لما كنت أهرب من الموت. ولكن مادامت تهم هؤلاء لي بلا أساس، فلا يحق لأحد أن يسلمني إليهم ليحاكموني. إني أستأنف دعواي إلى القيصر!»","25:12":"وتداول فستوس الأمر مع مستشاريه، ثم قال لبولس: «مادمت قد استأنفت دعواك إلى القيصر، فإلى القيصر تذهب!»","25:13":"وبعد بضعة أيام جاء الملك أغريباس و(أخته) برنيكي إلى قيصرية ليسلما على فستوس.","25:14":"ومكثا هناك أياما عديدة. فعرض فستوس على الملك قضية بولس قائلا: «هنا رجل تركه فيلكس سجينا.","25:15":"ولما ذهبت إلى أورشليم شكاه إلي رؤساء الكهنة والشيوخ، وطالبوا بإصدار الحكم عليه.","25:16":"فقلت لهم إنه ليس من عادة الرومان أن يصدروا حكما على أحد قبل أن يواجه الذين يتهمونه، لتتاح له فرصة الدفاع عن نفسه.","25:17":"فلما جاءوا إلى هنا أسرعت في اليوم التالي وعقدت جلسة للنظر في القضية، وأمرت بإحضار المتهم.","25:18":"فلما قابله متهموه لم يذكروا ذنبا واحدا مما كنت أتوقع أن يتهموه به،","25:19":"بل جادلوه في مسائل تختص بديانتهم وبرجل اسمه يسوع، مات وبولس يقول إنه حي!","25:20":"فحرت في الأمر، وعرضت على المتهم أن يذهب إلى أورشليم ويحاكم هناك،","25:21":"إلا أنه استأنف دعواه إلى جلالة القيصر ليحاكم في حضرته، فأمرت بحراسته حتى أرسله إلى القيصر».","25:22":"فقال أغريباس لفستوس: «أحب أن أسمع ما يقوله هذا الرجل». فأجاب: «غدا تسمعه».","25:23":"وفي اليوم التالي جاء أغريباس وبرنيكي، واستقبلا باحتفال باذخ، إذ دخلا قاعة الاستماع يحيط بهما القادة العسكريون ووجهاء المدينة. وأمر فستوس بإحضار بولس.","25:24":"فلما أحضر قال فستوس: «أيها الملك أغريباس، والسادة الحاضرون هنا جميعا: أمامكم هذا الرجل الذي شكاه إلي الشعب اليهودي كله في أورشليم وهم يصرخون أنه يجب ألا يبقى حيا","25:25":"وتبين لي أنه لم يفعل ما يستحق الإعدام. ولكنه استأنف دعواه إلى جلالة القيصر، فقررت أن أرسله إليه.","25:26":"ولكن ليس لي شيء أكيد أكتبه إلى جلالة القيصر بشأنه. لذلك أحضرته أمامكم جميعا، وخاصة أمامك أيها الملك أغريباس، حتى إذا تم النظر في قضيته أجد ما أكتبه.","25:27":"فمن غير المعقول، كما أرى، أن أرسل إلى القيصر سجينا دون تحديد التهم الموجهة إليه!»","26:1":"فقال أغريباس لبولس: «إننا نسمح لك بالدفاع عن نفسك». فأشار بولس بيده، وابتدأ دفاعه قائلا:","26:2":"«أيها الملك أغريباس، يسعدني أن أدافع عن نفسي في حضرتك، وأرد كل ما يتهمني به اليهود،","26:3":"وبخاصة لأنك تعرف تماما طقوسهم ومجادلاتهم. فألتمس أن تسمعني برحابة صدر.","26:4":"إن اليهود جميعا يعرفون نشأتي من البداية. فقد عشت بين شعبي في أورشليم منذ صغري.","26:5":"وماداموا يعرفونني من البداية، فلو أرادوا لشهدوا أنني كنت فريسيا، أي تابعا للمذهب الأكثر تشددا في ديانتنا.","26:6":"وأنا اليوم أحاكم لأن لي رجاء بأن يحقق الله ما وعد به آباءنا،","26:7":"ومازالت أسباط شعبنا الاثنا عشر تواظب على العبادة ليل نهار راجية تحقيقه. من أجل هذا الرجاء يتهمني اليهود، أيها الملك:","26:8":"لماذا لا تصدقون أن الله يقيم الأموات؟","26:9":"وكنت أعتقد أنه يجب أن أبذل غاية جهدي لأقاوم اسم يسوع الناصري.","26:10":"وقد عملت على تنفيذ خطتي في أورشليم بتفويض خاص من رؤساء الكهنة، فألقيت في السجن عددا كبيرا من القديسين. وكنت أعطي صوتي بالموافقة عندما كان المجلس يحكم بإعدامهم.","26:11":"وكم عذبتهم في المجامع كلها لأجبرهم على التجديف. وقد بلغ حقدي عليهم درجة جعلتني أطاردهم في المدن التي في خارج البلاد.","26:12":"وتوجهت إلى مدينة دمشق بتفويض وترخيص من رؤساء الكهنة،","26:13":"فرأيت، أيها الملك، على الطريق عند الظهر نورا يفوق نور الشمس يسطع حولي وحول مرافقي،","26:14":"فسقطنا كلنا على الأرض. وسمعت صوتا يناديني باللغة العبرية قائلا: شاول، شاول، لماذا تضطهدني؟ يصعب عليك أن ترفس المناخس.","26:15":"فسألت: من أنت ياسيد؟ فأجاب: أنا يسوع الذي أنت تضطهده.","26:16":"انهض وقف على قدميك، فقد ظهرت لك لأعينك خادما لي وشاهدا بهذه الرؤيا التي تراني فيها الآن، وبالرؤى التي ستراني فيها بعد اليوم.","26:17":"وسأنقذك من شعبك ومن الأمم التي أرسلك إليها الآن،","26:18":"لتفتح عيونهم كي يرجعوا من الظلام إلى النور، ومن سيطرة الشيطان إلى الله، فينالوا غفران الخطايا ونصيبا بين الذين تقدسوا بالإيمان بي.","26:19":"ومن ذلك الحين لم أعاند الرؤيا السماوية، أيها الملك أغريباس.","26:20":"فبشرت أهل دمشق أولا، ثم أهل أورشليم ومنطقة اليهودية كلها، ثم الأجانب. فدعوت الجميع إلى التوبة والرجوع إلى الله، والقيام بأعمال تليق بالتوبة.","26:21":"وبسبب تبشيري قبض اليهود علي في الهيكل وحاولوا أن يقتلوني،","26:22":"ولكن الله حفظني حتى هذا اليوم، وبمعونته أقف أمام البسطاء والعظماء شاهدا له ولست أحيد عما تنبأ به موسى والأنبياء،","26:23":"من أن المسيح سيتألم فيكون أول من يقوم من بين الأموات، ويبشر بالنور شعبنا والشعوب الأخرى».","26:24":"وما إن وصل بولس في دفاعه إلى هذا الحد، حتى قاطعه فستوس قائلا بصوت عال: «جننت يابولس! إن تبحرك في العلم أصابك بالجنون!»","26:25":"فقال بولس: «لست مجنونا ياسمو الحاكم فستوس، فأنا أنطق بكلام الحق والصواب.","26:26":"والملك الذي أخاطبه الآن صراحة يعرف هذه الأمور التي أتحدث عنها، وأنا متأكد أنه لا يخفى عليه شيء منها، لأنها لم تحدث في زاوية مظلمة!","26:27":"أيها الملك أغريباس، أتصدق أقوال الأنبياء؟ أنا أعلم أنك تصدقها!»","26:28":"فأجاب أغريباس: «قليلا بعد، وتقنعني بأن أصير مسيحيا!»","26:29":"فقال بولس: «سواء كان قليلا أم كثيرا، فإن صلاتي إلى الله لأجلك ولأجل الحاضرين هنا جميعا أن تصيروا مثلي، ولكن دون هذه السلاسل!»","26:30":"بعد ذلك قام الملك والحاكم وبرنيكي والحاضرون","26:31":"وتركوا القاعة، وهم يقولون بعضهم لبعض: «لم يرتكب هذا الرجل ما يستحق الموت أو السجن».","26:32":"وقال أغريباس لفستوس: «لو لم يستأنف هذا الرجل دعواه إلى القيصر لكان يمكن إطلاقه!»","27:1":"وأخيرا تقرر أن نسافر إلى إيطاليا بحرا، فتولى حراسة بولس وبعض السجناء الآخرين قائد مئة اسمه يوليوس، ينتمي إلى كتيبة أوغسطس.","27:2":"فركبنا سفينة قادمة من أدراميت، متجهة إلى موانيء مقاطعة أسيا. ورافقنا في الرحلة أرسترخس من مدينة تسالونيكي في مقاطعة مقدونية.","27:3":"وفي اليوم التالي وصلنا إلى صيدا. وعامل يوليوس بولس معاملة طيبة فسمح له بأن يزور أصدقاءه في صيدا ليتلقى منهم ما يحتاج إليه.","27:4":"وأقلعنا من ميناء صيدا، وسافرنا بمحاذاة شواطيء قبرص، لأن الريح كانت عكس اتجاه سيرنا.","27:5":"وعبرنا البحر المجاور لمقاطعتي كيليكية وبمفيلية، ووصلنا إلى ميناء ميرا في مقاطعة ليكية.","27:6":"وهناك وجد قائد المئة سفينة قادمة من الإسكندرية متجهة إلى إيطاليا، فأصعدنا إليها.","27:7":"وسافرت السفينة على مهل لعدة أيام، واقتربنا من شاطيء كنيدس بعد جهد، ولكن الريح منعتنا من دخول الميناء فلم نقدر أن ننزل هناك، فسافرنا على مقربة من شاطيء جزيرة كريت، مرورا بالقرب من رأس سلموني.","27:8":"وبعد جهد وصلنا إلى مكان يدعى الموانيء الجميلة بالقرب من مدينة لسائية.","27:9":"وقضينا هناك مدة طويلة، حتى مضى الصيف وأصبح السفر في البحر خطرا إذ كان الصوم أيضا قد مضى، فنصح بولس بحارة السفينة","27:10":"قائلا: «أيها الرجال، أرى في سفرنا الآن خطرا وخسارة عظيمة، لا على السفينة وحمولتها فقط، بل على حياتنا أيضا».","27:11":"على أن قائد المئة كان يميل إلى كلام ربان السفينة وصاحبها، لا إلى كلام بولس.","27:12":"ولما لم تكن الميناء صالحة لقضاء فصل الشتاء، فقد قرر معظم البحارة أن يغادروها، آملين الوصول إلى ميناء فينكس لقضاء الشتاء فيها، وقد كانت هذه الميناء في كريت تواجه الجنوب والشمال الغربيين.","27:13":"وهبت ريح خفيفة من الجنوب، فظن البحارة أنها ستدفعهم نحو فينكس، فرفعوا المرساة وأبحروا على مقربة من شاطيء كريت.","27:14":"ولكن ريحا عاصفة تعرف بالشمالية الشرقية هبت بعد قليل،","27:15":"فاندفعت السفينة ولم تقو على مقاومة الريح، فاستسلمنا. وحملتنا العاصفة","27:16":"إلى مكان قريب من جزير ة صغيرة اسمها كودا. وبعد جهد استطعنا أن نرفع قارب النجاة إلى ظهر السفينة.","27:17":"ثم أسرع البحارة باتخاذ الاحتياطات الضرورية، فشدوا وسط السفينة بالحبال. وخوفا من الانجراف إلى شواطيء الرمال المتحركة، أنزلوا الأشرعة والحبال، فأصبحت الريح تدفع السفينة.","27:18":"وفي اليوم الثاني اشتدت علينا العاصفة، فأخذوا يخففون من الحمولة.","27:19":"وفي اليوم الثالث رموا أثاث السفينة بأيديهم.","27:20":"وكانت العاصفة تشتد يوما بعد يوم، حتى إننا لم نر الشمس ولا النجوم عدة أيام، فانقطع كل أمل في النجاة.","27:21":"وكان المسافرون قد امتنعوا مدة طويلة عن تناول الطعام، فتقدم بولس إليهم وقال: «أيها الرجال، كان يجب أن تسمعوا كلامي ولا تقلعوا من كريت، فتسلموا من هذا الخطر والخسارة.","27:22":"ولكني الآن أدعوكم لتطمئنوا، فلن يفقد أحد منكم حياته. ولكن السفينة وحدها ستتحطم.","27:23":"فقد ظهر لي هذه الليلة ملاك من عند الله الذي أنا له وإياه أخدم،","27:24":"وقال لي: لا تخف يابولس! فلابد أن تمثل أمام القيصر. وقد وهبك الله حياة جميع المسافرين معك!","27:25":"فاطمئنوا أيها الرجال، لأني أومن بالله وبأن ما قاله لي سيتم.","27:26":"ولكن لابد أن تجنح السفينة إلى إحدى الجزر».","27:27":"وفي منتصف الليلة الرابعة عشرة، والرياح تحملنا في بحر أدريا إلى حيث لا ندري، ظن البحارة أنهم يقتربون إلى البر.","27:28":"فقاسوا عمق المياه فوجدوه عشرين قامة. وبعد قليل قاسوا العمق فوجدوه خمس عشرة قامة.","27:29":"وخافوا أن تجنح السفينة إلى الصخور، فألقوا من مؤخرها أربع مراس، منتظرين طلوع الصباح.","27:30":"وحاول البحارة أن يهربوا من السفينة، فأنزلوا قارب النجاة بحجة أنهم سيلقون المراسي من مقدم السفينة.","27:31":"فقال بولس لقائد المئة والجنود: «إذا لم يبق هؤلاء البحارة في السفينة فلن تنجوا».","27:32":"فقطع الجنود حبال القارب وتركوه يسقط في الماء.","27:33":"ولما اقترب طلوع الصباح، طلب بولس إلى الجميع أن يأكلوا، وقال: «مرت أربعة عشر يوما وأنتم لا تأكلون شيئا،","27:34":"فأدعوكم إلى تناول الطعام، لأنه يساعدكم على النجاة. فلن يفقد أحد منكم شعرة من رأسه».","27:35":"ثم أخذ رغيفا، وشكر الله أمام الجميع، وكسره وابتدأ يأكل،","27:36":"فاطمأنوا كلهم وأكلوا.","27:37":"وكان عددنا في السفينة مئتين وستة وسبعين نفسا.","27:38":"وبعدما شبعوا رموا بالقمح في البحر ليخففوا حمولة السفينة.","27:39":"ولما طلع النهار، لم يستطع البحارة أن يميزوا المكان، ولكنهم أبصروا خليجا له شاطيء، فقرروا أن يدفعوا السفينة إليه، إذا استطاعوا،","27:40":"فقطعوا المراسي وتركوها تغرق، وحلوا الحبال التي تربط الدفة، ورفعوا الشراع الأمامي للريح، واتجهوا نحو الشاطيء.","27:41":"ولكن السفينة وصلت إلى مكان قليل المياه بين تيارين، فجنحوا بها إلى الشاطيء، فارتكز مقدمها وظل لا يتحرك، في حين أخذ مؤخرها يتفكك من عنف الأمواج.","27:42":"وارتأى الجنود أن يقتلوا السجناء حتى لا يسبح أحد منهم إلى الشاطيء ويهرب،","27:43":"ولكن قائد المئة كان يرغب في إنقاذ بولس، فمنع جنوده من تنفيذ رأيهم، وأمر القادرين على السباحة أن يسبحوا إلى الشاطيء قبل غيرهم،","27:44":"والباقين أن يحاولوا الوصول إليه على ألواح السفينة، أو على قطع من حطامها. وهكذا وصل الجميع إلى البر سالمين.","28:1":"وعرفنا بعدما نجونا أن الشاطيء الذي وصلناه هو جزيرة مالطة.","28:2":"واستقبلنا أهلها الغرباء بعطف كبير قل نظيره. فإذ كان المطر ينهمر والجو باردا، أوقدوا لنا نارا، ورحبوا بنا.","28:3":"وجمع بولس بعض الحطب وألقاه في النار، فخرجت أفعى، دفعتها الحرارة، وتعلقت بيده.","28:4":"ورأى أهل مالطة الأفعى عالقة بيده، فقال بعضهم لبعض: «لابد أن هذا الرجل قاتل، فإن العدل لم يدعه يحيا بعدما نجا من البحر».","28:5":"ولكن بولس نفض الأفعى في النار دون أن يمسه أذى.","28:6":"وانتظروا أن يتورم جسمه أو يقع ميتا فجأة. وطال انتظارهم، دون أن يصيبه ضرر، فغيروا رأيهم فيه وقالوا: «إنه إله!»","28:7":"وكانت بالقرب من المكان مزارع لحاكم الجزيرة بوبليوس، فدعانا وأحسن ضيافتنا ثلاثة أيام.","28:8":"وكان والد بوبليوس طريح الفراش مريضا بالحمى والإسهال الشديد. فزاره بولس وصلى، ووضع يديه عليه، فشفاه.","28:9":"فجاء عندئذ مرضى الجزيرة إليه ونالوا الشفاء،","28:10":"فأعطونا هدايا كثيرة، وزودونا عند رحيلنا بما نحتاج إليه في سفرنا.","28:11":"وبعد ثلاثة أشهر أقلعنا على سفينة من الإسكندرية، تحمل صورة الجوزاء (أي التوأمين)، كانت قد قضت فصل الشتاء في مالطة.","28:12":"فلما وصلنا إلى مدينة سراكوسا قضينا فيها ثلاثة أيام،","28:13":"ثم أبحرنا وسرنا على مقربة من الشاطيء حتى وصلنا مدينة ريغيون. وفي اليوم التالي هبت ريح جنوبية، فوصلنا إلى مدينة بوطيولي في يومين.","28:14":"ووجدنا هناك بعض الإخوة، فطلبوا إلينا أن نقضي معهم سبعة أيام. وهكذا وصلنا إلى روما.","28:15":"ولما سمع الإخوة فيها بوصولنا، خرجوا لاستقبالنا في ساحة أبيوس وفي الخانات الثلاثة. فلما رآهم بولس شكر الله وتشجع.","28:16":"ولما دخلنا روما سمح الضابط لبولس أن يقيم في منزل خاص مع الجندي الذي يحرسه.","28:17":"وبعد ثلاثة أيام دعا بولس وجهاء اليهود، وقال لهم: «أيها الإخوة، مع أني لم أفعل ما يسيء إلى الشعب، ولا إلى طقوس آبائنا، فقد سجنت في أورشليم وسلمت إلى الرومان،","28:18":"فاستجوبوني وأرادوا إطلاقي، لأنه لم يكن هناك ما يستوجب إعدامي.","28:19":"غير أن اليهود اعترضوا، فاضطررت إلى استئناف دعواي إلى القيصر. وهذا لا يعني أنني أشكو بني وطني بشيء.","28:20":"لذلك طلبت أن أراكم وأكلمكم؛ فأنا موثق بهذه السلسلة من أجل رجاء إسرائيل».","28:21":"فقالوا: «لم نتلق بشأنك أية رسالة من بلاد اليهودية، ولا جاء رسول من عند إخواننا يخبرنا عنك بشيء، أو يشتكي عليك.","28:22":"ولكننا نرى من المناسب أن نسمع رأيك، لأننا نعلم أن الناس في كل مكان يعارضون هذا المذهب!»","28:23":"فحددوا موعدا للقاء قادم، جاءوا فيه مع كثيرين إلى منزل بولس. فشهد لهم من الصباح إلى المساء شارحا لهم أمور ملكوت الله ومحاولا إقناعهم بالأمور المختصة بيسوع استنادا إلى شريعة موسى وكتب الأنبياء.","28:24":"فمنهم من اقتنع بكلامه، ومنهم من لم يؤمن.","28:25":"فاختلفوا فيما بينهم، وانصرفوا بعدما قال لهم: «صدق الروح القدس إذ قال لآبائكم بلسان النبي إشعياء:","28:26":"اذهب إلى هذا الشعب وقل له: سمعا ستسمعون، ولكنكم لا تفهمون! ونظرا ستنظرون، ولكنكم لا تبصرون!","28:27":"لأن قلب هذا الشعب قد صار غليظا، وآذانهم قد صارت ثقيلة السمع، وقد أغمضوا عيونهم. لئلا يبصروا بعيونهم، ويسمعوا بآذانهم، ويفهموا بقلوبهم، ويرجعوا إلي فأشفيهم!»","28:28":"وختم بولس كلامه بقوله: «اعلموا إذن أن الله قد أرسل خلاصه هذا إلى الأمم الأخرى، وهم سيستمعون إليه!»","28:29":"فلما قال هذا الكلام، خرج اليهود من عنده وهم يتجادلون بعنف.","28:30":"وأقام بولس سنتين كاملتين في المنزل الذي استأجره، وكان يرحب بجميع الذين يأتون لزيارته،","28:31":"مبشرا بملكوت الله، ومعلما الأمور المختصة بالرب يسوع المسيح بكل جرأة وبلا عائق."},"Rom":{"1:1":"من بولس عبد يسوع المسيح، الرسول المدعو والمفرز لإنجيل الله،","1:2":"هذا الإنجيل الذي وعد الله به من قبل على ألسنة أنبيائه في الكتب المقدسة،","1:3":"وهو يختص بابنه الذي جاء من نسل داود من الناحية البشرية؛","1:4":"ومن ناحية روح القداسة، تبين بقوة أنه ابن الله بالقيامة من بين الأموات. إنه يسوع المسيح ربنا","1:5":"الذي به ولأجل اسمه نلنا نعمة ورسالة لإطاعة الإيمان بين جميع الأمم،","1:6":"ومن بينهم أنتم أيضا مدعوو يسوع المسيح…","1:7":"إلى جميع من هم في روما من أحباء الله القديسين المدعوين. لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح!","1:8":"بادىء بدء، أشكر إلهي بيسوع المسيح من أجلكم جميعا، لأن إيمانكم يذاع خبره في العالم كله.","1:9":"فإن الله الذي أخدمه بروحي في التبشير بإنجيل ابنه، هو شاهد لي كيف لا أتوقف عن ذكركم","1:10":"في صلواتي، متوسلا دائما عسى الآن أن يتيسر لي مرة بمشيئة الله أن آتي إليكم.","1:11":"فإني أشتاق أن أراكم لأحمل إليكم موهبة روحية لتثبيتكم،","1:12":"أي ليشجع بعضنا بعضا بالإيمان المشترك، إيمانكم وإيماني.","1:13":"ثم لا أريد أن يخفى عليكم، أيها الإخوة، أنني كثيرا ما قصدت أن آتي إليكم، ليكون لي ثمر من بينكم أيضا كما لي من بين الأمم الأخرى، إلا أنني كنت أعاق حتى الآن","1:14":"فإن علي دينا لليونانيين والبرابرة، للمتعلمين والجهال.","1:15":"ولذلك، فبكل ما لدي، أنا في غاية الشوق أن أبشر بالإنجيل أيضا بينكم أنتم الذين في روما.","1:16":"فأنا لا أستحي بالإنجيل، لأنه قدرة الله للخلاص، لكل من يؤمن، لليهودي أولا ثم لليوناني على السواء.","1:17":"ففيه قد أعلن البر الذي يمنحه الله على أساس الإيمان والذي يؤدي إلى الإيمان، على حد ما قد كتب: «أما من تبرر بالإيمان، فبالإيمان يحيا».","1:18":"فإنه قد أعلن غضب الله من السماء على جميع ما يفعله الناس من عصيان وإثم فيحجبون الحق بالإثم.","1:19":"ذلك لأن ما يعرف عن الله واضح بينهم، إذ بينه الله لهم.","1:20":"فإن ما لا يرى من أمور الله، أي قدرته الأزلية وألوهته، ظاهر للعيان منذ خلق العالم، إذ تدركه العقول من خلال المخلوقات. حتى إن الناس باتوا بلا عذر.","1:21":"فمع أنهم عرفوا الله ، لم يمجدوه باعتباره الله ، ولا شكروه، بل انحطوا بتفكيرهم إلى الحماقة وصار قلبهم لغباوته مظلما.","1:22":"وفيما يدعون أنهم حكماء، صاروا جهالا،","1:23":"واستبدلوا بمجد الله الخالد تماثيل لصور الإنسان الفاني والطيور وذوات الأربع والزواحف.","1:24":"لذلك أسلمهم الله ، في شهوات قلوبهم، إلى النجاسة، ليهينوا أجسادهم فيما بينهم.","1:25":"إذ قد استبدلوا بحق الله ما هو باطل، فاتقوا المخلوق وعبدوه بدل الخالق، المبارك إلى الأبد. آمين!","1:26":"لهذا السبب أسلمهم الله إلى الشهوات المخزية. فإن إناثهم تحولن عن استعمال أجسادهن بالطريقة الطبيعية إلى استعمالها بطريقة مخالفة للطبيعة.","1:27":"وكذلك تحول الذكور أيضا عن استعمال الأنثى بالطريقة الطبيعية، والتهبوا شهوة بعضهم لبعض، مرتكبين الفحشاء ذكورا بذكور، فاستحقوا أن ينالوا في أنفسهم الجزاء العادل على ضلالهم.","1:28":"وبما أنهم لم يتخيروا إبقاء الله ضمن معرفتهم، أسلمهم الله إلى ذهن عاطل عن التمييز دفعهم إلى ممارسة الأمور غير اللائقة.","1:29":"إذ قد امتلأوا من كل إثم وشر وجشع وخبث، وشحنوا حسدا وقتلا وخصاما ومكرا وسوءا. وهم ثرثارون،","1:30":"مغتابون، كارهون لله، شتامون، متكبرون، متفاخرون، مخترعون للشرور، غير طائعين للوالدين.","1:31":"لا فهم عندهم، ولا أمانة، ولا حنان، ولا رحمة.","1:32":"إنهم يعلمون حكم الله العادل: أن الذين يفعلون هذه الأمور يستوجبون الموت؛ ومع ذلك، لا يمارسونها وحسب، بل يسرون بفاعليها.","2:1":"إذن، لا عذر لك أيها الإنسان الذي يدين الآخرين، كائنا من كنت. فإنك بما تدين غيرك، تدين نفسك: لأنك أنت الذي تدين تفعل تلك الأمور نفسها.","2:2":"ولكننا نعلم أن دينونة الله على الذين يفعلون مثل هذه الأمور، هي بحسب الحق.","2:3":"فهل تظن، أيها الإنسان الذي تدين من يفعلون مثل هذه الأمور بينما تمارسها أنت، أنك ستفلت من دينونة الله؟","2:4":"أم أنك تحتقر غنى لطفه وصبره وطول أناته وأنت لا تعرف أن لطف الله يدفعك إلى التوبة؟","2:5":"ولكنك بسبب قساوتك وقلبك غير التائب، تخزن لنفسك غضبا ليوم الغضب، يوم تعلن دينونة الله العادلة.","2:6":"فإنه سيجازي كل إنسان بحسب أعماله.","2:7":"فتكون الحياة الأبدية للذين يسعون إلى المجد والكرامة والخلود مثابرين على العمل الصالح؛","2:8":"ويكون الغضب والسخط للمخاصمين الذين يرفضون الطاعة للحق ولكنهم يخضعون للإثم.","2:9":"فالشدة والضيق على نفس كل إنسان يعمل الشر اليهودي أولا ثم اليوناني؛","2:10":"والمجد والكرامة والسلام لكل من يعمل الصلاح اليهودي أولا، ثم اليوناني .","2:11":"فليس عند الله تحيز.","2:12":"فإن جميع الذين أخطأوا وهم بلا شريعة، فبلا شريعة يهلكون؛ وجميع الذين أخطأوا وهم تحت الشريعة، فبالشريعة يدانون.","2:13":"فليس سامعو الشريعة هم الأبرار أمام الله؛ بل العاملون بالشريعة يبررون.","2:14":"إذن الأمم الذين بلا شريعة، عندما يمارسون بالطبيعة ما في الشريعة، يكونون شريعة لأنفسهم، مع أن الشريعة ليست لهم.","2:15":"فهم يظهرون جوهر الشريعة مكتوبا في قلوبهم، ويشهد لذلك ضميرهم وأفكارهم في داخلهم، إذ تتهمهم تارة، وتارة تبرئهم.","2:16":"(وتكون الدينونة) يوم يدين الله خفايا الناس، وفقا لإنجيلي، على يد يسوع المسيح.","2:17":"ولكن، إن كنت تدعى يهوديا؛ وتتكل على الشريعة؛ وتفتخر بالله؛","2:18":"وتميز ما هو الأفضل بسبب ما تعلمته من الشريعة؛","2:19":"ولك ثقة في نفسك بأنك قائد للعميان، ونور للذين في الظلام،","2:20":"ومؤدب للجهال، ومعلم للأطفال؛ ولك في الشريعة صورة المعرفة والحق؛","2:21":"فأنت إذن، يامن تعلم غيرك، أما تعلم نفسك؟ أنت يامن تعظ أن لا يسرق، أتسرق؟","2:22":"أنت يامن تنهى عن الزنى، أتزني؟ أنت يامن تستنكر الأصنام، أتسرق الهياكل","2:23":"الذي تفتخر بالشريعة، أتهين الله بمخالفة الشريعة؟","2:24":"فإن «اسم الله يجدف عليه بين الأمم بسببكم»، كما هو مكتوب.","2:25":"فإن الختان ينفع إن كنت تعمل بالشريعة. ولكن إن كنت مخالفا للشريعة، فقد صار ختانك كأنه عدم ختان.","2:26":"إذن، إن عمل غير المختون بأحكام الشريعة، أفلا يحسب عدم ختانه كأنه ختان؟","2:27":"وغير المختون بالطبيعة، إذ يتمم الشريعة، يدينك أنت يامن تخالف الشريعة ولديك الكتاب والختان.","2:28":"فليس بيهودي من كان يهوديا في الظاهر، ولا بختان ما كان ظاهرا في اللحم.","2:29":"وإنما اليهودي هو من كان يهوديا في الباطن، والختان هو ما كان ختانا للقلب بالروح لا بالحرف. وهذا يأتيه المدح لا من الناس بل من الله!","3:1":"إذن، ما هو فضل اليهودي؟ بل ما هو نفع الختان؟","3:2":"إنه كثير من جميع الجهات، وأهمها فعلا أن أقوال الله وضعت أمانة بين أيديهم.","3:3":"فماذا يحدث؟ إن كان بعضهم قد أساءوا الأمانة، فهل يعطل عدم أمانتهم أمانة الله؟","3:4":"حاشا! وإنما، ليكن الله صادقا وكل إنسان كاذبا، كما قد كتب: «لكي تتبرر في كلامك، وتظفر متى حكمت».","3:5":"ولكن، إن كان إثمنا يبين بر الله، فماذا نقول؟ أيكون الله ظالما إذا أنزل بنا الغضب؟ أتكلم هنا بمنطق البشر:","3:6":"حاشا! وإلا، فكيف يدين الله العالم؟","3:7":"ولكن، إن كان كذبي يجعل صدق الله يزداد لمجده، فلماذا أدان أنا بعد باعتباري خاطئا؟","3:8":"أما يفترى علينا كما نتهم زورا ويزعم بعضهم أننا نقول لنمارس الشرور لكي يأتي الخير؟ هؤلاء دينونتهم عادلة.","3:9":"فماذا إذن؟ أنحن اليهود أفضل؟ لا، على الإطلاق! فإننا، في ما سبق، قد اتهمنا اليهود واليونانيين بكونهم جميعا تحت الخطيئة،","3:10":"كما قد كتب:","3:11":"ليس من يبحث عن الله.","3:12":"جميع الناس قد ضلوا، وصاروا كلهم بلا نفع. ليس من يمارس الصلاح، لا ولا واحد.","3:13":"حناجرهم قبور مفتوحة؛ ألسنتهم أدوات للمكر؛ شفاههم تخفي سم الأفاعي القاتلة؛","3:14":"أفواههم مملوءة لعنة ومرارة،","3:15":"أقدامهم سريعة إلى سفك الدماء؛","3:16":"في طرقهم الخراب والشقاء؛","3:17":"أما طريق السلام فلم يعرفوه؛","3:18":"ومخافة الله ليست نصب عيونهم».","3:19":"ونحن نعلم أن كل ما تقوله الشريعة إنما تخاطب به الذين هم تحت الشريعة، لكي يسد كل فم ويقع العالم كله تحت دينونة من الله.","3:20":"فإن أحدا من البشر لا يتبرر أمامه بالأعمال المطلوبة في الشريعة. إذ إن الشريعة هي لإظهار الخطيئة.","3:21":"أما الآن، فقد أعلن البر الذي يمنحه الله ، مستقلا عن الشريعة، ومشهودا له من الشريعة والأنبياء،","3:22":"ذلك البر الذي يمنحه الله على أساس الإيمان بيسوع المسيح لجميع الذين يؤمنون. إذ لا فرق،","3:23":"لأن الجميع قد أخطأوا وهم عاجزون عن بلوغ ما يمجد الله .","3:24":"فهم يبررون مجانا، بنعمته، بالفداء بالمسيح يسوع","3:25":"الذي قدمه الله كفارة، عن طريق الإيمان، وذلك بدمه.","3:26":"ليظهر بر الله إذ تغاضى، بإمهاله الإلهي، عن الخطايا التي حدثت في الماضي، ويظهر أيضا بره في الزمن الحاضر: فيتبين أنه بار وأنه يبرر من له الإيمان بيسوع.","3:27":"إذن، أين الافتخار؟ إنه قد أبطل! وعلى أي أساس؟ أعلى أساس الأعمال؟ لا، بل على أساس الإيمان،","3:28":"لأننا قد استنتجنا أن الإنسان يتبرر بالإيمان، بمعزل عن الأعمال المطلوبة في الشريعة.","3:29":"أو يكون الله إله اليهود وحدهم؟ أما هو إله الأمم أيضا؟ بلى، إنه إله الأمم أيضا،","3:30":"مادام الله الواحد هو الذي سيبرر أهل الختان على أساس الإيمان، وأهل عدم الختان على أساس الإيمان.","3:31":"إذن، هل نحن نبطل الشريعة بالإيمان؟ حاشا، بل إننا به نثبت الشريعة.","4:1":"والآن، ما قولنا في إبراهيم أبينا حسب الجسد؟ ماذا وجد؟","4:2":"فلو كان إبراهيم قد تبرر على أساس الأعمال، لكان من حقه أن يفتخر، ولكن ليس أمام الله.","4:3":"لأنه ماذا يقول الكتاب؟ «فآمن إبراهيم بالله، فحسب له ذلك برا».","4:4":"إن الذي يعمل، لا تحسب له الأجرة من قبيل النعمة بل من قبيل الدين. أما الذي لا يعمل","4:5":"وإنما يؤمن بمن يبرر الأثيم، فإن إيمانه يحسب له برا.","4:6":"كما يهنيء داود أيضا الإنسان الذي يحسب له الله برا بمعزل عن الأعمال، إذ يقول:","4:7":"«طوبى للذين غفرت آثامهم وسترت خطاياهم.","4:8":"طوبى للرجل الذي لا يحسب له الرب خطيئة!»","4:9":"فهل هذه الطوبى لأهل الختان وحدهم، أم لأهل عدم الختان أيضا؟ إننا نقول إن الإيمان قد حسب لإبراهيم برا.","4:10":"ففي أية حالة حسب له ذلك؟ أبعد الختان أم قبل الختان؟","4:11":"ثم تلقى إبراهيم علامة الختان ختما للبر الحاصل بالإيمان الذي كان له وهو مازال غير مختون، لكي يكون أبا لجميع الذين يؤمنون من غير المختونين فيحسب البر لهم أيضا،","4:12":"وأبا للمختونين الذين ليسوا من أهل الختان وحسب بل الذين يسيرون في خطى الإيمان الذي كان لأبينا إبراهيم وهو بعد غير مختون.","4:13":"فليس على أساس الشريعة كان الوعد لإبراهيم، أو لنسله، بأن يكون وارثا للعالم، وإنما على أساس البر الذي بالإيمان.","4:14":"فلو كان أهل الشريعة هم أصحاب الإرث، لصار الإيمان بلا فاعلية ونقض الوعد.","4:15":"لأن الشريعة إنما تنتج الغضب؛ فلولا الشريعة لما ظهرت المخالفة.","4:16":"لذلك، فإن الوعد هو على أساس الإيمان ليكون بحسب النعمة، بقصد أن يكون مضمونا للنسل كله: ليس لأهل الشريعة وحدهم، بل أيضا لأهل الإيمان الذي كان لإبراهيم. فإنه أب لنا جميعا،","4:17":"كما قد كتب: «إني جعلتك أبا لأمم كثيرة». (إنه أب لنا) في نظر الله الذي به آمن، والذي يحيي الموتى ويستدعي إلى الوجود ما كان غير موجود.","4:18":"إذ رغم انقطاع الرجاء، فبالرجاء آمن إبراهيم بأنه سيصير أبا لأمم كثيرة، وفقا لما قيل له: «بهذه الكثرة سيكون نسلك».","4:19":"ولم يضعف في الإيمان حين أدرك موت جسده، لكونه قارب سن المئة، وموت رحم زوجته سارة أيضا؛","4:20":"ولم يشك في وعد الله عن عدم إيمان، بل وجد في الإيمان قوة، فأعطى المجد لله.","4:21":"وإذ اقتنع تماما بأن ما وعده الله به هو قادر أن يفعله؛","4:22":"فلهذا أيضا حسب له ذلك برا.","4:23":"ولكن ما قد كتب من أن البر حسب له، لم يكن من أجله وحده،","4:24":"بل أيضا من أجلنا، نحن الذين سيحسب ذلك لنا إذ نؤمن بمن أقام من بين الأموات يسوع ربنا","4:25":"الذي أسلم للموت من أجل معاصينا ثم أقيم من أجل تبريرنا.","5:1":"فبما أننا قد تبررنا على أساس الإيمان، صرنا في سلام مع الله بربنا يسوع المسيح.","5:2":"وبه أيضا تم لنا الدخول بالإيمان إلى هذه النعمة التي نقيم فيها الآن؛ ونحن نفتخر برجائنا في التمتع بمجد الله.","5:3":"ليس هذا فقط، بل نفتخر أيضا في وسط الضيقات، لعلمنا أن الضيق ينتج فينا الصبر،","5:4":"والصبر يؤهلنا للفوز في الامتحان، والفوز يبعث فينا الرجاء،","5:5":"والرجاء لا يخيبنا، لأن الله أفاض محبته في قلوبنا بالروح القدس الذي وهبنا إياه.","5:6":"فإنه ونحن بعد عاجزون، مات المسيح عن العصاة في الوقت المعين.","5:7":"إذ قلما يموت أحد فدى إنسان بار، بل قد يتجرأ أحد أن يموت فدى إنسان صالح.","5:8":"ولكن الله أثبت لنا محبته، إذ ونحن مازلنا خاطئين مات المسيح عوضا عنا.","5:9":"ومادمنا الآن قد تبررنا بدمه، فكم بالأحرى نخلص به من الغضب الآتي!","5:10":"فإن كنا، ونحن أعداء، قد تصالحنا مع الله بموت ابنه، فكم بالأحرى نخلص بحياته ونحن مصالحون!","5:11":"وليس هذا فقط، بل إننا نفتخر أيضا بالله، بفضل ربنا يسوع المسيح الذي به نلنا المصالحة الآن.","5:12":"ولهذا، فكما دخلت الخطيئة إلى العالم على يد إنسان واحد، وبدخول الخطيئة دخل الموت، هكذا جاز الموت على جميع البشر، لأنهم جميعا أخطأوا.","5:13":"فإن الخطيئة كانت منتشرة في العالم قبل مجيء الشريعة. إلا أن الخطيئة ما كانت تسجل، لأن الشريعة لم تكن موجودة.","5:14":"أما الموت، فقد ملك منذ آدم إلى موسى، حتى على الذين لم يرتكبوا خطيئة شبيهة بمخالفة آدم، الذي هو رمز للآتي بعده.","5:15":"ولكن مفعول المعصية ليس كمفعول النعمة! فإذا كان الكثيرون بمعصية إنسان واحد قد ماتوا، فكم بالأحرى في الإنسان الواحد يسوع المسيح تتوافر للكثيرين نعمة الله والعطية المجانية بالنعمة.","5:16":"ثم إن أثر خطيئة إنسان واحد ليس كأثر الهبة! فإن الحكم من جراء معصية واحدة يؤدي إلى الدينونة. وأما فعل النعمة، من جراء معاص كثيرة، فيؤدي إلى التبرير.","5:17":"فما دام الموت بمعصية الإنسان الواحد، قد ملك بذلك الواحد، فكم بالأحرى يملك في الحياة بيسوع المسيح الواحد أولئك الذين ينالون فيض النعمة وعطية البر المجانية.","5:18":"فإذن، كما أن معصية واحدة جلبت الدينونة على جميع البشر، كذلك فإن برا واحدا يجلب التبرير المؤدي إلى الحياة لجميع البشر.","5:19":"فكما أنه بعصيان الإنسان الواحد جعل الكثيرون خاطئين، فكذلك أيضا بطاعة الواحد سيجعل الكثيرون أبرارا.","5:20":"وأما الشريعة فقد أدخلت لتظهر كثرة المعصية. ولكن، حيث كثرت الخطيئة، تتوافر النعمة أكثر جدا،","5:21":"حتى إنه كما ملكت الخطيئة بالموت، فكذلك أيضا تملك النعمة على أساس البر مؤدية إلى الحياة الأبدية بيسوع المسيح ربنا.","6:1":"إذن ماذا نقول؟ أنستمر في الخطيئة لكي تتوافر النعمة؟","6:2":"حاشا! فنحن الذين متنا بالنسبة للخطيئة، كيف نعيش بعد فيها؟","6:3":"أم يخفى عليكم أننا جميعا، نحن الذين تعمدنا اتحادا بالمسيح يسوع، قد تعمدنا اتحادا بموته؟","6:4":"وبسبب ذلك دفنا معه بالمعمودية للموت، حتى كما أقيم المسيح من الأموات بمجد الآب، كذلك نسلك نحن أيضا في حياة جديدة.","6:5":"فما دمنا قد اتحدنا به في ما يشبه موته، فإننا سنتحد به أيضا في قيامته.","6:6":"فنحن نعلم هذا: أن الإنسان العتيق فينا قد صلب معه لكي يبطل جسد الخطيئة فلا نبقى عبيدا للخطيئة فيما بعد.","6:7":"فإن من مات، قد تحرر من الخطيئة.","6:8":"ومادمنا متنا مع المسيح، فنحن نؤمن أننا سنحيا أيضا معه،","6:9":"لكوننا على يقين بأن المسيح، وقد أقيم من بين الأموات، لا يموت مرة ثانية، إذ ليس للموت سيادة عليه بعد.","6:10":"لأنه بموته، قد مات لأجل الخطيئة مرة واحدة؛ وبحياته، يحيا لله.","6:11":"فكذلك أنتم أيضا، احسبوا أنفسكم أمواتا بالنسبة للخطيئة وأحياء لله في المسيح يسوع.","6:12":"إذن، لا تملكن الخطيئة في جسدكم المائت فتنقادوا لها في شهواته.","6:13":"ولا تقدموا أعضاءكم للخطيئة أسلحة للإثم، بل قدموا أنفسكم لله باعتباركم أقمتم من بين الأموات أحياء، وأعضاءكم لله أسلحة للبر.","6:14":"فلن يكون للخطيئة سيادة عليكم، إذ لستم خاضعين للشريعة بل للنعمة.","6:15":"فماذا إذن؟ أنخطيء لأننا لسنا خاضعين للشريعة بل للنعمة؟ حاشا!","6:16":"أما تعلمون أنكم عندما تقدمون أنفسكم عبيدا للطاعة، تكونون للذي تطيعونه عبيدا: إما للخطيئة فإلى الموت، وإما للطاعة فإلى البر؟","6:17":"إنما الشكر لله، لأنكم كنتم عبيدا للخطيئة ولكن أطعتم من القلب صيغة التعليم الذي وضعتم في عهدته.","6:18":"والآن، إذ حررتم من الخطيئة، صرتم عبيدا للبر.","6:19":"أتكلم بشريا هنا بسبب ضعفكم البشري. فكما قدمتم سابقا أعضاءكم عبيدا للنجاسة والإثم في خدمة الإثم، كذلك قدموا الآن أعضاءكم عبيدا للبر في خدمة القداسة.","6:20":"فإنكم، لما كنتم عبيدا للخطيئة، كنتم أحرارا من البر.","6:21":"ولكن أي ثمر أنتجتم حينذاك من الأمور التي تخجلون بها الآن، وما عاقبتها إلا الموت؟","6:22":"أما الآن، وقد حررتم من الخطيئة وصرتم عبيدا لله، فإن لكم ثمركم للقداسة، والعاقبة هي الحياة الأبدية.","6:23":"لأن أجرة الخطيئة هي الموت، وأما هبة الله فهي الحياة الأبدية في المسيح يسوع ربنا.","7:1":"أيخفى عليكم أيها الإخوة وأنا أخاطب أناسا يعرفون قوانين الشريعة أن للشريعة سيادة على الإنسان مادام حيا؟","7:2":"فالمرأة المتزوجة تربطها الشريعة بزوجها مادام حيا. ولكن، إن مات الزوج، فالشريعة تحلها من الارتباط به.","7:3":"ولذلك، فمادام الزوج حيا، تعتبر زانية إن صارت إلى رجل آخر. ولكن إن مات الزوج تتحرر من الشريعة، حتى إنها لا تكون زانية إن صارت إلى رجل آخر.","7:4":"وهكذا أنتم أيضا ياإخوتي، فإنكم بجسد المسيح الذي مات، قد صرتم أمواتا بالنسبة للشريعة، لكي تصيروا لآخر، إلى المسيح نفسه الذي أقيم من بين الأموات، من أجل أن نثمر لله.","7:5":"فعندما كنا في الجسد، كانت أهواء الخطايا المعلنة في الشريعة عاملة في أعضائنا لكي نثمر للموت.","7:6":"أما الآن، فنحن قد تحررنا من الشريعة، إذ متنا بالنِّسبة لما كان يقيدنا، حتى نكون عبيدا يخدمون وفقا للنظام الروحي الجديد، لا للنظام الحرفي العتيق.","7:7":"إذن، ماذا نقول؟ هل الشريعة خطيئة؟ حاشا! ولكني ما عرفت الخطيئة إلا بالشريعة. فما كنت لأعرف الشهوة لولا قول الشريعة: «لا تشته!»","7:8":"ولكن الخطيئة استغلت هذه الوصية فأثارت في كل شهوة. فإن الخطيئة، لولا الشريعة، ميتة.","7:9":"أما أنا فكنت من قبل عائشا بمعزل عن الشريعة؛ ولكن لما جاءت الشريعة عاشت الخطيئة،","7:10":"فمت أنا. والوصية الهادفة إلى الحياة، صارت لي مؤدية إلى الموت.","7:11":"فإن الخطيئة، إذ استغلت الوصية، خدعتني وقتلتني بها.","7:12":"فالشريعة إذن مقدسة، والوصية مقدسة وعادلة وصالحة.","7:13":"فهل صار ما هو صالح موتا لي؟ حاشا! ولكن الخطيئة، لكي تظهر أنها خطيئة، أنتجت لي الموت بما هو صالح، حتى تصير الخطيئة خاطئة جدا بسبب الوصية.","7:14":"فإننا نعلم أن الشريعة روحية؛ وأما أنا فجسدي بيع عبدا للخطيئة.","7:15":"فإن ما أفعله لا أملك السيطرة عليه: إذ لا أمارس ما أريده، وإن ما أبغضه فإياه أعمل.","7:16":"فما دمت أعمل ما لا أريده، فإني أصادق على صواب الشريعة.","7:17":"فالآن، إذن، ليس بعد أنا من يفعل ذلك، بل الخطيئة التي تسكن في.","7:18":"لأنني أعلم أنه في، أي في جسدي، لا يسكن الصلاح: فأن أريد الصلاح ذلك متوفر لدي؛ وأما أن أفعله، فذلك لا أستطيعه.","7:19":"فأنا لا أعمل الصلاح الذي أريده؛ وإنما الشر الذي لا أريده فإياه أمارس.","7:20":"ولكن، إن كان ما لا أريده أنا إياه أعمل، فليس بعد أنا من يفعل ذلك، بل الخطيئة التي تسكن في.","7:21":"إذن، أجد نفسي، أنا الذي يريد أن يعمل ما هو صالح، خاضعا لهذا الناموس:","7:22":"أن لدي الشر. فإنني، وفقا للإنسان الباطن في، أبتهج بشريعة الله.","7:23":"ولكنني أرى في أعضائي ناموسا آخر يحارب الشريعة التي يريدها عقلي، ويجعلني أسيرا لناموس الخطيئة الكائن في أعضائي.","7:24":"فيا لي من إنسان تعيس ! من يحررني من جسد الموت هذا؟","7:25":"أشكر الله بيسوع المسيح ربنا! إذن، أنا نفسي من حيث العقل، أخدم شريعة الله عبدا لها؛ ولكنني من حيث الجسد، أخدم ناموس الخطيئة عبدا له.","8:1":"فالآن إذا ليس على الذين في المسيح يسوع أية دينونة بعد.","8:2":"لأن ناموس روح الحياة في المسيح يسوع قد حررني من ناموس الخطيئة ومن الموت.","8:3":"فإن ما عجزت الشريعة عنه، لكون الجسد قد جعلها قاصرة عن تحقيقه، أتمه الله إذ أرسل ابنه، متخذا ما يشبه جسد الخطيئة ومكفرا عن الخطيئة فدان الخطيئة في الجسد","8:4":"حتى يتم فينا البر الذي تسعى إليه الشريعة، فينا نحن السالكين لا بحسب الجسد بل بحسب الروح.","8:5":"فإن الذين هم بحسب الجسد يهتمون بأمور الجسد، والذين هم بحسب الروح يهتمون بأمور الروح.","8:6":"فاهتمام الجسد هو موت؛ وأما اهتمام الروح فهو حياة وسلام.","8:7":"لأن اهتمام الجسد هو عداوة لله، إذ إنه لا يخضع لناموس الله، بل لا يستطيع ذلك.","8:8":"فالذين هم تحت سلطة الجسد لا يستطيعون أن يرضوا الله .","8:9":"وأما أنتم، فلستم تحت سلطة الجسد بل تحت سلطة الروح، إذا كان روح الله ساكنا في داخلكم حقا. ولكن، إن كان أحد ليس له روح المسيح، فهو ليس للمسيح.","8:10":"وإذا كان المسيح فيكم، فمع أن الجسد مائت بسبب الخطيئة، فإن الروح حياة لكم بسبب البر.","8:11":"وإذا كان روح الذي أقام يسوع من بين الأموات يسكن فيكم، فإن الذي أقام المسيح من بين الأموات سوف يحيي أيضا أجسادكم الفانية بسبب روحه الذي يسكن فيكم.","8:12":"فليس علينا إذن، أيها الإخوة، أي التزام نحو الجسد لنعيش بحسب الجسد.","8:13":"لأنه إن عشتم بحسب الجسد، فإنكم ستموتون، ولكن إن كنتم بالروح تميتون أعمال الجسد، فستحيون.","8:14":"فإن جميع الخاضعين لقيادة روح الله، هم أبناء لله.","8:15":"إذ إنكم لم تنالوا روح عبودية يعيدكم إلى الخوف، بل نلتم روح بنوة به نصرخ: «أبا! أبانا!»","8:16":"فالروح نفسه يشهد مع أرواحنا بأننا أولاد الله.","8:17":"وما دمنا أولادا، فنحن أيضا وارثون؛ ورثة الله وشركاء المسيح في الإرث. وإن كنا الآن نشاركه في مقاساة الألم، فلأننا سوف نشاركه أيضا في التمتع بالمجد.","8:18":"فإني مقتنع بأن آلام الزمان الحاضر ليست شيئا إذا قيست بالمجد الآتي الذي سيعلن فينا.","8:19":"ذلك أن الخليقة تترقب بلهفة أن يعلن أبناء الله،","8:20":"لأن الخليقة قد أخضعت للباطل، لا باختيارها بل من قبل الذي أخضعها، على رجاء أن","8:21":"تحرر هي أيضا من عبودية الفساد إلى حرية المجد التي لأولاد الله.","8:22":"فإننا نعلم أن الخليقة كلها تئن وتتمخض معا حتى الآن.","8:23":"وليس هي وحدها، بل أيضا نحن الذين لنا باكورة الروح، نحن أنفسنا نئن في قرارة نفوسنا مترقبين إعلان بنوتنا بافتداء أجسادنا.","8:24":"فإننا قد خلصنا، إنما بالرجاء؛ ولكن الرجاء متى رأيناه لا يكون رجاء؛ فما يراه الإنسان لماذا يرجوه بعد؟","8:25":"ولكن، إن كنا نرجو ما لا نراه، فبالصبر نتوقعه.","8:26":"وكذلك الروح أيضا يمدنا بالعون لنقهر ضعفنا. فإننا لا نعلم ما يجب أن نصلي لأجله كما يليق، ولكن الروح نفسه يؤدي الشفاعة عنا بأنات تفوق التعبير.","8:27":"على أن فاحص القلوب يعلم قصد الروح، لأن الروح يشفع في القديسين بما يوافق الله .","8:28":"وإننا نعلم أن الله يجعل جميع الأمور تعمل معا لأجل الخير لمحبيه، المدعوين بحسب قصده.","8:29":"لأن الذين سبق فعرفهم، سبق فعينهم أيضا ليكونوا مشابهين صورة ابنه ليكون هو البكر بين إخوة كثيرين.","8:30":"والذين سبق فعينهم، فهؤلاء دعاهم أيضا. والذين دعاهم، فهؤلاء بررهم أيضا. والذين بررهم، فهؤلاء مجدهم أيضا.","8:31":"فبعد هذا، ماذا نقول؟ مادام الله معنا، فمن يكون علينا؟ ذاك الذي لم يمسك عنا ابنه،","8:32":"بل بذله لأجلنا جميعا، كيف لا يجود علينا معه بكل شيء أيضا؟","8:33":"ومن سيتهم مختاري الله؟ إن الله هو الذي يبرر،","8:34":"فمن ذا يدين؟ إنه المسيح يسوع هو الذي مات، بل بالأحرى قام، وهو أيضا عن يمين الله، وهو يشفع فينا أيضا.","8:35":"فمن سيفصلنا عن محبة المسيح لنا؟ هل الشدة أم الضيق أم الاضطهاد أم الجوع أم العري أم الخطر أم السيف؟","8:36":"بل كما قد كتب: «إننا من أجلك نعاني الموت طول النهار. قد حسبنا كأننا غنم للذبح!»","8:37":"ولكننا، في جميع هذه الأمور، نحرز ما يفوق الانتصار على يد من أحبنا.","8:38":"فإني لعلى يقين بأنه لا الموت ولا الحياة، ولا الملائكة ولا الرياسات، ولا الأمور الحاضرة ولا الآتية، ولا القوات،","8:39":"ولا الأعالي ولا الأعماق، ولا خليقة أخرى، تقدر أن تفصلنا عن محبة الله التي لنا في المسيح يسوع ربنا.","9:1":"أقول الحق في المسيح، لست أكذب، وضميري شاهد لي في الروح القدس،","9:2":"إن بي حزنا شديدا، وبقلبي ألم لا ينقطع:","9:3":"فقد كنت أتمنى لو أكون أنا نفسي محروما من المسيح في سبيل إخوتي، بني جنسي حسب الجسد.","9:4":"فإنهم إسرائيليون، وقد منحوا التبني والمجد والعهود والتشريع والعبادة والمواعيد،","9:5":"ومنهم كان الآباء ومنهم جاء المسيح حسب الجسد، وهو فوق الجميع الله المبارك إلى الأبد. آمين.","9:6":"لست أعني أن كلمة الله قد خابت. إذ ليس جميع بني إسرائيل هم إسرائيل؛","9:7":"وليسوا، لأنهم نسل إبراهيم، كلهم أولادا لله، بل (كما قد كتب): «بإسحاق سيكون لك نسل يحمل اسمك».","9:8":"أي أن أولاد الجسد ليسوا هم أولاد الله، بل أولاد الوعد يحسبون نسلا.","9:9":"فهذه هي كلمة الوعد: «في مثل هذا الوقت أعود، ويكون لسارة ابن».","9:10":"ليس ذلك فقط، بل إن رفقة أيضا، وقد حبلت من رجل واحد، من إسحاق أبينا،","9:11":"ولم يكن الولدان قد ولدا بعد ولا فعلا خيرا أو شرا، وذلك كي يبقى قصد الله من جهة الاختيار","9:12":"لا على أساس الأعمال بل على أساس دعوة منه، قيل لها: «إن الولد الأكبر يكون عبدا للأصغر»،","9:13":"كما قد كتب: «أحببت يعقوب، وأبغضت عيسو».","9:14":"إذا، ماذا نقول، أيكون عند الله ظلم، حاشا!","9:15":"فإنه يقول لموسى: «إني أرحم من أرحمه، وأشفق على من أشفق عليه!»","9:16":"إذا، لا يتعلق الأمر برغبة الإنسان ولا بسعيه، وإنما برحمة الله فقط.","9:17":"فإن الله يقول لفرعون في الكتاب: «لهذا الأمر بعينه أقمتك: لأظهر فيك قدرتي ويعلن اسمي في الأرض كلها».","9:18":"فالله إذا يرحم من يشاء، ويقسي من يشاء.","9:19":"هنا ستقول لي: «لماذ يلوم بعد؟ من يقاوم قصده؟»","9:20":"فأقول: من أنت أيها الإنسان حتى ترد جوابا على الله؟ أيقول الشيء المصنوع لصانعه: لماذا صنعتني هكذا؟","9:21":"أوليس لصانع الفخار سلطة على الطين ليصنع من كتلة واحدة وعاء للاستعمال الرفيع وآخر للاستعمال الوضيع؟","9:22":"فماذا إذا إن كان الله ، وقد شاء أن يظهر غضبه ويعلن قدرته، احتمل بكل صبر أوعية غضب جاهزة للهلاك،","9:23":"وذلك بقصد أن يعلن غنى مجده في أوعية الرحمة التي سبق فأعدها للمجد،","9:24":"فينا نحن الذين دعاهم لا من بين اليهود فقط بل من بين الأمم أيضا؟","9:25":"وذلك على حد ما يقول أيضا في نبوءة هوشع: «من لم يكونوا شعبي سأدعوهم شعبي، ومن لم تكن محبوبة سأدعوها محبوبة.","9:26":"ويكون أنه حيث قيل لهم: لستم شعبي، فهناك يدعون أبناء الله الحي».","9:27":"أما إشعياء، فيهتف متكلما على إسرائيل: «ولو كان بنو إسرائيل كرمل البحر عددا، فإن بقية منهم ستخلص.","9:28":"فإن الرب سيحسم الأمر وينجز كلمته سريعا على الأرض».","9:29":"وكما كان إشعياء قد قال سابقا: «لو لم يبق لنا رب الجنود نسلا، لصرنا مثل سدوم وشابهنا عمورة!»","9:30":"فما هي خلاصة القول؟ إن الأمم الذين لم يكونوا يسعون وراء البر، قد بلغوا البر، ولكنه البر القائم على أساس الإيمان.","9:31":"أما إسرائيل، وقد كانوا يسعون وراء شريعة تهدف إلى البر، فقد فشلوا حتى في بلوغ الشريعة.","9:32":"ولأي سبب؟ لأن سعيهم لم يكن على أساس الإيمان، بل كان وكأن الأمر قائم على الأعمال. فقد تعثروا بحجر العثرة،","9:33":"كما كتب: «ها أنا واضع في صهيون حجر عثرة وصخرة سقوط. ومن يؤمن به لا يخيب».","10:1":"أيها الإخوة، إن رغبة قلبي وتضرعي إلى الله لأجلهم، هما أن يخلصوا.","10:2":"فإني أشهد لهم أن عندهم غيرة لله، ولكنها ليست على أساس المعرفة.","10:3":"فبما أنهم جهلوا بر الله وسعوا إلى إثبات برهم الذاتي، لم يخضعوا للبر الإلهي.","10:4":"فإن غاية الشريعة هي المسيح لتبرير كل من يؤمن.","10:5":"فقد كتب موسى عن البر الآتي من الشريعة: «إن الإنسان الذي يعمل بهذه الأمور، يحيا بها».","10:6":"غير أن البر الآتي من الإيمان يقول هذا: «لا تقل في قلبك: من يصعد إلى السماوات؟» أي لينزل المسيح،","10:7":"ولا: «من ينزل إلى الأعماق؟» أي ليصعد المسيح من بين الأموات!","10:8":"فماذا يقول إذا؟ إنه يقول: «إن الكلمة قريبة منك. إنها في فمك وفي قلبك!» وما هذه الكلمة إلا كلمة الإيمان التي نبشر بها:","10:9":"أنك إن اعترفت بفمك بيسوع ربا، وآمنت في قلبك بأن الله أقامه من الأموات، نلت الخلاص.","10:10":"فإن الإيمان في القلب يؤدي إلى البر، والاعتراف بالفم يؤيد الخلاص،","10:11":"لأن الكتاب يقول: «كل من هو مؤمن به، لا يخيب».","10:12":"فلا فرق بين اليهودي واليوناني، لأن للجميع ربا واحدا، غنيا تجاه كل من يدعوه».","10:13":"«فإن كل من يدعو باسم الرب يخلص».","10:14":"ولكن، كيف يدعون من لم يؤمنوا به؟ وكيف يؤمنون بمن لم يسمعوا به؟ وكيف يسمعون بلا مبشر؟","10:15":"وكيف يبشر أحد إلا إذا كان قد أرسل؟ كما قد كتب: «ما أجمل أقدام المبشرين بالخيرات!»","10:16":"ولكن، ليس كلهم أطاعوا الإنجيل. فإن إشعياء يقول: «يارب! من صدق ما أسمعناه إياه؟»","10:17":"إذا، الإيمان نتيجة السماع، والسماع هو من التبشير بكلمة المسيح !","10:18":"ولكني أقول: أما سمعوا؟ بلى، فإن المبشرين «انطلق صوتهم إلى الأرض كلها، وكلامهم إلى أقاصي العالم».","10:19":"وأعود فأقول: أما فهم إسرائيل؟ إن موسى، أولا، يقول: «سأثير غيرتكم بمن ليسوا أمة، وبأمة بلا فهم سوف أغضبكم!»","10:20":"وأما إشعياء فيجرؤ على القول: «وجدني الذين لم يطلبوني وصرت معلنا للذين لم يبحثوا عني».","10:21":"ولكنه عن إسرائيل يقول: «طول النهار مددت يدي إلى شعب عاص معارض!»","11:1":"وهنا أقول: هل رفض الله شعبه؟ حاشا! فأنا أيضا إسرائيلي، من نسل إبراهيم ومن سبط بنيامين.","11:2":"إن الله لم يرفض شعبه الذي كان قد اختاره. أما تعلمون ما يقوله الكتاب في أمر إيليا لما رفع إلى الله شكوى على إسرائيل قائلا:","11:3":"«يارب؟ قتلوا أنبياءك، وهدموا مذابحك، وبقيت أنا وحدي، وهم يسعون إلى قتلي!»","11:4":"ولكن، ماذا كان الجواب الإلهي له؟: «أبقيت لنفسي سبعة آلاف رجل لم يحنوا ركبة للبعل!»","11:5":"فكذلك، في الزمان الحاضر، ماتزال بقية اختارها الله بالنعمة.","11:6":"ولكن، بما أن ذلك قد تم بالنعمة، فليس بعد على أساس الأعمال، وإلا فليست النعمة نعمة بعد.","11:7":"فما الخلاصة إذا؟ إن ما يسعى إليه إسرائيل لم ينالوه، بل ناله المختارون منهم، والباقون عميت بصائرهم،","11:8":"وفقا لما قد كتب: «ألقى الله عليهم روح خمول وأعطاهم عيونا لا يبصرون بها، وآذانا لا يسمعون بها، حتى هذا اليوم».","11:9":"كذلك يقول داود: «لتصر لهم مائدتهم فخا وشركا وعقبة وعقابا.","11:10":"لتظلم عيونهم كي لا يبصروا، ولتكن ظهورهم منحنية دائما!»","11:11":"فأقول إذا: هل تعثروا لكي يسقطوا أبدا؟ حاشا! بل بسقطتهم توفر الخلاص للأمم، لعل ذلك يثير غيرتهم.","11:12":"فإذا كانت سقطتهم غنى للعالم، وخسارتهم غنى للأمم، فكم بالأحرى يكون اكتمالهم...؟","11:13":"فإني أخاطبكم، أنتم الأمم، بما أني رسول للأمم، ممجدا رسالتي،","11:14":"لعلي أثير غيرة بني جنسي فأنقذ بعضا منهم.","11:15":"فإذا كان إبعادهم فرصة لمصالحة العالم، فماذا يكون قبولهم إلا حياة من بين الأموات؟","11:16":"وإذا كانت القطعة الأولى من العجين مقدسة، فالعجين كله مقدس؛ وإذا كان أصل الشجرة مقدسا، فالأغصان أيضا تكون مقدسة.","11:17":"فإذا كانت بعض أغصان الزيتونة قد قطعت، ثم طعمت فيها وأنت من زيتونة برية، فصرت بذلك شريكا في أصل الزيتونة وغذائها،","11:18":"فلا تفتخر على باقي الأغصان. وإن كنت تفتخر، فلست أنت تحمل الأصل، بل هو يحملك.","11:19":"ولكنك قد تقول: «تلك الأغصان قد قطعت لأطعم أنا!»","11:20":"صحيح! فهي قطعت لسبب عدم الإيمان، وأنت إنما تثبت بسبب الإيمان. فلا يأخذك الغرور، بل خف","11:21":"إن الله ربما لا يبقي عليك مادام لم يبق على الأغصان الأصلية.","11:22":"فتأمل إذا لطف الله وشدته: أما الشدة، فعلى الذين سقطوا؛ وأما لطف الله فمن نحوك مادمت تثبت في اللطف. ولو لم تكن ثابتا، لكنت أنت أيضا تقطع.","11:23":"وهم أيضا، إن كانوا لا يثبتون في عدم الإيمان، سوف يطعمون، لأن الله قادر أن يطعمهم من جديد.","11:24":"فإذا كنت أنت قد قطعت من الزيتونة البرية التي تنتمي إليها أصلا، وطعمت خلافا للعادة في الزيتونة الجيدة، فكم بالأحرى هؤلاء، الذين هم أغصان أصلية، سوف يطعمون في زيتونتهم الخاصة.","11:25":"فإني لا أريد، أيها الإخوة، أن يخفى عليكم هذا السر، لكي لا تكونوا حكماء في نظر أنفسكم، وهو أن العمى قد أصاب إسرائيل جزئيا إلى أن يتم دخول الأمم كليا.","11:26":"وهكذا، سوف يخلص جميع إسرائيل، وفقا لما قد كتب: «إن المنقذ سيطلع من صهيون ويرد الإثم عن يعقوب.","11:27":"وهذا هو العهد مني لهم حين أزيل خطاياهم».","11:28":"ففيما يتعلق بالإنجيل، هم أعداء الله من أجلكم. وأما فيما يتعلق بالاختيار الإلهي فهم محبوبون من أجل الآباء.","11:29":"فإن الله لا يتراجع أبدا عن هباته ودعوته.","11:30":"والواقع أنه كما كنتم أنتم في الماضي غير مطيعين لله، ولكنكم الآن نلتم الرحمة من جراء عدم طاعتهم هم،","11:31":"فكذلك الآن هم غير مطيعين لله. لينالوا هم أيضا الرحمة، من جراء الرحمة التي نلتموها أنتم.","11:32":"فإن الله حبس الجميع معا في عدم الطاعة لكي يرحمهم جميعا.","11:33":"فما أعمق غنى الله وحكمته وعلمه! ما أبعد أحكامه عن الفحص وطرقه عن التتبع !","11:34":"«لأنه من عرف فكر الرب؟ أو من كان له مشيرا؟","11:35":"أو من أقرضه شيئا حتى يرد له؟»","11:36":"فإن منه وبه وله كل شيء. له المجد إلى الأبد. آمين!","12:1":"لذلك أتوسل إليكم أيها الإخوة، نظرا لمراحم الله، أن تقدموا له أجسادكم ذبيحة مقدسة مقبولة عنده، وهي عبادتكم بعقل.","12:2":"ولا تتكيفوا مع هذا العالم، بل تغيروا بتجديد الذهن، لتميزوا ما هي إرادة الله الصالحة المقبولة الكاملة.","12:3":"فإني، بالنعمة الموهوبة لي، أوصي كل واحد بينكم ألا يقدر نفسه تقديرا يفوق حقه، بل أن يكون متعقلا في تفكيره، بحسب مقدار الإيمان الذي قسمه الله لكل منكم.","12:4":"فكما أن لنا في جسد واحد أعضاء كثيرة، ولكن ليس لجميع هذه الأعضاء عمل واحد،","12:5":"فكذلك نحن الكثيرين جسد واحد في المسيح، وكلنا أعضاء بعضنا لبعض.","12:6":"ولكن، بما أن المواهب موزعة بحسب النعمة الموهوبة لنا، (فلنمارسها): فمن وهب النبوءة، فليتنبأ بحسب مقدار الإيمان؛","12:7":"ومن وهب الخدمة، فلينهمك في الخدمة؛ أو التعليم، ففي التعليم؛","12:8":"أو الوعظ، ففي الوعظ؛ أو العطاء، فليعط بسخاء؛ أو القيادة، فليقد باجتهاد؛ أو إظهار الرحمة، فليرحم بسرور.","12:9":"ولتكن المحبة بلا رياء. انفروا من الشر، والتصقوا بالخير.","12:10":"أحبوا بعضكم بعضا محبة أخوية، مفضلين بعضكم على بعض في الكرامة.","12:11":"لا تتكاسلوا في الاجتهاد، بل كونوا ملتهبين في الروح، عبيدا خادمين للرب،","12:12":"فرحين بالرجاء، صابرين في الضيق، مواظبين على الصلاة،","12:13":"متعاونين على سد حاجات القديسين، مداومين على إضافة الغرباء.","12:14":"باركوا الذين يضطهدونكم. باركوا ولا تلعنوا!","12:15":"افرحوا مع الفرحين، وابكوا مع الباكين.","12:16":"كونوا متوافقين بعضكم مع بعض، غير مهتمين بالأمور العالية، بل مسايرين ذوي المراكز الوضيعة. لا تكونوا حكماء في نظر أنفسكم.","12:17":"لا تردوا لأحد شرا مقابل شر، بل اجتهدوا في تقديم ما هو حسن أمام جميع الناس.","12:18":"إن كان ممكنا، فمادام الأمر يتعلق بكم، عيشوا في سلام مع جميع الناس.","12:19":"لا تنتقموا لأنفسكم، أيها الأحباء، بل دعوا الغضب لله، لأنه قد كتب: «لي الانتقام، أنا أجازي، يقول الرب».","12:20":"وإنما «إن جاع عدوك فأطعمه، وإن عطش فاسقه. فإنك، بعملك هذا تجمع على رأسه جمرا مشتعلا».","12:21":"لا تدع الشر يغلبك، بل اغلب الشر بالخير.","13:1":"على كل نفس أن تخضع للسلطات الحاكمة. فلا سلطة إلا من عند الله، والسلطات القائمة مرتبة من قبل الله.","13:2":"حتى إن من يقاوم السلطة، يقاوم ترتيب الله، والمقاومون سيجلبون العقاب على أنفسهم.","13:3":"فإن الحكام لا يخافهم من يفعل الصلاح بل من يفعل الشر. أفترغب إذن في أن تكون غير خائف من السلطة؟ اعمل ما هو صالح، فتكون ممدوحا عندها،","13:4":"لأنها خادمة الله لك لأجل الخير. أما إن كنت تعمل الشر فخف، لأن السلطة لا تحمل السيف عبثا، إذ إنها خادمة الله، وهي التي تنتقم لغضبه ممن يفعل الشر.","13:5":"ولذلك، فمن الضروري أن تخضعوا، لا اتقاء للغضب فقط، بل مراعاة للضمير أيضا.","13:6":"فلهذا السبب تدفعون الضرائب أيضا، لأن رجال السلطة هم خدام لله يواظبون على هذا العمل بعينه.","13:7":"فأدوا لكل واحد حقه: الضريبة لصاحب الضريبة والجزية لصاحب الجزية، والاحترام لصاحب الاحترام، والإكرام لصاحب الإكرام.","13:8":"لا تكونوا في دين لأحد، إلا بأن يحب بعضكم بعضا. فإن من يحب غيره، يكون قد تمم الشريعة،","13:9":"لأن الوصايا «لا تزن، لا تقتل، لا تسرق، لا تشهد زورا، لا تشته....» وباقي الوصايا، تتلخص في هذه الكلمة: «أحب قريبك كنفسك!»","13:10":"فالمحبة لا تعمل سوءا للقريب. وهكذا تكون المحبة إتماما للشريعة كلها.","13:11":"وفوق هذا، فأنتم تعرفون الوقت، وأنها الآن الساعة التي يجب أن نستيقظ فيها من النوم. فخلاصنا الآن، أقرب إلينا مما كان يوم آمنا:","13:12":"كاد الليل أن ينتهي والنهار أن يطلع. فلنطرح أعمال الظلام، ونلبس سلاح النور","13:13":"وكما في النهار، لنسلك سلوكا لائقا: لا في العربدة والسكر، ولا في الفحشاء والإباحية، ولا في النزاع والحسد.","13:14":"وإنما البسوا الرب يسوع المسيح (تمثلوا به)، ولا تنشغلوا بالتدبير للجسد لقضاء شهواته.","14:1":"ومن كان ضعيفا في الإيمان، فاقبلوه بينكم دون أن تحاكموه على أرائه.","14:2":"من الناس من يعتقد أنه يحق له أن يأكل كل شيء. وأما الضعيف فيأكل البقول.","14:3":"فمن كان يأكل كل شيء، عليه ألا يحتقر من لا يأكل، ومن كان لا يأكل، عليه ألا يدين من يأكل، لأن الله قد قبله.","14:4":"فمن أنت لتدين خادم غيرك؟ إنه في نظر سيده يثبت أو يسقط. ولسوف يثبت، لأن الرب قادر أن يثبته.","14:5":"ومن الناس من يراعي يوما دون غيره، ومنهم من يعتبر الأيام كلها متساوية. فليكن كل واحد مقتنعا برأيه في عقله.","14:6":"إن من يراعي يوما معينا، يراعيه لأجل الرب؛ ومن يأكل كل شيء، يأكل لأجل الرب، لأنه يؤدي الشكر لله؛ ومن لا يأكل، لا يأكل لأجل الرب، لأنه يؤدي الشكر لله.","14:7":"فلا أحد منا يحيا لنفسه، ولا أحد يموت لنفسه.","14:8":"فإن حيينا، فللرب نحيا؛ وإن متنا فللرب نموت. فسواء حيينا أم متنا، فإنما نحن للرب.","14:9":"فإن المسيح مات وعاد حيا لأجل هذا: أن يكون سيدا على الأموات والأحياء.","14:10":"ولكن، لماذا أنت تدين أخاك؟ وأنت أيضا، لماذا تحتقر أخاك؟ فإننا جميعا سوف نقف أمام عرش الله لنحاسب.","14:11":"فإنه قد كتب: «أنا حي، يقول الرب، لي ستنحني كل ركبة، وسيعترف كل لسان لله!»","14:12":"إذا، كل واحد منا سيؤدي حسابا عن نفسه لله.","14:13":"فلنكف عن محاكمة بعضنا بعضا، بل بالأحرى احكموا بهذا: أن لا يضع أحد أمام أخيه عقبة أو فخا.","14:14":"فأنا عالم، بل مقتنع من الرب يسوع، أنه لا شيء نجس في ذاته. أما إن اعتبر أحد شيئا ما نجسا، فهو نجس في نظره.","14:15":"فإن كنت بطعامك تسبب الحزن لأخيك، فلست تسلك بعد بما يتفق مع المحبة. لا تدمر بطعامك من لأجله مات المسيح.","14:16":"إذن، لا تعرضوا صلاحكم لكلام السوء.","14:17":"إذ ليس ملكوت الله بأكل وشرب، بل هو بر وسلام وفرح في الروح القدس.","14:18":"فمن خدم المسيح هكذا، كان مقبولا عند الله وممدوحا عند الناس.","14:19":"فلنسع إذن وراء ما يؤدي إلى السلام وما يؤدي إلى بنيان بعضنا بعضا.","14:20":"لا تدمر عمل الله بسبب الطعام! حقا إن الأطعمة كلها طاهرة، ولكن الشر في أن يأكل الإنسان شيئا يسبب العثرة.","14:21":"فمن الصواب ألا تأكل لحما ولا تشرب خمرا، ولا تفعل شيئا يتعثر فيه أخوك.","14:22":"ألك اقتناع ما؟ فليكن لك ذلك بنفسك أمام الله! طوبى لمن لا يدين نفسه في ما يستحسنه.","14:23":"وأما من يشك، فإذا أكل يحكم عليه، لأن ذلك ليس عن إيمان. وكل ما لا يصدر عن الإيمان، فهو خطيئة.","15:1":"ولكن علينا نحن الأقوياء (في الإيمان)، أن نحتمل ضعف الضعفاء (فيه)، وأن لا نرضي أنفسنا.","15:2":"فليسع كل واحد منا لإرضاء قريبه من جهة ما هو صالح، في سبيل البنيان.","15:3":"فحتى المسيح لم يسع لإرضاء نفسه، بل وفقا لما قد كتب: «تعييرات الذين يعيرونك وقعت علي».","15:4":"فإن كل ما سبق أن كتب فإنما كتب لتعليمنا، حتى يكون لنا رجاء بما في الكتاب من الصبر والعزاء.","15:5":"وليعطكم إله الصبر والتعزية أن تكونوا متوافقين بعضكم مع بعض بحسب المسيح يسوع،","15:6":"لكي تمجدوا الله أبا ربنا يسوع المسيح بنفس واحدة وفم واحد.","15:7":"لذلك اقبلوا بعضكم بعضا، كما أن المسيح أيضا قبلنا لمجد الله.","15:8":"فإني أقول إن المسيح صار خادم أهل الختان إظهارا لصدق الله وتوطيدا لوعوده للآباء،","15:9":"وإن الأمم يمجدون الله على الرحمة، وفقا لما قد كتب: «لهذا أعترف لك بين الأمم وأرتل لاسمك!»","15:10":"وأيضا قيل: «افرحوا، أيها الأمم، مع شعبه».","15:11":"وأيضا: «سبحوا الرب ياجميع الأمم، ولتحمده جميع الشعوب».","15:12":"ويقول إشعياء أيضا: «سيطلع أصل يسى، والقائم، ليسود على الأمم: عليه تعلق الشعوب الرجاء».","15:13":"فليملأكم إله الرجاء كل فرح وسلام في إيمانكم حتى تزدادوا رجاء بقوة الروح القدس.","15:14":"وأنا نفسي أيضا على يقين من جهتكم أيها الإخوة بأنكم مشحونون صلاحا، وممتلئون بكل معرفة، وقادرون أيضا على نصح بعضكم بعضا.","15:15":"على أني كتبت إليكم بأوفر جرأة في بعض الأمور، مذكرا لكم، وذلك بالنعمة التي وهبها الله لي.","15:16":"وبذلك أكون خادم المسيح يسوع، المرسل إلى الأمم، حاملا إنجيل الله وكأني أقوم بخدمة كهنوتية، بقصد أن ترفع لله من بين الأمم تقدمة تكون مقبولة ومقدسة بالروح القدس.","15:17":"يحق لي إذن أن أفتخر في المسيح يسوع بما يعود لله من خدمتي.","15:18":"فما كنت لأتجاسر أن أتكلم بشيء إلا على ما عمله المسيح على يدي لهداية الأمم إلى الطاعة، بالقول والفعل،","15:19":"وبقوة الآيات والعجائب، وبقوة روح الله. حتى إنني، من أورشليم وما حولها حتى مقاطعة إليريكون، قد أكملت التبشير بإنجيل المسيح.","15:20":"وكنت حريصا على التبشير حيث لم يكن قد عرف اسم المسيح، لكي لا أبني على أساس وضعه غيري،","15:21":"بل كما قد كتب: «الذين لم يبشروا به سوف يبصرون، والذين لم يسمعوا به سوف يفهمون».","15:22":"لهذا السبب أيضا كنت أعاق عن المجيء إليكم مرارا كثيرة.","15:23":"أما الآن، فإذ لم يبق لي مجال للعمل بعد في هذه المناطق، وبي شوق شديد إلى المجيء إليكم طوال هذه السنين الكثيرة،","15:24":"فعندما أذهب إلى أسبانيا أرجو أن أمر بكم، فأراكم وتسهلون لي متابعة السفر بعد أن أتمتع بلقائكم ولو لفترة قصيرة.","15:25":"على أني الآن ذاهب إلى أورشليم في خدمة القديسين.","15:26":"ذلك أن مؤمني مقاطعتي مقدونية وأخائية حسن لديهم أن يجمعوا إعانة للفقراء بين القديسين الذين في أورشليم.","15:27":"حسن لديهم ذلك، وهم في دين لأولئك القديسين: فإذا كان الأمم قد اشتركوا في ما هو روحي عند أولئك، فعليهم أيضا أن يخدموهم في ما هو مادي.","15:28":"فبعد انتهائي من هذه المهمة، وتسليمي هذا الثمر للقديسين،","15:29":"سأنطلق إلى أسبانيا، مارا بكم. وأعلم أني، إذا جئت إليكم، فسوف أجيء في ملء بركة المسيح.","15:30":"فأتوسل إليكم، أيها الإخوة، بربنا يسوع المسيح وبمحبة الروح، أن تجاهدوا معي في الصلوات إلى الله من أجلي،","15:31":"لكي أنجو من غير المؤمنين الذين في اليهودية، ولكي تكون خدمتي هذه للقديسين في أورشليم مقبولة عندهم،","15:32":"حتى أجيء إليكم في فرح بمشيئة الله فأنتعش عندكم وأستريح.","15:33":"وليكن إله السلام معكم جميعا. آمين!","16:1":"وأوصيكم بفيبي أختنا الخادمة في كنيسة كنخريا:","16:2":"فاقبلوها في الرب قبولا يليق بالقديسين وقدموا لها أي عون تحتاج إليه منكم، لأنها هي كانت معينة لكثيرين ولي أنا أيضا.","16:3":"سلموا على بريسكلا وأكيلا، معاوني في خدمة المسيح يسوع،","16:4":"اللذين عرضا عنقيهما للذبح إنقاذا لحياتي، ولست أنا وحدي شاكرا لهما بل جميع كنائس الأمم أيضا.","16:5":"وسلموا على الكنيسة في بيتهما. سلموا على أبينتوس، حبيبي الذي هو باكورة للمسيح من مقاطعة أسيا.","16:6":"سلموا على مريم التي أجهدت نفسها كثيرا في خدمتنا من قبلكم.","16:7":"سلموا على أندرونيكوس ويونياس، قريبي اللذين سجنا معي، وهما مشهوران بين الرسل، وقد كانا في المسيح قبلي.","16:8":"سلموا على أمبلياس، حبيبي في الرب.","16:9":"سلموا على أوربانوس، معاوننا في خدمة المسيح، وعلى إستاخيس، حبيبي.","16:10":"سلموا على أبلس، الذي برهن عن ثباته في المسيح. سلموا على ذوي أرستوبولوس.","16:11":"سلموا على هيروديون، قريبي. سلموا على ذوي نركيسوس الذين في الرب.","16:12":"سلموا على تريفينا وتريفوسا اللتين تجهدان نفسيهما في خدمة الرب. سلموا على برسيس المحبوبة، التي أجهدت نفسها كثيرا في خدمة الرب.","16:13":"سلموا على روفس المختار في الرب، وعلى أمه التي هي أم لي.","16:14":"سلموا على أسينكريتس، وفليغون، وهرمس، وبتروباس، وهرماس، وعلى الإخوة الذين معهم.","16:15":"سلموا على فيلولوغوس، وجوليا، ونيريوس، وأخته، وأولمباس، وعلى جميع القديسين الذين معهم.","16:16":"سلموا بعضكم على بعض بقبلة مقدسة. تسلم عليكم جميع كنائس المسيح.","16:17":"ولكن، أتوسل إليكم، أيها الإخوة، أن تنتبهوا إلى مثيري الانقسامات والعثرات، خلافا للتعليم الذي تعلمتم، وأن تبتعدوا عنهم.","16:18":"فإن أمثال هؤلاء لا يخدمون ربنا يسوع المسيح بل (يخدمون) بطونهم، وبكلماتهم الطيبة وأقوالهم المعسولة يضللون قلوب البسطاء.","16:19":"إن خبر طاعتكم قد بلغ الجميع. ولذلك أفرح بكم، ولكن أريد لكم أن تكونوا حكماء في ما هو خير، وبسطاء في ما هو شر.","16:20":"وإله السلام سيسحق الشيطان تحت أقدامكم سريعا. لتكن نعمة ربنا يسوع المسيح معكم.","16:21":"يسلم عليكم تيموثاوس معاوني، ولوكيوس وياسون وسوسيباترس أقربائي.","16:22":"وأنا، ترتيوس الذي أخط هذه الرسالة، أسلم عليكم في الرب.","16:23":"يسلم عليكم غايوس، المضيف لي وللكنيسة كلها. يسلم عليكم أراستس، أمين صندوق المدينة، والأخ كوارتس.","16:24":"«لتكن نعمة ربنا يسوع المسيح معكم. آمين!»","16:25":"والمجد للقادر أن يثبتكم، وفقا لإنجيلي وللبشارة بيسوع المسيح، ووفقا لإعلان ما كان سرا ظل مكتوما مدى الأزمنة الأزلية،","16:26":"ولكن أذيع الآن، بأمر الله الأزلي في الكتابات النبوية، على جميع الأمم لأجل إطاعة الإيمان؛","16:27":"المجد لله إلى الأبد، الحكيم وحده، بيسوع المسيح. آمين!"},"1Co":{"1:1":"من بولس، رسول المسيح يسوع، المدعو بمشيئة الله، ومن الأخ سوستانيس،","1:2":"إلى كنيسة الله في مدينة كورنثوس، إلى الذين تقدسوا في المسيح يسوع، المدعوين، القديسين؛ وإلى جميع الذين يدعون باسم ربنا يسوع المسيح في كل مكان ربا لهم ولنا.","1:3":"لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح!","1:4":"إني أشكر الله من أجلكم دائما، وعلى نعمة الله الموهوبة لكم في المسيح يسوع.","1:5":"فبه قد صرتم أغنياء في كل شيء، في كل كلام، وكل معرفة،","1:6":"بمقدار ما ترسخت فيكم شهادة المسيح.","1:7":"حتى إنكم لا تحتاجون بعد إلى أية موهبة فيما تتوقعون ظهور ربنا يسوع المسيح علنا.","1:8":"وهو نفسه سيحفظكم ثابتين إلى النهاية حتى تكونوا بلا عيب في يوم ربنا يسوع المسيح.","1:9":"فإن الله أمين، وقد دعاكم إلى الشركة مع ابنه يسوع ربنا.","1:10":"على أنني أيها الإخوة، أتوسل إليكم باسم ربنا يسوع المسيح أن يكون لجميعكم صوت واحد وأن لا يكون بينكم أي انقسام. وإنما كونوا جميعا موحدي الفكر والرأي.","1:11":"فقد بلغني عنكم، ياإخوتي، على لسان عائلة خلوي، أن بينكم خلافات.","1:12":"أعني أن واحدا منكم يقول: «أنا مع بولس» وآخر: «أنا مع أبلوس»، وآخر: «أنا مع بطرس»، وآخر: «أنا مع المسيح».","1:13":"فهل تجزأ المسيح؟ أم أن بولس صلب لأجلكم، أو باسم بولس تعمدتم؟","1:14":"أشكر الله لأني لم أعمد منكم أحدا غير كريسبوس وغايوس،","1:15":"حتى لا يقول أحد إنكم باسمي تعمدتم.","1:16":"ومع أني عمدت أيضا عائلة استفاناس، فلا أذكر أني عمدت أحدا غيرهم.","1:17":"فإن المسيح قد أرسلني لا لأعمد، بل لأبشر بالإنجيل، غير معتمد على حكمة الكلام، لئلا يصير صليب المسيح كأنه بلا نفع.","1:18":"لأن البشارة بالصليب جهالة عند الهالكين؛ وأما عندنا، نحن المخلصين، فهي قدرة الله.","1:19":"فإنه قد كتب: «سأبيد حكمة الحكماء وأزيل فهم الفهماء!»","1:20":"إذن، أين الحكيم؟ وأين الكاتب؟ وأين المجادل في هذا الزمان؟ ألم يقلب الله حكمة هذا العالم جهالة؟","1:21":"فبما أن العالم، في حكمة الله، لم يعرف الله عن طريق الحكمة، فقد سر الله أن يخلص بجهالة البشارة الذين يؤمنون.","1:22":"إذ إن اليهود يطلبون آيات، واليونانيين يبحثون عن الحكمة.","1:23":"ولكننا نحن نبشر بالمسيح مصلوبا، مما يشكل عائقا عند اليهود وجهالة عند الأمم؛","1:24":"وأما عند المدعوين، سواء من اليهود أو اليونانيين، فإن المسيح هو قدر ة الله وحكمة الله.","1:25":"ذلك لأن «جهالة» الله أحكم من البشر، و«ضعف» الله أقوى من البشر.","1:26":"فاتخذوا العبرة من دعوتكم أيها الإخوة: فليس بينكم كثيرون من الحكماء حكمة بشرية، ولا كثيرون من المقتدرين، ولا كثيرون من النبلاء.","1:27":"بل إن الله قد اختار ما هو جاهل في العالم ليخجل الحكماء. وقد اختار الله ما هو ضعيف في العالم ليخجل المقتدرين.","1:28":"وقد اختار الله ما كان في العالم وضيعا ومحتقرا وعديم الشأن، ليزيل ما له شأن،","1:29":"حتى لا يفتخر أي بشر أمام الله.","1:30":"وبفضل الله صار لكم مقام في المسيح يسوع الذي جعل لنا حكمة من الله وبرا وقداسة وفداء،","1:31":"حتى إن «من افتخر، فليفتخر بالرب»، على حد ما قد كتب.","2:1":"وأنا، أيها الإخوة، لما جئت إليكم لأعلن لكم شهادة الله، ما جئت بالكلام البليغ أو الحكمة.","2:2":"إذ كنت عازما ألا أعرف شيئا بينكم إلا يسوع المسيح، وأن أعرفه مصلوبا.","2:3":"وقد كنت عندكم في حالة من الضعف والخوف والارتعاد الكثير.","2:4":"ولم يقم كلامي وتبشيري على الإقناع بكلام الحكمة، بل على ما يعلنه الروح والقدرة.","2:5":"وذلك لكي يتأسس إيمانكم لا على حكمة الناس، بل على قدرة الله.","2:6":"على أن لنا حكمة نتكلم بها بين البالغين. ولكنها حكمة ليست من هذا العالم ولا من رؤساء هذا العالم الزائلين.","2:7":"بل إننا نتكلم بحكمة الله المطوية في سر، تلك الحكمة المحجوبة التي سبق الله فأعدها قبل الدهور لأجل مجدنا","2:8":"وهي حكمة لم يعرفها أحد من رؤساء هذا العالم. فلو عرفوها،","2:9":"لما صلبوا رب المجد! ولكن، وفقا لما كتب: «إن ما لم تره عين، ولم تسمع به أذن، ولم يخطر على بال بشر قد أعده الله لمحبيه!»","2:10":"ولكن الله كشف لنا ذلك بالروح. فإن الروح يتقصى كل شيء، حتى أعماق الله.","2:11":"فمن من الناس يعرف ما في الإنسان إلا روح الإنسان الذي فيه؛ وكذلك فإن ما في الله أيضا لا يعرفه أحد إلا روح الله.","2:12":"وأما نحن فقد نلنا لا روح العالم بل الروح الذي من الله، لنعرف الأمور التي وهبت لنا من قبل الله.","2:13":"ونحن نتكلم بهذه الأمور لا في كلام تعلمه الحكمة البشرية، بل في كلام يعلمه الروح القدس، معبرين عن الحقائق الروحية بوسائل روحية.","2:14":"غير أن الإنسان البشري لا يتقبل أمور روح الله إذ يعتبرها جهالة، ولا يستطيع أن يعرفها لأن تمييزها إنما يحتاج إلى حس روحي.","2:15":"أما الإنسان الروحي، فهو يميز كل شيء، ولا يحكم فيه من أحد.","2:16":"فإنه «من عرف فكر الرب؟» ومن يعلمه؟ وأما نحن، فلنا فكر المسيح!","3:1":"على أني، أيها الإخوة، لم أستطع أن أكلمكم باعتباركم روحيين، بل باعتباركم جسديين وأطفالا في المسيح.","3:2":"قد أطعمتكم لبنا لا الطعام القوي، لأنكم لم تكونوا قادرين عليه، بل إنكم حتى الآن غير قادرين.","3:3":"فإنكم مازلتم جسديين. فمادام بينكم حسد وخصام (وانقسام)، أفلا تكونون جسديين وتسلكون وفقا للبشر؟","3:4":"ومادام أحدكم يقول: «أنا مع بولس»، وآخر: «أنا مع أبلوس»، أفلا تكونون جسديين؟","3:5":"فمن هو بولس؟ ومن هو أبلوس؟ إنهما فقط خادمان آمنتم على أيديهما، وكما أنعم الرب على كل منهما.","3:6":"أنا غرست وأبلوس سقى؛ ولكن الله أنمى.","3:7":"فليس الغارس شيئا ولا الساقي، بل الله الذي يعطي النمو.","3:8":"فالغارس والساقي سواء. إلا أن كلا منهما سينال أجرته بالنسبة إلى تعبه.","3:9":"فإننا نحن جميعا عاملون معا عند الله، وأنتم حقل الله وبناء الله.","3:10":"وبحسب نعمة الله الموهوبة لي، وضعت الأساس كما يفعل البناء الماهر، وغيري يبني عليه. ولكن، لينتبه كل واحد كيف يبني عليه.","3:11":"فليس ممكنا أن يضع أحد أساسا آخر بالإضافة إلى الأساس الموضوع، وهو يسوع المسيح.","3:12":"فإن بنى أحد على هذا الأساس ذهبا وفضة وحجارة كريمة، أو خشبا وعشبا وقشا،","3:13":"فعمل كل واحد سينكشف علنا إذ يظهره ذلك اليوم الذي سيعلن في نار، وسوف تمتحن النار قيمة عمل كل واحد.","3:14":"فمن بقي عمله الذي بناه على الأساس، ينال أجرا.","3:15":"ومن احترق عمله، يخسر، إلا أنه هو سيخلص؛ ولكن كمن يمر في النار.","3:16":"ألا تعرفون أنكم هيكل الله وأن روح الله ساكن فيكم؟","3:17":"فإن دمر أحد هيكل الله، يدمره الله ، لأن هيكل الله مقدس، وهو أنتم","3:18":"حذار أن يخدع أحد منكم نفسه! إن ظن أحد بينكم نفسه حكيما في هذا العالم، فليصر جاهلا ليصير حكيما حقا.","3:19":"فإن حكمة هذا العالم هي جهالة في نظر الله. فإنه قد كتب: «إنه يمسك الحكماء بمكرهم»","3:20":"وأيضا: «الرب يعلم أفكار الحكماء ويعرف أنها باطلة!»","3:21":"إذن، لا يفتخر أحد بالبشر، لأن كل شيء هو لكم،","3:22":"أبولس أم أبلوس أم بطرس أم العالم أم الحيا ة أم الموت أم الحاضر أم المستقبل: هذه الأمور كلها لكم،","3:23":"وأنتم للمسيح، والمسيح لله.","4:1":"فلينظر إلينا الناس باعتبارنا خداما للمسيح ووكلاء على أسرار الله.","4:2":"والمطلوب من الوكلاء، قبل كل شيء، أن يوجد كل منهم أمينا.","4:3":"أما أنا، فأقل ما أهتم به هو أن يتم الحكم في من قبلكم أو من قبل محكمة بشرية. بل أنا بذاتي لست أحكم على نفسي.","4:4":"فإن ضميري لا يؤنبني بشيء، ولكني لست أعتمد ذلك لتبرير نفسي. فإن الذي يحكم في هو الرب.","4:5":"إذن، لا تحكموا في شيء قبل الأوان، ريثما يرجع الرب الذي سيسلط النور على الأشياء التي يحجبها الظلام الآن، ويكشف نيات القلوب، عندئذ ينال كل واحد حقه من المدح من عند الله!","4:6":"فيما سبق، أيها الإخوة، قدمت نفسي وأبلوس إيضاحا لكم، لتتعلموا بنا أن لا تحلقوا بأفكاركم فوق ما قد كتب، فلا يفاخر أحدكم الآخر تحزبا لأحد.","4:7":"فمن جعلك متميزا عن غيرك؟ وأي شيء مما لك لم تكن قد أخذته هبة؟ ومادمت قد أخذت، فلماذا تتباهى كأنك لم تأخذ؟","4:8":"إنكم قد شبعتم وقد اغتنيتم! قد صرتم ملوكا وتخليتم عنا! ويا ليتكم ملوك حقا فنشترك معكم في الملك!","4:9":"فإني أرى أن الله عرضنا، نحن الرسل، في آخر الموكب كأنه محكوم علينا بالموت، لأننا صرنا معرضا للعالم، للملائكة والبشر معا.","4:10":"نحن جهلاء من أجل المسيح، وأنتم حكماء في المسيح. نحن ضعفاء وأنتم أقوياء. أنتم مكرمون ونحن مهانون.","4:11":"فما زلنا حتى هذه الساعة نجوع ونعطش، ونعرى ونلطم ونحرم محلا للإقامة","4:12":"ونجهد أنفسنا في الشغل بأيدينا. نتعرض للإهانة فنبارك، وللاضطهاد فنحتمل","4:13":"وللتجريح فنسالم. صرنا كأقذار العالم ونفاية الجميع، ومازلنا!","4:14":"لا أكتب هذا تخجيلا لكم، بل أنبهكم باعتباركم أولادي الأحباء.","4:15":"فقد يكون لكم عشر ة آلاف من المرشدين في المسيح، ولكن ليس لكم آباء كثيرون! لأني أنا ولدتكم في المسيح يسوع بالإنجيل.","4:16":"فأدعوكم إذن إلى الاقتداء بي.","4:17":"لهذا السبب عينه أرسلت إليكم تيموثاوس، ابني الحبيب الأمين في الرب، فهو يذكركم بطرقي في السلوك في المسيح كما أعلم بها في كل مكان في جميع الكنائس.","4:18":"فإن بعضا منكم ظنوا أني لن آتي إليكم فانتفخوا تكبرا!","4:19":"ولكني سآتي إليكم عاجلا، إن شاء الرب، فأختبر لا كلام هؤلاء المنتفخين بل قوتهم.","4:20":"فإن ملكوت الله ليس بالكلام، بل بالقدرة.","4:21":"كيف تفضلون أن آتي إليكم: أبالعصا أو بالمحبة وروح الوداعة؟","5:1":"قد شاع فعلا أن بينكم زنى. ومثل هذا الزنى لا يوجد حتى بين الأمم. ذلك بأن رجلا منكم يعاشر زوجة أبيه.","5:2":"ومع ذلك، فأنتم منتفخون تكبرا، بدلا من أن تنوحوا حتى يستأصل من بينكم مرتكب هذا الفعل!","5:3":"فإني، وأنا غائب عنكم بالجسد ولكن حاضر بينكم بالروح، قد حكمت على الفاعل كأني حاضر:","5:4":"باسم ربنا يسوع المسيح، إذ تجتمعون معا، وروحي معكم، فبسلطة ربنا يسوع المسيح،","5:5":"تقررون تسليم مرتكب هذا الفعل إلى الشيطان، ليهلك جسده؛ أما روحه فتخلص في يوم الرب يسوع.","5:6":"إن افتخاركم ليس في محله! ألستم تعلمون أن خميرة صغيرة تخمر العجين كله؟","5:7":"فاعزلوا الخميرة العتيقة من بينكم لتكونوا عجينا جديدا، لأنكم فطير ! فإن حمل فصحنا، أي المسيح، قد ذبح.","5:8":"فلنعيد إذن، لا بخميرة عتيقة، ولا بخميرة الخبث والشر، بل بفطير الخلاص والحق.","5:9":"كتبت إليكم في رسالتي أن لا تعاشروا الزناة.","5:10":"فلا أعني زناة هذا العالم أو الطماعين أو السراقين أو عابدي الأصنام على وجه الإطلاق، وإلا كنتم مضطرين إلى الخروج من المجتمع البشري!","5:11":"أما الآن فقد كتبت إليكم بأن لا تعاشروا من يسمى أخا إن كان زانيا أو طماعا أو عابد أصنام أو شتاما أو سكيرا أو سراقا. فمثل هذا لا تعاشروه ولا تجلسوا معه لتناول الطعام.","5:12":"فما لي وللذين خارج (الكنيسة) حتى أدينهم؟ ألستم أنتم تدينون الذين داخلها؟","5:13":"أما الذين في الخارج، فالله يدينهم. فاعزلوا من هو شرير من بينكم.","6:1":"إذا كان بينكم من له دعوى على آخر، فهل يجرؤ أن يقيمها لدى الظالمين وليس لدى القديسين؟","6:2":"أما تعلمون أن القديسين سيدينون العالم؟ وما دمتم ستدينون العالم، أفلا تكونون أهلا لأن تحكموا في القضايا البسيطة؟","6:3":"أما تعلمون أننا سندين الملائكة؟ أفليس أولى بنا أن نحكم في قضايا هذه الحياة؟","6:4":"إذن، إن كان بينكم خلاف في قضايا هذه الحياة، فأجلسوا صغار الشأن في الكنيسة للقضاء.","6:5":"أقول هذا تخجيلا لكم. أهكذا ليس بينكم حتى حكيم واحد يقدر أن يقضي بين إخوته!","6:6":"غير أن الأخ يقاضي أخاه، وذلك لدى غير المؤمنين.","6:7":"والواقع أنه من العيب على الإطلاق أن يقاضي بعضكم بعضا. أما كان أحر ى بكم أن تحتملوا الظلم وأحرى بكم أن تتقبلوا السلب؟","6:8":"ولكنكم أنتم تظلمون وتسلبون حتى إخوتكم.","6:9":"أما تعلمون أن الظالمين لن يرثوا ملكوت الله؟ لا تضلوا: فإن ملكوت الله لن يرثه الزناة ولا عابدو الأصنام ولا الفاسقون ولا المتخنثون ولا مضاجعو الذكور","6:10":"ولا السراقون ولا الطماعون ولا السكيرون ولا الشتامون ولا المغتصبون.","6:11":"وهكذا كان بعضكم، إلا أنكم قد اغتسلتم، بل تقدستم، بل تبررتم، باسم الرب يسوع المسيح وبروح إلهنا.","6:12":"كل شيء حلال لي، ولكن ليس كل شيء ينفع. كل شيء حلال لي، ولكني لن أدع أي شيء يسود علي.","6:13":"الطعام للبطن، والبطن للطعام؛ ولكن الله سيبيد هذا وذاك. غير أن الجسد ليس للزنى، بل للرب؛ والرب للجسد.","6:14":"والله قد أقام الرب من الموت، وسيقيمنا نحن أيضا بقدرته!","6:15":"أما تعلمون أن أجسادكم هي أعضاء المسيح؟ فهل يجوز أن آخذ أعضاء المسيح وأجعلها أعضاء زانية؟ حاشا!","6:16":"أوما تعلمون أن من اقترن بزانية صار معها جسدا واحدا؟ فإنه يقول: «إن الاثنين يصيران جسدا واحدا».","6:17":"وأما من اقترن بالرب، فقد صار معه روحا واحدا!","6:18":"اهربوا من الزنا! فكل خطيئة يرتكبها الإنسان هي خارجة عن جسده، وأما من يرتكب الزنا، فهو يسيء إلى جسده الخاص.","6:19":"أما تعلمون أن جسدكم هو هيكل للروح القدس الساكن فيكم والذي هو لكم من الله، وأنكم أنتم لستم ملكا لأنفسكم؟","6:20":"لأنكم قد اشتريتم بفدية. إذن، مجدوا الله في أجسادكم.","7:1":"وأما بخصوص المسائل التي كتبتم لي عنها، فإنه يحسن بالرجل ألا يمس امر أة.","7:2":"ولكن، تجنبا للزنا، ليكن لكل رجل زوجته، ولكل امرأة زوجها.","7:3":"وليوف الزوج زوجته حقها الواجب، وكذلك الزوجة حق زوجها.","7:4":"فلا سلطة للمرأة على جسدها، بل لزوجها. وكذلك أيضا لا سلطة للزوج على جسده، بل لزوجته.","7:5":"فلا يمنع أحدكما الآخر عن نفسه إلا حين تتفقان معا على ذلك، ولفترة معينة، بقصد التفرغ للصلاة. وبعد ذلك عودا إلى علاقتكما السابقة، لكي لا يجربكما الشيطان لعدم ضبط النفس.","7:6":"وإنما الآن أقول هذا على سبيل النصح لا الأمر؛","7:7":"فأنا أتمنى أن يكون جميع الناس مثلي. غير أن لكل إنسان موهبة خاصة به من عند الله: فبعضهم على الحال وبعضهم على تلك.","7:8":"على أني أقول لغير المتزوجين وللأرامل إنه يحسن بهم أن يبقوا مثلي.","7:9":"ولكن إذا لم يمكنهم ضبط أنفسهم، فليتزوجوا. لأن الزواج أفضل من التحرق.","7:10":"أما المتزوجون، فأوصيهم لا من عندي بل من عند الرب، ألا تنفصل الزوجة عن زوجها،","7:11":"وإن كانت قد انفصلت عنه، فلتبق غير متزوجة، أو فلتصالح زوجها وعلى الزوج ألا يترك زوجته.","7:12":"وأما الآخرون، فأقول لهم أنا، لا الرب: إن كان لأخ زوجة غير مؤمنة، وترتضي أن تساكنه، فلا يتركها.","7:13":"وإن كان لامرأة زوج غير مؤمن، ويرتضي أن يساكنها، فلا تتركه.","7:14":"ذلك لأن الزوج غير المؤمن قد تقدس في زوجته، والزوجة غير المؤمنة قد تقدست في زوجها. وإلا كان الأولاد في مثل هذا الزواج نجسين، والحال أنهم مقدسون.","7:15":"ولكن إن انفصل الطرف غير المؤمن، فلينفصل؛ فليس الأخ أو الأخت تحت ارتباط في مثل هذه الحالات، وإنما الله دعاكم إلى العيش بسلام.","7:16":"فكيف تعلمين، أيتها الزوجة، ما إذا كان زوجك سيخلص على يدك؟ أو كيف تعلم، أيها الزوج، ما إذا كانت زوجتك ستخلص على يدك؟","7:17":"وفي كل حال، ليسلك كل واحد في حياته كما قسم له الرب وكما دعاه الله هذا هو المبدأ الذي آمر به في الكنائس كلها.","7:18":"فمن دعي وهو مختون، فلا يصر كغير المختون، ومن دعي وهو غير مختون، فلا يصر كالمختون.","7:19":"إن الختان ليس شيئا، وعدم الختان ليس شيئا، بل المهم هو العمل بوصايا الله.","7:20":"فليبق كل واحد على الحال التي كان عليها حين دعاه الله .","7:21":"أكنت عبدا حين دعيت؟ فلا يهمك ذلك. لا بل إن سنحت لك الفرصة لتصير حرا، فأحرى بك أن تغتنمها.","7:22":"فإن من دعي في الرب وهو عبد، صار معتقا للرب. وكذلك أيضا من دعي وهو حر، صار عبدا للمسيح.","7:23":"قد اشتريتم بفدية، فلا تصيروا عبيدا للبشر.","7:24":"فليبق كل واحد، أيها الإخوة، مع الله على الحال التي كان عليها حين دعي.","7:25":"وأما العزاب، فليس عندي لهم وصية خاصة من الرب، ولكني أعطي رأيا باعتباري نلت رحمة من الرب لأكون جديرا بالثقة.","7:26":"فلسبب الشدة الحالية، أظن أنه يحسن بالإنسان أن يبقى على حاله.","7:27":"فإن كنت مرتبطا بزوجة، فلا تطلب الفراق، وإن كنت غير مرتبط بزوجة، فلا تطلب زوجة.","7:28":"ولكن، إن تزوجت، فأنت لا تخطيء. وإن تزوجت العذراء، فهي لا تخطيء. ولكن أمثال هؤلاء يلاقون مشقات معيشية، وأنا إنما أريد حمايتكم منها.","7:29":"فإني، أيها الإخوة، أقول لكم إن الوقت يتقاصر. ففي ما يخص المسائل الأخرى، ليكن الذين لهم زوجات كأنهم بلا زوجات،","7:30":"والذين يبكون كأنهم لا يبكون، والذين يفرحون كأنهم لا يفرحون، والذين يشترون كأنهم لا يملكون،","7:31":"والذين يستغلون هذا العالم كأنهم لا يستغلونه. ذلك لأن طراز هذا العالم زائل.","7:32":"فأريد لكم أن تكونوا بلا هم. إن غير المتزوج يهتم بأمور الرب","7:33":"وهدفه أن يرضي الرب. أما المتزوج فيهتم بأمور العالم وهدفه أن يرضي زوجته،","7:34":"فاهتمامه منقسم. كذلك غير المتزوجة والعزباء تهتمان بأمور الرب وهدفهما أن تكونا مقدستين جسدا وروحا. أما المتزوجة فتهتم بأمور العالم وهدفها أن ترضي زوجها.","7:35":"أقول هذا من أجل مصلحتكم، لا لأنصب فخا أمامكم، بل في سبيل ما يليق ويجعل اهتمامكم منصرفا إلى الرب دون ارتباك.","7:36":"ولكن، إن ظن أحد أنه يتصرف تصرفا غير لائق نحو عزوبيته إذا تجاوز السن، وأنه لابد من الزواج، فليفعل ما يشاء. إنه لا يخطيء. فليتزوج العزاب في هذه الحال.","7:37":"وأما من عقد العزم في قلبه، ولم يكن مضطرا، بل كان كامل السيطرة على إرادته، واختار من تلقاء نفسه أن يحافظ على عزوبيته، فحسنا يفعل.","7:38":"إذن، من تزوج فعل حسنا، ومن لا يتزوج يفعل أحسن.","7:39":"إن الزوجة تظل تحت ارتباط مادام زوجها حيا. فإذا رقد زوجها، تصير حرة يحق لها أن تتزوج من أي رجل تريده، إنما في الرب فقط.","7:40":"ولكنها، برأيي، تكون أسعد إذا بقيت على حالها، وأظن أن عندي، أنا أيضا، روح الله!","8:1":"وأما فيما يتعلق بالذبائح المقدمة للأصنام، فنعلم أن المعرفة لجميعنا. غير أن المعرفة تنفخ تكبرا، ولكن المحبة تبني. فمن ظن أنه يعرف شيئا،","8:2":"فهو لا يعرف شيئا بعد حق المعرفة.","8:3":"أما الذي يحب الله ، فإن الله يعرفه.","8:4":"ففيما يخص الأكل من ذبائح الأصنام، نحن نعلم أن الصنم ليس بإله موجود في الكون، وأنه لا وجود إلا لإله واحد.","8:5":"حتى لو كانت الآلهة المزعومة موجودة في السماء أو على الأرض وما أكثر تلك الآلهة والأرباب!","8:6":"فليس عندنا نحن إلا إله واحد هو الآب الذي منه كل شيء، ونحن له؛ ورب واحد هو يسوع المسيح الذي به كل شيء ونحن به.","8:7":"على أن هذه الحقيقة لا يعرفها الجميع: فبعضهم قد تعودوا الظن بأن الأصنام موجودة فعلا، ومازالوا يأكلون من تلك الذبائح كأنها فعلا مقدمة لها، فيتدنس ضميرهم بسبب ضعفه.","8:8":"إلا أن الطعام لا يقربنا إلى الله، فإننا إن أكلنا منه لا يعلو مقامنا، وإن لم نأكل منه لا يصغر شأننا!","8:9":"ولكن خذوا حذركم لكي لا يكون حقكم هذا فخا يسقط فيه الضعفاء.","8:10":"فياصاحب المعرفة، إن رآك أحد جالسا إلى الطعام في هيكل للأصنام، أفلا يتقوى ضميره، هو الضعيف، ليأكل من ذبائح الأصنام،","8:11":"وبذلك يتدمر ذلك الضعيف، وهو أخ لك مات المسيح من أجله، بسبب معرفتك!","8:12":"فإذ تخطئون هكذا إلى الإخوة فتجرحون ضمائرهم الضعيفة، إنما تخطئون إلى المسيح.","8:13":"لذا، إن كان بعض الطعام فخا يسقط فيه أخي، فلن آكل لحما أبدا، لكي لا أسقط أخي!","9:1":"ألست أنا حرا؟ أولست رسولا؟ أما رأيت يسوع ربنا؟ ألستم أنتم عمل يدي في الرب؟","9:2":"إن لم أكن رسولا إلى غيركم، فإنما أنا رسول إليكم، لأنكم ختم رسوليتي في الرب.","9:3":"وهذا هو دفاعي لدى الذين يستجوبونني:","9:4":"أليس لنا حق أن نأكل ونشرب؟","9:5":"أليس لنا حق أن نتخذ إحدى الأخوات زوجة ترافقنا، كما يفعل الرسل الآخرون وإخوة الرب، وبطرس؟","9:6":"أم أنا وبرنابا وحدنا لا حق لنا أن ننقطع عن العمل؟","9:7":"أي جندي يذهب إلى الحرب على نفقته الخاصة؟ وأي مزارع يغرس كرما ولا يأكل من ثماره؟ أم أي راع يرعى قطيعا ولا يأكل من لبن القطيع؟","9:8":"أتظنون أني أتكلم بهذا بمنطق البشر؟ أو ما توصي الشريعة به؟","9:9":"فإنه مكتوب في شريعة موسى: «لا تضع كمامة على فم الثور وهو يدرس الحنطة». ترى، هل تهم الله الثيران،","9:10":"أم يقول ذلك كله من أجلنا؟ نعم، فمن أجلنا قد كتب ذلك، لأنه من حق الفلاح أن يفلح برجاء، والدراس أن يدرس برجاء، على أمل الاشتراك في الغلة.","9:11":"وما دمنا نحن قد زرعنا لكم الأمور الروحية، فهل يكون كثيرا علينا أن نحصد منكم الأمور المادية؟","9:12":"إن كان لغيرنا هذا الحق عليكم، أفلا نكون نحن أحق؟ ولكننا لم نستعمل هذا الحق؟ بل نتحمل كل شيء، مخافة أن نضع أي عائق أمام إنجيل المسيح !","9:13":"أما تعلمون أن الذين يشتغلون بالمقدسات كانوا يأكلون مما يقدم إلى الهيكل، وأن الذين يقومون بخدمة المذبح، كانوا يشتركون في خيرات المذبح؟","9:14":"هكذا أيضا رسم الرب للذين يبشرون بالإنجيل أن يعيشوا من الإنجيل.","9:15":"على أني لم أستعمل أيا من هذه الحقوق. وما كتبت هذا الآن لأحظى بشيء. فإني أفضل الموت على أن يعطل أحد فخري.","9:16":"فمادمت أبشر بالإنجيل، فليس في ذلك فخر لي، لأنه واجب مفروض علي فالويل لي إن كنت لا أبشر!","9:17":"فإن قمت بذلك متطوعا، كانت لي مكافأة. ولكن، إن كنت مرغما، فأنا مؤتمن على مسئولية،","9:18":"فما هي مكافأتي إذن؟ هي أني في تبشيري أجعل الإنجيل بلا كلفة، غير مستغل كامل حقي لقاء التبشير بالإنجيل.","9:19":"فمع أني حر من الجميع، جعلت نفسي عبدا للجميع، لأكسب أكبر عدد ممكن منهم.","9:20":"فصرت لليهود كأني يهودي، حتى أكسب اليهود؛ وللخاضعين للشريعة كأني خاضع لها مع أني لست خاضعا لها حتى أكسب الخاضعين لها؛","9:21":"وللذين بلا شريعة كأني بلا شريعة مع أني لست بلا ناموس عند الله بل أنا خاضع لناموس من نحو المسيح حتى أكسب الذين هم بلا شريعة.","9:22":"وصرت للضعفاء ضعيفا، حتى أكسب الضعفاء. صرت للجميع كل شيء، لأنقذ بعضا منهم مهما كلف الأمر.","9:23":"وإني أفعل الأمور كلها من أجل الإنجيل، لأكون شريكا فيه مع الآخرين.","9:24":"أما تعلمون أن المتبارين يركضون جميعا في الميدان ولكن واحدا منهم فقط يفوز بالجائزة؟ هكذا اركضوا أنتم حتى تفوزوا!","9:25":"وكل متبار يفرض على نفسه تدريبا صارما في شتى المجالات. فهؤلاء المتبارون يفعلون ذلك ليفوزوا بإكليل فان، وأما نحن فلنفوز بإكليل غير فان.","9:26":"إذن، أنا أركض هكذا، لا كمن لا هدف له، وهكذا ألاكم أيضا، لا كمن يلطم الهواء،","9:27":"بل أسدد اللكمات إلى جسدي وأسوقه أسيرا، مخافة أن يتبين أني غير مؤهل (للمجازاة) بعدما دعوت الآخرين إليها!","10:1":"فإني لا أريد أن يخفى عليكم، أيها الأخوة أن آباءنا كانوا كلهم تحت السحابة، واجتازوا كلهم في البحر،","10:2":"فتعمدوا كلهم أتباعا لموسى، في السحابة وفي البحر،","10:3":"وأكلوا كلهم طعاما واحدا له رمز روحي،","10:4":"وشربوا كلهم شرابا واحدا له رمز روحي، إذ شربوا من صخرة روحية تبعتهم، وقد كانت هذه الصخرة هي المسيح.","10:5":"ومع ذلك، فإن الله لم يرتض بأكثرهم إذ طرحوا قتلى في الصحراء.","10:6":"وإنما حدثت هذه الأمور لتكون مثالا لنا، حتى لا نشتهي أمورا شريرة كما اشتهى أولئك.","10:7":"فلا تكونوا عابدين للأصنام كما كان بعضهم، كما قد كتب: «جلس الشعب للأكل والشرب، ثم قاموا للرقص واللهو».","10:8":"ولا نرتكب الزنا كما فعل بعضهم، فسقط في يوم واحد ثلاثة وعشرون ألفا.","10:9":"ولا نجرب الرب كما جربه بعضهم، فأهلكتهم الحيات.","10:10":"ولا تتذمروا، كما تذمر بعضهم، فهلكوا على يد الملاك المهلك.","10:11":"فهذه الأمور كلها حدثت لهم لتكون مثالا، وقد كتبت إنذارا لنا، نحن الذين تناهت إلينا أواخر الأزمنة.","10:12":"فمن توهم أنه صامد، فليحذر أن يسقط.","10:13":"لم يصبكم من التجارب إلا ما هو بشري. ولكن الله أمين وجدير بالثقة، فلا يدعكم تجربون فوق ما تطيقون، بل يدبر لكم مع التجربة سبيل الخروج منها لتطيقوا احتمالها.","10:14":"لذلك، ياأحبائي، اهربوا من عبادة الأصنام.","10:15":"إني أكلمكم كلامي لأذكياء: فاحكموا أنتم في ما أقول.","10:16":"أليست كأس البركة التي نباركها هي شركة دم المسيح؟ أو ليس رغيف الخبز الذي نكسره هو الاشتراك في جسد المسيح؟","10:17":"فإننا نحن الكثيرين رغيف واحد، أي جسد واحد، لأننا جميعا نشترك في الرغيف الواحد.","10:18":"انظروا إلى إسرائيل باعتباره بشرا: أما يجمع بين آكلي الذبائح اشتراكهم في المذبح؟","10:19":"فماذا أعني إذن؟ أأن ما ذبح للصنم له قيمة أو أن الصنم له قيمة؟","10:20":"لا، بل أن ما يذبحه الوثنيون فإنما يذبحونه للشياطين وليس لله. وإني لا أريد لكم أن تكونوا مشتركين مع الشياطين.","10:21":"فلا تستطيعون أن تشربوا كأس الرب وكأس الشياطين معا، ولا أن تشتركوا في مائدة الرب ومائدة الشياطين معا،","10:22":"أم نحاول إثارة غيرة الرب؟ أو نحن أقوى منه؟","10:23":"كل شيء حلال، ولكن ليس كل شيء ينفع. كل شيء حلال، ولكن ليس كل شيء يبني.","10:24":"فلا يسع أحد إلى مصلحة نفسه، بل إلى مصلحة غيره!","10:25":"فكل ما يباع في الملحمة، لكم أن تأكلوا منه، دونما استفهام لإرضاء الضمير.","10:26":"فإن الأرض وكل ما فيها للرب.","10:27":"أما إذا دعاكم أحد من غير المؤمنين، وأردتم أن ترافقوه، فكلوا من كل ما يقدمه لكم، دونما استفهام لإرضاء الضمير.","10:28":"ولكن إن قال لكم أحد: «هذه ذبيحة مقدمة لإله»، فلا تأكلوا منها مراعاة لمن أخبركم وإرضاء للضمير.","10:29":"وبقولي «الضمير» لا أعني ضميرك أنت بل ضمير الآخر. ولماذا يتحكم ضمير غيري بحريتي؟","10:30":"ومادمت أتناول شيئا وأشكر عليه، فلماذا يقال في سوء لأجل ما أشكر عليه؟","10:31":"فإذا أكلتم أو شربتم أو مهما فعلتم، فافعلوا كل شيء لتمجيد الله.","10:32":"لا تضعوا عائقا يسبب السقوط لأحد، سواء من اليهود أم اليونانيين أم كنيسة الله.","10:33":"فهكذا أنا أيضا أسعى لإرضاء الجميع في كل شيء، ولا أهتم بمصلحتي الخاصة، بل بمصلحة الكثيرين، لكي يخلصوا.","11:1":"فاقتدوا بي كما أقتدي أنا بالمسيح!","11:2":"إني أمدحكم لأنكم تذكرونني في كل أمر وتحافظون على التعاليم كما سلمتها إليكم.","11:3":"ولكني أريد أن تعلموا أن المسيح هو الرأس لكل رجل؛ أما رأس المرأة فهو الرجل، ورأس المسيح هو الله .","11:4":"فكل رجل يصلي أو يتنبأ، وعلى رأسه غطاء، يجلب العار على رأسه.","11:5":"وكل امرأة تصلي أو تتنبأ، وليس على رأسها غطاء، تجلب العار على رأسها، لأن كشف الغطاء كحلق الشعر تماما.","11:6":"فإذا كانت المرأة لا تغطي رأسها، فليقص شعرها! ولكن، مادام من العار على المرأة أن يقص شعرها أو يحلق، فلتغط رأسها.","11:7":"ذلك لأن الرجل عليه ألا يغطي رأسه، باعتباره صورة الله ومجده. وأما المرأة فهي مجد الرجل.","11:8":"فإن الرجل لم يؤخذ من المرأة، بل المرأة أخذت من الرجل؛","11:9":"والرجل لم يوجد لأجل المرأة، بل المرأة وجدت لأجل الرجل.","11:10":"لذا يجب على المرأة أن تضع على رأسها علامة الخضوع، من أجل الملائكة.","11:11":"غير أنه في الرب ليست المرأة من دون الرجل، ولا الرجل من دون المرأة.","11:12":"فكما أن المرأة أخذت من الرجل، فإن الرجل يكتمل بالمرأة، وإنما كل شيء هو من الله.","11:13":"فاحكموا إذن بأنفسكم: أمن اللائق أن تصلي المرأة إلى الله وهي مكشوفة الرأس؟","11:14":"أما تعلمكم الطبيعة نفسها أن إرخاء الرجل لشعره عار عليه،","11:15":"في حين أن إرخاء المرأة لشعرها مفخرة لها، لأن الشعر أعطي لها بمثابة حجاب.","11:16":"أما إذا رغب أحد في إظهار المشاكسة، فليس لنا نحن مثل هذه العادة ولا لكنائس الله!","11:17":"على أني، إذ أنتقل الآن لأوصيكم بهذا، لست أمدحكم، لأن اجتماعاتكم تضر أكثر مما تنفع.","11:18":"فأولا، سمعت أنكم، حين تجتمع جماعتكم، يكون بينكم شقاق. وأكاد أصدق ذلك،","11:19":"لأنه لابد من وجود المذاهب بينكم، حتى يبرز الفاضلون فيكم.","11:20":"فحين تجتمعون معا في مكان واحد، لا تجتمعون لأكل عشاء الرب،","11:21":"لأن كل واحد يسبق غيره ليتناول عشاءه الخاص، فيظل الواحد جائعا، ويشرب الآخر حتى يسكر!","11:22":"أفليس عندكم بيوت تأكلون وتشربون فيها؟ أم إنكم تحتقرون كنيسة الله وتهينون الذين لا يملكون شيئا؟ فماذا أقول لكم؟ أأمدحكم؟ على هذا لست أمدحكم!","11:23":"فإني قد تسلمت من الرب ما سلمتكم إياه. وهو أن الرب يسوع، في الليلة التي أسلم فيها، أخذ خبزا،","11:24":"وشكر، ثم كسر الخبز وقال: «هذا هو جسدي الذي يكسر من أجلكم اعملوا هذا لذكري».","11:25":"وكذلك أخذ الكأس بعد العشاء، وقال: «هذه الكأس هي العهد الجديد بدمي اعملوا هذا، كلما شربتم، لذكري».","11:26":"إذن، كلما أكلتم هذا الخبز وشربتم هذه الكأس، تعلنون موت الرب، إلى أن يرجع.","11:27":"فمن أكل الخبز، أو شرب كأس الرب بغير استحقاق، يكون مذنبا تجاه جسد الرب ودمه.","11:28":"ولكن، ليفحص الإنسان نفسه، ثم يأكل من الخبز ويشرب من الكأس.","11:29":"لأن الآكل والشارب يأكل ويشرب الحكم على نفسه إذ لا يميز جسد الرب.","11:30":"لهذا السبب فيكم كثيرون من الضعفاء والمرضى، وكثيرون يرقدون.","11:31":"فلو كنا حكمنا على نفوسنا، لما كان حكم علينا.","11:32":"ولكن، ما دام قد حكم علينا، فإننا نؤدب من قبل الرب حتى لا ندان مع العالم.","11:33":"فيا إخوتي، عندما تجتمعون معا للأكل، انتظروا بعضكم بعضا.","11:34":"وإن كان أحد جائعا فليأكل في بيته، لكي لا يكون اجتماعكم للحكم عليكم. أما المسائل الأخرى، فعندما آتي أرتبها.","12:1":"وأما بخصوص المواهب الروحية، أيها الإخوة، فلا أريد أن يخفى عليكم أمرها.","12:2":"تعلمون أنكم، عندما كنتم من الأمم، كنتم تنجرفون إلى الأصنام الخرساء أيما انجراف.","12:3":"لذلك أقول لكم أن تعرفوا أنه لا أحد وهو يتكلم بروح الله يقول: «اللعنة على يسوع!» وكذلك لا يستطيع أحد أن يقول: «يسوع رب» إلا بالروح القدس.","12:4":"هناك مواهب مختلفة، ولكن الروح واحد.","12:5":"وهناك خدمات مختلفة، والرب واحد.","12:6":"وهناك أيضا أعمال مختلفة، ولكن الله واحد، وهو يعمل كل شيء في الجميع.","12:7":"وإنما كل واحد يوهب موهبة يتجلى الروح فيها لأجل المنفعة.","12:8":"فواحد يوهب، عن طريق الروح، كلام الحكمة، وآخر كلام المعرفة وفقا للروح نفسه،","12:9":"وآخر إيمانا بالروح نفسه. ويوهب آخر موهبة شفاء الأمراض بالروح الواحد،","12:10":"وآخر عمل المعجزات، وآخر النبوءة وآخر التمييز بين الأرواح، وآخر التكلم بلغات مختلفة (لم يتعلمها)، وآخر ترجمة اللغات تلك.","12:11":"ولكن هذا كله يشغله الروح الواحد نفسه، موزعا المواهب، كما يشاء، على كل واحد.","12:12":"فكما أن الجسد واحد وله أعضاء كثيرة، ولكن أعضاء الجسد كلها تشكل جسما واحدا مع أنها كثيرة، فكذلك حال المسيح أيضا.","12:13":"فإننا، بالروح الواحد، قد تعمدنا جميعا لنصير جسدا واحدا، سواء كنا يهودا أم يونانيين، عبيدا أم أحرارا، وقد سقينا جميعا الروح الواحد.","12:14":"فليس الجسد عضوا واحدا بل مجموعة أعضاء.","12:15":"فإن قالت الرجل: «لأني لست يدا، لست من الجسد!» فهل تصبح من خارج الجسد فعلا؟","12:16":"وإن قالت الأذن: «لأني لست عينا، لست من الجسد!» فهل تصبح من خارج الجسد فعلا؟","12:17":"فلو كان الجسد كله عينا، فكيف كنا نسمع؟ ولو كان كله أذنا، فكيف كنا نشم؟","12:18":"على أن الله قد رتب كلا من الأعضاء في الجسد كما أراد.","12:19":"فلو كانت كلها عضوا واحدا، فكيف يتكون الجسد؟","12:20":"فالواقع أن الأعضاء كثيرة، والجسد واحد.","12:21":"وهكذا، لا تستطيع العين أن تقول لليد: «أنا لا أحتاج إليك!» ولا الرأس أن تقول للرجلين: «أنا لا أحتاج إليكما!»،","12:22":"بل بالأحرى جدا، أعضاء الجسد التي تبدو أضعف الأعضاء هي ضرورية،","12:23":"وتلك التي نعتبرها أقل ما في الجسد كرامة، نكسوها بإكرام أوفر. والأعضاء غير اللائقة يكون لها لياقة أوفر؛","12:24":"أما اللائقة، فلا تحتاج إلى ذلك. ولكن الله أحكم صنع الجسد بجملته، معطيا كرامة أوفر لما تنقصه الكرامة،","12:25":"لكي لا يكون في الجسد انقسام بل يكون بين الأعضاء اهتمام واحد لمصلحة الجسد.","12:26":"فحين يصيب الألم واحدا من الأعضاء، تشعر الأعضاء الباقية معه بالألم. وحين ينال واحد من الأعضاء إكراما، تفرح معه الأعضاء الباقية.","12:27":"فالواقع أنكم أنتم جميعا جسد المسيح، وأعضاء فيه كل بمفرده.","12:28":"وقد رتب الله في الكنيسة أشخاصا مخصوصين: أولا الرسل، ثانيا الأنبياء، ثالثا المعلمين، وبعد ذلك أصحاب المواهب المعجزية أو مواهب الشفاء أو إعانة الآخرين أو تدبير الشؤون أو التكلم باللغات المختلفة.","12:29":"فهل هم جميعا رسل؟ أجميعهم أنبياء؟ أجميعهم معلمون؟ أجميعهم حائزون على مواهب معجزية؟","12:30":"أجميعهم يملكون مواهب الشفاء؟ أجميعهم يتكلمون بلغات؟ أجميعهم يترجمون؟","12:31":"ولكن تشوقوا إلى المواهب العظمى. وها أنا أرسم لكم بعد طريقا أفضل جدا…","13:1":"... لو كنت أتكلم بلغات الناس والملائكة وليس عندي محبة، لما كنت إلا نحاسا يطن وصنجا يرن!","13:2":"ولو كانت لي موهبة النبوءة، وكنت عالما بجميع الأسرار والعلم كله، وكان عندي الإيمان كله حتى أنقل الجبال، وليس عندي محبة، فلست شيئا!","13:3":"ولو قدمت أموالي كلها للإطعام، وسلمت جسدي لأحرق، وليس عندي محبة، لما كنت أنتفع شيئا.","13:4":"المحبة تصبر طويلا؛ وهي لطيفة. المحبة لا تحسد. المحبة لا تتفاخر ولا تتكبر.","13:5":"لا تتصرف بغير لياقة، ولا تسعى إلى مصلحتها الخاصة. لا تستفز سريعا، ولا تنسب الشر لأحد.","13:6":"لا تفرح بالظلم، بل تفرح بالحق.","13:7":"إنها تستر كل شيء، وتصدق كل شيء، وترجو كل شيء، وتتحمل كل شيء.","13:8":"المحبة لا تزول أبدا. أما مواهب النبوآت فستزال، ومواهب اللغات ستنقطع، والمعرفة ستزال.","13:9":"فإن معرفتنا جزئية ونبوءتنا جزئية.","13:10":"ولكن، عندما يأتي ما هو كامل، يزال ما هو جزئي.","13:11":"فلما كنت طفلا، كنت أتكلم كالطفل، وأشعر كالطفل، وأفكر كالطفل. ولكن، لما صرت رجلا، أبطلت ما يخص الطفل.","13:12":"ونحن الآن ننظر إلى الأمور من خلال زجاج قاتم فنراها بغموض. إلا أننا سنراها أخيرا مواجهة. الآن، أعرف معرفة جزئية. ولكني، عندئذ، سأعرف مثلما عرفت.","13:13":"أما الآن، فهذه الثلاثة باقية: الإيمان، والرجاء، والمحبة. ولكن أعظمها هي المحبة!","14:1":"اسعوا وراء المحبة، وتشوقوا إلى المواهب الروحية، بل بالأحرى موهبة التنبوء.","14:2":"ذلك لأن الذي يتكلم بلغة مجهولة يخاطب لا الناس بل الله . إذ لا أحد يفهمه، ولكنه بالروح يتكلم بألغاز.","14:3":"أما الذي يتنبأ، فهو يخاطب الناس بكلام البنيان والتشجيع والتعزية.","14:4":"فالذي يتكلم بلغة مجهولة يبني نفسه؛ وأما الذي يتنبأ، فيبني الكنيسة.","14:5":"إني أرغب في أن تتكلموا جميعا بلغات مجهولة، ولكن بالأحرى أن تتنبأوا. فإن من يتنبأ أفضل ممن يتكلم باللغات إلا إذا ترجم (ما يقوله) لتنال الكنيسة بنيانا.","14:6":"والآن، أيها الإخوة، افرضوا أني جئتكم متكلما بلغات مجهولة، فأية منفعة تنالون مني، إلا إذا كلمتكم بإعلان أو علم أو نبوءة أو تعليم؟","14:7":"فحتى الآلات المصوتة التي لا حياة فيها، كالمزمار والقيثارة، إن كانت لا تعطي أنغاما مميزة، فكيف يعرف السامع أي لحن يؤديه المزمار أو القيثارة؟","14:8":"وإن كان بوق الحرب أيضا يطلق صوتا غير واضح، فمن يستعد للقتال؟","14:9":"فهذه حالكم أيضا في التكلم بلغة مجهولة، فإن كنتم لا تنطقون بكلام مميز، فكيف يفهم السامعون ما تقولون؟ فإنكم تكونون كمن يخاطب الهواء!","14:10":"قد يكون في العالم عدد كبير من اللغات، ولا تقتصر واحدة منها على أصوات بلا معنى.","14:11":"فإن كنت لا أفهم معنى الأصوات في لغة ما، أكون أجنبيا عند الناطق بها، ويكون هو أجنبيا عندي!","14:12":"وهكذا أنتم أيضا، إذ إنكم متشوقون إلى المواهب الروحية، اسعوا في طلب المزيد منها لأجل بنيان الكنيسة.","14:13":"لذلك يجب على المتكلم بلغة مجهولة أن يطلب من الله موهبة الترجمة.","14:14":"فإني إن صليت بلغة مجهولة، فروحي تصلي، ولكن عقلي عديم الثمر.","14:15":"فما العمل إذن؟ سأصلي بالروح، ولكن سأصلي بالعقل أيضا. سأرنم بالروح، ولكن سأرنم بالعقل أيضا.","14:16":"وإلا، فإن كنت تحمد الله بالروح فقط، فكيف يستطيع قليل الخبرة أن يقول: «آمين» لدى تقديمك الشكر ما دام لا يفهم ما تقول؟","14:17":"طبعا، أنت تقدم الشكر بطريقة حسنة، ولكن غيرك لا يبنى.","14:18":"أشكر الله لأني أتكلم بلغات مجهولة أكثر منكم جميعا.","14:19":"ولكن، حيث أكون في الكنيسة، أفضل أن أقول خمس كلمات بعقلي، لكي أعلم بها الآخرين أيضا، على أن أقول عشرة آلاف كلمة بلغة مجهولة.","14:20":"أيها الإخوة، لا تكونوا أولادا في التفكير، بل كونوا أطفالا في الشر. وأما في التفكير، فكونوا راشدين.","14:21":"فإنه قد كتب في الشريعة: «بأناس ذوي لغات أخرى، وبشفاه غريبة، سأكلم هذا الشعب؛ ولكن، حتى هكذا، لن يسمعوا لي، يقول الرب».","14:22":"إذن التكلم بلغات مجهولة هو علامة لا لأجل الذين يؤمنون، بل لأجل غير المؤمنين. وأما التنبؤ، فليس لغير المؤمنين، بل للذين يؤمنون.","14:23":"فإن اجتمعت الكنيسة كلها معا، وأخذ الجميع يتكلمون بلغات مجهولة، ثم دخل بعض قليلي الخبرة أو غير المؤمنين، أفلا يقولون إنكم مجانين؟","14:24":"ولكن، إن كان الجميع يتنبأون، ثم دخل واحد من غير المؤمنين أو قليلي الخبرة، فإنه يقتنع من الجميع، ويحكم عليه من قبل الجميع،","14:25":"وإذ تنكشف خبايا قلبه، يخر على وجهه ساجدا لله، معترفا بأن الله فيكم حقا.","14:26":"فما العمل إذن أيها الإخوة؟ كلما تجتمعون معا، سيكون لكل منكم مزمور، أو تعليم، أو كلام بلغة مجهولة، أو إعلان، أو ترجمة. فليتم كل شيء بهدف البنيان.","14:27":"فإذا صار تكلم بلغة، فليتكلم اثنان، أو ثلاثة على الأكثر، كل في دوره،","14:28":"وليترجم أحدكم. فإن لم يكن بينكم مترجم، فعلى المتكلم ألا يقول شيئا أمام الجماعة، بل أن يتحدث سرا مع نفسه ومع الله.","14:29":"وليتكلم أيضا اثنان أو ثلاثة من المتنبئين وليحكم الآخرون.","14:30":"وإن أوحي إلى أحد من الجالسين، فليسكت المتكلم الأول.","14:31":"فإنكم جميعا تقدرون أن تتنبأوا واحدا فواحدا، حتى يتعلم الجميع ويتشجع الجميع.","14:32":"ولكن مواهب النبوءة هي خاضعة لأصحابها.","14:33":"فليس الله إله فوضى بل إله سلام، كما هي الحال في كنائس القديسين كلها.","14:34":"لتصمت النساء في الكنائس، فليس مسموحا لهن أن يتكلمن، بل عليهن أن يكن خاضعات، على حد ما توصي به الشريعة أيضا.","14:35":"ولكن، إذا رغبن في تعلم شيء ما، فليسألن أزواجهن في البيت، لأنه عار على المرأة أن تتكلم في الجماعة.","14:36":"أمن عندكم انطلقت كلمة الله، أم إليكم وحدكم وصلت؟","14:37":"فإن اعتبر أحد نفسه نبيا أو صاحب موهبة روحية، فليدرك أن ما أكتبه إليكم إنما هو وصية الرب.","14:38":"وإن جهل أحد هذا، فسيبقى جاهلا!","14:39":"إذن، أيها الإخوة، تشوقوا إلى التنبوء، ولا تمنعوا التكلم بلغات مجهولة.","14:40":"وإنما، ليتم كل شيء بلياقة وترتيب.","15:1":"على أني أذكركم، أيها الإخوة بالإنجيل الذي بشرتكم به، وقبلتموه ومازلتم قائمين فيه،","15:2":"وبه أيضا أنتم مخلصون، إن كنتم تتمسكون بالكلمة التي بشرتكم بها، إلا إذا كنتم قد آمنتم عبثا.","15:3":"فالواقع أني سلمتكم، في أول الأمر، ما كنت قد تسلمته، وهو أن المسيح مات من أجل خطايانا وفقا لما في الكتاب،","15:4":"وأنه دفن، وأنه قام في اليوم الثالث وفقا لما في الكتاب،","15:5":"وأنه ظهر لبطرس، ثم للاثني عشر.","15:6":"وبعد ذلك ظهر لأكثر من خمس مئة أخ معا مازال معظمهم حيا، في حين رقد الآخرون.","15:7":"ثم ظهر ليعقوب، وبعد ذلك للرسل جميعا.","15:8":"وآخر الجميع، ظهر لي أنا أيضا، وكأني طفل ولد في غير أوانه!","15:9":"فإني أنا أصغر الرسل شأنا، ولست أهلا لأن أدعى رسولا لأني اضطهدت كنيسة الله.","15:10":"ولكن، بنعمة الله صرت على ما أنا عليه الآن، ونعمته الموهوبة لي لم تكن عبثا، إذ عملت جاهدا أكثر من الرسل الآخرين جميعا. إلا أني لم أكن أنا العامل، بل نعمة الله التي كانت معي.","15:11":"وسواء أكنت أنا أم كانوا هم، فهكذا نبشر، وهكذا آمنتم.","15:12":"والآن، مادام يبشر بأن المسيح قام من بين الأموات، فكيف يقول بعضكم إنه لا قيامة للأموات؟","15:13":"فإن كانت قيامة الأموات غير موجودة، فمعنى ذلك أن المسيح لم يقم أيضا!","15:14":"ولو لم يكن المسيح قد قام، لكان تبشيرنا عبثا وإيمانكم عبثا،","15:15":"ولكان تبين عندئذ أننا شهود زور على الله، إذ إننا شهدنا على الله أنه أقام المسيح، وهو لم يقمه لو صح أن الأموات لا يقامون.","15:16":"إذن، لو كان الأموات لا يقامون، لكان المسيح لم يقم أيضا.","15:17":"ولو لم يكن المسيح قد قام، لكان إيمانكم عبثا، ولكنتم بعد في خطاياكم،","15:18":"ولكان الذين رقدوا في المسيح قد هلكوا!","15:19":"ولو كان رجاؤنا في المسيح يقتصر على هذه الحياة، لكنا أشقى الناس جميعا!","15:20":"أما الآن فالمسيح قد قام من بين الأموات بكرا للراقدين.","15:21":"فبما أن الموت كان بإنسان، فإن قيامة الأموات أيضا تكون بإنسان.","15:22":"فإنه، كما يموت الجميع في آدم، فكذلك سيحيى الجميع في المسيح،","15:23":"على أن لكل واحد رتبته: فأولا المسيح بصفته البكر؛ وبعده خاصته لدى رجوعه،","15:24":"وبعد ذلك الآخرة حين يسلم المسيح الملك لله الآب بعد أن يكون قد أباد كل رئاسة وكل سلطة وكل قوة.","15:25":"فإنه لابد أن يملك «إلى أن يضع جميع الأعداء تحت قدميه».","15:26":"وآخر عدو يباد هو الموت. ذلك بأنه قد «أخضع كل شيء تحت قدميه».","15:27":"ولكن، في قوله إن كل شيء قد أخضع، فمن الواضح أنه يستثني الله الذي جعل كل شيء خاضعا للابن.","15:28":"وعندما يتم إخضاع كل شيء للابن، فإن الابن نفسه سيخضع للذي أخضع له كل شيء، لكي يكون الله هو كل شيء في كل شيء!","15:29":"والآن، إن صح أن الأموات لا يقومون أبدا، فما معنى ما يفعله الذين يعتمدون بدل الذين يموتون؟ لماذا إذن يعتمدون بدلا منهم؟","15:30":"ولماذا نعرض نحن أنفسنا للخطر كل ساعة؟","15:31":"فبحسب افتخاري بكم في المسيح يسوع ربنا، أشهد أيها الإخوة أني أموت كل يوم!","15:32":"ولو كنت بمنطق البشر قد تعرضت للموت في أفسس بين مخالب الوحوش، فأي نفع يعود علي إن كان الذين يموتون لا يقومون؟ ولم لا «نأكل ونشرب، لأننا غدا نموت؟»","15:33":"لا تنقادوا إلى الضلال: إن المعاشرات الرديئة تفسد الأخلاق الجيدة!","15:34":"عودوا إلى الصواب كما يجب ولا تخطئوا، فإن بعضا منكم يجهلون الله تماما أقول هذا لكي تخجلوا!","15:35":"ولكن أحدا قد يقول: كيف يقام الأموات؟ وبأي جسم يعودون؟»","15:36":"ياغافل! إن ما تزرعه لا يحيا إلا بعد أن يموت.","15:37":"وما تزرعه ليس هو الجسم الذي سيطلع بل مجرد حبة من الحنطة مثلا أو غيرها من البزور.","15:38":"ثم يعطيها الله الجسم الذي يريد، كما يعطي كل نوع من البزور جسمه الخاص.","15:39":"وليس للأجساد كلها شكل واحد بل للناس جسد وللحيوانات جسد آخر وللسمك آخر وللطير آخر.","15:40":"ثم إن هناك أجساما سماوية وأجساما أرضية. ولكن الأجسام السماوية لها بهاء، والأرضية لها بهاء مختلف.","15:41":"فالشمس لها بهاء، والقمر له بهاء آخر، والنجوم لها بهاء مختلف، لأن كل نجم يختلف عن الآخر ببهائه.","15:42":"وهكذا الحال في قيامة الأموات: يزرع الجسد منحلا، ويقام غير منحل،","15:43":"يزرع مهانا، ويقام مجيدا، يزرع ضعيفا، ويقام قويا،","15:44":"يزرع جسما ماديا، ويقام جسما روحيا. فبما أن هناك جسما ماديا، فهناك أيضا جسم روحي.","15:45":"فهكذا أيضا قد كتب: «صار الإنسان الأول، آدم، نفسا حية» وأما آدم الأخير فهو روح باعث للحياة.","15:46":"على أن الروحي لم يكن أولا، بل جاء المادي أولا ثم الروحي:","15:47":"الإنسان الأول من الأرض وقد صنع من التراب؛ أما الإنسان الثاني فهو من السماء.","15:48":"فعلى مثال المصنوع من التراب، سيكون المصنوعون من التراب، وعلى مثال السماوي سيكون السماويون.","15:49":"ومثلما حملنا صورة المصنوع من التراب، سنحمل أيضا صورة السماوي.","15:50":"ثم إني، أيها الإخوة، أؤكد لكم أن الأجسام ذات اللحم والدم لا يمكنها أن ترث ملكوت الله، كما لا يمكن للمنحل أن يرث غير المنحل.","15:51":"وها أنا أكشف لكم سرا: إننا لن نرقد جميعا، ولكننا سنتغير جميعا،","15:52":"في لحظة، بل في طرفة عين عندما ينفخ في البوق الأخير. فإنه سوف ينفخ في البوق، فيقوم الأموات بلا انحلال. وأما نحن، فسنتغير.","15:53":"فلابد لهذا الجسم القابل للانحلال أن يلبس عدم انحلال، ولهذا الفاني أن يلبس خلودا.","15:54":"وبعد أن يلبس هذا المنحل عدم انحلال، وهذا الفاني خلودا، تتم الكلمة التي قد كتبت: «ابتلع الموت في النصر!»","15:55":"فأين، ياموت، شوكتك؟ وأين، ياموت نصرك؟","15:56":"وشوكة الموت إنما هي الخطيئة، وقوة الخطيئة إنما هي الشريعة.","15:57":"ولكن الشكر لله الذي يمنحنا النصر بربنا يسوع المسيح!","15:58":"إذن، ياإخوتي الأحباء، كونوا راسخين غير متزحزحين، كثيري الاجتهاد في عمل الرب دائما، عالمين أن جهدكم في الرب ليس عبثا!","16:1":"وأما بخصوص جمع التبرعات للقديسين، فكما أوصيت الكنائس في مقاطعة غلاطية، كذلك اعملوا أنتم أيضا.","16:2":"ففي أول يوم من الأسبوع، ليضع كل منكم جانبا ما يتيسر له مما يكسبه؛ وليحتفظ به، حتى لا يحصل الجمع عندما أذهب إليكم.","16:3":"وعند وصولي، أبعث من تستحسنون ليحملوا ما تكرمتم به إلى أورشليم، بعد أن أزودهم برسائل.","16:4":"وإن كان في الأمر ما يدعوني إلى مرافقتهم، فيذهبون معي.","16:5":"ولكني سأذهب إليكم لدى اجتيازي في مقاطعة مقدونية، لأني إنما سأجتاز فيها،","16:6":"وربما أقضي عندكم مدة من الزمن، أو ربما أقضي الشتاء كله عندكم ثم تسهلون لي سبيل السفر إلى أية جهة أذهب إليها.","16:7":"فأنا لا أريد أن أزوركم كعابر سبيل هذه المرة، بل أرجو أن تطول إقامتي عندكم إن أذن الرب.","16:8":"على أني سأبقى في أفسس حتى اليوم الخمسين (أي عيد الحصاد اليهودي)","16:9":"لأن بابا كبيرا وفعالا قد انفتح لي، والمقاومون كثيرون!","16:10":"وإذا وصل تيموثاوس إليكم، فاهتموا بأن يكون مطمئنا عندكم، لأنه يقوم بعمل الرب مثلي.","16:11":"فلا يستخف به أحد، بل سهلوا له السبيل ليعود إلي بسلام، فأنا أنتظر وصوله، مع الإخوة.","16:12":"أما الأخ أبلوس، فكثيرا ما توسلت إليه أن يرافق الإخوة في الذهاب إليكم. ولكن، لم تكن رغبة قط في أن يذهب الآن. على أنه سيذهب عندما تتوفر له الفرصة المناسبة.","16:13":"كونوا متيقظين حذرين. اثبتوا في الإيمان. كونوا رجالا. كونوا أقوياء.","16:14":"وكل ما تعملونه، فاعملوه في المحبة.","16:15":"على أني، أيها الإخوة، أطلب إليكم هذا الطلب: أنتم تعرفون عائلة استفاناس، فهم باكورة أخائية، وقد كرسوا أنفسهم لخدمة القديسين،","16:16":"فاخضعوا لهم ولأمثالهم، ولكل من يشترك معهم باجتهاد في العمل.","16:17":"سررت كثيرا بمجيء استفاناس وفرتوناتوس وأخائيكوس. فقد نابوا عنكم في سد الاحتياج.","16:18":"إذ أنعشوا روحي وروحكم. فقدروا مثل هؤلاء حق التقدير!","16:19":"الكنائس في مقاطعة أسيا تسلم عليكم. ويسلم عليكم في الرب كثيرا، أكيلا وبريسكلا مع الكنيسة التي في بيتهما.","16:20":"جميع الإخوة يسلمون عليكم. سلموا بعضكم على بعض بقبلة طاهرة.","16:21":"وإليكم سلامي، أنا بولس، بخط يدي.","16:22":"إن كان أحد لا يحب الرب فليكن «أناثيما» (أي ملعونا)!","16:23":"لتكن معكم نعمة الرب يسوع المسيح!","16:24":"ولكم جميعا محبتي في المسيح يسوع! آمين."},"2Co":{"1:1":"من بولس، رسول المسيح يسوع بمشيئة الله، ومن الأخ تيموثاوس، إلى كنيسة الله في مدينة كورنثوس، وإلى جميع القديسين المقيمين في مقاطعة أخائية كلها.","1:2":"لتكن لكم النعمة والسلام من الله أبينا ومن الرب يسوع المسيح!","1:3":"تبارك الله ، أبو ربنا يسوع المسيح، أبو المراحم وإله كل تعزية،","1:4":"هو الذي يشجعنا في كل ضيقة نمر بها، حتى نستطيع أن نشجع الذين يمرون بأية ضيقة، بالتشجيع الذي به يشجعنا الله .","1:5":"فكما فاضت علينا آلام المسيح، يفيض علينا أيضا التشجيع بالمسيح.","1:6":"فإن كنا في ضيقة، فذلك لأجل تشجيعكم وخلاصكم؛ وإن كنا متشجعين، فذلك لأجل تشجيعكم، مما يعمل فيكم على احتمال نفس الآلام التي نتألم بها نحن أيضا.","1:7":"وإن رجاءنا من أجلكم هو رجاء وطيد، إذ نعلم أنكم كما تشتركون معنا في احتمال الآلام، ستشتركون أيضا في نوال التشجيع.","1:8":"فيا أيها الإخوة، نريد أن لا يخفى عليكم أمر الضيقة التي مررنا بها في مقاطعة أسيا. فقد كانت وطأتها علينا شديدة جدا وفوق طاقتنا، حتى يئسنا من الحياة نفسها.","1:9":"ولكننا شعرنا، في قرارة أنفسنا، أنه محكوم علينا بالموت، حتى نكون متكلين لا على أنفسنا بل على الله الذي يقيم الأموات؛","1:10":"وقد أنقذنا من هذا الموت الشنيع، ومازال ينقذنا حتى الآن، ولنا ملء الثقة بأنه حقا سينقذنا فيما بعد؛","1:11":"على أن تساعدونا أنتم بالصلاة لأجلنا؛ حتى إن ما يوهب لنا استجابة لصلاة الكثيرين، يدفع الكثيرين إلى الشكر من أجلنا.","1:12":"فإن فخرنا هو هذا: شهادة ضميرنا بأننا، في قداسة الله وإخلاصه، قد سلكنا في العالم، وبخاصة تجاهكم؛ ولم يكن ذلك بحكمة بشرية بل بنعمة الله.","1:13":"فإننا لا نكتب إليكم سوى ما تقرأونه وتفهمونه. وأرجو أن تفهموا الفهم كله،","1:14":"كما قد فهمتمونا فهما جزئيا، أننا سنكون فخرا لكم، مثلما أنتم فخر لنا، في يوم ربنا يسوع.","1:15":"فبهذه القناعة، كنت قد نويت سابقا أن أجيء إليكم، ليكون لكم فرح مرة أخرى،","1:16":"وأن أمر بكم في طريقي إلى مقاطعة مقدونية وأيضا في عودتي منها، وبعدئذ تسهلون لي سبيل السفر إلى منطقة اليهودية.","1:17":"فهل تظنون أني باعتمادي لهذه الخطة تصرفت بخفة، أو أني أتخذ قراراتي وفقا لمنطق البشر، ليكون في كلامي نعم نعم ولا لا في آن واحد؟","1:18":"صادق هو الله ، ويشهد أن كلامنا إليكم ليس نعم ولا معا!","1:19":"فإن ابن الله، المسيح يسوع، الذي بشرنا به فيما بينكم، أنا وسلوانس وتيموثاوس، لم يكن نعم ولا معا، وإنما فيه نعم.","1:20":"فمهما كانت وعود الله، فإن فيه النعم لها كلها، وفيه الآمين بنا لأجل مجد الله.","1:21":"ولكن الذي يرسخنا وإياكم في المسيح، والذي قد مسحنا، إنما هو الله ،","1:22":"وهو أيضا قد وضع ختمه علينا، ووهبنا الروح القدس عربونا في قلوبنا.","1:23":"غير أني أدعو الله أن يشهد على نفسي بأني إشفاقا عليكم لم آت إلى كورنثوس.","1:24":"وهذا لا يعني أننا نتسلط على إيمانكم، بل إننا معاونون لكم نعمل لأجل فرحكم. فبالإيمان أنتم ثابتون.","2:1":"ولكني قررت نهائيا أن لا يكون مجيئي إليكم سببا لإحزانكم.","2:2":"فإن أحزنتكم فمن ذا يفرحني إلا الذي أحزنته؟","2:3":"لهذا أكتب إليكم ما أكتبه هنا، حتى عندما أجيء لا يأتيني الحزن من الذي كان يجب أن يأتيني منه الفرح. ولي ثقة بجميعكم أن فرحي هو فرحكم جميعا.","2:4":"فإن ما كتبته إليكم سابقا كان نابعا من ضيق شديد واكتئاب في القلب، ومصحوبا بدموع كثيرة. وما كان قصدي أن أحزنكم، بل أن تعرفوا المحبة الفياضة التي عندي من نحوكم.","2:5":"وإذا كان أحد قد سبب الحزن، فإنه لم يسبب الحزن لي شخصيا، بل لجميعكم إلى حد ما، هذا لكي لا أبالغ!","2:6":"والآن، يكفي ذلك الرجل المذنب القصاص الذي أنزله به أكثركم.","2:7":"وعلى نقيض ذلك، فأحرى بكم الآن أن تسامحوه وتشجعوه، وإلا فإنه قد يبتلع في غمرة الحزن الشديد.","2:8":"لذلك أتوسل إليكم أن تؤكدوا له محبتكم.","2:9":"وقد كان ما كتبته إليكم بهدف اختباركم أيضا، لأعرف مدى طاعتكم في كل شيء.","2:10":"فمن تسامحونه بشيء، أسامحه أنا أيضا. وإذا كنت أنا أيضا قد سامحت ذلك الرجل بشيء، فقد سامحته من أجلكم في حضرة المسيح،","2:11":"مخافة أن يستغلنا الشيطان مادمنا لا نجهل نياته.","2:12":"ولما وصلت إلى مدينة ترواس لأجل إنجيل المسيح، وفتح لي الرب بابا للخدمة","2:13":"لم تسترح روحي لأني لم أجد تيطس أخي. فودعت المؤمنين هناك وتوجهت إلى مقاطعة مقدونية.","2:14":"ولكن، شكرا لله الذي يقودنا دائما في موكب النصر في المسيح، وينشر بنا رائحة معرفته في كل مكان.","2:15":"فإننا رائحة المسيح الطيبة المرتفعة إلى الله، المنتشرة على السواء عند الذين يخلصون وعند الذين يهلكون:","2:16":"هؤلاء يشمون فيها رائحة من الموت وإلى الموت، وأولئك رائحة من الحياة وإلى الحياة. ومن هو صاحب الكفاءة لتأدية هذه الأمور؟","2:17":"فإننا لا نتاجر بكلمة الله كما يفعل الكثيرون، وإنما بإخلاص ومن قبل الله، وأمام الله، نتكلم في المسيح.","3:1":"ترى، هل نبتديء نمدح أنفسنا من جديد؟ أم ترانا نحتاج كبعضهم إلى رسائل توصية نحملها إليكم أو منكم؟","3:2":"فأنتم الرسالة التي توصي بنا، وقد كتبت في قلوبنا، حيث يستطيع جميع الناس أن يعرفوها ويقرأوها.","3:3":"وهكذا يتبين أنكم رسالة من المسيح خدمناها نحن، وقد كتبت لا بحبر بل بروح الله الحي، ولا في ألواح حجرية بل في ألواح القلب البشرية.","3:4":"وهذه هي ثقتنا العظيمة من جهة الله بالمسيح:","3:5":"ليس أننا أصحاب كفاءة ذاتية لندعي شيئا لأنفسنا، بل إن كفاءتنا من الله،","3:6":"الذي جعلنا أصحاب كفاءة لنكون خداما لعهد جديد قائم لا على الحرف بل على الروح. فالحرف يؤدي إلى الموت؛ أما الروح فيعطي الحياة.","3:7":"ولكن، مادامت خدمة الموت التي نقشت حروفها في لوح حجر، قد ابتدأت بمجد، حتى إن بني إسرائيل لم يقدروا أن يثبتوا أنظارهم على وجه موسى، بسبب مجد وجهه، ذلك المجد الزائل،","3:8":"أفليس أحرى أن تكون خدمة الروح راسخة في المجد؟","3:9":"فبما أن خدمة الدينونة كانت مجدا، فأحرى كثيرا أن تفوقها في المجد خدمة البر.","3:10":"حتى إن ما قد مجد سابقا لا يكون قد مجد على هذا النحو بالنظر إلى المجد الفائق.","3:11":"فإذا كان الزائل قد صاحبه المجد، فأحرى كثيرا أن يصاحب المجد ما هو باق دائما.","3:12":"فإذ لنا هذا الرجاء الوطيد، نعمل بكثير من الجرأة.","3:13":"ولسنا كموسى الذي وضع حجابا على وجهه لكي لا يثبت بنو إسرائيل أنظارهم على نهاية الزائل.","3:14":"ولكن أذهانهم قد أعميت، لأن ذلك الحجاب مازال مسدلا حتى اليوم عندما يقرأ العهد القديم، وهو لايزال إلا في المسيح","3:15":"غير أن ذلك الحجاب مازال حتى اليوم موضوعا على قلوبهم عندما يقرأ كتاب موسى.","3:16":"ولكن عندما ترجع قلوبهم إلى الرب، ينزع الحجاب.","3:17":"فإن الرب هو الروح، وحيث يكون روح الرب، فهناك الحرية.","3:18":"ونحن جميعا فيما ننظر إلى مجد الرب بوجوه كالمرآة لا حجاب عليها، نتجلى من مجد إلى مجد لنشابه الصورة الواحدة عينها، وذلك بفعل الرب الروح.","4:1":"فما دامت لنا إذن هذه الخدمة برحمة من الله، فلا تخور عزيمتنا.","4:2":"ولكننا قد رفضنا الأساليب الخفية المخجلة، إذ لا نسلك في المكر، ولا نزور كلمة الله، بل بإعلاننا للحق نمدح أنفسنا لدى ضمير كل إنسان، أمام الله.","4:3":"ولكن إن كان إنجيلنا محجوبا، فإنما هو محجوب لدى الهالكين، لدى غير المؤمنين","4:4":"الذين أعمى إله هذا العالم أذهانهم حتى لا يضيء لهم نور الإنجيل المختص بمجد المسيح الذي هو صورة الله.","4:5":"فإننا لا نبشر بأنفسنا، بل بالمسيح يسوع ربا، وما نحن إلا عبيد لكم من أجل يسوع.","4:6":"فإن الله ، الذي أمر أن يشرق نور من الظلام، هو الذي جعل النور يشرق في قلوبنا، لإشعاع معرفة مجد الله المتجلي في وجه المسيح.","4:7":"ولكن هذا الكنز نحمله نحن في أوعية من فخار، ليتبين أن القدرة الفائقة آتية من الله لا صادرة منا.","4:8":"فالصعوبات تضيق علينا من كل جهة، ولكن لا ننهار. لا نجد حلا مناسبا، ولكن لا نيأس.","4:9":"يطاردنا الاضطهاد، ولكن لا يتخلى الله عنا. نطرح أرضا، ولكن لا نموت.","4:10":"وحيثما ذهبنا، نحمل موت يسوع دائما في أجسادنا لتظهر فيها أيضا حياة يسوع.","4:11":"فمع أننا مازلنا أحياء، فإننا نسلم دائما إلى الموت من أجل يسوع، لتظهر في أجسادنا الفانية حياة يسوع أيضا.","4:12":"وهكذا، فإن الموت فعال فينا؛ والحياة فعالة فيكم.","4:13":"وبما أن لنا روح الإيمان عينه، هذا الذي كتب بخصوصه: «آمنت، لذلك تكلمت»، فنحن أيضا نؤمن، ولذلك نتكلم،","4:14":"ونحن عالمون أن الذي أقام الرب يسوع من الموت سوف يقيمنا نحن أيضا مع يسوع، ويوقفنا في حضرته بصحبتكم.","4:15":"فإن جميع الأشياء نقاسيها من أجلكم، حتى إذا فاضت النعمة في الكثيرين، تجعل الشكر يفيض لأجل مجد الله.","4:16":"لهذا، لا تخور عزيمتنا! ولكن، مادام الإنسان الظاهر فينا يفنى، فإن الإنسان الباطن فينا يتجدد يوما فيوما.","4:17":"ذلك لأن ما يضايقنا الآن من صعوبات بسيطة عابرة، ينتج لنا بمقدار لا يحد وزنة أبدية من المجد،","4:18":"إذ نرفع أنظارنا عن الأمور المنظورة ونثبتها على الأمور غير المنظورة. فإن الأمور المنظورة إنما هي إلى حين؛ وأما غير المنظورة فهي أبدية.","5:1":"فإننا نعلم أنه متى تهدمت خيمتنا الأرضية التي نسكنها الآن، يكون لنا بناء من الله: بيت لم تصنعه أيدي البشر، أبدي في السماوات.","5:2":"فالواقع أننا، ونحن في هذا المسكن، نئن متشوقين أن نلبس بدلا منه بيتنا السماوي،","5:3":"حتى إذا لبسناه لا نوجد عراة.","5:4":"ذلك أننا، نحن الساكنين في هذه الخيمة، نئن كمن يحمل ثقلا، فنحن لا نريد أن نخلعها، بل أن نلبس فوقها مسكننا السماوي، فتبتلع الحياة ما هو مائت فينا.","5:5":"والذي أعدنا لهذا الأمر بعينه هو الله ، وقد أعطانا الروح عربونا أيضا.","5:6":"لذلك نحن واثقون دائما، وعالمون أننا مادمنا مقيمين في الجسد، نبقى مغتربين عن الرب،","5:7":"لأننا نسلك بالإيمان لا بالعيان.","5:8":"فنحن واثقون إذن، وراضون بالأحرى أن نكون مغتربين عن الجسد ومقيمين عند الرب.","5:9":"ولذلك أيضا نحرص أن نرضيه، سواء أكنا مقيمين أم مغتربين.","5:10":"إذ لابد أن نقف جميعا مكشوفين أمام عرش المسيح، لينال كل واحد منا استحقاق ما عمله حين كان في الجسد، أصالحا كان أم رديئا!","5:11":"فبدافع وعينا لرهبة الرب، نحاول إقناع الناس. ولكننا ظاهرون أمام الله، وأرجو أن نكون ظاهرين أيضا في ضمائركم.","5:12":"ليس أننا عدنا إلى مدح أنفسنا أمامكم؛ بل إنما نقدم لكم مبررا للافتخار بنا، ليكون لكم حجة تردون بها على الذين يفتخرون بالمظاهر لا بما في القلب.","5:13":"أترانا فقدنا صوابنا؟ إن ذلك لأجل الله. أم ترانا متعقلين؟ إن ذلك لأجلكم.","5:14":"فإن محبة المسيح تسيطر علينا، وقد حكمنا بهذا: مادام واحد قد مات عوضا عن الجميع، فمعنى ذلك أن الجميع ماتوا؛","5:15":"وهو قد مات عوضا عن الجميع حتى لا يعيش الأحياء في ما بعد لأنفسهم بل للذي مات عوضا عنهم ثم قام.","5:16":"إذن، نحن منذ الآن لا نعرف أحدا معرفة بشرية. ولكن إن كنا قد عرفنا المسيح معرفة بشرية، فنحن الآن لا نعرفه هكذا بعد.","5:17":"فإنه إذا كان أحد في المسيح، فهو خليقة جديدة: إن الأشياء القديمة قد زالت، وها كل شيء قد صار جديدا.","5:18":"وكل شيء هو من عند الله الذي صالحنا مع نفسه بالمسيح، ثم سلمنا خدمة هذه المصالحة.","5:19":"ذلك أن الله كان في المسيح مصالحا العالم مع نفسه، غير حاسب عليهم خطاياهم، وقد وضع بين أيدينا رسالة هذه المصالحة.","5:20":"فنحن إذن سفراء المسيح، وكأن الله يعظ بنا نتوسل بالنيابة عن المسيح منادين: «تصالحوا مع الله!»","5:21":"فإن الذي لم يعرف خطيئة، جعله الله خطيئة لأجلنا، لنصير نحن بر الله فيه.","6:1":"فبما أننا عاملون معا عند الله، نطلب ألا يكون قبولكم لنعمة الله عبثا.","6:2":"فإنه يقول: «في وقت القبول استجبت لك، وفي يوم الخلاص أعنتك». والآن هو وقت القبول. اليوم يوم الخلاص!","6:3":"ولسنا نتصرف أي تصرف يكون عثرة لأحد، حتى لا يلحق الخدمة أي لوم.","6:4":"وإنما نتصرف في كل شيء بما يبين أننا فعلا خدام الله: في تحمل الكثير؛ في الشدائد والحاجات والضيقات والجلدات","6:5":"والسجون والاضطرابات والأتعاب والسهر والصوم؛","6:6":"في الطهارة والمعرفة وطول البال واللطف؛ في الروح القدس والمحبة الخالصة من الرياء؛","6:7":"في كلمة الحق وقدرة الله؛ بأسلحة البر في الهجوم والدفاع؛","6:8":"بالكرامة والهوان؛ بالصيت السييء والصيت الحسن. نعامل كمضللين ونحن صادقون،","6:9":"كمجهولين ونحن معروفون، كمائتين وها نحن نحيا ، كمعاقبين ولا نقتل،","6:10":"كمحزونين ونحن دائما فرحون، كفقراء ونحن نغني كثيرين، كمن لا شيء عندهم ونحن نملك كل شيء.","6:11":"إننا كلمناكم، ياأهل كورنثوس، بصراحة فم ورحابة قلب.","6:12":"إنكم متضايقون لا بسببنا بل بسبب عواطفكم","6:13":"ولكن، على سبيل المعاملة بالمثل، وأخاطبكم كأولاد، لتكن قلوبكم أيضا رحبة!","6:14":"لا تدخلوا مع غير المؤمنين تحت نير واحد. فأي ارتباط بين البر والإثم؟ وأية شركة بين النور والظلام؟","6:15":"وأي تحالف للمسيح مع إبليس؟ وأي نصيب للمؤمن مع غير المؤمن؟","6:16":"وأي وفاق لهيكل الله مع الأصنام؟ فإننا نحن هيكل الله الحي، وفقا لما قاله الله : «سأسكن في وسطهم، وأسير بينهم، وأكون إلههم وهم يكونون شعبا لي…","6:17":"لذلك اخرجوا من وسطهم، وكونوا منفصلين، يقول الرب، ولا تلمسوا ما هو نجس،","6:18":"فأقبلكم، وأكون لكم أبا، وتكونوا لي بنين وبنات»، هذا يقوله الرب القادر على كل شيء.","7:1":"فإذ نلنا هذه الوعود، أيها الأحباء، لنطهر أنفسنا من كل ما يدنس الجسد والروح، ونكمل القداسة في مخافة الله.","7:2":"أفسحوا لنا مكانا في قلوبكم: فنحن لم نعامل أحدا معاملة ظالمة، ولم نؤذ أحدا، ولم نستغل أحدا.","7:3":"لا أقول هذا لأدينكم. فإنكم، كما قلت سابقا، في قلوبنا، حتى إننا نموت معكم أو نحيا معكم!","7:4":"كبيرة ثقتي بكم، وعظيم افتخاري بكم. إني ممتليء تشجيعا وفائض فرحا في جميع ضيقاتنا.","7:5":"فإننا لما وصلنا إلى مقاطعة مقدونية، لم تذق أجسادنا طعم الراحة، بل واجهتنا الضيقات من كل جهة: إذ كثر حولنا النزاع، وزاد في داخلنا الخوف.","7:6":"إلا أن الله ، الذي يشجع المسحوقين، أمدنا بالتشجيع بمجيء تيطس إلينا،","7:7":"لا بمجيئه وحسب، بل بالتشجيع الذي لقيه عندكم. وقد أخبرنا بشوقكم، وحزنكم، وغيرتكم علي، فتضاعف فرحي.","7:8":"فإذا كنت قد أحزنتكم برسالتي إليكم، فلست نادما على ذلك، مع أني كنت قد ندمت، لأني أرى أن تلك الرسالة أحزنتكم ولو إلى حين.","7:9":"وأنا الآن أفرح، لا لأنكم قد أحزنتم، بل لأن حزنكم أدى بكم إلى التوبة. فإنكم قد أحزنتم بما يوافق مشيئة الله، حتى لا تتأذوا منا في أي شيء.","7:10":"فإن الحزن الذي يوافق مشيئة الله ينتج توبة تؤدي إلى الخلاص، وليس عليه ندم. وأما حزن العالم فينتج موتا.","7:11":"فانظروا، إذن، هذا الحزن عينه الذي يوافق الله ، كم أنتج فيكم من الاجتهاد، بل من الاعتذار، بل من الاستنكار، بل من الخوف، بل من التشوق، بل من الغيرة، بل من الانتقام! وقد بينتم في كل شيء أنكم أبرياء من ذلك الأمر.","7:12":"إذن، كتبت إليكم ما كتبته سابقا لا من أجل المذنب ولا من أجل المذنب إليه، بل لكي يظهر لكم أمام الله مدى حماستكم لطاعتنا.","7:13":"لهذا السبب قد تعزينا. وفوق تعزيتنا، فرحنا أكثر جدا لفرح تيطس لأن روحه انتعشت بكم جميعا.","7:14":"فإذا كنت قد افتخرت له بشيء فيما يتعلق بكم، فإني لم أخجل؛ وإنما كما كلمناكم في كل شيء بالصدق، كذلك كان افتخارنا بكم لتيطس صادقا أيضا.","7:15":"وإن عواطفه تزداد نحوكم أكثر جدا عندما يتذكر طاعتكم جميعا وكيف استقبلتموه بخوف وارتعاد.","7:16":"إني أفرح بكوني واثقا بكم في كل شيء.","8:1":"والآن، نعرفكم، أيها الإخوة، بنعمة الله الموهوبة في كنائس مقاطعة مقدونية.","8:2":"فمع أنهم كانوا في تجربة ضيقة شديدة، فإن فرحهم الوافر مع فقرهم الشديد فاضا فأنتجا منهم سخاء غنيا.","8:3":"فإني أشهد أنهم تبرعوا من تلقاء أنفسهم، لا على قدر طاقتهم وحسب، بل فوق طاقتهم.","8:4":"وقد توسلوا إلينا بإلحاح شديد أن نقبل إحسانهم واشتراكهم في إعانة القديسين.","8:5":"كما أنهم تجاوزوا ما توقعناه، إذ كرسوا أنفسهم أولا للرب ثم لنا نحن بمشيئة الله،","8:6":"مما جعلنا نلتمس من تيطس أن يكمل عندكم هذا الإحسان كما سبق أن ابتدأ به.","8:7":"ولكن، كما أنكم في وفرة من كل شيء: من الإيمان، والكلمة، والمعرفة، والاجتهاد في كل أمر، ومحبتكم لنا، ليتكم تكونون أيضا في وفرة من نعمة العطاء هذه.","8:8":"لا أقول هذا على سبيل الأمر، بل اختبارا لصدق محبتكم بحماسة الآخرين.","8:9":"فأنتم تعرفون نعمة ربنا يسوع المسيح: فمن أجلكم افتقر، وهو الغني لكي تغتنوا أنتم بفقره.","8:10":"وأنا أبدي لكم رأيي في الموضوع. فإن هذا نافع لكم أنتم الذين سبق أن بدأتم منذ السنة الماضية لا أن تفعلوا فقط بل أن ترغبوا أيضا:","8:11":"إنما الآن أكملوا القيام بذلك العمل، حتى كما كان لكم الاستعداد لأن ترغبوا، يكون لكم أيضا الاستعداد لأن تكملوا العمل مما تملكون.","8:12":"فمتى وجد الاستعداد، يقبل العطاء على قدر ما يملك الإنسان، لا على قدر ما لا يملك.","8:13":"وليس ذلك بهدف أن يكون الآخرون في وفرة وتكونوا أنتم في ضيق، بل على مبدأ المساواة:","8:14":"ففي الحالة الحاضرة، تسد وفرتكم حاجتهم، لكي تسد وفرتهم حاجتكم، فتتم المساواة،","8:15":"وفقا لما قد كتب: «المكثر لم يفضل عنه شيء، والمقلل لم ينقصه شيء».","8:16":"ولكن، شكرا لله الذي وضع في قلب تيطس مثل هذه الحماسة لأجلكم.","8:17":"فقد لبى التماسنا فعلا، بل انطلق إليكم من تلقاء نفسه لكونه أشد حماسة.","8:18":"وقد أرسلنا معه الأخ الذي ذاع مدحه بين الكنائس كلها في خدمة الإنجيل.","8:19":"ليس هذا وحسب، بل هو أيضا منتخب الكنائس رفيقا لنا في السفر لإيصال هذا الإحسان الذي نعمل له تمجيدا للرب نفسه وإظهارا لاهتمامنا بعضنا ببعض.","8:20":"ونحن حريصون على ألا يلومنا أحد في أمر هذه التقدمة الكبيرة التي نتولى القيام بها.","8:21":"فإننا نحرص على النزاهة لا أمام الرب فقط، بل أمام الناس أيضا.","8:22":"وأرسلنا معهما أخانا الذي تبين لنا بالاختبار مرة بعد مرة، أن له حماسة شديدة في أمور كثيرة، وهو الآن أوفر جدا في الحماسة بسبب ثقته العظيمة بكم.","8:23":"أما تيطس، فهو زميلي ومعاوني من أجل مصلحتكم. وأما أخوانا الآخران، فهما رسولا الكنائس ومجد المسيح.","8:24":"فأثبتوا لهم إذن أمام الكنائس برهان محبتكم وصواب افتخارنا بكم.","9:1":"فإنه من غير الضروري أن أكتب إليكم في موضوع إعانة القديسين،","9:2":"مادمت أعرف استعدادكم الذي أفتخر به من جهتكم عند المقدونيين فأقول: إن مقاطعة أخائية جاهزة للإعانة منذ السنة الماضية. وحماستكم كانت دافعا لأكثر الإخوة.","9:3":"ولكني أرسلت إليكم الإخوة لكي لا ينقلب افتخارنا بكم في هذا الأمر افتخارا باطلا ولكي تكونوا جاهزين كما قلت؛","9:4":"لئلا نضطر نحن، ولا أقول أنتم، إلى الخجل بهذه الثقة العظيمة إذا ما رافقني بعض المقدونيين ووجدوكم غير جاهزين.","9:5":"لذلك رأيت من اللازم أن ألتمس من الإخوة أن يسبقوني إليكم، لكي يعدوا أولا بركتكم التي سبق الإعلان عنها، فتكون جاهزة باعتبارها بركة، لا كأنها واجب ثقيل!","9:6":"فمن الحق أن من يزرع بالتقتير، يحصد أيضا بالتقتير، ومن يزرع بالبركات، يحصد أيضا بالبركات.","9:7":"فليتبرع كل واحد بما نوى في قلبه، لا بأسف ولا عن اضطرار، لأن الله يحب المعطي المتهلل.","9:8":"والله قادر أن يجعل كل نعمة تفيض عليكم، حتى يكون لكم اكتفاء كلي في كل شيء وكل حين، فتفيضوا في كل عمل صالح؛","9:9":"وفقا لما قد كتب: «وزع بسخاء، أعطى الفقراء، بره يدوم إلى الأبد!»","9:10":"والذي يقدم بذارا للزارع، وخبزا للأكل، سيقدم لكم بذاركم ويكثره ويزيد أثمار بركم:","9:11":"إذ تغتنون في كل شيء، لأجل كل سخاء طوعي ينتج بنا شكرا لله","9:12":"ذلك لأن خدمة الله بهذه الإعانة لا تسد حاجة القديسين وحسب، بل تفيض بشكر كثير لله.","9:13":"فإن القديسين، إذ يختبرون هذه الخدمة، يمجدون الله على طاعتكم في الشهادة لإنجيل المسيح وعلى السخاء الطوعي في مشاركتكم لهم وللجميع.","9:14":"كما يرفعون الدعاء لأجلكم، متشوقين إليكم، بسبب نعمة الله الفائقة التي ظهرت فيكم.","9:15":"فشكرا لله على عطيته المجانية التي تفوق الوصف!","10:1":"ولكني أتوسل إليكم بوداعة المسيح وحلمه، أنا بولس «المتواضع وأنا حاضر بينكم، والجريء عليكم وأنا غائب عنكم»،","10:2":"راجيا ألا تضطروني لأن أكون جريئا عند حضوري، فألجأ إلى الحزم الذي أظن أني سأتجرأ عليه في معاملة من يظنون منكم أننا نسلك وفقا للجسد.","10:3":"فمع أننا نعيش في الجسد، فإننا لا نحارب وفقا للجسد.","10:4":"فإن الأسلحة التي نحارب بها ليست جسدية، بل قادرة بالله على هدم الحصون: بها نهدم النظريات","10:5":"وكل ما يعلو مرتفعا لمقاومة معرفة الله، ونأسر كل فكر إلى طاعة المسيح.","10:6":"ونحن على استعداد لمعاقبة كل عصيان، بعد أن تكون طاعتكم قد اكتملت.","10:7":"أتحكمون على الأمور بحسب ظواهرها؟ إن كانت لأحد ثقة في نفسه بأنه يخص المسيح، فليفكر أيضا في نفسه بأنه كما يخص هو المسيح، كذلك نخصه نحن أيضا.","10:8":"فإني، وإن كنت أفتخر ولو قليلا أكثر مما يجب، بسلطتنا التي أعطانا إياها الرب لبنيانكم لا لهدمكم، لن أضطر إلى الخجل،","10:9":"حتى لا أظهر كأني أخوفكم بالرسائل.","10:10":"فمنكم من يقول: «رسائله شديدة اللهجة وقوية؛ أما حضوره الشخصي فضعيف، وكلامه حقير».","10:11":"فليتنبه مثل هذا إلى أننا كما نكون بالقول في الرسائل ونحن غائبون، كذلك نحن أيضا بالفعل ونحن حاضرون.","10:12":"فإننا لا نجرؤ أن نصنف أنفسنا، أو نقارن أنفسنا، بمادحي أنفسهم الذين بينكم. فلأن هؤلاء يقيسون أنفسهم على أنفسهم، ويقارنون أنفسهم بأنفسهم، فهم لا يفهمون!","10:13":"أما نحن، فلن نفتخر بما يتعدى الحد، بل بما يوافق حدود القانون الذي عينه لنا الله لنصل به إليكم أيضا.","10:14":"فإننا لسنا نتعدى حدودنا وكأننا لم نصل إليكم، إذ قد وصلنا إليكم فعلا بإنجيل المسيح؛","10:15":"ولسنا نفتخر بما يتعدى الحد في أتعاب غيرنا. وإنما نرجو، إذا ما نما إيمانكم، أن نزداد تقدما بينكم وفقا لقانوننا،","10:16":"حتى يزداد تبشيرنا بالإنجيل انتشارا إلى أبعد من بلادكم، لا لنكون مفتخرين بما تم إنجازه في قانون غيرنا.","10:17":"وإنما «من افتخر، فليفتخر بالرب!»","10:18":"فليس الفاضل هو من يمدح نفسه، بل من يمدحه الرب.","11:1":"ليتكم تحتملون مني بعض الغباوة، بل إنكم في الواقع تحتملونني.","11:2":"فإني أغار عليكم غيرة من عند الله لأني خطبتكم لرجل واحد هو المسيح، لأقدمكم إليه عذراء عفيفة.","11:3":"غير أني أخشى أن تضلل عقولكم عن الإخلاص والطهارة تجاه المسيح مثلما أغوت الحية بمكرها حواء.","11:4":"فإذا كان من يأتيكم يبشر بيسوع آخر لم نبشر به نحن أو كنتم تنالون روحا آخر لم تنالوه، أو تقبلون إنجيلا لم تقبلوه، فإنكم تحتملون ذلك بكل سرور.","11:5":"فإني أعتبر نفسي غير متخلف في شيء عن أولئك الرسل المتفوقين.","11:6":"فمع أني أتكلم كلام العامة غير الفصيح، فلا تنقصني المعرفة. وإنما أظهرنا لكم ذلك في كل شيء أمام الجميع.","11:7":"أيكون ذنبي إذن، أني بشرتكم بالإنجيل دون أجرة منكم، فأنقصت قدري ليزداد قدركم؟","11:8":"ظلمت كنائس أخرى بتحميلها نفقة خدمتكم.","11:9":"وحين كنت عندكم واحتجت، لم أثقل على أحد منكم. إذ سد حاجتي الإخوة الذين جاءوا من مقاطعة مقدونية. وقد حفظت نفسي، وسأحفظها أيضا، من أن أكون ثقيلا عليكم في أي شيء.","11:10":"ومادام حق المسيح في، لن يوقف أحد افتخاري هذا في بلاد أخائية كلها!","11:11":"لماذا؟ ألأني لا أحبكم؟ الله يعلم!","11:12":"ولكن، سأفعل ما أنا فاعله الآن لأسقط حجة الذين يلتمسون حجة تبين أنهم مثلنا في ما يفتخرون به.","11:13":"فإن أمثال هؤلاء هم رسل دجالون، عمال ماكرون، يظهرون أنفسهم بمظهر رسل المسيح.","11:14":"ولا عجب! فالشيطان نفسه يظهر نفسه بمظهر ملاك نور.","11:15":"فليس كثيرا إذن أن يظهر خدامه أنفسهم بمظهر خدام البر. وإن عاقبتهم ستكون على حسب أعمالهم.","11:16":"أقول مرة أخرى: لا يظن أحد أني غبي وإلا، فاقبلوني ولو كغبي، كي أفتخر أنا أيضا قليلا!","11:17":"وما أتكلم به هنا، لا أتكلم به وفقا للرب، بل كأني في الغباوة، ولي هذه الثقة التي تدفعني إلى الافتخار:","11:18":"بما أن كثيرين يفتخرون بما يوافق الجسد، فأنا أيضا سأفتخر.","11:19":"فلأنكم عقلاء، تحتملون الأغبياء بسرور!","11:20":"فإنكم تحتملون كل من يستعبدكم، ويفترسكم، ويستغلكم، ويتكبر عليكم، ويلطمكم على وجوهكم.","11:21":"ياللمهانة! كم كنا ضعفاء في معاملتنا لكم!","11:22":"فإن كانوا عبرانيين، فأنا كذلك؛ أو إسرائيليين، فأنا كذلك؛ أو من نسل إبراهيم؛ فأنا كذلك!","11:23":"وإن كانوا خدام المسيح، أتكلم كأني فقدت صوابي، فأنا متفوق عليهم: في الأتعاب أوفر منهم جدا، في الجلدات فوق الحد، في السجون أوفر جدا، في التعرض للموت أكثر مرارا.","11:24":"من اليهود تلقيت الجلد خمس مرات، كل مرة أربعين جلدة إلا واحدة.","11:25":"ضربت بالعصي ثلاث مرات. رجمت بالحجارة مرة. تحطمت بي السفينة ثلاث مرات. قضيت في عرض البحر يوما بنهاره وليله.","11:26":"سافرت أسفارا عديدة؛ وواجهتني أخطار السيول الجارفة، وأخطار قطاع الطرق، وأخطار من بني جنسي، وأخطار من الأمم، وأخطار في المدن، وأخطار في البراري، وأخطار في البحر، وأخطار بين إخوة دجالين.","11:27":"وكم عانيت من التعب والكد والسهر الطويل، والجوع والعطش والصوم الكثير، والبرد والعري.","11:28":"وفضلا عن هذه المخاطر الخارجية، يزداد علي الضغط يوما بعد يوم، إذ أحمل هم جميع الكنائس.","11:29":"أهنالك من يضعف ولا أضعف أنا، ومن يتعثر ولا أحترق أنا؟","11:30":"إن كان لابد من الافتخار، فإني سأفتخر بأمور ضعفي.","11:31":"ويعلم الله ، أبو ربنا يسوع، المبارك إلى الأبد، أني لست أكذب:","11:32":"فإن الحاكم الذي أقامه الملك الحارث على ولاية دمشق، شدد الحراسة على مدينة دمشق، رغبة في القبض علي،","11:33":"ولكني تدليت في سل من نافذة في السور، فنجوت من يده.","12:1":"أجل، إن الافتخار لا ينفعني شيئا؛ ولكن سأنتقل إلى ما كشفه لي الرب من رؤى وإعلانات.","12:2":"أعرف إنسانا في المسيح، خطف إلى السماء الثالثة قبل أربع عشرة سنة: أكان ذلك بجسده؟ لا أعلم؛ أم كان بغير جسده؟ لا أعلم. الله يعلم!","12:3":"وأنا أعرف أن هذا الإنسان، أبجسده أم بغير جسده؟ لا أعلم؛ الله يعلم؛","12:4":"قد خطف إلى الفردوس، حيث سمع أمورا مدهشة تفوق الوصف ولا يحق لإنسان أن ينطق بها.","12:5":"بهذا أفتخر! ولكني لا أفتخر بما يخصني شخصيا إلا إذا كان يتعلق بأمور ضعفي.","12:6":"فلو أردت الافتخار، لا أكون غبيا، مادمت أقول الحق. إلا أني أمتنع عن ذلك، لئلا يظن بي أحد فوق ما يراني عليه أو ما يسمعه مني.","12:7":"ولكي لا أتكبر بما لهذه الإعلانات من عظمة فائقة، أعطيت شوكة في جسدي كأنها رسول من الشيطان يلطمني كي لا أتكبر!","12:8":"لأجل هذا تضرعت إلى الرب ثلاث مرات أن ينزعها مني","12:9":"فقال لي: «نعمتي تكفيك، لأن قدرتي تكمل في الضعف!» فأنا أرضى بأن أفتخر مسرورا بالضعفات التي في، لكي تخيم علي قدرة المسيح.","12:10":"فلأجل المسيح، تسرني الضعفات والإهانات والضيقات والاضطهادات والصعوبات، لأني حينما أكون ضعيفا، فحينئذ أكون قويا!","12:11":"ها قد صرت غبيا! ولكن، أنتم أجبرتموني! فقد كان يجب أن تمدحوني أنتم، لأني لست متخلفا في شيء عن أولئك الرسل المتفوقين، وإن كنت لا شيئا.","12:12":"إن العلامات التي تميز الرسول أجريت بينكم في كل صبر، من آيات وعجائب ومعجزات.","12:13":"ففي أي مجال كنتم أصغر قدرا من الكنائس الأخرى إلا في أني لم أكن عبئا ثقيلا عليكم؟ اغفروا لي هذه الإساءة!","12:14":"أنا مستعد الآن أن آتي إليكم مرة ثالثة، ولن أكون عبئا ثقيلا عليكم. فما أسعى إليه ليس هو ما عندكم بل هو أنتم: لأنه ليس على الأولاد أن يوفروا لوالديهم، بل على الوالدين أن يوفروا لأولادهم.","12:15":"وأنا، بكل سرور، أنفق ما عندي، بل أنفق نفسي لأجل أنفسكم، وإن كنت كلما زادت محبتي ألقى حبا أقل.","12:16":"ولكن، ليكن كذلك. (تقولون) إني لم أثقل عليكم بنفسي، ولكني كنت محتالا فسلبتكم بمكر.","12:17":"هل كسبت منكم شيئا بأحد من الذين أرسلتهم إليكم؟","12:18":"التمست من تيطس أن يتوجه إليكم، وأرسلت معه ذلك الأخ، فهل غنم منكم تيطس شيئا؟ ألم نتصرف معكم، أنا وتيطس، بروح واحد وخطوات واحدة؟","12:19":"طالما كنتم تظنون أننا ندافع عن أنفسنا عندكم! ولكننا إنما نتكلم أمام الله في المسيح. وذلك كله، أيها الأحباء، لأجل بنيانكم.","12:20":"فإني أخشى أن آتي إليكم فأجدكم في حالة لا أريدها وتجدوني في حالة لا تريدونها! أي أن يكون بينكم كثير من النزاع والحسد والحقد والتحزب والتجريح والنميمة والتكبر والبلبلة.","12:21":"وأخشى أن يجعلني إلهي ذليلا بينكم عند مجيئي إليكم مرة أخرى، فيكون حزني شديدا على كثيرين من الذين أخطأوا قبلا ولم يتوبوا عما ارتكبوا من دنس وزنى وفسق!","13:1":"هذه المرة الثالثة أنا قادم إليكم. بشهادة شاهدين أو ثلاثة يثبت كل أمر.","13:2":"سبق لي أن أعلنت، وها أنا أقول مقدما وأنا غائب، كما قلت وأنا حاضر عندكم في المرة الثانية، للذين أخطأوا في الماضي وللباقين جميعا: إني إذا عدت إليكم فلا أشفق،","13:3":"مادمتم تطلبون برهانا على أن المسيح يتكلم في. وهو ليس ضعيفا تجاهكم، بل قوي في ما بينكم.","13:4":"فمع أنه قد صلب في ضعف، فهو الآن حي بقدرة الله. ونحن أيضا ضعفاء فيه، ولكننا، بتصرفنا معكم، سنكون أحياء معه بقدرة الله.","13:5":"لذلك امتحنوا أنفسكم لتروا هل أنتم في الإيمان. اختبروا أنفسكم. ألستم تعرفون أنفسكم، أن يسوع المسيح فيكم، إلا إذا تبين أنكم فاشلون؟","13:6":"غير أني أرجو أنه سيتبين لكم أننا نحن لسنا فاشلين.","13:7":"ونصلي إلى الله ألا تفعلوا أي شر، لا لكي يتبين أننا نحن فاضلون، بل لكي تفعلوا أنتم ما هو حق، وإن كنا نحن كأننا فاشلون.","13:8":"فإننا لا نستطيع أن نفعل شيئا ضد الحق بل لأجل الحق.","13:9":"وكم نفرح عندما نكون نحن ضعفاء وتكونون أنتم أقوياء؛ حتى إننا نصلي طالبين لكم الكمال!","13:10":"لهذا أكتب إليكم بهذه الأمور وأنا غائب، حتى إذا حضرت لا ألجأ إلى الحزم بحسب السلطة التي منحني إياها الرب للبنيان لا للهدم.","13:11":"وأخيرا، أيها الإخوة: افرحوا؛ تكملوا؛ تشجعوا؛ اتفقوا في الرأي؛ عيشوا بسلام. وإله المحبة والسلام سيكون معكم!","13:12":"سلموا بعضكم على بعض بقبلة طاهرة.","13:13":"جميع القديسين يسلمون عليكم.","13:14":"ولتكن معكم جميعا نعمة ربنا يسوع المسيح، ومحبة الله، وشركة الروح القدس. آمين!"},"Gal":{"1:1":"من بولس، وهو رسول لا من قبل الناس ولا بسلطة إنسان، بل بسلطة يسوع المسيح والله الآب الذي أقامه من بين الأموات،","1:2":"ومن جميع الإخوة الذين معي، إلى الكنائس في مقاطعة غلاطية.","1:3":"لتكن لكم النعمة والسلام من الله الآب وربنا يسوع المسيح،","1:4":"الذي بذل نفسه من أجل خطايانا لكي ينقذنا من العالم الحاضر الشرير، وفقا لمشيئة إلهنا وأبينا.","1:5":"له المجد إلى أبد الآبدين. آمين!","1:6":"عجبا! كيف تتحولون بمثل هذه السرعة عن الذي دعاكم بنعمة المسيح، وتنصرفون إلى إنجيل غريب؟","1:7":"لا أعني أن هنالك إنجيلا آخر، بل إنما هنالك بعض (المعلمين) الذين يثيرون البلبلة بينكم، راغبين في تحوير إنجيل المسيح.","1:8":"ولكن، حتى لو بشرناكم نحن، أو بشركم ملاك من السماء، بغير الإنجيل الذي بشرناكم به، فليكن ملعونا!","1:9":"وكما سبق أن قلنا، أكر ر القول الآن أيضا: إن كان أحد يبشركم بإنجيل غير الذي قبلتموه، فليكن ملعونا!","1:10":"فهل أسعى الآن إلى كسب تأييد الناس أو الله؟ أم تراني أطلب أن أرضي الناس؟ لو كنت حتى الآن أرضي الناس، لما كنت عبدا للمسيح!","1:11":"وأعلمكم، أيها الإخوة، أن الإنجيل الذي بشرتكم به ليس إنجيلا بشريا.","1:12":"فلا أنا تسلمته من إنسان، ولا تلقنته، بل جاءني بإعلان من يسوع المسيح.","1:13":"فإنكم قد سمعتم بسيرتي الماضية في الديانة اليهودية، كيف كنت أضطهد كنيسة الله متطرفا إلى أقصى حد، ساعيا إلى تخريبها،","1:14":"وكيف كنت متفوقا في الديانة اليهودية على كثيرين من أبناء جيلي في أمتي لكوني غيورا أكثر منهم جدا على تقاليد آبائي.","1:15":"ولكن، لما سر الله ، الذي كان قد أفرزني وأنا في بطن أمي ثم دعاني بنعمته،","1:16":"أن يعلن ابنه في لأبشر به بين الأمم، في الحال لم أستشر لحما ودما،","1:17":"ولا صعدت إلى أورشليم لأقابل الذين كانوا رسلا من قبلي، بل انطلقت إلى بلاد العرب، وبعد ذلك رجعت إلى دمشق.","1:18":"ثم صعدت إلى أورشليم، بعد ثلاث سنوات، لأتعرف ببطرس. وقد أقمت عنده خمسة عشر يوما.","1:19":"ولكني لم أقابل غيره من الرسل إلا يعقوب، أخا الرب.","1:20":"إن ما أكتبه إليكم هنا، وها أنا أمام الله، لست أكذب فيه.","1:21":"وبعد ذلك، جئت إلى بلاد سورية وكيليكية.","1:22":"إلا أنني كنت غير معروف شخصيا لدى كنائس اليهودية التي هي في المسيح.","1:23":"وإنما كانوا يسمعون «أن الذي كان في السابق يضطهدنا، يبشر الآن بإنجيل الإيمان الذي كان يسعى قبلا إلى تخريبه!»","1:24":"فكانوا يمجدون الله بسببي.","2:1":"وبعد أربع عشرة سنة، صعدت مرة ثانية إلى أورشليم بصحبة برنابا، وقد أخذت معي تيطس أيضا.","2:2":"وإنما صعدت إليها استجابة للوحي؛ وبسطت أمامهم الإنجيل الذي أبشر به بين الأمم، ولكن على انفراد أمام البارزين فيهم، لئلا يكون مسعاي في الحاضر والماضي بلا جدوى.","2:3":"ولكن، حتى تيطس الذي كان يرافقني وهو يوناني، لم يضطر أن يختن.","2:4":"إنما أثير الأمر بسبب الإخوة الدجالين الذين أدخلوا بيننا خلسة، فاندسوا ليتجسسوا حريتنا التي لنا في المسيح يسوع، لعلهم يعيدوننا إلى العبودية؛","2:5":"فلم نخضع لهم مستسلمين ولو لساعة واحدة، ليبقى حق الإنجيل ثابتا عندكم.","2:6":"أما الذين كانوا يعتبرون من البارزين، ولا فرق عندي مهما كانت مكانتهم مادام الله لا يراعي وجاهة إنسان، فإنهم لم يزيدوا شيئا على ما أبشر به.","2:7":"بل بالعكس، رأوا أنه عهد إلي بالإنجيل لأهل عدم الختان، كما عهد به إلى بطرس لأهل الختان.","2:8":"لأن الذي استخدم بطرس في رسوليته إلى أهل الختان، استخدمني أيضا بالنسبة إلى الأمم.","2:9":"فلما اتضحت النعمة الموهوبة لي عند يعقوب وبطرس ويوحنا، وهم البارزون باعتبارهم أعمدة، مدوا إلي وإلى برنابا أيديهم اليمنى إشارة إلى المشاركة، فنتوجه نحن إلى الأمم وهم إلى أهل الختان،","2:10":"على ألا نغفل أمر الفقراء، وهذا عينه طالما كنت مجتهدا في العمل له.","2:11":"ولكن لما جاء بطرس إلى مدينة أنطاكية، قاومته وجها لوجه لأنه كان يستحق أن يلام.","2:12":"إذ قبل أن يأتي بعضهم من عند يعقوب، كان بطرس يأكل مع الإخوة الذين من الأمم؛ ولكن لما أتى أولئك، انسحب وعزل نفسه، خوفا من أهل الختان.","2:13":"وجاراه في ريائه باقي الإخوة الذين من اليهود. حتى إن برنابا أيضا انساق إلى ريائهم.","2:14":"فلما رأيت أنهم لا يسلكون باستقامة توافق حق الإنجيل، قلت لبطرس أمام الحاضرين جميعا: «إن كنت وأنت يهودي تعيش كالأمم لا كاليهود، فكيف تجبر الأمم أن يعيشوا كاليهود؟»","2:15":"نحن يهود بالولادة، ولسنا أمما خاطئين.","2:16":"ولكننا، إذ علمنا أن الإنسان لا يتبرر على أساس الأعمال المطلوبة في الشريعة بل فقط بالإيمان بيسوع المسيح، آمنا نحن أيضا بالمسيح يسوع، لنتبرر على أساس الإيمان به، لا على أساس أعمال الشريعة، لأنه على أعمال الشريعة لا يبرر أي إنسان.","2:17":"ولكن، إن كنا ونحن نسعى أن نتبرر في المسيح، قد وجدنا خاطئين أيضا، فهل يكون المسيح خادما للخطيئة؟ حاشا!","2:18":"فإذا عدت أبني ما قد هدمته، فإني أجعل نفسي مخالفا.","2:19":"فإنني، بالشريعة، قد مت عن الشريعة، لكي أحيا لله.","2:20":"مع المسيح صلبت، وفيما بعد لا أحيا أنا بل المسيح يحيا في. أما الحياة التي أحياها الآن في الجسد، فإنما أحياها بالإيمان في ابن الله، الذي أحبني وبذل نفسه عني.","2:21":"إني لا أبطل فاعلية نعمة الله، إذ لو كان البر بالشريعة، لكان موت المسيح عملا لا داعي له.","3:1":"ياأهل غلاطية الأغبياء! من سحر عقولكم، أنتم الذين قد رسم أمام أعينكم يسوع المسيح وهو مصلوب؟","3:2":"أريد أن أستعلم منكم هذا الأمر فقط: أعلى أساس العمل بما في الشريعة نلتم الروح، أم على أساس الإيمان بالبشارة؟","3:3":"أإلى هذا الحد أنتم أغبياء؟ أبعدما ابتدأتم بالروح تكملون بالجسد؟","3:4":"وهل كان اختباركم الطويل بلا جدوى، إن كان حقا بلا جدوى؟","3:5":"فذاك الذي يهبكم الروح، ويجري معجزات في ما بينكم، أيفعل ذلك على أساس أعمال الشريعة أم على أساس الإيمان بالبشارة؟","3:6":"كذلك «آمن إبراهيم بالله، فحسب له ذلك برا».","3:7":"فاعلموا إذن أن الذين هم على مبدأ الإيمان هم أبناء إبراهيم فعلا.","3:8":"ثم إن الكتاب، إذ سبق فرأى أن الله سوف يبرر الأمم على أساس الإيمان، بشر إبراهيم سلفا بقوله: «فيك تتبارك جميع الأمم!»","3:9":"إذن الذين هم على مبدأ الإيمان يباركون مع إبراهيم المؤمن.","3:10":"أما جميع الذين على مبدأ أعمال الشريعة، فإنهم تحت اللعنة، لأنه قد كتب: «ملعون كل من لا يثبت على العمل بكل ما هو مكتوب في كتاب الشريعة!»","3:11":"أما أن أحدا لا يتبر ر عند الله بفضل الشريعة، فذلك واضح، لأن «من تبرر بالإيمان فبالإيمان يحيا».","3:12":"ولكن الشريعة لا تراعي مبدأ الإيمان، بل «من عمل بهذه الوصايا، يحيا بها».","3:13":"إن المسيح حررنا بالفداء من لعنة الشريعة، إذ صار لعنة عوضا عنا، لأنه قد كتب: «ملعون كل من علق على خشبة»،","3:14":"لكي تصل بركة إبراهيم إلى الأمم في المسيح يسوع، فننال عن طريق الإيمان الروح الموعود.","3:15":"أيها الإخوة، بمنطق البشر أقول إنه حتى العهد الذي يقره إنسان، لا أحد يلغيه أو يزيد عليه.","3:16":"وقد وجهت الوعود لإبراهيم ونسله، ولا يقول «وللأنسال» كأنه يشير إلى كثيرين، بل يشير إلى واحد، إذ يقول «ولنسلك»، يعني المسيح.","3:17":"فما أقوله هو هذا: إن عهدا سبق أن أقره الله لا تنقضه الشريعة التي جاءت بعده بأربع مئة وثلاثين سنة، وكأنها تلغي الوعد.","3:18":"فلو كان الميراث يتم على مبدأ الشريعة، لما كان الأمر متعلقا بعد بالوعد. غير أن الله ، بالوعد، أنعم بالميراث على إبراهيم.","3:19":"فلماذا الشريعة إذن؟ إنها فقط أضيفت إظهارا للمعاصي، إلى أن يجيء «النسل» الذي قطع له الوعد، وقد رتبت بملائكة وعلى يد وسيط.","3:20":"ولكن، عندما يصدر الوعد من جانب واحد، فلا لزوم لوسيط. والواعد هنا هو الله وحده.","3:21":"فهل تناقض الشريعة وعود الله؟ حاشا! فلو أعطيت شريعة قادرة أن تحيي، لكان البر بالحقيقة على مبدأ الشريعة.","3:22":"ولكن الكتاب حبس الجميع تحت الخطيئة، حتى إن الوعد، على أساس الإيمان بيسوع المسيح، يوهب للذين يؤمنون.","3:23":"فقبل مجيء الإيمان، كنا تحت حراسة الشريعة، محتجزين إلى أن يعلن الإيمان الذي كان إعلانه منتظرا.","3:24":"إذن، كانت الشريعة هي مؤدبنا حتى مجيء المسيح، لكي نبرر على أساس الإيمان.","3:25":"ولكن بعدما جاء الإيمان، تحررنا من سلطة المؤدب.","3:26":"فإنكم جميعا أبناء الله بالإيمان بالمسيح يسوع.","3:27":"لأنكم، جميع الذين تعمدتم في المسيح، قد لبستم المسيح.","3:28":"لا فرق بعد الآن بين يهودي ويوناني، أو عبد وحر، أو ذكر وأنثى، لأنكم جميعا واحد في المسيح يسوع.","3:29":"فإذا كنتم للمسيح، فأنتم إذن نسل إبراهيم وحسب الوعد وارثون.","4:1":"أقول أيضا مادام الوريث قاصرا، فليس بينه وبين العبد أي فرق، مع أنه صاحب الإرث كله،","4:2":"بل يبقى خاضعا للأوصياء والوكلاء إلى أن تنقضي الفترة التي حددها أبوه.","4:3":"وهذه حالنا نحن أيضا: فإذ كنا قاصرين، كنا في حالة العبودية لمبادىء العالم.","4:4":"ولكن لما جاء تمام الزمان، أرسل الله ابنه، وقد ولد من امرأة وكان خاضعا للشريعة،","4:5":"ليحرر بالفداء أولئك الخاضعين للشريعة، فننال جميعا مقام أبناء الله.","4:6":"وبما أنكم أبناء له، أرسل الله إلى قلوبنا روح ابنه، مناديا: «أبا، ياأبانا».","4:7":"إذن، أنت لست عبدا بعد الآن، بل أنت ابن. ومادمت ابنا، فقد جعلك الله وريثا أيضا.","4:8":"ولكن، لما كنتم في ذلك الحين لا تعرفون الله ، كنتم في حال العبودية.","4:9":"أما الآن وقد عرفتم الله ، بل بالأحرى عرفكم الله ، فكيف ترتدون أيضا إلى تلك المباديء العاجزة الفقيرة التي ترغبون في الرجوع إلى العبودية لها من جديد؟","4:10":"تحتفلون بأيام وأشهر ومواسم وسنين!","4:11":"أخاف عليكم، خشية أن أكون قد تعبت من أجلكم بلا جدوى.","4:12":"أتوسل إليكم أيها الإخوة، أن تكونوا مثلي، لأني أنا أيضا مثلكم. أنتم لم تظلموني بشيء،","4:13":"بل تعرفون أنني في علة بالجسد بشرتكم أول الأمر؛","4:14":"ومع أن العلة التي في جسدي كانت تجربة لكم، فإنكم لم تحتقروني ولم تنفروا مني بسببها، بل قبلتموني كأني ملاك من عند الله، أو كأني المسيح يسوع.","4:15":"فأين غبطتكم تلك؟ فإني أشهد لكم أنكم كنتم ستقلعون عيونكم وتقدمونها لي، لو كان ذلك ممكنا!","4:16":"فهل صرت الآن عدوا لكم لأني كلمتكم بالحق؟","4:17":"إن أولئك (المعلمين) يظهرون من نحوكم حماسة، ولكنها غير صادقة، بل هم يرغبون في عزلكم عنا،","4:18":"لكي تتحمسوا لهم. جميل إظهار الحماسة في ما هو حق، كل حين، وليس فقط حين أكون حاضرا عندكم.","4:19":"ياأطفالي الذين أتمخض بكم مرة أخرى إلى أن تتشكل فيكم صورة المسيح.","4:20":"وكم أود لو أكون الآن حاضرا عندكم، فأخاطبكم بغير هذه اللهجة، لأني متحير في أمركم.","4:21":"قولوا لي، يامن ترغبون في الرجوع إلى العبودية للشريعة، ألستم تسمعون ما جاء في الشريعة؟","4:22":"فإنه قد كتب أن إبراهيم كان له ابنان: أحدهما من الجارية، والآخر من المرأة الحرة.","4:23":"أما ابن الجارية، فقد ولد حسب الجسد. وأما ابن الحرة، فإتماما للوعد.","4:24":"وهذه الحقيقة لها معنى رمزي. فهاتان المرأتان ترمزان إلى عهدين: الأول مصدره جبل سيناء، يجعل المولودين تحته في حال العبودية، ورمزه هاجر.","4:25":"ولفظة هاجر تطلق على جبل سيناء، في بلاد العرب، وتمثل أورشليم الحالية، فإنها مع بنيها في العبودية.","4:26":"أما الثاني، فرمزه الحرة التي تمثل أورشليم السماوية التي هي أمنا.","4:27":"فإنه قد كتب: «افرحي أيتها العاقر التي لا تلد، اهتفي بأعلى صوتك أيتها التي لا تتمخض، لأن أولاد المهجورة أكثر عددا من أولاد التي لها زوج!»","4:28":"وأما أنتم، أيها الإخوة، فأولاد الوعد، على مثال إسحاق.","4:29":"ولكن، كما كان في الماضي المولود بحسب الجسد يضطهد المولود بحسب الروح، فكذلك أيضا يحدث الآن.","4:30":"إنما ماذا يقول الكتاب؟ «اطرد الجارية وابنها، لأن ابن الجارية لا يرث مع ابن الحرة!»","4:31":"إذن، أيها الإخوة، نحن لسنا أولاد الجارية، بل أولاد الحرة.","5:1":"إن المسيح قد حررنا وأطلقنا في سبيل الحرية. فاثبتوا إذن، ولا تعودوا إلى الارتباك بنير العبودية.","5:2":"ها أنا بولس أقول لكم: إن ختنتم، لا ينفعكم المسيح شيئا.","5:3":"وأشهد مرة أخرى لكل مختون بأنه ملتزم أن يعمل بالشريعة كلها.","5:4":"يامن تريدون التبرير عن طريق الشريعة، قد حرمتم المسيح وسقطتم من النعمة!","5:5":"فإننا، بالروح وعلى أساس الإيمان، ننتظر الرجاء الذي ينتجه البر.","5:6":"ففي المسيح يسوع، لا نفع للختان ولا لعدم الختان، بل للإيمان العامل بالمحبة.","5:7":"كنتم تجرون جريا جيدا، فمن أعاقكم حتى لا تذعنوا للحق؟","5:8":"هذا التضليل ليس من الذي دعاكم!","5:9":"إن خميرة صغيرة تخمر العجين كله.","5:10":"ولكن لي ثقة بكم في الرب أنكم لن تعتنقوا رأيا آخر. وكل من يثير البلبلة بينكم سيلقى عقاب ذلك، كائنا من كان.","5:11":"وأما أنا، أيها الإخوة، فلو صح أنني مازلت أدعو إلى الختان، فلماذا مازلت ألقى الاضطهاد؟ إذن لكانت العثرة التي في الصليب قد زالت!","5:12":"ليت الذين يثيرون البلبلة بينكم يبترون أنفسهم!","5:13":"فإنما إلى الحرية قد دعيتم، أيها الإخوة؛ ولكن لا تتخذوا من الحرية ذريعة لإرضاء الجسد، بل بالمحبة كونوا عبيدا في خدمة أحدكم الآخر.","5:14":"فإن الشريعة كلها تتم في وصية واحدة: «أن تحب قريبك كنفسك».","5:15":"فإذا كنتم تنهشون وتفترسون بعضكم بعضا، فاحذروا أن يفني أحدكم الآخر!","5:16":"إنما أقول: اسلكوا في الروح. وعندئذ لا تتممون شهوة الجسد أبدا.","5:17":"فإن الجسد يشتهي بعكس الروح، والروح بعكس الجسد؛ وهذان يقاوم أحدهما الآخر حتى إنكم لا تفعلون ما ترغبون فيه.","5:18":"ولكن إذا كنتم خاضعين لقيادة الروح، فلستم في حال العبودية للشريعة.","5:19":"أما أعمال الجسد فظاهرة، وهي: الزنى والنجاسة والدعارة،","5:20":"وعبادة الأصنام والسحر، والعداوة والنزاع والغيرة والغضب، والتحزب والانقسام والتعصب،","5:21":"والحسد والسكر والعربدة، وما يشبه هذه. وبالنظر إليها، أقول لكم الآن، كما سبق أن قلت أيضا، إن الذين يفعلون مثل هذه لن يرثوا ملكوت الله!","5:22":"وأما ثمر الروح فهو: المحبة والفرح والسلام، وطول البال واللطف والصلاح، والأمانة","5:23":"والوداعة وضبط النفس. وليس من قانون يمنع مثل هذه الفضائل.","5:24":"ولكن الذين صاروا خاصة للمسيح، قد صلبوا الجسد مع الأهواء والشهوات.","5:25":"إذا كنا نحيا بالروح، فلنسلك أيضا بالروح.","5:26":"لا نكن طامحين إلى المجد الباطل، يستفز بعضنا بعضا، ويحسد أحدنا الآخر!","6:1":"أيها الإخوة، إن سقط أحدكم في خطأ ما فمثل هذا أصلحوه أنتم الروحيين بروح وداعة. واحذر أنت لنفسك لئلا تجرب أيضا.","6:2":"ليحمل الواحد منكم أثقال الآخر، وهكذا تتممون شريعة المسيح.","6:3":"فإن ظن أحد أنه شيء، وهو في الواقع لا شيء، فإنما يخدع نفسه.","6:4":"فليمتحن كل واحد عمله الخاص، وعندئذ يكون له أن يفتخر بما يخصه وحده لا بما يخص غيره.","6:5":"فإن كل واحد سيحمل حمله الخاص.","6:6":"ليشارك الذي يتعلم الكلمة من يعلمها، في جميع الخيرات.","6:7":"لا تنخدعوا: إن الله لا يستهزأ به. فكل ما يزرعه الإنسان، فإياه يحصد أيضا.","6:8":"فإن من يزرع لجسده، فمن الجسد يحصد فسادا. ومن يزرع للروح، فمن الروح يحصد حياة أبدية. فلا نفشل في عمل الخير،","6:9":"لأننا، متى حان الأوان، سنحصد، إن كنا لا نتراخى.","6:10":"فمادامت لنا الفرصة إذن، فلنعمل الخير للجميع، وخصوصا لأهل الإيمان.","6:11":"انظروا بأية حروف كبيرة قد كتبت إليكم هنا بيدي:","6:12":"إن الذين يريدون أن يظهروا في الجسد بمظهر حسن، أولئك يرغمونكم أن تختنوا، فقط لئلا يلقوا الاضطهاد بسبب صليب المسيح.","6:13":"فحتى أولئك الذين يختنون، هم أنفسهم، لا يعملون بالشريعة، بل يريدون لكم أن تختنوا ليفتخروا بجسدكم.","6:14":"أما أنا فحاشا لي أن أفتخر إلا بصليب ربنا يسوع المسيح، الذي به أصبح العالم بالنسبة لي مصلوبا، وأنا أصبحت بالنسبة له مصلوبا.","6:15":"فليس الختان بشيء، ولا عدم الختان بشيء، وإنما (المهم أن يصير الإنسان) خليقة جديدة.","6:16":"فالسلام والرحمة على جميع السالكين وفقا لهذا المبدأ، وعلى إسرائيل الله.","6:17":"لا يسبب لي أحد المتاعب فيما بعد، فإني أحمل في جسدي سمات الرب يسوع.","6:18":"لتكن مع روحكم، أيها الإخوة، نعمة ربنا يسوع المسيح. آمين!"},"Eph":{"1:1":"من بولس، وهو رسول للمسيح يسوع بمشيئة الله، إلى القديسين الأمناء في المسيح يسوع، المقيمين في أفسس.","1:2":"لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح.","1:3":"تبارك الله ، أبو ربنا يسوع المسيح الذي باركنا بكل بركة روحية في الأماكن السماوية.","1:4":"كما كان قد اختارنا فيه قبل تأسيس العالم، لنكون قديسين بلا لوم أمامه.","1:5":"إذ سبق فعيننا في المحبة ليتخذنا أبناء له بيسوع المسيح. وذلك موافق للقصد الذي سرت به مشيئته،","1:6":"بغرض مدح مجد نعمته التي بها أعطانا حظوة لديه في المحبوب:","1:7":"ففيه لنا بدمه الفداء، أي غفران الخطايا؛ بحسب غنى نعمته","1:8":"التي جعلها تفيض علينا مصحوبة بكل حكمة وفهم.","1:9":"إذ كشف لنا سر مشيئته بحسب مرضاته التي قصدها في نفسه،","1:10":"لأجل تدبير تمام الأزمنة، حين يوحد كل شيء تحت رئاسة المسيح، سواء الأشياء التي في السماوات والتي على الأرض.","1:11":"وفي المسيح أيضا قد حصلنا على الميراث الذي سبق أن عينا له، وفقا لقصده، هو الذي يعمل كل شيء كما تقضي مشيئته.","1:12":"والغاية أن نكون سببا لمدح مجده بعدما سبق لنا أن وضعنا رجاءنا في المسيح.","1:13":"وفيه أنتم أيضا (وضعتم رجاءكم) إذ سمعتم كلمة الحق، أي الإنجيل الذي فيه خلاصكم؛ كذلك فيه أيضا ختمتم، إذ آمنتم، بالروح القدس الموعود،","1:14":"هذا الروح الذي هو عربون ميراثنا إلى أن يتم فداء ما قد اقتني: بغر ض مدح مجده.","1:15":"لذلك أنا أيضا، وقد سمعت بما فيكم من الإيمان بالرب يسوع والمحبة لجميع القديسين،","1:16":"لا أنقطع عن شكر الله لأجلكم وعن ذكركم في صلواتي،","1:17":"حتى يهبكم إله ربنا يسوع المسيح، أبو المجد، روح حكمة وإلهام: لتعرفوه معرفة كاملة","1:18":"إذ تستنير بصائر قلوبكم، فتعلموا ما في دعوته لكم من رجاء، وما هو غنى مجد ميراثه في القديسين،","1:19":"وما هي عظمة قدرته الفائقة المعلنة لنا نحن المؤمنين، بحسب عمل اقتدار قوته","1:20":"الذي عمله في المسيح، بإقامته له من بين الأموات. وقد أجلسه عن يمينه في الأماكن السماوية،","1:21":"أرفع جدا من كل رئاسة وسلطة وقوة وسيا دة، ومن كل اسم يسمى، لا في هذا العالم وحسب، بل في ذلك الآتي أيضا.","1:22":"وأخضع كل شيء تحت قدميه، وإياه جعل فوق كل شيء رأسا للكنيسة","1:23":"التي هي جسده وكماله، هو الذي يكمل الكل في الكل.","2:1":"وأنتم كنتم في السابق أمواتا بذنوبكم وخطاياكم،","2:2":"التي كنتم تسلكون فيها حسب مسرى هذا العالم، تابعين رئيس قوات الهواء، ذلك الروح العامل الآن في أبناء العصيان،","2:3":"الذين بينهم نحن أيضا كنا نسلك سابقا في شهوات جسدنا، عاملين ما يريده الجسد والأفكار، وكنا بالطبيعة أولاد الغضب كالآخرين أيضا.","2:4":"أما الله ، وهو غني في الرحمة، فبسبب محبته العظيمة التي أحبنا بها،","2:5":"وإذ كنا نحن أيضا أمواتا بالذنوب، أحيانا مع المسيح، إنما بالنعمة أنتم مخلصون،","2:6":"وأقامنا معه وأجلسنا معه في الأماكن السماوية في المسيح يسوع.","2:7":"وذلك كي يعرض في الدهور القادمة غنى نعمته الفائق في لطفه علينا في المسيح يسوع.","2:8":"فإنكم بالنعمة مخلصون، بالإيمان، وهذا ليس منكم. إنه هبة من الله،","2:9":"لا على أساس الأعمال، حتى لا يفتخر أحد.","2:10":"فإننا نحن تحفة الله، وقد خلقنا في المسيح يسوع لأعمال صالحة أعدها سلفا لنسلك فيها.","2:11":"لذلك اذكروا، أنتم الأمم في الجسد سابقا، يامن تسمون أهل عدم الختان من قبل من يسمون أهل الختان الذي يجري في الجسد باليد،","2:12":"أنكم كنتم في ذلك الحين بلا مسيح، أجانب عن جماعة إسرائيل، وغرباء عن العهود الموعودة، لا رجاء لكم، ومنكرين لله في العالم.","2:13":"أما الآن، ففي المسيح يسوع، أنتم الذين كنتم من قبل بعيدين قد صرتم قريبين بدم المسيح.","2:14":"فإنه هو سلامنا، ذاك الذي جعل الفريقين واحدا وهدم حائط الحاجز الفاصل بينهما،","2:15":"أي العداء: إذ أبطل بجسده شريعة الوصايا ذات الفرائض، لكي يكون من الفريقين إنسانا واحدا جديدا، إذ أحل السلام بينهما،","2:16":"ولكي يصالحهما معا في جسد واحد مع الله بالصليب الذي به قتل العداء.","2:17":"ثم جاء وبشركم بالسلام أنتم البعيدين، (كما بشر بالسلام) أولئك القريبين.","2:18":"فبه لنا كلينا اقتراب إلى الآب بروح واحد.","2:19":"إذن، لستم غرباء وأجانب بعد الآن، بل أنتم رعية مع القديسين وأعضاء في عائلة الله،","2:20":"وقد بنيتم على أساس الرسل والأنبياء، والمسيح يسوع نفسه هو حجر الزاوية الأساس،","2:21":"الذي فيه يتناسق البناء كله فيرتفع ليصير هيكلا مقدسا في الرب.","2:22":"وفيه أنتم أيضا قد بنيتم معا فصرتم مسكنا لله بوجود الروح.","3:1":"لهذا السبب، أنا بولس سجين المسيح يسوع لأجلكم أنتم الأمم …","3:2":"على اعتبار أنكم قد سمعتم بتدبير نعمة الله الموهوبة لي لأجلكم:","3:3":"كيف كشف لي السر عن طريق الوحي، كما كتبت قبلا بإيجاز،","3:4":"ويمكنكم، حينما تقرأون ما كتبته، أن تدركوا اطلاعي العميق على سر المسيح،","3:5":"ذلك السر الذي لم يطلع عليه بنو البشر في الأجيال الماضية مثلما أعلن الآن بوحي الروح لرسله القديسين وأنبيائه:","3:6":"وهو أن الأمم هم شركاء اليهود في الميراث، وأعضاء في الجسد معهم، ولهم أيضا حق الاستفادة من الوعد. وذلك في المسيح يسوع وبفضل الإنجيل","3:7":"الذي صرت أنا خادما له بحسب نعمة الله الموهوبة لي وفقا لعمل قدرته.","3:8":"فلي، أنا الأصغر من أصغر القديسين جميعا، وهبت هذه النعمة: أن أذيع بين الأمم بشارة غنى المسيح الذي لا يحد،","3:9":"وأنير الجميع بمعرفة ما هو تدبير السر الذي أبقاه الله ، خالق كل شيء، مكتوما مدى الأجيال.","3:10":"والغاية أن يتجلى الآن أمام الرئاسات والسلطات في الأماكن السماوية ما يظهر في الكنيسة من حكمة الله المتعددة الوجوه،","3:11":"وفقا للقصد الأزلي الذي قصده الله في المسيح يسوع ربنا،","3:12":"الذي به لنا جرأة واقتراب واثق من جراء الإيمان به","3:13":"فلذلك أطلب إليكم ألا يفتر عزمكم بسبب الضيقات التي أقاسيها لأجلكم، فهي مفخرة لكم.","3:14":"ولهذا السبب أحني ركبتي للآب","3:15":"الذي هو أصل كل أبوة في السماوات وعلى الأرض،","3:16":"لكي يمنحكم، وفقا لغنى مجده، أن يمد الروح الكيان الداخلي في كل منكم بالقوة المؤيدة،","3:17":"ليسكن المسيح في قلوبكم بالإيمان؛ حتى إذا تأصلتم وتأسستم في المحبة،","3:18":"تصيرون قادرين تماما أن تدركوا، مع القديسين جميعا، ما هو العرض والطول والعلو والعمق،","3:19":"وتعرفوا محبة المسيح التي تفوق المعرفة، فتمتلئوا حتى تبلغوا ملء الله كله.","3:20":"والقادر أن يفعل، وفقا للقدرة العاملة فينا، ما يفوق بلا حصر كل ما نطلب أو نتصور،","3:21":"له المجد في الكنيسة، في المسيح يسوع، مدى الأجيال والدهور! آمين …","4:1":"... إذن، أنا السجين في الرب، أناشدكم أن تسلكوا سلوكا يليق بالدعوة التي إليها دعيتم،","4:2":"بكل تواضع ووداعة وطول بال، محتملين بعضكم بعضا في المحبة،","4:3":"مجتهدين أن تحافظوا على وحدة الروح برابطة الوفاق. فإنما هناك جسد واحد وروح واحد،","4:4":"مثلما دعيتم، جميعكم، دعوة لها رجاء واحد.","4:5":"ولكم رب واحد، وإيمان واحد، ومعمودية واحدة،","4:6":"وإله وآب واحد للجميع، وهو فوق الجميع وبالجميع وفي الجميع.","4:7":"على أن كل واحد منا قد أعطي نعمة توافق مقدار ما يهبه المسيح.","4:8":"لذلك يقول (الوحي): «إذ صعد إلى الأعالي، ساق أسرى، ووهب الناس مواهب!»","4:9":"وأما أنه «صعد»، فما معنى هذا سوى أنه كان قد نزل أيضا إلى الأقسام السفلى في الأرض؟","4:10":"إن الذي نزل هو نفسه الذي صعد إلى ما فوق جميع السماوات لكي يملأ كل شيء.","4:11":"وهو قد وهب البعض أن يكونوا رسلا، والبعض أنبياء، والبعض مبشرين والبعض رعاة ومعلمين،","4:12":"لتأهيل القديسين من جهة عمل الخدمة، لبنيان جسد المسيح،","4:13":"حتى نصل جميعا إلى وحدة الإيمان ووحدة المعرفة لابن الله، إلى إنسان تام البلوغ، إلى مقدار قامة ملء المسيح.","4:14":"وذلك حتى لا نكون فيما بعد أطفالا تتقاذفنا وتحملنا كل ريح تعليم يقوم على خداع الناس والمكر بهم لجرهم إلى الضلال الملفق،","4:15":"بل نتمسك بالحق في المحبة، فننمو في كل شيء نحو من هو الرأس، أي المسيح.","4:16":"فمنه يستمد الجسد كله تماسكه وترابطه بمساندة كل مفصل وفقا لمقدار العمل المخصص لكل جزء، لينشيء نموا يؤول إلى بنيان الجسد بنيانا ذاتيا في المحبة.","4:17":"أقول هذا إذن، وأشهد في الرب، راجيا ألا تسلكوا فيما بعد كما يسلك الأمم في عقم ذهنهم،","4:18":"لكونهم مظلمي البصيرة ومتغربين عن حياة الله بسبب ما فيهم من جهل وقساوة قلب.","4:19":"فهؤلاء، إذ طرحوا جانبا كل إحساس، استسلموا للإباحية ليرتكبوا كل نجاسة بشهوة نهمة لا ترتوي.","4:20":"أما أنتم، فلم تتعلموا المسيح هكذا،","4:21":"إذا كنتم قد سمعتموه حقا وتلقيتم فيه التعليم الموافق للحق الذي في يسوع!","4:22":"وهو أن تخلعوا ما يتعلق بسيرتكم الماضية: الإنسان العتيق الذي يفسد نفسه بالشهوات الخداعة؛","4:23":"وتتجددوا في روح ذهنكم؛","4:24":"وتلبسوا الإنسان الجديد المخلوق على مثال الله في البر والقداسة بالحق.","4:25":"لذلك اخلعوا عنكم الكذب، وتكلموا بالصدق كل واحد مع قريبه، لأننا أعضاء بعضنا لبعض.","4:26":"إن غضبتم، فلا تخطئوا؛ لا تدعوا الشمس تغيب وأنتم غاضبون،","4:27":"ولا تتيحوا فرصة لإبليس!","4:28":"ومن كان سارقا، فلا يسرق في ما بعد، بل بالأحرى ليكد ويستخدم يديه في عمل شريف ليكون عنده ما يشارك فيه المحتاجين.","4:29":"لا تخرج من أفواهكم كلمة فاسدة، بل الكلام الصالح للبنيان الذي تدعو إليه الحاجة، كي يعطي السامعين نعمة.","4:30":"ولا تحزنوا روح الله، الروح القدس الذي به ختمتم ليوم الفداء.","4:31":"انزعوا عنكم كل حقد ونقمة وغضب وصخب وسباب وكل شر.","4:32":"وكونوا لطفاء بعضكم نحو بعض، شفوقين، مسامحين بعضكم بعضا كما سامحكم الله في المسيح.","5:1":"فاقتدوا إذن بالله كأولاد أحباء،","5:2":"واسلكوا في المحبة على مثال المسيح الذي أحبنا وبذل نفسه لأجلنا تقدمة وذبيحة لله طيبة الرائحة.","5:3":"أما الزنى، وكل نجاسة أو شهوة نهمة، فلا يذكر بينكم حتى اسمها، كما يليق بالقديسين.","5:4":"وكذلك البذاءة والكلام السفيه والهزل، فهي غير لائقة. وإنما أحرى بكم أن تلهجوا بالشكر لله!","5:5":"فإنكم تعلمون هذا جيدا: أن كل زان أو نجس أو صاحب شهوة نهمة، ما هو إلا عابد أصنام، ليس له ميراث في ملكوت المسيح والله.","5:6":"لا يخدعكم أحد بكلام باطل! فبسبب هذه الأمور يحل غضب الله على أبناء العصيان.","5:7":"إذن، لا تكونوا شركاء لهم:","5:8":"فقد كنتم في الماضي ظلاما، ولكنكم الآن نور في الرب. فاسلكوا سلوك أولاد النور.","5:9":"فإن ثمر النور يكون في كل صلاح واستقامة وحق.","5:10":"هكذا تختبرون الأمور التي ترضي الرب.","5:11":"وعليكم ألا تكتفوا بعدم الاشتراك في أعمال الظلام العقيمة، بل بالأحرى أن تفضحوها أيضا.","5:12":"فالأمور التي يفعلونها سرا، قبيح حتى ذكرها.","5:13":"إلا أن كل شيء، إذا ما فضح النور أمره، يصير مكشوفا:","5:14":"لأن الذي يكشف كل شيء هو النور. لذلك يقال: «استيقظ أيها النائم، وقم من بين الأموات، فيشرق عليك نور المسيح!»","5:15":"فانتبهوا تماما إذن كيف تسلكون بتدقيق، لا سلوك الجهلاء بل سلوك العقلاء،","5:16":"مستغلين الوقت أحسن استغلال، لأن الأيام شريرة.","5:17":"لذلك لا تكونوا أغبياء، بل افهموا ما هي مشيئة الرب.","5:18":"لا تسكروا بالخمر، ففيها الخلاعة، وإنما امتلئوا بالروح،","5:19":"محدثين بعضكم بعضا بمزامير وتسابيح وأناشيد روحية، مرنمين ومرتلين بقلوبكم للرب؛","5:20":"رافعين الشكر كل حين وعلى كل شيء لله والآب، باسم ربنا يسوع المسيح؛","5:21":"خاضعين بعضكم لبعض في مخافة المسيح.","5:22":"أيتها الزوجات، اخضعن لأزواجكن، كما للرب.","5:23":"فإن الزوج هو رأس الزوجة كما أن المسيح أيضا هو رأس الكنيسة (جسده)، وهو نفسه مخلص الجسد.","5:24":"فكما أن الكنيسة قد أخضعت للمسيح، فكذلك الزوجات أيضا لأزواجهن، في كل شيء.","5:25":"أيها الأزواج، أحبوا زوجاتكم مثلما أحب المسيح الكنيسة وبذل نفسه لأجلها،","5:26":"لكي يقدسها مطهرا إياها بغسل الماء، بالكلمة،","5:27":"حتى يزفها إلى نفسه كنيسة بهية لا يشوبها عيب أو تجعد أو أية نقيصة مشابهة بل تكون مقدسة خالية من العيوب.","5:28":"على هذا المثال يجب على الأزواج أن يحبوا زوجاتهم كأجسادهم. إن من يحب زوجته، يحب نفسه.","5:29":"فلا أحد يبغض جسده البتة، بل يغذيه ويعتني به، كما يعامل المسيح أيضا الكنيسة.","5:30":"فإننا نحن أعضاء جسده.","5:31":"لذلك يستقل الزوج عن أبيه وأمه، ويتحد بزوجته، فيصير الاثنان جسدا واحدا.","5:32":"هذا السر عظيم ولكنني أشير به إلى المسيح والكنيسة!","5:33":"إنما أنتم أيضا، كل بمفرده، ليحب كل واحد منكم زوجته كنفسه. وأما الزوجة، فعليها أن تهاب زوجها.","6:1":"أيها الأولاد، أطيعوا والديكم في (رضى) الرب. فهذا هو الصواب:","6:2":"«أكرم أباك وأمك» وهذه أول وصية مرتبطة بوعد","6:3":"«لكي تلاقي الخير ويطول عمرك على الأرض!»","6:4":"وأنتم، أيها الآباء، لا تثيروا غضب أولادكم. وإنما ربوهم بتأديب الرب وتحريضه.","6:5":"أيها العبيد، أطيعوا سادتكم البشريين بخوف وارتعاد، من قلب صادق، كمن يطيع المسيح،","6:6":"غير عاملين بجد فقط حين تكون عيونهم عليكم كمن يحاول إرضاء الناس، بل انطلاقا من كونكم عبيدا للمسيح،","6:7":"عاملين بمشيئة الله من القلب، خادمين بنية حسنة كما للرب، لا للناس.","6:8":"فأنتم تعلمون أنه مهما عمل كل واحد من الخير، فسوف ينال المكافأة من الرب، سواء أكان عبدا أم حرا.","6:9":"وأنتم، أيها السادة، عاملوهم بمثل هذه المعاملة غير لاجئين إلى التهديد، عالمين أن سيدكم وسيدهم هو في السماء، وهو لا يراعي مقامات الناس.","6:10":"وختاما، تشددوا في الرب وفي قدرة قوته.","6:11":"البسوا سلاح الله الكامل، لتتمكنوا من الصمود في وجه مكايد إبليس.","6:12":"فإن حربنا ليست ضد ذوي اللحم والدم، بل ضد الرئاسات، ضد السلطات، ضد أسياد العالم حكام هذا الظلام، ضد قوى الشر الروحية في الأماكن السماوية.","6:13":"لذلك اتخذوا سلاح الله الكامل، لتتمكنوا من المقاومة في يوم الشر، ومن الصمود أيضا بعد تحقيق كل هدف.","6:14":"فاصمدوا إذن بعد أن تتخذوا الحق حزاما لأوساطكم، والبر درعا لصدوركم،","6:15":"والاستعداد لنشر بشارة السلام حذاء لأقدامكم.","6:16":"وفوق هذا كله، احملوا الإيمان ترسا به تقدرون أن تطفئوا جميع سهام الشرير المشتعلة.","6:17":"واتخذوا الخلاص خوذة للرأس، وكلمة الله سيف الروح.","6:18":"كونوا مصلين في كل حال، بكل صلاة وطلبة في الروح، وساهرين لهذا الغرض عينه مواظبين تماما على جميع الطلبات لأجل القديسين جميعا،","6:19":"ولأجلي كي ألهم ما أنطق به كلما فتحت فمي لأعلن بجرأة سر الإنجيل","6:20":"الذي أنا سفيره المقيد بالسلاسل، فأكون جريئا في إعلانه كما يجب أن أتكلم به.","6:21":"ولكي تعرفوا أحوالي وأخبار عملي، فإن تيخيكس، الأخ الحبيب والخادم الأمين في الرب، يخبركم بها جميعا.","6:22":"وقد أرسلته إليكم لهذا الأمر بعينه: لتعرفوا أحوالي فتتشجع قلوبكم.","6:23":"سلام إلى الإخوة، ومحبة مع إيمان، من الله الآب والرب يسوع المسيح!","6:24":"لتكن النعمة مع جميع الذين يحبون ربنا يسوع المسيح محبة لا يعتريها الفساد!"},"Phi":{"1:1":"من بولس وتيموثاوس، عبدي المسيح يسوع، إلى جميع القديسين في المسيح يسوع، المقيمين في مدينة فيلبي، بمن فيهم من رعاة ومدبرين.","1:2":"لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح.","1:3":"إني أشكر إلهي كلما تذكرتكم،","1:4":"إذ أتضرع بفرح لأجلكم جميعا كل حين في جميع صلواتي،","1:5":"بسبب مساهمتكم في نشر الإنجيل من أول يوم إلى الآن.","1:6":"ولي ثقة في هذا الأمر بالذات: أن الذي بدأ فيكم عملا صالحا سوف يتممه إلى يوم المسيح يسوع.","1:7":"كما أن من الحق أن يكون لي هذا الشعور تجاهكم جميعا، لأني أحتفظ بكم في قلبي، لكونكم جميعا شركاء لي في النعمة، سواء أكان في قيودي أم في الدفاع عن الإنجيل وتثبيته.","1:8":"فإن الله شاهد لي كيف أحن إليكم جميعا في عواطف المسيح يسوع.","1:9":"وصلاتي لأجلكم هي هذه: أن تزداد محبتكم أكثر فأكثر في تمام المعرفة والإدراك،","1:10":"لكي تستحسنوا الأمور الممتازة، حتى تكونوا طاهرين وخالين من العثرات إلى يوم المسيح،","1:11":"كاملين في ثمار البر الآتية بيسوع المسيح، لمجد الله وحمده.","1:12":"على أني أريد أن تعلموا، أيها الإخوة، أن أحوالي قد أدت في الواقع إلى انتشار الإنجيل بنجاح،","1:13":"حتى إنه قد صار معروفا لدى الحرس الإمبراطوري كله ولدى الباقين جميعا أن قيودي إنما هي لأجل المسيح؛","1:14":"كما أن أكثر الإخوة، وقد صاروا واثقين بالرب بسبب قيودي، يجرؤون على التبشير بكلمة الله دون خوف.","1:15":"حقا أن بعضهم يبشرون بالمسيح عن حسد ونزاع؛ وأما الآخرون فعن حسن نية.","1:16":"فهؤلاء تدفعهم المحبة، عالمين أني قد عينت للدفاع عن الإنجيل؛","1:17":"وأولئك يدفعهم التحزب، فينادون بالمسيح بغير إخلاص، ظنا منهم أنهم يثيرون علي الضيق إضافة إلى القيود.","1:18":"فماذا إذن؟ مهما يكن، وفي أي حال، فإن المسيح ينادى به، سواء أكان بذريعة أم بحق. وبهذا أنا أفرح وسأفرح بعد!","1:19":"فإنني أعلم أن هذا الأمر سيؤدي إلى الإفراج عني، بفضل صلاتكم وبمعونة روح يسوع المسيح؛","1:20":"وفقا لما أتوقعه وأرجوه: أني لن أفشل في شيء، بل في كل جرأة وكما في كل حين فكذلك الآن أيضا، يتعظم المسيح في جسدي، سواء أكان بالحياة أم بالموت.","1:21":"فالحياة عندي هي المسيح، والموت ربح لي.","1:22":"ولكن، إن كان لي أن أحيا في الجسد، فحياتي تهييء لي عملا مثمرا. ولست أدري أي الاثنين أختار!","1:23":"فأنا تحت ضغط من كليهما: إذ إني راغب في أن أرحل وأقيم مع المسيح، وهذا أفضل بكثير جدا؛","1:24":"ولكن بقائي في الجسد أشد ضرورة من أجلكم.","1:25":"وما دامت لي ثقة بهذا، أعلم أني سأبقى وأقيم معكم جميعا، لأجل تقدمكم في الإيمان وفرحكم فيه،","1:26":"ليزداد بسببي افتخاركم بالمسيح بحضوري بينكم من جديد.","1:27":"إنما عيشوا عيشة تليق فقط بإنجيل المسيح. حتى إذا جئت وشاهدتكم أو بقيت غائبا عنكم، أسمع أخباركم وأعرف أنكم ثابتون في روح واحد، وبنفس واحدة تجاهدون معا لأجل الإيمان المعلن في الإنجيل،","1:28":"غير مرتعبين في شيء من الذين يقاومونكم، فإن في مقاومتهم دليلا على هلاكهم هم وعلى خلاصكم أنتم، وذلك من عند الله.","1:29":"فقد وهب لكم، لأجل المسيح، لا أن تؤمنوا به وحسب، بل أيضا أن تتألموا لأجله،","1:30":"مجاهدين الجهاد عينه الذي رأيتموه في والذي تسمعون الآن أنه في.","2:1":"فما دام لنا التشجيع في المسيح، والتعزية في المحبة، والشركة في الروح، ولنا المراحم والحنو،","2:2":"فتمموا فرحي بأن يكون لكم رأي واحد ومحبة واحدة ونفس واحدة وفكر واحد.","2:3":"لا يكن بينكم شيء بروح التحزب والافتخار الباطل، بل بالتواضع ليعتبر كل واحد منكم غيره أفضل كثيرا من نفسه،","2:4":"مهتما لا بمصلحته الخاصة بل بمصالح الآخرين أيضا.","2:5":"فليكن فيكم هذا الفكر الذي هو أيضا في المسيح يسوع.","2:6":"إذ إنه، وهو الكائن في هيئة الله، لم يعتبر مساواته لله خلسة، أو غنيمة يتمسك بها؛","2:7":"بل أخلى نفسه، متخذا صورة عبد، صائرا شبيها بالبشر؛","2:8":"وإذ ظهر بهيئة إنسان، أمعن في الاتضاع، وكان طائعا حتى الموت، موت الصليب.","2:9":"لذلك أيضا رفعه الله عاليا، وأعطاه الاسم الذي يفوق كل اسم،","2:10":"لكي تنحني سجودا لاسم يسوع كل ركبة، سواء في السماء أم على الأرض أم تحت الأرض،","2:11":"ولكي يعترف كل لسان بأن يسوع المسيح هو الرب، لمجد الله الآب.","2:12":"إذن، ياأحبائي، كما كنتم تطيعون دائما، لا كما لو أنني حاضر وحسب، بل بالأحرى كثيرا الآن وأنا غائب، كذلك اسعوا لتحقيق خلاصكم عمليا بخوف وارتعاد،","2:13":"لأن الله هو الذي ينشيء فيكم الإرادة والعمل لأجل مرضاته.","2:14":"فافعلوا كل شيء دون تذمر أو جدال،","2:15":"لتكونوا بلا أذى وبسطاء، أولادا لله لا يعابون بشيء في وسط جيل منحرف فاسد، تضيئون بينهم كأنوار في العالم،","2:16":"حاملين كلمة الحياة، لتكونوا في يوم المسيح موضع فخر بأني ما سعيت باطلا ولا اجتهدت عبثا.","2:17":"حتى لو سفك دمي سكيبا فوق ذبيحة إيمانكم وخدمته، فإني أفرح وأبتهج معكم جميعا.","2:18":"هكذا أيضا افرحوا أنتم، وابتهجوا معي.","2:19":"غير أني أرجو في الرب يسوع أن أرسل إليكم تيموثاوس عن قريب، لكي تطيب نفسي بمعرفة أحوالكم.","2:20":"فليس عندي أحد غيره يهتم مثلي بأحوالكم بإخلاص.","2:21":"فإن الجميع يسعون وراء مصالحهم الخاصة، لا لأجل المسيح يسوع.","2:22":"أما تيموثاوس، فأنتم تعرفون أنه مختبر، إذ خدم معي في التبشير بالإنجيل كأنه ولد يعاون أباه.","2:23":"فإياه أرجو أن أرسل حالما يتبين لي كيف ستجري أحوالي.","2:24":"ولكن لي ثقة في الرب بأني، أنا نفسي، سآتي إليكم عن قريب.","2:25":"إلا أني رأيت من الضروري أن أرسل إليكم أبفروديتس، أخي ومعاوني ورفيقي في التجند، والمرسل من قبلكم عاملا على سد حاجتي،","2:26":"إذ كان مشتاقا إليكم جميعا، ومكتئبا لسماعكم بمرضه.","2:27":"فقد مرض حتى أشرف على الموت، ولكن الله أشفق عليه، وليس عليه وحده، بل علي أنا أيضا، لئلا يصيبني حزن على حزن.","2:28":"لذلك عجلت كثيرا في إرساله إليكم، حتى إذا رأيتموه من جديد تفرحون أنتم وأكون أنا أقل حزنا.","2:29":"فاقبلوه إذن في الرب بكل فرح، وعاملوا أمثاله بالإكرام.","2:30":"فإنه من أجل عمل المسيح أشرف على الموت، مخاطرا بحياته ليسد ما نقص من خدمتكم لي.","3:1":"وبعد، ياإخوتي، افرحوا في الرب. لا يزعجني أن أكتب إليكم بالأمور نفسها، فإن ذلك يجعلكم في مأمن.","3:2":"خذوا حذركم من «الكلاب»، من العمال الأشرار، من الذين يبترون الجسد.","3:3":"فإننا نحن أهل الختان الحق، لأننا إنما نعبد بروح الله ونفتخر في المسيح يسوع، ولا نعتمد على أمور الجسد،","3:4":"مع أن من حقي أنا أيضا أن أعتمد عليها. فإن خطر على بال أحد أن يعتمد على أمور الجسد، فأنا أحق منه:","3:5":"فمن جهة الختان، مختون في اليوم الثامن من عمري؛ وأنا من جنس إسرائيل، من سبط بنيامين، عبراني من العبرانيين؛ ومن جهة الشريعة، أنا فريسي؛","3:6":"ومن جهة الحماسة، مضطهد للكنيسة؛ ومن جهة البر المطلوب في الشريعة، كنت بلا لوم.","3:7":"ولكن، ما كان لي من ربح، فقد اعتبرته خسارة، من أجل المسيح.","3:8":"بل إني أعتبر كل شيء خسارة، من أجل امتياز معرفة المسيح يسوع ربي؛ فمن أجله تحملت خسارة كل شيء، وأعتبر كل شيء نفاية، لكي أربح المسيح","3:9":"ويكون لي فيه مقام، إذ ليس لي بري الذاتي القائم على أساس الشريعة، بل البر الآتي من الإيمان بالمسيح، البر الذي من عند الله على أساس الإيمان.","3:10":"وغايتي أن أعرف المسيح وقوة قيامته والشركة في آلامه؛ والتشبه به في موته،","3:11":"على رجاء القيامة من بين الأموات!","3:12":"لست أدعي أني قد نلت الجائزة أو بلغت الكمال. ولكني ماأزال أسعى لاقتنائها، كما أن المسيح يسوع قد اقتناني.","3:13":"أيها الإخوة، أنا لا أعتبر نفسي قد نلت الجائزة، ولكني أفعل أمرا واحدا: أنسى ما هو وراء وأتقدم إلى ما هو أمام،","3:14":"إذ أسعى إلى الهدف، لنوال تلك الجائزة التي يدعونا الله إليها دعوة عليا في المسيح يسوع.","3:15":"جميع البالغين فينا، ليكن فيهم هذا الفكر. وإن كان فيكم غير هذا الفكر، فذلك أيضا سيكشفه لكم الله .","3:16":"إنما، لنواصل السير من حيث قد وصلنا، في المنهج نفسه.","3:17":"كونوا جميعا، أيها الإخوة، مقتدين بي؛ ولاحظوا الذين يسلكون بحسب القدوة التي ترونها فينا.","3:18":"فإن كثيرين ممن يسلكون بينكم، وقد ذكرتهم لكم مرارا وأذكرهم الآن أيضا باكيا، إنما هم أعداء لصليب المسيح.","3:19":"الذين مصيرهم الهلاك، وإلههم بطونهم، ومفخرتهم في عيبتهم، وفكرهم منصرف إلى الأمور الأرضية.","3:20":"أما نحن، فإن وطننا في السماوات التي منها ننتظر عودة مخلصنا الرب يسوع المسيح،","3:21":"الذي سيحول جسدنا الوضيع إلى صورة مطابقة لجسده المجيد، وفقا لعمل قدرته على إخضاع كل شيء لنفسه.","4:1":"إذن، ياإخوتي الأحباء والمشتاق إليهم، يافرحي وإكليلي، هكذا اثبتوا في الرب أيها الأحباء.","4:2":"أحث أفودية، كما أحث سنتيخي، أن يكون لهما، في الرب، فكر واحد،","4:3":"أجل، أطلب إليك أنت أيضا، أيها الزميل المخلص، أن تساعدهما، لأنهما جاهدتا معي في خدمة الإنجيل، هما وأكليمندس ومعاوني الآخرون، المكتوبة أسماؤهم في سجل الحياة.","4:4":"افرحوا في الرب دائما، وأقول أيضا: افرحوا.","4:5":"ليكن طول بالكم معروفا لدى الناس جميعا. إن الرب قريب.","4:6":"لا تقلقوا من جهة أي شيء، بل في كل أمر لتكن طلباتكم معروفة لدى الله، بالصلاة والدعاء، مع الشكر.","4:7":"وسلام الله، الذي تعجز العقول عن إدراكه، يحرس قلوبكم وأفكاركم في المسيح يسوع.","4:8":"وختاما، أيها الإخوة: كل ما كان حقا، وكل ما كان شريفا، وكل ما كان عادلا، وكل ما كان طاهرا وكل ما كان مستحبا، وكل ما كان حسن السمعة، وكل ما كان فيه فضيلة وخصلة حميدة، فاشغلوا أفكاركم به.","4:9":"واعملوا بها ما تعلمتم وتلقيتم وسمعتم مني وما رأيتم في. وإله السلام يكون معكم.","4:10":"ثم إني فرحت في الرب فرحا عظيما إذ إنكم الآن قد جددتم مرة أخرى اهتمامكم بي. فمع أنه كان لكم مثل هذا الاهتمام، فإن الفرصة لم تتيسر لكم من قبل.","4:11":"لست أعني أني كنت في حاجة، فأنا قد تعلمت أن أكون قنوعا في كل حال.","4:12":"وأعرف كيف أعيش في العوز، وكيف أعيش في الوفرة. فإني، في كل شيء، وفي جميع الأحوال، متدرب على الشبع وعلى الجوع، وعلى العيش في الوفرة أو في العوز.","4:13":"إني أستطيع كل شيء، في المسيح الذي يقويني.","4:14":"إلا أنكم حسنا فعلتم إذ ساهمتم في تبديد ضيقتي.","4:15":"وتعرفون أيضا، يامؤمني فيلبي، أنه عند ابتداء خدمتي للإنجيل، إذ انطلقت من مقاطعة مقدونية، ما من كنيسة ساهمت معي في حساب العطاء والأخذ إلا أنتم وحدكم.","4:16":"حتى وأنا في مدينة تسالونيكي، بعثتم إلي بما أحتاج إليه، لا مرة واحدة بل أكثر.","4:17":"والواقع أني لا أسعى إلى العطايا، بل أسعى إلى الفائدة المتكاثرة لحسابكم.","4:18":"فالآن عندي كل ما يسد حاجتي ويزيد عنها. أنا في بحبوحة إذ تسلمت من أبفروديتس ما بعثتم به إلي، عطرا طيب الرائحة، ذبيحة يقبلها الله ويسر بها.","4:19":"وإن إلهي سيسد حاجاتكم كلها إلى التمام، وفقا لغناه في المجد، في المسيح يسوع.","4:20":"فلإلهنا وأبينا، المجد إلى دهر الدهور. آمين!","4:21":"سلموا على كل قديس في المسيح يسوع.","4:22":"الإخوة الذين معي يسلمون عليكم. ويسلم عليكم جميع القديسين، ولاسيما الذين هم من حاشية القيصر.","4:23":"لتكن نعمة ربنا يسوع المسيح مع روحكم. آمين!"},"Col":{"1:1":"من بولس وهو رسول للمسيح يسوع بمشيئة الله، ومن الأخ تيموثاوس،","1:2":"إلى الإخوة القديسين والأمناء في المسيح، المقيمين في مدينة كولوسي. لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح.","1:3":"إننا دائما نرفع الشكر لله، أبي ربنا يسوع المسيح فيما نصلي لأجلكم.","1:4":"إذ بلغنا خبر إيمانكم بالمسيح يسوع والمحبة التي لكم نحو جميع القديسين،","1:5":"بسبب الرجاء المحفوظ لكم في السماوات، الرجاء الذي سمعتم به سابقا في كلمة الحق التي في الإنجيل","1:6":"والتي وصلت إليكم كما تنتشر الآن في العالم أجمع، منتجة الثمر ونامية، مثلما يحدث بينكم أنتم منذ أن سمعتم بنعمة الله واختبرتموها بالحق،","1:7":"على حسب ما تعلمتم من أبفراس شريكنا العبد الحبيب، والخادم الأمين للمسيح عندكم","1:8":"وهو نفسه أخبرنا بما لكم من المحبة في الروح.","1:9":"لذلك نحن أيضا، من اليوم الذي فيه سمعنا بأخباركم، مازلنا نصلي ونتضرع لأجلكم، لأن تمتلئوا من تمام المعرفة لمشيئة الله في كل حكمة وإدراك روحي،","1:10":"لكي تسلكوا سلوكا لائقا بالرب ومرضيا في كل شيء، منتجين الثمر في كل عمل صالح ونامين في معرفة الله إلى التمام،","1:11":"متشددين بكل قوة موافقة لقدرة مجده، لتتمكنوا تماما من الاحتمال وطول البال،","1:12":"رافعين الشكر بفرح للآب الذي جعلكم أهلا للاشتراك في ميراث القديسين في (ملكوت) النور،","1:13":"هو الذي أنقذنا من سلطة الظلام ونقلنا إلى ملكوت ابن محبته","1:14":"الذي فيه لنا الفداء، أي غفران الخطايا.","1:15":"هو صورة الله الذي لا يرى، والبكر على كل ما قد خلق،","1:16":"إذ به خلقت جميع الأشياء: ما في السماوات وما على الأرض، ما يرى وما لا يرى، أعروشا كانت أم سيادات أم رئاسات أم سلطات. كل ما في الكون قد خلق به ولأجله.","1:17":"هو كائن قبل كل شيء، وبه يدوم كل شيء.","1:18":"وهو رأس الجسد، أي الكنيسة؛ هو البداءة وبكر القائمين من بين الأموات، ليكون له المقام الأول في كل شيء.","1:19":"فإنه فيه سر الله أن يحل بكل ملئه،","1:20":"وأن يصالح به كل شيء مع نفسه، إذ أحل السلام بدمه على الصليب، فبه يصالح كل شيء، سواء كان ما على الأرض أو ما في السماوات.","1:21":"وأنتم، يامن كنتم في الماضي أجانب وأعداء في الفكر، بأعمالكم الشريرة،","1:22":"قد صالحكم الآن في جسد بشرية (ابنه) بالموت. وذلك لكي يحضركم فتمثلوا أمامه وأنتم قديسون بلا ذنب ولا لوم.","1:23":"على أن تثبتوا فعلا في الإيمان، مؤسسين وراسخين وغير متحولين عن رجاء الإنجيل الذي سمعتموه والذي بشر به للخليقة كلها تحت السماء، وله صرت أنا بولس خادما.","1:24":"والآن أنا أفرح في الآلام التي أقاسيها لأجلكم، وأتمم في جسدي ما نقص من ضيقات المسيح لأجل جسده الذي هو الكنيسة،","1:25":"ولها قد صرت أنا خادما بموجب تدبير الله الموهوب لي من أجلكم، وهو أن أتمم كلمة الله، بإعلان","1:26":"السر الذي كان مكتوما طوال العصور والأجيال، ولكن كشف الآن لقديسيه،","1:27":"الذين أراد الله أن يعلن لهم كم هو غني مجد هذا السر بين الأمم: إنه المسيح فيكم، وهو رجاء المجد؛","1:28":"هذا السر نعلنه نحن، واعظين كل إنسان، ومعلمين كل إنسان، في كل حكمة، لكي نحضر كل إنسان كاملا في المسيح.","1:29":"ولأجل هذا أتعب أنا أيضا وأجاهد، بفضل قدرته العاملة في بقوة.","2:1":"فإني أريد أن تعلموا مقدار جهادي لأجلكم ولأجل الذين في مدينة لاودكية، ولأجل جميع الذين لا يعرفونني بالوجه،","2:2":"بغرض أن تتشجع قلوبهم وتكون كلها متحدة في المحبة، لبلوغ الإدراك التام بكل غناه، لمعرفة سر الله، أي المسيح،","2:3":"المخزونة فيه كنوز الحكمة والمعرفة كلها.","2:4":"أقول هذا حتى لا يضللكم أحد بكلام خداع.","2:5":"فمع أني في الجسد غائب، إلا أني في الروح حاضر معكم، أفرح إذ أشاهد ترتيبكم وثباتكم في الإيمان بالمسيح.","2:6":"فمثلما قبلتم المسيح يسوع الرب، ففيه اسلكوا","2:7":"وأنتم متأصلون ومبنيون فيه وراسخون في الإيمان الموافق لما تعلمتم وفائضون بالشكر.","2:8":"احذروا أن يوقعكم أحد فريسة بالفلسفة والغرور الباطل، عملا بتقاليد الناس ومباديء العالم؛ مما لا يوافق المسيح.","2:9":"فإنه فيه، جسديا، يحل الله بكل ملئه،","2:10":"وأنتم مكملون فيه. فهو رأس كل رئاسة وسلطة؛","2:11":"وفيه أيضا ختنتم أنتم ختانا لم تجره الأيدي، إذ نزع عنكم جسد الخطايا البشري وهذا هو ختان المسيح:","2:12":"فقد دفنتم معه في المعمودية، وفيها أيضا أقمتم معه، عن طريق إيمانكم بقدرة الله الذي أقامه من بين الأموات.","2:13":"فأنتم، إذ كنتم أمواتا في الخطايا وعدم ختانكم الجسدي، أحياكم جميعا معه؛ مسامحا لنا جميعا بالخطايا كلها.","2:14":"إذ قد محا صك الفرائض المكتوب علينا والمناقض لمصلحتنا، بل إنه قد أزاله من الوسط، مسمرا إياه على الصليب.","2:15":"وإذ نزع سلاح الرئاسات والسلطات، فضحهم جهارا فيه، وساقهم في موكبه ظافرا عليهم.","2:16":"فلا يحكم عليكم أحد في قضية الأكل والشرب، أو في القضايا المتعلقة بالأعياد ورؤوس الشهور والسبوت؛","2:17":"فهذه كانت ظلالا لما سيأتي، أي للحقيقة التي هي المسيح.","2:18":"لا يحرمكم أحد من جائزتكم، بحملكم على ما يرغب فيه من إظهار التواضع والتعبد للملائكة، داخلا في رؤى يتوهمها، وقد نفخه باطلا ذهنه الجسدي،","2:19":"وهو غير ممسك بالرأس الذي منه يتلقى الجسد كله غذاءه وتماسكه بالمفاصل والأوصال، فينمو النمو الذي يمنحه الله .","2:20":"فمادمتم قد متم مع المسيح بالنسبة لمباديء العالم، فلماذا، كما لو كنتم عائشين في العالم، تخضعون أنفسكم لفرائض مثل هذه:","2:21":"لا تمسك، لا تذق، لا تلمس","2:22":"وهذه أشياء تستهلك وتزول. فتلك الفرائض هي وصايا البشر وتعاليمهم.","2:23":"لها مظاهر الحكمة لما فيها من إفراط في العبادة المصطنعة، وإذلال للذات، وقهر للجسد؛ أمور لا قيمة لها، وما هي إلا لإرضاء الميول البشرية.","3:1":"فبما أنكم قد قمتم مع المسيح، فاسعوا إلى الأمور التي في العلى، حيث المسيح جالس عن يمين الله.","3:2":"احصروا اهتمامكم بالأمور التي في العلى، لا بالأمور الأرضية.","3:3":"فإنكم قد متم، وحياتكم مستورة مع المسيح في الله.","3:4":"فعندما يظهر المسيح، وهو حياتنا، عندئذ تظهرون أنتم أيضا معه في المجد.","3:5":"فأميتوا إذن أعضاءكم الأرضية: الزنى، النجاسة، جموح العاطفة، الشهوة الرديئة، والاشتهاء النهم الذي هو عبادة أصنام.","3:6":"فبسبب هذه الخطايا ينزل غضب الله،","3:7":"وفيها سلكتم في الماضي، حين كنتم تعيشون فيها.","3:8":"وأما الآن، فانزعوا عنكم، أنتم أيضا، هذه الخطايا كلها: الغضب، النقمة، الخبث، التجديف، الكلام القبيح الخارج من أفواهكم.","3:9":"لا يكذب أحدكم على الآخر، إذ قد نزعتم الإنسان العتيق وأعماله","3:10":"ولبستم الجديد الذي يتجدد لبلوغ تمام المعرفة وفقا لصورة خالقه،","3:11":"وفيه لا فرق بين يوناني ويهودي، أو مختون وغير مختون، أو متحضر ومتخلف، أو عبد وحر، بل المسيح هو الكل وفي الكل.","3:12":"فباعتباركم جماعة مختارة من الله، قديسين محبوبين، البسوا دائما عواطف الحنان واللطف والتواضع والوداعة وطول البال،","3:13":"محتملين بعضكم بعضا، ومسامحين بعضكم بعضا. إن كان لأحدكم شكوى على آخر، كما سامحكم الرب، هكذا افعلوا أنتم أيضا.","3:14":"وفوق هذا كله البسوا المحبة، فهي رابطة الكمال.","3:15":"وليملك في قلوبكم سلام المسيح، فإليه قد دعيتم في الجسد الواحد؛ وكونوا شاكرين!","3:16":"لتسكن كلمة المسيح في داخلكم بغنى، في كل حكمة، معلمين وواعظين بعضكم بعضا، مرنمين بمزامير وتسابيح وأناشيد روحية في قلوبكم لله، رافعين له الحمد.","3:17":"ومهما كان ما تعملونه، بالقول أو بالفعل، فليجر كل شيء باسم الرب يسوع، رافعين به الشكر لله الآب.","3:18":"أيتها الزوجات اخضعن لأزواجكن كما يليق (بالعيشة) في الرب.","3:19":"أيها الأزواج، أحبوا زوجاتكم، ولا تعاملوهن بقسوة.","3:20":"أيها الأولاد، أطيعوا والديكم في كل أمر، لأن ذلك مرضي في الرب.","3:21":"أيها الآباء، لا تثيروا غضب أولادكم لئلا يصيبهم الفشل.","3:22":"أيها العبيد، أطيعوا في كل أمر سادتكم البشريين، فلا تعملوا بجد فقط حين تكون عيونهم عليكم، كمن يحاول إرضاء الناس، بل بقلب صادق خائفين الرب.","3:23":"ومهما عملتم، فاجتهدوا فيه من صميم القلب، وكأنه للرب لا للناس،","3:24":"عالمين أنكم سوف تنالون المكافأة بالميراث من الرب. فإنما أنتم عبيد تخدمون الرب المسيح","3:25":"وأما من عمل شرا فسوف ينال جزاء عمله الشرير، وليس محاباة.","4:1":"أيها السادة، عاملوا عبيدكم بالعدل والإنصاف، عالمين أن لكم، أنتم أيضا، سيدا في السماء.","4:2":"داوموا على الصلاة، متيقظين فيها بالشكر،","4:3":"مصلين معا لأجلنا أيضا، كي يفتح لنا الله بابا للكلمة، فنتكلم بسر المسيح الذي من أجله أنا مقيد أيضا،","4:4":"حتى أعلنه كما يجب أن أتكلم به.","4:5":"تصرفوا بحكمة مع الذين هم من خارج الكنيسة، مستغلين الوقت أحسن استغلال.","4:6":"ليكن كلامكم دائما مصحوبا بالنعمة، وليكن مصلحا بملح، فتعرفوا كيف يجب أن تجيبوا كل واحد.","4:7":"أما أحوالي كلها، فسيخبركم بها تيخيكس، الأخ الحبيب والخادم الأمين ورفيقنا العبد في الرب،","4:8":"فإياه قد أرسلت إليكم لهذا الغرض عينه، لتعرفوا أحوالنا ويشجع قلوبكم،","4:9":"يرافقه أونسيموس، الأخ الأمين الحبيب الذي هو من عندكم. فهما يطلعانكم على أحوالنا هنا.","4:10":"يسلم عليكم أرسترخس رفيقي في السجن؛ ومرقس ابن أخت برنابا، وفي شأنه تلقيتم بعض التوصيات: فإن جاء إليكم، فرحبوا به؛","4:11":"ويسوع المعروف باسم يسطس. هؤلاء جميعا من أهل الختان، وهم وحدهم معاوني لأجل ملكوت الله، وقد كانوا لي عزاء.","4:12":"يسلم عليكم أبفراس الذي هو منكم، وهو عبد للمسيح يسوع، يجاهد كل حين لأجلكم في الصلوات لتثبتوا كاملين ولكم تمام اليقين من جهة مشيئة الله كلها.","4:13":"فإني أشهد له بأنه يجتهد كثيرا لأجلكم ولأجل الذين في مدينة لاودكية والذين في مدينة هيرابوليس.","4:14":"يسلم عليكم لوقا الطبيب الحبيب؛ وديماس.","4:15":"سلموا على الإخوة الذين في لاودكية، وعلى نمفاس، وعلى الكنيسة التي في بيته.","4:16":"وبعد أن تقرأ هذه الرسالة عليكم، ابعثوا بها لتقرأ على كنيسة مؤمني لاودكية، وخذوا الرسالة التي عندهم لتقرأوها أنتم أيضا.","4:17":"وقولوا لأرخبس: «تنبه للخدمة التي تلقيتها في الرب، وقم بها كاملة!»","4:18":"هذا السلام بخط يدي، أنا بولس. تذكروا قيودي. لتكن النعمة معكم."},"1Th":{"1:1":"من بولس وسلوانس وتيموثاوس، إلى كنيسة مؤمني تسالونيكي الذين هم في الله الآب والرب يسوع المسيح. لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح.","1:2":"إننا نشكر الله دائما من أجلكم جميعا، إذ نذكركم في صلواتنا دون توقف؛","1:3":"متذكرين، أمام إلهنا وأبينا، ما لكم من عمل الإيمان واجتهاد المحبة وثبات الرجاء، في ربنا يسوع المسيح؛","1:4":"ونحن عالمون، أيها الإخوة أحباء الله، حقيقة اختياركم من قبل الله:","1:5":"لأن تبشيرنا لكم بالإنجيل لم يكن مجرد كلام، بل كان مصحوبا أيضا بالقوة وبالروح القدس وبتمام اليقين. كما أنكم تعلمون تماما ماذا كنا بينكم لأجل مصلحتكم،","1:6":"وقد صرتم مقتدين بنا وبالرب، إذ تقبلتم كلمة الله في وسط ضيقة شديدة بفرح الروح القدس.","1:7":"حتى إنكم صرتم مثالا لجميع المؤمنين المقيمين في مقاطعتي مقدونية وأخائية.","1:8":"فمن عندكم دوت كلمة الرب، منتشرة لا في مقدونية وأخائية فقط، بل إن إيمانكم بالله ذاع في كل مكان، حتى ليس لنا حاجة لأن نقول شيئا بعد.","1:9":"فإن أولئك المؤمنين أنفسهم يخبرون عنا كيف كان قدومنا إليكم أول مرة، وكيف تحولتم إلى الله عن الأصنام، لتصيروا عبيدا يخدمون الله الحي الحق،","1:10":"وتنتظروا من السماوات ابنه الذي أقامه من بين الأموات، يسوع مخلصنا من الغضب الآتي.","2:1":"فإنكم، أيها الإخوة، تعلمون أن قدومنا إليكم لم يكن باطلا.","2:2":"فمع أننا كنا قد قاسينا الألم والإهانة في مدينة فيلبي، كما تعلمون، فقد تجرأنا في إلهنا أن نكلمكم بإنجيل الله مجاهدين في وجه المعارضة الشديدة.","2:3":"فما كان وعظنا صادرا عن ضلال ولا عن نجاسة، ولا خالطه مكر،","2:4":"بل إننا نتكلم كمن تبين من اختبار الله لهم أنهم أهل لأن يؤتمنوا على الإنجيل، لنرضي لا الناس بل الله الذي يختبر قلوبنا.","2:5":"وكما تعلمون أيضا، فإننا لم نستعمل معكم قط كلام التملق، ولا اتخذنا ذريعة للطمع إنما الله شاهد","2:6":"ولا سعينا لنوال مجد من الناس، لا منكم ولا من غيركم،","2:7":"مع أن لنا الحق في أن نفرض أنفسنا عليكم باعتبارنا رسلا للمسيح. ولكننا كنا مترفقين بكم كأم مرضع تحنو على أولادها.","2:8":"وإذ كان حنونا عليكم شديدا، ارتضينا أن نقدم إليكم لا إنجيل الله فقط بل أنفسنا أيضا، لأنكم صرتم محبوبين لدينا.","2:9":"فأنتم تذكرون، أيها الإخوة، جهدنا وكدنا، إذ بشرناكم بإنجيل الله ونحن نشتغل ليلا ونهارا لكي لا نكون عبئا ثقيلا على أحد منكم.","2:10":"فأنتم تشهدون، ويشهد الله ، كيف تصرفنا بينكم، أنتم المؤمنين، بطهارة واستقامة وبراءة من اللوم،","2:11":"كما أنكم تعلمون كيف عاملناكم معاملة الأب لأولاده، فكنا نعظ كل واحد منكم ونشجعكم","2:12":"ونحرضكم أن تسلكوا سلوكا يليق بالله، ذاك الذي يدعوكم إلى ملكوته ومجده.","2:13":"ولذلك نحن أيضا نرفع الشكر لله بلا توقف، لأنكم لما تلقيتم منا كلمة البشارة من الله، قبلتموها لا كأنها كلمة بشر، بل كما هي في الحقيقة: باعتبارها كلمة الله العاملة أيضا فيكم أنتم المؤمنين.","2:14":"فإنكم، أيها الإخوة، قد صرتم على مثال كنائس الله التي في منطقة اليهودية والتي هي في المسيح يسوع. فأنتم أيضا قاسيتم على أيدي بني جنسكم ما قاسوه هم على أيدي اليهود","2:15":"الذين قتلوا الرب يسوع والأنبياء واضطهدونا نحن أيضا، وهم لا يرضون الله ويعادون الناس جميعا،","2:16":"إذ يمنعوننا من تبشير الأمم ليخلصوا، وبذلك يستكملون خطاياهم كل حين، ولكن الغضب قد حل عليهم إلى الغاية.","2:17":"أما نحن، أيها الإخوة، فإذ قد سلخنا عنكم لمدة قصيرة، بالوجه لا بالقلب، بذلنا جهدا أوفر جدا لرؤية وجوهكم ونحن في غاية الشوق إليكم.","2:18":"ولهذا عزمنا أن نأتي إليكم على الأخص أنا بولس مرة بعد مرة، فعاقنا الشيطان.","2:19":"فما هو رجاؤنا أو فرحنا أو إكليل افتخارنا أمام ربنا يسوع عند عودته؟ أليس أنتم؟ بلى،","2:20":"لأنكم فخرنا وفرحنا.","3:1":"لذلك لما صار افتراقنا عنكم لا يحتمل، حسن لدينا أن نبقى وحدنا في مدينة أثينا،","3:2":"فبعثنا تيموثاوس، أخانا ومعاوننا في خدمة الله بنشر الإنجيل، لكي يشددكم ويشجعكم في إيمانكم،","3:3":"حتى لا يتزعزع أحد منكم من جراء هذه الضيقات. فإنكم تعلمون أننا معينون لذلك؛","3:4":"وقد سبق لنا، لما كنا عندكم أن أخبرناكم أننا سنقاسي الضيقات، الأمر الذي حدث بعد ذلك كما تعلمون.","3:5":"ولهذا أيضا، إذ صار الافتراق عنكم لا يحتمل، أرسلت أستخبر عن إيمانكم لئلا يكون المجرب قد جربكم فيذهب جهدنا سدى!","3:6":"أما الآن، وقد عاد تيموثاوس إلينا من عندكم وبشرنا بما لكم من إيمان ومحبة، وبأنكم تذكروننا ذكرا حسنا في كل حين، وتشتاقون كثيرا لرؤيتنا كما نشتاق نحن لرؤيتكم،","3:7":"فقد وجدنا بكم أيها الإخوة عزاء في وسط ضيقتنا وشدتنا من جهة إيمانكم.","3:8":"فقد طابت لنا الحياة مادمتم ثابتين في الرب!","3:9":"فأي شكر نستطيع أن نؤديه إلى الله عوضا عنكم من أجل كل ما نبتهج به من الفرح بسببكم أمام إلهنا،","3:10":"ونحن نتضرع ليل نهار متوسلين أن نرى وجوهكم ونكمل ما كان ناقصا في إيمانكم؟","3:11":"ليت الله أبانا نفسه، وربنا يسوع المسيح، يسهل أمامنا الطريق إليكم.","3:12":"وليجعلكم الرب تنمون وتفيضون في المحبة لتحبوا بعضكم بعضا وجميع الناس كمحبتنا لكم،","3:13":"حتى تتثبت قلوبكم بغير لوم في القداسة أمام إلهنا وأبينا عندما يظهر ربنا يسوع عائدا مع جميع قديسيه.","4:1":"وبعد، أيها الإخوة، فمثلما تلقيتم منا كيف يجب أن تسلكوا سلوكا يرضي الله ، وكما أنتم فاعلون، نرجو منكم ونحرضكم في الرب يسوع أن تضاعفوا تقدمكم في ذلك أكثر فأكثر.","4:2":"فإنكم تعرفون الوصايا التي لقناكم إياها من قبل الرب يسوع.","4:3":"فإن مشيئة الله هي هذه: قداستكم. وذلك بأن تمتنعوا عن الزنى،","4:4":"وأن يعرف كل واحد منكم كيف يحفظ جسده في الطهارة والكرامة","4:5":"غير منساق للشهوة الجامحة كالوثنيين الذين لا يعرفون الله ،","4:6":"وألا يتعدى حقوق أخيه ويسيء إليه في هذا الأمر، لأن الرب هو المنتقم لجميع هذه الإساءات، كما أنذرناكم قبلا وشهدنا لكم بحق.","4:7":"فإن الله دعانا لا إلى النجاسة بل (إلى العيش( في القداسة.","4:8":"إذن، من استخف بأخيه في هذا الأمر، يستخف لا بإنسان بل بالله، بذاك الذي وهبكم فعلا روحه القدوس.","4:9":"أما المحبة الأخوية، فلستم في حاجة لأن أكتب إليكم عنها، لأنكم بأنفسكم قد تعلمتم من الله أن تحبوا بعضكم بعضا،","4:10":"ولأنكم أيضا هكذا تعاملون جميع الإخوة في مقاطعة مقدونية كلها. وإنما نحرضكم، أيها الإخوة، أن تضاعفوا ذلك أكثر فأكثر،","4:11":"وأن تسعوا بجد إلى العيش بهدوء، مهتمين بممارسة شؤونكم الخاصة، ومحصلين معيشتكم بعمل أيديكم، كما أوصيناكم.","4:12":"عندئذ تكون سيرتكم حسنة السمعة تجاه الذين من خارج الكنيسة، ولا تكونون في حاجة إلى شيء.","4:13":"على أننا نريد، أيها الإخوة، ألا يخفى عليكم أمر الراقدين، حتى لا يصيبكم الحزن كغيركم من الناس الذين لا رجاء لهم.","4:14":"فمادمنا نؤمن أن يسوع مات ثم قام، فمعه كذلك سيحضر الله أيضا الراقدين بيسوع.","4:15":"فهذا نقوله لكم بكلمة من عند الرب: إننا نحن الباقين أحياء إلى حين عودة الرب، لن نسبق الراقدين.","4:16":"لأن الرب نفسه سينزل من السماء حالما يدوي أمر بالتجمع، وينادي رئيس ملائكة، ويبوق في بوق إلهي، عندئذ يقوم الأموات في المسيح أولا.","4:17":"ثم إننا، نحن الباقين أحياء، نختطف جميعا في السحب للاجتماع بالرب في الهواء. وهكذا نبقى مع الرب على الدوام.","4:18":"لذلك عزوا بعضكم بعضا بهذا الكلام!","5:1":"أما مسألة الأزمنة والأوقات المحددة، فلستم في حاجة لأن يكتب إليكم فيها.","5:2":"لأنكم تعلمون يقينا أن يوم الرب سيأتي كما يأتي اللص في الليل.","5:3":"فبينما الناس يقولون: حل السلام والأمن! ينزل بهم الهلاك المفاجيء كالمخاض الذي يدهم الحبلى، فلا يستطيعون أبدا أن يفلتوا.","5:4":"غير أنكم أنتم، أيها الإخوة، لستم في الظلام حتى يفاجئكم ذلك اليوم كأنه لص.","5:5":"فأنتم جميعا أبناء النور وأبناء النهار. إننا لسنا أهل الليل ولا أهل الظلام.","5:6":"إذن، لا ننم كما ينام الآخرون، بل لنظل ساهرين وصاحين،","5:7":"فإنه في الليل ينام الذين ينامون، وفي الليل يسكر الذين يسكرون","5:8":"وأما نحن، أهل النهار، فلنظل صاحين، متخذين من الإيمان والمحبة درعا لصدورنا، ومن الرجاء بالخلاص خوذة لرؤوسنا.","5:9":"فإن الله عيننا لا لينزل علينا الغضب بل لننال الخلاص بربنا يسوع المسيح،","5:10":"الذي مات عنا لكي نحيا جميعا معه، سواء كنا في سهر الحياة أم في رقاد الموت!","5:11":"لذلك عزوا بعضكم بعضا وشددوا أحدكم الآخر، كما أنتم فاعلون.","5:12":"على أننا نرجو منكم، أيها الإخوة، أن تميزوا أولئك الذين يجتهدون بينكم، ويرعونكم كما يريد الرب، ويعظونكم،","5:13":"وأن تقدروهم تقديرا فائقا في المحبة، من أجل عملهم. عيشوا بسلام بعضكم مع بعض.","5:14":"إلا أننا نناشدكم، أيها الإخوة، أن تعظوا الفوضويين، وتشددوا فاقدي العزم، وتساندوا الضعفاء، وتعاملوا الجميع بطول البال.","5:15":"حذار أن يبادل أحدكم شر غيره بشر مثله بل اسعوا دائما إلى الخير في معاملتكم بعضكم لبعض وللآخرين جميعا.","5:16":"افرحوا على الدوام؛","5:17":"صلوا دون انقطاع؛","5:18":"ارفعوا الشكر في كل حال: فهذه هي مشيئة الله لكم في المسيح يسوع.","5:19":"لا تخمدوا الروح،","5:20":"لا تحتقروا النبوءات؛","5:21":"امتحنوا كل شيء وتمسكوا بالحسن.","5:22":"ترفعوا عن كل ما فيه شبهة شر.","5:23":"وإله السلام نفسه يقدسكم إلى التمام ويحفظكم سالمين، روحا ونفسا وجسدا، لتكونوا بلا لوم عند عودة ربنا يسوع المسيح.","5:24":"فإن الله الذي يدعوكم صادق، وسوف يتم ذلك.","5:25":"أيها الإخوة، صلوا لأجلنا.","5:26":"سلموا على جميع الإخوة بقبلة طاهرة!","5:27":"أناشدكم بالرب أن تقرأ هذه الرسالة على جميع الإخوة.","5:28":"ولتكن معكم نعمة ربنا يسوع المسيح."},"2Th":{"1:1":"من بولس وسلوانس وتيموثاوس، إلى كنيسة مؤمني تسالونيكي الذين هم في الله أبينا والرب يسوع المسيح.","1:2":"لتكن لكم النعمة والسلام من الله الآب والرب يسوع المسيح.","1:3":"من واجبنا أن نشكر الله على الدوام لأجلكم أيها الإخوة. كما أن هذا حق: لأن إيمانكم ينمو نموا فائقا، ومحبة أحدكم للآخر تفيض بينكم جميعا.","1:4":"حتى إننا، نحن أنفسنا، نفتخر بكم في كنائس الله بسبب ثباتكم وإيمانكم في وسط كل ما تحتملونه من اضطهادات وضيقات.","1:5":"وفي هذا دليل على حكم الله العادل، بقصد أن تعتبروا مؤهلين لملكوت الله الذي من أجله تلاقون الآلام.","1:6":"فمن العدل عند الله حقا أن يجازي بالضيقة أولئك الذين يضايقونكم،","1:7":"وأن يكافئكم، أنتم الذين تتضايقون، كما يكافئنا نحن، بالراحة لدى ظهور الرب يسوع علنا من السماء، ومعه ملائكة قدرته،","1:8":"وسط نار ملتهبة، منتقما إلى التمام من غير العارفين لله وغير المطيعين لإنجيل ربنا يسوع.","1:9":"فهؤلاء سيكابدون عقاب الهلاك الأبدي، بعيدا من حضرة الرب ومن مجد قوته،","1:10":"عندما يعود في ذلك اليوم ليتمجد في قديسيه ويكون موضع العجب عند جميع الذين آمنوا، وأنتم قد آمنتم بشهادتنا لكم!","1:11":"لأجل ذلك أيضا نصلي من أجلكم على الدوام، لكي يجعلكم إلهنا مؤهلين للدعوة الإلهية ويتم فيكم، بقدرته، كل ما يسره من الصلاح وفعالية الإيمان،","1:12":"حتى يتمجد اسم ربنا يسوع فيكم وتتمجدوا أنتم فيه وفقا لنعمة إلهنا وربنا يسوع المسيح.","2:1":"ولكن بالنسبة إلى رجوع ربنا يسوع المسيح واجتماعنا إليه معا، نرجو منكم أيها الإخوة","2:2":"ألا تضطرب أفكاركم سريعا ولا تقلقوا، لا من إيحاء ولا من خبر ولا من رسالة منسوبة إلينا زورا، يزعم فيها أن يوم الرب قد حل فعلا.","2:3":"لا تدعوا أحدا يخدعكم بأية وسيلة! فإن ذلك اليوم لا يأتي دون أن يسبقه انتشار العصيان وظهور الإنسان المتمرد، ابن الهلاك،","2:4":"الذي يتحدى كل ما يدعى إلها أو معبودا، ويعاديه مترفعا عليه. بل إنه أيضا يتخذ من هيكل الله مقرا له، محاولا أن يبرهن أنه إله.","2:5":"ألا تذكرون أني كثيرا ما قلت لكم هذا عندما كنت عندكم؟","2:6":"وأنتم الآن تعرفون ما الذي يحتجزه حتى لا يظهر إلا في الوقت المعين له.","2:7":"فإن التمرد الآن يعمل خفية كأنه سر. ولكن فقط إلى أن يرفع من الوسط ذاك الذي يحتجز المتمرد.","2:8":"عندئذ سيظهر الإنسان المتمرد ظهورا جليا فيبيده الرب يسوع بنفخة فمه ويلاشيه ببهاء ظهوره عند عودته.","2:9":"أما بروز المتمرد، فسوف يكون بقدر طاقة الشيطان على المعجزات والعلامات والعجائب المزيفة كلها،","2:10":"وعلى جميع أنواع التضليل الذي يجرف الهالكين إلى العصيان، لأنهم لم يقبلوا محبة الحق حتى يخلصوا.","2:11":"ولهذا السبب، سيرسل الله إليهم طاقة الضلال حتى يصدقوا ما هو دجل،","2:12":"فتقع الدينونة على جميع الذين لم يؤمنوا بالحق بل سرهم الإثم.","2:13":"أما نحن، فمن واجبنا أن نشكر الله على الدوام من أجلكم، أيها الإخوة الذين يحبهم الرب، لأن الله اختاركم من البدء للخلاص، بتقديس الروح لكم وإيمانكم بالحق.","2:14":"فإلى هذا الأمر قد دعاكم ببشارتنا لكم، لنوال مجد ربنا يسوع المسيح.","2:15":"فاثبتوا إذن، أيها الإخوة، وتمسكوا بالتعاليم التي تلقيتم منا، سواء كان بالكلام أم برسالتنا.","2:16":"وليت ربنا يسوع المسيح نفسه، والله أبانا، الذي أحبنا ووهبنا بنعمته راحة أبدية ورجاء صالحا،","2:17":"يشجع قلوبكم ويرسخكم في كل عمل صالح وقول حسن!","3:1":"وبعد، أيها الإخوة، صلوا لأجلنا، لتنتشر كلمة الرب بسرعة وتتمجد كما هي الحال عندكم،","3:2":"ولينقذنا الله من الناس الأردياء الأشرار، لأن الإيمان ليس من نصيب الجميع.","3:3":"إلا أن الرب جدير بالثقة؛ فهو سيثبتكم ويحميكم من الشر.","3:4":"ولنا في الرب ملء الثقة من جهتكم بأنكم عاملون بما نوصيكم به، وستعملون به أيضا.","3:5":"وليهد الله قلوبكم إلى ما لدى الله من المحبة ولدى المسيح من الصبر!","3:6":"ثم نوصيكم، أيها الإخوة، باسم ربنا يسوع المسيح، أن تعتزلوا عن كل أخ يسلك سلوكا فوضويا، لا يوافق التعليم الذي تلقيتم منا.","3:7":"فأنتم أنفسكم تعرفون كيف ينبغي أن تقتدوا بنا، لأن سلوكنا بينكم لم يكن فوضويا،","3:8":"ولا أكلنا الخبز من عند أحد مجانا، بل كنا نشتغل بتعب وكد ليل نهار، لكي لا نكون عبئا ثقيلا على أي واحد منكم.","3:9":"وذلك لا يعني أنه ليس لنا حق، بل لنجعل أنفسنا مثالا لكم لتقتدوا بنا.","3:10":"فلما كنا عندكم، أوصيناكم بهذا المبدأ: إن كان أحد لا يريد أن يشتغل، فلا يأكل!","3:11":"وقد سمعنا أن بينكم بعض الذين يسلكون سلوكا فوضويا فلا يشتغلون شيئا بل يتلهون بشؤون غيرهم.","3:12":"فمثل هؤلاء نوصيهم ونناشدهم، في الرب يسوع المسيح، أن يكسبوا معيشتهم بأنفسهم، مشتغلين بهدوء.","3:13":"أما أنتم، أيها الإخوة، فلا تملوا من عمل الخير.","3:14":"وإن كان أحد لا يطيع كلمتنا في هذه الرسالة، فميزوه ولا تتعاملوا معه، لتدفعوه إلى الخجل.","3:15":"ولكن، لا تعتبروه عدوا لكم، بل أرشدوه باعتباره أخا.","3:16":"وليعطكم رب السلام نفسه السلام على الدوام وفي كل حال! وليكن الرب معكم جميعا!","3:17":"هذا سلامي، أنا بولس، بخط يدي وهو العلامة المميزة في كل رسالة لي. فهكذا أنا أكتب.","3:18":"لتكن نعمة ربنا يسوع المسيح معكم جميعا!"},"1Ti":{"1:1":"من بولس، رسول المسيح يسوع وفقا لأمر الله مخلصنا والمسيح يسوع رجائنا،","1:2":"إلى تيموثاوس ولدي الحقيقي في الإيمان. لتكن لك النعمة والرحمة والسلام من الله أبينا والمسيح يسوع ربنا!","1:3":"كما أوصيتك لما كنت منطلقا إلى مقاطعة مقدونية، (أطلب إليك) أن تبقى في مدينة أفسس، لكي تمنع بعض المعلمين من نشر التعاليم المخالفة للتعليم الصحيح،","1:4":"وتوصي المؤمنين ألا ينشغلوا بالأساطير وسلاسل النسب المتشابكة. فتلك الأمور تثير المجادلات ولا تعمل على تقدم تدبير الله القائم على الإيمان.","1:5":"أما الغاية مما أوصيتك به، فهي المحبة النابعة من قلب طاهر وضمير صالح وإيمان خال من الرياء.","1:6":"هذه الفضائل قد زاغ عنها بعضهم، فانحرفوا إلى المجادلات الباطلة،","1:7":"راغبين في أن يكونوا أساتذة في الشريعة، وهم لا يفهمون ما يقولون ولا ما يقررون!","1:8":"إننا نعلم أن الشريعة جيدة في ذاتها، إذا استعملت استعمالا شرعيا.","1:9":"إذ ندرك أن الشريعة لا تطبق على من كان بارا، بل على الأشرار والمتمردين، على الفاجرين والخاطئين، والنجسين والدنسين، وقاتلي آبائهم وأمهاتهم، وقاتلي الناس،","1:10":"والزناة ومضاجعي الذكور، وخطافي الناس والكذابين وشاهدي الزور. وذوي كل شر آخر يخالف التعليم الصحيح","1:11":"الموافق لإنجيل مجد الله المبارك، ذلك الإنجيل الذي وضع أمانة بين يدي.","1:12":"وكم أشكر المسيح يسوع ربنا الذي أعطاني القدرة وعينني خادما له، إذ اعتبرني جديرا بثقته،","1:13":"مع أني كنت في الماضي مجدفا عليه، ومضطهدا ومهينا له! ولكني عوملت بالرحمة، لأني عملت ما عملته عن جهل وفي عدم إيمان.","1:14":"إلا أن نعمة ربنا قد فاضت علي فوق كل حد، ومعها الإيمان والمحبة، وذلك في المسيح يسوع.","1:15":"ما أصدق هذا القول، وما أجدره بالتصديق الكلي: إن المسيح يسوع قد جاء إلى العالم ليخلص الخاطئين، وأنا أولهم!","1:16":"ولكن لهذا السبب عوملت بالرحمة، ليجعل يسوع المسيح مني، أنا أولا، مثالا يظهر صبره الطويل، لجميع الذين سيؤمنون به لنوال الحياة الأبدية.","1:17":"فللملك الأزلي، الله الواحد غير المنظور وغير الفاني، الكرامة والمجد إلى أبد الآبدين. آمين!","1:18":"هذه التوصيات، ياتيموثاوس ولدي، أسلمها لك، بمقتضى النبوآت السابقة المختصة بك، وغايتي أن تحسن الجهاد في حربك الروحية،","1:19":"متمسكا بالإيمان، وبالضمير الصالح، هذا الضمير الذي تخلى عنه بعضهم، فانكسرت بهم سفينة الإيمان.","1:20":"ومن هؤلاء همنايوس وإسكندر، وقد سلمتهما إلى الشيطان ليتعلما بالتأديب ألا يجدفا.","2:1":"فأطلب، قبل كل شيء، أن تقيموا الطلبات الحارة والصلوات والتضرعات والتشكرات لأجل جميع الناس،","2:2":"ولأجل الملوك وأصحاب السلطة، لكي نعيش حياة مطمئنة هادئة كلية التقوى والرصانة.","2:3":"فإن هذا الأمر جيد ومقبول في نظر الله مخلصنا،","2:4":"فهو يريد لجميع الناس أن يخلصوا، ويقبلوا إلى معرفة الحق بالتمام:","2:5":"فإن الله واحد، والوسيط بين الله والناس واحد، وهو الإنسان المسيح يسوع،","2:6":"الذي بذل نفسه فدية عوضا عن الجميع. هذه شهادة تؤدى في أوقاتها الخاصة،","2:7":"ولها قد عينت أنا مبشرا ورسولا، الحق أقول ولست أكذب، معلما للأمم في الإيمان والحق.","2:8":"فأريد إذن، أن يصلي الرجال في كل مكان، رافعين أيادي طاهرة، وهم لا يضمرون أي حقد أو شكوك.","2:9":"كما أريد أيضا، أن تظهر النساء بمظهر لائق محشوم اللباس، متزينات بالحياء والرزانة، غير متحليات بالجدائل والذهب واللاليء والحلل الغالية الثمن،","2:10":"بل بما يليق بنساء يعترفن علنا بأنهن يعشن في تقوى الله، بالأعمال الصالحة!","2:11":"على المرأة أن تتلقى التعليم بسكوت وبكل خضوع.","2:12":"ولست أسمح للمرأة أن تعلم ولا تتسلط على الرجل. بل عليها أن تلزم السكوت.","2:13":"ذلك لأن آدم كون أولا، ثم حواء:","2:14":"ولم يكن آدم هو الذي انخدع (بمكر الشيطان)، بل المرأة انخدعت، فوقعت في المعصية.","2:15":"إلا أنها ستحفظ سالمة في ولادة الأولاد، على أن يثبتن في الإيمان والمحبة والقداسة مع الرزانة!","3:1":"ما أصدق القول إن من يرغب في الرعاية فإنما يتوق إلى عمل صالح.","3:2":"إذن، يجب أن يكون الراعي بلا عيب، زوجا لامرأة واحدة، نبيها عاقلا مهذبا مضيافا، قادرا على التعليم؛","3:3":"لا مدمنا للخمر ولا عنيفا؛ بل لطيفا، غير متعود الخصام، غير مولع بالمال،","3:4":"يحسن تدبير بيته، ويربي أولاده في الخضوع بكل احترام.","3:5":"فإن كان أحد لا يحسن تدبير بيته، فكيف يعتني بكنيسة الله؟","3:6":"ويجب أيضا أن لا يكون مبتدئا في الإيمان، لئلا ينتفخ تكبرا، فيقع في جريمة إبليس!","3:7":"ومن الضروري أن تكون له شهادة حسنة من الذين في خارج الكنيسة، لكي لا يقع في العار وفي فخ إبليس.","3:8":"أما المدبرون، فيجب أن يكونوا أيضا ذوي رصانة، لا ذوي لسانين، ولا مدمنين للخمر، لا ساعين إلى المكسب الخسيس.","3:9":"يتمسكون بحقائق الإيمان الخفية بضمير نقي.","3:10":"وأيضا يجب أن يتم اختبار المدبرين أولا، فإذا تبين أنهم بلا شكوى، فليباشروا خدمة التدبير.","3:11":"كذلك يجب أن تكون النساء أيضا رزينات، غير نمامات، نبيهات، أمينات في كل شيء.","3:12":"كما يجب أن يكون كل مدبر زوجا لامرأة واحدة، يحسن تدبير أولاده وبيته.","3:13":"فإن الذين يقومون بخدمة التدبير خير قيام، يكسبون لأنفسهم مكانة جيدة، وجرأة كبيرة في الإيمان الثابت في المسيح يسوع!","3:14":"هذه التوصيات أكتبها إليك، وأنا أرجو أن آتي إليك بأكثر سرعة،","3:15":"حتى إذا تأخرت تعلم كيف يجب التصرف في بيت الله، أي كنيسة الله الحي، ركن الحق ودعامته.","3:16":"وباعتراف الجميع، أن سر التقوى عظيم: الله ظهر في الجسد، شهد الروح لبره، شاهدته الملائكة، بشر به بين الأمم، أومن به في العالم، ثم رفع في المجد.","4:1":"إلا أن الروح يعلن صراحة أن قوما في الأزمنة الأخيرة سوف يرتدون عن الإيمان، منساقين وراء أرواح مضللة وتعاليم شيطانية،","4:2":"في موجة رياء ينشرها معلمون دجالون لهم ضمائر كويت بالنار.","4:3":"يحرمون الزواج، ويأمرون بالامتناع عن أطعمة خلقها الله ليتناولها المؤمنون وعارفو الحق شاكرين.","4:4":"فإن كل ما خلقه الله جيد، ولا شيء منه يرفض إذا تناوله الإنسان شاكرا؛","4:5":"لأنه يصير مقدسا بكلمة الله والصلاة.","4:6":"إن بسطت هذه الأمور أمام الإخوة، كنت خادما صالحا للمسيح يسوع، متغذيا بكلام الإيمان والتعليم الصالح الذي اتبعته تماما.","4:7":"أما أساطير العجائز المبتذلة، فتجنبها. إنما مرن نفسك في طريق التقوى.","4:8":"فالرياضة البدنية نافعة بعض الشيء. أما التقوى فنافعة لكل شيء، لأن فيها وعدا بالحياة الحاضرة والآتية.","4:9":"ما أصدق هذا القول، وما أجدره بالتصديق!","4:10":"فإننا لأجل هذا نعمل باجتهاد ونقاسي التعيير، لأننا وضعنا رجاءنا في الله الحي، حافظ جميع الناس، وبالأخص المؤمنين.","4:11":"أوص بهذه الأمور وعلم!","4:12":"لا يستخف أحد بحداثة سنك. وإنما كن قدوة للمؤمنين، في الكلام والسلوك والمحبة والإيمان والطهارة.","4:13":"إلى حين وصولي، انصرف إلى تلاوة الكتاب، وإلى الوعظ، وإلى التعليم.","4:14":"لا تهمل الموهبة الخاصة التي فيك والتي أعطيت لك بالتنبوء ووضع الشيوخ أيديهم عليك.","4:15":"انصرف إلى هذه الأمور، وانشغل بها كليا، ليكون تقدمك واضحا للجميع.","4:16":"انتبه جيدا لنفسك وللتعليم. فإنك إذ تواظب على ذلك، تنقذ نفسك وسامعيك أيضا.","5:1":"لا توبخ شيخا توبيخا قاسيا، بل عظه كأنه أب لك. وعامل الشبان كأنهم إخوة لك؛","5:2":"والعجائز كأنهن أمهات؛ والشابات كأنهن أخوات، بكل طهارة.","5:3":"أكرم الأرامل اللواتي لا معيل لهن.","5:4":"فإن كان للأرملة أولاد أو حفدة، فمن أول واجبات هؤلاء أن يتعلموا توقير أهلهم وأن يفوا حق والديهم. فإن هذا العمل مقبول في نظر الله.","5:5":"ولكن الأرملة التي تعيش وحيدة ولا معيل لها، فقد وضعت رجاءها في الله وهي تداوم على الأدعية والصلوات ليلا ونهارا.","5:6":"أما تلك التي تعيش منغمسة في اللذات، فقد ماتت، وإن كانت حية.","5:7":"وعليك أن توصي بهذه الأمور، لكي يكون الجميع بلا لوم.","5:8":"فإذا كان أحد لا يهتم بذويه، وبخاصة بأهل بيته، فقد أنكر الإيمان، وهو أسوأ من غير المؤمن.","5:9":"لتقيد في سجل الأرامل من بلغت سن الستين على الأقل، على أن تكون قد تزوجت من رجل واحد،","5:10":"ويكون مشهودا لها بالأعمال الصالحة، كأن تكون قد ربت الأولاد، وأضافت الغرباء، وغسلت أقدام القديسين، وأسعفت المتضايقين، ومارست كل عمل صالح!","5:11":"أما الأرامل الشابات، فلا تقيدهن. إذ عندما يبطرن على المسيح، يرغبن في الزواج،","5:12":"فيصرن أهلا للقصاص، لأنهن قد نكثن عهدهن الأول.","5:13":"وفي الوقت نفسه يتعودن البطالة والتنقل من بيت إلى بيت. ولا تكفيهن البطالة، بل ينصرفن أيضا إلى الثرثرة والتشاغل بما لا يعنيهن والتحدث بأمور غير لائقة.","5:14":"فأريد إذن أن تتزوج الأرامل الشابات، فيلدن الأولاد، ويدبرن بيوتهن، ولا يفسحن للمقاوم في المجال للطعن في سلوكهن.","5:15":"ذلك لأن بعضا منهن قد انحرفن وراء الشيطان فعلا.","5:16":"وإن كان لأحد المؤمنين أو المؤمنات أرامل من ذويه، فعليه أن يعينهن حتى لا تتحمل الكنيسة الأعباء، فتتفرغ لإعانة الأرامل المحتاجات حقا.","5:17":"أما الشيوخ الذين يحسنون القيادة، فليعتبروا أهلا للإكرام المضاعف، وبخاصة الذين يبذلون الجهد في نشر الكلمة وفي التعليم.","5:18":"لأن الكتاب يقول: «لا تضع كمامة على فم الثور وهو يدرس الحبوب»، وأيضا: ¢العامل يستحق أجرته¢.","5:19":"ولا تقبل تهمة موجهة إلى أحد الشيوخ، إلا إذا أيدها شاهدان أو ثلاثة.","5:20":"فإذا ثبت أن المتهم مخطيء، وبخه أمام الجميع، ليكون عند الباقين خوف!","5:21":"أطلب منك أمام الله والمسيح والملائكة المختارين أن تعمل بهذه التوصيات دون مراعاة أشخاص، فلا تعمل شيئا بتحيز.","5:22":"لا تتسرع في وضع يدك على أحد. ولا تشترك في خطايا الآخرين. واحفظ نفسك طاهرا.","5:23":"لا تشرب الماء فقط بعد الآن. وإنما خذ قليلا من الخمر مداويا معدتك وأمراضك التي تعاودك كثيرا.","5:24":"من الناس من تكون خطاياهم واضحة قبل المحاكمة؛ ومن الناس من لا تظهر خطاياهم إلا بعد المحاكمة.","5:25":"وقياسا على ذلك، فإن الأعمال الصالحة تكون واضحة مسبقا؛ والأعمال التي ليست بصالحة، لا يمكن أن تظل مخفية.","6:1":"على جميع من هم تحت نير العبودية أن يعتبروا سادتهم أهلا لكل إكرام، لكي لا يجلبوا التجديف على اسم الله وعلى التعليم.","6:2":"وعلى الذين لهم سادة مؤمنون أن لا يستخفوا بهم لأنهم إخوة لهم، بل بالأحرى أن يخدموهم بخضوع، لأن المستفيدين من خدمتهم الصالحة هم مؤمنون محبوبون.","6:3":"أما إذا كان أحد يعلم ما يخالفها ولا يذعن للكلام الصحيح، كلام ربنا يسوع المسيح، وللتعليم الموافق للتقوى،","6:4":"فهو قد انتفخ تكبرا، ولا يعرف شيئا، وإنما هو مهووس بالمجادلات والمنازعات الكلامية، ومنها ينشأ الحسد والخصام والتجريح والنيات السيئة،","6:5":"وشتى أنواع النزاع بين أناس فاسدي العقول مجردين من الحق، يعتبرون التقوى تجارة.","6:6":"أما التقوى مع القناعة فهي تجارة عظيمة.","6:7":"فنحن لم ندخل العالم حاملين شيئا، ولا نستطيع أن نخرج منه حاملين شيئا.","6:8":"إنما، مادام لنا قوت ولباس، فلنكن قانعين بهما.","6:9":"أما الذين يرغبون في أن يصيروا أغنياء، فيسقطون في التجربة والفخ ويتورطون في كثير من الشهوات السفيهة المضرة التي تغرق الناس في الدمار والهلاك.","6:10":"فإن حب المال أصل لكل شر؛ وإذ سعى بعضهم إليه، ضلوا عن الإيمان، وطعنوا أنفسهم بأوجاع كثيرة.","6:11":"وأما أنت، ياإنسان الله، فاهرب من هذه الأمور، واسع في إثر البر والتقوى والإيمان والمحبة والصبر والوداعة.","6:12":"أحسن الجهاد في معركة الإيمان الجميلة. تمسك بالحياة الأبدية، التي إليها قد دعيت، وقد اعترفت الاعتراف الحسن (بالإيمان) أمام شهود كثيرين.","6:13":"وأوصيك، أمام الله الذي يحيي كل شيء، والمسيح يسوع الذي شهد أمام بيلاطس البنطي بالاعتراف الحسن،","6:14":"أن تحفظ الوصية خالية من العيب واللوم إلى يوم ظهور ربنا يسوع المسيح علنا.","6:15":"هذا الظهور سوف يتممه الله في وقته الخاص، هو السيد المبارك الأوحد، ملك الملوك ورب الأرباب،","6:16":"الذي وحده لا فناء له، الساكن في نور لا يدنى منه، الذي لم يره أي إنسان ولا يقدر أن يراه. له الكرامة والقدرة الأبدية. آمين!","6:17":"أوص أغنياء هذا الزمان بأن لا يتكبروا، ولا يتكلوا على الغنى غير الثابت، بل على الله الذي يمنحنا كل شيء بوفرة لنتمتع به،","6:18":"وأن يفعلوا خيرا، ويكونوا أغنياء بالأعمال الصالحة، ويوزعوا بسخاء، ويكونوا على استعداد دائم لإشراك الآخرين في خيراتهم.","6:19":"وبذلك يوفرون لأنفسهم رأس مال للمستقبل، حتى يمسكوا بالحياة الحقيقية.","6:20":"ياتيموثاوس، حافظ على الأمانة المودعة لديك. تجنب الكلام الدنس الباطل، ومناقضات ما يسمى زورا «معرفة».","6:21":"وإذ ادعى بعضهم هذه المعرفة المزعومة، زاغوا عن الإيمان. لتكن النعمة معك!"},"2Ti":{"1:1":"من بولس، وهو بمشيئة الله رسول للمسيح يسوع في سبيل الوعد بالحياة التي هي في المسيح،","1:2":"إلى تيموثاوس، ولدي الحبيب لتكن لك النعمة والرحمة والسلام من الله الآب والمسيح يسوع ربنا.","1:3":"كم أشكر الله ، الذي أعبده بضمير طاهر كما أخذت عن أجدادي، إذ مازلت أذكرك دائما في تضرعاتي ليلا ونهارا؛","1:4":"وإذ أتذكر دموعك (ساعة افتراقنا) أجدني في غاية الشوق لأن أراك لأمتليء فرحا.","1:5":"كما أستذكر إيمانك الخالي من الرياء، هذا الإيمان الذي فيك والذي حل أولا في جدتك لوئيس ثم في أمك أفنيكي، وأنا متأكد أنه حال فيك أيضا.","1:6":"لهذا السبب أنبهك أن تلهب نار موهبة الله التي فيك بوضع يدي عليك.","1:7":"فإن الله قد أعطانا لا روح الجبن بل روح القوة والمحبة والبصيرة.","1:8":"فلا تخجل إذن بالشهادة لربنا، ولا تخجل بي أنا السجين لأجله، بل شاركني في المشقات لأجل الإنجيل، متوكلا على قدرة الله.","1:9":"فهو قد خلصنا، ودعانا إليه دعوة مقدسة، لا على أساس أعمالنا، بل بموجب قصده ونعمته التي وهبت لنا في المسيح يسوع قبل أزمنة الأزل،","1:10":"والتي أعلنت الآن بظهور مخلصنا يسوع المسيح الذي سحق الموت وأنار الحياة والخلود بالإنجيل","1:11":"الذي له عينت أنا مبشرا ورسولا ومعلما.","1:12":"من أجل ذلك أيضا أقاسي الآن هذه الآلام، ولكني لست أخجل، لأنني أعرف من أنا مؤمن به، ولي تمام الثقة بأنه قادر أن يحفظ لي الأمانة التي أودعتها عنده سالمة إلى ذلك اليوم.","1:13":"اتخذ من الكلام الصحيح الذي سمعته مني مثالا في الإيمان والمحبة اللذين في المسيح يسوع.","1:14":"وحافظ على الأمانة الكريمة المودعة لديك، بالروح القدس الحال فينا.","1:15":"أنت على علم بأن معاوني الذين في مقاطعة أسيا، ومنهم فيجلس وهرموجينس، قد تخلوا عني.","1:16":"ليرحم الرب عائلة أونيسيفورس، لأنه كثيرا ما أنعشني، ولم يخجل بقيودي،","1:17":"بل إذ كان في مدينة روما، بذل جهدا في البحث عني حتى وجدني.","1:18":"لينعم عليه الرب بأن يلقى الرحمة من الرب في ذلك اليوم! أما كل ما خدمني به في مدينة أفسس، فأنت تعرفه جيدا.","2:1":"وأنت ياولدي، فكن قويا في النعمة التي في المسيح يسوع.","2:2":"والتعاليم التي سمعتها مني بحضور شهود عديدين، أودعها أمانة بين أيدي أناس جديرين بالثقة، يكونون قادرين على تعليم الآخرين.","2:3":"شارك في احتمال الآلام كجندي صالح للمسيح يسوع.","2:4":"وما من مجند يربك نفسه بشؤون الحياة إذا رغب في إرضاء من جنده.","2:5":"كما أن المصارع لا يفوز بالإكليل إلا إذا صارع بحسب القوانين.","2:6":"كذلك الفلاح الذي يشتغل بجد يجب أن يكون أول من ينال حصته من الغلة.","2:7":"فكر في ما أقوله، فإن الرب سيهبك فهما في كل شيء.","2:8":"اذكر يسوع المسيح الذي أقيم من الموت، وهو من نسل داود، كما أعلنه في إنجيلي","2:9":"الذي لأجل التبشير به أقاسي حتى القيود كأني فاعل شر. إلا أن كلمة الله لا تكبلها القيود.","2:10":"لهذا السبب أحتمل كل شيء بصبر لأجل الذين اختارهم الله ، لكي يحصلوا، هم أيضا، على الخلاص الذي في المسيح يسوع مع المجد الأبدي.","2:11":"وما أصدق القول: «إن كنا قد متنا معه، فسوف نحيا أيضا معه؛","2:12":"إن تحملنا الآلام، فسوف نملك أيضا معه؛ إن أنكرناه، فسوف ينكرنا أيضا؛","2:13":"إن تخلينا عن أمانتنا، فهو يبقى على أمانته، إذ لا يمكن أن يتنكر لذاته!»","2:14":"بهذه الأمور ذكر، شاهدا في حضرة الله أن لا تنشأ المجادلات الكلامية، وهي لا تنفع شيئا، غير تخريب سامعيها.","2:15":"اجتهد أن تقدم نفسك لله فائزا في الامتحان، عاملا ليس عليه ما يدعو للخجل، مفصلا كلمة الحق باستقامة.","2:16":"أما الأحاديث الباطلة الدنسة، فتجنبها؛ فإن المنصرفين إليها يتقدمون إلى فجور أفظع،","2:17":"وكلامهم ينهش كالآكلة، ومنهم هيمنايوس وفيليتوس،","2:18":"اللذان زاغا عن الحق؛ إذ يزعمان أن القيامة قد حدثت، ويهدمان إيمان بعض الناس.","2:19":"إلا أن الأساس الراسخ الذي وضعه الله يظل ثابتا، وعليه هذا الختم: «الرب يعرف خاصته»، وأيضا: «لينفصل عن الإثم كل من يسمي اسم الرب!»","2:20":"وإنما، في بيت كبير، لا تكون الأواني كلها من الذهب والفضة وحسب، بل يكون بعضها من الخشب والفخار أيضا. كما يكون بعضها للاستعمال الرفيع، وبعضها للاستعمال الوضيع.","2:21":"إذن الذي ينفصل عن هذه الأخيرة، مطهرا نفسه، يكون إناء للاستعمال الرفيع، مقدسا، نافعا لرب البيت، متأهبا لكل عمل صالح.","2:22":"إنما اهرب من الشهوات الشبابية، واسع وراء البر والإيمان والمحبة والسلام، مشاركا الذين يدعون الرب من قلب نقي.","2:23":"أما المجادلات الغبية الحمقاء، فتجنبها، عالما أنها تولد المشاجرات.","2:24":"وعبد الرب يجب ألا يتشاجر، بل أن يكون مترفقا تجاه الجميع، قادرا على التعليم، يتحمل المشقات بصبر،","2:25":"ويؤدب بالوداعة مقاومي الإيمان، عسى أن يمنحهم الله التوبة، فيعرفوا الحق بالتمام،","2:26":"فيعودوا إلى الصواب ناجين من فخ إبليس الذي أطبق عليهم، ليعملوا إرادته.","3:1":"واعلم هذا الأمر: أن أزمنة صعبة ستعم في الأيام الأخيرة؛","3:2":"إذ يكون الناس محبين لأنفسهم، محبين للمال، متكبرين، مباهين بأنفسهم، شتامين، غير مطيعين لوالديهم، ناكرين للجميل، دنسين،","3:3":"متحجري العواطف، غير صفوحين، نمامين، جامحي الأهواء، شرسين غير محبين للصلاح،","3:4":"خائنين، وقحين، مدعين، محبين للذات أكثر من محبتهم لله،","3:5":"لهم من التقوى مظهرها ولكنهم لقوتها منكرون، فعن هؤلاء الناس ابتعد!","3:6":"فمن هؤلاء من يدخلون البيوت خلسة، ويوقعون في حبائلهم بعض النساء السخيفات المثقلات بالخطايا، اللواتي تجرفهن شهوات مختلفة،","3:7":"يصغين للتعليم دائما، ولا يستطعن أبدا أن يبلغن معرفة الحق بالتمام!","3:8":"ومثلما قاوم (الساحران) ينيس ويمبريس موسى، كذلك أيضا يقاوم هؤلاء الحق؛ أناس عقولهم فاسدة، وقد تبين أنهم غير أهل للإيمان.","3:9":"ولكنهم لن يزدادوا تقدما، لأن حماقتهم ستنكشف للجميع، مثلما انكشفت حماقة الرجلين المذكورين.","3:10":"وأما أنت، فقد عرفت جيدا تعليمي، وسيرتي، وهدفي، وإيماني، وتحملي للمشقات، ومحبتي، وثباتي،","3:11":"واضطهاداتي، وآلامي تلك التي حدثت لي في مدن أنطاكية وإيقونية ولسترة وغيرها؛ وكم احتملت من اضطهادات، والرب أنقذني منها جميعا!","3:12":"وحقا، إن جميع الذين يعزمون أن يعيشوا عيشة التقوى في المسيح يسوع يضطهدون.","3:13":"أما الناس الأشرار والدجالون المحتالون، فيتقدمون في الشر، مضللين الآخرين وهم أنفسهم مضللون!","3:14":"إنما أنت فاثبت على ما تعلمته وتيقنته بالتمام، إذ تعرف على يد من تعلمت ذلك.","3:15":"وتعلم أنك منذ حداثة سنك تعرف الكتب المقدسة، وهي القادرة أن تجعلك حكيما لبلوغ الخلاص عن طريق الإيمان في المسيح يسوع.","3:16":"إن الكتاب بكل ما فيه، قد أوحى به الله؛ وهو مفيد للتعليم والتوبيخ والتقويم وتهذيب الإنسان في البر،","3:17":"لكي يجعل إنسان الله مؤهلا تأهيلا كاملا، ومجهزا لكل عمل صالح.","4:1":"أطلب منك في حضرة الله والمسيح الذي سيدين الأحياء والأموات، بعودته العلنية وملكوته،","4:2":"أن تنادي بالكلمة منشغلا بها كليا، في الفرص المناسبة وغير المناسبة على السواء، وأن توبخ وتنذر وتشجع بكل صبر في التعليم.","4:3":"فإنه سيأتي زمان لا يطيق الناس فيه التعليم الصحيح، بل تبعا لشهواتهم الخاصة يكدسون لأنفسهم معلمين (يقولون لهم كلاما) يداعب الآذان.","4:4":"فيحولون آذانهم بعيدا عن الحق، منحرفين إلى الخرافات.","4:5":"أما أنت، فكن بصيرا في كل أمر، وتحمل المشقات، واعمل عمل المبشر، وأكمل خدمتك إلى التمام!","4:6":"وأما أنا، فها إن حياتي بدأت تسكب سكيبا، وموعد رحيلي قد اقترب.","4:7":"قد جاهدت الجهاد الحسن، قد بلغت نهاية الشوط، قد حافظت على الإيمان.","4:8":"إنما ينتظرني الآن إكليل البر المحفوظ لي، والذي سيهبه لي الرب الديان العادل في ذلك اليوم؛ ولن يوهب لي وحدي، بل أيضا لجميع الذين يحبون ظهوره.","4:9":"اجتهد أن تأتي إلي سريعا،","4:10":"لأن ديماس، إذ أحب الحياة الحاضرة، تركني وذهب إلى مدينة تسالونيكي. أما كريسكيس، فقد ذهب إلى مقاطعة غلاطية، وتيطس إلى دلماطية","4:11":"ولم يبق معي إلا لوقا وحده. مر بمرقس وأحضره معك، فهو ينفعني في الخدمة.","4:12":"أما تيخيكس، فقد أرسلته إلى مدينة أفسس.","4:13":"وعندما تجيء، أحضر معك ردائي الذي تركته عند كاربس في ترواس، وكذلك كتبي، وبخاصة الرقوق المخطوطة.","4:14":"إن إسكندر النحاس قد أساء إلي إساءات كثيرة، سيجازيه الرب حسب أعماله.","4:15":"فاحترس منه أنت أيضا، لأنه قاوم كلامنا مقاومة شديدة.","4:16":"عندما دافعت عن نفسي في محاكمتي أول مرة، لم يقف أحد بجانبي، بل تركني الجميع، لا حاسبهم الله على ذلك!","4:17":"إلا أن الرب وقف بجانبي وأمدني بالقوة، لكي تتم بي المناداة بالبشارة، فيسمعها جميع من هم من الأمم؛ وقد نجوت من فم الأسد.","4:18":"وسينجيني الرب من كل عمل شرير ويحفظني سالما لملكوته السماوي. فله المجد إلى أبد الآبدين آمين!","4:19":"سلم على برسكا وأكيلا، وعائلة أونيسيفورس.","4:20":"أراستس مازال في مدينة كورنثوس. أما تروفيموس، فقد تركته في ميليتس مريضا.","4:21":"اجتهد أن تجيء إلي قبل حلول الشتاء.","4:22":"ليكن الرب مع روحك، ولتكن النعمة معكم!"},"Tit":{"1:1":"من بولس، عبد الله ورسول يسوع المسيح في سبيل إيمان من اختارهم الله ، ومعرفتهم للحق الموافق للتقوى،","1:2":"في رجاء الحياة الأبدية، التي وعد بها الله المنزه عن الكذب، من قبل أزمنة الأزل،","1:3":"ثم بين كلمته في أوانها المعين: بالبشارة التي وضعت أمانة بين يدي بموجب أمر مخلصنا الله …","1:4":"إلى تيطس، ولدي الحقيقي بالنسبة إلى الإيمان المشترك بيننا.","1:5":"تركتك في جزيرة كريت لكي تكمل ترتيب الأمور الباقية، وتقيم شيوخا في كل مدينة، مثلما أمرتك؛","1:6":"على أن يكون الواحد منهم بريئا من كل تهمة، زوجا لامرأة واحدة، أبا لأولاد مؤمنين لا يتهمون بالخلاعة والتمرد.","1:7":"وذلك لأن الناظر يجب أن يكون بريئا من كل تهمة باعتباره وكيلا لله، لا معجبا بنفسه ولا حاد الطبع، ولا مدمن الخمر، ولا عنيفا، ولا ساعيا إلى المكسب الخسيس؛","1:8":"بل مضيافا، محبا للصلاح، رزينا، بارا، تقيا، مالكا لطبعه،","1:9":"ملتصقا بالكلمة الصادقة الموافقة للتعليم، ليكون قادرا على تشجيع المؤمنين بالتعليم الصحيح وعلى إفحام المعارضين.","1:10":"فإن هنالك كثيرين من معلمي الباطل المتمردين وخادعي عقول الناس، وبخاصة الذين من أهل الختان.","1:11":"هؤلاء يجب أن تسد أفواههم: فهم يخربون بيوتا بجملتها، إذ يعلمون تعاليم يجب ألا تعلم، في سبيل مكسب خسيس.","1:12":"وقد قال واحد منهم، وهو عندهم نبي خاص بهم: «أهل كريت دائما كذابون، وحوش شرسة، نهمون كسالى».","1:13":"وهذه شهادة صدق. لذلك كن متشددا في توبيخهم، ليكونوا أصحاء في الإيمان،","1:14":"لا يديرون عقولهم إلى خرافات يهودية ووصايا أناس تحولوا عن الحق بعيدا.","1:15":"عند الطاهرين، كل شيء طاهر. أما عند النجسين وغير المؤمنين، فما من شيء طاهر، بل إن عقولهم وضمائرهم أيضا قد صارت نجسة.","1:16":"يشهدون معترفين بأنهم يعرفون الله ، ولكنهم بأعمالهم ينكرونه، لأنهم مكروهون وغير طائعين، وقد تبين أنهم غير أهل لكل عمل صالح.","2:1":"أما أنت، فعلم بما يوافق التعليم الصحيح:","2:2":"أن يكون الشيوخ ذوي رزانة ووقار، متعقلين، صحيحي الإيمان والمحبة والصبر.","2:3":"وكذلك أن تكون العجائز ذوات سيرة موافقة للقداسة، غير نمامات ولا مدمنات للخمر، بل معلمات لما هو صالح،","2:4":"لكي يدربن الشابات على أن يكن محبات لأزواجهن ولأولادهن،","2:5":"متعقلات، عفيفات، مهتمات بشؤون بيوتهن صالحات، خاضعات لأزواجهن، حتى لا يتكلم أحد بالسوء على كلمة الله.","2:6":"كذلك عظ الشبان أن يكونوا متعقلين،","2:7":"جاعلا من نفسك في كل شيء قدوة للأعمال الصالحة، مظهرا في تعليمك النقاوة والوقار","2:8":"والكلمة الصحيحة التي لا تلام، لكي يخجل المقاوم حين لا يجد أمرا سيئا يقوله فينا.","2:9":"وعلم العبيد أن يكونوا خاضعين لسادتهم، مرضين لهم في كل شيء؛ غير معاندين؛","2:10":"ولا سارقين، بل مظهرين أمانة كلية صالحة، لكي يزينوا في كل شيء تعليم مخلصنا الله.","2:11":"فإن نعمة الله التي تحمل معها الخلاص لجميع الناس، قد ظهرت.","2:12":"وهي تعلمنا أن نقطع علاقتنا بالإباحية والشهوات العالمية، وأن نحيا في العصر الحاضر حياة التعقل والبر والتقوى،","2:13":"فيما ننتظر تحقيق رجائنا السعيد، ثم الظهور العلني لمجد إلهنا ومخلصنا العظيم يسوع المسيح،","2:14":"الذي بذل نفسه لأجلنا لكي يفتدينا من كل إثم ويطهرنا لنفسه شعبا خاصا يجتهد بحماسة في الأعمال الصالحة.","2:15":"بهذه الأمور تكلم، وعظ، ووبخ بكل سلطان، ولا تدع أحدا يستخف بك!","3:1":"ذكر المؤمنين أن يخضعوا للحكام والسلطات، ويطيعوا القانون، ويكونوا مستعدين لكل عمل صالح،","3:2":"ولا يقولوا سوءا في أحد، ولا يكونوا مخاصمين، بل لطفاء يعاملون الجميع بوداعة تامة.","3:3":"فإننا نحن أيضا كنا في الماضي جهالا، غير مطيعين، تائهين في الضلال، عبيدا يخدمون الشهوات واللذات المختلفة، نعيش في الخبث والحسد، مكروهين، وكارهين بعضنا لبعض.","3:4":"ولكن، لما ظهر لطف مخلصنا الله، ومحبته للناس،","3:5":"خلصنا لا على أساس أعمال بر قمنا بها نحن، وإنما بموجب رحمته، وذلك بأن غسلنا كليا غسل الخليقة الجديدة والتجديد الذي يجريه الروح القدس،","3:6":"الذي سكبه علينا بغنى بيسوع المسيح مخلصنا.","3:7":"حتى إذا تبررنا بنعمته، نصير ورثة، وفقا لرجائنا بالحياة الأبدية.","3:8":"صادق هذا القول! وأريد أن تقرر هذه الأمور قرارا حاسما، حتى يهتم الذين آمنوا بالله بأن يجتهدوا في الأعمال الصالحة. هذه الأمور حسنة ونافعة للناس.","3:9":"أما المسائل السخيفة، وسلاسل النسب، والمخاصمات، والمنازعات حول الشريعة، فتجنبها، لأنها غير نافعة، وباطلة.","3:10":"وصاحب الهرطقة اقطع العلاقة به بعد إنذاره أولا وثانيا،","3:11":"عالما أن مثل هذا هو منحرف يمضي في الخطيئة وقد حكم على نفسه بنفسه!","3:12":"حالما أرسل إليك أرتماس أو تيخيكس، اجتهد أن تأتيني إلى مدينة نيكوبوليس، لأني قررت أن أقضي فصل الشتاء هناك.","3:13":"اجتهد في إطلاق زيناس المحامي وأبلوس بعد تزويدهما للسفر، حتى لا يحتاجا إلى شيء.","3:14":"وليتعلم ذوونا أيضا أن يمارسوا أعمالا حسنة، لسد الحاجات الضرورية، لكي لا يكونوا عديمي الثمر.","3:15":"جميع الذين معي يسلمون عليك. سلم على محبينا في الإيمان. لتكن النعمة معكم جميعا!"},"Phm":{"1:1":"من بولس، السجين لأجل المسيح يسوع، ومن تيموثاوس الأخ، إلى فليمون الحبيب شريكنا في العمل،","1:2":"وإلى أبفية الأخت، وأرخيبوس رفيقنا في التجند، وإلى الكنيسة التي في بيتك.","1:3":"لتكن لكم النعمة والسلام من الله أبينا والرب يسوع المسيح!","1:4":"إني أشكر إلهي، إذ أذكرك دائما في صلواتي،","1:5":"وقد سمعت بما لك من محبة وأمانة من نحو الرب يسوع، ومن نحو جميع القديسين،","1:6":"طالبا أن يكون اشتراكك معنا في الإيمان فعالا، فتدرك إلى التمام ما فينا من كل صلاح لأجل المسيح.","1:7":"فقد كان لي أيها الأخ، سرور عظيم وتشجيع، بفضل محبتك، لأن عواطف القديسين قد انتعشت بفضلك!","1:8":"لذلك، فمع أن لي كامل الحق في المسيح أن آمرك بالواجب،","1:9":"إلا أني، إكراما للمحبة، اخترت أن أقدم إليك التماسا، بصفتي بولس العجوز والسجين حاليا لأجل المسيح يسوع.","1:10":"فألتمس منك لأجل ولدي الذي ولدته وأنا مكبل بالقيود، أونسيموس،","1:11":"الذي كان في الماضي غير نافع لك، ولكنه الآن نافع لك ولي.","1:12":"فإياه أرد إليك، فاقبله كأنه فلذة من كبدي!","1:13":"وكنت راغبا في الاحتفاظ به لنفسي، لكي يخدمني نيابة عنك في قيود الإنجيل.","1:14":"ولكني لم أرد أن أفعل شيئا من دون رأيك، ليكون معروفك لا كأنه عن اضطرار بل عن اختيار.","1:15":"فربما لهذا السبب قد أبعد إلى حين: كي تمتلكه إلى الأبد،","1:16":"لا كعبد في ما بعد، بل أفضل من عبد، أخا حبيبا، إلي بخاصة، فكم بالأحرى إليك، في الجسد وفي الرب معا؟","1:17":"فإن كنت تعتبرني شريكك، فاقبله كأنه أنا.","1:18":"وإن كان قد أساء إليك في شيء، أو كان مديونا لك بشيء، فاحسب ذلك دينا علي.","1:19":"وها أنا بولس قد كتبت هذا بخط يدي: أنا أوفي، ولست أذكرك هنا أنك مديون لي بنفسك أيضا.","1:20":"نعم، أيها الأخ، أطلب منك أن تنفعني، في الرب، بهذا المعروف: أنعش عواطفي في المسيح","1:21":"لما كنت واثقا بإطاعتك، كتبت هذه الرسالة إليك، عالما أنك ستفعل أيضا فوق ما أطلب.","1:22":"وفضلا عن هذا، أعد لي عندك مكانا للإقامة، لأني أرجو أن أوهب لكم إجابة لصلواتكم.","1:23":"يسلم عليك أبفراس، رفيق سجني في المسيح يسوع،","1:24":"وكذلك مرقس، وأرسترخس، وديماس، ولوقا زملائي في العمل.","1:25":"ولتكن نعمة ربنا يسوع المسيح مع روحكم!"},"Heb":{"1:1":"إن الله ، في الأزمنة الماضية، كلم آباءنا بلسان الأنبياء الذين نقلوا إعلانات جزئية بطرق عديدة ومتنوعة.","1:2":"أما الآن، في هذا الزمن الأخير، فقد كلمنا بالابن، الذي جعله وارثا لكل شيء، وبه قد خلق الكون كله!","1:3":"إنه ضياء مجد الله وصورة جوهره. حافظ كل ما في الكون بكلمته القديرة. وهو الذي بعدما طهرنا بنفسه من خطايانا،","1:4":"جلس في الأعالي عن يمين الله العظيم. وهكذا، أخذ مكانا أعظم من الملائكة، بما أن الاسم الذي ورثه متفوق جدا على أسماء الملائكة جميعا!","1:5":"فلأي واحد من الملائكة قال الله مرة: «أنت ابني، أنا اليوم ولدتك!» أو قال أيضا: «أنا أكون له أبا، وهو يكون لي ابنا؟»","1:6":"وعندما يعيد الله ابنه البكر إلى العالم، يقول: «ولتسجد له ملائكة الله جميعا!»","1:7":"وعن الملائكة يقول: «قد جعل ملائكته رياحا، وخدامه لهيب نار!»","1:8":"ولكنه يخاطب الابن قائلا: «إن عرشك، ياالله، ثابت إلى أبد الآبدين، وصولجان حكمك عادل ومستقيم.","1:9":"إنك أحببت البر وأبغضت الإثم. لذلك مسحك الله إلهك ملكا، إذ صب عليك زيت البهجة أكثر من رفقائك!»","1:10":"كما يخاطب الابن أيضا بقوله: «أنت، يارب، وضعت أساس الأرض في البداية. والسماوات هي صنع يديك.","1:11":"هي تفنى، وأنت تبقى. فسوف تبلى كلها كما تبلى الثياب،","1:12":"فتطويها كالرداء، ثم تبدلها. ولكنك أنت الدائم الباقي، وسنوك لن تنتهي!»","1:13":"فهل قال الله مرة لأي واحد من الملائكة ما قاله للابن: «اجلس عن يميني حتى أجعل أعداءك موطئا لقدميك؟»","1:14":"لا! فليس الملائكة إلا أرواحا خادمة ترسل لخدمة الذين سيرثون الخلاص.","2:1":"لذلك، يجب علينا أن نهتم أشد الاهتمام بالكلام الذي سمعناه، متنبهين ألا ننحرف عنه.","2:2":"فإننا نعلم أن كل كلمة نقلتها الملائكة، قد تبين أنها ثابتة، وقد نال كل متعد أو مخالف لها عقابا عادلا.","2:3":"فكيف نفلت نحن إن أهملنا هذا الخلاص العظيم جدا؟ فإن الرب يسوع نفسه قد أعلنه أولا، ثم تثبت لنا من الذين سمعوه مباشرة.","2:4":"وقد أيد الله شهادتهم بعلامات وعجائب ومعجزات مختلفة، وبالمواهب التي وزعها الروح القدس وفقا لإرادته!","2:5":"ثم إن «العالم الآتي» الذي نتحدث عنه كثيرا، لن يكون خاضعا لسيطرة الملائكة.","2:6":"فقد شهد أحدهم في موضع من الكتاب، قائلا:","2:7":"جعلته أدنى من الملائكة إلى حين، ثم كللته بالمجد والكرامة، وأعطيته السلطة على كل ما صنعته يداك.","2:8":"أخضعت كل شيء تحت قدميه!» فمادام الله قد أخضع للابن كل شيء، فإنه لم يترك شيئا غير خاضع له. ولكننا الآن لا نرى كل شيء تحت سلطته: (لأن ذلك سيحدث فيما بعد).","2:9":"إلا أننا نرى يسوع الآن مكللا بالمجد والكرامة، لأنه قاسى الموت. وذلك بعدما صار أدنى من الملائكة إلى حين، ليذوق بنعمة الله الموت عوضا عن كل واحد.","2:10":"فلما قصد الله ، الذي من أجله كل شيء وبه كل شيء، أن يحضر إلى المجد أبناء كثيرين، كان من اللائق أن يجعل قائدهم إلى الخلاص مؤهلا لإكمال مهمته عن طريق الآلام.","2:11":"فإن للمسيح الذي يقدس المؤمنين به، وللمقدسين أنفسهم، أبا واحدا. لهذا، لا يستحي المسيح أن يدعو المؤمنين به إخوة له.","2:12":"إذ يقول الكتاب بلسانه: «أعلن اسمك لإخوتي. وأسبحك في وسط الجماعة!»","2:13":"ويقول أيضا: «وأنا أكون متوكلا عليه!» وأيضا: «ها أنا مع الأولاد الذين وهبهم الله لي!»","2:14":"إذن، بما أن هؤلاء الأولاد متشاركون في أجسام بشرية من لحم ودم، اشترك المسيح أيضا في اللحم والدم باتخاذه جسما بشريا. وهكذا تمكن أن يموت، ليقضي على من له سلطة الموت، أي إبليس،","2:15":"ويحرر من كان الخوف من الموت يستعبدهم طوال حياتهم.","2:16":"نعم، كانت غايته أن ينقذ لا الملائكة بل نسل إبراهيم.","2:17":"ولذلك كان لابد أن يشبه إخوته من جميع النواحي، ليكون هو رئيس الكهنة، الرحيم والأمين، الذي يقوم بعمله أمام الله نيابة عن الشعب، فيكفر عن خطاياهم.","2:18":"وبما أنه هو نفسه، قد تألم وتعرض للتجارب، فهو قادر أن يعين الذين يتعرضون للتجارب.","3:1":"إذن، أيها الإخوة القديسون الذين اشتركتم في الدعوة السماوية، تأملوا يسوع: الرسول ورئيس الكهنة في الإيمان الذي نتمسك به.","3:2":"فهو أمين لله في المهمة التي عينه لها، كما كان موسى أمينا في القيام بخدمته في بيت الله كله.","3:3":"إلا أنه يستحق مجدا أعظم من مجد موسى، كما أن الذي يبني بيتا ينال إكراما ومدحا أكثر مما ينال البيت الذي بناه!","3:4":"طبعا، كل بيت لابد أن يكون له بان، والله نفسه هو باني كل شيء.","3:5":"إن موسى كان أمينا في كل بيت الله، ولكن بصفته خادما. وكان ذلك شهادة لما أعلنه الله في ما بعد.","3:6":"أما المسيح، فهو أمين بصفته ابنا يترَأس على البيت. وهذا البيت هو نحن المؤمنين، على أن نتمسك بالثقة والافتخار برجائنا تمسكا ثابتا حتى النهاية.","3:7":"لهذا، ينبهنا الروح القدس إذ يقول: «اليوم، إن سمعتم صوته،","3:8":"فلا تقسوا قلوبكم، كما حدث قديما، حين أثار آباؤكم غضبي، يوم التجربة في الصحراء.","3:9":"هناك جربوني واختبروني، وقد شاهدوا أعمالي طوال أربعين سنة.","3:10":"لذلك ثار غضبي على ذلك الجيل، وقلت: إن قلوبهم تدفعهم دائما إلى الضلال، ولم يعرفوا طرقي قط!","3:11":"وهكذا، في غضبي، أقسمت قائلا: إنهم لن يدخلوا مكان راحتي!»","3:12":"فعليكم، أيها الإخوة، أن تأخذوا حذركم جيدا، حتى لا يكون قلب أي واحد منكم شريرا لا إيمان فيه، مما يؤدي به إلى الارتداد عن الله الحي.","3:13":"وإنما، شجعوا بعضكم بعضا كل يوم، مادمنا نقول: «اليوم...». وذلك لكي لا تقسي الخطيئة قلب أحد منكم بخداعها.","3:14":"فإن تمسكنا دائما بالثقة التي انطلقنا بها في البداية، وأبقيناها ثابتة إلى النهاية، نكون مشاركين للمسيح.","3:15":"فمازال التحذير موجها إلينا: «اليوم، إن سمعتم صوته، فلا تقسوا قلوبكم، كما حدث قديما عندما أثير غضبي...!»","3:16":"فمن هم الذين أثاروا غضب الله عندما سمعوا الدعوة ورفضوها؟ إنهم ذلك الشعب الذي خرج من مصر بقيادة موسى!","3:17":"وعلى من ثار غضب الله مدة أربعين سنة؟ على أولئك الذين أخطأوا، فسقطت جثثهم متناثرة في الصحراء!","3:18":"ولمن أقسم الله أنهم لن يدخلوا أبدا مكان راحته؟ للذين عصوا أمره!","3:19":"وهكذا، نرى أن عدم الإيمان منعهم من الدخول إلى مكان الراحة.","4:1":"ومادام الوعد بالدخول إلى الراحة الإلهية قائما حتى الآن، فلنخف: فربما تبين أن بعضا منكم قد فشلوا في الدخول.","4:2":"ذلك أن البشارة بالوعد قد وصلت إلينا، نحن أيضا، كما كانت قد وصلت إلى ذلك الشعب. ولكن البشارة لم تنفع سامعيها شيئا، لأنهم قابلوها بالرفض فلم يؤمنوا بها.","4:3":"أما نحن، الذين آمنا بالبشارة، فسوف ندخل الراحة الإلهية. إذ قال عن الذين لم يؤمنوا: «وهكذا، في غضبي، أقسمت قائلا: إنهم لن يدخلوا مكان راحتي...!» هذه الراحة، كانت جاهزة منذ أن أتم الله تأسيس العالم.","4:4":"فقد قال الوحي في موضع من الكتاب مشيرا إلى اليوم السابع: «ثم استراح الله من جميع أعماله في اليوم السابع».","4:5":"ثم عاد فقال: «لن يدخلوا مكان راحتي!»","4:6":"وهكذا، يتبين أن الراحة الإلهية هي في انتظار من سيدخلون إليها. وبما أن الذين تلقوا البشارة بها أولا لم يدخلوا إليها بسبب تمردهم،","4:7":"أعلن الله عن فرصة جديدة، إذ قال: «اليوم...» بلسان داود، بعدما مضى زمان طويل على ما كان قد قاله قديما: «اليوم، إن سمعتم صوته، فلا تقسوا قلوبكم...»","4:8":"فلو كان يشوع قد أدخل الشعب إلى الراحة، لما تكلم الله بعد ذلك عن موعد جديد للدخول بقوله: «اليوم...»","4:9":"إذن، مازالت الراحة الحقيقية الكاملة محفوظة لشعب الله.","4:10":"فالذي يدخل تلك الراحة، يستريح هو أيضا من أعماله، كما استراح الله من أعماله.","4:11":"لذلك، لنجتهد جميعا للدخول إلى تلك الراحة، لكي لا يسقط أحد منا كما سقط أولئك الذين عصوا أمر الله.","4:12":"ذلك لأن كلمة الله حية، وفعاله، وأمضى من كل سيف له حدان، وخارقة إلى مفترق النفس والروح والمفاصل ونخاع العظام، وقادرة أن تميز أفكار القلب ونياته.","4:13":"وليس هنالك مخلوق واحد محجوب عن نظر الله، بل كل شيء عريان ومكشوف أمام عينيه، هو الذي سنؤدي له حسابا.","4:14":"فمادام لنا رئيس كهنتنا العظيم الذي ارتفع مجتازا السماوات، وهو يسوع ابن الله، فلنتمسك دائما بالاعتراف به.","4:15":"ذلك لأن رئيس الكهنة الذي لنا، ليس عاجزا عن تفهم ضعفاتنا، بل إنه قد تعرض للتجارب التي نتعرض نحن لها، إلا أنه بلا خطية.","4:16":"فلنتقدم بثقة إلى عرش النعمة، لننال الرحمة ونجد نعمة تعيننا عند الحاجة.","5:1":"فإن الكاهن الأعلى كان يؤخذ من بين الناس، ويعين للقيام بمهمته نيا بة عنهم في ما يخص علاقتهم بالله. وذلك لكي يرفع إلى الله التقدمات والذبائح، تكفيرا عن الخطايا.","5:2":"ولكونه، هو أيضا، معرضا للضعف البشري دائما، كان يمكنه أن يعطف على الجهال والضالين.","5:3":"وبسبب ضعفه، كان من واجبه أيضا أن يكفر عن خطاياه الخاصة كما يكفر عن خطايا الآخرين.","5:4":"ولم يكن أحد يتخذ لنفسه هذه الوظيفة الشريفة متى أراد، بل كان يتخذها من دعاه الله إليها، كما دعا هرون.","5:5":"كذلك المسيح لم يرفع نفسه حتى يصير رئيس كهنة، بل إن الله هو الذي قال له: «أنت ابني. أنا اليوم ولدتك!»","5:6":"وخاطبه في موضع آخر بقوله: «أنت كاهن إلى الأبد على رتبة ملكيصادق!»","5:7":"والمسيح، في أثناء حياته البشرية على الأرض، رفع أدعية وتضرعات مقترنة بصراخ شديد ودموع، إلى القادر أن يخلصه من الموت. وقد لبى الله طلبه إكراما لتقواه.","5:8":"فمع كونه ابنا تعلم الطاعة من الآلام التي قاساها.","5:9":"وبذلك، أصبح مؤهلا لمهمته، فصار لجميع الذين يطيعونه مصدرا للخلاص الأبدي.","5:10":"وقد أيد الله ذلك، فأعلنه رئيس كهنة على رتبة ملكيصادق.","5:11":"بخصوص رئيس الكهنة هذا، عندي كلام كثير، ولكنه صعب التفسير! إذ يبدو أنكم تعانون بلادة في الفهم.","5:12":"كان يجب أن تكونوا الآن قادرين على تعليم الآخرين، بعدما مضى زمان طويل على اهتدائكم. ولكنكم مازلتم بحاجة إلى من يعلمكم حتى المباديء الأساسية لإعلانات الله. ها قد عدتم من جديد تحتاجون إلى اللبن! فأنتم غير قادرين على هضم الطعام القوي.","5:13":"وكل من يتناول اللبن، يكون عديم الخبرة في التعليم القويم، لأنه مازال طفلا غير ناضج.","5:14":"أما الناضجون روحيا، فهم قادرون على تناول الطعام القوي: لأن حواسهم قد تدربت، بالممارسة الصحيحة، على التمييز بين الخير والشر.","6:1":"لذلك، فلنترك تلك المباديء الأولية عن المسيح، ونتقدم إلى النضوج الكامل. ولا نضع من جديد تلك الأسس التي تعلمناها سابقا، وهي: التوبة من الأعمال المميتة، والإيمان بالله،","6:2":"والنظم المختصة بطقوس الاغتسال، ووضع الأيدي، وقيامة الأموات، والدينونة الأبدية.","6:3":"وبإذن الله، سنفعل ذلك كله!","6:4":"ذلك لأن الذين قد تعرضوا مرة لنور الإيمان بالمسيح، فذاقوا العطية السماوية، وصاروا (إلى حين) من شركاء الروح القدس،","6:5":"وذاقوا كلمة الله الطيبة، وشاهدوا المعجزات التي تظهر عظمة «العالم الآتي»،","6:6":"ثم ارتدوا إلى تلك الأسس القديمة، أولئك يستحيل عليهم أن يتجددوا ثانية فيعودوا إلى التوبة. فهم يجنون على أنفسهم إذ يصلبون ابن الله مرة ثانية ويجعلونه عرضة للعار.","6:7":"ولا عجب، فالتربة التي تشرب الأمطار النازلة عليها مرارا كثيرة، ثم تنتج نباتا ينفع الذين حرثوها، تنال البركة من الله!","6:8":"ولكنها، إن أخرجت الشوك والعشب البري، تكون مرفوضة وتستحق اللعنة، وما نهايتها إلا الحريق.","6:9":"أيها الأحباء، مع أني قصدت تحذيركم بما قلته هنا، فأنا مقتنع بأن خلاصكم أمر لا شك فيه. إذ قد عملتم أعمالا فضلى، ترافق هذا الخلاص.","6:10":"وليس الله بظالم حتى ينسى عملكم الجاد في إظهار محبتكم له عن طريق خدمتكم للقديسين إكراما لاسمه، الأمر الذي قمتم به قبلا، وتقومون به الآن!","6:11":"وإنما نتمنى أن يظهر كل واحد منكم اجتهادا مماثلا في المحافظة حتى النهاية على الثقة الكاملة بالرجاء.","6:12":"وذلك حتى لا تتكاسلوا، بل تقتدوا بالذين يرثون ما وعد الله به، عن طريق الإيمان والصبر.","6:13":"لنأخذ وعد الله لإبراهيم مثلا. فلما قطع له ذلك الوعد، أقسم بنفسه، إذ ليس هنالك من هو أعظم منه حتى يقسم به.","6:14":"وقد قال له: «لأباركنك وأعطينك نسلا كثيرا!»","6:15":"وهكذا، انتظر إبراهيم بصبر فنال ما وعد به.","6:16":"فالواقع أن الناس يقسمون بالأعظم. والقسم عندهم، يضع حدا لكل مشاجرة لأنه يحسم الأمور.","6:17":"ولذلك، لما أراد الله أن يؤكد بصورة قاطعة لوارثي وعده، أن قراره لا يتغير أبدا، ثبته بالقسم.","6:18":"فاستنادا إلى وعد الله وقسمه، وهما أمران ثابتان لا يتغيران ويستحيل أن يكذب الله فيهما، نحصل على تشجيع قوي، بعدما التجأنا إلى التمسك بالرجاء الموضوع أمامنا.","6:19":"هذا الرجاء هو لنا بمثابة مرساة أمينة ثابتة تشد نفوسنا إلى ما وراء الحجاب السماوي.","6:20":"فلأجلنا دخل يسوع إلى هناك سابقا لنا. وهو هناك يقوم بمهمته نيابة عنا بعدما صار رئيس كهنة إلى الأبد على رتبة ملكيصادق!","7:1":"فإن ملكيصادق المذكور، كان ملكا على مدينة ساليم وكاهنا لله العلي، في وقت واحد. وقد استقبل إبراهيم العائد منتصرا من معركة هزم فيها عددا من الملوك، ونقل إليه بركة الله.","7:2":"وأدى له إبراهيم عشرا من كل ما غنمه في المعركة. فمن جهة، يعني اسم ملكيصادق «ملك العدل». ومن جهة أخرى، كان لقبه «ملك ساليم» أي «ملك السلام».","7:3":"والوحي لا يذكر له أبا ولا أما ولا نسبا، كما لا يذكر شيئا عن ولادته أو موته. وذلك لكي يصح اعتباره رمزا لابن الله، بوصفه كاهنا إلى الأبد.","7:4":"لنتأمل الآن كم كان هذا الشخص عظيما. فحتى إبراهيم، جدنا الأكبر، أدى له عشرا من غنائمه.","7:5":"ونحن نعلم أن شريعة موسى توصي الكهنة المتحدرين من نسل لاوي بأن يأخذوا العشور من الشعب، أي من إخوتهم، مع أن أصلهم جميعا يرجع إلى إبراهيم.","7:6":"ولكن ملكيصادق الذي لا يجمعه بهؤلاء أي نسب، أخذ العشر من إبراهيم وباركه، مع كون إبراهيم حاصلا على وعود بالبركة من الله.","7:7":"إذن، لا خلاف أن ملكيصادق أعظم من إبراهيم، وإلا فما كان قد باركه!","7:8":"أضف إلى ذلك أن الكهنة المتحدرين من نسل لاوي، الذين يأخذون العشور بموجب الشريعة، هم بشر يموتون. أما ملكيصادق، الذي أخذ العشور من إبراهيم، فمشهود له بأنه حي.","7:9":"ولو جاز القول، لقلنا: حتى لاوي، الذي يأخذ نسله العشور، هو أيضا قد أدى العشور لملكيصادق من خلال إبراهيم.","7:10":"فمع أن لاوي لم يكن قد ولد بعد، فإنه كان موجودا في صلب جده إبراهيم، عندما لاقاه ملكيصادق.","7:11":"إن شريعة موسى كلها كانت تدور حول نظام الكهنوت الذي قام بنو لاوي بتأدية واجباته. إلا أن ذلك النظام لم يوصل إلى الكمال أولئك الذين كانوا يعبدون الله على أساسه. وإلا، لما دعت الحاجة إلى تعيين كاهن آخر على رتبة ملكيصادق، وليس على رتبة هرون!","7:12":"وحين يحدث أي تغير في الكهنوت، فمن الضروري أن يقابله تغير مماثل في شريعة الكهنوت.","7:13":"فالمسيح، رئيس كهنتنا، لم يكن من سبط لاوي، الذي كان كهنة اليهود يتحدرون منه.","7:14":"إذ من الواضح تاريخيا أن ربنا يرجع بأصله البشري إلى يهوذا. وشريعة موسى لا تذكر أية علاقة لنسل يهوذا بنظام الكهنوت.","7:15":"ومما يزيد الأمر وضوحا، أن الكاهن الجديد، الشبيه بملكيصادق،","7:16":"لم يعين كاهنا على أساس الشريعة التي توصي بضرورة الانتماء إلى نسل بشري معين، بل على أساس القوة النابعة من حياته التي لا تزول أبدا.","7:17":"ذلك لأن الوحي يشهد له قائلا: «أنت كاهن إلى الأبد على رتبة ملكيصادق!»","7:18":"هكذا، يتبين أن نظام الكهنوت القديم قد ألغي لأنه عاجز وغير نافع.","7:19":"فالشريعة لم توصل الذين كانوا يعبدون الله بحسبها ولو إلى أدنى درجات الكمال. ولذلك، وضع الله أساسا جديدا للاقتراب إليه، مقدما لنا رجاء أفضل.","7:20":"ثم إن تعيين المسيح رئيس كهنة، قد تأيد بالقسم.","7:21":"أما بنو لاوي، فكانوا يصيرون كهنة دون أي قسم. هذا القسم واضح في قول الله: «أقسم الرب ولن يتراجع: أنت كاهن إلى الأبد...»","7:22":"فعلى أساس ذلك القسم، صار يسوع ضامنا لعهد أفضل!","7:23":"فضلا عن هذا، فالكهنة العاديون كانوا يتغيرون دائما، لأن الموت كان يمنع أي واحد منهم من البقاء.","7:24":"وأما المسيح، فلأنه حي إلى الأبد، فهو يبقى صاحب كهنوت لا يزول!","7:25":"وهو لذلك قادر دائما أن يحقق الخلاص الكامل للذين يتقربون به إلى الله. فهو، في حضرة الله، حي على الدوام ليتضرع من أجلهم ويحامي عنهم!","7:26":"نعم، هذا هو رئيس الكهنة الذي كنا محتاجين إليه. إنه قدوس، لا عيبة فيه، ولا نجاسة، قد انفصل عن الخاطئين، وارتفع حتى صار أسمى من السماوات.","7:27":"وهو لا يحتاج إلى ما كان يحتاج إليه قديما كل رئيس كهنة: أن يقدم الذبائح يوميا للتكفير عن خطاياه الخاصة أولا، ثم عن خطايا الشعب، وذلك لأنه كفر عن خطاياهم مرة واحدة، حين قدم نفسه عنهم.","7:28":"إذن، كانت الشريعة تعين كل رئيس كهنة من بين البشر الضعفاء. أما كلمة القسم، التي جاءت بعد الشريعة، فقد عينت ابن الله، المؤهل تماما لمهمته، رئيس كهنة إلى الأبد!","8:1":"وخلاصة القول في هذا الموضوع، أن المسيح هو رئيس كهنتنا الذي وصفنا كهنوته هنا. إنه الآن جالس في السماء عن يمين عرش الله العظيم.","8:2":"وهو يقوم بمهمته هناك، في قدس الأقداس: في خيمة العبادة الحقيقية التي نصبها الرب، لا الإنسان.","8:3":"فمهمة كل رئيس كهنة هي أن يقرب لله التقدمات والذبائح. وعليه، فمن الضروري أن يكون لرئيس كهنتنا ما يقدمه.","8:4":"فلو أن المسيح كان على هذه الأرض، لما كانت الشريعة تسمح له بأن يكون كاهنا. إذ تحصر الشريعة وظيفة الكهنوت في نسل واحد يحق للمتحدرين منه أن يقربوا التقدمات.","8:5":"وهؤلاء يقومون بخدمة ما يشكل رمزا وظلا للأمور التي في السماء. وهذا واضح من قول الله لموسى قبل أن يصنع خيمة العبادة. إذ أوحى إليه قائلا: «انتبه! عليك أن تصنع الخيمة وما فيها وفقا للمثال الذي أظهرته لك على الجبل!»","8:6":"فرئيس كهنتنا، إذن، قد حصل على خدمة أفضل من خدمة الكهنوت الأرضي، لكونه الوسيط الذي أعلن لنا قيام عهد جديد أفضل من العهد السابق، ولكون هذا العهد الجديد ينطوي على وعود أفضل.","8:7":"فلو كان العهد السابق بلا عيب، لما ظهرت الحاجة إلى عهد آخر يحل محله.","8:8":"والواقع أن الله نفسه يعبر عن عجز العهد السابق. وهذا واضح في قول أحد الأنبياء قديما:","8:9":"هذا العهد الجديد ليس كالعهد الذي أبرمته مع آبائهم، حين أمسكت بأيديهم وأخرجتهم من أرض مصر. فبما أنهم خرقوا ذلك العهد، يقول الرب، أصبح من حقي أن ألغيه!","8:10":"فهذا هو العهد الذي أبرمه مع بني إسرائيل، بعد تلك الأيام، يقول الرب: أضع شرائعي داخل ضمائرهم، وأكتبها على قلوبهم، وأكون لهم إلها، وهم يكونون لي شعبا.","8:11":"بعد ذلك، لا يعلم أحد منهم ابن وطنه ولا أخاه قائلا: تعرف بالرب! ذلك لأن الجميع سوف يعرفونني حق المعرفة، من الصغير فيهم إلى العظيم.","8:12":"لأني سأصفح عن آثامهم، ولا أعود أبدا إلى تذكر خطاياهم ومخالفاتهم!»","8:13":"وهكذا، نلاحظ أن الله بكلامه عن عهد جديد، جعل العهد السابق عتيقا. وطبيعي أن كل ما عتق وشاخ، يكون في طريقه إلى الزوال!","9:1":"حقا كان العهد العتيق يتضمن طقوسا وقوانين تنظم عبادة الله في خيمة مقدسة منصوبة على هذه الأرض.","9:2":"وكانت هذه الخيمة الكبيرة تحتوي على غرفتين يفصل بينهما الحجاب. الغرفة الأولى، واسمها «القدس»، كانت تحتوي على منارة ذهبية، ومائدة يوضع عليها خبز مقرب لله.","9:3":"أما الغرفة الثانية، الواقعة وراء الحجاب، فكانت تسمى «قدس الأقداس»،","9:4":"وتحتوي على موقد للبخور مصنوع من الذهب، وتابوت مغشى بالذهب من كل جهة، يدعى «تابوت العهد». وكان في داخل التابوت إناء مصنوع من الذهب يحتوي على بعض المن؛ وعصا هرون التي أطلعت ورقا أخضر؛ واللوحان المنقوشة عليهما وصايا العهد.","9:5":"أما فوق التابوت، فكان يوجد كروبا المجد (تمثالان لملاكين)، يخيمان بأجنحتهما على غطاء الصندوق الذي كان يدعى «كرسي الرحمة» ... وهنا، نكتفي بهذا المقدار من التفاصيل. فالمجال لا يتسع للمزيد.","9:6":"وبما أن هذه الأمور كانت مرتبة هكذا، كان الكهنة يدخلون دائما إلى الغرفة الأولى، حيث يقومون بواجبات خدمتهم.","9:7":"أما الغرفة الثانية، فلم يكن يدخلها إلا رئيس الكهنة وحده، مرة واحدة كل سنة. وكان من الواجب عليه أن يحمل دما يرشه على «كرسي الرحمة» تكفيرا عن نفسه وعن الخطايا التي ارتكبها الشعب عن جهل.","9:8":"وبهذا، يشير الروح القدس إلى أن الطريق المؤدية إلى «قدس الأقداس» الحقيقي في السماء، كانت غير مفتوحة بعد. ذلك لأن المسكن الأول مازال قائما.","9:9":"وما هذا إلا صورة للوقت الحاضر الذي فيه مازالت التقدمات والذبائح تقرب وفقا لنظام العهد العتيق. ولكنها لا تستطيع أن تطهر قلوب الذين يتقربون بها إلى الله، ولا أن توصلهم إلى الكمال فتريح ضمائرهم.","9:10":"إذ إن نظام العهد السابق قد اقتصر على تحريم بعض المأكولات والمشروبات وتحليل غيرها، وعلى وضع النظم المختصة بطقوس الاغتسال المختلفة. بل إن كل ما ضمه ذلك النظام، كان قوانين جسدية ينتهي عملها حين يأتي وقت الإصلاح.","9:11":"ذلك أن البركات السماوية قد تحققت في المسيح. فهو الآن كاهننا الأعلى الذي يؤدي مهمته في الخيمة الحقيقية، وهي أعظم وأكمل من الخيمة الأرضية. إنها في السماء. لم تصنعها يد بشرية، وليست من هذا العالم المادي.","9:12":"فإلى «قدس الأقداس» في هذه الخيمة، دخل المسيح مرة واحدة، حاملا دم نفسه، لا دم تيوس وعجول. وذلك بعدما سفك دمه عوضا عنا. فحقق فداء أبديا.","9:13":"ولا عجب! فوفقا للنظام السابق، كان دم الثيران والتيوس يرش على المنجسين، مع رماد عجلة محروقة، فيصيرون طاهرين طهارة جسدية.","9:14":"فكم بالأحرى دم المسيح الذي قدم نفسه لله بروح أزلي ذبيحة لا عيب فيها، يطهر ضمائرنا من الأعمال الميتة لنعبد الله الحي.","9:15":"ولذلك، فالمسيح هو الوسيط لهذا العهد الجديد. فبما أنه قد تم الموت فداء للمخالفات الحاصلة تحت العهد الأول، ينال المدعوون الوعد بالإرث الأبدي.","9:16":"فعندما يموت أحد ويترك وصية، لابد من إثبات موته للاستفادة من وصيته.","9:17":"إذ لا قوة للوصية على الإطلاق مادام صاحبها حيا. فلا تثبت الوصية إلا بموت صاحبها.","9:18":"وهكذا، فحتى العهد العتيق لم يبدأ تنفيذه إلا برش الدم.","9:19":"فمعلوم أن موسى، بعد تلاوة وصايا الشريعة كلها على الشعب، أخذ دم العجول والتيوس مع بعض الماء، ورشه على كتاب الشريعة، وعلى أفراد الشعب، بباقة من نبات الزوفا وصوف أحمر اللون.","9:20":"وقال: هذا دم العهد الذي أوصاكم الله بحفظه.","9:21":"وقد رش موسى الدم أيضا على خيمة العبادة، وعلى أدوات الخدمة التي فيها.","9:22":"فالشريعة توصي بأن يتطهر كل شيء تقريبا بالدم. ولا غفران إلا بسفك الدم!","9:23":"وبما أن تطهير الخيمة الأرضية كان يتطلب رش دم الذبائح الحيوانية، فإن الخيمة الحقيقية لابد أن تتطلب دم ذبيحة أفضل من الذبائح الأخرى.","9:24":"فالمسيح، رئيس كهنتنا، لم يدخل إلى «قدس الأقداس» الأرضي، الذي صنعته يد بشرية وما هو إلا ظل للحقيقة، بل دخل إلى السماء عينها، حيث يقوم الآن بتمثيلنا في حضرة الله بالذات.","9:25":"وهو لم يدخل ليقدم نفسه ذبيحة مرة بعد مرة، كما كان الكاهن الأعلى على الأرض يدخل مرة كل سنة إلى «قدس الأقداس» بدم غير دمه.","9:26":"وإلا لكان يجب أن يموت المسيح متألما مرات كثيرة منذ تأسيس العالم! ولكنه الآن، عند انتهاء الأزمنة، ظهر مرة واحدة ليبطل قوة الخطيئة بتقديم نفسه ذبيحة لله.","9:27":"فكما أن مصير الناس المحتوم، هو أن يموتوا مرة واحدة ثم تأتي الدينونة،","9:28":"كذلك المسيح أيضا: مات مرة واحدة حاملا خطايا كثيرين، مقربا نفسه (لله) عوضا عنهم. ولا بد أن يعود إلى الظهور. لا ليعالج الخطايا، بل ليحقق الخلاص النهائي لجميع منتظريه!","10:1":"فقد كانت شريعة موسى تتضمن ظلا واهيا للخيرات التي سيأتي بها المسيح، ولم تكن لتصور الحقيقة كما هي. ولذلك، لم تكن قادرة أن توصل إلى الكمال أولئك الذين يتقربون بها إلى الله، مقدمين دائما الذبائح السنوية عينها،","10:2":"وإلا، لما كان هنالك داع للاستمرار في تقديمها! لأن ضمائر العابدين، متى تطهرت مرة واحدة إلى التمام، لا تعود بحاجة إلى التطهير مرة ثانية: إذ يكون الشعور بالذنب قد زال.","10:3":"ولكن في عملية تقديم الذبائح المتكررة كل سنة، تذكيرا للعابدين بخطاياهم.","10:4":"فمن المستحيل أن يزيل دم الثيران والتيوس خطايا الناس.","10:5":"لذلك قال المسيح، عند مجيئه إلى هذه الأرض: «إن الذبائح والتقدمات ما أردتها. لكنك أعددت لي جسدا بشريا.","10:6":"فالحيوانات التي كانت تذبح وتحرق أمامك تكفيرا عن الخطيئة، لم ترض بها.","10:7":"عندئذ قلت لك: ها أنا آتي لأعمل إرادتك، ياالله . هذا هو المكتوب عني في صفحة الكتاب !»","10:8":"فبعد أن عبر المسيح عن عدم رضى الله بجميع التقدمات والذبائح التي كانت تقرب مع أنها كانت تقدم وفقا للشريعة،","10:9":"أضاف قائلا: «ها أنا آتي لأعمل إرادتك!» فهو، إذن، يلغي النظام السابق، ليضع محله نظاما جديدا ينسجم مع إرادة الله.","10:10":"بموجب هذه الإرادة الإلهية، صرنا مقدسين إذ قرب يسوع المسيح، مرة واحدة، جسده عوضا عنا!","10:11":"وقديما، كان كل كاهن يقف يوميا أمام المذبح ليقوم بمهمته، فيقدم لله تلك الذبائح عينها، مع أنها لم تكن قادرة على إزالة الخطايا إطلاقا.","10:12":"ولكن المسيح، رئيس كهنتنا، قدم ذبيحة واحدة عن الخطايا، ثم جلس إلى الأبد عن يمين الله،","10:13":"منتظرا أن يوضع أعداؤه موطئا لقدميه.","10:14":"إذ إنه، بتقدمة وحيدة جعل أولئك الذين قدسهم كاملين إلى الأبد.","10:15":"والروح القدس نفسه يشهد لنا بهذه الحقيقة. إذ قال أولا:","10:16":"«هذا هو العهد الذي أبرمه معهم بعد تلك الأيام، يقول الرب: أضع شرائعي في داخل قلوبهم، وأكتبها في عقولهم».","10:17":"ثم أضاف: «ولا أعود أبدا إلى تذكر خطاياهم ومخالفاتهم».","10:18":"فحينما يتحقق غفر ان الخطايا، لا تبقى حاجة بعد إلى تقريب التقدمات عنها!","10:19":"فلنا الآن، أيها الإخوة حق التقدم بثقة إلى «قدس الأقداس» (في السماء) بدم يسوع.","10:20":"وذلك بسلوك هذا الطريق الحي الجديد الذي شقه لنا المسيح بتمزيق الحجاب، أي جسده.","10:21":"ولنا أيضا كاهن عظيم يمارس سلطته على بيت الله.","10:22":"فلنتقدم إلى حضرة الله بقلب صادق وبثقة الإيمان الكاملة، بعدما طهر رش الدم قلوبنا من كل شعور بالذنب، وغسل الماء النقي أجسادنا.","10:23":"ولنتمسك دائما بالرجاء الذي نعترف به، دون أن نشك في أنه سيتحقق، لأن الذي وعدنا بتحقيقه، هو أمين وصادق.","10:24":"وعلى كل واحد منا أن ينتبه للآخرين، لنحث بعضنا بعضا على المحبة والأعمال الصالحة.","10:25":"وعلينا ألا ننقطع عن الاجتماع معا، كما تعود بعضكم أن يفعل. إنما، يجدر بكم أن تحثوا وتشجعوا بعضكم بعضا، وتواظبوا على هذا بقدر ما ترون ذلك اليوم يقترب.","10:26":"فإن أخطأنا عمدا برفضنا للمسيح بعد حصولنا على معرفة الحق، لا تبقى هناك ذبيحة لغفران الخطايا،","10:27":"بل انتظار العقاب الأكيد في لهيب النار التي ستلتهم المتمردين. ويا له من انتظار مخيف!","10:28":"تعلمون أن من خالف شريعة موسى، كان عقابه الموت دون رحمة، على أن يؤيد مخالفته شاهدان أو ثلاثة.","10:29":"ففي ظنكم، كم يكون أشد كثيرا ذلك العقاب الذي يستحقه من يدوس ابن الله، إذ يعتبر أن دم العهد، الذي يتقدس به، هو دم نجس، وبذلك يهين روح النعمة؟","10:30":"فنحن نعرف من قال: «لي الانتقام، أنا أجازي، يقول الرب!» وأيضا: «إن الرب سوف يحاكم شعبه!»","10:31":"حقا ما أرهب الوقوع في يدي الله الحي!","10:32":"لا تنسوا أبدا تلك الأيام الماضية التي فيها، بعدما أشرق عليكم نور الإيمان بالمسيح، صبرتم على جهاد مرير طويل، إذ قاسيتم كثيرا من الآلام.","10:33":"وذلك عندما تعرضتم للإهانات والمضايقات من جهة، وعندما شاركتم الذين عوملوا مثل هذه المعاملة من جهة أخرى.","10:34":"فقد تعاطفتم مع المسجونين، كما تقبلتم نهب ممتلكاتكم بفرح، علما منكم بأن لكم في السماء ثروة أفضل وأبقى.","10:35":"إذن، لا تتخلوا عن ثقتكم بالرب. فإن لها مكافأة عظيمة.","10:36":"إنكم تحتاجون إلى الصبر لتعملوا إرادة الله، فتنالوا البركة التي وعدتم بها.","10:37":"فقريبا جدا، سيأتي الآتي ولا يتمهل.","10:38":"وأما من تبرر بالإيمان، فبالإيمان يحيا. ومن ارتد لا تسر به نفسي!","10:39":"ولكننا نحن لسنا من أهل الارتداد المؤدي إلى الهلاك، بل من أهل الإيمان المؤدي إلى خلاص نفوسنا!","11:1":"أما الإيمان، فهو الثقة بأن ما نرجوه لابد أن يتحقق، والاقتناع بأن ما لا نراه موجود حقا.","11:2":"بهذا الإيمان، كسب رجال الله قديما شهادة حسنة أمام الله والناس.","11:3":"وعن طريق الإيمان، ندرك أن الكون كله قد خرج إلى الوجود بكلمة أمر من الله. حتى إن عالمنا المنظور، قد تكون من أمور غير منظورة!","11:4":"بالإيمان، قدم هابيل لله ذبيحة أفضل من تلك التي قدمها قايين. وعلى ذلك الأساس، شهد الله بأن هابيل بار، إذ قبل التقدمة التي قربها له. ومع أن هابيل مات قتلا، فإنه مازال الآن يلقننا العبر بإيمانه.","11:5":"وبالإيمان، انتقل أخنوخ إلى حضرة الله دون أن يموت. وقد اختفى من على هذه الأرض لأن الله أخذه إليه. وقبل حدوث ذلك، شهد له بأنه قد أرضى الله .","11:6":"فمن المستحيل إرضاء الله بدون إيمان. إذ إن من يتقرب إلى الله، لابد له أن يؤمن بأنه موجود، وبأنه يكافيء الذين يسعون إليه.","11:7":"وبالإيمان نوح، لما أنذره الله عن طريق الوحي بالطوفان الآتي، دفعه خوف الله إلى بناء سفينة ضخمة كانت وسيلة النجاة له ولعائلته، مع أنه لم يكن قد رأى طوفانا من قبل. وبعمله هذا، حكم على العالم وأصبح وارثا للبر القائم على أساس الإيمان.","11:8":"وبالإيمان، لبى إبراهيم دعوة الله، فترك وطنه وانطلق إلى أرض أخرى وعده الله بأن يورثه إياها. ولما خرج من بيته، كان لا يعرف أين يتوجه.","11:9":"وبالإيمان، كان يرحل كالغريب من مكان إلى آخر في الأرض التي وعده الله بها، وكأنها أرض غريبة. وكان يسكن في الخيام مع إسحاق ويعقوب، شريكيه في إرث الوعد عينه.","11:10":"فإنه كان ينتظر الانتقال إلى المدينة السماوية ذات الأسس الثابتة، التي مهندسها وبانيها هو الله .","11:11":"وبالإيمان أيضا، نالت سارة زوجة إبراهيم قدرة على الإنجاب، فولدت ابنا مع أنها كانت قد جاوزت سن الحمل. وذلك لأنها آمنت بأن الله ، الذي وعدها بذلك، لابد أن يحقق وعده.","11:12":"وهكذا ولد من إبراهيم، وقد كان ميتا من حيث القدرة على الإنجاب، شعب كبير «كنجوم الفضاء عددا، وكالرمل الذي على شط البحر، لا يحصى...»","11:13":"هؤلاء جميعا، حافظوا على إيمانهم إلى النهاية. وماتوا قبل أن تتحقق وعود الله لهم في أثناء حياتهم. ولكنهم رأوها من بعيد، وتوقعوا تحقيقها كاملة في المستقبل. وإذ آمنوا بتلك الوعود الإلهية اعترفوا بأنهم ليسوا إلا غرباء على الأرض يزورونها زيارة عابرة.","11:14":"والذين يقولون ذلك، يوضحون أن عيونهم على وطنهم الحقيقي.","11:15":"ولو كانوا يتذكرون الوطن الأرضي الذي هجروه، لاغتنموا الفرصة وعادوا إليه.","11:16":"ولكن، لا ... فهم الآن يتطلعون إلى وطن أفضل، أي الوطن السماوي. بسبب إيمانهم هذا لا يستحي الله أن يدعى إلههم. فهو قد أعد لهم مدينة!","11:17":"وبالإيمان، إبراهيم أيضا، لما امتحنه الله ، قدم إسحاق ابنه. فإنه، إذ قبل وعود الله، قدم ابنه الوحيد ذبيحة،","11:18":"مع أن الله قال له: «بإسحاق سوف يكون لك نسل يحمل اسمك!»","11:19":"فقد آمن إبراهيم بأن الله قادر على إقامة إسحاق من الموت. والواقع أن إبراهيم استعاد ابنه من الموت، على سبيل المثال أو الرمز.","11:20":"بالإيمان، بارك إسحاق يعقوب وعيسو.","11:21":"وبالإيمان، بارك يعقوب، قبيل موته، كل واحد من ابني يوسف، وسجد متوكئا على رأس عصاه.","11:22":"وبالإيمان، استند يوسف على وعد الله بإخراج بني إسرائيل من بلاد مصر، فترك وصية بأن ينقلوا رفاته معهم.","11:23":"بالإيمان موسى خبأه والداه حتى صار عمره ثلاثة أشهر، لأنهما رأياه طفلا جميلا، ولم يخافا المرسوم الذي أصدره الملك.","11:24":"وبالإيمان، موسى نفسه، لما كبر، رفض أن يدعى ابنا لابنة فرعون.","11:25":"بل اختار أن يتحمل المذلة مع شعب الله، بدلا من التمتع الوقتي بلذات الخطيئة.","11:26":"فقد اعتبر أن عار المسيح، هو ثروة أعظم من كنوز مصر، لأنه كان يتطلع إلى المكافأة.","11:27":"بالإيمان، ترك أرض مصر وهو غير خائف من غضب الملك. فقد مضى في تنفيذ قراره، كأنه يرى بجانبه الله غير المنظور.","11:28":"وبالإيمان، أقام الفصح ورش الدم، لكي لا يمس مهلك الأبكار أحدا من أبناء شعبه.","11:29":"بالإيمان اجتاز الشعب في البحر الأحمر كأنه أرض يابسة. أما المصريون، فإذ حاولوا ذلك غرقوا!","11:30":"بالإيمان انهارت أسوار مدينة أريحا، بعدما دار الشعب حولها لمدة سبعة أيام.","11:31":"وجزاء للإيمان، نجت راحاب الزانية من الموت المحتم مع المتمردين، بعدما استقبلت الجاسوسين بسلام.","11:32":"وهل من حاجة بعد لمزيد من الأمثلة؟ إن الوقت لا يتسع لي حتى أسرد أخبار الإيمان عن: جدعون وباراق وشمشون ويفتاح وداود وصموئيل والأنبياء.","11:33":"فبالإيمان، تغلب هؤلاء على ممالك الأعداء، وحكموا حكما عادلا ونالوا ما وعدهم به الله . وبه، أطبقوا أفواه الأسود،","11:34":"وأبطلوا قوة النار، ونجوا من الموت قتلا بالسيف. وبه أيضا نالوا القوة بعد ضعف، فصاروا أشداء في المعارك، وردوا جيوشا غريبة على أعقابها.","11:35":"وبالإيمان، استرجعت بعض النساء أمواتهن بعدما أعيدوا إلى الحياة. وبه، تحمل كثيرون العذاب والضرب، وماتوا رافضين النجاة لعلمهم أنهم سوف يقومون إلى حياة أفضل.","11:36":"وكثيرون غيرهم تحملوا المحاكمات الظالمة تحت الإهانة والجلد، والإلقاء في السجون مقيدين بالسلاسل.","11:37":"ومنهم من حوكموا فماتوا رجما بالحجارة، أو نشرا بالمنشار، أو ذبحا بالسيف. وبعضهم، تشردوا متسترين بجلود الغنم والمعزى، يعانون من الحاجة والضيق والظلم،","11:38":"ولم يكن العالم يستحقهم، تائهين في البراري والجبال والمغاور والكهوف.","11:39":"إن هؤلاء لم يحصلوا جميعا على تحقيق كل ما وعدهم الله به، مع أنهم حاصلون على شهادة حسنة من جهة الإيمان.","11:40":"ولكن الله سبق فأعد لنا ما هو أفضل، وذلك حتى لا يكملوا بمعزل عنا.","12:1":"فبما أن هذا العدد الكبير من الشاهدين للإيمان، يتجمع حولنا كأنه سحابة عظيمة، فلنطرح جانبا كل ثقل يعيقنا عن التقدم، ونتخلص من تلك الخطيئة التي نتعرض للسقوط في فخها بسهولة، لكي نتمكن، نحن أيضا، أن نركض باجتهاد في السباق الممتد أمامنا،","12:2":"متطلعين دائما إلى يسوع: رائد إيماننا ومكمله. فهو قد تحمل الموت صلبا، هازئا بما في ذلك من عار، إذ كان ينظر إلى السرور الذي ينتظره، ثم جلس عن يمين عرش الله.","12:3":"فتأملوا مليا ما قاساه بتحمله تلك المعاملة العنيفة التي عامله بها الخاطئون، لكي لا تتعبوا وتنهاروا!","12:4":"لم تقاوموا بعد حتى بذل الدم في مجاهدتكم ضد الخطيئة.","12:5":"فهل نسيتم الوعظ الذي يخاطبكم به الله بوصفكم أبناء له؟ إذ يقول: «ياابني، لا تستخف بتأديب الرب. ولا تفقد العزيمة حين يوبخك على الخطأ.","12:6":"فإن الذي يحبه الرب يؤدبه. وهو يجلد كل من يتخذه له ابنا!»","12:7":"إذن، تحملوا تأديب الرب. فهو يعاملكم معاملة الأبناء: وأي ابن لا يؤدبه أبوه؟","12:8":"فإن كنتم لا تتلقون التأديب الذي يشترك فيه أبناء الله جميعا، فمعنى ذلك أنكم لستم أبناء شرعيين له.","12:9":"إن آباءنا الأرضيين كانوا يؤدبوننا ونحن أولاد، وكنا نحترمهم. أفلا يجدر بنا الآن أن نخضع خضوعا تاما لتأديب أبي الأرواح، لنحيا حياة فضلى؟","12:10":"وقد أدبنا آباؤنا فترة من الزمان، حسب ما رأوه مناسبا. أما الله ، فيؤدبنا دائما من أجل منفعتنا: لكي نشترك في قداسته.","12:11":"وطبعا، كل تأديب لا يبدو في الحال باعثا على الفرح، بل على الحزن. ولكنه فيما بعد، ينتج بسلام في الذين يتلقونه ثمر البر.","12:12":"لذلك، شددوا أيديكم المرتخية، وركبكم المنحلة.","12:13":"ومهدوا لأقدامكم طرقا مستقيمة، حتى لا تنحرف أرجل العرج، بل تشفى!","12:14":"اجعلوا هدفكم أن تسالموا جميع الناس، وتعيشوا حياة مقدسة. فبغير قداسة، لا يقدر أحد أن يرى الرب.","12:15":"انتبهوا ألا يسقط أحدكم من نعمة الله، حتى لا يتأصل بينكم جذر مرارة، فيسبب بلبلة، وينجس كثيرين منكم.","12:16":"وحذار أن يكون بينكم زان أو مستهتر مثل عيسو الذي باع حقوقه بوصفه الابن البكر، لقاء أكلة واحدة.","12:17":"فأنتم تعلمون جيدا أنه لما أراد استعادة البركة من أبيه، بعدما كان قد استخف بها، رفض لأنه لم يجد مجالا للتوبة، مع أنه طلب البركة وهو يذرف الدموع.","12:18":"إنكم لم تقتربوا إلى جبل ملموس، مشتعل بالنار، ولا ضباب وظلام وريح عاصفة،","12:19":"حيث انطلق صوت بوق هاتفا بكلمات واضحة، وقد كان مرعبا حتى إن سامعيه التمسوا أن يتوقف عن الكلام.","12:20":"فإنهم لم يطيقوا احتمال هذا الأمر الصادر إليهم: «حتى الحيوان الذي يمس الجبل، يجب أن تقتلوه رجما!»","12:21":"والواقع أن ذلك المشهد كان مرعبا إلى درجة جعلت موسى يقول: «أنا خائف جدا بل مرتجف خوفا!»","12:22":"ولكنكم قد اقتربتم إلى جبل صهيون، إلى مدينة الله الحي، أورشليم السماوية. بل تقدمتم إلى حفلة يجتمع فيها عدد لا يحصى من الملائكة،","12:23":"إلى كنيسة تجمع أبناء لله أبكارا، أسماؤهم مكتوبة في السماء. بل إلى الله نفسه، ديان الجميع، وإلى أرواح أناس بررهم الله وجعلهم كاملين.","12:24":"كذلك، تقدمتم إلى يسوع، وسيط العهد الجديد، وإلى دمه المرشوش الذي يتكلم مطالبا بأفضل مما طالب به دم هابيل.","12:25":"إذن حذار أن ترفضوا الذي يتكلم! فمادام أولئك الذين رفضوا الاستماع لمن كلمهم على هذه الأرض، لم يفلتوا (من العقاب) قط، فكم بالأحرى لا نفلت نحن أبدا إن تحولنا عن الذي يتكلم إلينا من السماء عينها!","12:26":"وإذ تكلم الله قديما، زلزل صوته الأرض، أما الآن، فيعد قائلا: «إني مرة أخرى، سوف أزلزل لا الأرض وحدها، بل السماء أيضا!»","12:27":"وبقوله: «مرة أخرى»، يشير إلى أنه سوف يزيل كل ما ليس له أساس متين باعتباره مخلوقا، حتى لا تبقى إلا تلك الأشياء الثابتة الأساس.","12:28":"فبما أننا قد حصلنا على مملكة ثابتة لا تتزلزل، لنعبد الله ونخدمه شاكرين، بصورة ترضيه، بكل احترام ومخافة،","12:29":"متذكرين أن «إلهنا نار آكلة!»","13:1":"اثبتوا على المحبة الأخوية.","13:2":"ولا تغفلوا عن ضيافة الغرباء، فبها أضاف بعض القدماء ملائكة دون أن يعرفوا.","13:3":"اهتموا دائما بالمسجونين، كأنكم مسجونون معهم. وتعاطفوا مع المظلومين، كأنكم مظلومون معهم.","13:4":"حافظوا جميعا على كرامة الزواج، مبعدين النجاسة عن الفراش. فإن الله سوف يعاقب الذين ينغمسون في خطايا الدعارة والزنى.","13:5":"اجعلوا سيرتكم مترفعة عن حب المال، واقنعوا بما عندكم، لأن الله يقول: «لا أتركك، ولا أتخلى عنك أبدا!»","13:6":"فنستطيع إذن، أن نقول بكل ثقة وجرأة: «الرب معيني، فلن أخاف! ماذا يصنع بي الإنسان؟»","13:7":"اذكروا دائما مرشديكم الذين علموكم كلام الله. تأملوا سيرتهم حتى النهاية، واقتدوا بإيمانهم.","13:8":"يسوع المسيح هو هو أمسا واليوم وإلى الأبد.","13:9":"فلا تنخدعوا وتتبعوا تلك التعاليم الغريبة المتنوعة ... فمن الأفضل أن يثبت القلب بالنعمة لا بنظم الأطعمة التي لم تنفع المتقيدين بها.","13:10":"أما نحن، فلنا «مذبح» لا يحق للكهنة الذين يقومون بخدمة الخيمة الأرضية أن يأكلوا منه.","13:11":"فقد كان رئيس الكهنة قديما يحمل دم الحيوانات، ويدخل به إلى «قدس الأقداس»، حيث يقدمه تكفيرا عن الخطيئة، وكانت أجسام تلك الحيوانات تحرق خارج المحلة التي حل فيها الشعب","13:12":"لذلك تألم يسوع خارج باب المدينة، لكي يقدس الشعب بدم نفسه.","13:13":"فلنخرج إذن إلى خارج المحلة، قاصدين المسيح ونحن على استعداد لتحمل العار معه!","13:14":"فليس لنا هنا مدينة باقية، وإنما نسعى إلى المدينة الآتية.","13:15":"فبالمسيح، رئيس كهنتنا، لنقرب لله دائما ذبيحة الحمد والتسبيح، أي الثمار التي تنتجها أفواهنا المعترفة باسمه.","13:16":"ولا تغفلوا أيضا عن عمل الخير وإعانة المحتاجين: لأن مثل هذه «الذبائح» تسر الله جدا!","13:17":"أطيعوا مرشديكم، واخضعوا لهم، لأنهم يسهرون على مصلحتكم الروحية، كما يسهر الذي يحمل مسئولية سوف يقدم حسابا عن قيامه بها. وعندئذ، يؤدون مهمتهم بفرح دون تذمر. فلن يكون في تذمرهم نفع لكم!","13:18":"صلوا لأجلنا، فنحن مقتنعون بأن لنا ضميرا صالحا وراغبون في أن نحسن التصرف في كل شيء.","13:19":"وبالأخص، أرجو بإلحاح أن تطلبوا من الله أن يعيدني إليكم في أسرع وقت.","13:20":"وأسأل الله ، إله السلام الذي أقام من بين الأموات ربنا يسوع راعي الخراف العظيم بفضل دمه الذي ختم به العهد الأبدي","13:21":"أن يؤهلكم تماما لتعملوا مشيئته في كل عمل صالح، وأن يعمل فينا جميعا ما يرضيه بيسوع المسيح، له المجد إلى أبد الآبدين. آمين!","13:22":"إنما أسألكم، أيها الإخوة، أن تحتملوا ما وجهته إليكم من كلام الوعظ في هذه الرسالة، وهو قليل!","13:23":"واعلموا أن أخانا تيموثاوس قد أطلق من السجن. فإن أسرع في المجيء إلي، نذهب معا لرؤيتكم.","13:24":"سلموا على جميع مرشديكم، وعلى القديسين جميعا.","13:25":"لتكن النعمة معكم جميعا!"},"Jam":{"1:1":"من يعقوب، عبد الله والرب يسوع المسيح، إلى أسباط اليهود الاثني عشر، المشتتين في كل مكان سلام!","1:2":"ياإخوتي، عندما تنزل بكم التجارب والمحن المختلفة، اعتبروها سبيلا إلى الفرح الكلي.","1:3":"وكونوا على ثقة بأن امتحان إيمانكم هذا ينتج صبرا.","1:4":"ودعوا الصبر يعمل عمله الكامل فيكم، لكي يكتمل نضوجكم وتصيروا أقوياء قادرين على مواجهة جميع الأحوال.","1:5":"وإن كان أحد منكم بحاجة إلى الحكمة، فليطلب من الله الذي يعطي الجميع بسخاء ولا يعير. فسيعطى له.","1:6":"وإنما، عليه أن يطلب ذلك بإيمان، دون أي تردد أو شك. فإن المتردد كموجة البحر تتلاعب بها الرياح فتقذفها وتردها!","1:7":"فلا يتوهم المتردد أنه ينال شيئا من الرب.","1:8":"فعندما يكون الإنسان برأيين، لا يثبت على قرار في جميع أموره.","1:9":"من كان فقيرا وأخا مؤمنا، فليسر بمقامه الذي رفعه الله إليه.","1:10":"وأما الغني، فعليه أن يسر بأن ما له لا يغنيه عن الله: لأن نهايته ستكون كنهاية الأعشاب المزهرة.","1:11":"فعندما تشرق الشمس بحرها المحرق، تيبس تلك الأعشاب، فيسقط زهرها، ويتلاشى جمال منظرها. هكذا يذبل الغني في طرقه!","1:12":"طوبى لمن يتحمل المحنة بصبر. فإنه، بعد أن يجتاز الامتحان بنجاح، سينال «إكليل الحياة» الذي وعد به الرب محبيه!","1:13":"وإذا تعرض أحد لتجربة ما، فلا يقل: «إن الله يجربني!» ذلك لأن الله لا يمكن أن يجربه الشر، وهو لا يجرب به أحدا.","1:14":"ولكن الإنسان يسقط في التجربة حين يندفع مخدوعا وراء شهوته.","1:15":"فإذا ما حبلت الشهوة ولدت الخطيئة. ومتى نضجت الخطيئة، أنتجت الموت.","1:16":"فيا إخوتي الأحباء، لا تضلوا:","1:17":"إن كل عطية صالحة وهبة كاملة إنما تنزل من فوق، من لدن أبي الأنوار الذي ليس فيه تحول، ولا ظل لأنه لا يدور.","1:18":"وهو قد شاء أن يجعلنا أولادا له، فولدنا بكلمته، كلمة الحق. وغايته أن نكون باكورة خليقته.","1:19":"لذلك، ياإخوتي الأحباء، على كل واحد منكم أن يكون مسرعا إلى الإصغاء، غير متسرع في الكلام، بطيء الغضب.","1:20":"لأن الإنسان، إذا غضب، لا يعمل الصلاح الذي يريده الله .","1:21":"إذن، تخلصوا من كل ما في حياتكم من نجاسة وشر متزايد. وليكن قبولكم لتلك الكلمة التي غرسها الله في قلوبكم، قبولا وديعا. فهي القادرة أن تخلص نفوسكم.","1:22":"لا تكتفوا فقط بسماعها، بل اعملوا بها، وإلا كنتم تغشون أنفسكم.","1:23":"فالذي يسمع الكلمة ولا يعمل بها، يكون كمن ينظر إلى المرآة ليشاهد وجهه فيها.","1:24":"وبعد أن يرى نفسه، يذهب فينسى صورته حالا.","1:25":"أما الذي ينظر بالتدقيق في القانون الكامل، قانون الحرية، ويواظب على ذلك، فيكون كمن يعمل بالكلمة لا كمن يسمعها وينساها، فإن الله يباركه كثيرا في كل ما يعمله.","1:26":"وإن ظن أحد أنه متدين، وهو لا يلجم لسانه، فإنه يغش قلبه، وديانته غير نافعة!","1:27":"فالديانة الطاهرة النقية في نظر الله الآب، تظهر في زيارة الأيتام والأرامل لإعانتهم في ضيقهم، وفي صيانة النفس من التلوث بفساد العالم.","2:1":"ياإخوتي، نظرا لإيمانكم بربنا يسوع المسيح، رب المجد، لا تعاملوا الناس بالانحياز والتمييز!","2:2":"لنفرض أن إنسانين دخلا مجمعكم، أحدهما غني يلبس ثيابا فاخرة ويزين أصابعه بخواتم من ذهب، والآخر فقير يلبس ثيابا رثة.","2:3":"فإن رحبتم بالغني قائلين: «تفضل، اجلس هنا في الصدر!» ثم قلتم للفقير: «وأنت، قف هناك، أو اقعد على الأرض عند أقدامنا!»","2:4":"فإن ذلك يؤكد أنكم تميزون بين الناس بحسب طبقاتهم، جاعلين من أنفسكم قضاة ذوي أفكار سيئة!","2:5":"فياإخوتي الأحباء، أما اختار الله الفقراء في نظر الناس ليجعلهم أغنياء في الإيمان، ويعطيهم حق الإرث في الملكوت الذي وعد به محبيه؟","2:6":"ولكنكم أنتم عاملتم الفقير معاملة مهينة. ألا تعرفون أن الأغنياء هم الذين يتسلطون عليكم ويجرونكم إلى المحاكم،","2:7":"وهم الذين يستهزئون بالمسيح الذي تحملون اسمه الجميل؟","2:8":"ما أحسن عملكم حين تطبقون تلك القاعدة الملوكية الواردة في الكتاب: «تحب قريبك كما تحب نفسك!»","2:9":"ولكن عندما تعاملون الناس بالانحياز والتمييز، ترتكبون خطيئة وتحكم عليكم الشريعة باعتباركم مخالفين لها.","2:10":"فأنتم تعرفون أن من يطيع جميع الوصايا الواردة في شريعة موسى، ويخالف واحدة منها فقط، يصير مذنبا، تماما كالذي يخالف الوصايا كلها.","2:11":"فإن الله ، مثلا، قال: «لا تزن» كما قال: «لا تقتل!» فإن لم تزن، ولكن قتلت، فقد خرقت الشريعة.","2:12":"إذن، تصرفوا في القول والعمل بحسب قانون الحرية، كأنكم سوف تحاكمون وفقا له.","2:13":"فلابد أن يكون الحكم على الذين لا يمارسون الرحمة، حكما خاليا من الرحمة، أما الرحمة فهي تتفوق على الحكم!","2:14":"ياإخوتي، هل ينفع أحدا أن يدعي أنه مؤمن، وليس له أعمال تثبت ذلك، هل يقدر إيمان مثل هذا أن يخلصه؟","2:15":"لنفرض أن أخا أو أختا كانا بحاجة شديدة إلى الثياب والطعام اليومي،","2:16":"وقال لهما أحدكم: «أتمنى لكما كل خير. البسا ثيابا دافئة، وكلا طعاما جيدا!» دون أن يقدم لهما ما يحتاجان إليه من ثياب وطعام، فأي نفع في ذلك؟","2:17":"هكذا نرى أن الإيمان وحده ميت ما لم تنتج عنه أعمال.","2:18":"وربما قال أحدكم: «أنت لك إيمان وأنا لي أعمال». أرني كيف يكون إيمانك من غير أعمال، وأنا أريك كيف يكون إيماني بأعمالي.","2:19":"أنت تؤمن أن الله واحد؟ حسنا تفعل ! والشياطين أيضا تؤمن بهذه الحقيقة، ولكنها ترتعد خوفا.","2:20":"وهذا يؤكد لك، أيها الإنسان الغبي، أن الإيمان الذي لا تنتج عنه أعمال هو إيمان ميت!","2:21":"لنأخذ أبانا إبراهيم مثلا: كيف تبرر؟ أليس بأعماله، إذ أصعد ابنه إسحاق على المذبح","2:22":"فأنت ترى أن إيمان إبراهيم قد رافقته الأعمال. فبالأعمال قد اكتمل الإيمان.","2:23":"وهكذا، تم ما قاله الكتاب: «آمن إبراهيم بالله، فحسب له ذلك برا»، حتى إنه دعي «خليل الله».","2:24":"فترون إذن أن الإنسان لا يتبرر بإيمانه فقط، بل بأعماله أيضا.","2:25":"على هذا الأساس أيضا، تبررت راحاب التي كانت زانية: فقد استقبلت الرجلين اللذين أرسلا إليها، وصرفتهما في طريق آخر.","2:26":"فكما أن جسم الإنسان يكون ميتا إذا فارقته الروح، كذلك يكون الإيمان ميتا إذا لم ترافقه الأعمال!","3:1":"ياإخوتي، لا تتسابقوا كي تجعلوا أنفسكم معلمين لغيركم فتزيدوا عدد المعلمين! واذكروا أننا، نحن المعلمين، سوف نحاسب حسابا أقسى من غيرنا.","3:2":"فإننا جميعا معرضون للوقوع في أخطاء كثيرة. ولكن من يلجم لسانه ولا يخطيء في كلامه هو ناضج يقدر أن يسيطر على طبيعته سيطرة تامة.","3:3":"فحين نضع لجاما في فم حصان، نتمكن من توجيهه واقتياده كما نريد.","3:4":"ومهما كانت السفينة كبيرة والرياح التي تدفعها قوية وهوجاء، فبدفة صغيرة جدا يتحكم الربان فيها ويسوقها إلى الجهة التي يريد. كذلك اللسان أيضا: فهو عضو صغير،","3:5":"ولكن ما أشد فعاليته! انظروا: إن شرارة صغيرة تحرق غابة كبيرة!","3:6":"واللسان كالنار خطرا: فهو وحده، بين أعضاء الجسم، جامع للشرور كلها، ويلوث الجسم كله بالفساد. إنه يشعل دائرة الكون، ويستمد ناره من جهنم!","3:7":"من السهل على الإنسان أن يروض الوحوش والطيور والزواحف والحيوانات البحرية، بجميع أجناسها. فهذا ما نراه يحدث.","3:8":"ولكن أحدا من الناس لا يقدر أن يروض اللسان. فهو شر لا ينضبط، ممتليء بالسم القتال!","3:9":"به نرفع الحمد والشكر للرب والآب، وبه نوجه الشتائم إلى الناس الذين خلقهم الله على مثاله.","3:10":"وهكذا، تخرج البركات واللعنات من الفم الواحد. وهذا، ياإخوتي، يجب ألا يحدث أبدا!","3:11":"هل سمعتم أن نبعا واحدا يعطي ماء عذبا وماء مرا من عين واحدة؟","3:12":"أم هل يمكن، ياإخوتي، أن تثمر التينة زيتونا، أو الكرمة تينا؟ كذلك لا يمكن أن يعطي النبع المالح ماء عذبا.","3:13":"أبينكم بعض الحكماء والفهماء؟ إذن، على هؤلاء أن يسلكوا سلوكا حسنا، مظهرين بأعمالهم تلك الوداعة التي تتصف بها الحكمة (الحقيقية).","3:14":"أما إن كانت قلوبكم مملوءة بمرارة الحسد وبالتحزب، فلا تفتخروا بحكمتكم، ولا تنكروا الحق.","3:15":"إن هذه الحكمة التي تدعونها ليست نازلة من عند الله، بل هي «حكمة» أرضية بشرية شيطانية.","3:16":"فحيث تكون مرارة الحسد والتحزب، ينتشر الخلاف والفوضى وجميع الشرور.","3:17":"أما الحكمة النازلة من عند الله، فهي نقية طاهرة، قبل كل شيء. وهي أيضا تدفع صاحبها إلى المسالمة والترفق. كما أنها مطاوعة، مملوءة بالرحمة والأعمال الصالحة، مستقيمة: لا تميز ولا تنحاز ولا ترائي.","3:18":"والبر هو ثمر ة ما يزرعه في سلام صانعو السلام.","4:1":"من أين النزاع والخصام بينكم؟ أليس من لذاتكم تلك المتصارعة في أعضائكم؟","4:2":"فأنتم ترغبون في امتلاك ما لا يخصكم، لكن ذلك لا يتحقق لكم، فتقتلون، وتحسدون، ولا تتمكنون من بلوغ غايتكم. وهكذا تتخاصمون وتتصارعون! إنكم لا تمتلكون ما تريدونه، لأنكم لا تطلبونه من الله.","4:3":"وإذا طلبتم منه شيئا، فإنكم لا تحصلون عليه: لأنكم تطلبون بدافع شرير، إذ تنوون أن تستهلكوا ما تنالونه لإشباع شهواتكم فقط.","4:4":"أيها الخونة! ألستم تعلمون أن مصادقة العالم هي معاداة لله؟ فالذي يريد أن يصادق العالم، يجعل نفسه عدوا لله.","4:5":"أتظنون أن الكتاب يتكلم عبثا! هل الروح الذي حل في داخلنا يغار عن حسد؟","4:6":"لا، بل إنه يجود علينا بنعمة أعظم. لذلك يقول الكتاب: «إن الله يقاوم المتكبرين، ولكنه يعطي المتواضعين نعمة».","4:7":"إذن، كونوا خاضعين لله. وقاوموا إبليس فيهرب منكم.","4:8":"اقتربوا إلى الله فيقترب إليكم. أيها الخاطئون نظفوا أيديكم، وياأصحاب الرأيين طهروا قلوبكم.","4:9":"احزنوا مولولين ونائحين وباكين. ليتحول ضحككم إلى نواح، وفرحكم إلى كآبة.","4:10":"تواضعوا في حضرة الرب فيرفعكم!","4:11":"وياإخوتي، لا تذموا بعضكم بعضا. فمن يفعل هذا ويحكم على أخيه، يطعن في شريعة الله ويحكم عليها. فإن كنت تحكم على الشريعة، لا تكون عاملا بها بل تجعل نفسك قاضيا لها.","4:12":"وليس للشريعة إلا قاض واحد، هو الله واضعها، وهو وحده القادر أن يحكم بالخلاص أو بالهلاك. فمن تكون أنت لتحكم على الآخرين؟","4:13":"وأنتم، يامن تخططون قائلين: «اليوم أو غدا، نذهب إلى مدينة كذا، ونقضي هناك سنة، فنتاجر ونربح...»","4:14":"مهلا! فأنتم لا تعرفون ماذا يحدث غدا! وما هي حياتكم؟ إنها بخار، يظهر فترة قصيرة ثم يتلاشى!","4:15":"بدلا من ذلك، كان يجب أن تقولوا: «إن شاء الرب، نعيش ونعمل هذا الأمر أو ذاك!»","4:16":"وإلا، فإنكم تفتخرون متكبرين. وكل افتخار كهذا، هو افتخار رديء.","4:17":"فمن يعرف أن يعمل الصواب، ولا يعمله، فإن ذلك يحسب له خطيئة.","5:1":"أيها الأغنياء، هيا الآن ابكوا مولولين بسبب ما ينتظركم من أهوال وشقاء.","5:2":"إن ثرواتكم الكثيرة قد فسدت، وثيابكم الفاخرة قد أكلها العث","5:3":"ذهبكم وفضتكم قد تآكلا، وسيكون تآكلهما شاهدا ضدكم، ويأكل لحمكم كنار جمعتموها ثروة للأيام الأخيرة؟","5:4":"وهذه أجرة العمال الذين حصدوا حقولكم، تلك الأجرة التي مازلتم تحبسونها عنهم ظلما، إنها تصرخ، وصراخ أولئك العمال أنفسهم قد سمعه رب الجنود!","5:5":"أنتم تعيشون على الأرض عيشة رفاهية وانصراف إلى المباهج واللذات؛ وقد أصبحت قلوبكم سمينة كأنها جاهزة ليوم الذبح.","5:6":"والبريء حكمتم عليه وقتلتموه، وهو لا يقاومكم!","5:7":"وأما أنتم، ياإخوتي، فاصبروا منتظرين عودة الرب. خذوا العبرة من الفلاح: فهو ينتظر أن تعطيه الأرض غلالا ثمينة، صابرا على الزرع حتى يشرب من مطر الخريف ومطر الربيع.","5:8":"فاصبروا أنتم إذن، وشددوا قلوبكم لأن عودة الرب قد صارت قريبة.","5:9":"أيها الإخوة، لا تتذمروا بعضكم على بعض، لكي لا يصدر الحكم ضدكم. تذكروا دائما أن الديان قريب جدا، إنه أمام الباب.","5:10":"واقتدوا، ياإخوتي، في احتمال الآلام والصبر عليها، بالأنبياء الذين تكلموا باسم الرب.","5:11":"فنحن نقول عن الصابرين على الألم: «طوبى لهم!» وقد سمعتم بصبر أيوب، ورأيتم كيف عامله الرب في النهاية. وهذا يبين أن الرب كثير الرحمة والشفقة.","5:12":"ولكن قبل كل شيء، ياإخوتي، لا تحلفوا، لا بالسماء، ولا بالأرض ولا بأي قسم آخر. وإنما ليكن كلامكم «نعم» إن كان نعم، و«لا» إن كان لا. وذلك لكي لا تقعوا تحت الحكم.","5:13":"هل بينكم من يتألم؟ فليصل! وهل بينكم من هو سعيد؟ فليرتل!","5:14":"ومن كان منكم مريضا، فليستدع شيوخ الكنيسة ليصلوا من أجله ويدهنوه بزيت باسم الرب.","5:15":"فالصلاة المرفوعة باءيمان تشفي المريض، إذ يعيد الرب إليه الصحة. وإن كان مرضه بسبب خطيئة ما، يغفرها الرب له.","5:16":"ليعترف كل واحد منكم لأخيه بزلاته، وصلوا بعضكم لأجل بعض، حتى تشفوا. إن الصلاة الحارة التي يرفعها البار لها فعالية عظيمة.","5:17":"فقد كان إيليا بشرا مثلنا، وطلب من الله بالصلاة أن يحبس المطر. وهكذا كان، فلم تنزل على الأرض قطرة مطر لمدة ثلاث سنين وستة أشهر.","5:18":"ثم صلى صلاة ثانية، فأمطرت السماء وأنتجت الأرض ثمارها!","5:19":"أيها الإخوة، إن ضل أحد بينكم عن الحق، ورده آخر،","5:20":"فليتأكد أن الذي يرد خاطئا عن ضلال مسلكه، فإنما ينقذ نفسا من الموت، ويستر خطايا كثيرة!"},"1Pe":{"1:1":"من بطرس، رسول يسوع المسيح إلى المشتتين المغتربين في بلاد بنطس وغلاطية وكبدوكية وآسيا وبيثينية، أولئك الذين اختارهم الله الآب","1:2":"بحسب علمه السابق ثم قدسهم بالروح ليطيعوا يسوع المسيح ويطهروا برش دمه عليهم.","1:3":"تبارك الله أبو ربنا يسوع المسيح! فمن فرط رحمته العظيمة ولدنا ولادة ثانية، (معطيا إيانا حياة جديدة) مليئة بالرجاء على أساس قيامة يسوع المسيح من بين الأموات،","1:4":"وإرثا لا يفنى ولا يفسد ولا يزول،","1:5":"محفوظا لكم في السماوات. فإنكم محفوظون بقدرة الله العاملة من خلال إيمانكم، إلى أن تفوزوا بالخلاص النهائي المعد لكم والذي سوف يتجلى في الزمان الأخير.","1:6":"وهذا يدعوكم إلى الابتهاج، مع أنه لابد لكم الآن من الحزن فترة قصيرة تحت وطأة التجارب المتنوعة!","1:7":"إلا أن غاية هذه التجارب هي اختبار حقيقة إيمانكم. فكما تختبر النار الذهب وتنقيه، تختبر التجارب حقيقة إيمانكم، وهو أثمن جدا من الذهب الفاني. وهكذا، يكون إيمانكم مدعاة مدح وإكرام وتمجيد لكم، عندما يعود يسوع المسيح ظاهرا بمجده.","1:8":"أنتم لم تروا المسيح، ولكنكم تحبونه. ومع أنكم لا ترونه الآن، فأنتم تؤمنون به وتبتهجون بفرح مجيد يفوق الوصف.","1:9":"إذ بلغتم هدف إيمانكم، وهو خلاص نفوسكم.","1:10":"وكم فتش الأنبياء قديما وبحثوا عن هذا الخلاص! فهم تنبأوا عن نعمة الله التي كان قد أعدها لكم أنتم،","1:11":"واجتهدوا لمعرفة الزمان والأحوال التي كان يشير إليها روح المسيح الذي كان عاملا فيهم، عندما شهد لهم مسبقا بما ينتظر المسيح من آلام، وبما يأتي بعدها من أمجاد.","1:12":"ولكن الله أوحى إليهم أن اجتهادهم لم يكن لمصلحتهم هم، بل لمصلحتكم أنتم. فقد كان ذلك من أجل البشارة التي نقلها إليكم في الزمان الحاضر مبشرون يؤيدهم الروح القدس المرسل من السماء. ويالها من أمور يتمنى حتى الملائكة أن يطلعوا عليها!","1:13":"لذلك اجعلوا أذهانكم متنبهة دائما، وتيقظوا، وعلقوا رجاءكم كله على النعمة التي ستكون من نصيبكم عندما يعود يسوع المسيح ظاهرا بمجده!","1:14":"وبما أنكم صرتم أولادا لله مطيعين له، فلا تعودوا إلى مجاراة الشهوات التي كانت تسيطر عليكم سابقا في أيام جهلكم.","1:15":"وإنما اسلكوا سلوكا مقدسا في كل أمر، مقتدين بالقدوس الذي دعاكم،","1:16":"لأنه قد كتب: «كونوا قديسين، لأني أنا قدوس!»","1:17":"وما دمتم تعترفون بالله أبا لكم، وهو يحكم على كل إنسان حسب أعماله دون انحياز، فاسلكوا في مخافته مدة إقامتكم المؤقتة على الأرض.","1:18":"واعلموا أنه قد دفع الفدية ليحرركم من سيرة حياتكم الباطلة التي أخذتموها بالتقليد عن آبائكم. وهذه الفدية لم تكن شيئا فانيا كالفضة أو الذهب،","1:19":"بل كانت دما ثمينا، دم المسيح، ذلك الحمل الطاهر الذي ليس فيه عيب ولا دنس!","1:20":"ومع أن الله كان قد عين المسيح لهذا الغرض قبل تأسيس العالم، فهو لم يعلنه إلا في هذا الزمن الأخير لفائدتكم","1:21":"أنتم الذين تؤمنون بالله بالمسيح الذي أقامه من الموت وأعطاه المجد، حتى يكون الله غاية إيمانكم ورجائكم.","1:22":"وإذ قد خضعتم للحق، فتطهرت نفوسكم وصرتم قادرين أن تحبوا الآخرين محبة أخوية لا رياء فيها، أحبوا بعضكم بعضا محبة شديدة صادرة من قلب طاهر!","1:23":"فأنتم قد ولدتم ولادة ثانية لا من زرع بشري يفنى، بل مما لا يفنى: بكلمة الله الحية الباقية إلى الأبد.","1:24":"فإن الحياة البشرية كالعشب، ومجدها كله كزهر العشب. ولابد أن تفنى كما ييبس العشب ويسقط زهره!","1:25":"أما كلمة الرب فتبقى ثابتة إلى الأبد، وهي الكلمة التي وصلت بشارتها إليكم!","2:1":"لذلك، تخلصوا من كل أثر للشر والخداع والرياء والحسد والذم.","2:2":"وكأطفال مولودين حديثا، تشوقوا إلى اللبن الروحي النقي لكي تنموا به إلى أن تبلغوا الخلاص،","2:3":"إن كنتم حقا قد تذوقتم أن الرب طيب!","2:4":"فأنتم قد أتيتم إليه، باعتباره الحجر الحي الذي رفضه الناس، واختاره الله ، وهو ثمين في نظره.","2:5":"إذن اتحدوا به كحجارة حية، مبنيين بيتا روحيا، تكونون فيه كهنة مقدسين تقدمون لله ذبائح روحية مقبولة لديه بفضل يسوع المسيح.","2:6":"وكما يقول الكتاب: «ها أنا أضع في صهيون حجر زاوية، مختارا وثمينا. والذي يؤمن به، لا يخيب!»","2:7":"فإن هذا الحجر هو ثمين في نظركم، أنتم المؤمنين به. أما بالنسبة إلى الذين لا يؤمنون، «فالحجر الذي رفضه البناؤون صار هو الحجر الأساسي رأس زاوية البيت»،","2:8":"كما أنه هو «الحجر الذي يصطدمون به، والصخرة التي يسقطون عليها»! وهم يسقطون لأنهم يرفضون أن يؤمنوا بالكلمة.","2:9":"فإن سقوطهم أمر حتمي! وأما أنتم، فإنكم تشكلون جماعة كهنة ملوكية، وسلالة اختارها الله ، وأمة كرسها لنفسه، وشعبا امتلكه. وذلك لكي تخبروا بفضائل الرب، الذي دعاكم من الظلام إلى نوره العجيب!","2:10":"فإنكم في الماضي لم تكونوا شعبا؛ أما الآن، فأنتم «شعب الله وقد كنتم سابقا لا تتمتعون برحمة الله، أما الآن، فإنكم تتمتعون بها!»","2:11":"أيها الأحباء، ما أنتم إلا غرباء تزورون الأرض زيارة عابرة. لذلك أطلب إليكم أن تبتعدوا عن الشهوات الجسدية التي تصارع النفس.","2:12":"وليكن سلوككم بين الأمم سلوكا حسنا. فمع أنهم يتهمونكم زورا بأنكم تفعلون الشر، فحين يلاحظون أعمالكم الصالحة يمجدون الله في يوم الافتقاد.","2:13":"فإكراما للرب، اخضعوا لكل نظام يدير شؤون الناس: للملك، باعتباره صاحب السلطة العليا،","2:14":"وللحكام، باعتبارهم ممثلي الملك الذين يعاقبون المذنبين ويمدحون الصالحين.","2:15":"فإن هذه هي إرادة الله: أن تفعلوا الخير دائما، فتفحموا جهالة الناس الأغبياء!","2:16":"تصرفوا كأحرار حقا، لا كالذين يتخذون من الحرية ستارا لارتكاب الشر بل باعتبار أنكم عبيد لله.","2:17":"أكرموا جميع الناس. أحبوا الإخوة. خافوا الله . أكرموا الملك.","2:18":"أيها الخدم، اخضعوا لسادتكم باحترام لائق. ليس للسادة الصالحين المترفقين فقط، بل للظالمين القساة أيضا!","2:19":"فما أجمل أن يتحمل الإنسان الأحزان حين يتألم مظلوما، بدافع من ضميره الخاضع لله!","2:20":"فبالحقيقة، أي مجد لكم إن كنتم تصبرون وأنتم تتحملون قصاص أخطائكم؟ لا فضل لكم عند الله إلا إذا تحملتم الآلام صابرين، وأنتم تفعلون الصواب.","2:21":"لأن الله دعاكم إلى الاشتراك في هذا النوع من الآلام. فالمسيح، الذي تألم لأجلكم، هو القدوة التي تقتدون بها. فسيروا على آثار خطواته:","2:22":"إنه لم يفعل خطيئة واحدة، ولا كان في فمه مكر.","2:23":"ومع أنه أهين، فلم يكن يرد الإهانة. وإذ تحمل الآلام، لم يكن يهدد بالانتقام، بل أسلم أمره لله الذي يحكم بالعدل.","2:24":"وهو نفسه حمل خطايانا في جسده (عندما مات مصلوبا) على الخشبة، لكي نموت بالنسبة للخطايا فنحيا حياة البر. وبجراحه هو تم لكم الشفاء،","2:25":"فقد كنتم ضالين كخراف ضائعة، ولكنكم قد رجعتم الآن إلى راعي نفوسكم وحارسها!","3:1":"كذلك، أيتها الزوجات، اخضعن لأزواجكن. حتى وإن كان الزوج غير مؤمن بالكلمة، تجذبه زوجته إلى الإيمان، بتصرفها اللائق دون كلام،","3:2":"وذلك حين يلاحظ سلوكها الطاهر ووقارها.","3:3":"وعلى المرأة ألا تعتمد الزينة الخارجية لإظهار جمالها، بضفر الشعر والتحلي بالذهب ولبس الثياب الفاخرة.","3:4":"وإنما لتعتمد الزينة الداخلية، ليكون قلبها متزينا بروح الوداعة والهدوء. هذه هي الزينة التي لا تفنى، وهي غالية الثمن في نظر الله!","3:5":"وبها كانت تتزين النساء التقيات قديما، فكانت الواحدة منهن تتكل على الله وتخضع لزوجها.","3:6":"فسارة، مثلا، كانت تطيع زوجها إبراهيم وتدعوه «سيدي». والمؤمنات اللواتي يقتدين بها، يثبتن أنهن بنات لها، إذ يتصرفن تصرفا صالحا، فلا يخفن أي تهديد.","3:7":"وأنتم، أيها الأزواج، إذ تساكنون زوجاتكم عالمين بأنهن أضعف منكم، أكرموهن باعتبارهن شريكات لكم في وراثة نعمة الحياة، لكي لا يعوق صلواتكم شيء.","3:8":"والخلاصة، كونوا جميعا متحدين في الرأي، متعاطفين بعضكم مع بعض، مبادلين أحدكم الآخر المحبة الأخوية، شفوقين، متواضعين.","3:9":"لا تبادلوا الشر بشر، ولا الشتيمة بشتيمة. بل بالعكس: باركوا، فترثوا البركة، لأنه لهذا دعاكم الله .","3:10":"فمن أراد أن يتمتع بحياة سعيدة وأيام طيبة، فليمنع لسانه عن الشر وشفتيه عن كلام الغش.","3:11":"ليتحول عن الشر ويفعل الخير. ليطلب السلام ويسع للوصول إليه.","3:12":"لأن الرب يرعى الأبرار بعنايته، ويستجيب إلى دعائهم. ولكنه يقف ضد الذين يعملون الشر…","3:13":"من يؤذيكم إن كنتم متحمسين للخير؟","3:14":"وإن كان لابد أن تتألموا في سبيل البر، فطوبى لكم! لا تخافوا من تهديد الذين يضطهدونكم، ولا تقلقوا.","3:15":"وإنما كرسوا المسيح ربا في قلوبكم. وكونوا دائما مستعدين لأن تقدموا جوابا مقنعا لكل من يسألكم عن سبب الرجاء الذي في داخلكم","3:16":"على أن تفعلوا ذلك بوداعة واحترام، محافظين على طهارة ضمائركم، سالكين في المسيح سلوكا صالحا، وعندئذ يخيب الذين يوجهون إليكم التهم الكاذبة ويشتمونكم كأنكم تفعلون شرا.","3:17":"فإن كان الله يريد لكم أن تتألموا، فمن الأفضل أن تتألموا وأنتم تفعلون الخير لا الشر.","3:18":"فإن المسيح نفسه مات مرة واحدة لكي يحل مشكلة الخطايا. فمع أنه هو البار، فقد تألم من أجلنا نحن المذنبين، لكي يقربنا إلى الله، فمات بجسمه البشري، ثم عاد حيا بالروح.","3:19":"بهذا الروح نفسه، ذهب قديما وبشر الناس الذين أصبحت أرواحهم الآن في السجن.","3:20":"وذلك بعدما رفضوا البشارة في أيام نوح، عندما كان الله يتأنى صابرا طوال المدة التي كان نوح يبني فيها السفينة، التي نجا بها عدد قليل من الناس عبر الماء، ثمانية أشخاص فقط!","3:21":"وعملية النجاة هذه مصورة في المعمودية التي لا نقصد بها أن نغتسل من أوساخ أجسامنا، بل هي تعهد ضمير صالح أمام الله بفضل قيامة يسوع المسيح،","3:22":"الذي انطلق إلى السماء، وهو الآن جالس عن يمين الله؛ وقد جعلت الملائكة والسلطات والقوات (الروحية) خاضعة له!","4:1":"فبما أن المسيح قد تحمل الآلام الجسمية لأجلكم، سلحوا أنفسكم بالاستعداد دائما لتحمل الآلام. فإن من يتحمل الآلام الجسمية، يكون قد قاطع الخطيئة.","4:2":"وغايته أن يعيش بقية عمره في الجسد، منقادا لا لشهوات الناس، بل لإرادة الله.","4:3":"كفاكم ذلك الزمان الماضي من حياتكم، لتكونوا قد سلكتم سلوك الوثنيين، حين كنتم تعيشون في الدعارة والشهوات وإدمان الخمر، وحفلات السكر والعربدة، وعبادة الأصنام المحرمة.","4:4":"ورفاقكم في تلك العيشة سابقا يستغربون أنكم لا تركضون معهم إلى فيض هذه الخلاعة، ويجرحون سمعتكم.","4:5":"لكنهم سوف يؤدون الحساب أمام المسيح، المستعد أن يدين الأحياء والأموات.","4:6":"ولهذا أبلغت البشارة إلى الأموات أيضا لكي يكونوا دائما أحياء بالروح في نظر الله، مع أن حكم الموت قد نفذ بأجسادهم، فماتوا كغيرهم من الناس.","4:7":"إن نهاية كل شيء قد صارت قريبة. فتعقلوا إذن، وكونوا متنبهين لرفع الصلاة دائما.","4:8":"لكن أهم شيء هو أن تبادلوا بعضكم بعضا المحبة الشديدة. لأن المحبة تستر إساءات كثيرة.","4:9":"ومارسوا الضيافة بعضكم نحو بعض بلا تذمر.","4:10":"وعلى كل واحد منكم أن يخدم الآخرين بالموهبة التي أعطاه الله إياها، باعتباركم وكلاء صالحين مؤتمنين على أنواع متعددة من المواهب التي يمنحها الله بالنعمة.","4:11":"فمن يتكلم، عليه أن يتكلم بما يوافق أقوال الله؛ ومن يخدم، عليه أن يخدم بموجب القوة التي يمنحها الله . وذلك لكي يتمجد الله في كل شيء، بيسوع المسيح، له المجد والسلطة إلى أبد الآبدين. آمين!","4:12":"أيها الأحباء، لا تستغربوا نار الاضطهاد المشتعلة عندكم لاختباركم وكأن أمرا غريبا قد أصابكم!","4:13":"وإنما افرحوا: لأنكم كما تشاركون المسيح في الآلام الآن، لابد أن تفرحوا بمشاركته في الابتهاج عند ظهور مجده.","4:14":"فإذا لحقتكم الإهانة لأنكم تحملون اسم المسيح، فطوبى لكم! لأن روح المجد، أي روح الله، يستقر عليكم.","4:15":"لا يكن بينكم من يتأ لم عقابا على شر ارتكبه: كالقتل أو السرقة، أو غيرهما من الجرائم، أو التدخل في شؤون الآخرين.","4:16":"ولكن إن تألم أحدكم لأنه «مسيحي»، فعليه ألا يخجل، بل أن يمجد الله لأجل هذا الاسم!","4:17":"حقا إن الوقت قد حان ليبتديء القضاء بأهل بيت الله. فإن كان القضاء يبدأ بنا أولا، فما هو مصير الذين لا يؤمنون بإنجيل الله؟","4:18":"وإن كان البار يخلص بجهد، فماذا يحدث للشرير والخاطيء؟","4:19":"إذن، على الذين يتألمون وفقا لإرادة الله، أن يسلموا أنفسهم للخالق الأمين، ويواظبوا على عمل الصلاح!","5:1":"وهذه وصيتي إلى الشيوخ الذين بينكم، بصفتي شيخا رفيقا لهم، وشاهدا لآلام المسيح، وشريكا في المجد الذي سيتجلى:","5:2":"ارعوا قطيع الله الذي بينكم، كحراس له، لا بدافع الواجب، بل بدافع التطوع، كما يريد الله ، ولا رغبة في الربح الدنيء، بل رغبة في الخدمة بنشاط.","5:3":"لا تتسلطوا على القطيع الذي وضعه الله أمانة بين أيديكم، بل كونوا قدوة له.","5:4":"وعندما يظهر رئيس الرعاة، تنالون إكليل المجد الذي لا يفنى.","5:5":"كذلك، أيها الشباب، اخضعوا للشيوخ. البسوا جميعا ثوب التواضع في معاملتكم بعضكم لبعض. لأن الله يقاوم المتكبرين، ولكنه يعطي المتواضعين نعمة.","5:6":"إذن، تواضعوا تحت يد الله القديرة لكي يرفعكم عندما يحين الوقت،","5:7":"واطرحوا عليه ثقل همومكم كلها، لأنه هو يعتني بكم.","5:8":"تعقلوا وتنبهوا. إن خصمكم إبليس كأسد يزأر، يجول باحثا عن فريسة يبتلعها.","5:9":"فقاوموه، ثابتين في الإيمان. واذكروا أن إخوتكم المنتشرين في العالم يجتازون وسط هذه الآلام عينها.","5:10":"وبعد أن تتألموا لفترة قصيرة، فإن الله ، إله كل نعمة، الذي دعاكم إلى الاشتراك في مجده الأبدي في المسيح، لابد أن يجعلكم كاملين وثابتين ومؤيدين بالقوة وراسخين.","5:11":"له المجد والسلطة إلى أبد الآبدين. آمين!","5:12":"إني مرسل إليكم هذه الرسالة القصيرة بيد سلوانس الأخ الأمين. وغايتي أن أحرضكم وأشهد لكم أن النعمة التي تتمتعون بها هي نعمة الله الحقيقية التي أنتم فيها ثابتون.","5:13":"ومن بابل، تسلم عليكم تلك التي اختارها الله معكم، وكذلك مرقس ابني.","5:14":"سلموا بعضكم على بعض بقبلة المحبة."},"2Pe":{"1:1":"من سمعان بطرس، عبد يسوع المسيح ورسوله، إلى الذين يشاركوننا في الإيمان الواحد الثمين الذي نتساوى جميعا في الحصول عليه ببر إلهنا ومخلصنا يسوع المسيح!","1:2":"ليكن لكم المزيد من النعمة والسلام بفضل معرفة الله ويسوع ربنا!","1:3":"إن الله، بقدرته الإلهية، قد زودنا بكل ما نحتاج إليه في الحيا ة الروحية المتصفة بالتقوى. ذلك أنه عرفنا بالمسيح الذي دعانا إلى مجده وفضيلته،","1:4":"اللذين بهما أعطانا الله بركاته العظمى الثمينة التي كان قد وعد بها. وبهذا صار بإمكانكم أن تتخلصوا من الفساد الذي تنشره الشهوة في العالم، وتشتركوا في الطبيعة الإلهية.","1:5":"فمن أجل ذلك، عليكم أن تبذلوا كل اجتهاد ونشاط في ممارسة إيمانكم حتى يؤدي بكم إلى الفضيلة. واقرنوا الفضيلة بالتقدم في المعرفة،","1:6":"والمعرفة بضبط النفس، وضبط النفس بالصبر، والصبر بالتقوى،","1:7":"والتقوى بالمودة الأخوية، والمودة الأخوية بالمحبة.","1:8":"فحين تكون هذه الصفات الطيبة في داخلكم، وتزداد بوفرة، تجعلكم مجتهدين ومثمرين في معرفتكم لربنا يسوع المسيح.","1:9":"أما الذي لا يملك هذه الصفات، فهو أعمى روحيا. إنه قصير البصر، قد نسي أنه تطهر من خطاياه القديمة!","1:10":"فأحرى بكم إذن، أيها الإخوة، أن تجتهدوا لتثبتوا عمليا أن الله قد دعاكم واختاركم حقا. فإنكم، إن فعلتم هذا، لن تسقطوا أبدا!","1:11":"وهكذا يفتح الله لكم الباب واسعا للدخول إلى الملكوت الأبدي، ملكوت ربنا ومخلصنا يسوع المسيح.","1:12":"لذلك أنوي أن أذكركم دائما بهذه الأمور، وإن كنتم عالمين بها، وراسخين في الحق الذي عندكم.","1:13":"فمادمت في خيمة جسمي هذه، أرى من واجبي أن أنبهكم مذكرا.","1:14":"فأنا أعلم أن خيمتي ستطوى بعد وقت قصير، كما سبق أن أعلن لي ربنا يسوع المسيح.","1:15":"ولهذا، أجتهد الآن في تذكيركم بهذه الأمور، حتى تستطيعوا أن تتذكروها دائما بعد رحيلي.","1:16":"فنحن، عندما أخبرناكم بقدرة ربنا يسوع المسيح، وبعودته المجيدة، لم نكن ننقل عن أساطير مختلقة بمهارة. وإنما، تكلمنا باعتبارنا شهود عيان لعظمة المسيح.","1:17":"فإنه قد نال من الله الآب كرامة ومجدا، إذ جاءه من المجد الفائق صوت يقول: «هذا هو ابني الحبيب الذي به سررت كل سرور!»","1:18":"ونحن أنفسنا قد سمعنا هذا الصوت الصادر من السماء لما كنا معه على الجبل المقدس.","1:19":"وهكذا، صارت الكلمة النبوية أكثر ثباتا عندنا. فحسنا تفعلون إن انتبهتم إلى هذه الكلمة في قلوبكم. إذ إنها أشبه بمصباح يضيء في مكان مظلم، إلى أن يطلع النهار ويظهر كوكب الصبح.","1:20":"ولكن، قبل كل شيء، اعلموا أن كل نبوءة واردة في الكتاب لا تفسر باجتهاد خاص.","1:21":"إذ لم تأت نبوءة قط بإرادة بشرية، بل تكلم بالنبوآت جميعا رجال الله غالقديسونف مدفوعين بوحي الروح القدس.","2:1":"ولكن، كما كان في الشعب قديما أنبياء دجالون، كذلك سيكون بينكم أنتم أيضا معلمون دجالون. هؤلاء سيدسون بدعا مهلكة، وينكرون السيد الذي اشتراهم لنفسه. وبذلك يجلبون على أنفسهم دمارا سريعا.","2:2":"وكثيرون سيسيرون وراءهم في طرق الإباحية. وبسببهم توجه الإهانة إلى طريق الحق.","2:3":"وبدافع الطمع، يتاجرون بكم بالأقوال المحرفة المزخرفة.","2:4":"فإن الله لم يشفق على الملائكة الذين أخطأوا، بل طرحهم في أعماق هاوية الظلام مقيدين بالسلاسل، حيث يظلون محبوسين إلى يوم الحساب.","2:5":"كذلك لم يشفق على العالم القديم عندما أحدث الطوفان على عالم الفاجرين، إلا أنه حفظ نوحا المنادي ببر الله وعدله. وكان نوح واحدا من ثمانية أشخاص نجوا من الطوفان.","2:6":"وإذ حكم الله على مدينتي سدوم وعمورة بالخراب، حولهما إلى رماد، جاعلا منهما عبرة للذين يعيشون حياة فاجرة.","2:7":"ولكنه أنقذ لوطا البار، الذي كان متضايقا جدا من سلوك أشرار زمانه في الدعارة.","2:8":"فإذ كان ساكنا بينهم، وهو رجل بار، كانت نفسه الزكية تتألم يوميا من جرائمهم التي كان يراها أو يسمع بها.","2:9":"وهكذا نرى أن الرب يعرف أن ينقذ الأتقياء من المحنة، ويحفظ الأشرار محبوسين ليحكم عليهم بالعقاب في يوم الدينونة.","2:10":"وما أشد العقاب، وبخاصة على الذين ينجرفون وراء الميول الجسدية، مستجيبين لشهوة النجاسة، ومحتقرين سيادة الله! ثم إنهم وقحون، معجبون بأنفسهم، لا يخافون أن يتكلموا بالشتم والإهانة على أصحاب الأمجاد.","2:11":"ومع ذلك، فحتى الملائكة، وهم يتفوقون عليهم في القوة والقدرة، لا يقدمون عليهم أمام الرب أية تهمة مهينة..","2:12":"حقا إن هؤلاء المعلمين الدجالين الذين يتكلمون كلاما مهينا في أمور يجهلونها، يشبهون الحيوانات المفترسة غير العاقلة، المولودة ليصطادها الناس ويقتلوها. فلابد أن يهلكوا مثلها.","2:13":"وبذلك ينالون أجرة إثمهم! إنهم يحسبون الانغماس في اللذات طول النهار بهجة عظيمة. فهم أوساخ وعيوب: يتلذذون بالنجاسة ويحاولون خداعكم، فيشتركون معكم في الولائم.","2:14":"عيونهم لا تنظر إلا نظرات الزنى، ولا تشبع من الخطيئة. وكم من نفوس ضعيفة تقع في فخاخهم! أما قلوبهم، فقد تدربت على الشهوة والطمع. إنهم حقا أبناء اللعنة!","2:15":"وإذ خرجوا عن الطريق المستقيم، ضلوا. فهم سائرون في طريق بلعام بن بعور، الذي أحب الحصول على المال أجرة لإثمه.","2:16":"ولكنه توبخ على هذه المخالفة التي ارتكبها. إذ إن الحمار الأبكم نطق بصوت بشري، فوضع حدا لحماقة ذلك النبي!","2:17":"فليس هؤلاء إلا آبارا لا ماء فيها، وغيوما تسوقها الريح العاصفة. ويا له من مصير مرعب محجوز لهم في الظلام الأبدي القاتم!","2:18":"ينطقون بأقوال طنانة فارغة، مشجعين على الانغماس في الشهوات الجسدية بممارسة الدعارة، فيصطادون من كانوا قد بدأوا ينفصلون عن رفاق السوء الذين يسلكون في الضلال.","2:19":"يعدون هؤلاء بالحرية، وهم أنفسهم عبيد للفساد! لأن الإنسان يصير عبدا لكل ما يتسلط عليه ويغلبه.","2:20":"فإن الذين يبتعدون عن نجاسات العالم بعد أن يتعرفوا بالرب والمخلص يسوع المسيح، ثم يعودون ويتورطون بها، تتسلط عليهم تلك النجاسات، فتصير نهايتهم أشر من بدايتهم.","2:21":"وبالحقيقة، كان أفضل لهم لو أنهم لم يتعرفوا بطريق البر، من أن يتعرفوا به ثم يرتدوا عن الوصية المقدسة التي تسلموها.","2:22":"وينطبق على هؤلاء ما يقوله المثل الصادق: «عاد الكلب إلى تناول ما تقيأه، والخنزيرة المغتسلة إلى التمرغ في الوحل!»","3:1":"أيها الأحباء، أنا الآن أكتب إليكم رسالتي الثانية. وفي كلتا الرسالتين، أقصد أن أنبه أذهانكم الصافية، مذكرا إياكم بحقائق تعرفونها.","3:2":"وغايتي أن تتذكروا الأقوال التي أعلنها الأنبيا ء القديسون قديما، وكذلك وصية الرب والمخلص، تلك الوصية التي نقلها إليكم الرسل.","3:3":"فاعلموا، قبل كل شيء أنه سيأتي في آخر الأيام أناس مستهزئون يسخرون بالحق، ويسلكون منجرفين وراء شهواتهم الخاصة.","3:4":"وسيقولون: «أين هو الوعد برجوع المسيح؟ فمنذ أن مات آباؤنا الأولون، بل منذ بدء الخليقة، مازال كل شيء على حاله!»","3:5":"إنهم يتناسون، عمدا، أنه بكلمة أمر من الله وجدت السماوات منذ القديم وتكونت الأرض من الماء وبالماء.","3:6":"وبكلمة منه أيضا، دمر العالم الذي كان موجودا في ذلك الزمان، إذ فاض الماء عليه.","3:7":"أما السماوات والأرض الحالية، فستبقى مخزونة ومحفوظة للنار بتلك الكلمة عينها إلى يوم الدينونة وهلاك الفاجرين!","3:8":"ولكن، أيها الأحباء، عليكم ألا تنسوا هذه الحقيقة: أن يوما واحدا في نظر الرب هو كألف سنة، وألف سنة كيوم واحد.","3:9":"فالرب، إذن، لا يبطيء في إتمام وعده، كما يظن بعض الناس، ولكنه يتأنى عليكم، فهو لا يريد لأحد من الناس أن يهلك، بل يريد لجميع الناس أن يرجعوا إليه تائبين.","3:10":"إلا أن «يوم الرب» سيأتي كما يأتي اللص في الليل. في ذلك اليوم، تزول السماوات محدثة دويا هائلا وتنحل العناصر محترقة بنار شديدة، وتحترق الأرض وما فيها من منجزات.","3:11":"ومادامت هذه الأشياء جميعا ستنحل، فكيف يجب أن تكونوا أنتم أصحاب سلوك مقدس يتصف بالتقوى،","3:12":"منتظرين «يوم الله» الأبدي وطالبين حلوله بسرعة. ففي ذلك اليوم، تنحل السماوات ملتهبة، وتذوب العناصر محترقة.","3:13":"إلا أننا، وفقا لوعد الرب، ننتظر سماوات جديدة وأرضا جديدة، حيث يسكن البر.","3:14":"فبينما تنتظرون إتمام هذا الوعد، أيها الأحباء، اجتهدوا أن يجدكم الرب في سلام، خالين من الدنس والعيب.","3:15":"وتأكدوا أن تأني ربنا في رجوعه، هو فرصة للخلاص.","3:16":"وما كتبه في رسالته إليكم، يوافق ما كتبه في باقي رسائله. وفي تلك الرسائل كلها أمور صعبة الفهم، يحرفها الجهال وغير الراسخين في الحق، كما يحرفون غيرها أيضا من الكتابات الموحى بها، فيجلبون الهلاك على أنفسهم.","3:17":"أما أنتم أيها الأحباء، فإذ قد تنبهتم إلى الخطر قبل حدوثه، احذروا أن تسقطوا عن ثباتكم بالانجراف وراء ضلال الأشرار.","3:18":"ولكن، ازدادوا نموا في النعمة وفي معرفة ربنا ومخلصنا يسوع المسيح. له المجد، الآن وإلى اليوم الأبدي."},"1Jo":{"1:1":"نكتب إليكم عما كان من البداية بخصوص كلمة الحياة: عما سمعناه، ورأيناه بعيوننا، وشاهدناه، ولمسناه بأيدينا.","1:2":"فإن «الحياة» تجلت أمامنا. وبعدما رأيناها فعلا، نشهد لها الآن. وها نحن ننقل إليكم خبر هذه الحياة الأبدية التي كانت عند الآب ثم تجلت أمامنا!","1:3":"فنحن، إذن، نخبركم بما رأيناه وسمعناه، لكي تكونوا شركاءنا. كما أن شركتنا هي مع الآب ومع ابنه يسوع المسيح.","1:4":"ونكتب إليكم هذه الأمور لكي يكتمل فرحكم!","1:5":"وهذا هو الخبر الذي سمعناه من المسيح ونعلنه لكم: إن الله نور، وليس فيه ظلام البتة.","1:6":"فإن كنا ندعي أن لنا شركة معه، ونحن نعيش في الظلام، نكون كاذبين ولا نمارس الحق.","1:7":"ولكن، إن كنا فعلا نعيش في النور، كما هو في النور، تكون لنا حقا شركة بعضنا مع بعض، ودم ابنه يسوع يطهرنا من كل خطيئة.","1:8":"إن كنا ندعي أن لا خطيئة لنا، نخدع أنفسنا، ولا يكون الحق في داخلنا.","1:9":"ولكن، إن اعترفنا لله بخطايانا، فهو جدير بالثقة وعادل، يغفر لنا خطايانا ويطهرنا من كل إثم.","1:10":"فإن كنا ندعي أننا لم نرتكب خطيئة، نجعل الله كاذبا، ولا تكون كلمته في داخلنا!","2:1":"ياأولادي الصغار، أكتب إليكم هذه الأمور لكي لا تخطئوا. ولكن، إن أخطأ أحدكم، فلنا عند الآب شفيع هو يسوع المسيح البار.","2:2":"فهو كفارة لخطايانا، لا لخطايانا فقط، بل لخطايا العالم كله.","2:3":"وما يؤكد لنا أننا قد عرفنا المسيح حقا هو أن نعمل بوصاياه.","2:4":"فالذي يدعي أنه قد عرفه، ولكنه لا يعمل بوصاياه، يكون كاذبا ولا يكون الحق في داخله.","2:5":"أما الذي يعمل بحسب كلمة المسيح، فإن محبة الله تكون قد اكتملت في داخله. بهذا نعرف أننا ننتمي إلى المسيحِ.","2:6":"كل من يعترف أنه ثابت في المسيح، يلتزم أن يسلك كما سلك المسيح!","2:7":"أيها الأحباء، أنا لا أكتب إليكم هنا وصية جديدة، بل وصية قديمة كانت عندكم منذ البداية، وهي الكلمة التي سمعتموها قبلا.","2:8":"ومع ذلك فالوصية التي أكتبها إليكم، هي جديدة دائما، وتتضح حقيقتها في المسيح كما تتضح فيكم أنتم. ذلك لأن الظلام قد بدأ يزول منذ أن أشرق النور الحقيقي الذي مازال الآن مشرقا.","2:9":"من ادعى أنه يحيا في النور، ولكنه يبغض أحد إخوته، فهو مازال حتى الآن في الظلام.","2:10":"فالذي يحب إخوته، هو الذي يحيا في النور فعلا ولا شيء يسقطه.","2:11":"أما الذي يبغض أحد إخوته، فهو تائه في الظلام، يتلمس طريقه ولا يعرف أين يتجه، لأن الظلام قد أعمى عينيه!","2:12":"أكتب إليكم، أيها الأولاد، لأن الله قد غفر لكم خطاياكم إكراما لاسم المسيح.","2:13":"أكتب إليكم أيها الآباء، لأنكم قد عرفتم المسيح الكائن منذ البداية. أكتب إليكم أيها الشباب، لأنكم قد غلبتم إبليس الشرير. كتبت إليكم أيها الأولاد الصغار، لأنكم قد عرفتم الآب.","2:14":"كتبت إليكم، أيها الآباء، لأنكم قد عرفتم المسيح الكائن منذ البداية. كتبت إليكم، أيها الشباب، لأنكم أقوياء، وقد ترسخت كلمة الله في قلوبكم، وغلبتم إبليس الشرير.","2:15":"لا تحبوا العالم، ولا الأشياء التي في العالم. فالذي يحب العالم، لا تكون محبة الآب في قلبه.","2:16":"لأن كل ما في العالم، من شهوات الجسد وشهوات العين وترف المعيشة، ليس من الآب، بل من العالم.","2:17":"وسوف يزول العالم، وما فيه من شهوات أما الذي يعمل بإرادة الله، فيبقى إلى الأبد!","2:18":"أيها الأولاد، اعلموا أننا نعيش الآن في الزمن الأخير. وكما سمعتم أنه سوف يأتي أخيرا «مسيح دجال»، فقد ظهر حتى الآن كثيرون من الدجالين المقاومين للمسيح. من هنا نتأكد أننا نعيش في الزمن الأخير.","2:19":"هؤلاء الدجالون انفصلوا عنا، لكنهم في الواقع لم يكونوا منا. ولو كانوا منا لظلوا معنا. فانفصالهم عنا إذن برهان على أنهم جميعا ليسوا منا.","2:20":"أما أنتم فلكم مسحة من القدوس، وجميعكم تعرفون الحق.","2:21":"فأنا أكتب إليكم ليس لأنكم لا تعرفون الحق، بل لأنكم تعرفونه وتدركون أن كل ما هو كذب لا يأتي من الحق.","2:22":"ومن هو الكذاب؟ إنه الذي ينكر أن يسوع هو المسيح حقا. إنه ضد للمسيح ينكر الآب والابن معا.","2:23":"وكل من ينكر الابن، لا يكون الآب أيضا من نصيبه. ومن يعترف بالابن، فله الآب أيضا.","2:24":"أما أنتم، فالكلام الذي سمعتموه منذ البداية، فليكن راسخا فيكم. فحين يترسخ ذلك الكلام في داخلكم، تتوطد صلتكم بالابن، وبالآب.","2:25":"فإن الله نفسه قد وعدنا بالحياة الأبدية.","2:26":"كتبت إليكم هذا مشيرا إلى الذين يحاولون أن يضللوكم.","2:27":"أما أنتم فقد نلتم من الله مسحة تبقى فيكم دائما. ولذلك، لستم بحاجة إلى من يعلمكم الحق. فتلك المسحة عينها هي التي تعلمكم كل شيء. وهي حق وليست كذبا. فكما علمتكم اثبتوا في المسيح.","2:28":"والآن، أيها الأولاد، كونوا ثابتين في المسيح، حتى تكون لنا نحن ثقة أمامه، ولا نخجل منه، عندما يعود.","2:29":"وما دمتم تعلمون أن الله بار، فاعلموا أن كل من يفعل الصلاح، يظهر أنه مولود من الله حقا.","3:1":"تأملوا ما أعظم المحبة التي أحبنا بها الآب حتى صرنا ندعى «أولاد الله»، ونحن أولاده حقا. ولكن، بما أن أهل العالم لا يعرفون الله، فهم لا يعرفوننا.","3:2":"أيها الأحباء، نحن الآن أولاد الله. ولا نعلم حتى الآن ماذا سنكون، لكننا نعلم أنه متى أظهر المسيح، سنكون مثله، لأننا سنراه عندئذ كما هو!","3:3":"وكل من عنده هذا الرجاء بالمسيح، يطهر نفسه كما أن المسيح طاهر.","3:4":"أما الذي يمارس الخطيئة، فهو يخالف ناموس الله: لأن الخطيئة هي مخالفة الناموس.","3:5":"وأنتم تعرفون أن المسيح جاء إلى هذه الأرض لكي يحمل الخطايا، مع كونه بلا خطيئة.","3:6":"فكل من يثبت فيه، لا يمارس الخطيئة. أما الذين يمارسون الخطيئة، فهم لم يروه ولم يتعرفوا به قط.","3:7":"أيها الأولاد الصغار، لا تدعوا أحدا يضللكم. تأكدوا أن من يمارس الصلاح، يظهر أنه بار كما أن المسيح بار.","3:8":"ولكن من يمارس الخطيئة، يظهر أنه من أولاد إبليس، لأن إبليس يمارس الخطيئة منذ البداية. وقد جاء ابن الله إلى الأرض لكي يبطل أعمال إبليس.","3:9":"فكل مولود من الله، لا يمارس الخطيئة، لأن طبيعة الله صارت ثابتة فيه. بل إنه لا يستطيع أن يمارس الخطيئة، لأنه مولود من الله.","3:10":"إذن، هذا هو المقياس الذي نميز به بين أولاد الله وأولاد إبليس. من لا يمارس الصلاح، فهو ليس من الله. وكذلك من لا يحب أخاه!","3:11":"فالوصية التي سمعتموها منذ البداية، هي أن يحب بعضنا بعضا،","3:12":"لا أن نكون مثل قايين الذي قتل أخاه. فقايين كان من أولاد إبليس الشرير. ولماذا قتل أخاه؟ قتله لأن أعماله هو كانت شريرة، أما أعمال أخيه فكانت صالحة.","3:13":"إذن، ياإخوتي، لا تتعجبوا إن كان أهل العالم يبغضونكم!","3:14":"إن محبتنا لإخوتنا تبين لنا أننا انتقلنا من الموت إلى الحياة. فالذي لا يحب إخوته، فهو باق في الموت.","3:15":"وكل من يبغض أخا له، فهو قاتل. وأنتم تعرفون أن القاتل لا تكون له حياة أبدية ثابتة فيه.","3:16":"ومقياس المحبة هو العمل الذي قام به المسيح إذ بذل حياته لأجلنا. فعلينا نحن أيضا أن نبذل حياتنا لأجل إخوتنا.","3:17":"وأما الذي يملك مالا يمكنه من العيش في بحبوحة، ويقسي قلبه على أحد الإخوة المحتاجين، فكيف تكون محبة الله متأصلة فيه؟","3:18":"أيها الأولاد الصغار، لا يجب أن تكون محبتنا مجرد ادعاء بالكلام واللسان، بل تكون محبة عملية حقة.","3:19":"عندئذ نتأكد أننا نتصرف بحسب الحق، وتطمئن نفوسنا في حضرة الله،","3:20":"ولو لامتنا قلوبنا؛ فإن الله أعظم من قلوبنا، وهو العليم بكل شيء.","3:21":"أيها الأحباء، إذا كانت ضمائرنا لا تلومنا. فهذا دليل على أن لنا ثقة عظيمة من نحو الله.","3:22":"ومهما نطلب منه بالصلاة، نحصل عليه: لأننا نطيع ما يوصينا به، ونمارس الأعمال التي ترضيه.","3:23":"وأما وصيته فهي أن نؤمن باسم ابنه يسوع المسيح، وأن يحب بعضنا بعضا كما أوصانا.","3:24":"وكل من يطيع وصايا الله، فإنه يثبت في الله، والله يثبت فيه. والذي يؤكد لنا أن الله يثبت فينا، هو الروح القدس الذي وهبه لنا.","4:1":"أيها الأحباء، لا تصدقوا كل روح، بل امتحنوا الأرواح لتعرفوا ما إذا كانت من عند الله أم لا، لأن عددا كبيرا من الأنبياء الدجالين قد انتشر في العالم.","4:2":"وهذه هي الطريقة التي تعرفون بها كون الروح من عند الله فعلا: إذا كان ذلك الروح يعترف بأن يسوع المسيح قد جاء إلى الأرض في الجسد، فهو من عند الله.","4:3":"وإن كان ينكر ذلك لا يكون من عند الله، بل من عند ضد المسيح الذي سمعتم أنه سوف يأتي، وهو الآن موجود في العالم.","4:4":"أيها الأولاد الصغار، أنتم من الله، وقد غلبتم الذين يقاومون المسيح: لأن الروح القدس الساكن فيكم أقوى من الروح الشرير المنتشر في العالم.","4:5":"هؤلاء المقاومون هم من العالم، ولذلك يستمدون كلامهم من العالم، فيصغي أهل العالم إليهم.","4:6":"أما نحن، فإننا من الله، ولذلك يصغي إلينا فقط من يعرف الله . أما الذي ليس من الله، فلا يصغي إلينا. وبهذا، نميز بين روح الحق وروح الضلال.","4:7":"أيها الأحباء، لنحب بعضنا بعضا: لأن المحبة تصدر من الله. إذن، كل من يحب، يكون مولودا من الله ويعرف الله .","4:8":"أما من لا يحب، فهو لم يتعرف بالله قط لأن الله محبة!","4:9":"وقد أظهر الله محبته لنا إذ أرسل ابنه الأوحد إلى العالم لكي نحيا به.","4:10":"وفي هذا نرى المحبة الحقيقية، لا محبتنا نحن لله، بل محبته هو لنا. فبدافع محبته، أرسل ابنه كفارة لخطايانا.","4:11":"ومادام الله قد أحبنا هذه المحبة العظيمة، أيها الأحباء، فعلينا نحن أيضا أن نحب بعضنا بعضا.","4:12":"إن الله لم يره أحد من الناس قط. ولكن، حين نحب بعضنا بعضا، نبين أن الله يحيا في داخلنا، وأن محبته قد اكتملت في داخلنا.","4:13":"وما يؤكد لنا أننا نثبت في الله، وأنه يثبت فينا هو أنه وهب لنا من روحه.","4:14":"ونحن أنفسنا نشهد أن الآب قد أرسل الابن مخلصا للعالم، لأننا رأيناه بعيوننا.","4:15":"من يعترف بأن يسوع هو ابن الله، فإن الله يثبت فيه، وهو يثبت في الله،","4:16":"ونحن أنفسنا اختبرنا المحبة التي خصنا الله بها، ووضعنا ثقتنا فيها. إن الله محبة. ومن يثبت في المحبة، فإنه يثبت في الله، والله يثبت فيه.","4:17":"وتكون محبة الله قد اكتملت في داخلنا حين تولد فينا ثقة كاملة من جهة يوم الدينونة: لأنه كما المسيح، هكذا نحن أيضا في هذا العالم.","4:18":"ليس في المحبة أي خوف. بل المحبة الكاملة تطرد الخوف خارجا. فإن الخوف يأتي من العقاب. والخائف لا تكون محبة الله قد اكتملت فيه.","4:19":"ونحن نحب، لأن الله أحبنا أولا.","4:20":"فإن قال أحد: «أنا أحب الله !» ولكنه يبغض أخا له، فهو كاذب، لأنه إن كان لا يحب أخاه الذي يراه، فكيف يقدر أن يحب الله الذي لم يره قط؟","4:21":"فهذه الوصية جاءتنا من المسيح نفسه: من يحب الله ، يحب أخاه!","5:1":"كل من يؤمن حقا أن يسوع هو المسيح، فهو مولود من الله. ومن يحب الوالد، فلابد أن يحب المولودين منه أيضا.","5:2":"وما يثبت لنا محبتنا لأولاد الله هو أن نحب الله ونعمل بوصاياه.","5:3":"فالمحبة الحقيقية لله هي أن نعمل بما يوصينا به. وهو لا يوصينا وصية فوق طاقتنا.","5:4":"ذلك لأن المولود من الله ينتصر على العالم. فالإيمان هو الذي يجعلنا ننتصر على العالم.","5:5":"ومن ينتصر على العالم إلا الذي يؤمن أن يسوع هو ابن الله؟","5:6":"فيسوع المسيح وحده جاءنا بالماء والدم. لا بالماء فقط، بل بالماء والدم معا. هذه الحقيقة، يشهد لها الروح القدس: لأنه هو الحق ذاته.","5:7":"فإن هنالك ثلاثة شهود غفي السماء، الآب والكلمة والروح القدس، وهؤلاء الثلاثة هم واحدف.","5:8":"والذين يشهدون في الأرض هم ثلاثة: الروح، والماء، والدم. وهؤلاء الثلاثة هم في الواحد.","5:9":"إن كنا نصدق الشهادة التي يقدمها الناس، فالشهادة التي يقدمها الله أعظم، لأنها شهادة إلهية شهد الله بها لابنه.","5:10":"فمن يؤمن بابن الله، يثق في قلبه بصحة هذه الشهادة. أما من لا يصدق الله ، إذ يرفض تصديق الشهادة التي شهد بها لابنه، فهو يتهم الله بالكذب.","5:11":"وهذه الشهادة هي أن الله أعطانا حياة أبدية، وأن هذه الحياة هي في ابنه.","5:12":"فمن كان له ابن الله كانت له الحياة. ومن لم يكن له ابن الله، لم تكن له الحياة!","5:13":"يامن آمنتم باسم ابن الله، إني كتبت هذا إليكم لكي تعرفوا أن الحياة الأبدية ملك لكم منذ الآن.","5:14":"نحن نثق بالله ثقة عظيمة تؤكد لنا أنه يسمع لنا الطلبات التي نرفعها إليه، إن كانت منسجمة مع إرادته.","5:15":"ومادمنا واثقين بأنه يسمع لنا، مهما كانت طلباتنا، فلنا الثقة بأننا قد حصلنا منه على تلك الطلبات.","5:16":"إن رأى أحد منكم واحدا من إخوته يمارس خطيئة لا تنتهي به إلى الموت، فمن واجبه أن يصلي إلى الله من أجله، فيبقيه على قيد الحياة. هذا إذا كانت الخطيئة التي يمارسها لا تنتهي به إلى الموت. فهنالك خطيئة لابد أن تنتهي إلى الموت. وطبعا، أنا لا أقصد هذه الخطيئة هنا.","5:17":"كل إثم هو خطيئة، ولا تنتهي كل خطيئة إلى الموت.","5:18":"نحن واثقون بأن كل من ولد من الله لا يمارس الخطيئة، لأن ابن الله يحميه فلا يمسه إبليس الشرير.","5:19":"ونحن واثقون أيضا بأننا من الله، وأن العالم كله خاضع لسيطرة إبليس الشرير.","5:20":"وإننا نعلم أن ابن الله قد جاء إلى الأرض وأنار أذهاننا لنعرف الإله الحق. ونحن الآن نحيا فيه، لأننا في ابنه يسوع المسيح. هذا هو الإله الحق، والحياة الأبدية.","5:21":"أيها الأولاد الصغار، احفظوا أنفسكم من الأصنام!"},"2Jo":{"1:1":"من يوحنا الشيخ، إلى السيدة التي اختارها الله ، وإلى أولادها الذين أحبهم جميعا بالحق، ولست أنا وحدي أحبهم، بل أيضا جميع الذين عرفوا الحق.","1:2":"بما أن الحق ثابت في قلوبنا، ولابد أن يرافقنا إلى الأبد،","1:3":"فإن النعمة والرحمة والسلام ستكون معنا، من عند الله الآب والرب يسوع المسيح ابن الآب، بالحق والمحبة.","1:4":"فرحت جدا حين وجدت بعض أولادك يسلكون بحسب الحق، وفقا لما أوصانا به الآب.","1:5":"وا لآن، أيتها السيدة، لي رجاء أطلبه منك، ولا تعتبريه وصية جديدة. وإنما هو تلك الوصية الموجودة عندنا منذ البداية،: أن يحب بعضنا بعضا.","1:6":"هذه هي المحبة: أن نسلك وفقا لوصاياه. وهذه هي الوصية، كما سمعتم منذ البداية: أن تسلكوا في المحبة!","1:7":"إن العالم أصبح يعج بالمضللين الذين لا يعترفون أن يسوع المسيح جاء إلى الأرض بجسم بشري. هذا هو روح المضل وضد المسيح!","1:8":"فانتبهوا لأنفسكم، لكي لا يضيع الجهد الذي بذلناه في سبيلكم، بل لتنالوا أجركم كاملا.","1:9":"لأن من تعدى تعليم المسيح ولم يثبت فيه، فليس الله من نصيبه. أما من يثبت في هذا التعليم، فله الآب والابن معا.","1:10":"إن جاءكم أحد بغير هذا التعليم، فلا تستقبلوه في بيتكم، ولا تبادلوه التحية.","1:11":"لأن من يسلم عليه، يشاركه في أعماله الشريرة.","1:12":"كان عندي أمور كثيرة أكتبها إليكم إلا أني ما أردت أن أكتبها هنا بالحبر والورق. فأنا آمل أن أزوركم شخصيا فنتكلم مواجهة. وعندئذ يكتمل فرحنا.","1:13":"يسلم عليك أولاد أختك التي اختارها الله ."},"3Jo":{"1:1":"من يوحنا الشيخ إلى غايوس الحبيب الذي أحبه بالحق.","1:2":"أيها الحبيب، أود أن تكون موفقا في كل أمر، وأن تكون صحتك البدنية قوية ومعافاة كصحتك الروحية.","1:3":"فكم كان فرحي عظيما عندما مر بي بعض الإخوة المسافرين وأخبروني أنك تسلك بحسب الحق، وشهدوا للحق الثابت فيك!","1:4":"وما أعظم الفرح الذي يغمر قلبي حين أسمع الأخبار الطيبة التي تؤكد أن أولادي يسلكون بحسب الحق!","1:5":"أيها الحبيب، إن معاملتك الحسنة للإخوة وللغرباء تدل على أنك تتصرف بأمانة نحو الله.","1:6":"وقد شهد هؤلاء الإخوة، أمام الكنيسة، شهادة جميلة لمحبتك. فإنك تفعل حسنا إذا زودتهم بما يحتاجون إليه في السفر. فأنت تعرف أن هذا يرضي الله ،","1:7":"لأن هؤلاء الإخوة قد انطلقوا في سبيل خدمة المسيح، وهم لا يتلقون أي عون من غير المؤمنين.","1:8":"فعلينا نحن أن نرحب بأمثال هؤلاء لكي نكون حقا شركاء لهم في خدمة الحق.","1:9":"كتبت كلمة إلى الكنيسة بشأن هذا الأمر. ولكن ديوتريفوس، الذي يحب أن يفرض نفسه عليهم قائدا لا يقبلنا.","1:10":"لهذا، سألفت الانتباه إلى الأعمال التي يقوم بها، حين أجيء. إنه يثير ضدنا تهما كاذبة، متكلما بأسلوب خبيث. وهو لا يكتفي بهذا، بل يرفض استقبال الإخوة المسافرين، ويمنع الذين يريدون استقبالهم، ويطردهم من الكنيسة أيضا.","1:11":"أيها الحبيب، لا تقتد بما هو شر، بل بما هو خير. فإن من يفعل الخير، يكون من الله. ومن يفعل الشر، يبين أنه لم يتعرف بالله قط.","1:12":"أما ديمتريوس، فالجميع يشهدون له شهادة طيبة. حتى الحق نفسه يشهد له. ونحن أيضا نشهد له. وأنتم تثقون بصدق ما نشهد به.","1:13":"كان عندي أمور كثيرة أكتبها إليك. ولكني لست أريد أن أكتبها هنا بالحبر والقلم.","1:14":"فآمل أن نتقابل عن قريب، فنتكلم مواجهة! (1:15) السلام لك! الأحباء هنا يسلمون عليك. سلم على كل واحد من الأحباء باسمه."},"Jud":{"1:1":"من يهوذا، عبد يسوع المسيح وشقيق يعقوب، إلى الذين دعاهم الله الآب إليه، المحبوبين منه، والمحفوظين من أجل يسوع المسيح.","1:2":"لتكن لكم الرحمة والسلام والمحبة في وفرة وازدياد!","1:3":"أيها الأحباء، كنت قد نويت أن أكتب إليكم في موضوع الخلاص الذي نشترك فيه جميعا. ولكن، أراني الآن مضطرا لأن أكتب لأشجعكم على الجهاد في سبيل الإيمان الذي سلم مرة واحدة للقديسين.","1:4":"لأنه قد تسلل إلى ما بينكم معلمون لابد أن يلاقوا الحكم بالعقاب الأبدي، كما هو مكتوب لهم منذ القديم. فهم أشرار لا يهابون الله ، يتخذون من نعمة إلهنا فرصة لإباحة الرذائل، وينكرون سيدنا وربنا الوحيد يسوع المسيح.","1:5":"فالآن، أريد أن أذكركم بأمور تعرفونها. فأنتم تعرفون أن الرب، بعدما أنقذ الشعب من مصر، عاد فأهلك الذين لم يؤمنوا من ذلك الشعب.","1:6":"وأما الملائكة الذين لم يحافظوا على مقامهم الرفيع، بل تركوا مركزهم، فمازال الرب يحفظهم مقيدين بسلاسل أبدية في أعماق الظلام، بانتظار دينونة ذلك اليوم العظيم.","1:7":"وتعرفون كذلك ما فعله الرب بمدينتي سدوم وعمورة وبالمدن التي حولهما. فقد كان أهل هذه المدن، مثل أولئك المعلمين، مندفعين وراء الزنى، ومنغمسين في شهوات مخالفة للطبيعة. لذلك عاقب الرب هذه المدن بالنار الأبدية، فدمرها. فكانت بذلك عبرة للآخرين.","1:8":"ومع ذلك، فإن أولئك المعلمين المتوهمين يسيرون في الطريق التي سار فيها أهل تلك المدن. إذ يلوثون أجسادهم بالنجاسة، ويحتقرون السيادة الإلهية، ويتكلمون بالإهانة على الكائنات المجيدة!","1:9":"فحتى ميخائيل، وهو رئيس ملائكة، لم يجرؤ أن يحكم على إبليس بكلام مهين عندما خاصمه وتجادل معه بخصوص جثمان موسى، وإنما اكتفى بالقول له: «ليزجرك الرب!»","1:10":"ولكن هؤلاء المعلمين يتكلمون كلاما مهينا على أمور لا يعرفونها. وأما ما يفهمونه بالغريزة، كالحيوانات غير العاقلة، فإنهم به يدمرون أنفسهم.","1:11":"الويل لهم! لأنهم سلكوا طريق قايين، واندفعوا إلى ارتكاب خطيئة بلعام طلبا للمال، وتمردوا كما تمرد قورح، فدمروا أنفسهم.","1:12":"إنهم يشتركون معكم في ولائم المحبة دون خجل، ولكنهم كصخور تعيقكم. لا هم لهم سوى تعليف أنفسهم! إنهم يشبهون غيوما بلا مطر تسوقها الرياح، وأشجارا خريفية بلا ثمر، يقتلعها أصحابها، فتكون قد ماتت مرتين.","1:13":"وبأعمالهم المخجلة يفضحون أنفسهم كأمواج في البحر هائجة تقذف الأوساخ. وهم أشبه بنجوم تائهة في الفضاء، مصيرها الظلام الشديد إلى الأبد!","1:14":"عن هؤلاء وأمثالهم، تنبأ أخنوخ السابع بعد آدم، فقال: «انظروا إن الرب آت بصحبة عشرات الألوف من قديسيه،","1:15":"ليدين جميع الناس، ويوبخ جميع الأشرار الذين لا يهابون الله ، بسبب جميع أعمالهم الشريرة التي ارتكبوها وجميع أقوالهم القاسية التي أهانوه بها والتي لا تصدر إلا عن الخاطئين الأشرار غير الأتقياء!»","1:16":"وهؤلاء المعلمون يتذمرون ويشكون دائما وفيما هم يندفعون وراء شهواتهم، يطلقون ألسنتهم متحدثين بأمور طنانة، ويمدحون من يعجبهم طلبا للمنفعة!","1:17":"أما أنتم أيها الأحباء، فاذكروا دائما ما قاله رسل ربنا يسوع المسيح.","1:18":"فقد سبق أن نبهوكم إلى أنه، في نهاية الزمان، سيطلع مستهزئون يعيشون منغمسين في شهواتهم الفاسقة.","1:19":"هؤلاء هم الذين يسببون الانشقاق، وينساقون وراء غرائزهم الحيوانية، وليس الروح القدس فيهم!","1:20":"وأما أنتم أيها الأحباء، فابنوا أنفسكم على إيمانكم الأقدس، وصلوا دائما في الروح القدس.","1:21":"واحفظوا أنفسكم في محبة الله، منتظرين رحمة ربنا يسوع المسيح إذ يعود ويأخذكم لتحيوا معه إلى الأبد.","1:22":"بعض الناس يجب أن تعاملوهم بشفقة بسبب شكوكهم.","1:23":"وبعضهم يجب أن تنقذوهم من النار خطفا. وآخرون يجب أن تعالجوهم بشفقة وحذر، مبغضين حتى الثياب التي يلوثونها بأجسادهم.","1:24":"وللقادر أن يحرسكم من السقوط حتى يوصلكم إلى المثول أمامه في المجد مبتهجين ولا عيب فيكم …","1:25":"لله الواحد، مخلصنا بيسوع المسيح ربنا ... المجد والجلال والقدرة والسلطة، من قبل أن كان الزمان، والآن وطوال الأزمان آمين!"},"Rev":{"1:1":"هذه رؤيا أعطاها الله ليسوع المسيح، ليكشف لعبيده عن أمور لابد أن تحدث عن قريب. وأعلنها المسيح لعبده يوحنا عن طريق ملاك أرسله لذلك.","1:2":"وقد شهد يوحنا بكلمة الله وبشهادة يسوع المسيح، بجميع الأمور التي رآها.","1:3":"طوبى للذي يقرأ كتاب النبوءة هذا وللذين يسمعونه، فيراعون ما جاء فيه، لأن موعد إتمام النبوءة قد اقترب!","1:4":"من يوحنا، إلى الكنائس السبع في مقاطعة آسيا: لكم النعمة والسلام من الكائن والذي كان والذي سيأتي، ومن الأرواح السبعة الماثلة أمام عرشه،","1:5":"ومن يسوع المسيح الشاهد الأمين، بكر القائمين من بين الأموات، ملك ملوك الأرض، ذاك الذي بدافع محبته لنا مات لأجلنا فغسلنا بدمه من خطايانا،","1:6":"وجعل منا مملكة، وكهنة لله أبيه، له المجد والسلطان إلى أبد الآبدين. آمين!","1:7":"ها هو آت مع السحاب! ستراه عيون الجميع، حتى أولئك الذين طعنوه، وتنوح بسببه قبائل الأرض كلها! نعم، آمين!","1:8":"«أنا الألف والياء» (البداية والنهاية). هذا يقوله الرب الإله الكائن والذي كان والذي سيأتي، القادر على كل شيء.","1:9":"أنا، يوحنا أخاكم وشريككم في الضيقة والملكوت والصبر في يسوع، كنت منفيا في الجزيرة التي تسمى بطمس، لأجل كلمة الله وشهادة يسوع.","1:10":"وفي يوم الرب، صرت في الروح، فسمعت من ورائي صوتا عاليا كصوت البوق","1:11":"يقول: «دون ما تراه في كتاب، وابعث به إلى الكنائس السبع: في أفسس، وسميرنا، وبرغامس، وثياتيرا، وساردس، وفيلادلفيا، ولاودكية».","1:12":"و","1:13":"وعندما التفت نحو الصوت، رأيت كائنا يشبه ابن الإنسان، يقف وسط سبع منائر من ذهب، ويرتدي ثوبا طويلا إلى الرجلين، يلف صدره حزام من ذهب.","1:14":"شعر رأسه ناصع البياض كالصوف أو الثلج، وعيناه كشعلة ملتهبة.","1:15":"رجلاه تلمعان كأنهما نحاس نقي مصقول بالنار، وصوته يدوي كصوت شلال غزير،","1:16":"ووجهه يتوهج بالنور كشمس الظهيرة. وكان في يده اليمنى سبعة نجوم، ومن فمه يخرج سيف قاطع ذو حدين.","1:17":"فلما رأيته ارتميت عند قدميه كالميت، فلمسني بيده اليمنى وقال: «لا تخف! أنا الأول والآخر،","1:18":"أنا الحي. كنت ميتا، ولكن ها أنا حي إلى أبد الآبدين. ولي مفاتيح الموت والهاوية.","1:19":"دون ما رأيته، وما يحدث الآن، وما يوشك أن يحدث بعده.","1:20":"وهذا سر النجوم السبعة التي رأيتها في يميني، ومنائر الذهب السبع: النجوم السبعة تمثل ملائكة الكنائس السبع، أما المنائر السبع فهي تمثل الكنائس السبع نفسها.","2:1":"اكتب إلى ملاك الكنيسة في أفسس: إليك ما يقوله الذي يمسك النجوم السبع بيمينه ويمشي بين منائر الذهب السبع:","2:2":"إني عالم بأعمالك، وجهدك، وصبرك، وأعلم أنك لا تستطيع احتمال الأشرار، وأنك دققت في فحص ادعاءات أولئك الذين يزعمون أنهم رسل، وما هم برسل، فتبين لك أنهم دجالون!","2:3":"وقد تألمت من أجل اسمي بصبر وبغير كلل.","2:4":"ولي عليك أنك تركت محبتك الأولى!","2:5":"فاذكر من أين سقطت، وتب راجعا إلى أعمالك السابقة، وإلا أتيت وزحزحت منارتك من موضعها إن كنت لا تتوب!","2:6":"أما ما يسرني فيك فهو أنك تكره أعمال النيقولاويين التي أكرهها أنا أيضا.","2:7":"من له أذنان فليسمع ما يقوله الروح للكنائس! كل من ينتصر سأطعمه من ثمر شجرة الحياة في فردوس الله.","2:8":"واكتب إلى ملاك الكنيسة في سميرنا: إليك ما يقوله الأول والآخر، الذي كان ميتا وعاد حيا:","2:9":"إني أعلم كم تقاسي من ضيق وفقر، رغم أنك غني. وأعلم تجريح الذين يدعون أنهم يهود ولكنهم ليسوا يهودا، بل هم مجمع للشيطان!","2:10":"دع عنك الخوف مما ينتظرك من آلام، فإن إبليس سيزج ببعضكم في السجن لكي تمتحنوا، فتقاسون الاضطهاد عشرة أيام. فابق أمينا حتى الموت، فأمنحك إكليل الحياة.","2:11":"من له أذن فليسمع ما يقوله الروح للكنائس! كل من ينتصر لن يلحق به أذى الموت الثاني!","2:12":"واكتب إلى ملاك الكنيسة في برغامس: إليك ما يقوله صاحب السيف القاطع ذي الحدين.","2:13":"إني أعلم أين تسكن، حيث عرش الشيطان! ورغم ذلك تمسكت باسمي، ورفضت أن تنكر الإيمان بي، حتى في أيام أنتيباس شهيدي الأمين، الذي قتل عندكم حيث يسكن الشيطان!","2:14":"ولكني عاتب عليك قليلا لأنك تتسامح مع القوم الذين يتمسكون بتعليم بلعام عندما علم الملك بالاق أن يدمر بني إسرائيل بتوريطهم في ارتكاب الزنى والأكل من الذبائح المقدمة للأصنام،","2:15":"هكذا عندك أنت أيضا قوم يتمسكون بتعاليم النيقولاويين!","2:16":"عليك أن تتوب، وإلا جئتك سريعا لأحارب هؤلاء الضالين بالسيف الذي في فمي.","2:17":"من له أذن فليسمع ما يقوله الروح للكنائس! كل من سينتصر سأطعمه من المن الخفي، وأعطيه حجرا صغيرا أبيض حفر عليه اسم جديد لا يعرفه إلا الذي يأخذه!","2:18":"واكتب إلى ملاك الكنيسة في ثياتيرا: إليك ما يقوله ابن الله الذي عيناه كلهيب نار ورجلاه كالنحاس النقي:","2:19":"إني عالم بأعمالك، ومحبتك، وإيمانك، وتضحيتك، وصبرك؛ وأعلم أن أعمالك الأخيرة زادت عما كانت عليه قبلا!","2:20":"ولكن لي عليك أنك تتساهل مع هذه المرأة إيزابل، التي تدعي أنها نبية، فتعلم عبيدي وتغويهم أن يزنوا ويأكلوا من الذبائح المقدمة للأصنام.","2:21":"وقد أمهلتها مدة لتتوب تاركة زناها، ولكنها لم تتب.","2:22":"فإني سألقيها على فراش، وأبتلي الزانين معها بمحنة شديدة، إن كانوا لا يتوبون عن أعمالهم.","2:23":"سأبيد أولادها بالموت، فتعرف الكنائس كلها أنني أنا الذي أفحص الأفكار والقلوب، وأجازي كل واحد منكم بحسب أعماله.","2:24":"أما أنتم، الباقين من أهل ثياتيرا، الذين لم يتقبلوا هذا التعليم الفاسد، ولم يعرفوا ما يدعونه «أسرار الشيطان العميقة»، فلن أحملكم أي عبء جديد.","2:25":"فقط تمسكوا بما لديكم إلى أن أجيء.","2:26":"كل من ينتصر، ويستمر حتى النهاية في فعل ما يرضيني، فسوف أعطيه سلطانا على الأمم،","2:27":"فيحكمهم بعصا من حديد، مثلما أخذت أنا من أبي سلطانا أحكمهم به، فيتحطمون كما تتحطم أواني الخزف،","2:28":"وأمنحه كوكب الصبح!","2:29":"من له أذن فليسمع ما يقوله الروح للكنائس!","3:1":"واكتب إلى ملاك الكنيسة في ساردس: إليك ما يقوله من له أرواح الله السبعة والنجوم السبعة: إني عالم بأعمالك. فأنت حي بالاسم، ولكنك ميت فعلا.","3:2":"تيقظ، وما تبقى لديك أنعشه قبل أن يموت، لأني وجدت أعمالك غير كاملة في نظر إلهي.","3:3":"تذكر ما سبق أن تقبلته وسمعته، وتمسك بما آمنت به، وتب! فإن كنت لا تتنبه، آتيك كما يأتي اللص، ولا تدري في أية ساعة أفاجئك!","3:4":"إلا أن عندك في ساردس قليلين لم يلوثوا ثيابهم بالنجاسة. هؤلاء سيسيرون معي لابسين ثيابا بيضاء.","3:5":"كل من ينتصر سيلبس ثوبا أبيض، ولن أمحو اسمه من سجل الحياة، وسأعترف باسمه أمام أبي وملائكته.","3:6":"من له أذن فليسمع ما يقوله الروح للكنائس!","3:7":"واكتب إلى ملاك الكنيسة في فيلادلفيا: إليك ما يقوله القدوس الحق، الذي بيده مفتاح داود، يفتح ولا أحد يغلق، ويغلق ولا أحد يفتح.","3:8":"إني عالم بأعمالك. فمع أن لك قوة ضئيلة، فقد أطعت كلمتي ولم تنكر اسمي، ولذلك فتحت لك بابا لا يقدر أحد أن يغلقه.","3:9":"أما الذين هم من مجمع الشيطان، ويدعون كذبا أنهم يهود، فسأجبرهم على أن يسجدوا عند قدميك، ويعترفوا بأني أحببتك.","3:10":"ولأنك حفظت كلمتي وصبرت، فسأحفظك أنا أيضا من ساعة التجربة التي ستأتي على العالم أجمع لتجرب الساكنين على الأرض.","3:11":"إني آت سريعا، فتمسك بما عندك، لئلا يسلب أحد إكليلك.","3:12":"كل من ينتصر سأجعله عمودا في هيكل إلهي، فلا يخرج منه أبدا، وسأكتب عليه اسم إلهي واسم مدينة إلهي أورشليم الجديدة، التي تنزل من السماء من عند إلهي، وأكتب عليه اسمي الجديد.","3:13":"من له أذن فليسمع ما يقوله الروح للكنائس!","3:14":"واكتب إلى ملاك الكنيسة في لاودكية: إليك ما يقوله الحق، الشاهد الأمين الصادق، رئيس خليقة الله:","3:15":"إني عالم بأعمالك، وأعلم أنك لست باردا ولا حارا. وليتك كنت باردا أو حارا!","3:16":"فبما أنك فاتر، لا حار ولا بارد، سألفظك من فمي!","3:17":"تقول: أنا غني، قد اغتنيت ولا يعوزني شيء! ولكنك لا تعلم أنك شقي بائس فقير أعمى عريا ن.","3:18":"نصيحتي لك أن تشتري مني ذهبا نقيا، صفته النار، فتغتني حقا، وثيابا بيضاء ترتديها فتستر عريك المعيب، وكحلا لشفاء عينيك فيعود إليك البصر.","3:19":"إني أوبخ وأؤدب من أحبه، لذا كن حارا وتب!","3:20":"ها أنا واقف خارج الباب أقرعه. إن سمع أحد صوتي وفتح الباب، أدخل إليه فأتعشى معه وهو معي.","3:21":"وكل من ينتصر سأجلسه معي على عرشي، كما انتصرت أنا أيضا فجلست مع أبي على عرشه؛","3:22":"من له أذن فليسمع ما يقوله الروح للكنائس!»","4:1":"بعد ذلك رأيت بابا مفتوحا في السماء، وإذا الصوت الذي سمعته من قبل يخاطبني كأنه بوق، ويقول: «اصعد إلى هنا فأريك ما لابد أن يحدث بعد هذا».","4:2":"وفي الحال صرت في الروح، فرأيت في السماء عرشا يجلس عليه واحد","4:3":"تنبعث منه أنوار كأنها صادرة من لمعان اليشب والعقيق الأحمر. وحول العرش قوس قزح يلمع كأنه الزمرد.","4:4":"وقد أحاط بالعرش أربعة وعشرون عرشا يجلس عليها أربعة وعشرون شيخا يلبسون ثيابا بيضاء، وعلى رؤوسهم أكاليل من ذهب.","4:5":"وكانت تخرج من العرش بروق ورعود وأصوات، وأمامه سبعة مصابيح نار مضاءة، هي أرواح الله السبعة.","4:6":"وكان يبدو كأن بحرا شفافا مثل البلور يمتد أمام العرش، وفي وسط العرش وحوله أربعة كائنات تكسوها عيون كثيرة من الأمام ومن الخلف:","4:7":"الكائن الأول يشبه الأسد، والثاني يشبه العجل، والثالث له وجه مثل وجه إنسان. أما الكائن الرابع فيشبه النسر الطائر.","4:8":"وكان لكل كائن منها ستة أجنحة، تكسوها عيون من الداخل ومن الخارج. وهذه الكائنات الحية الأربعة تهتف ليلا ونهارا دون انقطاع قائلة: «قدوس قدوس قدوس، الرب الإله القادر على كل شيء، الذي كان والكائن والذي سيأتي».","4:9":"وكلما قدمت هذه الكائنات التمجيد والإجلال والحمد للجالس على العرش، الحي إلى أبد الآبدين،","4:10":"يجثو الشيوخ الأربعة والعشرون أمام الجالس على العرش ساجدين للحي إلى أبد الآبدين، ويلقون أكاليلهم أمام عرشه وهم يهتفون:","4:11":"«مستحق أنت ياربنا وإلهنا المجد والإجلال والقدرة، لأنك خلقت الأشياء كلها، وهي بإرادتك كائنة وقد خلقت!»","5:1":"ورأيت إلى يمين الجالس على العرش درج كتاب مخطوطا من الداخل والخارج، مختوما بسبعة ختوم.","5:2":"ورأيت ملاكا قويا ينادي بأعلى صوته: «من هو المستحق أن يفك ختوم الكتاب ويفتحه؟»","5:3":"فلم يستطع أحد في السماء ولا على الأرض ولا تحت الأرض أن يفتح الكتاب أو ينظر إليه!","5:4":"فأخذت أبكي بكاء شديدا لأنه لم يكن هناك من يستحق أن يفتح الكتاب أو ينظر إليه.","5:5":"ولكن شيخا من الشيوخ قال لي: «لا تبك! قد انتصر الأسد الذي من سبط يهوذا، الذي هو أصل داود، وهو المستحق أن يفتح الكتاب ويفك ختومه السبعة».","5:6":"ونظرت فرأيت في الوسط بين العرش والكائنات الحية الأربعة والشيوخ حملا يظهر كأنه كان قد ذبح. وكانت له سبعة قرون، وسبع أعين تمثل أرواح الله السبعة التي أرسلت إلى الأرض كلها.","5:7":"فتقدم وأخذ الكتاب من يمين الجالس على العرش.","5:8":"فسجد الشيوخ الأربعة والعشرون والكائنات الحية الأربعة أمام الحمل، وكان بيد كل منهم قيثارة وكؤوس ذهب مملوءة بالبخور، الذي هو صلوات القديسين.","5:9":"وأخذوا يرتلون ترتيلة جديدة يقولون فيها: «مستحق أنت أن تأخذ الكتاب وتفك ختومه، لأنك ذبحت، وبدمك اشتريت لله أناسا من كل قبيلة ولغة وشعب وأمة،","5:10":"وجعلتهم مملكة لإلهنا وكهنة له، وسيملكون على الأرض».","5:11":"ثم نظرت، فسمعت ترتيل الملايين من الملائكة وهي تحيط بالعرش وبالكائنات الحية والشيوخ،","5:12":"وهم يهتفون بصوت عال: «مستحق هو الحمل المذبوح أن ينال القدرة والغنى والحكمة والقوة والإجلال والمجد والبركة».","5:13":"ثم سمعت كل خليقة في السماء وعلى الأرض، وتحت الأرض، وعلى البحر، هاتفة مع كل ما فيها: «البركة والإجلال والمجد والسلطة للجالس على العرش وللحمل، إلى أبد الآبدين».","5:14":"فردت الكائنات الحية الأربعة: «آمين!» وجثا الشيوخ ساجدين.","6:1":"ورأيت الحمل وهو يفك أول الختوم السبعة، وسمعت واحدا من الكائنات الحية الأربعة ينادي بصوت كالرعد: «تعال!»","6:2":"فنظرت وإذا أمامي حصان أبيض، يحمل راكبه قوسا، وعلى رأسه إكليل، وقد خرج منتصرا ولكي ينتصر.","6:3":"ثم فك الحمل الختم الثاني، فسمعت الكائن الثاني ينادي: «تعال!»","6:4":"فخرج حصان أحمر، أعطي راكبه سيفا عظيما، ومنح سلطة نزع السلام من الأرض وجعل الناس يقتلون بعضهم بعضا.","6:5":"وعندما فك الحمل الختم الثالث سمعت الكائن الثالث ينادي: «تعال!» فرأيت حصانا أسود، يحمل راكبه ميزانا بيده.","6:6":"وسمعت صوتا من بين الكائنات الحية الأربعة يقول: «كيلة قمح بدينار، وثلاث كيلات شعير بدينار. أما الزيت والخمر فلا تمسهما».","6:7":"ثم فك الحمل الختم الرابع فسمعت الكائن الرابع ينادي: «تعال!»","6:8":"فرأيت حصانا لونه أخضر «باهت اللون»، اسم راكبه «الموت» يتبعه حصان آخر اسم راكبه «الهاوية»، وأعطيا سلطة إبادة ربع الأرض بالسيف والجوع والوباء ووحوش الأرض الضارية!","6:9":"ثم فك الحمل الختم الخامس، فرأيت مذبحا تحته أرواح الذين سفكت دماؤهم من أجل كلمة الله، ومن أجل الشهادة التي أدوها،","6:10":"وهم يصرخون للرب بأعلى صوتهم: «حتى متى، أيها السيد القدوس والحق، تؤخر معاقبة أهل الأرض على ما فعلوه بنا؟ متى تنتقم منهم لدمائنا؟»","6:11":"فأعطي كل منهم ثوبا أبيض، وقيل لهم أن يصبروا قليلا إلى أن يكمل عدد شركائهم العبيد وإخوتهم الذين سيقتلون مثلهم.","6:12":"ثم نظرت، فرأيت الحمل يفك الختم السادس، وإذا الأرض قد زلزلت زلزالا عظيما، والشمس اسودت فصارت كخرقة من شعر، وصار القمر أحمر كالدم،","6:13":"وسقطت نجوم السماء على الأرض كما تطرح شجرة التين ثمارها الفجة، إذا هزتها ريح عاصفة.","6:14":"وطويت السماء كما تطوى لفافة من ورق، فتزحزحت الجبال والجزر كلها من مواضعها.","6:15":"وملوك الأرض والعظماء والقواد والأغنيا ء والأقوياء والعبيد والأحرار كلهم اختبأوا في المغاور وصخور الجبال،","6:16":"وهم يقولون للجبال والصخور: اسقطي علينا، وأخفينا من وجه الجالس على العرش ومن غضب الحمل!»","6:17":"فإن يوم الغضب العظيم قد جاءهم، ومن يقوى على الوقوف أمامه؟","7:1":"ورأيت بعد ذلك أربعة ملائكة واقفين على زوايا الأرض الأربع، يحبسون رياح الأرض الأربع، فلا تهب ريح على بر أو بحر أو شجر.","7:2":"ثم رأيت ملاكا آخر قادما من الشرق يحمل ختم الله الحي، فنادى بصوت عال الملائكة الأربعة الذين عهد إليهم أن ينزلوا الضرر بالبر والبحر:","7:3":"«انتظروا! لا تضروا البر ولا البحر ولا الشجر، إلى أن نضع ختم إلهنا على جباه عبيده».","7:4":"وسمعت أن عدد المختومين، مئة وأربعة وأربعون ألفا، من جميع أسباط بني إسرائيل:","7:5":"من سبط يهوذا ختم اثنا عشر ألفا؛ ومن سبط رأوبين اثنا عشر ألفا؛ ومن سبط جاد اثنا عشر ألفا؛","7:6":"ومن سبط أشير اثنا عشر ألفا؛ ومن سبط نفتالي اثنا عشر ألفا؛ ومن سبط منسى اثنا عشر ألفا","7:7":"ومن سبط شمعون اثنا عشر ألفا؛ ومن سبط لاوي اثنا عشر ألفا؛ ومن سبط يساكر اثنا عشر ألفا؛","7:8":"ومن سبط زبولون اثنا عشر ألفا؛ ومن سبط يوسف اثنا عشر ألفا؛ ومن سبط بنيامين ختم اثنا عشر ألفا.","7:9":"ثم نظرت، فرأيت جمعا كثيرا لا يحصى، من كل أمة وقبيلة وشعب ولغة، واقفين أمام العرش وأمام الحمل، وقد ارتدوا ثيا با بيضاء، وأمسكوا بأيديهم سعف النخل،","7:10":"وهم يهتفون بصوت عال: «الخلاص من عند إلهنا الجالس على العرش ومن عند الحمل!»","7:11":"واجتمع الملائكة جميعا حول العرش، ومعهم الشيوخ والكائنات الحية الأربعة، وخروا على وجوههم أمام العرش سجودا لله،","7:12":"قائلين: «آمين! لإلهنا البركة والمجد والحكمة والشكر والإجلال والقدرة والقوة إلى أبد الآبدين. آمين!»","7:13":"وسألني أحد الشيوخ: «أتعلم من هم هؤلاء الذين يرتدون الثياب البيضاء، وهل تعرف من أين أتوا؟»","7:14":"فأجبته: «أنت أعلم ياسيدي!» فقال: «هؤلاء هم الذين أتوا من الضيقة العظيمة، وقد غسلوا ثيابهم وبيضوها بدم الحمل.","7:15":"لهذا هم أمام عرش الله يخدمونه في هيكله ليلا ونهارا والجالس على العرش يبسط خيمته عليهم،","7:16":"فلن يجوعوا ولن يعطشوا، ولن تضربهم الشمس ولا أي حر،","7:17":"لأن الحمل الذي في وسط العرش يرعاهم ويقودهم إلى ينابيع ماء الحياة، ويمسح الله كل دمعة من عيونهم».","8:1":"ولما فك الحمل الختم السابع ساد السماء سكوت نحو نصف ساعة،","8:2":"ورأيت الملائكة السبعة الواقفين أمام الله، وقد أعطوا سبعة أبواق.","8:3":"ثم جاء ملاك آخر ومعه مبخرة من ذهب ووقف عند المذبح، وأعطي بخورا كثيرا ليقدمه مع صلوات القديسين على مذبح الذهب أمام العرش،","8:4":"فارتفع دخان البخور من يد الملاك مصحوبا بصلوات القديسين إلى حضرة الله.","8:5":"ثم ملأ الملاك المبخرة من النار التي على المذبح وألقاها إلى الأرض، فحدثت رعود وأصوات وبروق وزلزلة.","8:6":"واستعد الملائكة السبعة، أصحاب الأبواق السبعة، لينفخوا فيها.","8:7":"ولما نفخ الملاك الأول في بوقه، إذا برد ونار يخالطهما الدم يسقطان إلى الأرض، فاحترق ثلث الأرض وثلث الأشجار مع كل عشب أخضر.","8:8":"ولما نفخ الملاك الثاني في بوقه، ألقي في البحر ما يشبه جبلا عظيما مشتعلا، فصار ثلث البحر دما،","8:9":"فمات ثلث المخلوقات الحية التي فيه، وتحطم ثلث السفن.","8:10":"ثم نفخ الملاك الثالث في بوقه، فهوى من السماء نجم عظيم كأنه شعلة من نار، وسقط على ثلث الأنهار وينابيع المياه.","8:11":"واسم هذا النجم «العلقم». فصار ثلث المياه مرا كالعلقم، ومات كثيرون من الناس بسبب مرارة المياه.","8:12":"ولما نفخ الملاك الرابع في بوقه، حدثت ضربة لثلث الشمس وثلث القمر وثلث النجوم، فأظلم ثلثها وفقد النهار ثلث ضيائه، وكذلك الليل.","8:13":"ثم نظرت فرأيت نسرا يطير في وسط السماء وسمعته يصيح بصوت عال: «الويل الويل الويل لسكان الأرض مما سيحدث لهم عندما ينفخ الملائكة الثلاثة الباقون في أبواقهم!»","9:1":"ولما نفخ الملاك الخامس في بوقه، رأيت نجما قد هوى من السماء إلى الأرض، وأعطي مفتاح الهاوية السحيقة.","9:2":"فلما فتحها اندفع الدخان كأنه من أتون عظيم، فأظلمت الشمس والجو من هذا الدخان.","9:3":"وطلع من الدخان جراد على الأرض، وأعطي سلطة أن يلسع كالعقارب،","9:4":"وأمر ألا يضر عشب الأرض ولا مزروعاتها ولا أشجارها بل فقط جميع من ليس على جباههم ختم الله،","9:5":"فيعذبهم دون أن يقتلهم، مدة خمسة أشهر. والألم الذي يسببه يشبه ألم لدغة العقرب.","9:6":"وفي أثناء تلك الشهور يحاول الناس أن يتخلصوا من حياتهم فلا يقدرون! ويتمنون أن يموتوا، لكن الموت يهرب منهم.","9:7":"ويبدو هذا الجراد كأنه خيل مجهزة للقتال، على رؤوسه ما يشبه أكاليل الذهب، ووجوهه كوجوه البشر،","9:8":"وله شعر طويل كشعر النساء، وأسنانه كأسنان الأسود،","9:9":"وصدوره كدروع حديدية، وحفيف أجنحته كضجيج مركبات خيل تجري إلى القتال،","9:10":"وأذنابه ذات إبر كالعقارب. وله سلطة أن يؤذي البشر بأذنابه مدة خمسة أشهر.","9:11":"أما ملكه فهو «ملاك الهاوية»، واسمه بالعبرية «أبدون»، وباليونانية «أبوليون».","9:12":"انقضى الويل الأول، وهناك ويلان آخران قادمان!","9:13":"وعندما نفخ الملاك السادس في بوقه، سمعت صوتا آتيا من القرون الأربعة لمذبح الذهب الموجود أمام الله،","9:14":"يقول للملاك السادس الذي يحمل البوق: «أطلق الملائكة الأربعة المقيدين عند نهر الفرات الكبير».","9:15":"وكان هؤلاء الملائكة الأربعة مجهزين استعدادا لهذه الساعة واليوم والشهر والسنة، فأطلقوا ليقتلوا ثلث البشر.","9:16":"وسمعت أن جيشهم يبلغ مئتي مليون محارب!","9:17":"ور أيت في الرؤيا الخيول وعليها فرسان يلبسون دروعا بعضها أحمر ناري، وبعضها بنفسجي، وبعضها أصفر كبريتي. وكانت رؤوس الخيل مثل رؤوس الأسود، تلفظ من أفواهها نارا ودخانا وكبريتا.","9:18":"فقتل ثلث الناس بهذه البلايا الثلاث، أي بالنار والدخان والكبريت الخارجة من أفواه الخيل.","9:19":"وكانت قوة الخيل القاتلة تكمن في أفواهها وفي أذنابها أيضا، لأن أذنابها تشبه الحيات ذات الرؤوس المؤذية!","9:20":"ولكن الناس الذين نجوا من هذه البلايا، لم يتوبوا عن أعمالهم، وظلوا يسجدون للشياطين وللأصنام التي صنعوها من الذهب والفضة والنحاس والحجر والخشب، مع أنها لا ترى ولا تسمع ولا تتحرك!","9:21":"ولم يتوبوا عن القتل والسحر والزنى والسرقة!","10:1":"ثم رأيت ملاكا آخر قويا نازلا من السماء، لابسا سحابة، وعلى رأسه قوس قزح؛ وجهه كالشمس، ورجلاه كعمودين من نار،","10:2":"وبيده درج كتاب صغير مفتوح. فوضع رجله اليمنى على البحر واليسرى على الأرض،","10:3":"وصرخ صرخة عظيمة كزئير الأسد، دوت بعدها أصوات الرعود السبعة.","10:4":"ولما تأهبت لكتابة ما تقوله الرعود، سمعت صوتا من السماء يقول لي: «لا تكتب، فما نطقت به الرعود يجب أن تبقيه مكتوما».","10:5":"ثم إن الملاك الذي رأيته واقفا على البحر والأرض رفع يده اليمنى نحو السماء،","10:6":"وأقسم بالحي إلى أبد الآبدين الذي خلق السماء وما فيها والأرض وما فيها والبحر وما فيه، إنه لن تكون مهلة بعد،","10:7":"فحالما ينفخ الملاك السابع في بوقه، تتم خطة الله الخفية، وفقا لما أعلنه لعبيده الأنبياء!","10:8":"ثم كلمني الصوت السماوي ثانية وقال لي: «اذهب، خذ الكتاب الصغير المفتوح في يد الملاك القوي الواقف على البحر والأرض».","10:9":"فذهبت إليه وطلبت الكتاب منه، فأجابني: «خذه والتهمه. ستجد طعمه في فمك حلوا كالعسل، ولكنه سيجعل بطنك مرا!»","10:10":"ولما أخذته من يده والتهمته، كان حلوا كالعسل في فمي، ولكن ما إن ابتلعته حتى ملأ بطني مرارة!","10:11":"وقيل لي: «عليك أن تتنبأ أيضا بشأن كثير من الشعوب والأمم واللغات والملوك».","11:1":"وأعطيت عصا قياس، وأمرت أن أقيس هيكل الله والمذبح، وأن أحصي عدد المتعبدين فيه.","11:2":"وقيل لي: «لا تقس الساحة الخارجية لأنها خصصت للأمم، وسيدوسون المدينة المقدسة مدة اثنين وأربعين شهرا،","11:3":"ولكني سأمنح شاهدي أن يتنبآ مدة ألف ومئتين وستين يوما، وهما يلبسان ثوبين من الوبر».","11:4":"هذان الشاهدان هما شجرتا الزيتون والمنارتان القائمتان أمام رب الأرض.","11:5":"فإذا حاول أحد أن يمسهما بسوء تخرج نار من فمهما وتلتهم أعداءهما. ذلك يجب أن يكون مصير من يحاول أن يؤذيهما.","11:6":"وللشاهدين السلطة أن يغلقا السماء فلا تمطر طيلة مدة نبوءتهما، وأن يحولا مياه الأنهار والبحار دما، وأن ينزلا البلايا بالأرض، كلما أرادا.","11:7":"وعندما يكملان شهادتهما يعلن الوحش الصاعد من الهاوية الحرب عليهما، ويهزمهما ويقتلهما","11:8":"وتبقى جثتاهما مطروحتين في ساحة المدينة العظمى التي ترمز إليها «سدوم» أو «مصر»، حيث صلب ربهما.","11:9":"فيراهما أناس من مختلف الشعوب والقبائل واللغات والأمم، مدة ثلاثة أيام ونصف يوم، ولا يؤذن لأحد بدفنهما.","11:10":"ويشمت بهما أهل الأرض، فيفرحون كأنهم في عيد، ويتبادلون الهدايا، لأن هذين النبيين كانا قد عذباهم كثيرا.","11:11":"وبعد أن تمر الأيام الثلاثة ونصف اليوم يبعث الله في النبيين روح الحياة، فينهضان واقفين، ويستولي على الناظرين إليهما خوف شديد.","11:12":"ويدعوهما صوت عال من السماء: «اصعدا إلى هنا»، فيصعدان إلى السماء في سحابة بمشهد من أعدائهما.","11:13":"وفي الوقت ذاته يحدث زلزال عنيف يدمر عشر المدينة، ويهلك سبعة آلاف من ساكنيها. فيرتعب الناجون ويمجدون إله السماء.","11:14":"انقضى الويل الثاني، وها هو الثالث يأتي سريعا!","11:15":"ونفخ الملاك السابع في بوقه فسمعت أصوات عالية في السماء تقول: «قد صار ملك العالم لربنا ومسيحه. إنه يملك إلى أبد الآبدين».","11:16":"فجثا الشيوخ الأربعة والعشرون الجالسون على عروشهم في حضر ة الله وخروا على وجوههم ساجدين لله.","11:17":"وقالوا: «نحمدك أيها الإله القدير على كل شيء، الكائن والذي كان، لأنك الآن قد تقلدت قوتك العظمى وباشرت ملكك.","11:18":"غضبت الشعوب عليك، فجاء دور غضبك عليهم. جاءت الساعة ليدان الأموات، وتكافيء عبيدك الأنبياء والقديسين والمتقين اسمك، صغارا وكبارا، وتهلك الذين كانوا يدمرون الأرض!»","11:19":"وانفتح هيكل الله في السماء، وظهر تابوت العهد في داخله. وحدثت بروق وأصوات ورعود وزلزلة، وسقط برد كبير.","12:1":"وظهرت في السماء آية عظيمة: امرأة لابسة الشمس، والقمر تحت قدميها، وعلى رأسها تاج من اثني عشر نجما.","12:2":"وكانت حبلى تصرخ من ألم الولادة وتتوجع وهي تلد.","12:3":"وظهرت في السماء آية أخرى: تنين عظيم أحمر له سبعة رؤوس، على كل منها تاج، وله عشرة قرون،","12:4":"فسحب بذيله ثلث نجوم السماء وألقاها إلى الأرض. ثم وقف التنين أمام المرأة وهي تلد، ليبتلع طفلها بعد أن تلده!","12:5":"وولدت المرأة ابنا ذكرا، وهو الذي سيحكم الأمم كلها بعصا من حديد. ورفع الطفل إلى حضرة الله وإلى عرشه.","12:6":"أما المرأة فهربت إلى البرية، حيث أعد الله لها مكانا تعال فيه مدة ألف ومئتين وستين يوما.","12:7":"ونشبت حرب في السماء، إذ هاجم ميخائيل وملائكته التنين وملائكته،","12:8":"وحارب التنين وملائكته، لكنهم انهزموا ولم يبق لهم مكان في السماء،","12:9":"إذ طرحوا إلى الأرض. هذا التنين العظيم هو الحية القديمة، ويسمى إبليس والشيطان الذي يضلل العالم كله.","12:10":"ثم سمعت صوتا عاليا في السماء يقول: «الآن تم خلاص إلهنا، وآلت القدرة والملك إليه والسلطان إلى مسيحه! فإنه قد طرح من السماء إلى الأرض المشتكي الذي يتهم إخوتنا أمام إلهنا ليلا ونهارا.","12:11":"وهم قد انتصروا عليه بدم الحمل وبالكلمة التي شهدوا لها، فلم تكن حياتهم عزيزة لديهم، حتى إنهم ماتوا.","12:12":"افرحي أيتها السماوات، وافرحوا ياأهلها، الويل لكم ياأهل الأرض والبحر، لأن إبليس هبط عليكم وهو في شدة الغضب، عالما أن أيامه صارت معدودة».","12:13":"وعندما وجد التنين أنه طرح إلى الأرض، أخذ يطارد المرأة التي ولدت الطفل الذكر،","12:14":"فأعطيت المرأة جناحي النسر العظيم، لتطير بهما إلى البر ية، إلى المكان المجهز لها، حيث تعال بمأمن من الحية، مدة ثلاث سنوات ونصف سنة.","12:15":"وأخرجت الحية من جوفها خلف المرأة ما يشبه النهر لتغرقها فيه،","12:16":"ولكن الأرض أعانت المرأة، ففتحت فمها وابتلعت النهر الذي أخرجه التنين من فمه!","12:17":"فاغتاظ التنين من المرأة وشن حربا على باقي أولادها الذين يعملون بوصايا الله وعندهم الشهادة ليسوع.","13:1":"ثم رأيت نفسي واقفا على رمل البحر، وإذا وحش خارج من البحر، له سبعة رؤوس وعشرة قرون، على كل قرن منها تاج، وقد كتب على كل رأس اسم تجديف.","13:2":"وبدا هذا الوحش مثل النمر وله قوائم كقوائم دب وفم كفم أسد! وأعطاه التنين قدرته وعرشه وسلطة عظيمة.","13:3":"وبدا واحد من رؤوسه كأنه ذبح ذبحا مميتا، ولكن الجرح المميت شفي، فتعجب سكان الأرض لذلك، وتبعوا الوحش.","13:4":"وسجد الناس للتنين لأنه وهب الوحش سلطته، وعبدوا الوحش وهم يقولون: «من مثل هذا الوحش؟ ومن يجرؤ على محاربته؟»","13:5":"وأعطى التنين الوحش فما ينطق بكلام الكبرياء والتجديف، وأعطاه سلطة العمل مدة اثنين وأربعين شهرا.","13:6":"فأخذ الوحش يشتم اسم الله، ويشتم بيته وسكان السماء.","13:7":"وأعطي الوحش قدرة على أن يحارب القديسين ويهزمهم وسلطة على كل قبيلة وشعب ولغة وأمة.","13:8":"فيسجد للوحش جميع سكان الأرض الذين لم تكتب أسماؤهم منذ تأسيس العالم في سجل الحياة للحمل الذي ذبح.","13:9":"من له أذن فليسمع:","13:10":"من ساق غيره إلى السبي، فإلى السبي سيساق؛ ومن قتل بالسيف، فبالسيف سيقتل! هنا يظهر صبر القديسين وإيمانهم.","13:11":"ثم رأيت وحشا آخر خارجا من الأرض، له قرنان صغيران كقرني خروف، ولكن صوته كصوت تنين،","13:12":"وقد استمد سلطته من الوحش الأول الذي خرج من البحر ليعمل بها في حضوره، فجعل سكان الأرض يسجدون للوحش الأول الذي شفي من جرحه المميت.","13:13":"وقام الوحش الثاني بآيات خارقة، حتى إنه أنزل من السماء نارا على الأرض بمشهد من الناس جميعا،","13:14":"فخدع سكان الأرض بالآيات التي كان يقوم بها في حضور الوحش الأول. وأمر سكان الأرض أن يقيموا تمثالا للوحش الأول الذي كان قد جرح جرحا مميتا ولكنه عاش!","13:15":"وأعطي سلطة على أن يبعث الروح في التمثال لينطق، وأن يمد يده فيقتل كل من يرفض السجود لتمثال الوحش،","13:16":"وأن يأمر الجميع، كبارا وصغارا، أغنياء وفقراء، أحرارا وعبيدا، أن يحملوا علامة على أيديهم اليمنى أو على جباههم،","13:17":"فلا يستطيع أحد أن يبيع أو يشتري إلا إذا كانت عليه علامة الوحش، أو الرقم الذي يرمز لاسمه!","13:18":"ولابد هنا من الفطنة: فعلى أهل المعرفة أن يحسبوا عدد اسم الوحش. إنه عدد لإنسان، وهو الرقم «ست مئة وستة وستون».","14:1":"ثم رأيت حملا واقفا على جبل صهيون ومعه مئة وأربعة وأربعون ألفا كتب على جباههم اسمه واسم أبيه.","14:2":"وسمعت من السماء صوتا أشبه بصوت الشلال الغزير أو دوي الرعد الشديد. وكان الصوت الذي سمعته كأنه صوت منشدين على القيثارات يضربون بقيثاراتهم","14:3":"وكانوا ينشدون ترتيلة جديدة أمام عرش الله، وأمام الكائنات الحية الأربعة والشيوخ. ولم يستطع أحد أن يتعلم هذه الترتيلة إلا المئة والأربعة والأربعون ألفا المشترون من الأرض،","14:4":"فهؤلاء لم ينجسوا أنفسهم مع النساء لأنهم أطهار، وهم يتبعون الحمل حيثما ذهب، وقد تم شراؤهم من بين الناس باكورة لله، وللحمل،","14:5":"لم تنطق أفواههم بالكذب، ولا عيب فيهم.","14:6":"ثم رأيت ملاكا آخر يطير في وسط السماء، معه بشارة أبدية يبشر بها أهل الأرض وكل أمة وقبيلة ولغة وشعب،","14:7":"وهو ينادي عاليا: «اتقوا الله ومجدوه، فقد حانت ساعة دينونته. اسجدوا لمن خلق السماء والأرض والبحر والينابيع».","14:8":"وتبعه ملاك ثان يقول: «سقطت، سقطت بابل العظمى التي سقت أمم العالم من خمر زناها الجالبة للغضب!»","14:9":"ثم تبعهما ملاك ثالث ينادي بصوت عال: «جميع الذين سجدوا للوحش ولتمثاله، وقبلوا علامته على أيديهم أو على جباههم،","14:10":"فلابد لهم، في حضرة الملائكة القديسين وفي حضرة الحمل، من أن يشربوا من خمر الغضب غير المخففة، المسكوبة في كأس غضب الله، فيكابدوا عذاب النار والكبريت المتقد،","14:11":"ويتصاعد دخان عذابهم إلى أبد الآبدين. لا راحة في النهار ولا في الليل للذين عبدوا الوحش وسجدوا لتمثاله وقبلوا علامة اسمه.","14:12":"وهنا يظهر صبر القديسين الذين يحافظون على وصايا الله والإيمان بيسوع!»","14:13":"وسمعت صوتا من السماء يقول: «اكتب: طوبى للأموات الذين يموتون منذ الآن وهم في الرب! يقول الروح: نعم! فليستريحوا من متاعبهم، لأن أعمالهم ترافقهم».","14:14":"ثم نظرت، فرأيت سحابة بيضاء، يجلس عليها كائن يشبه ابن الإنسان، على رأسه إكليل من ذهب، وفي يده منجل حاد.","14:15":"وخرج ملاك آخر من الهيكل يناديه بصوت عال: «أرسل منجلك ليحصد، فقد حلت ساعة الحصاد ونضج حصاد الأرض».","14:16":"فألقى الجالس على السحابة منجله على الأرض فحصدت الأرض.","14:17":"ثم خرج ملاك آخر من الهيكل الذي في السماء، ومعه أيضا منجل حاد.","14:18":"ومن المذبح خرج ملاك آخر له السلطة على النار، ونادى بصوت عظيم الملاك الذي يمسك المنجل الحاد: «أرسل منجلك الحاد واقطف عناقيد كرم الأرض لأن عنبها قد نضج».","14:19":"فألقى الملاك منجله إلى الأرض وقطف العناقيد وألقاها في معصرة غضب الله العظمى،","14:20":"فديست المعصرة بالأرجل خارج المدينة، فانبثق منها الدم وجرى أنهارا حتى إلى لجم الخيل، مسافة ثلثمائة وعشرين كيلومترا.","15:1":"ثم رأيت في السماء آية أخرى عظيمة وعجيبة: سبعة ملائكة مكلفين أن ينزلوا بالأرض البلايا السبع الأخيرة التي بها يكتمل غضب الله.","15:2":"ورأيت أيضا ما يشبه بحرا من زجاج تختلط به النار، وقد وقف عليه جميع الذين انتصروا على الوحش وتمثاله ورقم اسمه، وهم يحملون قيثارات الله،","15:3":"وينشدون ترتيلة موسى، عبد الله وترتيلة الحمل قائلين: «عظيمة وعجيبة أعمالك أيها الرب الإله القادر على كل شيء، عادلة ومستقيمة طرقك ياملك الدهور.","15:4":"من لا يخافك يارب ولا يمجد اسمك؟ فأنت وحدك قدوس! والأمم جميعا سيأتون ويسجدون لك، لأن أحكامك قد ظهرت جلية».","15:5":"وبعد ذلك نظرت، فرأيت هيكل خيمة الشهادة في السماء وقد انفتح،","15:6":"وخرج منه الملائكة السبعة المكلفون بإنزال البلايا السبع الأخيرة بالأرض، وهم يرتدون ثيابا من كتان خالص براق، ويشدون صدورهم بأحزمة من ذهب.","15:7":"وسلم واحد من الكائنات الحية الأربعة هؤلاء الملائكة السبعة سبع كؤوس من ذهب مملوءة بغضب الله الحي إلى أبد الآبدين.","15:8":"وامتلأ الهيكل دخانا من مجد الله وقدرته، فلم يستطع أحد أن يدخل الهيكل، حتى ينتهي الملائكة السبعة من إنزال البلايا السبع بالأرض.","16:1":"وسمعت صوتا عاليا صادرا من الهيكل يأمر الملائكة السبعة: «اذهبوا الآن واسكبوا على الأرض كؤوس غضب الله السبع».","16:2":"فذهب الملاك الأول وسكب كأسه على الأرض، فخرجت منها قروح خبيثة أصابت جميع الناس الذين عليهم علامة الوحش والذين يسجدون لتمثاله.","16:3":"ثم سكب الملاك الثاني كأسه على البحر، فصار دما كدم الميت، وماتت جميع المخلوقات الحية التي فيه.","16:4":"وسكب الملاك الثالث كأسه على الأنهار وينابيع المياه، فصار ت كلها دما.","16:5":"وسمعت ملاك المياه يقول: «عادل أنت في أحكامك، أيها الإله القدوس، الكائن والذي كان،","16:6":"فقد سفك الناس دم قديسين وأنبياء، وها أنت تسقي قاتليهم دما! إنهم ينالون ما يستحقون!»","16:7":"وسمعت ملاك المذبح يقول: «إن أحكامك حق وعدل أيها الرب الإله القادر على كل شيء».","16:8":"وسكب الملاك الرابع كأسه على الشمس، فأعطيت الشمس أن تحرق الناس بنار،","16:9":"فاحترق الناس من الحر الشديد. ولكنهم لم يتوبوا ليمجدوا الله ، بل جدفوا على اسم الله صاحب السلطة على هذه البلايا.","16:10":"ثم سكب الملاك الخامس كأسه على عرش الوحش، فحل بمملكته ظلام دامس، جعل أتباعه يعضون ألسنتهم من الألم.","16:11":"غير أنهم لم يتوبوا عن أعمالهم الشريرة، بل جدفوا على إله السماء لما يعانون من آلام وقروح!","16:12":"وسكب الملاك السادس كأسه على نهر «الفرات» الكبير فجف ماؤه، ليصير ممرا للملوك القادمين من الشرق.","16:13":"وعند هذا رأيت ثلاثة أرواح نجسة تشبه الضفادع تخرج من فم التنين، ومن فم الوحش، ومن فم النبي الدجال،","16:14":"وهي أرواح شيطانية قادرة على صنع المعجزات، تذهب إلى ملوك الأرض جميعا وتجمعهم للحرب في ذلك اليوم العظيم، يوم الله القادر على كل شيء.","16:15":"»ها أنا آت كما يأتي اللص، طوبى لمن يكون بانتظاري، ساهرا وحارسا لثيابه، لئلا يمشي عريانا فيرى الناس عورته!«","16:16":"وجمعت الأرواح الشيطانية جيوش العالم كلها في مكان يسمى بالعبرية «هرمجدون».","16:17":"ثم سكب الملاك السابع كأسه على الهواء، فدوى صوت من العرش في الهيكل السماوي يقول: «قد تم!»","16:18":"فحدثت بروق وأصوات ورعود وزلزال عنيف لم تشهد الأرض له مثيلا منذ وجد الإنسان على الأرض، لأنه كان زلزالا عنيفا جدا!","16:19":"فانقسمت المدينة العظمى إلى ثلاثة أقسام، وحل الدمار بمدن الأمم. فقد ذكر الله بابل العظمى ليسقيها كأسا تفور بخمر غضبه.","16:20":"وهربت الجزر كلها، واختفت الجبال.","16:21":"وتساقط من السماء على الناس برد كبير، كل حبة منه بمقدار وزنة واحدة، فجدف الناس على الله بسبب هذه البلية الشديدة جدا.","17:1":"وجاء واحد من الملائكة السبعة حاملي الكؤوس السبع وقال لي: «تعال فأريك عقاب الزانية الكبرى الجالسة على المياه الكثيرة،","17:2":"والتي زنى معها ملوك الأرض، وسكر أهل الأرض من خمر زناها».","17:3":"وحملني الملاك بالروح إلى البرية، فرأيت امرأة راكبة على وحش قرمزي له سبعة رؤوس وعشرة قرون، وقد كتبت على جسمه كله أسماء تجديف.","17:4":"وكانت المرأة تلبس ملابس من أرجوان وقرمز، وتتحلى بالذهب والحجارة الكريمة واللؤلوء، وقد أمسكت كأس ذهب مملوءة بزناها المكروه النجس،","17:5":"وعلى جبينها اسم مكتوب: سر: «بابل العظمى، أم زانيات الأرض وأصنامها المكروهة».","17:6":"ورأيت المرأة سكرى لكثرة ما شربت من دم القديسين، ودم شهداء يسوع الذين قتلتهم. فتملكتني الدهشة لمنظرها،","17:7":"فسألني الملاك: «لماذا دهشت؟ سأطلعك على ما ترمز إليه المرأة والوحش الذي يحملها، صاحب الرؤوس السبعة والقرون العشرة:","17:8":"هذا الوحش كان موجودا، وهو غير موجود الآن، ولكنه على وشك أن يطلع من الهاوية ويمضي إلى الهلاك. وسيدهش سكان الأرض الذين لم تكتب أسماؤهم منذ تأسيس العالم في سجل الحياة، عندما يرون الوحش، لأنه كان موجودا، ثم أصبح غير موجود، وسيعود!","17:9":"«ولابد هنا من فطنة العقل: الرؤوس السبعة ترمز إلى التلال السبعة التي تجلس المرأة عليها وترمز أيضا إلى سبعة ملوك،","17:10":"خمسة منهم مضوا، والسادس يحكم الآن، والسابع سيأتي، ولكن مدة حكمه ستكون قصيرة.","17:11":"أما الوحش الذي كان موجودا ثم أصبح غير موجود، فهو ملك ثامن سبق أن ملك كواحد من السبعة، سيمضي إلى الهلاك.","17:12":"وأما القرون العشرة التي رأيت هي عشرة ملوك لم يتولوا الملك بعد، وسيتولون سلطة الملك مع الوحش لمدة ساعة واحدة،","17:13":"يتفقون فيها برأي واحد أن يعطوا الوحش قوتهم وسلطتهم.","17:14":"ثم يحاربون الحمل، ولكن الحمل يهزمهم، لأنه رب الأرباب وملك الملوك، والذين معه هم المدعوون، المختارون، المؤمنون».","17:15":"ثم قال لي الملاك: «أما الميا ه التي رأيت حيث تجلس الزانية، فترمز إلى شعوب وجماهير وأمم ولغات.","17:16":"وأما القرون العشرة التي رأيتها، والوحش، فسيبغضون الزانية ويجعلونها معزولة وعارية، ويأكلون لحمها ويحرقونها بالنار،","17:17":"لأن الله جعل في قلوبهم أن يعملوا وفق قصده، فيتفقوا على أن يعطوا الوحش ملكهم، حتى تتم كلمات الله.","17:18":"أما هذه المرأة التي رأيتها، فإنها ترمز إلى المدينة العظمى التي تحكم ملوك الأرض».","18:1":"بعد هذا رأيت ملاكا آخر نازلا من السماء، له سلطان عظيم، أضاء بهاؤه الأرض.","18:2":"وصاح بأعلى صوته: «سقطت، سقطت بابل العظمى، وصارت وكرا للشياطين ومأوى لكل روح نجس ولكل طائر نجس مكروه،","18:3":"لأن جميع الأمم شربت من خمر زناها، وملوك الأرض زنوا معها، وتجار الأرض اغتنوا من كثرة ترفها!»","18:4":"ثم سمعت صوتا آخر ينادي من السماء: «اخرجوا منها ياشعبي، لئلا تشتركوا في خطاياها، فتصابوا ببلاياها،","18:5":"فقد تراكمت خطاياها حتى بلغت السماء، وتذكر الله ما ارتكبته من آثام!","18:6":"افعلوا بها كما فعلت بكم، وضاعفوا لها جزاء ما اقترفت. في الكأس التي مزجت فيها للآخرين، امزجوا لها ضعفا.","18:7":"أنزلوا بها من العذاب والشقاء على قدر ما عظمت نفسها وترفهت. فإنها تقول في نفسها: أنا ملكة على العرش، ولست أرملة، ولن أذوق طعم الحزن.","18:8":"لذلك ستنقض عليها البلايا في يوم واحد، من موت وحزن وجوع، وستحترق بالنار، فإن الله الذي يدينها هو رب قدير.","18:9":"وسيبكي عليها ملوك الأرض الذين زنوا وترفهوا معها، وسينوحون وهم ينظرون إلى دخان حريقها،","18:10":"فيقفون على بعد منها، خوفا من عذابها، وهم يصرخون: الويل، الويل، أيتها المدينة العظمى، بابل القوية! في ساعة واحدة حل بك العقاب!","18:11":"وسيبكي تجار الأرض ويحزنون عليها، لأنه لم يبق أحد ليشتري بضائعهم،","18:12":"فقد كانت هي تشتري منهم الذهب والفضة والحجارة الكريمة واللؤلؤ، والكتان والأرجوان والحرير والقرمز، وجميع الأخشاب العطرة وأدوات العاج والمصنوعات الخشبية الثمينة، والنحاس والحديد والرخام،","18:13":"والقرفة والبهار، والعطور والطيب والبخور، والخمر والزيت والدقيق والحبوب، والبهائم والغنم، والخيل والمركبات، والأجساد والنفوس البشرية","18:14":"وسيقولون: مضى عنك الثمر الذي كانت تشتهيه نفسك؛ وزالت عنك مظاهر الترف والعظمة كلها، ولن تعود!","18:15":"هؤلاء التجار الذين اغتنوا من التجارة معها، يقفون على بعد منها، خوفا من عذابها، يبكون وينتحبون","18:16":"قائلين: الويل، الويل على المدينة العظمى! كانت ترتدي أفضل الكتان والأرجوان والقرمز، وتتحلى بالذهب والأحجار الكريمة واللؤلوء،","18:17":"وقد زال هذا الغنى كله في ساعة واحدة!","18:18":"ينظرون إلى دخان حريقها، فيصرخون: أية مدينة مثل هذه المدينة العظمى؟","18:19":"ويذرون التراب على رؤوسهم وهم يصرخون باكين منتحبين: الويل، الويل على المدينة العظمى التي اغتنى أصحاب سفن البحر جميعا بفضل ثروتها! ها هي في ساعة واحدة قد زالت!","18:20":"اشمتي بها أيتها السماء! واشمتوا بها أيها القديسون والرسل والأنبياء، فقد أصدر الله حكمه عليها بعدما أصدرت أحكامها عليكم».","18:21":"وتناول ملاك قوي حجرا كأنه حجر طاحونة عظيم وألقاه في البحر قائلا: «هكذا تدفع وتطرح بابل المدينة العظمى، فتختفي إلى الأبد!","18:22":"لن يسمع فيك عزف موسيقى بعد، لا صوت قيثارة ولا مزمار ولا بوق، ولن تقوم فيك صناعة بعد الآن، ولن يسمع فيك صوت رحى","18:23":"ولن يضيء فيك نور مصباح. ولن يسمع فيك صوت عريس وعروس. فقد كان تجارك سادة الأرض، وبسحرك ضللت جميع الأمم.","18:24":"وفيها وجدت دماء أنبياء وقديسين وجميع الذين قتلوا على الأرض».","19:1":"وبعد هذا سمعت صوتا عاليا كأنه صادر من جمع كبير في السماء يقول: «هللويا! الخلاص والمجد والكرامة والقدرة للرب إلهنا","19:2":"فإن أحكامه حق وعدل، لأنه عاقب الزانية الكبرى التي أفسدت الأرض، وانتقم لدم عبيده منها».","19:3":"وهتفوا ثانية: «هللويا! دخان حريقها يتصاعد إلى أبد الآبدين!»","19:4":"وجثا الشيوخ الأربعة والعشرون والكائنات الحية الأربعة سجودا لله الجالس على العرش، وهتفوا: «آمين! هللويا!»","19:5":"وخرج من العرش صوت يقول: «سبحوا إلهنا ياجميع عبيده الذين يتقونه صغارا وكبارا!»","19:6":"ثم سمعت صوتا كأنه صوت جمع كبير أو شلال غزير أو رعد شديد، يقول: «هللويا! فإن الرب الإله القادر على كل شيء قد ملك،","19:7":"لنفرح ونبتهج ونمجده، فإن عرس الحمل قد حان موعده، وعروسه قد هيأت نفسها،","19:8":"ووهب لها أن تلبس الكتان الأبيض الناصع!» والكتان يرمز إلى أعمال الصلاح التي قام بها القديسون.","19:9":"وأملى علي الملاك أن أكتب: «طوبى للمدعوين إلى وليمة عرس الحمل». ثم قال: «الله نفسه يقول هذا القول الحق».","19:10":"فجثوت عند قدميه لأسجد له، فقال لي: «لا تفعل! إني عبد لله، مثلك ومثل إخوتك المؤمنين الذين لديهم الشهادة المختصة بيسوع: لله اسجد! فإن الشهادة المختصة بيسوع هي روح النبوءة».","19:11":"ثم رأيت السماء مفتوحة، وإذا حصان أبيض يسمى راكبه «الأمين الصادق» الذي يقضي ويحارب بالعدل.","19:12":"عيناه كلهيب نار، وعلى رأسه أكاليل كثيرة، وقد كتب على جبهته اسم لا يعرفه أحد إلا هو.","19:13":"وكان يرتدي ثوبا مغمسا بالدم؛ أما اسمه فهو «كلمة الله»","19:14":"وكان الأجناد الذين في السماء يتبعونه راكبين خيولا بيضاء، ولابسين كتانا نقيا ناصع البياض،","19:15":"وكان يخرج من فمه سيف حاد ليضرب به الأمم ويحكمهم بعصا من حديد، ويدوسهم في معصرة شدة غضب الله القادر على كل شيء.","19:16":"وقد كتب على ثوبه وعلى فخذه «ملك الملوك ورب الأرباب».","19:17":"ثم رأيت ملاكا واقفا في الشمس، ينادي الطيور الطائرة في وسط السماء بصوت عال قائلا: «هلمي اجتمعي معا إلى وليمة الله الكبرى!","19:18":"تعالي والتهمي لحوم الملوك والقادة والأبطال، والخيول وفرسانها، ولحوم البشر جميعا من أحرار وعبيد، وصغار وكبار».","19:19":"ورأيت الوحش وملوك الأرض وجيوشهم وقد احتشدوا ليحاربوا هذا الفارس وجيشه.","19:20":"فقبض على الوحش وعلى النبي الدجال الذي قام بالمعجزات في حضور الوحش وأضل بها الذين قبلوا علامة الوحش، وسجدوا لتمثاله. وطرح كلاهما حيا في بحيرة النار والكبريت المتقدة،","19:21":"وقتل السيف الخارج من فم الفارس جميع الباقين، وشبعت الطيور كلها من لحومهم.","20:1":"ثم رأيت ملاكا نازلا من السماء، وبيده مفتاح الهاوية وسلسلة عظيمة","20:2":"قيد بها التنين، أي الحية القديمة، وهو إبليس أو الشيطان، وسجنه مدة ألف سنة،","20:3":"وطرحه في الهاوية وأغلقها عليه، وختمها، حتى يكف عن تضليل الأمم، إلى أن تنقضي الألف سنة. ولكن لابد من إطلاقه بعد ذلك لمدة قصيرة.","20:4":"ثم رأيت عروشا منح الجالسون عليها حق القضاء. ورأيت نفوس الذين قتلوا في سبيل الشهادة ليسوع وفي سبيل كلمة الله، والذين رفضوا أن يسجدوا للوحش ولتمثاله، والذين رفضوا علامته على أيديهم وجباههم، وقد عادوا إلى الحياة، وملكوا مع المسيح ألف سنة.","20:5":"هذه هي القيامة الأولى. أما بقية الأموات فلا يعودون إلى الحياة حتى تنقضي الألف سنة.","20:6":"ما أسعد وأقدس من كان لهم نصيب في القيامة الأولى! لن يكون للموت الثاني سلطة عليهم، بل يكونون كهنة لله والمسيح، ويملكون معه ألف سنة.","20:7":"فحين تنقضي الألف سنة، يطلق الشيطان من سجنه،","20:8":"فيخرج ليضلل الأمم في زوايا الأرض الأربع، جوج وماجوج، ويجمعهم للقتال، وعددهم كثير جدا كرمل البحر!","20:9":"فيصعدون على سهول الأرض العريضة، ويحاصرون من كل جانب معسكر القديسين والمدينة المحبوبة، ولكن نارا من السماء تنزل عليهم وتلتهمهم.","20:10":"ثم يطرح إبليس الذي كان يضللهم، في بحيرة النار والكبريت، حيث الوحش والنبي الدجال. هناك سوف يعذبون نهارا وليلا، إلى أبد الآبدين.","20:11":"ثم رأيت عرشا عظيما أبيض هربت السماء والأرض من أمام الجالس عليه، فلم يبق لهما مكان.","20:12":"ورأيت الأموات، كبارا وصغارا، واقفين قدام العرش. وفتحت الكتب، ثم فتح كتاب آخر هو سجل الحياة، ودين الأموات بحسب ما هو مدون في تلك الكتب، كل واحد حسب أعماله.","20:13":"وسلم البحر من فيه من الأموات، وسلم الموت وهاوية الموتى الأموات الذين فيهما، وحكم على كل واحد بحسب أعماله.","20:14":"وطرح الموت وهاوية الموتى في بحيرة النار، الذي هو الموت الثاني.","20:15":"وكل من لم يوجد اسمه مكتوبا في سجل الحياة طرح في بحيرة النار!","21:1":"ثم رأيت سماء جديدة وأرضا جديدة لا بحر فيها، لأن السماء والأرض القديمتين قد زالتا.","21:2":"وأنا رأيت المدينة المقدسة، أورشليم الجديدة، نازلة من السماء من عند الله، مجهزة كأنها عروس مزينة لعريسها.","21:3":"وسمعت صوتا هاتفا من العرش: «الآن صار مسكن الله مع الناس، هو يسكن بينهم، وهم يصيرون شعبا له. الله نفسه يكون معهم إلها لهم!","21:4":"وسيمسح كل دمعة من عيونهم. إذ يزول الموت والحزن والصراخ والألم، لأن الأمور القديمة كلها قد زالت!»","21:5":"وقال الجالس على العرش: «سأصنع كل شيء جديدا». ثم قال لي: «اكتب هذا، فإن ما أقوله هو الصدق والحق».","21:6":"ثم قال: «قد تم. أنا الألف والياء (البداية والنهاية). أنا أسقي العطشان من ينبوع ماء الحياة مجانا.","21:7":"هذا كله نصيب المنتصر، وأكون إلها له، وهو يكون ابنا لي.","21:8":"أما الجبناء وغير المؤمنين، والفاسدون والقاتلون والزناة، والمتصلون بالشياطين وعبدة الأصنام وجميع الدجالين، فمصيرهم إلى البحيرة المتقدة بالنار والكبريت، الذي هو الموت الثاني».","21:9":"وجاء أحد الملائكة السبعة الذين أفرغوا كؤوس بلاياهم السبع الأخيرة، وقال لي: «تعال فأريك عروس الحمل».","21:10":"وأخذني بالروح إلى قمة جبل ضخم عال، وأراني المدينة المقدسة أورشليم نازلة من السماء من عند الله","21:11":"ولها مجد الله، وهي تتلألأ كالأحجار الكريمة، وكأنها من حجر اليشب البلوري!","21:12":"لها سور ضخم عال واثنا عشر بابا يحرسها اثنا عشر ملاكا، وقد كتبت عليها أسماء أسباط إسرائيل الاثني عشر؛","21:13":"إلى الشرق ثلاثة أبواب؛ وإلى الشمال ثلاثة أبواب، وإلى الجنوب ثلاثة أبواب؛ وإلى الغرب ثلاثة أبواب.","21:14":"ويقوم سور المدينة على اثنتي عشرة دعامة كتبت عليها أسماء رسل الحمل الاثني عشر.","21:15":"وكان الملاك الذي يكلمني يمسك قصبة من الذهب ليقيس بها المدينة وأبوابها وسورها.","21:16":"وكانت أرض المدينة مربعة، طولها يساوي عرضها، فلما قاسها بالقصبة تبين أن ضلعها يساوي ألفين وأربعمئة كيلومتر، وهي متساوية الطول والعرض والارتفاع.","21:17":"ثم قاس السور، فتبين أنه يساوي مئة وأربعا وأربعين ذراعا، وكان الملاك يستعمل قياسا يعادل ذراع إنسان.","21:18":"كانت المدينة مبنية من ذهب خالص شفاف كالزجاج النقي. أما سورها فمن اليشب،","21:19":"وهو قائم على اثنتي عشرة دعامة مرصعة بالأحجار الكريمة: كانت الدعامة الأولى من اليشب؛ والثانية من الياقوت الأزرق؛ والثالثة من العقيق الأبيض؛ والرابعة من الزمرد الذبابي؛","21:20":"والخامسة من الجزع العقيقي؛ والسادسة من العقيق الأحمر؛ والسابعة من الزبرجد؛ والثامنة من الزمرد السلقي؛ والتاسعة من الياقوت الأصفر، والعاشرة من العقيق الأخضر؛ والحادية عشرة من الأسمانجوني؛ والثانية عشرة من الجمشت.","21:21":"أما الأبواب الاثنا عشر فهي اثنتا عشرة لؤلؤة: كل باب لؤلؤة واحدة. وساحة المدينة من ذهب خالص كالزجاج الشفاف.","21:22":"ولم أجد في المدينة هيكلا، لأن الرب الإله القادر على كل شيء والحمل هما هيكلها.","21:23":"ولم تكن المدينة في حاجة إلى نور الشمس أو القمر، لأن مجد الله ينيرها، والحمل مصباحها.","21:24":"ستسير بنورها الأمم، ويأتيها ملوك الأرض بكنوزهم.","21:25":"ولا تقفل أبوابها أبدا طول النهار، لأن الليل لا يأتي عليها!","21:26":"وستحمل إليها كنوز الأمم وأمجادها.","21:27":"ولن يدخلها شيء نجس، ولا الذين يعملون القبائح ويدجلون، بل فقط الذين كتبت أسماؤهم في سجل الحياة للحمل!","22:1":"ثم أراني الملاك نهر ماء الحياة صافيا كالبلور، ينبع من عرش الله والحمل","22:2":"ويخترق ساحة المدينة، وعلى ضفتيه شجرة الحياة تثمر اثنتي عشرة مرة، كل شهر مرة. وأوراقها دواء يشفي الأمم.","22:3":"لن تكون فيما بعد لعنة أبدا. لأن عرش الله والحمل قائم في المدينة، حيث يخدمه عبيده","22:4":"ويرون وجهه، وقد كتب اسمه على جباههم.","22:5":"ولن يكون هنالك ليل، فلا يحتاجون إلى نور مصباح أو شمس، لأن الرب الإله ينير عليهم، وهم سيملكون إلى أبد الآبدين!","22:6":"وقال لي الملاك: «هذا الكلام صدق وحق. إن الرب إله أرواح الأنبياء أرسل ملاكه ليخبر عبيده بما لا بد أن يحدث سريعا","22:7":"إني آت سريعا! طوبى لمن يراعي ما ورد في كتاب النبوءة هذا!»","22:8":"أنا يوحنا رأيت وسمعت هذه الأمور كلها. وبعدما سمعت ورأيت كل ما حدث، ارتميت على قدمي الملاك الذي أراني إياها لأسجد له.","22:9":"فقال لي: «لا تفعل! إنني عبد مثلك ومثل إخوتك الأنبياء، ومثل الذين يراعون ما جاء في هذا الكتاب. لله اسجد!»","22:10":"ثم قال لي: «لا تختم على ما جاء في كتاب النبوءة هذا، لأن موعد إتمامه قد اقترب.","22:11":"فمن كان ظالما، فليمعن في الظلم؛ ومن كان نجسا، فليمعن في النجاسة؛ ومن كان صالحا، فليمعن في الصلاح؛ ومن كان مقدسا، فليمعن في القداسة!»","22:12":"إني آت سريعا، ومعي المكافأة لأجازي كل واحد بحسب عمله.","22:13":"أنا الألف والياء، الأول والآخر، البداية والنهاية.","22:14":"طوبى للذين يغسلون ثيابهم، فلهم السلطة على شجرة الحياة، والحق في دخول المدينة من الأبواب!","22:15":"أما في خارج المدينة، فهنالك الكلاب والمتصلون بالشياطين، والزناة والقتلة، وعبدة الأصنام والدجالون ومحبو التدجيل!","22:16":"أنا يسوع أرسلت ملاكي لأشهد لكم بهذه الأمور في الكنائس. أنا أصل داود ونسله. أنا كوكب الصبح المنير».","22:17":"الروح والعروس يقولان: «تعال!» ومن يسمع فليردد النداء: «تعال!»","22:18":"وإنني أشهد لكل من يسمع ما جاء في كتاب النبوءة هذا: إن زاد أحد شيئا على ما كتب فيه، يزيده الله من البلايا التي ورد ذكرها،","22:19":"وإن أسقط أحد شيئا من أقوال كتاب النبوءة هذا، يسقط الله نصيبه من شجرة الحياة، ومن المدينة المقدسة، اللتين جاء ذكرهما في هذا الكتاب.","22:20":"والذي يشهد بهذه الأمور يقول: «نعم! أنا آت سريعا».","22:21":"ولتكن نعمة ربنا يسوع المسيح معكم جميعا."},"Zep":{"1:1":"هذه كلمة الرب التي أوحى بها إلى صفنيا بن كوشي بن جدليا بن أمريا بن حزقيا، في عهد حكم يوشيا بن آمون ملك يهوذا.","1:2":"يقول الرب: «سأمحو محوا كل شيء عن وجه الأرض.","1:3":"أبيد الإنسان والحيوان وطيور السماء وسمك البحر، وأقضي على الأشرار ومعاثرهم، وأستأصل البشر عن وجه الأرض، يقول الرب.","1:4":"أمد يدي لأعاقب يهوذا وكل أهل أورشليم، وأفني من هذا الموضع بقية عبدة البعل، وكل كهنة الوثن.","1:5":"والذين يصعدون إلى السطوح للسجود لكواكب السماء، والذين يجثون عابدين الرب حالفين باسمه، وباسم ملكوم أيضا.","1:6":"والذين ارتدوا عن اتباع الرب، والذين كفوا عن طلبه والتماسه.","1:7":"اصمتوا في محضر السيد الرب لأن يوم الرب بات وشيكا. قد أعد الرب ذبيحة وقدس مدعويه.","1:8":"فيكون في يوم ذبيحة الرب أني أعاقب الرؤساء وأبناء الملك وكل من يرتدي ثيابا غريبة وثنية.","1:9":"وأعاقب في ذلك اليوم كل الذين يقفزون من فوق عتبة الهيكل (على غرار كهنة داجون)، الذين يملأون بيت سيدهم جورا ونهبا.","1:10":"ويقول الرب: في ذلك اليوم تتردد صرخة من باب السمك وولولة من الحي الثاني، ويدوي صوت تحطيم في التلال.","1:11":"ولولوا ياسكان دائرة السوق، لأن تجاركم يبيدون، وكل المتاجرين بالفضة قد استؤصلوا.","1:12":"في ذلك الوقت أفتش أورشليم بمصباح، وأعاقب الناس المتربعين فوق قاذوراتهم، القائلين في قلوبهم: إن الرب لا يضر ولا ينفع.","1:13":"فتصبح ثروتهم غنيمة، وبيوتهم خرابا. يشيدون بيوتا ولا يسكنون فيها، ويغرسون كروما ولا يشربون من خمرها.","1:14":"إن يوم الرب العظيم قريب، وشيك وسريع جدا. دوي يوم الرب مخيف، فيه يصرخ الجبار مرتعبا.","1:15":"يوم غضب هو ذلك اليوم، يوم ضيق وعذاب، يوم خراب ودمار، يوم ظلمة واكتئاب، يوم غيوم وقتام.","1:16":"يوم دوي بوق وصيحة قتال ضد المدن الحصينة والبروج الشامخة.","1:17":"فيه أضايق الناس فيمشون كالعمي، لأنهم أخطأوا بحق الرب، فتنسكب دماؤهم كالتراب، ولحمهم يتناثر كالجلة.","1:18":"لا ينقذهم ذهبهم ولا فضتهم في يوم غضب الرب، إذ بنار غيرته تلتهم كل الأرض، وفيه يضع نهاية مباغتة كاملة سريعة لكل سكان المعمورة».","2:1":"«اجتمعي، احتشدي أيتها الأمة الوقحة.","2:2":"قبل أن يحين القضاء، فيطوح بك كالعصافة أمام الريح، قبل أن يحل بك غضب الرب الماحق، قبل أن ينصب عليك سخط الرب.","2:3":"التمسوا الرب ياودعاء الأرض الراضخين لحكمه. اطلبوا البر والتواضع لعلكم تجدون ملاذا في يوم سخط الرب.","2:4":"فإن غزة تصبح مهجورة، وأشقلون موحشة، وأهل أشدود يطردون عند الظهيرة، وعقرون تستأصل.","2:5":"ويل لكم ياأهل ساحل البحر، أمة الكريتيين. إن قضاء الرب منصب عليكم ياسكان كنعان أرض الفلسطينيين. سأدمرك حتى لا يبقى فيك مقيم.","2:6":"وأنت ياأرض ساحل البحر تصبحين مراعي ومروجا للرعاة وحظائر للمواشي.","2:7":"ويصبح ساحل البحر ملكا لبقية بيت يهوذا فيرعون فيه قطعانهم، ويرقدون في المساء في بيوت أشقلون، لأن الرب إلههم يفتقدهم ويرد سبيهم.","2:8":"قد سمعت تعيير موآب وتجاديف بني عمون، وكيف احتقروا شعبي وهددوا تخمهم.","2:9":"لذلك، كما أنا حي، يقول الرب القدير إله إسرائيل، ليصبحن أهل موآب كسدوم، والعمونيون كعمورة، منبتا للقريص وحفرة للملح وخرابا إلى الأبد، وتنهبهم بقية شعبي ويمتلكهم الناجون من أمتي.","2:10":"هذا ما يجنونه لقاء تشامخهم، لأنهم احتقروا وتباهوا على شعب الرب القدير.","2:11":"سيكون الرب مثار رعبهم حين يحطم جميع آلهة الأرض، فيسجد له آنئذ جميع الناس، كل في موضعه، في كل ديار المسكونة.","2:12":"وأنتم أيضا أيها الكوشيون ستسقطون صرعى سيفي.","2:13":"ثم يبسط يده نحو الشمال ويبيد أشور ويجعل نينوى قفرا موحشا، أرضا قاحلة كالصحراء.","2:14":"تربض في وسطها القطعان وسائر وحوش البر، ويأوي إلى تيجان أعمدتها القوق والقنفذ وينعب الغراب على عتباتها، لأن أرزها قد تعرى.","2:15":"هذه هي المدينة الطروب التي سكنت آمنة قائلة لنفسها: أنا وليس لي نظير! كيف صارت أطلالا، ومأوى للوحوش البرية؟ كل من يجتاز بها يصفر دهشة ويهز يده».","3:1":"ويل للمدينة الظالمة المتمردة الدنسة،","3:2":"التي لا تصغي لصوت أحد، وتأبى التقويم، ولا تتكل على الرب، ولا تتقرب من إلهها.","3:3":"رؤساؤها في داخلها أسود زائرة، وقضاتها كذئاب المساء الجائعة التي لا تبقي شيئا من فرائسها إلى الصباح.","3:4":"أنبياؤها مغرورون وخونة، وكهنتها يدنسون المقدس ويتعدون على الشريعة.","3:5":"ولكن الرب ما برح صديقا في وسطها، لا يرتكب خطأ، ويبدي في كل صباح عدله وفي كل فجر حقه. لا يخفق قط؛ أما الأثيم فلا يعرف ما هو الخزي.","3:6":"استأصلت أمما فغدت بروجهم أطلالا. أقفرت شوارعهم فلا يعبر بها أحد. صارت مدنهم خرابا لا يقيم فيها إنسان أو ساكن.","3:7":"فقلت: لو إن أهلها يخافونني ويقبلون تقويمي، فلا تستأصل مساكنهم ولا ينصب عليهم كل غضبي. ولكنهم جدوا مبكرين بارتكاب الفساد في كل عمل أقدموا عليه.","3:8":"لذلك يقول الرب: انتظروني لأني عزمت في اليوم الذي أقوم فيه كشاهد أن أجمع الأمم وأحشد الممالك لأسكب عليهم سخطي واحتدام غضبي، لأن الأرض بكاملها ستؤكل بنار غيرة غيظي.","3:9":"عندئذ أنقي شفاه الشعب ليدعوا جميعهم باسم الرب ويعبدوه جنبا إلى جنب.","3:10":"فيقرب إلي شعبي المشتت ذبيحة من وراء أنهار كوش حيث يقيم المتضرعون إلي.","3:11":"في ذلك اليوم لن يلحقكم العار من جراء ما ارتكبتم من أعمال تمردتم بها علي، لأني سأزيل آنئذ من وسطكم المستخفين المتكبرين، فلا يبقى متشامخ في جبلي المقدس.","3:12":"إنما أبقي بينكم شعبا متواضعا فقيرا يتوكلون على اسم الرب.","3:13":"ولن يرتكب بقية إسرائيل الإثم، ولا ينطقون بالكذب، وليس في أفواههم غش، بل يعيشون آمنين من غير أن يهددهم أحد.","3:14":"اشدي ياابنة صهيون واهتف ياإسرائيل، ابتهجي وتهللي ياابنة أورشليم.","3:15":"لأن الرب قد رفع عنك حكم قضائه ورد عنك أعداءك. إن الرب ملك إسرائيل هو في وسطك، فلا تخشي شرا في ما بعد.","3:16":"ويقال في ذلك اليوم لأورشليم: لا تخافي ياصهيون، ولا ترتخ يداك.","3:17":"فالرب إلهك في وسطك، جبار يخلص. يسر فرحا بك، ويجدد بمحبته حياتك، ويبتهج بك مترنما.","3:18":"وكما في يوم موسم عيد، أزيل عنك بلاياك، فلا تتحملين من أجلها أي عار.","3:19":"في ذلك الوقت أعاقب الذين ضايقوك، وأخلص الأعرج، وأعيد المسبي، وأغدق عليهم مدحا وشرفا في كل أرض تعرضوا فيها للخزي.","3:20":"في ذلك الوقت أجمعكم من الشتات وأعيدكم إلى موطنكم، وأجعل لكم مقاما شريفا محمودا بين جميع شعوب الأرض، حين أرد لكم ازدهاركم. هكذا قال الرب."},"Hag":{"1:1":"في السنة الثانية لحكم داريوس الملك،في اليوم الأول من الشهر السادس (أي شهر آب ; أوغسطس)، بعث الرب بهذه الرسالة على لسان النبي حجي إلى زربابل بن شألتيئيل حاكم يهوذا، وإلى يهوشع بن يهوصادق رئيس الكهنة قائلا:","1:2":"«هذا ما يقوله الرب القدير: قد قال هذا الشعب إن الوقت لم يحن بعد لبناء بيت الرب».","1:3":"فأوحى الرب بكلمته هذه إلى النبي حجي قائلا:","1:4":"«هل حان الوقت الذي فيه تقيمون في بيوت مغشاة بألواح بينما هذا البيت ما برح مهدما؟»","1:5":"والآن هذا ما يقوله الرب القدير: «تأملوا فيما فعلتم:","1:6":"لقد زرعتم كثيرا وحصدتم قليلا. أكلتم ولم تشبعوا. شربتم ولم ترتووا. اكتسيتم ولم تستدفئوا. ومن ينال أجرة سرعان ما تتبدد، وكأنها وضعت في صرة مثقوبة».","1:7":"هكذا يقول الرب القدير: «تأملوا فيما فعلتم:","1:8":"اصعدوا إلى الجبل واجلبوا خشبا وشيدوا الهيكل فأرضى عنه وأتمجد، قال الرب.","1:9":"لقد توقعتم كثيرا فحصلتم على قليل، وما أتيتم به إلى البيت من غلة نفخت عليه وبددته. لماذا فعلت هذا يقول الرب القدير؟ من أجل بيتي الذي ما برح مهدما بينما كل واحد منكم منهمك في بناء بيته.","1:10":"لذلك منعت السماء من فوق عنكم الندى، ومنعت الأرض غلتها.","1:11":"وقضيت بالقحط على الأرض والتلال، وعلى حقول الحنطة والكروم، وأشجار الزيتون وعلى كل ما تنتجه الأرض، وعلى الناس والبهائم، وعلى كل تعب أيديكم».","1:12":"حينئذ أطاع زربابل بن شألتيئيل ويهوشع بن يهوصادق رئيس الكهنة، وسائر بقية شعب إسرائيل صوت الرب إلههم، واستمعوا إلى كلمات حجي النبي، كما بعثه الرب إلههم إليهم، فاعترى الخوف الشعب في محضر الله.","1:13":"ثم أبلغ حجي رسول الرب، الشعب رسالة الرب قائلا: «أنا معكم، يقول الرب».","1:14":"وبث الرب الهمة في نفس زربابل بن شألتيئيل حاكم يهوذا ونفس يهوشع بن يهوصادق رئيس الكهنة ونفوس سائر بقية الشعب، فتوافدوا وباشروا العمل في هيكل الرب القدير إلههم.","1:15":"وكان ذلك في اليوم الرابع والعشرين من الشهر السادس من السنة الثانية من حكم الملك داريوس.","2:1":"وفي اليوم الحادي والعشرين من الشهر السابع (أي شهر تشرين الأول ; أكتوبر) أوحى الرب بهذه الكلمة إلى حجي النبي:","2:2":"«خاطب زربابل بن شألتيئيل حاكم يهوذا، ويهوشع بن يهوصادق رئيس الكهنة وجميع البقية الناجية من الشعب قائلا:","2:3":"من بقي منكم ممن شاهدوا هذا الهيكل في مجده السابق؟ كيف ترونه الآن؟ أليس هو في نظركم كلا شيء؟","2:4":"والآن تشجع يازربابل، يقول الرب، وتشدد يايهوشع بن يهوصادق رئيس الكهنة، وأنتم كذلك ياجميع سكان الأرض. تشجعوا واعملوا بجد لأني معكم، يقول الرب القدير.","2:5":"بمقتضى عهدي الذي أبرمته معكم عندما خرجتم من ديار مصر. إن روحي ماكث معكم، فلا تفزعوا.","2:6":"لأنه هكذا يقول الرب القدير: ها أنا مزمع مرة أخرى، عما قليل، أن أزلزل السماء والأرض والبحر واليابسة.","2:7":"وأزعزع أركان جميع الأمم فتجلب نفائسهم إلى هذا المكان وأملأ هذا الهيكل بالمجد.","2:8":"فالذهب والفضة لي يقول الرب القدير.","2:9":"ويكون مجد هذا الهيكل الأخير أعظم من مجد الهيكل السابق، وأجعل السلام يسود هذا الموضع يقول الرب القدير».","2:10":"وفي اليوم الرابع والعشرين من الشهر التاسع (أي شهر كانون الأول ; ديسمبر)، في السنة الثانية لحكم داريوس أوحى الرب بهذه الكلمة إلى النبي حجي:","2:11":"«هذا ما يقوله الرب القدير: اسأل الكهنة عما تقوله الشريعة بشأن هذا السؤال:","2:12":"إن حمل إنسان لحما مقدسا بين طيات ثوبه، ولمس طرفه خبزا أو طبيخا أو خمرا أو زيتا أو أي طعام آخر، فهل يصبح ذاك مقدسا؟» فأجاب الكهنة: «لا».","2:13":"ثم سأل حجي: «إن لمس إنسان تنجس بمس ميت شيئا من هذه هل تصبح نجسة؟» فأجاب الكهنة: «نعم، تصبح نجسة».","2:14":"عندئذ قال حجي: «هذا هو حال الشعب، وهذه هي حال الأمة أمامي يقول الرب، فكل أعمال أيديهم وجميع ما يقدمونه نجس.","2:15":"والآن تأملوا فيما صنعتم اليوم والأيام السالفة قبل أن تضعوا حجرا فوق حجر لبناء هيكل الرب.","2:16":"عندما كان يقبل أحد على كومة حبوب ظنا منه أن الأرض قد غلت عشرين مكيالا، يجد أنها لم تغل سوى عشرة فقط. وحين يدنو من المعصرة ليغرف ملء خمسين وعاء، لا يجد إلا عشرين.","2:17":"إني ابتليت تعب أيديكم بالقحط والذبول والبرد، ولكنكم لم ترجعوا تائبين إلي، يقول الرب.","2:18":"ولكن تأملوا فيما يجري منذ هذا اليوم وصاعدا، من اليوم الرابع والعشرين من الشهر التاسع، منذ أن تم وضع أساس هيكل الرب. تأملوا.","2:19":"هل في الأهراء بذار بعد؟ حتى الكروم والتين والرمان والزيتون لم تثمر بعد. لكن منذ هذا اليوم أبارك فيها».","2:20":"ثم أوحى الرب بكلمته إلى حجي للمرة الثانية في اليوم الرابع والعشرين من الشهر قائلا:","2:21":"«كلم زربابل حاكم يهوذا وقل له: أنا مزمع أن أزلزل السماء والأرض.","2:22":"وأطوح بعروش ممالك الأمم، وأدمر قوتها وأقلب المركبات وفرسانها، فتهوي الخيول وركابها ويلقى كل واحد حتفه بسيف صاحبه.","2:23":"في ذلك اليوم، يقول الرب القدير، أصطفيك يازربابل بن شألتيئيل عبدي، وأجعلك كخاتم في إصبعي (حاكما باسمي) لأني اخترتك يقول الرب القدير»."},"Zec":{"1:1":"في الشهر الثامن من السنة الثانية لحكم داريوس أوحى الرب بهذه الكلمة إلى النبي زكريا بن برخيا بن عدو قائلا:","1:2":"«لقد غضب الرب أشد الغضب على آبائكم.","1:3":"ولكن قل لهم، هذا ما يعلنه الرب القدير: ارجعوا إلي فأرجع إليكم، يقول الرب القدير.","1:4":"ولا تكونوا كآبائكم الذين ناداهم الأنبياء السالفون قائلين: هكذا يقول الرب القدير، ارجعوا عن طرقكم الباطلة وأعمالكم الشريرة، ولكنهم لم يسمعوا ولم يصغوا إلي، يقول الرب.","1:5":"أين هم آباؤكم؟ وهل يحيا الأنبياء إلى الأبد؟","1:6":"ولكن ألم تدرك أقوالي وفرائضي التي أمرت بها عبيدي الأنبياء آباءكم فتابوا قائلين: لقد نفذ الرب القدير ما عزم أن يعاقبنا بمقتضى ما ارتكبناه من أعمال باطلة؟»","1:7":"وفي اليوم الرابع والعشرين من الشهر الحادي عشر، أي شهر شباط العبري، من السنة الثانية لحكم داريوس أوحى الرب بهذه الكلمة إلى النبي زكريا بن برخيا بن عدو قائلا:","1:8":"«شاهدت في رؤيا الليل وإذا برجل يمتطي فرسا أحمر اللون يقف بين أشجار الآس المتوارية في الوادي، وخلفه رجال راكبون على خيل حمر وشقر وبيض.","1:9":"فسألت: «من هؤلاء ياسيدي؟» فأجابني الملاك الذي كلمني: «أنا أخبرك من هؤلاء».","1:10":"قال الفارس الواقف بين الآس: «هؤلاء هم الذين أوفدهم الرب ليجولوا في الأرض».","1:11":"عندئذ قال راكبو الجياد للملاك الواقف بين الآس: «قد جلنا في الأرض، فإذا بها كلها آمنة مطمئنة».","1:12":"فقال الملاك: «إلى متى أيها الرب القدير لا تشفق على أورشليم ومدن يهوذا التي سخطت عليها طوال هذه السبعين سنة؟»","1:13":"فأجاب الرب الملاك الذي كلمني، بعبارات طيبة معزية.","1:14":"ثم خاطبني الملاك قائلا: «ناد، هذا ما يقوله الرب القدير: إني قد غرت على أورشليم وعلى صهيون غيرة عظيمة.","1:15":"ولكن غضبي متأجج على الأمم المتنعمة. لقد اغتظت قليلا من شعبي إلا أنهم زادوا من فواجعهم.","1:16":"لذلك يقول الرب سأرجع إلى أورشليم بفيض من المراحم، فيبنى هيكلي فيها وتعمر أورشليم، يقول الرب القدير.","1:17":"واهتف أيضا قائلا: هذا ما يقوله الرب القدير: ستفيض مدني خيرا ثانية، ويرجع الرب فيعزي صهيون ويصطفي أورشليم».","1:18":"ثم رفعت نظري وإذا بي أرى أربعة قرون.","1:19":"فقلت للملاك: «ما هذه؟» فأجاب: «هذه هي القرون التي بددت أهل يهوذا وإسرائيل وأورشليم».","1:20":"وأراني الرب أربعة صناع،","1:21":"فسألت: «ما الذي جاء يفعله هؤلاء الرجال؟» فأجاب: «هذه هي القرون (أي الأمم) التي بددت أهل يهوذا حتى ذلت كل نفس. أما هؤلاء الصناع فقد أقبلوا ليوقعوا الرعب في نفوس الأمم التي هاجمت أرض يهوذا ليطردوا أهلها».","2:1":"ثم رفعت عيني (في الرؤيا) وإذا بي أرى رجلا حاملا بيده حبل قياس،","2:2":"فسألته: «إلى أين أنت ذاهب؟» فأجابني: «لأمسح أرض أورشليم، فأرى مقدار طولها وعرضها».","2:3":"ثم خرج الملاك الذي كلمني للقاء ملاك آخر أقبل إليه،","2:4":"فقال له: «أسرع وقل لهذا الشاب: ستكون أورشليم كسهل مكشوف آهلة بالناس والبهائم المطمئنين فيها","2:5":"لأني سأكون لها سورا محيطا من نار، يقول الرب، ومجدا في داخلها».","2:6":"هيا أسرعوا، اهربوا من أرض الشمال، فقد شتتكم في أربعة أرجاء الأرض، يقول الرب.","2:7":"أما الآن، فهيا اهربوا إلى صهيون يامن أقمتم في أرض بابل.","2:8":"فإن الرب القدير يقول إنه أرسلني إلى الأمم التي سلبتكم إعلاء لمجده، لأن من يمسكم يمس حدقة عينه.","2:9":"ها أنا أضربهم بيدي فيصيرون نهبا لعبيدهم، فتدركون أن الرب القدير قد أرسلني حقا.","2:10":"رنمي وابتهجي ياأورشليم، لأني قادم لأقيم في وسطك، يقول الرب.","2:11":"فتنضم أمم كثيرة في ذلك اليوم إلى الرب ويكونون لي شعبا، فأقيم في وسطك، فتدركين أن الرب القدير قد أرسلني إليك.","2:12":"ويرث الرب يهوذا نصيبا له في الأرض المقدسة، ويرجع فيصطفي لنفسه أورشليم.","2:13":"ليصمت كل بشر في حضرة الرب لأنه قد هب من مسكن قدسه.","3:1":"ثم أراني الرب يهوشع رئيس الكهنة واقفا في حضرة ملاك الرب، وعن يمينه ينتصب الشيطان ليقاومه.","3:2":"فقال الرب للشيطان: «إن الرب ينتهرك ياشيطان، الرب الذي اصطفى أورشليم ينتهرك، أليس هذا الرجل كحطبة مشتعلة انتشلت من النار؟»","3:3":"وكان يهوشع آنئذ واقفا في حضرة الملاك مرتديا ثيابا قذرة.","3:4":"فقال الملاك للماثلين في حضرته: «اخلعوا عنه هذه الثياب القذرة». ثم قال ليهوشع: «انظر، ها أنا قد أزلت عنك إثمك وكسوتك ثوبا جديدا».","3:5":"ثم أضاف: «ضعوا عمامة طاهرة على رأسه». فوضعوا العمامة الطاهرة على رأسه وكسوه ثيابا بهية، وملاك الرب ما برح واقفا.","3:6":"وأشهد ملاك الرب على يهوشع قائلا:","3:7":"«هذا ما يقوله الرب القدير: إن سلكت في طريقي وأطعت أوامري، فأنت أيضا تتولى شؤون هيكلي وتحافظ على دياري، وأمنحك مقاما بين هؤلاء الماثلين في حضرتي.","3:8":"فأصغ يايهوشع رئيس الكهنة أنت وسائر رفاقك الكهنة الجالسين أمامك. أنتم رجال آية وها أنا آتي بعبدي الذي يدعى الغصن.","3:9":"ها هو الحجر الذي وضعته أمام يهوشع، تحرسه سبع أعين، قد شذبته تشذيبا وكتبت عليه، يقول الرب القدير: وأزيل إثم هذه الأرض في يوم واحد.","3:10":"ويقول الرب القدير: «في ذلك اليوم يدعو كل منكم صديقه ليستريح تحت كرمته وفي ظل تينته».","4:1":"ورجع ملاك الرب الذي يكلمني وأيقظني كما يوقظ رجل من نومه،","4:2":"وسألني: «ماذا ترى؟» فأجبت: «أرى منارة مصوغة كلها من ذهب، على رأسها صحن قائم، عليه سبعة سرج، متصلة بسبع أنابيب من أعلى","4:3":"ينتصب إلى جوارها زيتونتان إحداهما عن يمين الصحن والأخرى عن يساره».","4:4":"ثم سألت الملاك: «ما هذه ياسيدي؟»","4:5":"فأجابني: «ألم تعلم ما هذه؟» فقلت: «لا ياسيدي».","4:6":"فقال: «هذه رسالة الرب إلى زربابل: لا بالقدرة ولا بالقوة، ولكن بروحي تفلحون يقول الرب القدير.","4:7":"أي شيء أنت أيها الجبل العظيم؟ أنت سهل أمام زربابل، وسيضع زربابل حجر الزاوية في خضم هتاف القائلين: ليباركه، ليباركه الرب».","4:8":"ثم أوحى الرب إلي بكلمته قائلا:","4:9":"«قد أسست يدا زربابل هذا الهيكل، ويداه تكملان بناءه، فتدرك أن الرب القدير قد أرسلني إليكم.","4:10":"من يزدري بيوم الإنجازات الصغيرة؟ يفرح الرجال حين يشاهدون ميزان البناء في يد زربابل، وهذه السبعة هي أعين الرب الجائلة في كل الأرض».","4:11":"ثم سألته: «ما هاتان الزيتونتان القائمتان عن يمين المنارة وعن يسارها؟","4:12":"وما غصنا الزيتون هذان المنتصبان إلى جوار أنبوبتي الذهب، اللذان يصبان الزيت الذهبي؟»","4:13":"فأجابني: «ألا تعلم ما هاتان؟» فقلت: «لا ياسيدي».","4:14":"فقال: «هاتان هما الممسوحان بالزيت اللذان يمثلان لدى رب الأرض كلها».","5:1":"وعدت ورفعت عيني وإذا بي أشاهد درجا طائرا.","5:2":"فسألني الملاك: «ماذا ترى؟» فأجبت: «أرى درجا طائرا، طوله عشرون ذراعا (نحو عشرة أمتار) وعرضه عشر أذرع (نحو خمسة أمتار)».","5:3":"فقال لي: «هذه هي اللعنة المنصبة على وجه الأرض كلها. كل من يسرق يستأصل بمقتضى ما هو مدون فيها، وكل حالف زور يعاقب بموجب ما هو منصوص فيها».","5:4":"ويقول الرب القدير: «إني أصب هذه اللعنة على بيت كل سارق أو حالف باسمي زورا، فتحل في وسط بيته وتبيده مع خشبه وحجره».","5:5":"ثم قال لي الملاك الذي كلمني: «ارفع عينيك وانظر إلى هذا الشيء المقبل».","5:6":"فسألت: «ما هذا؟» فأجاب: «إنه مكيال، وهو رمز إثمهم في الأرض كلها».","5:7":"وما لبث أن رفع الغطاء الرصاصي من على فوهته، وإذا بامرأة جالسة في داخل المكيال.","5:8":"فقال لي: «هذه هي رمز الشر»، وألقى بها إلى داخل المكيال، وألقى الغطاء الثقيل على فوهته.","5:9":"ثم نظرت مرة أخرى فرأيت امرأتين مقبلتين لهما أجنحة كأجنحة اللقلق، محمولتين على أمواج الريح، فرفعتا المكيال وحلقتا به بين الأرض والسماء.","5:10":"فسألت الملاك الذي كلمني: «إلى أين مضتا بالمكيال؟»","5:11":"فأجابني: «إلى أرض شنعار لتشيدا له هيكلا حتى إذا تم بناؤه يستقر المكيال فيه على قاعدته».","6:1":"ثم رفعت عيني مرة أخرى وإذا بي أرى أربع مركبات مندفعات من بين جبلين نحاسيين،","6:2":"وكانت تجر المركبة الأولى جياد حمر، والمركبة الثانية جياد سود،","6:3":"والمركبة الثالثة جياد بيض، والمركبة الرابعة جياد مرقطة.","6:4":"فسألت الملاك الذي كلمني: «ما هذه ياسيدي؟»","6:5":"فأجابني: «هذه أرواح السماء الأربعة خارجة بعد مثولها في حضرة رب الأرض كلها.","6:6":"فالمركبة التي تجرها الجياد السود تتوجه نحو بلاد الشمال، والمركبة التي تجرها الجياد البيضاء تتبعها إلى هناك، أما المركبة ذات الجياد المرقطة فمتجهة نحو أرض الجنوب.","6:7":"أما الجياد القوية الحمراء فهي متلهفة للتجوال في الأرض. وما إن قال لها الرب: انطلقي وتجولي في الأرض، حتى اندفعت تطوف في أرجائها».","6:8":"ثم هتف بي: «انظر! إن التي قصدت أرض الشمال قد نفذت قضائي، فأخمدت سورة غضبي هناك».","6:9":"ثم أوحى الرب إلي بكلمته هذه:","6:10":"«خذ من أهل السبي، كلا من حلداي وطوبيا ويدعيا، الذين رجعوا من بابل، وتعال أنت في ذلك اليوم وادخل بيت يوشيا بن صفنيا.","6:11":"خذ (منهم) فضة وذهبا وصغ منها تيجانا، كلل بأحدها رأس يهوشع بن يهوصادق رئيس الكهنة.","6:12":"وقل له: هكذا يقول الرب القدير: ها هو الرجل الذي اسمه الغصن، الذي ينبت من ذاته ويبني هيكل الرب.","6:13":"هو الذي يبني هيكل الرب ويتجلل بالمجد ويكون نفسه ملكا وكاهنا في آن واحد فيجلس ويحكم على عرشه ويعمل بفضل مشورة رتبتيه على إشاعة السلام بين قومه.","6:14":"أما بقية التيجان، فتكون من نصيب حلداي وطوبيا ويدعيا ويوشيا بن صفنيا، وضعها تذكارا في هيكل الرب.","6:15":"ويتوافد قوم من بعيد ليبنوا هيكل الرب، فتدركون أن الرب القدير قد أرسلني إليكم. ويتم هذا كله إن أطعتم صوت الرب إلهكم طاعة كاملة».","7:1":"وفي اليوم الرابع من الشهر التاسع أي شهر كسلو (تشرين الثاني ; نوفمبر)، من السنة الرابعة لحكم الملك داريوس، أوحى الرب بهذه الكلمة إلى زكريا:","7:2":"عندما أرسل أهل بيت إيل شراصر، ورجم ملك، ورجالهم ليصلوا أمام الرب،","7:3":"ليستشيروا كهنة بيت الرب القدير والأنبياء قائلين: «هل ننوح ونصوم في الشهر الخامس (آب ; أوغسطس) كما اعتدنا طوال هذه السنين الكثيرة؟»","7:4":"فأوحى الرب القدير إلي بهذه الرسالة:","7:5":"قل لجميع شعب الأرض والكهنة: «حين كنتم تصومون وتنوحون في الشهر الخامس والشهر السابع (أي تشرين ; الأول أكتوبر) في غضون سنوات المنفى السبعين، هل كان صيامكم حقا لي؟","7:6":"وحين تأكلون وتشربون، ألم يكن ذلك لإشباع نهمكم وإرواء أنفسكم؟","7:7":"وعندما كانت أورشليم آهلة تنعم بالرخاء، محاطة بقرى عامرة، والناس يقيمون في جنوبها وسهلها، ألم تكن هذه هي كلمات الرب التي أعلنها على ألسنة الأنبياء السابقين؟»","7:8":"ثم قال الرب لزكريا:","7:9":"«هذا ما يقوله الرب القدير، اقضوا بالعدل، وليبد كل منكم إحسانا ورحمة لأخيه.","7:10":"ولا تجوروا على الأرملة واليتيم والغريب والمسكين، ولا يضمر أحدكم شرا في قلبه لأخيه.","7:11":"ولكنهم أبوا أن يصغوا، واعتصموا بعنادهم غير عابئين، وأصموا آذانهم لئلا يسمعوا.","7:12":"وقسوا قلوبهم كالصوان لئلا يسمعوا الشريعة التي أرسلها الرب القدير بروحه على لسان أنبيائه السابقين. فانصب غضب عظيم من لدن الرب القدير.","7:13":"وكما ناديت فلم يسمعوا فإني أنا أيضا لا أسمع، يقول الرب القدير.","7:14":"فبددتهم بالزوبعة بين الأمم التي لم يعرفوها من قبل، فصارت الأرض التي نفوا منها خرابا لا يجتازها ذاهب أو راجع، وأضحت الأرض المبهجة قفرا».","8:1":"وأوحى الرب القدير إلي بهذه الكلمة:","8:2":"«هذا ما يقوله الرب القدير: إني أغار على صهيون غيرة عظيمة مفعمة بغضب شديد على أعدائها.","8:3":"لهذا يقول الرب القدير: ها أنا عائد إلى صهيون لأقيم في أورشليم، فتدعى آنئذ مدينة الحق، كما يدعى جبل الرب القدير الجبل المقدس.","8:4":"ويعود الشيوخ من رجال ونساء، ممن يتكئون على عصيهم لفرط كبر أعمارهم، فيجلسون في شوارع أورشليم.","8:5":"وتكتظ طرقاتها بالأولاد والبنات اللاعبين فيها.","8:6":"فإن كان هذا الأمر عجيبا في أعين البقية الناجية من هذا الشعب، أيكون عجيبا في عيني الرب؟","8:7":"ها أنا أنقذ شعبي المنفي في أرض المشرق أو في المغرب.","8:8":"وأردهم إلى أورشليم ليسكنوا فيها، ويكونون لي شعبا وأنا أكون لهم إلها بالحق والعدل.","8:9":"ولتتشدد أيديكم أنتم يامن تسمعون هذه الكلمات التي نطق بها الأنبياء الذين كانوا حاضرين عند إرساء أساس هيكل الرب القدير لإعادة بنائه،","8:10":"فإنه قبل تلك الأيام لم تدفع أجرة لرجل أو بهيمة، ولم يكن هناك من يأمن على نفسه من أعدائه في ذهابه وإيابه، لأنني أثرت كل واحد ضد صاحبه.","8:11":"أما الآن فلن أتعامل مع بقية شعبي الناجية كما تعاملت معه في الأيام الغابرة، يقول الرب القدير.","8:12":"بل يزرعون في سلام، فتعطي الكروم ثمرها والأرض غلاتها، وتجود السماء بأمطارها، وأورث بقية هذا الشعب الناجية كل هذه.","8:13":"وكما كنتم لعنة بين الأمم ياأ بناء يهوذا وإسرائيل، فإنني أخلصكم فتصبحون بركة. لا تجزعوا، بل تشجعوا.","8:14":"لأنه هكذا يقول الرب القدير، كما وطدت العزم أن أعاقبكم بالشر عندما أثار آباؤكم سخطي، ولم أرجع عن عزمي، يقول الرب القدير،","8:15":"فإني عدت أيضا فقضيت في هذه الأيام أن أحسن إلى أورشليم وإلى شعب يهوذا. فلا تجزعوا.","8:16":"وهذا ما عليكم أن تفعلوه: لا تكذبوا بعضكم على بعض، واحكموا في ساحات قضائكم بالعدل وأحكام السلام.","8:17":"لا يضمر أحدكم شرا في قلبه لقريبه، ولا تحلفوا يمين زور، فإن هذه جميعها مقتها، يقول الرب».","8:18":"ثم أوحى الرب إلي بكلمته قائلا:","8:19":"«هذا ما يقوله الرب القدير: إن أصوامكم في الشهور الرابع والخامس والسابع والعاشر ستكون مواسم ابتهاج وفرح وأعياد سعيدة يتمتع بها شعب يهوذا، لهذا أحبوا الحق والسلام.","8:20":"وستأتي شعوب أيضا وأفواج من سكان مدن كثيرة إلى أورشليم.","8:21":"ويمضي أهل المدينة الواحدة إلى المدينة الأخرى قائلين: هيا نذهب على الفور لنطلب رضى وجه الرب القدير ونلتمس بركته، لأننا على أي حال منطلقون إلى هناك.","8:22":"فتتوافد أمم كثيرة وشعوب قوية ليلتمسوا وجه الرب القدير في أورشليم وليحظوا برضاه.","8:23":"في تلك الأيام يتشبث عشرة رجال من أبناء الأمم بثوب رجل يهودي قائلين: دعنا نذهب معكم، لأننا سمعنا أن الرب معكم».","9:1":"وحي قضاء الرب بعقاب أرض حدراخ ودمشق، لأن أعين الناس وسائر أسباط إسرائيل نحو الرب.","9:2":"وكذلك قضاء الرب على حماة المتاخمة لدمشق، وعلى صور وصيدون المتصفتين بالحكمة:","9:3":"«قد بنت صور حصنا لنفسها وادخرت الفضة كالتراب والذهب كطين الشوارع.","9:4":"ولكن ها الرب يجردها من ممتلكاتها، ويطرح عزتها إلى البحر، وتلتهمها النيران.","9:5":"فتشهد مدينة أشقلون هذا فتفزع، وتتلوى غزة ألما. تتوجع عقرون أيضا لأن رجاءها قد تبدد. يهلك ملك غزة وتصبح أشقلون موحشة.","9:6":"ويستوطن الزنيم في أشدود، ويستأصل الرب كبرياء الفلسطينيين.","9:7":"لا يعودون يأكلون لحما بدمه أو طعاما نجسا ويصبحون هم أيضا بقية ناجية للرب، يصيرون كعشيرة في سبط يهوذا، وتغدو عقرون نظير اليبوسيين.","9:8":"ثم أعسكر حول شعبي لأحفظه من غزوات الجيوش في ذهابها وإيابها، فلا يذلهم مستعمر، لأني رأيت الآن بعيني معاناتهم».","9:9":"»ابتهجي جدا ياابنة صهيون واهتفي ياابنة أورشليم، لأن هوذا ملكك مقبل إليك. هو عادل ظافر، ولكنه وديع راكب على أتان، على جحش ابن أتان.","9:10":"وأستأصل المركبات الحربية من أفرايم، والخيل من أورشليم، وتبيد أقواس القتال، ويشيع السلام بين الأمم، ويمتد ملكه من البحر إلى البحر، ومن نهر الفرات إلى أقاصي الأرض.","9:11":"أما أنتم فبفضل دم عهدي معكم أطلق أسراكم من الجب الذي لا ماء فيه.","9:12":"ارجعوا إلى الحصن ياأسرى الرجاء، فأنا أعلن اليوم أني أضاعف لكم الأجر لقاء ما عانيتم من ويلات.","9:13":"ها أنا أوتر يهوذا كقوس وأجعل أفرايم كسهم وأثير رجال صهيون على أبناء اليونان فتكونين كسيف جبار.","9:14":"ثم يتجلى الرب، وينفذ سهمه كالبرق. ينفخ السيد الرب بالبوق ويقتحم في زوابع الجنوب.","9:15":"يقيهم الرب القدير فلا تنالهم حجارة المقلاع، بل تقصر عنهم ويطأونها، ويشربون (من دماء أعدائهم) ويصخبون كالسكارى من الخمر ويمتلئون كمناضح المحرقات وزوايا المذبح.","9:16":"في ذلك اليوم يخلصهم الرب إلههم لأنهم شعبه قطيعه، ويتألقون في أرضه كحجارة كريمة مرصعة في تاج.","9:17":"فما أجملهم وما أبهاهم! الحنطة تجعل الفتيان أكثر ازدهارا، والخمرة تجعل الفتيات أكثر نضرة».","10:1":"اطلبوا من الرب المطر في موسم الربيع، لأن الرب هو الذي يستجيب ببروق، ويسكب على الناس وابلا هطالا، ويرزق كل واحد عشبا في الحقل.","10:2":"أما الأوثان فإنها تنطق بالباطل، ويرى العرافون رؤى كاذبة، وينبئون بأحلام زور. وعبثا يعزون. لذلك شرد الناس كغنم، وقاسوا مشقة لافتقارهم إلى راع.","10:3":"إن غضبي محتدم على الرعاة، وسأعاقب الرؤساء، لأن الرب القدير يعتني بقطيعه شعب يهوذا، ويجعلهم كفرس المزهو في القتال.","10:4":"منهم يخرج حجر الزاوية والوتد وقوس القتال وكل حاكم متسلط.","10:5":"ويدوسون الأعداء معا كما يدوس الجبابرة الطين في الشوارع، ويحاربون لأن الرب معهم فيلحقون العار بفرسان الأعداء.","10:6":"إني أشدد شعب يهوذا وأخلص ذرية يوسف وأردهم إلى أرضهم لأني أكن لهم الرحمة، فيكونون كأني لم أنبذهم لأني أنا الرب إلههم فأستجيبهم.","10:7":"ويصبح شعب إسرائيل كجبابرة الحرب، وتنتشي قلوبهم كمن شرب خمرة، ويشهد أبناؤهم هذا ويفرحون، وتبتهج نفوسهم بالرب.","10:8":"أصدر إشارتي لهم فأجمع شتاتهم، لأني افتديتهم، ويكثرون كما في الحقب الأولى.","10:9":"مع أني بددتهم بين الأمم، فإنهم يظلون يذكرونني في المنافي البعيدة، ويحيون مع أولادهم ويرجعون.","10:10":"سأردهم إلى موطنهم من ديار مصر، وأجمع شتاتهم من أشور، وآتي بهم إلى أرض جلعاد ولبنان حتى لا يبقى متسع لهم بعد.","10:11":"يجتازون عبر بحر المشقات، فتنحسر الأمواج وتجف لجج النيل. تذل كبرياء أشور ويزول صولجان مصر.","10:12":"وأشددهم بالرب فيسلكون بمقتضى اسمه، يقول الرب.","11:1":"افتح أبوابك يالبنان حتى تلتهم النار أرزك.","11:2":"انتحب أيها السرو لأن الأرز قد تهاوى، والعظماء قد هلكوا. انتحب يابلوط باشان لأن الغابات الكثيفة دمرت.","11:3":"استمعوا إلى نواح الرعاة (أي الحكام) لأن مرابعهم الثرية قد تلفت. أنصتوا إلى زمجرة الأسود لأن أجمات وادي الأردن قد صارت خرابا.","11:4":"هكذا قال الرب إلهي: «ارع الغنم المعد للذبح،","11:5":"الذين يقتلهم مالكوهم ويفلتون من العقاب، وكل من يبيعهم يقول: تبارك الرب فإني قد أثريت. أما رعاتهم فلا يضمرون لهم شفقة».","11:6":"ويقول الرب: «لذلك لا أشفق بعد على سكان الأرض، بل أنا أسلم كل واحد إلى قريبه أو مالكه، فيهلكون الناس ولا أنقذ أحدا من أيديهم».","11:7":"وهكذا صرت راعيا لأهزل الغنم المعد للذبح، وأخذت لنفسي عصوين دعوت إحداهما نعمة والأخرى وحدة، وقمت برعاية الغنم.","11:8":"وفي غضون شهر واحد أفنيت الرعاة الثلاثة. ولكن صبري نفد على الأغنام، كما أضمروا هم أيضا لي الكراهية.","11:9":"لذلك قلت: «لن أكون لكم راعيا. من يمت منكم فليمت، ومن يهلك فليهلك، وليأكل من يبقى منكم لحم بعضكم بعضا».","11:10":"وتناولت عصاي «نعمة» وكسرتها ناقضا بذلك العهد الذي أبرمته مع جميع الشعوب.","11:11":"وهكذا بطل العهد في ذلك اليوم، وأدرك أهزل الغنم الذين كانوا يراقبونني أن ما جرى كان بقضاء الرب.","11:12":"ثم قلت لهم: «إن طاب لكم فأعطوني أجرتي، وإلا فاحتفظوا بها». فوزنوا أجرتي ثلاثين شاقلا من الفضة.","11:13":"فقال الرب لي: «أعط هذا الثمن الكريم الذي ثمنوني به إلى الفخاري». فأخذت الثلاثين قطعة من الفضة وألقيتها في بيت الرب إلى الفخاري.","11:14":"وحطمت عصاي الأخرى «وحدة» لأنقض الإخاء بين يهوذا وإسرائيل».","11:15":"ثم قال لي الرب: «اذهب وتجهز ثانية بأدوات راع أحمق.","11:16":"فها أنا مزمع أن أقيم في الأرض راعيا لا يعبأ بالغنم الشاردة، ولا يفتقد الحملان أو يجبر المكسورين، ولا يغذي الصحيح. ولكنه يفترس السمان منهم وينزع أظلافها.","11:17":"ويل للراعي الأحمق الذي يهجر القطيع. ليبتر السيف ذراعه ويفقأ عينه اليمنى، فتيبس ذراعه وتكف عينه اليمنى عن البصر».","12:1":"وحي كلمة الرب بشأن إسرائيل. يقول الرب باسط السماوات ومرسي الأرض، وجابل روح الإنسان فيه:","12:2":"«ها أنا مزمع أن أجعل أورشليم كأس خمر تترنح منها جميع الشعوب المحيطة بها، فتحاصر يهوذا أيضا في أثناء حصارها لأورشليم.","12:3":"في ذلك اليوم أجعل أورشليم كصخرة ثقيلة تعجز عن حملها جميع الشعوب. وكل من يحاول حملها ينشق شقا، ويتألب عليها جميع شعوب الأرض.","12:4":"في ذلك اليوم، يقول الرب: أصيب كل فرس من جيوش الأعداء بالرعب، وفارسه بالجنون، وأرعى برضاي شعب يهوذا، وأبتلي جميع خيول الأمم بالعمى.","12:5":"فيقول آنئذ رؤساء يهوذا في قلوبهم: إن سكان أورشليم أعزاء بفضل قوة الرب القدير إلههم.","12:6":"في ذلك اليوم أجعل عشائر يهوذا كمستوقد نار بين الحطب، أو كمشعل ملتهب بين أكداس الحنطة، فيلتهمون الشعوب من حولهم ممن عن يمينهم وعن يسارهم، بينما تظل أورشليم مستقرة آمنة آهلة في موضعها.","12:7":"ويخلص الرب أولا خيام يهوذا لئلا يتعاظم افتخار بيت داود وأهل أورشليم على سائر يهوذا.","12:8":"في ذلك اليوم يحفظ الرب سكان أورشليم، فيكون أضعفهم قويا قادرا مثل داود، ويتولى بيت داود قيادتهم في الطليعة، تماما كما كان الله أو ملاك الرب يتقدمهم.","12:9":"في ذلك اليوم أعمل على إهلاك جميع الشعوب الزاحفين على أورشليم.","12:10":"وأفيض على ذرية داود وعلى سكان أورشليم روح النعمة والابتهال، حتى إذا نظروا إلي أنا الذي طعنوه ينوحون عليه كما ينوح والد على ولده الوحيد، متفجعين عليه كتفجعهم على موت بكرهم.","12:11":"في ذلك اليوم يكون النواح في أورشليم مماثلا للنواح في هددرمون في سهل مجدو (حيث قتل الملك يوشيا).","12:12":"فيشيع النحيب بين أهل البلاد، فتنوح كل عشيرة على حدة، فيبكي رجال عشيرة داود منفردين عن النساء، والنساء عن الرجال، ورجال عشيرة ذرية ناثان منفردين عن النساء، والنساء عن الرجال.","12:13":"وكذلك ينوح رجال ونساء عشيرة لاوي كل على حدة، ورجال ونساء عشيرة شمعي كل على حدة.","12:14":"وأيضا ينوح رجال ونساء سائر العشائر الباقية كل على حدة».","13:1":"»في ذلك اليوم يتفجر ينبوع ليطهر ذرية داود وسكان أورشليم من إثمهم ونجاستهم.","13:2":"ويقول الرب القدير: في ذلك اليوم أستأصل أسماء الأصنام من الأرض فلا يعود لها ذكر، وألاشي الأنبياء الكذبة والروح النجس من الأرض.","13:3":"وإن تنبأ أحد فيما بعد، يطعنه أبوه وأمه اللذان أنجباه قائلين: لابد أن تموت لأنك نطقت بالزور باسم الرب.","13:4":"في ذلك اليوم يعتري الخزي كل نبي كاذب يتنبأ من رؤياه، ولا يرتدي مسوح الشعر ليكذب.","13:5":"إنما يقول: أنا لست نبيا. أنا رجل فلاح أحرث الأرض منذ صباي.","13:6":"وعندما يسأله أحد: ما هذه الجروح في يديك؟ يجيبه: هي التي جرحت بها في بيت أحبائي».","13:7":"ويقول الرب القدير: «استيقظ أيها السيف وهاجم راعي ورجل رفقتي. اضرب الراعي فتتبدد الخراف. ولكني أرد يدي عن الصغار (أي القلة المؤمنة).","13:8":"يقول الرب فيفنى ثلثا شعب أرضي ويبقى ثلثهم حيا فقط.","13:9":"فأجيز هذا الثلث في النار لأنقيه تنقية الفضة، وأمحصه كما يمحص الذهب. هو يدعو باسمي وأنا أستجيبه. أنا أقول: هو شعبي، وهو يقول: الرب هو إلهي».","14:1":"انظروا ها هو يوم مقبل للرب، يقسم فيه ما سلب منكم في وسطكم.","14:2":"لأني أجمع جميع الأمم على أورشليم لتحاربها، فتؤخذ المدينة وتنهب البيوت وتغتصب النساء ويسبى نصف أهلها إلى المنفى. إنما لا ينقرض بقية الشعب من المدينة.","14:3":"ولا يلبث أن يهب الرب ليحارب تلك الأمم، كما كان يحارب في يوم القتال.","14:4":"وتقف قدماه في ذلك اليوم على جبل الزيتون الممتد أمام أورشليم باتجاه الشرق، فينشق جبل الزيتون إلى شطرين من الشرق إلى الغرب عن واد عظيم جدا، فيتراجع نصف الجبل إلى الشمال، والنصف الآخر نحو الجنوب.","14:5":"ويهربون من خلال وادي جبالي الممتد إلى آصل. تهربون كما هربتم من الزلزلة في أيام حكم عزيا ملك يهوذا، ويأتي الرب إلهي في موكب من جميع قديسيه.","14:6":"في ذلك اليوم يتلاشى نور (الكواكب) ولا يكون برد ولا صقيع.","14:7":"ويكون يوم متواصل معروف عند الرب، لا نهار فيه ولا ليل، إذ يغمر النهار ساعات المساء.","14:8":"في ذلك اليوم تجري مياه حية من أورشليم، يصب نصفها في البحر الشرقي (البحر الميت)، ونصفها الآخر في البحر الغربي (البحر الأبيض المتوسط) طوال الصيف والشتاء.","14:9":"ويملك الرب على الأرض كلها، فيكون في ذلك اليوم رب واحد لا يذكر سوى اسمه.","14:10":"وتتحول الأرض كلها من جبع شمالا إلى رمون جنوبا، إلى سهل كسهل عربة. أما أورشليم فلا تبرح شامخة في موقعها الممتد من بوابة بنيامين حتى البوابة الأولى وإلى بوابة الزوايا، ومن برج حننئيل إلى معاصر خمر الملك.","14:11":"وتصبح آهلة إذ لن يحل بها دمار ثانية، وتكون أورشليم آمنة.","14:12":"وهذا هو البلاء الذي يعاقب به الرب جميع الشعوب الذين اجتمعوا على أورشليم: تتهرأ لحومهم وهم واقفون على أرجلهم، وتتآكل عيونهم في أوقابها، وتتلف ألسنتهم في أفواههم.","14:13":"في ذلك اليوم يلقي الرب الرعب في قلوبهم حتى ترتفع يد الرجل ضد يد رفيقه في آن واحد ويهلكان معا.","14:14":"ويحارب أبناء يهوذا أيضا دفاعا عن أورشليم، ويغنمون ثروات من الأمم المحيطة بها من ذهب وفضة وأثواب، بوفرة عظيمة.","14:15":"ويصيب بلاء مماثل الخيول والبغال والجمال والحمير وسائر البهائم الموجودة داخل هذه المعسكرات.","14:16":"فيصعد الناجون من الأمم التي تألبت على أورشليم، سنة بعد سنة ليعبدوا الملك الرب القدير ويحتفلوا بعيد المظال.","14:17":"وإن تقاعست أية عشيرة من عشائر أمم الأرض عن الصعود إلى أورشليم لتسجد للملك الرب القدير، يمتنع المطر عن الهطول على ديارهم.","14:18":"وإن أبى أهل مصر الصعود للاشتراك في الاحتفال، يحل بهم البلاء الذي يعاقب به الرب الأمم التي لا تجيء للاحتفال بعيد المظال.","14:19":"هذا هو عقاب مصر وعقاب سائر الشعوب التي تأبى المجيء للاحتفال بعيد المظال.","14:20":"وينقش في ذلك اليوم على أجراس الخيل: «قدس للرب». وتكون القدور في الهيكل مقدسة كالمناضح التي أمام المذبح.","14:21":"بل يكون كل قدر في أورشليم وفي يهوذا مقدسا للرب القدير، فيصبح في وسع المقربين أن يأتوا ويستخدموا ما يشاؤون منها، ليطبخوا فيها لحم الذبيحة. ولا يبقى في هيكل الرب القدير تجار في ذلك اليوم."},"Jon":{"1:1":"وأمر الرب يونان بن أمتاي:","1:2":"«هيا امض إلى نينوى المدينة العظيمة وبلغ أهلها قضائي، لأن إثمهم قد صعد إلي».","1:3":"غير أن يونان تأهب ليهرب من الرب إلى ترشيش، فانحدر إلى مدينة يافا حيث عثر على سفينة مبحرة إلى ترشيش، فدفع أجرتها وصعد إليها ليتوجه مع بحارتها إلى ترشيش هربا من الرب.","1:4":"فأرسل الرب ريحا عاتية على البحر أثارت إعصارا بحريا، حتى أشرفت السفينة على الانكسار.","1:5":"ففزع الملاحون واستغاث كل واحد منهم بإلهه، وطرحوا ما في السفينة من أمتعة ليخففوا من حمولتها. أما يونان فلجأ إلى جوف السفينة ورقد مستغرقا في نوم عميق.","1:6":"فاقترب منه الربان وقال له: «ما بالك مستغرقا في النوم؟ قم وتضرع إلى إلهك لعل الله يذكرنا فلا نهلك».","1:7":"ثم قال كل واحد لرفيقه: «هيا نلق قرعة لعلنا نعرف من جر علينا هذا البلاء». فألقوا القرعة، فوقعت على يونان.","1:8":"فقالوا له: «أخبرنا لماذا جرى علينا هذا البلاء؟ وما هي حرفتك؟ ومن أين أقبلت؟ وما هي بلادك؟ ومن هم قومك؟»","1:9":"فأجابهم: «أنا عبراني، وأنا خائف من الرب إله السماوات، صانع البحر والبر».","1:10":"فاعترى البحارة خوف عظيم وقالوا له بعد أن أخبرهم أنه هارب من الرب: «لماذا صنعت هذا؟»","1:11":"ثم تساءلوا: «ماذا نفعل بك حتى يسكن البحر عنا؟»؛ لأن البحر كان يزداد هياجا.","1:12":"فأجابهم: «خذوني واطرحوني إلى البحر فيسكن، لأني موقن أن هذا الإعصار المريع قد هاج عليكم بسببي».","1:13":"ولكن البحارة شرعوا يجذفون ليرجعوا إلى الشاطيء، فأخفقوا لتفاقم هياج البحر.","1:14":"فصرخوا إلى الرب قائلين: «أيها الرب لا تهلكنا من أجل حياة هذا الرجل، ولا تحملنا دما بريئا لأنك يارب فعلت كما شئت».","1:15":"ثم أخذوا يونان وقذفوا به إلى البحر، فران عليه الهدوء وسكنت أمواجه.","1:16":"فانتاب الرجال خوف عظيم من الرب، وقربوا له ذبيحة ونذروا نذورا.","1:17":"وأما الرب فأعد حوتا عظيما ابتلع يونان. فمكث يونان في جوف الحوت ثلاثة أيام وثلاث ليال.","2:1":"ثم صلى يونان إلى الرب إلهه من جوف الحوت،","2:2":"قائلا: «استغثت بالرب في ضيقي فاستجاب لي، ومن جوف الهاوية ابتهلت فسمعت صوتي.","2:3":"لأنك طرحتني إلى اللجج العميقة في قلب البحار، فاكتنفني الغمر وأحاطت بي تياراتك وأمواجك","2:4":"فقلت: قد طردت من حضرتك، ولن أعود أتفرس في هيكلك المقدس.","2:5":"قد غمرتني المياه وأحدقت بي اللجج، والتف عشب البحر حول رأسي.","2:6":"انحدرت إلى أسس الجبال وهبطت إلى أعماق الأرض حيث أغلقت علي مزاليجها إلى الأبد. ولكنك تصعد حياتي من الهاوية أيها الرب إلهي.","2:7":"عندما وهنت نفسي في داخلي، تذكرت إلهي، فحلقت صلاتي إليك، إلى هيكلك المقدس.","2:8":"إن الذين يبجلون الأصنام الباطلة يتخلون عن مصدر نعمتهم.","2:9":"أما أنا فبهتاف الحمد أذبح لك، وما نذرته أوفي به، لأن للرب الخلاص».","2:10":"فأمر الرب الحوت فقذف بيونان إلى الشاطيء.","3:1":"وأمر الرب يونان ثانية:","3:2":"«قم امض إلى نينوى المدينة العظيمة، وأعلن لهم الرسالة التي أبلغك إياها».","3:3":"فهب يونان وتوجه إلى نينوى بموجب أمر الرب. وكانت نينوى مدينة بالغة العظمة يستغرق اجتيازها ثلاثة أيام.","3:4":"فدخل يونان المدينة واجتاز فيها مسيرة يوم واحد، وابتدأ ينادي قائلا: «بعد أربعين يوما تتدمر المدينة».","3:5":"فآمن شعب نينوى بالرب، وأعلنوا الصيام وارتدوا المسوح من كبيرهم إلى صغيرهم .","3:6":"ثم بلغ إنذار النبي ملك نينوى، فقام عن عرشه وخلع عنه حلته، وارتدى المسح وجلس على الرماد.","3:7":"وأذاع في كل نينوى مرسوما ورد فيه: «بأمر من الملك ونبلائه، يمتنع الناس عن الأكل والشرب، وكذلك البهائم والغنم والبقر، لا ترع ولا تشرب ماء.","3:8":"وعلى جميع الناس والبهائم أن يرتدوا المسوح، متضرعين إلى الله تائبين عن طرقهم الشريرة وعما ارتكبوه من ظلم.","3:9":"لعل الرب يرجع فيعدل عن احتدام سخطه فلا نهلك».","3:10":"فلما رأى الله أعمالهم وتوبتهم عن طرقهم الآثمة عدل عن العقاب الذي كان مزمعا أن يوقعه بهم وعفا عنهم.","4:1":"فأثار ذلك غيظ يونان وغضبه الشديدين.","4:2":"وصلى إلى الرب قائلا: «أيها الرب، أليس هذا ما قلته عندما كنت في بلادي؟ لهذا أسرعت إلى الهرب إلى ترشيش، لأني عرفت أنك إله رحيم رؤوف بطيء الغضب كثير الإحسان، ترجع عن العقاب.","4:3":"والآن دعني أيها الرب ألفظ أنفاسي لأنه خير لي أن أموت من أن أحيا».","4:4":"فقال الرب: «أأنت محق في غضبك؟»","4:5":"وخرج يونان من نينوى وجلس شرقي المدينة، بعد أن نصب لنفسه مظلة جلس تحت ظلها يرقب ما يجري على المدينة.","4:6":"فأعد الرب الإله يقطينة نمت وارتفعت حتى ظللت رأس يونان لتقيه من شدة الحر فلا يؤذيه. فابتهج يونان باليقطينة ابتهاجا عظيما.","4:7":"ولكن في فجر اليوم التالي أعد الله دودة قرضت اليقطينة فجفت.","4:8":"فلما أشرقت الشمس، أرسل الله ريحا شرقية حارة لفحت رأس يونان، فأصابه الإعياء وتمنى لنفسه الموت قائلا: «خير لي أن أموت من أن أظل حيا».","4:9":"فقال الله ليونان: «أأنت محق في غضبك من أجل اليقطينة؟» فأجاب: «أنا محق في غضبي حتى الموت».","4:10":"فقال الرب: «لقد أشفقت أنت على اليقطينة التي لم تتعب في تنميتها وتربيتها. هذه اليقطينة التي ترعرعت في ليلة وذوت في ليلة.","4:11":"أفلا أشفق أنا على نينوى المدينة العظيمة التي يقيم فيها أكثر من مئة وعشرين ألف شخص ممن لا يفرقون بين يمينهم وشمالهم، فضلا عما فيها من بهائم كثيرة؟»."},"Mic":{"1:1":"هذه كلمة الرب التي أوحى بها إلى ميخا المورشتي في أثناء حكم يوثام وآحاز وحزقيا ملوك يهوذا، بشأن السامرة وأورشليم.","1:2":"اسمعوا ياجميع الشعوب، وأصغي أيتها الأرض وكل من فيها، وليكن السيد الرب من هيكله المقدس شاهدا عليكم.","1:3":"انظروا: ها هو الرب خارج من مقر سكناه. هوذا ينزل ليطأ مشارف الأرض،","1:4":"فتذوب الجبال من تحت قدميه، وتتصدع الوديان كالشمع أمام النار، كالمياه المنصبة في المنخفضات.","1:5":"من أجل آثام يعقوب ومن أجل خطايا بيت إسرائيل. فما هو ذنب يعقوب؟ أليس هو أصنام السامرة؟ وما هي خطيئة يهوذا؟ أليست هي أوثان أورشليم؟","1:6":"لذلك سأجعل السامرة كومة حجارة في الحقل ومغرسا للكروم، وأقذف بحجارتها إلى الوادي، وأعري أساساتها.","1:7":"فتتحطم كل أصنامها، وتحرق كل تقدمات زناها بالنار، وأدمر جميع تماثيلها لأنها جمعتها من أجرة زانية، وإلى زانية يكون مآلها.","1:8":"لهذا أنوح وأولول وأمشي حافيا عريانا، وأعول كبنات آوى، وأنتحب كالنعام.","1:9":"لأن جروح السامرة لن تندمل، وهي لابد أن تصيب يهوذا، ها هي قد بلغت أبواب شعبي أهل أورشليم.","1:10":"لا تخبروا في جت، ولا تبكوا في عكاء. عفروا أنفسكم بالتراب في بيت عفرة.","1:11":"اخرجوا ياأهل شافير عرايا مجللين بالعار، وليمكث سكان صانان في منازلهم خجلا. وعندما تسمعون عويل أهل هأيصل تدركون أنها قد سقطت ولا ملجأ لكم فيها.","1:12":"لشد ما انتظر أهل ماروث الخير، غير أن الشر قد أقبل على باب أورشليم من عند الرب.","1:13":"شدوا الخيل إلى المركبات ياسكان لاخيش، لأنكم كنتم أول من ارتكب الخطيئة بين مدن صهيون، وفيكم قد وجدت آثام إسرائيل.","1:14":"لهذا تحملون هدايا وداع إلى مورشة جت، وتصبح مدينة أكزيب خدعة لملوك إسرائيل.","1:15":"وأبعث إليكم بقاهر ياأهل مريشة، فيهرب من أمامه نبلاء إسرائيل إلى مغارة عدلام.","1:16":"احلقوا رؤوسكم وجزوا شعوركم من أجل أبناء مسرتكم. اجعلوا رؤوسكم صلعاء كرأس النسر، لأنهم سيؤخذون منكم إلى السبي.","2:1":"ويل للمتآمرين بالسوء، الذين يحوكون الشر وهم في مضاجعهم، الذين ينفذون عند طلوع الصباح ما خططوا له، لأن ذلك في متناول قدرتهم.","2:2":"يشتهون حقولا ويغتصبونها، وبيوتا فيستولون عليها. يجورون على الرجل وعلى بيته والإنسان وميراثه.","2:3":"لهذا، هكذا يقول الرب. ها أنا أدبر شرا لهذا الشعب تعجزون عن فك رقابكم منه، ولن تمشوا بعد متشامخين لأن الزمن يكون زمن سوء.","2:4":"في ذلك اليوم يسخر أعداؤكم منكم، وتنوحون بمثل هذا الرثاء: «قد تم تدميرنا واستبدل الرب نصيب شعبه. كيف أخذه منا وقسم حقولنا بين آسرينا؟»","2:5":"لهذا لن يوجد بين جماعة الرب من يلقي القرعة ليقسم الأرض.","2:6":"يقول الشعب للأنبياء: لا تتنبأوا بمثل هذه الأمور، لأن العار لن يلحق بنا.","2:7":"آه يابيت يعقوب؟ هل نفد صبر روح الرب؟ أهذه الأفعال صدرت عنه؟ أليست كلماتي صالحة للسالكين بالاستقامة؟","2:8":"بالأمس هب شعبي كعدو! تسلبون رداء العابرين بأمن والعائدين من القتال.","2:9":"تطردون أرامل شعبي من بيوتهن، وتجردون أطفال كل منهن من عطاياي إلى الأبد.","2:10":"هبوا واذهبوا، فهذا ليس مكان راحتكم، لأنه أصبح نجسا، مدمرا ولا يمكن ترميمه.","2:11":"إن جال رجل يتنبأ بينكم بالكذب وباللغو الباطل قائلا: إنني أتنبأ لكم بالخمر الوفير والمسكر، فإنه يصبح نبي هذا الشعب.","2:12":"سأجمع شتاتك جميعا يايعقوب، وأجمع بقية إسرائيل وأضمهم معا كقطيع غنم في حظيرة، مثل قطيع محتشد في مرعى، فترتفع جلبة جمهورهم.","2:13":"والذي يفتح الثغرة يتقدمهم فيقتحمون ويعبرون الباب خارجا، وفي طليعتهم يسير ملكهم والرب في مقدمتهم.","3:1":"وقلت اسمعوا يارؤساء يعقوب وياقضاة شعب إسرائيل: ألا ينبغي لكم أن تعرفوا الحق؟","3:2":"أنتم يامن تبغضون الخير وتحبون الشر، وتسلخون جلود شعبي وتجردون لحومهم عن عظامهم.","3:3":"الذين تأكلون لحوم شعبي، وتسلخون جلودهم عنهم وتهشمون عظامهم، وتقطعونهم كما يقطع اللحم في القدر، أو كاللحم المعد للمقلى.","3:4":"ثم حين تستغيثون بالرب لا يستجيب ويحجب وجهه عنكم في ذلك الوقت بسبب ما ارتكبتموه من أعمال شريرة.","3:5":"وهذا ما يقوله الرب بشأن الأنبياء الذين يضلون شعبه، الذين ينادون قائلين: «سلام» لمن يعطيهم طعاما، ويعلنون الحرب على من لا يلقم أفواههم.","3:6":"لذلك يطغى عليكم ليل خال من الرؤيا، وظلام من غير عرافة، وتغرب الشمس عن الأنبياء ويظلم عليهم النهار.","3:7":"يعتري الرائين الخزي وينتاب العرافين الخجل، ويغطون جميعهم شفاههم لأنهم لا ينالون جوابا من الرب.","3:8":"أما أنا، فإني ممتليء بقوة روح الرب وبالحق والعزة، لأعلن لنسل يعقوب معاصيه ولإسرائيل خطيئته.","3:9":"استمعوا هذا يارؤساء بيت يعقوب وقضاة شعب إسرائيل الذين يكرهون العدل ويحرفون الحق.","3:10":"الذين يبنون صهيون بالدم وأورشليم بالظلم.","3:11":"إذ يحكم رؤساؤها بالرشوة، وكهنتها يعلمون بالأجرة ويتعاطى أنبياؤها العرافة لقاء المال، ومع ذلك يدعون الاتكال على الله قائلين: «أليس الرب في وسطنا؟ لذلك لن يصيبنا مكروه».","3:12":"لهذا من جراء أعمالكم ستحرث صهيون كالحقل وتصبح أورشليم كومة من الخرائب، وجبل الهيكل مرتفعا تنمو عليه أشجار الغاب.","4:1":"ويكون في آخر الأيام أن جبل هيكل الرب يصبح أشهر الجبال، ويعلو فوق كل التلال، فتتقاطر إليه شعوب عديدة،","4:2":"وتقبل إليه أمم كثيرة قائلة: «تعالوا لنصعد إلى جبل الرب، إلى هيكل يعقوب ليعلمنا طرقه فنسلك في سبله، لأن من صهيون تخرج الشريعة ومن أورشليم تذاع كلمة الرب».","4:3":"فيقضي بين الأمم الكثيرة ويملي أحكامه بعدل على أمم قوية بعيدة، فيصنعون من سيوفهم أسنة محاريث، ومن رماحهم مناجل حصاد، فلا ترفع أمة على أمة سيفا ولا يتلقنون فنون الحرب بعد.","4:4":"بل يجلس كل رجل تحت كرمه وتحت شجرة تينته ولا يرعبهم شيء من بعد، لأن هذا ما تكلم به الرب القدير.","4:5":"فإن جميع الأمم تسلك باسم إلهها، أما نحن فنسلك باسم الرب إلهنا إلى أبد الآبدين.","4:6":"في ذلك اليوم، يقول الرب، أجمع العرج، وأضم المطرودين وكل الذين أنزلت بهم البلاء.","4:7":"فأجعل من العرج بقية، ومن المنبوذين أمة قوية، فيملك الرب عليهم في جبل صهيون من الآن وإلى الأبد.","4:8":"أما أنت يابرج القطيع، ياتلة ابنة صهيون، إليك يعود الحكم الأول، ملك ابنة أورشليم.","4:9":"لماذا تنوحين بصوت مرتفع؟ أليس فيك ملك؟ هل هلك مشيرك حتى ألم بك الألم كامرأة تقاسي من المخاض.","4:10":"تلوي وجعا وتأوهي ياابنة صهيون كامرأة تعاني من المخاض، لأنك الآن تخرجين من المدينة لتقيمي في الصحراء. ستذهبين إلى بابل، وهناك يتم إنقاذك لأن الرب يفتديك هناك من أيدي أعدائك.","4:11":"والآن ها أمم غفيرة قد اجتمعت عليك قائلة «لتتدنس أورشليم حتى تتفرس عيوننا في خرابها».","4:12":"لكنهم لم يعرفوا نوايا الرب، ولم يفهموا مقاصده، فإنه قد جمعهم كأكداس إلى البيدر ليعاقبهم.","4:13":"فانهضي ياابنة صهيون وادرسي أعداءك، لأني سأجعل لك قرنا من حديد وأظلافا من نحاس فتسحقين أمما كثيرة، وتكرسين كل ما تغنمينه منهم للرب، وتقدمين ثروتهم لسيد الأرض كلها.","5:1":"الآن احشدي جيوشك يامدينة الجيوش، لأن العدو يقيم عليك حصارا، وسيضرب خد قاضي إسرائيل بالقضيب.","5:2":"أما أنت يابيت لحم أفراتة، مع أنك قرية صغيرة بين ألوف قرى يهوذا، إلا أن منك يخرج لي من يصبح ملكا في إسرائيل وأصله منذ القديم، منذ الأزل.","5:3":"لذلك يسلم الرب شعبه إلى أعدائهم إلى أن تلد من تقاسي من المخاض، عندئذ ترجع بقية إخوته من السبي إلى شعب إسرائيل.","5:4":"فيقوم ويرعى شعبه بقوة الرب وبجلال اسم الرب إلهه، فيعيشون بأمن، لأن عظمته تمتد إلى أقاصي الأرض.","5:5":"ويصبح الرب سلامهم، إذ حين يزحف الأشوريون إلى أرضنا ويطأون ترابنا، فإننا نثير عليهم سبعة رعاة وثمانية أمراء من الناس،","5:6":"فيحكمون بلاد أشور بقوة السيف، ويقتحمون بوابات أرض نمرود، وينقذنا ( الله ) من الأشوريين عندما يزحفون إلى أرضنا ويطأون تخومنا.","5:7":"عندئذ تغدو بقية ذرية يعقوب بين الأمم الكثيرة كندى من لدن الرب، كالمطر الوابل على العشب الذي لا يتوانى من أجل الناس أو يرجو أبناء البشر.","5:8":"وتكون بقية ذرية يعقوب بين الشعوب الكثيرة كأسد بين وحوش الغابة، أو كشبل بين قطعان الغنم، الذي إن اقتحم يدوس ويفترس وليس من منقذ.","5:9":"فتتعاظم ياشعبي على مبغضيك، ويبيد جميع أعدائك.","5:10":"ويقول الرب: في ذلك اليوم أستأصل خيولكم من بينكم وأدمر مركبات حربكم،","5:11":"وأخرب مدنكم وأهدم جميع حصونكم،","5:12":"وأقضي على السحر في دياركم ولا يبقى لكم عرافون،","5:13":"وأنتزع تماثيلكم وأنصابكم من وسطكم، فلا تعودون تسجدون لأصنام من صنع أيديكم.","5:14":"وأفني عشتاروث من بينكم، وأهدم مدنكم،","5:15":"وبغضب وسخط أنتقم من الأمم التي لم تطعني.","6:1":"استمعوا إلى ما يقوله الرب: انهض وأعلن دعواك أمام الجبال، ولتكن الأكام شاهدة على كلامك.","6:2":"استمعي ياجبال إلى شكوى الرب، وأصغي ياأسس الأرض الثابتة، فإن لدى الرب شكوى على شعبه وهو يحاكم إسرائيل.","6:3":"بماذا أسأت إليك ياشعبي وبما ضايقتك؟ أجبني.","6:4":"لقد أخرجتك من ديار مصر، وافتديتك من بيت العبودية، وأرسلت أمامك موسى وهرون ومريم","6:5":"اذكر ياشعبي ما تآمر به عليك بالاق ملك موآب، وما أجابه به بلعام بن بعور. واذكر ما أحسنت به إليك في رحلتك من شطيم إلى الجلجال لكي تدرك عدل الرب.","6:6":"يارب: بماذا أتقدم عندما أمثل أمام الرب وأسجد في حضرة الله العلي؟ هل أتقدم منه بمحرقات وبعجول حولية؟","6:7":"هل يسر الرب بألوف أنهار زيت؟ هل أقرب بكري فداء إثمي وثمرة جسدي تكفيرا عن خطيئة نفسي؟","6:8":"لقد أوضح لك الرب أيها الإنسان ما هو صالح. وماذا يبتغي منك سوى أن تتوخى العدل، وتحب الرحمة، وتسلك متواضعا مع إلهك؟","6:9":"صوت الرب ينادي في أرجاء المدينة، ومن الحكمة أن يتقى اسمك. استمعوا ياأهل المدينة وأعضاء مجلسها:","6:10":"في بيوت الأشرار كنوز مسروقة وموازين مغشوشة.","6:11":"فكيف أبرىء ذا المعايير المغشوشة، صاحب كيس الموازين الناقصة؟","6:12":"قد امتلأ أثرياء المدينة ظلما، ونطق سكانها بالكذب وألسنة الغش في أفواههم","6:13":"لذلك شرعت في تدميرك لأجعلك خرابا من أجل خطاياك.","6:14":"ستأكلين ولا تشبعين، ويظل جوفك خاويا. وما تدخرينه تعجزين عن الاحتفاظ به. لأني أدفعه للسيف.","6:15":"تزرعين ولا تحصدين. تعصرين الزيتون ولا تدهني بزيته، وتعصرين العنب ولا تشربين من خمره.","6:16":"لأنك قد مارست فرائض عمري، ونهجت على غرار أخآب، وسلكت في مشوراتهم. لذلك أجعلك خرابا، وشعبك مثار سخرية، وتقاسون من احتقار الأمم.","7:1":"ويل لي، فقد صرت كرجل جائع جاء يبحث عن جني الصيف وبقايا قطاف العنب، فلم يجد عنقودا للأكل ولا شيئا من باكورة التين مما تشتهيه نفسي.","7:2":"قد باد الصالح من الأرض واختفى المستقيم من بين الناس. جميعهم يكمنون لسفك الدماء، وكل واحد منهم يقتنص أخاه.","7:3":"تجد أيديهم في ارتكاب الشر، ويسعى الرئيس والقاضي وراء الرشوة، ويملي العظيم عليهم أهواء نفسه، فيتآمرون جميعا على الحق.","7:4":"أفضلهم مثل العوسج، وأكثرهم استقامة أسوأ من سياج الشوك. وها يوم عقابكم الذي أنذر به أنبياؤكم قد وافى. عندئذ يعتريكم الارتباك.","7:5":"لا تأتمن جارك ولا تثق بصديق، واحترس مما تنطق به شفتاك ممن ترقد في حضنك.","7:6":"فإن الابن يستخف بأبيه والابنة تتمرد على أمها، والكنة على حماتها، وأعداء الإنسان أهل بيته.","7:7":"أما أنا فأرتقب الرب وأنتظر إله خلاصي فيسمعني إلهي.","7:8":"لا تشمتي بي ياعدوتي، لأني إن سقطت أقوم، وإن جلست في الظلمة يكون الرب نورا لي.","7:9":"إني أخطأت إلى الرب لذلك أتحمل غضبه، إلى أن يدافع عني ويثبت استقامتي، فيخرجني إلى النور لأشاهد عدله.","7:10":"عندئذ ترى ذلك عدوتي فيعتريها الخزي إذ قالت لي: «أين هو الرب إلهك؟» ستشهدها عيناي تداس كطين الشوارع والأزقة.","7:11":"ها قد أقبل يوم بناء أسوار مدينتك.في ذلك اليوم تتسع تخومك.","7:12":"ويتقاطر إليك شعبك في ذلك اليوم، من أشور ومن مدن مصر حتى نهر الفرات؛ من بحر إلى بحر؛ ومن جبل إلى جبل.","7:13":"غير أن الأرض تكون موحشة بسبب سيئات سكانها.","7:14":"ارع يارب شعبك بعصاك، فهم قطيع ميراثك الرابضون وحدهم في الغابة في وسط الكرمل. قدهم إلى باشان وجلعاد ليتمتعوا بخصب أرضهما كالعهد بهم في أيام القدم.","7:15":"ويجيب الرب: سأريهم معجزات كما فعلت في أيام خروجهم من ديار مصر.","7:16":"فترى الأمم ويخزون من قوتهم ويضعون أيديهم على أفواههم وتصاب آذانهم بالصمم.","7:17":"ويلحسون التراب كالحية وينسلون من حصونهم مرتعبين كزواحف الأرض، ويرجعون بخوف إلى الرب إلهنا مرتعبين منك.","7:18":"إي إله مثلك يصفح عن الإثم ويعفو عن معصية بقية ميراثه؟ لا يحتفظ إلى الأبد بغضبه لأنه يسر بالرحمة.","7:19":"يعود يرحمنا ويطأ ذنوبنا بقدميه، ويطرح معاصينا إلى أعماق البحر.","7:20":"أنت تبدي أمانة لذرية يعقوب، ورحمة لنسل إبراهيم، كما حلفت لأجدادنا منذ القدم."},"Nah":{"1:1":"وحي بشأن نينوى، كما ورد في كتاب رؤيا ناحوم الألقوشي.","1:2":"الرب إله غيور ومنتقم. الرب منتقم وساخط ينتقم من أعدائه، ويضمر الغضب لخصومه.","1:3":"الرب بطيء في غضبه وعظيم العزة، إنما لا يبريء الخاطيء البتة. طريق الرب في الزوبعة والعاصفة، والغمام غبار قدميه.","1:4":"يزجر البحر فيجففه. ينضب جميع الأنهار، فتذوي مراعي باشان والكرمل، ويذبل زهر لبنان.","1:5":"تتزلزل الجبال أمامه، وتذوب التلال، وتتصدع الأرض في حضرته والمسكونة والساكنون فيها.","1:6":"من يصمد أمام سخطه؟ من يتحمل فرط اضطرام غضبه؟ ينصب غضبه كالنار وتنحل تحت وطأته الصخور.","1:7":"الرب صالح، حصن في يوم الضيق، ويعرف المعتصمين به.","1:8":"ولكنه بطوفان طام يخفي معالم نينوى، وتدرك الظلمة أعداءه.","1:9":"لماذا تتآمرون على الرب؟ إنه يقضي على مؤامرتكم، ويفنيكم بضربة واحدة.","1:10":"وتلتهمهم النار كما تلتهم شجرة عليق كثيفة أو سكارى مترنحين من خمرهم أو حزمة قش جافة.","1:11":"منك خرج يانينوى من تآمر بالشر على الرب، والمشير بالسوء.","1:12":"وهذا ما يقوله الرب: مع أنكم أقوياء وكثيرون فإنكم تستأصلون وتفنون. أما أنتم ياشعبي فقد عاقبتكم أشد عقاب ولن أنزل بكم الويلات ثانية.","1:13":"بل أحطم الآن نير أشور عنكم، وأكسر أغلالكم.","1:14":"وها الرب قد أصدر قضاءه بشأنك ياأشور: لن تبقى لك ذرية تحمل اسمك. وأستأصل من هيكل آلهتك منحوتاتك ومسبوكاتك، وأجعله قبرك، لأنك صرت نجسا.","1:15":"هوذا على الجبال (تسير) قدما المبشر حامل الأخبار السارة، الذي يعلن السلام. فيايهوذا واظب على الاحتفال بأعيادك وأوف نذورك لأنه لن يهاجمك الشرير من بعد، إذ قد انقرض تماما.","2:1":"قد زحف عليك المهاجم يانينوى، فاحرسي الحصن وراقبي الطريق، منعي أسوارك، وجندي كل قوتك.","2:2":"لأن الرب يعيد بهاء يعقوب ومجد إسرائيل، لأن الناهبين سلبوهم وأتلفوا كرومهم.","2:3":"تروس أبطاله مخضبة بالاحمرار، وجنوده المحاربون مسربلون بالقرمز. يبرق فولاذ المركبات في يوم تأهبها، وتتبختر جيادها.","2:4":"تتراكض المركبات بعنف في الشوارع، وعبر الساحات تمرق كالبرق ومنظرها كالمشاعل المتوهجة.","2:5":"يستدعي الملك ضباطه، فيسرعون إليه متعثرين في خطاهم، يهرولون إلى سور المدينة وقد أقيمت المتاريس.","2:6":"قد انفتحت بوابات الأنهار، وانهار القصر أمام جحافل الأعداء.","2:7":"أصبحت سيدة القصر عارية مسوقة إلى الأسر، وشرعت جواريها ينحن كنوح الحمام ويضربن صدورهن.","2:8":"نينوى كبركة نضبت مياهها، إذ فر أهلها. وتعلو الصرخة: «قفوا، قفوا». ولا من مجيب يلتفت.","2:9":"انهبوا الفضة، انهبوا الذهب. لا نهاية لكنوزها أو لنفائس ثروتها.","2:10":"أضحت موحشة خاوية جرداء، ذابت منها القلوب رعبا وانحلت منها الركب، طغى عليها الألم وعلا وجوه أهلها الشحوب.","2:11":"أين نينوى عرين الأسود ومرتع الأشبال حيث يسرح الأسد واللبوءة والأشبال من غير إزعاج؟","2:12":"قد افترس الأسد ما يكفي لإعالة أشباله وخنق فريسة للبوءاته. قد ملأ عرينه بقنائصه وكهفه بأشلائهم.","2:13":"ها أنا أقاومك. يقول الرب القدير. فأحرق مركباتك فتصبح دخانا، ويلتهم السيف لحوم أبنائك، وأستأصل من الأرض غنائمك ولن يتردد في ما بعد صوت مندوبيك.","3:1":"ويل للمدينة السافكة الدماء الممتلئة كذبا، المكتظة بالغنائم المنهوبة، التي لا تخلو أبدا من الضحايا.","3:2":"ها فرقعة السياط وقعقعة العجلاتِ وجلبة حوافر الخيول وصلصلة المركبات.","3:3":"وفرسان واثبة، وسيوف لامعة ورماح بارقة وكثرة قتلى وأكوام جثث لا نهاية لها، بها يتعثرون.","3:4":"كل هذا من أجل كثرة زنى نينوى الفاتنة الآسرة ومن أجل سحرها القاتل. لقد استعبدت الشعوب بعهرها والأمم بشعوذتها.","3:5":"ها أنا أقاومك، يقول الرب القدير، فأكشف عارك لأطلع الأمم على عورتك والممالك على خزيك.","3:6":"وألوثك بالأوساخ وأحقرك وأجعلك عبرة.","3:7":"وكل من يراك يعرض عنك قائلا: «قد خربت نينوى فمن ينوح عليها؟ أين أجد لها معزين؟»","3:8":"هل أنت أفضل من طيبة الجاثمة إلى جوار النيل المحاطة بالمياه، المتمنعة بالبحر وبأسوار من المياه.","3:9":"كوش ومصر كانتا قوتها اللامتناهية، وفوط وليبيا من حلفائها.","3:10":"ومع ذلك فقد وقعت أسيرة واقتيدت إلى السبي، وتمزق أطفالها أشلاء في زاوية كل شارع، واقترع على عظمائها، وصفد نبلاؤها بالأغلال.","3:11":"وأنت أيضا تسكرين وتترنحين، وتلتمسين ملجأ من الأعداء","3:12":"وتتساقط جميع حصونك كتساقط بواكير أثمار أشجار التين الناضجة في أفواه من يهزونها.","3:13":"انظري إلى جنودك مرتعبين كالنساء في وسطك. صارت أبواب أرضك مفتوحة أمام أعدائك. وشرعت النيران تلتهم مزاليجك.","3:14":"خز ني ماء تأهبا للحصار، حصني قلاعك. دوسي أكوام الطين لتجهزي الطوب؛ أصلحي قوالب الطين.","3:15":"هناك تلتهمك النار، ويستأصلك السيف، فيبيدك الأعداء كالجراد. تكاثري كالجراد وكالجنادب.","3:16":"قد أضحى تجارك أكثر من كواكب السماء، ولكنهم تبددوا كجراد فرد أجنحته وطار.","3:17":"أصبح رؤساؤك كالجنادب، وقادتك كأسراب الجراد المتكومة على سياج في يوم بارد. ما إن تشرق الشمس حتى تطير بعيدا إلى حيث لا يعلم أحد.","3:18":"قد نام رعاتك ياملك أشور، وغرق عظماؤك في سبات عميق، تشتت شعبك على الجبال ولا يوجد من يجمعهم.","3:19":"لا جبر لكسرك، وجرحك مميت. وكل من يسمع بما جرى لك يصفق ابتهاجا لما أصابك، فمن لم يعان من شرك المتمادي؟"},"Hab":{"1:1":"هذه رؤيا حبقوق النبي:","1:2":"إلى متى يارب أستغيث وأنت لا تستجيب؟ وأصرخ إليك مستجيرا من الظلم وأنت لا تخلص؟","1:3":"لماذا تريني الإثم، وتتحمل رؤية الظلم؟ أينما تلفت أشهد أمامي جورا واغتصابا، ويثور حولي خصام ونزاع.","1:4":"لذلك بطلت الشريعة، وباد العدل لأن الأشرار يحاصرون الصديق فيصدر الحكم منحرفا عن الحق.","1:5":"تأملوا الأمم وأبصروا. تعجبوا وتحيروا لأني مقبل على إنجاز أعمال في عهدكم إذا حدثتم بها لا تصدقونها.","1:6":"فها أنا أثير الكلدانيين، هذه الأمة الحانقة المندفعة الزاحفة في رحاب الأرض، لتستولي على مساكن ليست لها.","1:7":"أمة مخيفة مرعبة، تستمد حكمها وعظمتها من ذاتها.","1:8":"خيولها أسرع من النمور، وأكثر ضراوة من ذئاب المساء. فرسانها يندفعون بكبرياء قادمين من أماكن بعيدة، متسابقين كالنسر المسرع للانقضاض على فريسته.","1:9":"يقبلون جميعهم ليعيثوا فسادا، ويطغى الرعب منهم على قلوب الناس قبل وصولهم، فيجمعون أسرى كالرمل.","1:10":"يهزأون بالملوك ويعبثون بالحكام. يسخرون من الحصون، يكومون حولها تلالا من التراب، ويستولون عليها.","1:11":"ثم يجتاحون كالريح ويرحلون، فقوة هؤلاء الرجال هي إلههم.","1:12":"ألست أنت منذ الأزل أيها الرب إلهي، قدوسي؟ لهذا لن نفنى. لقد أقمت الكلدانيين لمقاضاتنا واخترتهم ياصخرتي لتعاقبنا.","1:13":"إن عينيك أطهر من أن تشهدا الشر، وأنت لا تطيق رؤية الظلم، فكيف تحتمل مشاهدة الأثمة، وتصمت عندما يبتلع المنافقون من هم أبر منهم؟","1:14":"وكيف تجعل الناس كأسماك البحر، أو كأسراب الحشرات التي لا قائد لها؟","1:15":"إن الكلدانيين يستخرجونهم بالشصوص، ويصطادونهم بالشبكة، ويجمعونهم في مصيدتهم متهللين فرحين.","1:16":"لهذا هم يقربون ذبائح لشباكهم، ويحرقون بخورا لمصائدهم، لأنهم بفضلها يتمتعون بالرفاهية ويتلذذون بأطايب الطعام.","1:17":"أمن أجل هذا يظلون يفرغون شباكهم ولا يكفون عن إهلاك الأمم إلى الأبد؟","2:1":"سأقف على مرصدي وأنتصب على الحصن، وأترقب لأرى ماذا يقول لي الرب، وبما أجيب عن شكواي.","2:2":"فأجابني الرب: «اكتب الرؤيا بوضوح على الألواح ليستطيع حتى الراكض قراءتها بسهولة وحملها للآخرين.","2:3":"لأن الرؤيا لا تتحقق إلا في ميعادها، وتسرع إلى نهايتها. إنها لا تكذب وإن توانت فانتظرها، لأنها لابد أن تتحقق ولن تتأخر طويلا.","2:4":"أما الرسالة فهي: إن ذا النفس المنتفخة غير المستقيمة مصيره الهلاك، أما البار فبالإيمان يحيا.","2:5":"وكما أن الخمر غادرة، كذلك تأخذ المغتر نشوة الانتصار فلا يستكين، فإن جشعه في سعة الهاوية، وهو كالموت لا يشبع. لهذا يجمع لنفسه كل الأمم ويسبي جميع الشعوب.","2:6":"ولكن لا يلبث أن يسخر منه سباياه قائلين: «ويل لمن يكوم لنفسه الأسلاب، ويثرى على حساب ما نهب. إنما إلى متى؟","2:7":"ألا يقوم عليك دائنوك بغتة، أو لا يثورون عليك ويملأونك رعبا، فتصبح لهم غنيمة؟","2:8":"لأنك سلبت أمما كثيرة فإن بقية الشعوب ينهبونك ثأرا لما سفكت من دماء وارتكبت من جور في الأرض، فدمرت مدنا وأهلكت الساكنين فيها.","2:9":"ويل لمن يدخر لبنيه مكسب ظلم، ويشيد مسكنه في مقام حصين ليكون في مأمن من الخطر.","2:10":"لقد لطخت مؤامرتك بيتك بالعار حين استأصلت أمما عديدة وجلبت الدمار على نفسك.","2:11":"حتى حجارة الجدران تصرخ من شرك، فتردد الدعائم الخشبية أصداءها.","2:12":"ويل لمن يبني مدينة بالدماء، ويؤسس قرية بالإثم.","2:13":"ألم يصدر القضاء من عند الرب القدير أن يؤول تعب الشعوب إلى النار وجهد الأمم إلى الباطل؟","2:14":"لأن الأرض ستمتليء من معرفة مجد الرب كما تغمر المياه البحر.","2:15":"ويل لمن يسقي صاحبه من كأس الغضب إلى أن يسكر لينظر إلى خزيه.","2:16":"فأنت تشبع خزيا عوض المجد، فاشرب أنت، وترنح، فإن كأس يمين الرب تدور عليك ويجلل العار مجدك.","2:17":"لأن ما ارتكبته من ظلم في حق لبنان يغطيك، وما أهلكته من بهائم يروعك. من أجل ما سفكته من دماء واقترفته من جور في الأرض والمدن والساكنين فيها.","2:18":"أي جدوى من تمثال حتى يصوغه صانع، أو صنم يعلم الكذب لأن من يصنعه يتكل على ما صنعه، وهو لم يصنع سوى أصنام بكماء.","2:19":"ويل لمن يقول لمنحوت خشبي: «استيقظ» أو لحجر أبكم: «انهض». أيمكن أن يهدي؟ إنما هو مغشى بالذهب والفضة وخال من كل حياة.","2:20":"أما الرب ففي هيكله المقدس، فلتصمت الأرض كلها في محضره».","3:1":"هذه صلاة النبي حبقوق:","3:2":"«يارب قد بلغني ما فعلت فخفت يارب، عملك في وسط السنين أحيه، وعرف به على مر الأيام، واذكر الرحمة في الغضب.","3:3":"قد أقبل الله من أدوم، وجاء القدوس من جبل فاران. غمر جلاله السماوات وامتلأت الأرض من تسبيحه.","3:4":"إن بهاءه كالنور، ومن يده يومض شعاع، وهناك يحجب قوته.","3:5":"يتقدمه وبأ، والموت يقتفي خطاه.","3:6":"وقف وزلزل الأرض، تفرس فأرعب الأمم، اندكت الجبال الأبدية وانهارت التلال القديمة، أما مسالكه فهي من الأزل.","3:7":"لقد رأيت خيام كوشان تنوء بالبلية وشقق أخبية ديار مديان ترجف رعبا.","3:8":"هل غضبك منصب على الأنهار يارب؟ أعلى الأنهار احتدم سخطك؟ أم على البحر سكبت جام غيظك، عندما ركبت خيولك ومركبات ظفرك؟","3:9":"جردت قوسك وتأهبت لإطلاق سهامك الكثيرة، وشققت الأرض أنهارا.","3:10":"رأتك الجبال فارتعدت، وطمت المياه الهائجة. زأرت اللجج وارتفعت أمواجها عالية.","3:11":"القمر والشمس توقفا في منازلهما أمام وميض سهامك المندفعة وبريق رمحك المتلأليء.","3:12":"تطأ الأرض بسخط، وبغضب تدوس الأمم.","3:13":"خرجت لخلاص شعبك، لخلاص مختارك. هشمت رؤوس زعماء البلاد الأشرار وتركتهم مطروحين عراة من العنق حتى أخمص القدم.","3:14":"طعنت برماحه قائد جيشهم المندفع كإعصار ليشتتنا بابتهاج من يفترس المسكين سرا","3:15":"خضت البحر بخيلك في وسط مياهه الهائجة.","3:16":"سمعت هذا فتولاني الفزع وارتجفت شفتاي من الصوت، وتسرب النخر إلى عظامي، وارتعشت قدماي. ولكن سأنتظر بصبر يوم البلية الذي يحيق بالأمة التي غزتنا.","3:17":"فمع أنه لا يزهر التين ولا يكون حمل في الكروم يكذب عمل الزيتونة والحقول لا تصنع طعاما ينقطع الغنم من الحظيرة ولا بقر في المذاود","3:18":"فإني أبتهج بالرب وأفرح بإله خلاصي.","3:19":"الرب الإله هو قوتي؛ يجعل قدمي كقدمي غزال، ويعينني على ارتقاء المرتفعات.إلى قائد الجوقة: تغنى على ذوات الأوتار."},"Joe":{"1:1":"هذا ما أوحى به الرب إلى يوئيل بن فثوئيل:","1:2":"اسمعوا هذا أيها الشيوخ، وأصغوا ياجميع أهل الأرض، هل جرى مثل هذا في أيامكم أو في أيام آبائكم؟","1:3":"أخبروا بهذا أبناءكم، وليخبر أبناؤكم أبناءهم لينقلوه إلى الأجيال القادمة.","1:4":"إن ما تخلف من محصولكم عن هجمات الزحاف التهمته أسراب الجراد، وما تفضل عن أسراب الجراد أكلته الجنادب؛ وما بقي عن الجنادب قضى عليه الطيار.","1:5":"اصحوا أيها السكارى، وابكوا ياجميع مدمني الخمر على العصير لأنه قد انقطع عن أفواهكم.","1:6":"فإن أمة قد زحفت على أرضي، أمة قوية لا تحصى لكثرتها. لها أسنان ليث وأنياب لبؤة،","1:7":"فأتلفت كرومي وحطمت أشجار بيتي وسلخت قشورها وطرحتها، فابيضت أغصانها.","1:8":"نوحوا كما تنوح صبية متشحة بالمسوح على زوجها الذي مات.","1:9":"لأن تقدمات الدقيق والخمر قد انقطعت عن بيت الرب، وانتحب الكهنة خدام الرب.","1:10":"قد خربت الحقول، وناحت الأرض لأن الحنطة تلفت والخمرة انقطعت، وافتقد زيت الزيتون.","1:11":"اخزوا أيها الحراثون وأعولوا أيها الكرامون على الحنطة والشعير، لأن حصاد الحقل قد تلف.","1:12":"قد ذوى الكرم وذبل التين والرمان والنخيل والتفاح ويبست سائر أشجار الحقل، وزالت البهجة من أبناء البشر.","1:13":"أيها الكهنة اتشحوا بالمسوح ونوحوا. ولولوا ياخدام المذبح. تعالوا وبيتوا ليلتكم بالمسوح ياخدام إلهي، لأن تقدمات الدقيق والخمر قد منعت عن هيكل الله.","1:14":"خصصوا صوما. نادوا بالاعتكاف. ادعوا الشيوخ وجميع سكان الأرض للاجتماع في هيكل الرب إلهكم وتضرعوا إليه.","1:15":"يا له من يوم رهيب، لأن يوم الرب قريب يأتي حاملا معه الدمار من عند القدير.","1:16":"ألم ينقطع الطعام أمام عيوننا، ألم يتلاش الفرح والغبطة من بيت إلهنا؟","1:17":"قد تعفنت الحبوب المزروعة في الأرض الجافة، وتهدمت المخازن وفرغت الأهراء من القمح، لأن الحبوب قد جفت.","1:18":"لكم أنت البهائم، وشردت المواشي إذ افتقرت إلى المرعى. حتى قطعان الغنم هلكت أيضا.","1:19":"إليك يارب أصرخ لأن النار قد التهمت مراعي البرية، وأحرق اللهيب كل أشجار الحقل.","1:20":"حتى الحيوانات البرية استغاثت بك، لأن مياه الجداول الجارية قد جفت، والتهمت النيران مراعي البرية.","2:1":"انفخوا بالبوق في صهيون، وأطلقوا نفير الإنذار في جبل قدسي، وليرتعد جميع سكان الأرض، لأن يوم الرب مقبل وقد بات وشيكا.","2:2":"هو يوم ظلمة وتجهم، يوم غيوم مكفهرة وقتام دامس،فيه تزحف أمة قوية وعظيمة كما يزحف الظلام على الجبال، أمة لم يكن لها شبيه في سالف الزمان، ولن يكون لها نظير من بعدها عبر سني الأجيال.","2:3":"تلتهم النار ما أمامها، ويحرق اللهيب ما خلفها. الأرض قدامها كجنة عدن، وخلفها صحراء موحشة، ولا شيء ينجو منها.","2:4":"منظرهم كالخيول، وكأفراس الحرب يركضون.","2:5":"يثبون على رؤوس الجبال في جلبة كجلبة المركبات، كفرقعة لهيب نار يلتهم القش، وكجيش عات مصطف للقتال.","2:6":"تنتاب الرعدة منهم جميع الشعوب وتشحب كل الوجوه.","2:7":"يندفعون كالجبابرة وكرجال الحرب يتسلقون السور، وكل منهم يزحف في طريقه لا يحيد عن سبيله.","2:8":"لا يزاحم بعضهم بعضا. بل يتقدم كل منهم في طريقه. ينسلون بين الأسلحة من غير أن يتوقفوا.","2:9":"ينقضون على المدينة ويتواثبون فوق الأسوار، يتسلقون البيوت ويتسللون من الكوى كاللص.","2:10":"ترتعد الأرض أمامهم وترجف السماء، تظلم الشمس والقمر، وتكف الكواكب عن الضياء.","2:11":"يجهر الرب بصوته في مقدمة جيشه لأن جنده لا يحصى لهم عدد، ومن ينفذ أمره يكون مقتدرا، لأن يوم الرب عظيم ومخيف جدا، فمن يتحمله؟","2:12":"والآن، يقول الرب: ارجعوا إلي من كل قلوبكم بصوم وبكاء ونوح.","2:13":"مزقوا قلوبكم لا ثيابكم. ارجعوا إلى الرب إلهكم لأنه رؤوف ورحيم بطيء الغضب وكثير الرأفة، ولا يسر بالعقاب.","2:14":"لعله يرجع ويكف عن العقاب مخلفا وراءه بركة: تقدمة دقيق وتقدمة سكيب لتقربوهما للرب إلهكم.","2:15":"انفخوا بالبوق في صهيون، وقدسوا صوما، ونادوا لمحفل مقدس.","2:16":"اجمعوا الشعب، قدسوا الجماعة، احشدوا الشيوخ والأولاد والرضع. ليغادر العريس مخدعه والعروس حجرتها.","2:17":"ليبك الكهنة خدام الرب بين الرواق والمذبح قائلين: «اعف عن شعبك يارب ولا تجعل ميراثك مثار احتقار وهزء بين الأمم، فيقولوا بين الشعوب: أين إلههم؟»","2:18":"عندئذ يغار الرب على أرضه ويرق لشعبه.","2:19":"ويجيبهم قائلا: ها أنا أنعم عليكم بالحنطة والخمرة والزيت فتشبعون منها، ولا أجعلكم من بعد عارا بين الأمم.","2:20":"سأطرد عنكم الشمالي، وأطوح به إلى أرض مقفرة موحشة فتكون طليعته في البحر الميت ومؤخرته في البحر الأبيض، فتملأ رائحة نتنه وعفونته الفضاء، لأنه قد ارتكب الكبائر.","2:21":"لا تخافي أيتها الأرض، ابتهجي وافرحي لأن الرب قد صنع عظائم.","2:22":"لا تخافي يابهائم الحقل، لأن مراعي البر قد أضحت خضراء، والأشجار باتت مثقلة بالثمار، وشجرة التين والكرمة تجودان بنتاجهما.","2:23":"افرحوا ياأبناء صهيون، ابتهجوا بالرب إلهكم لأنه أنعم عليكم بفضل صلاحه بأمطار الخريف، وسكب عليكم الغيث المبكر والمتأخر بغزارة، كالسابق.","2:24":"فتمتليء البيادر بأكوام القمح، وتتدفق المعاصر بالخمرة والزيت.","2:25":"وأعوضكم عن محاصيل السنين التي التهمها الجراد والجندب والطيار والقمص، جيشي العظيم الذي أطلقته عليكم.","2:26":"فتأكلون بوفرة وتشبعون وتسبحون اسم الرب إلهكم الذي أجرى لكم العجائب، ولن يخزى شعبي ثانية.","2:27":"فتدركون أني في وسط إسرائيل، وأني أنا هو الرب إلهكم وليس غيري، ولن يخزى شعبي ثانية.","2:28":"ثم أسكب روحي على كل بشر، فيتنبأ أبناؤكم وبناتكم، ويحلم شيوخكم أحلاما ويرى شبابكم رؤى.","2:29":"وأسكب في تلك الأيام أيضا روحي على العبيد والإماء.","2:30":"وأجري آيات في السماء وعلى الأرض، دما ونارا وأعمدة دخان.","2:31":"وتتحول الشمس إلى ظلام، والقمر إلى دم، قبل مجيء يوم الرب العظيم المخيف.","2:32":"إنما كل من يدعو باسم الرب يخلص، لأن النجاة تكون في جبل صهيون وفي أورشليم، كما قال الرب، إذ يكون بين الناجين من يدعوه الرب.","3:1":"لأنه في تلك الأيام، وفي ذلك الحين عندما أرد سبي يهوذا وأورشليم،","3:2":"أجمع الأمم كلها وأحضرهم إلى وادي يهوشافاط، وأحاكمهم هناك من أجل شعبي وميراثي إسرائيل، لأنهم شتتوهم بين الشعوب واقتسموا أرضي.","3:3":"وألقوا القرعة على شعبي فقايضوا الزانية بالصبي، وباعوا الصبية لقاء شربة خمر.","3:4":"ماذا لديكم ضدي ياصور وصيدون وسائر أقاليم فلسطين؟ أتجازونني على أمر أتيته؟ أم تسعون لإيذائي؟ إني أنزل العقاب على رؤوسكم بغتة وسريعا.","3:5":"لأنكم قد استوليتم على ذهبي وفضتي، ونقلتم نفائسي إلى هياكلكم.","3:6":"وبعتم يهوذا وأبناء أورشليم إلى الأغارقة لتبعدوهم عن تخوم أرضهم.","3:7":"وها أنا الآن أنهضهم من الموضع حيث بعتموهم، وأرد على رؤوسكم سوء أعمالكم.","3:8":"وأبيع أبناءكم وبناتكم بأيدي أبناء يهوذا، فيبيعونهم بدورهم إلى السبئيين، إلى أمة بعيدة، لأن الرب قد أصدر قضاءه.","3:9":"نادوا بهذا بين الأمم، وتأهبوا للحرب. احشدوا أبطالكم. ليتقدم ويصعد جميع رجال القتال.","3:10":"أطرقوا سكك محاريثكم وحولوها إلى سيوف، ومناجلكم إلى رماح، وليقل الضعيف: إنني جبار قتال!","3:11":"أسرعوا وتعالوا من كل ناحية يا كل الأمم، واجتمعوا هناك، وأنزل يارب محاربيك.","3:12":"لتنهض الأمم وتقبل إلى وادي القضاء لأنني هناك أجلس لأدين الشعوب المتوافدة من كل جهة.","3:13":"احملوا المنجل لأن الحصيد قد نضج. تعالوا ودوسوا فإن معصرة الخمر قد امتلأت، والحياض فاضت بكثرة شرهم.","3:14":"جماهير جماهير متزاحمة في وادي القضاء، لأن يوم الرب قريب في وادي القضاء.","3:15":"قد أظلمت الشمس والقمر، وكفت الكواكب عن الضياء.","3:16":"يزأر الرب في صهيون، ويجلجل بصوته من أورشليم فترجف السماوات والأرض؛ لكن الرب يكون ملجأ لشعبه، وحصنا لبني إسرائيل.","3:17":"فتدركون أني أنا هو الرب إلهكم الساكن في صهيون جبلي المقدس، وتكون أورشليم مقدسة ولا يجتاز فيها الغرباء أبدا.","3:18":"وتقطر الجبال في ذلك اليوم خمرة عذبة، وتفيض التلال باللبن وجميع ينابيع يهوذا تتدفق ماء، ويخرج ينبوع من هيكل الرب يروي وادي السنط،","3:19":"وتصبح مصر خرابا، وأدوم قفرا موحشا لفرط ما أنزلوه من ظلم بأبناء يهوذا، ولأنهم سفكوا دما بريئا في ديارهم.","3:20":"أما يهوذا فإنه يسكن الأرض إلى الأبد، وتعمر أورشليم مدى الأجيال.","3:21":"وأزكي دمهم الذي لم أبرئه، لأن الرب يسكن في صهيون."},"Amo":{"1:1":"هذه كلمات عاموس الذي كان راعيا من رعاة تقوع، ينبيء فيها بما رآه بشأن إسرائيل في أيام عزيا ملك يهوذا، وفي أيام يربعام بن يوآش ملك إسرائيل، قبل وقوع الزلزلة بسنتين.","1:2":"قال: «يزأر الرب من صهيون ويدوي بصوته من أورشليم، فتنتحب مراعي الرعاة، وتذوي قمة الكرمل.","1:3":"هذا ما يقوله الرب: من أجل معاصي دمشق الثلاث والأربع لن أرد عنها سخطي، لأن أهلها قد داسوا شعبي في جلعاد بنوارج من حديد.","1:4":"لذلك أرسل نارا على بيت حزائيل فتلتهم حصون بنهدد.","1:5":"وأحطم مزلاج دمشق وأستأصل أهل وادي آون، وأهلك حامل صولجان ملك بيت عدن، ويساق شعب أرام إلى السبي إلى أرض قير.","1:6":"هذا ما يقوله الرب: من أجل معاصي غزة الثلاث والأربع لن أرد عنها سخطي، لأن أهلها نفوا شعبا عن آخره ليسلموه إلى أدوم.","1:7":"لذلك سأرسل نارا على أسوار غزة تلتهم حصونها.","1:8":"وأستأصل أهل أشدود، وأهلك حامل صولجان ملك أشقلون، وأوجه ضرباتي ضد عقرون فيفنى من بقي من الفلسطينيين.","1:9":"هذا ما يقوله الرب: من أجل معاصي صور الثلاث والأربع لن أرد عنها سخطي، لأن أهلها سلموا شعبا بكامله إلى أدوم، ونقضوا عهد الإخوة.","1:10":"لهذا أرسل نارا على أسوار صور فتلتهم حصونها.","1:11":"وهذا ما يقوله الرب: من أجل معاصي أدوم الثلاث والأربع لن أرد عنهم سخطي، لأنهم تعقبوا إخوتهم بالسيف، وتغاضوا عن كل رحمة، وجعلوا غضبهم يتأجج ملتهما باستمرار، وظلوا حاقدين على الدوام.","1:12":"فأرسل نارا على تيمان، فتلتهم حصون بصرة.","1:13":"هذا ما يقوله الرب: من أجل معاصي العمونيين الثلاث والأربع لن أرد عنهم سخطي، لأنهم شقوا بطون الحوامل في جلعاد ليوسعوا تخمهم.","1:14":"لهذا أضرم نارا في سور ربة فتلتهم حصونها في معترك جلبة يوم الحرب، وفي وسط عاصفة في يوم الزوبعة.","1:15":"ويساق ملكهم إلى السبي مع سائر رؤسائه يقول الرب.","2:1":"هذا ما يقوله الرب: من أجل معاصي موآب الثلاث والأربع لن أرد عنهم سخطي، لأن موآب أحرق عظام ملك أدوم حتى صارت كلسا.","2:2":"لهذا أرسل نارا على موآب فتلتهم حصون قريوت، فيموت موآب في وسط الضجيج وصيحات المحاربين ودوي الأبواق.","2:3":"وأستأصل الحاكم من بين الموآبيين، وأقضي على كل رؤسائهم، يقول الرب.","2:4":"هذا ما يقوله الرب: من أجل معاصي يهوذا الثلاث والأربع لن أرد عنهم سخطي، لأنهم رفضوا شريعة الرب ولم يطيعوا فرائضه، فأضلتهم أكاذيبهم التي غوى وراءها آباؤهم.","2:5":"لهذا أرسل نارا على يهوذا فتلتهم حصون أورشليم.","2:6":"هذا ما يقوله الرب: من أجل معاصي إسرائيل الثلاث والأربع لن أرد عنهم سخطي، لأنهم باعوا الصديق لقاء الفضة، والبائس مقابل نعلين.","2:7":"الذين يسحقون رأس المسكين في التراب، ويجورون على البائسين، ويعاشر الرجل وابنه امرأة واحدة، فيتدنس بذلك اسمي المقدس.","2:8":"يرقدون إلى جوار المذبح فوق ثياب مرهونة، ويشربون في هيكل إلههم خمر المغرمين.","2:9":"مع أني أهلكت من أمامهم الأموريين ذوي القامات الطويلة كأشجار الأرز، الأقوياء كأشجار البلوط، أتلفت أثمارهم على أغصانها، وجذور أشجارهم من تحت الأرض.","2:10":"كما أخرجتكم من ديار مصر وقدت طريقكم عبر الصحراء طوال أربعين سنة لترثوا أرض الأموريين.","2:11":"وأقمت من بين أبنائكم أنبياء ومن فتيانكم نذيرين. أليس هذا صحيحا ياأبناء إسرائيل، يقول الرب؟","2:12":"ولكنكم سقيتم النذيرين خمرا، وأمرتم الأنبياء قائلين: لا تتنبأوا.","2:13":"هأنذا أسحقكم في مواضعكم فتئنون كما تئن عربة تحت وطأة ثقل أكداسها.","2:14":"فلا يتاح الهرب للسريع، وتتلاشى قوة الجبار، ويعجز القوي عن إنقاذ نفسه.","2:15":"ولا يصمد رامي القوس ولا يصيب الهدف، ولا يسلم سريع العدو، ولا ينجو راكب الفرس بحياته.","2:16":"والثابت الجنان بين أقرانه الأبطال يفر عريانا في ذلك اليوم، يقول الرب.","3:1":"اسمعوا يابني إسرائيل هذه الكلمة التي قضى بها الرب عليكم، بل على كل القبيلة التي أخرجتها من ديار مصر:","3:2":"إياكم وحدكم اخترت من بين جميع قبائل الأرض، لهذا أعاقبكم على جميع آثامكم.","3:3":"هل يترافق اثنان معا ما لم يكونا على موعد؟","3:4":"أيزأر أسد في الغابة من غير أن يقع على فريسة؟ أيزمجر الشبل بصوته من عرينه ما لم يكن قد اقتنص شيئا؟","3:5":"أيسقط العصفور في فخ على الأرض إذا لم يكن هناك فخ منصوب؟ أينطبق فخ على الأرض من غير أن يكون قد أمسك شيئا؟","3:6":"أيدوي بوق في المدينة ولا يعتري الشعب الخوف؟ أيقع بلاء في المدينة ما لم يكن الرب قد أرسله؟","3:7":"إن السيد الرب لا يجري أمرا من غير أن يعلن سره لعبيده الأنبياء.","3:8":"قد زأر الأسد فمن لا يخاف، وتكلم الرب فمن لا يتنبأ؟","3:9":"أذيعوا في حصون أشدود وفي حصون ديار مصر وقولوا: احتشدوا على جبال السامرة، واشهدوا ما في وسطها من جلبة، وانظروا إلى المظلومين في داخلها.","3:10":"فهؤلاء الذين يكنزون الجور والنهب في قصورهم لا يعرفون التصرف باستقامة، يقول الرب.","3:11":"لذلك يعلن الرب الإله: سيجتاح العدو البلاد، ويحيل حصونكم حطاما وينهب قصوركم.","3:12":"هذا ما يقوله الرب: كما يعجز الراعي أن ينتزع من فم الأسد سوى رجلي حمل، أو قطعة من أذن، هكذا لن ينجو سوى القليل من شعب إسرائيل المقيمين في السامرة، المتكئين على الأرائك الوثيرة والأسرة الناعمة.","3:13":"اسمعوا واشهدوا على بيت يعقوب، يقول السيد الرب الإله القدير.","3:14":"في ذلك اليوم الذي أعاقب فيه إسرائيل على تعدياته، أهدم أيضا مذابح بيت إيل، وتقطع قرون المذبح وتتهاوى على الأرض.","3:15":"وأدمر البيوت التي يأوون إليها في الشتاء، وبيوت المنتجعات الصيفية، وتندك بيوت العاج وتزول من الوجود قصور كثيرة، يقول الرب.","4:1":"اسمعي هذه الكلمة يانساء باشان، اللواتي يقمن في جبل السامرة، ممن يظلمن المسكين ويسحقن الفقراء واللواتي يقلن لأزواجهن: هاتوا مسكرا لنشرب.","4:2":"قد أقسم السيد الرب بقداسته قائلا: ها أيام تقبل عليكن، يجركن فيها العدو بالكلاليب وذريتكن بشصوص السمك.","4:3":"وتخرج كل واحدة منكن من شق، زاحفة على وجهها، وتطردن إلى هرمون، يقول الرب.","4:4":"تعالوا إلى بيت إيل وارتكبوا المعاصي، وأقبلوا إلى الجلجال وكثروا ذنوبكم. قر بوا ذبائحكم في كل صباح، وعشوركم كل ثلاثة أيام.","4:5":"قدموا من الخمير قربان شكر، وأعلنوا متباهين عن تقدماتكم التطوعية، وتفاخروا بها، لأن هذا ما تحبون أن تفعلوه ياشعب إسرائيل، يقول السيد الرب.","4:6":"قد جعلت الجوع يعم مدنكم، فلم تتسخ أسنانكم بالطعام! وأفقرتكم إلى الخبز في كل أماكن سكناكم، ولكنكم لم ترجعوا إلي تائبين، يقول الرب.","4:7":"منعت عنكم المطر ولم يكن قد بقي للحصاد سوى ثلاثة أشهر، وأمطرت على مدينة دون مدينة، وعلى حقل دون الآخر، فجف الحقل الذي لم أمطر عليه.","4:8":"فأقبلت مدينتان أو ثلاث على مدينة واحدة لتشرب ماء، ولكنها لم ترتو، ومع ذلك لم ترجعوا إلي تائبين، يقول الرب.","4:9":"أرسلت الرياح اللافحة واليرقان لتجفف محاصيلكم، والتهم الجراد حدائقكم وكرومكم وأشجار تينكم وزيتونكم. وما رجعتم إلي!","4:10":"أصبتكم بالأوبئة التي أصيبت بها مصر، وقضيت على شبابكم بالسيف وسبيت خيولكم، وجعلت نتن معسكركم يزكم أنوفكم. ولكنكم لم ترجعوا إلي تائبين يقول الرب.","4:11":"دمرت بعض مدنكم كما دمر الله سدوم وعمورة، فكان من نجا منكم كشعلة منتشلة من النار. ولكنكم لم ترجعوا إلي تائبين.","4:12":"لذلك، هذا ما أجريه عليك ياإسرائيل. فمن أجل ما أصنعه بك تأهب للقاء إلهك.","4:13":"فانظر إنه هو صانع الجبال وخالق الرياح، الذي أعلن فكره للبشر، وأحال النهار إلى ليل، ومشى فوق مشارف الأرض، الرب الإله القدير اسمه.","5:1":"اسمعوا هذه المرثية التي أرثيكم بها يابني إسرائيل.","5:2":"قد سقطت عذراء إسرائيل ولن تنهض بعد. صارت طريحة على أرضها وليس من يقيمها.","5:3":"لأنه هكذا يقول الرب: إن المدينة التي قدمت ألفا من رجالها للحرب، لا يبقى لها منهم سوى مئة. والتي قدمت مئة منهم للحرب لا يبقى لبيت إسرائيل منهم سوى عشرة.","5:4":"لأن هذا ما يقوله الرب لبيت إسرائيل: التمسوني فتحيوا.","5:5":"لا تسعوا وراء بيت إيل، ولا تدخلوا الجلجال، ولا تعبروا إلى بئر سبع، لأن أهل الجلجال لابد أن يتم سبيهم، وبيت إيل تصبح عدما.","5:6":"التمسوا الرب فتحيوا لئلا يندلع كنار تحرق بيت يوسف وتلتهم بيت إيل، وليس من يطفيء.","5:7":"إنكم تحولون العدل مرارة، وتطرحون الحق إلى الأرض.","5:8":"إنه هو الذي خلق الثريا والجبار، ويحول دياجير الظلمة إلى نهار، والنهار إلى ليل، ويستدعي مياه البحر ويفيضها على وجه الأرض، الرب اسمه.","5:9":"الذي ينزل الخراب بالقوي، فيعصف الدمار بالحصون.","5:10":"قد أبغضوا من يندد بالجور في ساحة القضاء، ويكرهون من ينطق بالحق.","5:11":"فلأنكم تطأون المسكين وتبتزون منه رشوة قمح حتى تشيدوا بيوتا من حجارة منحوتة، فإنكم لن تسكنوا فيها، وتغرسوا كروما شهية ولكنكم لن تشربوا من خمرها.","5:12":"لأنني عالم بكثرة معاصيكم وعظم خطاياكم، إذ أنكم تضايقون البار أيها المرتشون الذين تصدون المسكين عن حقه في ساحة القضاء.","5:13":"لهذا يصمت العاقل في مثل هذا الزمان الرديء.","5:14":"اطلبوا الخير لا الشر لتحيوا، فيكون الرب الإله القدير معكم كما تقولون.","5:15":"امقتوا الشر وأحبوا الخير وأقيموا العدل في ساحة القضاء، لعل الرب الإله القدير يترفق على بقية بيت يوسف.","5:16":"لذلك، هذا ما يقوله الرب الإله القدير، سيملأ النحيب أرجاء الساحات، ويرتفع عويلهم في الشوارع قائلين: آه! آه! ويدعون الفلاحين إلى البكاء، والنادبات إلى الرثاء،","5:17":"وتعلو الولولة في جوانب الكروم، لأني سأجتاز منتقما في وسطكم يقول الرب.","5:18":"ويل للذين يتشوقون ليوم الرب. لماذا تطلبون مجيء يوم الرب؟ فيوم الرب هو ظلمة لا نور.","5:19":"فتكونون كرجل هرب من وجه أسد فلقيه دب، أو كمن دخل إلى بيت واتكأ بيده على حائط فلدغته أفعى.","5:20":"أو ليس يوم الرب ظلمة لا نورا، وقتاما خاليا من الضياء؟","5:21":"إني أمقت أعيادكم وأحتقرها، ولا أسر باحتفالاتكم.","5:22":"ومع أنكم تقربون لي ذبائح محرقاتكم وتقدماتكم من الدقيق، فإني لا أقبلها ولا ألتفت إلى ذبائح السلام من مسمنات مواشيكم.","5:23":"أبعدوا عني جلبة أغانيكم لأني لن أصغي إلى نغمات رباباتكم.","5:24":"إنما ليجر الحق متدفقا كالمياه والعدل كنهر سيال.","5:25":"هل قربتم لي ذبائح وتقدمات طوال أربعين سنة في البرية، يابيت إسرائيل؟","5:26":"بل إن الملك الذي حملتم خيمته ونصب تماثيله لم يكن سوى نجم صنعتموه لأنفسكم وعبدتموه كإله.","5:27":"لذلك أسبيكم إلى ما وراء دمشق، يقول الرب الذي اسمه الإله القدير.","6:1":"ويل للمترفين في صهيون والمطمئنين في جبل السامرة، نبلاء طليعة الأمم الذين يتوافد إليهم شعب إسرائيل.","6:2":"توجهوا إلى مدينة كلنة وتأملوا، ثم انتقلوا إلى حماة العظيمة، ومنها انحدروا إلى جت مدينة الفلسطينيين. هل هي خير من هذه الممالك أم تخومهم أعظم من تخومكم؟","6:3":"أنتم يامن تتجاهلون يوم السوء وتقربون كرسي الظلم.","6:4":"ويل للراقدين فوق أسرة من عاج، المسترخين فوق الأرائك، الآكلين لحم خيرة الحملان والعجول المختارة من وسط المعلف.","6:5":"المغنين على صوت الرباب، المخترعين لأنفسهم آلات غناء كداود.","6:6":"الشاربين خمرا في كؤوس، المتطيبين بأفضل العطور، ولا يكتئبون على خراب يوسف.","6:7":"لهذا سيكونون أول الذاهبين إلى السبي، ويزول ما أنتم عليه من لهو وعبث.","6:8":"ويقول الرب القدير: قد أقسمت بذاتي، أن أمقت زهو يعقوب، وأبغض قصوره، فأسلم المدينة بكل ما فيها.","6:9":"فيكون إذا بقي عشرة رجال في بيت واحد، أنهم يلقون حتفهم.","6:10":"وعندما يقبل عم الميت المشرف على إحراق الجثث ليخرج عظامه من البيت، ويسأل من هو مختبيء في أقصى المنزل: أما بقي واحد معك؟ فيجيب: لا، ثم يضيف: اصمت ولا تذكر اسم الرب.","6:11":"لأنه ها الرب يأمر، فيهدم البيت الكبير فيصير ركاما، والبيت الصغير حطاما.","6:12":"أتجري الخيول على الصخور؟ وهل يحرث البحر بثيران؟ لقد حولتم الحق سما زعافا، وثمار البر مرارة.","6:13":"أنتم أيها المبتهجون بالعدم القائلون: أليس بقوتنا ظفرنا؟","6:14":"ها أنا أثير عليكم أمة يابيت إسرائيل، يقول السيد الرب القدير، فيسومونكم العذاب من مدخل حماة إلى وادي العربة».","7:1":"وهذا ما أراني السيد الرب: ها هو يعد أسراب جراد في بدء نمو الأعشاب المتأخرة بعد أن تم جز نصيب الملك منها.","7:2":"وبعد أن فرغ الجراد من التهام عشب الأرض، قلت: «أيها السيد الرب، اصفح عن شعبك. إذ كيف يمكن ليعقوب أن ينهض، فإنه صغير؟»","7:3":"فعفا الرب عن هذا وقال: «لن يحدث ما رأيته».","7:4":"ثم هذا ما أراني السيد الرب: شاهدت السيد الرب يدعو للمحاكمة بالنار التي لعقت البحر العظيم فجف، وأكلت الحقول.","7:5":"عندئذ قلت: «أيها السيد الرب، كف عن هذا، إذ كيف يمكن ليعقوب أن ينهض، فإنه صغير؟»","7:6":"فعفا الرب عن هذا، وقال: «لن يحدث ما رأيته».","7:7":"ثم رأيت، وإذا الرب واقف بجوار حائط مبني، وفي يده ميزان البناء.","7:8":"فقال لي الرب: «ياعاموس، ماذا ترى؟» فأجبت: «ميزان البناء». فقال الرب: «ها أنا أمد ميزان البناء في وسط شعبي إسرائيل، ولن أعفو عنهم.","7:9":"فتقفر مرتفعات إسحاق ويعتري الخراب مقادس إسرائيل، وأثور على بيت يربعام بالسيف».","7:10":"فأرسل أمصيا كاهن بيت إيل إلى يربعام ملك إسرائيل قائلا: «قد تآمر عليك عاموس في وسط بيت إسرائيل، ولا تطيق الأرض تحمل كل تنبؤاته","7:11":"لأن هذا ما يقوله عاموس: إن يربعام يموت بحد السيف، ويسبى إسرائيل بعيدا عن دياره».","7:12":"ثم قال أمصيا لعاموس: «اهرب أيها الرائي إلى أرض يهوذا، وكل خبزا هناك وتنبأ فيها.","7:13":"أما بيت إيل فلا تعد للتنبوء فيها، لأنها مقدس الملك ومقر المملكة».","7:14":"فأجاب عاموس: «أنا لم أكن نبيا ولا ابن نبي، إنما أنا راعي غنم وجاني جميز،","7:15":"فاصطفاني الرب من وراء الغنم وأمرني قائلا: اذهب تنبأ لشعبي إسرائيل.","7:16":"لذلك اسمع الآن كلمة الرب: أنت تقول لا تتنبأ ضد إسرائيل ولا تهاجم بيت إسحاق.","7:17":"لهذا يقول الرب: ستصبح امرأتك عاهرة في المدينة، ويقتل أبناؤك وبناتك بالسيف، وتقسم أرضك بالحبل. أما أنت فتموت في أرض الأمم الوثنية، ويسبى إسرائيل إلى أرض بعيدة عن دياره».","8:1":"ثم أراني السيد الرب في رؤيا سلة لقطاف الثمار.","8:2":"وسألني: «ماذا ترى ياعاموس؟» فأجبت: «سلة مليئة بثمار الصيف الناضجة». فقال لي الرب: «لقد دنت نهاية شعبي إسرائيل ولن أعفو عنهم بعد.","8:3":"فتتحول أغاني قصورهم إلى عويل في ذلك اليوم، وتكثر الجثث ويطرحونها في كل مكان بصمت».","8:4":"استمعوا هذا أيها الدائسون على البائسين، يامن حاولتم أن تقضوا على فقراء الأرض،","8:5":"قائلين: «متى ينقضي أول الشهر حتى نبيع الحنطة؟ متى يمضي السبت لنعرض القمح في السوق، فنعمد إلى تصغير حجم مكيال الإيفة ونرفع الأسعار، ونستعمل ميزانا مغشوشا.","8:6":"لنشتري المسكين بقطعة من الفضة، والبائس بنعلين، ونبيع نفاية القمح؟»","8:7":"قد أقسم الرب بعزة يعقوب قائلا: «لن أنسى شيئا من مساوئهم.","8:8":"ألا ترتعب الأرض من جراء ذلك، فينوح كل ساكن فيها، فتطمو كنهر، وترتفع وتنخفض كنيل مصر؟","8:9":"ويقول الرب: في ذلك اليوم أجعل الشمس تغرب عند الظهيرة، وأغمر الأرض بالظلمة في رابعة النهار.","8:10":"أحول أعيادكم إلى مآتم، وأغانيكم إلى مراث، وألبسكم المسوح على أحقائكم، وأفشي الصلع في كل رأس، فتصبح أعيادكم كمناحة على وحيد، ونهايتها كيوم مفعم بالمرارة.","8:11":"ستأتي أيام أجعل فيها المجاعة تنتشر في الأرض، لا مجاعة إلى الخبز، ولا ظمأ إلى الماء إنما لسماع كلام الرب، يقول السيد الرب.","8:12":"فيهيمون من بحر إلى بحر، ومن الشمال إلى الشرق. يذهبون ويجيئون بحثا عن كلمة الرب ولا يحظون بها.","8:13":"في ذلك اليوم يغشى على العذارى الجميلات والفتيان من فرط الظمإ.","8:14":"أما الذين يقسمون بأوثان السامرة قائلين: حي إلهك يادان، وحي معبود بئر سبع. هؤلاء يسقطون ولا ينهضون أبدا ثانية».","9:1":"ورأيت السيد واقفا إلى جوار المذبح قائلا: «اضرب تيجان الأعمدة حتى تهتز العتبات، وحطمها على رؤوس جميع الشعب. ومن ينجو منهم أهلكه بالسيف، فلا يهرب منهم أحد ولا يفلت منهم ناج.","9:2":"وإن نقبوا لأنفسهم ملجأ في أعماق الهاوية، فإن يدي تطولهم هناك، وإن ارتقوا إلى السماوات فمن هناك أنزلهم.","9:3":"وإن اختبأوا في أعالي الكرمل فهناك أبحث عنهم وأعتقلهم. وإن تواروا عني في أعماق البحر فإني آمر هناك الحية فتلدغهم.","9:4":"وإن سيقوا إلى السبي أمام أعدائهم ألاحقهم بالسيف لأفنيهم، وأتعقبهم لأبتليهم بالشر لا بالخير».","9:5":"إن الرب الإله القدير هو الذي يلمس الأرض فتذوب، وينوح كل المقيمين فيها، ويرتفع كل ما فيها وينخفض كنهر نيل مصر.","9:6":"هو الذي يبني مخادعه العليا في السماوات ويؤسس قبته على الأرض، الذي يدعو مياه البحر ويسكبها على وجه الثرى، الرب اسمه.","9:7":"ألستم لي يابني إسرائيل مثل الكوشيين يقول الرب؟ ألم أخرج إسرائيل من ديار مصر والفلسطينيين من كفتور والأراميين من قير.","9:8":"ها إن عيني الرب مسلطتان على المملكة الخاطئة لأمحوها عن وجه الأرض، إلا أني لن أستأصل بيت يعقوب قاطبة يقول الرب.","9:9":"أغربل بيت إسرائيل بين جميع الأمم كما تغربل الحنطة في غربال، فلا تسقط حبة على الأرض.","9:10":"ويموت جميع خطاة شعبي بالسيف ممن يقولون: لن يدركنا الشر أو يلقانا.","9:11":"في ذلك اليوم أقيم مسكن داود الذي تهاوى، وأسد ثغراته وأعمر خرائبه وأعيد بناءه كالعهد به في الأيام الغابرة.","9:12":"لكي يرث إسرائيل ما تبقى من أدوم وجميع الأمم التي دعي اسمي عليها، يقول الرب صانع هذه الأمور.","9:13":"ها أيام تأتي يقول الرب، يدرك فيها الحارث الحاصد، ودائس العنب باذر الحب، وتسيل الخمور الطيبة من كروم الجبال وتفيض بها التلال كلها.","9:14":"وأرد سبي شعبي إسرائيل فيعيدون بناء المدن الخربة ويسكنونها، ويزرعون كروما ويشربون من خمرها، ويغرسون جنات ويأكلون من ثمارها.","9:15":"وأغرس شعبي في أرضهم فلا يستأصلون ثانية أبدا من الأرض التي وهبتها لهم، يقول الرب إلهكم."},"Oba":{"1:1":"هذه نبوءة عوبديا: هذا ما يقوله السيد الرب بشأن أدوم: قد بلغنا خبر من عند الرب أنه أرسل رسولا إلى الأمم قائلا: «تأهبوا، ولننهض لمحاربة أدوم».","1:2":"ها أنا أجعلك صغيرا بين الأمم وأشدها احتقارا.","1:3":"قد غرتك كبرياء قلبك أيها المقيم في شقوق الصخور، ومساكنه في القمم، القائل في قلبه: من يهوي بي إلى الأرض؟","1:4":"ولكن إن كنت تحلق كالنسر ومنازلك مبنية بين الكواكب، فإني سأهوي بك إلى الحضيض يقول الرب.","1:5":"إن اقتحم اللصوص بيتك، وهاجمك الناهبون ليلا، ألا يسرقون ما يحتاجون إليه فقط؟ وإن أقبل إليك قاطفو العنب، ألا يبقون خصاصة؟ ولكن يالدمارك!","1:6":"إذ كيف تم تفتيش عيسو ونقبت مخابيء كنوزه؟","1:7":"جميع حلفائك طردوك إلى التخوم. خدعك مسالموك وأوقعوا بك الهزيمة، والذين أكلوا من خبزك كادوا لك وأنت لم تفهم.","1:8":"ألا أستأصل في ذلك اليوم حكماء أدوم، يقول الرب، وأزيل الفهم من جبل عيسو؟","1:9":"فيرتعب أبطالك ياتيمان حتى ينقرض قتلا كل رجل من جبل عيسو.","1:10":"فمن أجل ما أنزلت بأخيك يعقوب من ظلم، يغشاك العار وتنقرض إلى الأبد.","1:11":"ففي ذلك اليوم الذي وقفت فيه بعيدا، يوم غنم الغرباء كنوزه، واقتحم الأجانب أبوابه وألقوا القرعة على أورشليم، كنت أنت أيضا كواحد منهم.","1:12":"ما كان يجب أن تشمت بيوم مصير أخيك، في يوم فاجعته، وما كان يجب أن تبتهج في يوم دمار شعب يهوذا أو تتباهى في يوم الضيق.","1:13":"وما كان يجب أن تقتحم أبواب شعبي في يوم كارثته، أو تشمت لمصيبته في يوم نكبته، أو تنهب ثروته في يوم بليته،","1:14":"أو تقف عند مفترق الطرق لتقضي على الناجين من قومه وتسلم الباقين الأحياء منهم في يوم الضيق.","1:15":"لأن يوم الرب قريب آت على كل الأمم، وكما فعلت، لابد أن يفعل بك أيضا، فيرتد عملك على رأسك.","1:16":"فإنه كما شربت على جبل قدسي فإن جميع الأمم تشرب في كل حين. يشربون ويجرعون ويتلاشون كمن لم يكونوا.","1:17":"أما جبل صهيون فيصبح ملاذ النجاة، ويكون قدسا، ويرث بيت يعقوب نصيبه.","1:18":"ويصير بيت يعقوب نارا، وبيت يوسف لهيبا، وبيت عيسو قشا فيوقدونهم ويلتهمونهم، ولا يفلت من بيت عيسو أحد، يقول الرب.","1:19":"ويرث أهل النقب جبل عيسو، وسكان السهول أرض الفلسطينيين، ويملكون أرض أفرايم وبلاد السامرة، ويرث بنيامين جلعاد.","1:20":"ويستولي جيش مسبيي بني إسرائيل على أرض الكنعانيين حتى صرفة، ويحتل مسبيو أورشليم في صفارد مدن جنوب يهوذا.","1:21":"ويصعد المنقذون إلى جبل صهيون ليحكموا جبل عيسو، ويصبح الملك للرب."},"Hos":{"1:1":"هذه هي كلمة الرب التي أوحى بها إلى هوشع بن بئيري في أثناء حكم كل من عزيا ويوثام وآحاز وحزقيا ملوك يهوذا، وفي أيام يربعام بن يوآش ملك إسرائيل.","1:2":"وأول ما خاطب الرب به هوشع أنه قال له: «اذهب وتزوج من عاهرة، تنجب لك أبناء زنى، لأن الأرض قد زنت إذ تركت الرب».","1:3":"فمضى هوشع وتزوج جومر بنت دبلايم، فحملت وأنجبت له ابنا.","1:4":"فقال الرب له: «ادع اسمه يزرعيل، لأني موشك أن أقضي على بيت ياهو انتقاما لدم يزرعيل، وأبيد مملكة بيت إسرائيل.","1:5":"في ذلك اليوم أحطم قوس إسرائيل في وادي يزرعيل».","1:6":"ثم حملت ثانية فأنجبت ابنة، فقال له الرب: «سمها لورحامة (ومعناه: لا رحمة) لأني لا أعود أرحم بيت إسرائيل ولن أصفح عنهم.","1:7":"ولكني أرحم بيت يهوذا وأخلصهم بقوتي أنا الرب إلههم. لن أنقذهم بقوس أو بسيف، ولا بحرب ولا بخيل أو فرسان».","1:8":"وبعد أن فطمت «لورحامة» حملت وأنجبت ابنا.","1:9":"وقال الرب: «سمه لوعمي (ومعناه: ليس شعبي) لأنكم لستم شعبي وأنا لست إلهكم.","1:10":"ومع ذلك فإن عدد بني إسرائيل يكون كرمل البحر الذي لا يكال ولا يحصى. وفي الموضع الذي قيل لهم فيه: أنتم لستم شعبي، يقال لهم: أنتم أبناء الله الحي.","1:11":"ويجتمع أبناء يهوذا وأبناء إسرائيل معا وينصبون عليهم قائدا واحدا، ويرجعون من أرض السبي، لأن يوم يزرعيل عظيم».","2:1":"«قولوا لإخوتكم عمي (شعبي) ولأخواتكم رحامة (المرحومة).","2:2":"حاكموا أمكم، لأنها ليست زوجتي، وأنا لست رجلها، حتى تخلع زناها عن وجهها وفجورها من بين ثدييها.","2:3":"لئلا أعريها وأردها كما كانت يوم مولدها، وأجعلها كالقفر أو كأرض جرداء، وأميتها ظمأ.","2:4":"ولا أرحم أبناءها لأنهم أولاد زنى.","2:5":"فأمهم قد زنت، والتي حملتهم ارتكبت الموبقات، لأنها قالت: أسعى وراء عشاقي الذين يقدمون لي خبزي ومائي وصوفي وكتاني وزيتي ومشروباتي.","2:6":"لذلك أسيج طريقها بالشوك وأحوطها بسور حتى لا تجد لها مسلكا.","2:7":"فتسعى وراء عشاقها ولكنها لا تدركهم، وتلتمسهم فلا تجدهم، ثم تقول، لأنطلقن وأرجعن إلى زوجي الأول، فقد كنت معه في حال خير مما أنا عليه الآن.","2:8":"إنها لم تعرف أنني أنا الذي أعطيتها القمح والخبز والزيت، وأغدقت عليها الفضة والذهب التي قدموها للبعل.","2:9":"لذلك أسترد حنطتي في حينها، وخمري في أوانه، وأنتزع صوفي وكتاني اللذين تستر بهما عريها.","2:10":"وأكشف عورتها أمام عشاقها، ولا ينقذها أحد من يدي.","2:11":"وأبطل كل أفراحها وأعيادها واحتفالات رؤوس شهورها وسبوتها وجميع مواسمها.","2:12":"وأتلف كرومها وتينها التي قالت عنها: هي أجرتي التي قبضتها من عشاقي، فأحولها إلى غابة يلتهمها وحش الصحراء.","2:13":"وأعاقبها على أيام احتفالاتها بآلهة البعل، حين أحرقت لها البخور، وتزينت بخواتمها وحليها وضلت وراء عشاقها ونسيتني، يقول الرب.","2:14":"لهذا، ها أنا أتملقها وآخذها إلى الصحراء وأخاطبها بحنان،","2:15":"وأرد لها كرومها هناك، وأجعل من وادي عخور (أي وادي الإزعاج) بابا للرجاء، فتتجاوب معي كالعهد بها في أيام صباها، حين خرجت من ديار مصر.","2:16":"في ذلك اليوم، يقول الرب، تدعينني: زوجي، ولا تدعينني أبدا: بعلي.","2:17":"لأني أنزع أسماء البعل من فمك، ولا يرد ذكرها بأسمائها من بعد.","2:18":"وأبرم في ذلك اليوم من أجلك عهدا مع وحش البرية وطيور السماء وزواحف الأرض وأحطم القوس والسيف، وأبطل الحرب من الأرض، وأجعلك تنامين مطمئنة","2:19":"وأخطبك لنفسي إلى الأبد، أخطبك بالعدل والحق والإحسان والمراحم.","2:20":"أخطبك لنفسي بالأمانة فتعرفين الرب.","2:21":"في ذلك اليوم أستجيب لشعبي إسرائيل، وأغمر أرضهم بالمطر، فتثمر.","2:22":"فتنبت الأرض القمح والعنب والزيت، وكلها تستجيب ليزرعيل (أي: الله يزرع)","2:23":"وأزرع شعبي في الأرض لنفسي، وأرحم لورحامة (أي: لا رحمة)، وأقول: للوعمي (أي: ليس شعبي) أنت شعبي، فيقول: أنت إلهي».","3:1":"ثم قال لي الرب: «اذهب ثانية وأحبب امرأة عشيقة آخر، زانية، أحببها كمحبة الرب لشعبه إسرائيل، على الرغم من ضلالهم وراء آلهة أخرى، وولعهم بتقديم قرابين الزبيب لهم.","3:2":"فاشتريتها بخمسة عشر شاقلا من الفضة (نحو مئة وثمانين جراما)، وبحومر ونصف حومر من الشعير (نحو ثلاث مئة وستين لترا)،","3:3":"وقلت لها: تمكثين ملكا خالصا لي أياما كثيرة لا تزنين ولا تكونين لرجل آخر وأكون أنا كذلك لك.","3:4":"لأن أبناء إسرائيل يمكثون أمدا طويلا من غير ملك أو أمير، ومن غير ذبيحة ولا تماثيل ولا أفود ولا ترافيم.","3:5":"ثم يرجع أبناء إسرائيل ويطلبون الرب إلههم، وداود ملكهم (أي المسيح)، ويلتمسون برهبة الرب وجوده في آخر الأيام».","4:1":"اسمعوا كلمة الرب يابني إسرائيل، لأن للرب دعوى على أهل الأرض إذ خلت الأرض من الأمانة والإحسان ومعرفة الله.","4:2":"وتفشت فيها اللعنة والكذب والقتل والسرقة والفسق. قد تخطوا كل حد، وسفك الدم يعقبه سفك دم.","4:3":"لذلك تنوح الأرض، ويذوي كل مقيم فيها، فضلاَ عن وحش البر وطير السماء، بل سمك البحر يستأصل أيضا.","4:4":"ولكن لا يخاصم أحد أحدا، ولا يتهمه لأن دعواي هي ضدكم أيها الكهنة.","4:5":"إنك تتعثر في النهار، ويكبو النبي معك في الليل، وأنا أدمر أمكم إسرائيل.","4:6":"قد هلك شعبي لافتقاره إلى المعرفة، ولأنك رفضت المعرفة فأنا أرفضك فلا تكون لي كاهنا، أنت تجاهلت شريعتي لذلك أنا أنسى أبناءك.","4:7":"وبقدر ما تكاثروا تفاقمت خطيئتهم، لذلك أحول مجدهم إلى عار.","4:8":"يأكلون من ذبائح خطيئة شعبي ويفرحون لتماديهم في الإثم ليكثر نصيبهم منها.","4:9":"فيصبح الشعب كالكاهن. وأعاقبهم جميعا على سوء تصرفاتهم وأجزيهم على أعمالهم.","4:10":"فيأكلون ولا يشبعون، ويزنون ولا يتكاثرون، لأنهم نبذوا الرب واستسلموا إلى العهارة.","4:11":"قد سلبت الخمرة المعتقة والجديدة عقول شعبي","4:12":"فيطلبون مشورة قطعة خشب ويسألون عصا! لأن روح زنى قد أضلهم فنبذوا إلههم وزنوا وراء آخر.","4:13":"ذبحوا على قمم الجبال وأصعدوا تقدماتهم على التلال وتحت شجر البلوط واللبنى والبطم لطيب ظلها. لذلك تزني بناتكم وتفسق كناتكم.","4:14":"ولكني لن أعاقب بناتكم حين يزنين، ولا كناتكم حين يفسقن لأن الرجال أنفسهم قد تورطوا مع الزانيات، وذبحوا محرمات مع بغايا المعابد الوثنية، والشعب غير المتعقل يلحق به الدمار.","4:15":"فإن كنت ياشعب إسرائيل زانيا، فلا تجعل يهوذا يأثم أو يذهب إلى الجلجال أو إلى بيت آون ولا يحلف قائلا: حي هو الرب.","4:16":"إن إسرائيل شعب عنيد كعجلة جامحة، فكيف يرعاهم الرب كحمل في مرج رحب؟","4:17":"إن أفرايم مكبل بعبادة الأصنام، فاتركوه وحيدا.","4:18":"وحالما ينضب خمرهم ينغمسون في فسادهم، مفضلين العار على الشرف.","4:19":"قد صرتهم الريح في أجنحتها، وأنزلت بهم ذبائحهم الوثنية العار.","5:1":"اسمعوا هذا أيها الكهنة وأنصتوا ياشعب إسرائيل، وأصغوا ياأهل بيت الملك، لأن القضاء حال بكم إذ كنتم فخا في المصفاة وشبكة منصوبة على جبل تابور.","5:2":"لقد حفرتم حفرة عميقة في شطيم، لكني أقوم بتأديبهم جميعا.","5:3":"إني أعرف إسرائيل ولا يخفى عني منه خافية، فأنت ياإسرائيل قد زنيت الآن وتنجست.","5:4":"إن أعمال شرهم تحول دون رجوعهم إلى إلههم، لأن روح الزنى (أي خيانة الرب) كامنة فيهم، وهم لا يعرفون الرب.","5:5":"ها صلف إسرائيل يشهد عليه في وجهه، وإسرائيل وأفرايم يكبوان بإثمهما، ويتعثر معهما يهوذا أيضا.","5:6":"وحين ينطلقون بمواشيهم ليلتمسوا الرب لا يجدونه، إذ قد انصرف عنهم.","5:7":"لقد خانوا الرب لأنهم أنجبوا أبناء غرباء عنه، لذلك فإن مواسم أوائل الشهر الجديد تلتهمهم مع حقولهم.","5:8":"انفخوا في أبواق الحرب في جبعة وفي الرامة، وأطلقوا صيحة القتال في بيت آون: تقدم يابنيامين.","5:9":"أرض أفرايم ستصبح خرابا في يوم القضاء، وبين أسباط إسرائيل أظهرت ما هو يقين.","5:10":"قد صار رؤساء يهوذا متعدين كالذين ينقلون تخوم الأرض ليسلبوا سواهم. لهذا سأصب عليهم سخطي كالماء.","5:11":"لقد لحق الضيق بإسرائيل، وسحقه القضاء لأنه وطد العزم على الغواية وراء الأوثان.","5:12":"لهذا أكون كالعث لإسرائيل، وكالسوس الناخر لشعب يهوذا.","5:13":"عندما تبين إسرائيل داءه، ويهوذا جراحه، لجأ إسرائيل إلى أشور يلتمس معونة الملك العظيم، إلا أنه أخفق في علاجه أو في مداواة جراحه.","5:14":"فإني سأكون كالأسد المفترس لإسرائيل، وكالشبل لأبناء يهوذا. أفترس وأمضي. أخطف ولا من منقذ.","5:15":"ثم أرجع إلى موضعي إلى أن يعترفوا بإثمهم ويطلبوا وجهي، وفي ضيقهم يلتمسونني (قائلين):","6:1":"«تعالوا نرجع إلى الرب. هو الذي مزقنا إربا إربا، وهو وحده يبرئنا. هو الذي ضربنا، وهو وحده الذي يجبرنا.","6:2":"بعد يومين يحيينا، وفي اليوم الثالث يقيمنا، لنحيا أمامه.","6:3":"لنعرف، بل لنجد حتى نعرف الرب، فمجيئه يقين كالفجر، يقبل إلينا كإقبال المطر وكغيوث الربيع التي تروي الأرض».","6:4":"ماذا أصنع بك ياإسرائيل، وأي شيء أفعله بك يايهوذا؟ إن حبكم يتلاشى كسحابة الصبح ويتبخر كالندى.","6:5":"لذلك مزقتكم بإنذارات الأنبياء، وقضيت عليكم بأحكامي، فقضائي عليكم يشع كالنور.","6:6":"إني أطلب رحمة لا ذبيحة، ومعرفتي أكثر من المحرقات.","6:7":"ولكنكم مثل آدم، نقضتم عهدي وغدرتم بي.","6:8":"جلعاد، مدينة فاعلي الشر، داست عليها أقدام ملطخة بالدم.","6:9":"وكما يكمن اللصوص، كمن الكهنة على طريق شكيم ليرتكبوا جرائم القتل. حقا إنهم يقترفون الفواحش.","6:10":"لقد شهدت في وسط شعب إسرائيل فظائع، فقد زنى هناك أفرايم وتنجس إسرائيل.","6:11":"أما أنت يايهوذا فقد تحدد موعد عقابك عندما أرد سبي شعبي.","7:1":"حين كنت أشفي إسرائيل، تكشفت خطيئة أفرايم، واستعلنت آثام السامرة، فقد مارسوا النفاق واقتحم اللصوص البيوت، وسلب قطاع الطرق في الخارج.","7:2":"ولكنهم لا يدركون أني أتذكر سوء أعمالهم. ها هي أعمالهم تحدق بهم، وهي دائما ماثلة أمامي.","7:3":"بشرهم يبهجون الملك، وبخيانتهم الرؤساء.","7:4":"كلهم فاسقون ملتهبون مثل فرن متقد يكف الخباز عن إشعاله ما بين عجن الدقيق إلى أوان اختماره.","7:5":"في يوم احتفال ملكنا انتشى الرؤساء من سورة الخمر، وانضم هو إلى المتبذلين.","7:6":"فقلوبهم تشتعل بالمكائد كالأتون. يخمد غضبهم في الليل، ويتوهج كنار ملتهبة عند الصباح.","7:7":"كلهم متأججون كأتون مشتعل. يفترسون حكامهم. هلك جميع ملوكهم، ولم يوجد بينهم من يطلبني.","7:8":"قد اختلط أفرايم بالشعوب، صار كرغيف لم ينضج لأنه لم يقلب.","7:9":"استنزف الغرباء قوته وهو لا يدري، وخط الشيب شعر رأسه وهو لا يعلم.","7:10":"يشهد غرور إسرائيل عليه ولم يرجع إلى الرب إلهه، ولا التمسه.","7:11":"إن أفرايم مثل حمامة غبية حمقاء، تستنجد بمصر تارة وتستغيث بأشور تارة أخرى.","7:12":"إذا ذهبوا أبسط عليهم شبكتي وأطرحهم كطيور السماء، وأعاقبهم بمقتضى شرورهم.","7:13":"ويل لهم لأنهم شردوا عني! تبا لهم لأنهم تمردوا علي! لشد ما أتوق لافتدائهم، ولكنهم نطقوا علي كذبا.","7:14":"لم يستغيثوا بي من كل قلوبهم، بل أعولوا في مضاجعهم، وتألبوا حول أصنامهم يطلبون قمحا وخمرا، وارتدوا عني.","7:15":"دربتهم على القتال وشددتهم، ومع ذلك ارتكبوا الشر ضدي.","7:16":"لا يرجعون إلي، فهم كقوس ملتوية مخطئة. يهلك رؤساؤهم بالسيف لفرط سلاطة ألسنتهم، ويصبح مصيرهم مثار سخرية المصريين.","8:1":"ضع البوق بين شفتيك لتنفخ فيه، لأن نسرا ينقض على بيت الرب، فإن الشعب قد نقضوا عهدي وتعدوا على شريعتي.","8:2":"يستغيثون بي قائلين: «ياإلهنا، إننا نعرفك، فنحن إسرائيل شعبك».","8:3":"غير أن إسرائيل قد مقت الخير، لهذا يطارده عدو.","8:4":"قد نصبوا لهم ملوكا ولكن من غير رضاي، وأقاموا رؤساء من غير موافقتي، وصنعوا بذهبهم وفضتهم أصناما تؤول إلى هلاكهم.","8:5":"لشد ما أزدري عجلك أيتها السامرة، وها غضبي قد احتدم عليهم فإلى متى يظلون عاجزين عن النقاوة؟","8:6":"إنه صنعة عامل إسرائيلي وليس إلها، ولابد أن يصير عجل السامرة حطاما.","8:7":"إنهم يزرعون الريح، وسيحصدون الزوبعة. زرع عقيم لا يصنع دقيقا، وإن صنع يلتهمه الغرباء.","8:8":"قد ابتلع إسرائيل، وأصبح بين الشعوب كإناء لا جدوى منه،","8:9":"لأن أبناء إسرائيل لجأوا إلى أشور كحمار وحشي متوحد شريد، واستأجر أفرايم محبين","8:10":"وإن كانوا يستأجرون حلفاء من بين الأمم، فإني أجمعهم الآن، فيتحررون إلى حين من نير الملك والرؤساء.","8:11":"أكثر أفرايم من تشييد المذابح ليصعد عليها ذبائح الخطيئة، فأصبحت هذه مذابح لارتكاب الخطيئة.","8:12":"قد كتبت لهم بكثرة شريعتي لكنهم حسبوها غريبة عنهم.","8:13":"يذبحون الذبائح المقربة إلي ليأكلوا لحومها، لا ليقدموها إلي. ولكني لا أسر بها. والآن أذكر إثمهم وأعاقبهم على خطاياهم وإلى مصر يرجعون.","8:14":"لأن إسرائيل قد نسي خالقه، وشيد قصورا، وأكثر يهوذا من بناء المدن المحصنة، لهذا سأرسل نارا على هذه المدن فتلتهم حصونه.","9:1":"لا تبتهج ياإسرائيل ولا تطرب كبقية الشعوب، لأنك قد خنت إلهك وهجرته، وأحببت أجرة الزنى على كل بيادر الحنطة.","9:2":"لهذا فإن البيدر والمعصرة لا يطعمانكم، والخمرة الجديدة لا تلبي حاجتكم.","9:3":"لن تظلوا مقيمين في أرض الرب بل يرجع أفرايم إلى ديار مصر، ويأكلوا لحما نجسا في أشور.","9:4":"لا تسكبوا للرب خمرا ولن تسره ذبائحكم، بل تكون لكم كخبز النائحين. كل من يأكل منه يتنجس، إذ يكون خبزكم لسد جوعكم فقط، ولا يدخل أبدا إلى بيت الرب.","9:5":"ماذا تفعلون في يوم الاحتفال وفي يوم عيد الرب؟","9:6":"حتى لو سلمتم من الخراب فإن مصر تجمعكم ومنف تفنيكم وتدفنكم. يرث القريص نفائس فضتكم، وينمو العوسج في منازلكم.","9:7":"لقد أزفت أيام العقاب وحان يوم الحساب، فليعلم إسرائيل هذا. لكثرة إثمك وفرط حقدك حسب النبي أحمق، ورجل الروح مجنونا.","9:8":"إن النبي هو رقيب أفرايم شعب إلهي، غير أن فخ صياد قد نصب في كل طرقه، وطغى الحقد على بيت إلهي.","9:9":"قد أوغلوا في الفساد كما حدث في أيام جبعة، لهذا سيذكر إثمهم ويعاقبهم على خطاياهم.","9:10":"وجدت إسرائيل كعنب في البرية، ورأيت آباءهم كباكورة ثمر شجرة التين في أول موسمها. ولكنهم التصقوا ببعل فغور ونذروا أنفسهم للصنم المخزي، فأصبحوا رجسا نظير الشيء الذي أحبوه.","9:11":"إن مجد أفرايم يتوارى كالطائر المحلق إذ يموت أولادكم في أثناء الولادة أو في الأرحام، أو لا يحبل بهم أبدا.","9:12":"وحتى إن أنجبوا أولادا فإني أحرمكم منهم حتى لا يبقى منهم أحد. ويل لكم حين أنصرف عنكم.","9:13":"مصير أبناء أفرايم، كما أرى، هو الوقوع في قبضة الصياد، لأن أفرايم، يقتاد أبناءه للذبح.","9:14":"أعطهم يارب: ولكن ماذا تعطيهم؟ أعطهم نساء ذوات أرحام مسقطة، وأثداء جافة.","9:15":"في الجلجال ارتكبوا جميع شرورهم، فكرهتهم هناك. لسوء أعمالهم أطردهم من بيتي ولا أعود أحبهم، فكل رؤسائهم متمردون.","9:16":"أفرايم مصاب. قد جفت أصولهم فلن يثمروا، وإن أنجبوا فإني أهلك أبناءهم الأعزاء.","9:17":"ينبذهم إلهي لأنهم أبوا الاستماع إليه، لهذا يتشردون بين الأمم.","10:1":"إن إسرائيل مثل كرمة مخصبة يغل ثمرا لنفسه. كلما تكاثر محصول ثمره، زاد في بناء المذابح، وبمقدار ما تجود أرضه، يتقن بناء أنصابه.","10:2":"قلوبهم كلها خداع، وعليهم أن يتحملوا عقاب ذنوبهم. إن الرب يهدم مذابحهم ويدمر أوثانهم.","10:3":"يقولون الآن: «ليس لنا ملك لأننا لم نخش الله، وماذا في وسع الملك أن يفعل لنا؟»","10:4":"ينطقون بكلام لغو ويبرمون عهودا بأقسام باطلة، فيحل بهم القضاء كأعشاب سامة نبتت في أرض محروثة.","10:5":"يخشى أهل السامرة على عجل بيت آون، لأن شعبه يعولون عليه، وكذلك كهنته الخونة الذين ابتهجوا ببهائه الذي سلب منه.","10:6":"سيحمل هذا العجل إلى أشور هدية للملك العظيم، فيخزى أفرايم ويعتري إسرائيل الخجل من اتكاله عليه.","10:7":"يهلك ملك السامرة كقشة عائمة على وجه المياه.","10:8":"وتدمر أماكن العبادة على مشارف آون التي أضحت خطيئة إسرائيل، وينمو الشوك والحسك على مذابحهم، فيقولون للجبال: غطينا، وللتلال: اسقطي علينا.","10:9":"لقد أخطأت ياإسرائيل منذ أيام جبعة ولم تكف عن ارتكاب الإثم، ألم تدركهم الحرب في جبعة؟","10:10":"فأعاقبهم عندما أشاء، إذ تتألب عليهم أمم وتصفدهم بالأغلال من جراء إثمهم المتكاثر.","10:11":"كان أفرايم كعجلة مروضة تحب أن تدوس الحنطة، ولكني سأضع نيرا على عنقها الجميل الذي حافظت على سلامته، وأدفعها إلى العمل الشاق، ويحرث يهوذا ويمهد إسرائيل الأرض.","10:12":"ازرعوا لأنفسكم بذار البر، فتحصدوا بمقتضاه ثمار الرحمة، احرثوا لكم حرثا لأن هذا أوان التماس الرب، حتى يأتي ويمطر عليكم غيوث صلاحه.","10:13":"لكنكم زرعتم الشر فحصدتم الإثم، وأكلتم ثمار الكذب لأنكم اتكلتم على مركباتكم وعلى كثرة محاربيكم الجبابرة.","10:14":"لذلك يدوي زئير المعركة بين شعبك، وتدمر جميع حصونك كما دمر شلمان بيت أربئيل في يوم القتال إذ أصبحت الأم مع أولادها حطاما.","10:15":"هذا ما يجري عليكم يابيت إسرائيل عقابا لكم على إثمكم العظيم، ويتم القضاء على ملك إسرائيل عند انبلاج الفجر.","11:1":"عندما كان إسرائيل صغيرا أحببته، ومن مصر دعوت ابني.","11:2":"لكن كلما دعاهم الأنبياء لعبادتي أعرضوا عني، ذابحين قرابين للبعل، ومصعدين بخورا للأوثان.","11:3":"أنا الذي دربت إسرائيل على المشي، وحملته على ذراعي، ولكنهم لم يدركوا أني أنا الذي أبرأتهم.","11:4":"قدتهم بحبال اللطف البشرية وبربط المحبة، فكنت لهم كمن يرفع النير عن أعناقهم وينحني بنفسه ليطعمهم.","11:5":"ولكنهم رفضوا أن يتحولوا إلي تائبين، لذلك لن يرجعوا إلى مصر بل يصبح أشور ملكا عليهم.","11:6":"يهجم السيف على مدنهم، ويلتهم أرتاج بواباتها، ويهلكهم لمشوراتهم الخاطئة.","11:7":"قد وطد شعبي العزم على الارتداد عني، لهذا ولو استغاثوا بالعلي، فإنهم لا يجدون من يرفع النير عنهم.","11:8":"كيف أتخلى عنك ياأفرايم؟ وكيف أسلمك إلى العدو ياإسرائيل؟ كيف أعاملك كما عاملت أدمة؟ وكيف أجري عليك ما أجريته على صبوئيم؟ إن قلبي يتلوى أسى في داخلي وتضرم في مراحمي.","11:9":"لن أنفذ فيهم قضاء احتدام غضبي، ولن أدمر أفرايم ثانية، لأني الله لا إنسان، أنا القدوس الذي في وسطك لا أقبل عليكم بسخط.","11:10":"يسيرون ورائي أنا الرب، فأزأر كالأسد، وعندئذ يسرع أبنائي قادمين من الغرب.","11:11":"ويهرعون كالطيور من مصر، وكحمام من أرض أشور، وأردهم إلى بيوتهم.","11:12":"لقد حاصرني أفرايم بالكذب وبيت إسرائيل بالنفاق، وما زال يهوذا شاردا عني أنا الله القدوس الأمين.","12:1":"يرعى أفرايم الريح، ويطارد الريح الشرقية طوال اليوم، ويرتكب الأكاذيب والجور بكثرة، ويبرم عهدا مع أشور، ويبعث بزيت الزيتون إلى مصر.","12:2":"للرب دعوى على يهوذا، وسيعاقب إسرائيل بمقتضى طرقه ويجازيه بموجب أعماله.","12:3":"(لكم طمع يعقوب في بركة الرب)، فقبض وهو ما برح في الرحم على عقب أخيه، وفي رجولته جاهد مع الله.","12:4":"تصارع مع الملاك وغلب. بكى والتمس رضاه وبركته، التقاه الله في بيت إيل فخاطبه هناك.","12:5":"هو الله القدير ويهوه اسمه.","12:6":"أما أنتم فارجعوا إلى إلهكم تائبين. تمسكوا برحمته وعدله، وداوموا على الا تكال عليه.","12:7":"إن أفرايم مثل التاجر الكنعاني يحمل بيده ميزانا مغشوشا لأنه يحب الجور.","12:8":"ويقول: «قد أصبحت غنيا، وضمنت لنفسي ثروة، ولا يمكن لأحد إن يجد في كل ما اكتسبته من غنى مالا حراما أثيما».","12:9":"ولكني أنا الرب إلهك منذ أن كنت في ديار مصر. سأجعلك تقيم في خيام ثانية كما كنت في أيام أعيادك في الصحراء.","12:10":"قد خاطبت الأنبياء، وأكثرت لهم الرؤى، ونطقت على ألسنتهم بأمثال.","12:11":"أفي جلعاد إثم؟ حتما قد انتهوا إلى بطل. إن ذبحوا في الجلجال ثيرانا لوثن، فإن مذابحهم تصير كركام حجارة في حقل محروث.","12:12":"قد لجأ يعقوب إلى أرض أرام، حيث خدم كراع ليحظى بزوجة.","12:13":"وبقيادة نبي أخرج الرب إسرائيل من ديار مصر، وبنبي حافظ عليه.","12:14":"غير أن أفرايم أثار غضب الرب أشد إثارة لهذا فإنه سيترك لطخات إثم دمه عليه ويرد عليه تعييره.","13:1":"عندما تكلم أفرايم اعترى الرعب الأمم، وعظم شأنه في إسرائيل، ولكن حين عبد البعل وأثم مات.","13:2":"وها هم يكثرون الآن معاصيهم، ويصوغون ببراعة لأنفسهم تماثيل وأصناما من فضتهم، كلها صنعة عمال حاذقين قائلين: «قبلوا تماثيل العجول هذه يامقربي الذبائح البشرية».","13:3":"لهذا يتلاشون كضباب الصباح وكالندى الذي يتبخر سريعا، أو كعصافة مذراة من البيدر، أو دخان متسرب من الكوة.","13:4":"أنا هو الرب إلهك منذ أن كنت في ديار مصر، ولست تعرف إلها غيري، ولا منقذ لك سواي.","13:5":"أنا الذي اعتنيت بك في الصحراء الجرداء، في أرض الظمإ","13:6":"ولكن عندما رعوا وشبعوا خامرت قلوبهم الكبرياء، لذلك نسوني.","13:7":"لهذا أكون لهم كأسد، وأكمن كنمر لهم على الطريق.","13:8":"وأنقض عليهم كدبة ثاكل، وأمزق قلوبهم أشلاء وأفترسهم هناك كلبوءة، ووحش البر يقطعهم إربا إربا.","13:9":"هلاكك منك ياإسرائيل لأنك عاديتني. عاديت معينك.","13:10":"أين هو ملكك لينقذك؟ أين هم حكامك المنتشرون في جميع مدنك الذين قلت عنهم: أعطني ملكا ورؤساء؟","13:11":"قد أعطيتك ملكا في إبان غضبي وأخذته في سورة غيظي.","13:12":"إثم أفرايم محفوظ في صرة، وخطيئته مدخرة","13:13":"آلام مخاض امرأة مشرفة على الولادة حلت به، ولكنه ابن جاهل يأبى أن يقترب من فوهة الرحم عند أوان ولادته.","13:14":"هل أفتديهم من قوة الهاوية؟ هل أنجيهم من الموت؟ أين أوبئتك ياموت؟ أين هلاكك ياهاوية؟ قد احتجبت الرحمة عن عيني.","13:15":"وحتى ولو ازدهر كالعشب بين إخوته تهب ريح شرقية، ريح الرب المقبلة من الصحراء فتجفف ينبوعه وتنضب عينه وتنهب مخابيء كنزه من كل شيء نفيس.","13:16":"لابد أن تتحمل السامرة وزر خطيئتها لأنها تمردت على إلهها، فيفنى أهلها بحد السيف، ويتمزق أطفالها أشلاء، وتشق بطون حواملها.","14:1":"ارجع تائبا ياإسرائيل إلى الرب إلهك، لأنك قد تعثرت بخطيئتك.","14:2":"احملوا معكم كلام ابتهال وارجعوا إلى الرب قائلين له: «انزع إثمنا، وتقبلنا بفائق رحمتك، فنزجي إليك حمد شفاهنا كالقرابين.","14:3":"إن أشور لن تخلصنا، ولن نعتمد على خيول مصر لإنقاذنا، ولن نقول للأوثان صنعة أيدينا: «أنتم آلهتنا» لأن فيك وحدك يجد اليتيم رحمة».","14:4":"أنا أبريء ارتدادهم وأحبهم فضلا، لأن غضبي قد تحول عنهم.","14:5":"وأكون كالطل لإسرائيل، فيزهر كالسوسن، وتتأصل جذوره كأرز لبنان.","14:6":"تمتد أغصانه ويصير جماله كشجرة الزيتون وشذاه كأرز لبنان.","14:7":"ويعودون ويقيمون في ظله ويزدهرون كالحنطة، ويزهرون كالكرمة، ويذيع ذكرهم كخمر لبنان.","14:8":"يقول أفرايم تائبا: «مالي وللأصنام!» فيجيب الرب: «قد استمعت وأنا رعيتك بعين الرضى وصرت لك كشجرة سرو خضراء، ومني أمدك بثمرك».","14:9":"من هو حكيم فليسمع هذه الأمور، ومن هو فطن فليفهمها، لأن طرق الله مستقيمة، فيها يسلك الأبرار، أما المنافقون فيعثرون."},"Dan":{"1:1":"في السنة الثالثة من حكم يهوياقيم ملك يهوذا، زحف نبوخذناصر ملك بابل على أورشليم وحاصرها.","1:2":"وأسلم الرب إليه يهوياقيم ملك يهوذا مع بعض آنية هيكل الله، فحملها معه إلى أرض بابل واحتفظ بالآنية في خزانة معبد إلهه.","1:3":"ثم أمر الملك أشفنز رئيس خصيانه أن يحضر من بني إسرائيل، من السلالة الملكية ومن الشرفاء،","1:4":"فتيانا كاملي الخلقة، ذوي جمال، ماهرين في كل صنعة، يتحلون بالمعرفة ومتبحرين في كل علم ممن هم أهل للمثول في قصر الملك، ليتعلموا كتابة الكلدانيين ولغتهم.","1:5":"وعين الملك لهم مخصصات كل يوم بيومه من أطايب مأكولات الملك ومن خمر شرابه، وأوصى أن يقضوا ثلاث سنوات في التثقف يمثلون في نهايتها في حضرة الملك.","1:6":"وكان من جملة المنتخبين من بني يهوذا أربعة هم: دانيآل وحننيا وميشائيل وعزريا،","1:7":"فأطلق عليهم رئيس الخصيان أسماء كلدانية، فدعا دانيآل بلطشاصر، وحننيا شدرخ، وميشائيل ميشخ، وعزريا عبدنغو.","1:8":"أما دانيآل فقد عزم في نفسه أن لا يتنجس بأطايب مأكولات الملك ولا بخمر شرابه، وطلب من رئيس الخصيان أن يعفيه من ذلك.","1:9":"فأعطى الله دانيآل حظوة ورحمة لدى رئيس الخصيان،","1:10":"ولكنه قال لدانيآل: «إنني أخشى سيدي الملك الذي عين مخصصات طعامكم وشرابكم. فاءذا رأى وجوهكم أكثر هزالا من سائر رفاقكم فاءن الملك يأمر بقطع رأسي».","1:11":"فقال دانيآل للمشرف الذي عهد إليه رئيس الخصيان بدانيآل وحننيا وميشائيل وعزريا:","1:12":"«جرب عبيدك عشرة أيام فقط، ولا تعطنا سوى خضروات وماء لنأكل ونشرب،","1:13":"ثم استعرضنا وقارن بين مناظرنا ومناظر سائر رفاقنا الذين يتناولون من طعام الملك، ثم تصرف مع عبيدك بمقتضى ما تشهده».","1:14":"فاستجاب لطلبتهم وجربهم عشرة أيام.","1:15":"وبعد عشرة أيام بدت مظاهرهم أكثر عافية وأوفر سمنا من جميع الفتيان الذين يتناولون من طعام الملك","1:16":"فصار المشرف يستبدل مخصصات طعامهم وخمر شرابهم بالخضروات.","1:17":"ووهب الله أولئك الفتيان الأربعة معرفة وعقلا في كل ضروب الكتابة والعلم. وكان دانيآل فطنا في تفسير جميع الرؤى والأحلام.","1:18":"وحين أزف وقت مثولهم كأمر الملك، أحضرهم رئيس الخصيان أمام نبوخذناصر،","1:19":"فتحدث إليهم الملك، فلم يجد بينهم جميعا من هو مثل دانيآل وحننيا وميشائيل وعزريا، فاختارهم للمثول في حضرته.","1:20":"وحين شرع الملك في مباحثتهم في شؤون العلوم والمعارف وجدهم يفوقون بعشرة أضعاف جميع السحرة والمجوس المقيمين في مملكته كلها.","1:21":"وظل دانيآل هناك إلى السنة الأولى لولاية كورش الملك.","2:1":"وفي السنة الثانية من ملك نبوخذناصر حلم نبوخذناصر أحلاما أزعجته وطردت عنه النوم،","2:2":"فأمر أن يدعى السحرة والمجوس والعرافون والمنجمون ليخبروه بأحلامه فحضروا ومثلوا أمامه.","2:3":"فقال لهم الملك: «إني حلمت حلما انزعجت له نفسي، ولن تطمئن حتى تعرف الحلم ومعناه».","2:4":"فأجابوا بالأرامية: «لتعش إلى الأبد أيها الملك. اسرد على عبيدك الحلم فنفسره لك».","2:5":"فقال لهم الملك: «قد صدر عني الأمر: إن لم تسردوا علي الحلم وتفسروه، تمزقوا إربا إربا، وتصبح بيوتكم أنقاضا.","2:6":"وإن أنبأتموني بالحلم وتفسيره أغدق عليكم هدايا وجوائز، وأسبغ عليكم الإكرام. والآن اسردوا علي الحلم وتفسيره».","2:7":"فأجابوه ثانية: «لينبيء الملك عبيده بالحلم فنكشف عن معناه».","2:8":"فرد الملك: «إني أعلم يقينا أنكم تسعون لاَكتساب الوقت، إذ أدركتم أني أصدرت أمرا مبرما","2:9":"بمعاقبتكم إن لم تنبئوني بالحلم، لأنكم اتفقتم على اختلاق الكذب والضلال لتنطقوا بهما أمامي إلى أن يتحقق معنى الحلم. لذلك أنبئوني أولا بما حلمت فأعلم آنئذ أنكم قادرون على تفسيره».","2:10":"فأجابوا: «ليس على الأرض إنسان في وسعه تلبية أمر الملك ولم يحدث قط أن ملكا عظيما ذا سلطان طلب مثل هذا الأمر من مجوسي أو ساحر أو منجم.","2:11":"ومطلب الملك متعذر لا يمكن لأحد أن ينبيء به الملك سوى الآلهة الذين لا يسكنون مع البشر».","2:12":"عند ذلك استشاط الملك غضبا وحنقا وأمر بإبادة كل حكماء بابل.","2:13":"وهكذا صدر الأمر بقتل كل الحكماء. وجاء من يقبض على دانيآل ورفاقه للقضاء عليهم.","2:14":"فخاطب دانيآل بحكمة وتبصر أريوخ قائد حرس الملك الذي خرج ليقتل حكماء بابل،","2:15":"وقال له: «لماذا أصدر الملك هذا الأمر العنيف؟» فأخبر أريوخ دانيآل بما حدث.","2:16":"فمثل دانيآل أمام الملك وطلب منه أن يمنحه وقتا فيطلعه على تفسير الحلم.","2:17":"ثم مضى دانيآل إلى بيته وأبلغ رفاقه حننيا وميشائيل وعزريا الأمر،","2:18":"ليطلبوا من إله السماوات الرحمة بشأن هذا اللغز لكي لا يهلك دانيآل ورفاقه مع سائر حكماء بابل.","2:19":"عندئذ انكشف السر لدانيآل في رؤيا الليل، فبارك إله السماوات،","2:20":"قائلا: «ليكن اسم الله مباركا من الأزل وإلى الأبد لأن له الحكمة والقدرة.","2:21":"هو يغير الأوقات والفصول. يعزل ملوكا وينصب ملوكا. يهب الحكماء حكمة وذوي الفطنة معرفة.","2:22":"يكشف الأعماق والخفايا ويعلم ما في باطن الظلمة، ولديه يسكن النور.","2:23":"لك ياإله آبائي أحمد وأسبح، لأنك أنعمت علي بالحكمة والقوة، أطلعتني الآن على ما التمسناه منك إذ عرفتنا بأمر الملك».","2:24":"ثم قال دانيآل لأريوخ الذي كلفه الملك بإبادة حكماء بابل: «لا تقتل حكماء بابل. أدخلني للمثول أمام الملك فأكشف له عن تفسير الحلم».","2:25":"فأسرع أريوخ بإحضار دانيآل إلى الملك وقال: «قد عثرت على رجل من سبي يهوذا، وهو ينبيء الملك بتفسير الحلم».","2:26":"فسأل الملك دانيآل المدعو بلطشاصر: «هل تستطيع أنت أن تطلعني على الحلم الذي رأيت وعلى تفسيره؟»","2:27":"فأجاب دانيآل الملك: «لا يستطيع ساحر أو حكيم أو مجوسي أو منجم أن يطلع الملك على السر الذي طلبه.","2:28":"ولكن هناك إله في السماء يعلن الخفايا. وقد عرف الملك نبوخذناصر عما سيحدث في آخر الأيام. أما حلمك والرؤيا التي شهدتها في منامك فهي هذه:","2:29":"أيها الملك، فيما أنت مستلق على مضجعك انتابتك الأفكار عما يحدث في الأيام المقبلة، والذي يكشف الخفايا عرفك بما سيكون.","2:30":"وقد أعلن لي هذا السر، لا لحكمة في أكثر من سائر الأحياء، إنما لكي يطلع الملك على تفسيره وتدرك أفكار قلبك.","2:31":"رأيت أيها الملك وإذا بتمثال عظيم ضخم كثير البهاء واقفا أمامك وكان منظره هائلا.","2:32":"وكان رأس التمثال من ذهب نقي، وصدره وذراعاه من فضة، وبطنه وفخذاه من نحاس،","2:33":"وساقاه من حديد، وقدماه خليط من حديد ومن خزف.","2:34":"وبينما أنت في الرؤيا انقض حجر لم يقطع بيد إنسان، وضرب التمثال على قدميه المصنوعتين من خليط الحديد والخزف فسحقهما،","2:35":"فتحطم الحديد والخزف والنحاس والفضة والذهب معا، وانسحقت وصارت كعصافة البيدر في الصيف، فحملتها الريح حتى لم يبق لها أثر. أما الحجر الذي ضرب التمثال فتحول إلى جبل كبير وملأ الأرض كلها.","2:36":"هذا هو الحلم. أما تفسيره فهذا ما نخبر به الملك:","2:37":"أنت أيها الملك هو ملك الملوك، لأن إله السموات أنعم عليك بمملكة وقدرة وسلطان ومجد،","2:38":"وولاك وسلطك على كل ما يسكنه أبناء البشر ووحوش البر وطيور السماء. فأنت الرأس الذي من ذهب.","2:39":"ثم لا تلبث أن تقوم من بعدك مملكة أخرى أقل شأنا منك، وتليها مملكة ثالثة أخرى ممثلة بالنحاس فتسود على كل الأرض.","2:40":"ثم تعقبها مملكة رابعة صلبة كالحديد، فتحطم وتسحق كل تلك الممالك كالحديد الذي يدق ويسحق كل شيء.","2:41":"وكما رأيت أن القدمين والأصابع هي خليط من خزف وحديد، فإن المملكة تكون منقسمة فيكون فيها من قوة الحديد، بمقدار ما شاهدت فيها من الحديد مختلطا بالخزف.","2:42":"وكما أن أصابع القدمين بعضها من حديد والبعض من خزف، فإن بعض المملكة يكون صلبا والبعض الآخر هشا.","2:43":"وكما رأيت الحديد مختلطا بخزف الطين، فإن هذه المملكة تعقد صلات زواج مع ممالك الناس الأخرى، إنما لا يلتحمون معا، كما أن الحديد لا يختلط بالخزف.","2:44":"وفي عهد هؤلاء الملوك يقيم إله السماوات مملكة لا تنقرض إلى الأبد، ولا يترك ملكها لشعب آخر، وتسحق وتبيد جميع هذه الممالك. أما هي فتخلد إلى الأبد.","2:45":"لأنك رأيت أن الحجر المنقض الذي لم يقطع من الجبل بيدين، قد سحق الحديد والنحاس والخزف والفضة والذهب. إن الله العظيم قد أطلع الملك عما سيحدث في الأيام الآتية؛ فالحلم حقيقة وتفسيره صدق».","2:46":"حينئذ انطرح نبوخذناصر على وجهه وسجد لدانيآل، وأمر أن يقدموا له تقدمة ورائحة رضى","2:47":"وقال الملك لدانيآل: «حقا إن إلهكم هو إله الآلهة ورب الملوك وكاشف الأسرار، لأنك استطعت إعلان هذا السر».","2:48":"ثم عظم الملك دانيآل ووهبه عطايا كثير ة، وسلطه على كل ولاية بابل، وأقامه رئيسا على كل حكماء بابل وولاتها.","2:49":"وطلب دانيآل من الملك أن يعين شدرخ وميشخ وعبدنغو على شؤون ولاية بابل، ففعل. أما دانيآل فأقام في قصر الملك.","3:1":"ثم صنع نبوخذناصر تمثالا من ذهب، ارتفاعه ستون ذراعا (نحو ثلاثين مترا)، وعرضه ست أذرع (نحو ثلاثة أمتار)، ونصبه في سهل دورا في ولاية بابل.","3:2":"واستدعى نبوخذناصر الملك جميع أقطاب الدولة وولاتها وحكامها وقضاتها وأمناء خزائنها ومستشاريها، وسائر كبار موظفي الأقاليم، ليأتوا للاشتراك في تدشين التمثال الذي نصبه.","3:3":"فاجتمع الأقطاب والحكام والقضاة وأمناء الخزائن والمستشارون وسائر عظماء الأقاليم لتدشين التمثال الذي نصبه نبوخذناصر ومثلوا أمامه.","3:4":"وصاح مناد بصوت عال: «أيها الشعوب والأمم من كل لغة ولسان، قد صدر لكم أمر","3:5":"أنكم حين تسمعون أصوات بوق القرن والناي والعود والرباب والقيثارة المثلثة والمزمار وكل أنواع الموسيقى، تنحنون وتسجدون لتمثال الذهب الذي نصبه نبوخذناصر الملك.","3:6":"وكل من لا ينحني ويسجد، يلقى فورا في وسط أتون نار متقدة».","3:7":"لهذا حالما سمعت الشعوب الحاضرة أصوات تلك الالات الموسيقية المختلفة، انحنت وسجدت لتمثال الذهب المنصوب.","3:8":"غير أن بعضا من رجال الكلدانيين تقدموا إلى الملك نبوخذناصر واشتكوا على اليهود","3:9":"قائلين: «لتعش أيها الملك إلى الأبد.","3:10":"لقد أصدرت أيها الملك أمرا أن كل من يسمع أصوات بوق القرن والناي والعود والرباب والقيثارة المثلثة والمزمار، وكل أنواع الموسيقى، ينحني ويسجد لتمثال الذهب.","3:11":"وكل من يأبى يلقى في وسط أتون نار متقدة.","3:12":"وها هنا رجال يهود ممن وليتهم على أعمال إقليم بابل، هم شدرخ وميشخ وعبدنغو لم يأبهوا لك، ولم يعبدوا آلهتك، ولم يسجدوا لتمثال الذهب الذي نصبته».","3:13":"حينئذ أمر نبوخذناصر باحتدام غضب وغيظ أن يؤتى بشدرخ وميشخ وعبدنغو فأحضروهم أمام الملك.","3:14":"وقال لهم نبوخذناصر: «أحقا ياشدرخ وميشخ وعبدنغو أنكم لا تعبدون آلهتي ولا تسجدون لتمثال الذهب الذي نصبته؟","3:15":"والآن إن كنتم مستعدين لدى سماعكم صوت الالات الموسيقية المختلفة أن تنحنوا وتسجدوا للتمثال الذي صنعته، أعفو عنكم. ولكن إن أبيتم السجود، تطرحون في تلك الساعة في وسط أتون النار المتقدة. وأي إله يقدر أن ينقذكم عندئذ من يدي؟»","3:16":"فأجابه شدرخ وميشخ وعبدنغو: «لا داعي لأن نجيبك عن هذا الشأن","3:17":"لأن إلهنا الذي نعبده قادر أن ينجينا من أتون النار المتقدة، وأن ينقذنا من يدك أيها الملك.","3:18":"وحتى إن لم ينقذنا، فاعلم يقينا أيها الملك أننا لا نعبد آلهتك، ولا نسجد لتمثال الذهب الذي نصبته».","3:19":"فاستشاط نبوخذناصر حنقا واكفهر وجهه غضبا على شدرخ وميشخ وعبدنغو، وأمر أن يضرموا الأتون سبعة أضعاف عما كانت عليه العادة.","3:20":"وطلب من بعض رجال جيشه الصناديد أن يوثقوا شدرخ وميشخ وعبدنغو ويطرحوهم في أتون النار المتقدة.","3:21":"حينئذ أوثق الرجال بما عليهم من ثيا ب وسراويل وأقمصة وأردية، وطرحوا في وسط أتون النار المتقدة.","3:22":"وإذ كان أمر الملك صارما والأتون قد أضرم أشد إضرام، فإن لهيب النار أحر ق الرجال الذين حملوا شدرخ وميشخ وعبدنغو، وطرحوهم في النار.","3:23":"فسقط هؤلاء الرجال الثلاثة موثقين وسط أتون النار المتقدة.","3:24":"وما لبثت الحيرة أن اعترت نبوخذناصر، فهب مسرعا وقال لمشيريه: «ألم نطرح ثلاثة رجال موثقين في وسط النار؟» فأجابوا: «صحيح أيها الملك».","3:25":"فقال: «إني أرى أربعة رجال طليقين يتمشون في وسط النار، لم ينلهم أذى، ومنظر الرابع شبيه بابن الآلهة».","3:26":"ثم دنا نبوخذناصر من باب الأتون المتقد بالنار وهتف: «ياشدرخ وميشخ وعبدنغو ياعبيد الله العلي، اخرجوا وتعالوا». فخرج شدرخ وميشخ وعبدنغو من وسط النار.","3:27":"فأحاط الأقطاب والولاة والحكام وعظماء الدولة بهم، فوجدوا أن النار لم تؤذ أجسامهم، ولم تحترق شعرة من رؤوسهم، ولم تشط ثيابهم، ولم تعلق بهم رائحة النار.","3:28":"فقال نبوخذناصر: «تبارك إله شدرخ وميشخ وعبدنغو الذي أرسل ملاكه وأنقذ عبيده الذين اتكلوا عليه وخالفوا أمر الملك وبذلوا أجسادهم كيلا يعبدوا أو يسجدوا لإله غير إلههم.","3:29":"لهذا قد صدر مني أمر أن أي شعب أو أمة أو قوم من أي لسان يذمون إله شدرخ وميشخ وعبدنغو، يمزقون إربا إربا، وتصبح بيوتهم أنقاضا، إذ ليس هناك إله آخر يقدر أن ينجي مثله».","3:30":"ثم رفع الملك من شأن شدرخ وميشخ وعبدنغو في ولاية بابل.","4:1":"من نبوخذناصر الملك إلى جميع الشعوب والأمم والأقوام من كل لسان المقيمين في كل الأرض: ليكثر سلامكم.","4:2":"قد طاب لي أن أحدث بالآيات والعجائب التي صنعها الله العلي،","4:3":"فما أعظم آياته وما أقوى عجائبه. إن ملكوته أبدي وسلطانه يدوم على مدى الأجيال.","4:4":"أنا نبوخذناصر كنت مقيما مطمئنا في بيتي، أتمتع في البحبوحة في قصري،","4:5":"فرأيت حلما أثار فزعي، وأقلقتني على مضجعي أفكاري ورؤى رأسي،","4:6":"فأصدرت أمرا باستدعاء جميع حكماء بابل أمامي ليطلعوني على تفسير الحلم.","4:7":"فحضر المجوس والسحرة والكلدانيون والمنجمون، فسردت الحلم عليهم فعجزوا عن تفسيره.","4:8":"أخيرا مثل في حضرتي دانيآل المدعو بلطشاصر، كاسم إلهي، الذي فيه روح الآلهة القدوسين فقصصت عليه الحلم.","4:9":"قلت: «يابلطشاصر رئيس المجوس، إني أعلم أن فيك روح الآلهة القدوسين ولا يتعذر عليك سر، فأخبرني برؤى حلمي الذي شهدته وبتفسيره.","4:10":"وهذه هي الرؤيا التي شهدتها في منامي: رأيت وإذا بشجرة منتصبة في وسط الأرض ذات ارتفاع عظيم،","4:11":"وقد نمت الشجرة وقويت حتى بلغ ارتفاعها السماء، وبدت للعيان حتى إلى أطراف الأرض.","4:12":"وكانت أوراقها جميلة وأثمارها كثيرة، توافر فيها غذاء للجميع، وتحتها تستظل وحوش الصحراء وتأوي إلى أغصانها طيور السماء، ومنها يقتات كل ذي جسد.","4:13":"ثم شاهدت في الرؤى وأنا في منامي، وإذا برقيب قدوس قد نزل من السماء،","4:14":"وهتف بصوت مدو وقال: اقطعوا الشجرة واقضبوا أغصانها وبعثروا أوراقها وانثروا أثمارها، لتشرد الوحوش من تحتها، وتهجر الطيور أغصانها.","4:15":"ولكن اتركوا ساق أصلها في الأرض، وأوثقوه بقيد من حديد ونحاس في وسط عشب الحقل، ليبتل بندى السماء، وليكن طعامه من عشب الحقل مع البهائم.","4:16":"وليتحول عقله من عقل إنسان إلى عقل حيوان إلى أن تنقضي عليه سبعة أزمنة.","4:17":"قد صدر هذا القضاء عن أمر الرقباء الساهرين، وقرار الحكم بكلمة القدوسين، لكي يدرك الأحياء أن العلي متسلط في مملكة الناس، يهبها لمن يشاء، ويولي عليها أحقرهم.","4:18":"هذا هو الحلم الذي رأيته أنا نبوخذناصر الملك، وعليك أنت يابلطشاصر أن تفسره، لأن كل حكماء مملكتي قد عجزوا عن إطلاعي على تفسيره. أما أنت فتستطيع ذلك لأن فيك روح الآلهة القدوسين».","4:19":"حينئذ انتابت الحيرة دانيآل المدعو بلطشاصر طوال ساعة وروعته أفكاره، فقال له الملك: «لا يفزعك الحلم ولا تفسيره يابلطشاصر». فأجاب: «ليرتد الحلم على مبغضيك وتفسيره على أعاديك.","4:20":"الشجرة التي شاهدتها والتي نمت واشتدت وبلغ ارتفاعها السماء فبدت للعيان حتى أطراف الأرض،","4:21":"وكانت أوراقها جميلة وأثمارها كثيرة، توافر فيها غذاء للجميع، وتحتها تستظل وحوش الصحراء وتأوي إلى أغصانها طيور السماء،","4:22":"هي أنت أيها الملك الذي نموت وقويت شوكتك وازدادت عظمتك، حتى بلغت إلى السماء، وسلطانك إلى أطراف الأرض.","4:23":"أما ما شاهدته من أن رقيبا قدوسا قد نزل من السماء وقال: اقطعوا الشجرة وأفنوها، ولكن اتركوا ساق أصلها في الأرض، وأوثقوه بقيد من حديد ونحاس في وسط عشب الحقل، ليبتل بندى السماء، وليكن طعامه من عشب الحقل مع البهائم،","4:24":"فهذا هو تفسيره، وهذا هو قضاء العلي الذي يحل بسيدي الملك:","4:25":"سيطردونك من بين الناس فتأوي مع حيوان الصحراء، يطعمونك العشب كالثيران، وتبتل بندى السماء، إلى أن تنقضي عليك سبعة أزمنة، حتى تعلم أن العلي متسلط في مملكة الناس يهبها من يشاء.","4:26":"أما الأمر الصادر بالمحافظة على ساق الشجرة فمعناه أن مملكتك تبقى لك حتى تدرك أن السيادة هي للسماء.","4:27":"لذلك أيها الملك، تقبل مشورتي وتخل عن خطاياك بالبر وآثامك بممارسة الرحمة مع البائسين، عسى أن يطول فلاحك».","4:28":"وقد أصاب نبوخذناصر الملك كل ما أنبأ به دانيآل.","4:29":"فبعد انقضاء اثني عشر شهرا على هذا الحلم، وفيما كان نبوخذناصر يتمشى على سطح قصر بابل الملكي،","4:30":"قال: «أليست هذه هي بابل العظيمة التي بنيتها بقوة اقتداري لتكون عاصمة للمملكة، ولجلال مجدي؟»","4:31":"وفيما كانت كلماته بعد تتردد على شفتيه تجاوب صوت من السماء قائلا: «يانبوخذناصر الملك، لك يقولون الآن قد زال عنك الملك.","4:32":"ثم يطردونك من بين الناس فتأوي مع حيوان الصحراء، ويطعمونك العشب كالثيران إلى أن تنقضي عليك سبعة أزمنة، حتى تعلم أن العلي متسلط في مملكة الناس يهبها لمن يشاء».","4:33":"في تلك الساعة تم حكم القضاء على نبوخذناصر، فطرد من بين الناس وأكل العشب كالثيران، وابتل جسمه بندى السماء حتى استرخى شعره مثل النسور، وطالت أظفاره مثل براثن الطيور.","4:34":"وفي ختام السبعة الأزمنة، أنا نبوخذناصر، التفت نحو السماء، فرجع إلي عقلي، وباركت العلي وسبحت وحمدت الحي الأبدي ذا السلطان السرمدي، والذي ملكه على مدى الأجيال.","4:35":"وعرفت أن كل أهل الأرض لا يحسبون شيئا، وأنه يفعل ما يشاء في جند السماء وسكان الأرض، وليس من يكف يده أو يقول له: ماذا تفعل؟","4:36":"في ذلك الحين ثاب إلي عقلي، وعاد إلي جلال مملكتي ومجدي وبهائي، وطلبني مشيري ونبلاء دولتي، وتثبت على عرش مملكتي وازدادت عظمتي جدا.","4:37":"فالآن، أنا نبوخذناصر، أسبح وأمجد وأحمد ملك السماء الذي جميع أعماله حق، وطرقه عادلة وقادر على إذلال كل من يسلك بالكبرياء.","5:1":"وأقام بيلشاصر الملك مأدبة عظيمة لنبلاء دولته الألف، وشرب خمرا أمامهم.","5:2":"وفيما كان يحتسي الخمر أمر بإحضار آنية الذهب والفضة التي استولى عليها أبوه نبوخذناصر من هيكل أورشليم، ليشرب بها مع نبلاء مملكته وزوجاته ومحظياته.","5:3":"فأحضروها وشرب بها الملك ونبلاء مملكته وزوجاته ومحظياته","5:4":"وأخذوا يسبحون آلهة الذهب والفضة والنحاس والحديد والخشب والحجر.","5:5":"فظهرت أصابع يد إنسان وخطت بإزاء المصباح على كلس جدار قصر الملك، والملك يشهد اليد الكاتبة.","5:6":"عندئذ شحب وجه الملك وأفزعته أفكاره واصطكت ركبتاه واعتراه الانهيار،","5:7":"فزعق طالبا أن يحضروا السحرة والكلدانيين والمنجمين، وقال لهم: «أي رجل يقرأ هذه الكتابة ويفسر لي محتواها، يرتدي الأرجوان وقلادة من ذهب في عنقه، ويصبح الرجل الثالث المتسلط في المملكة».","5:8":"فأقبل حكماء الملك ولكنهم عجزوا عن قراءة الكتابة وعن إطلاع الملك على تفسيرها.","5:9":"فدب الفزع في الملك بيلشاصر، وتبدلت هيئته واعترى عظماءه الاضطراب.","5:10":"وعلى أثر كلام الملك ونبلائه، أقبلت الملكة الأم إلى قاعة المأدبة وقالت له: «أيها الملك لتعش إلى الأبد. لا تروعك أفكارك، ولا يشحب وجهك،","5:11":"لأن في مملكتك رجلا فيه روح الآلهة القدوسين، وقد تميز في عهد أبيك باستنارة وفهم وحكمة كحكمة الآلهة، فعينه أبوك الملك نبوخذناصر رئيسا للمجوس والسحرة والكلدانيين والمنجمين.","5:12":"لأن دانيآل هذا الذي دعاه الملك بلطشاصر، كان يتحلى بروح فاضلة ومعرفة وفطنة، وقدرة على تفسير الأحلام وفك الألغاز وحل المعضلات. فليدع الآن دانيآل ليطلعك على تفسير الكتابة».","5:13":"حينئذ استدعي دانيآل، فمثل أمام الملك، فقال له الملك: «هل أنت دانيآل من المسبيين الذين أحضرهم أبي الملك من أرض يهوذا؟","5:14":"قد سمعت أن فيك روح الآلهة وأن فيك استنارة وفطنة وحكمة حاذقة.","5:15":"وقد سبق أن أحضر أمامي الحكماء والسحرة ليقرأوا هذه الكتابة ويطلعوني على تفسيرها فعجزوا عن ذلك.","5:16":"وأنا قد سمعت عنك أنك قادر على تفسير الأحلام وحل المعضلات فإن استطعت الآن أن تقرأ الكتابة وتطلعني على تفسيرها، ترتدي الأرجوان وتتقلد طوق ذهب في عنقك، وتصبح الرجل الثالث المتسلط في المملكة».","5:17":"فأجاب دانيآل الملك: «لتبق عطاياك لك، وجد بهباتك على غيري، ولكني أقرأ الكتابة للملك وأطلعه على تفسيرها.","5:18":"أيها الملك قد وهب الله العلي أباك نبوخذناصر ملكا وعظمة وجلالا وبهاء.","5:19":"ولفرط عظمته التي أنعم الله بها عليه، كانت جميع الأمم والشعوب من كل لسان ترتعد أمامه وتفزع، فكان يقتل من يشاء، ويستحيي من يشاء، يرفع من يشاء ويضع من يشاء.","5:20":"وعندما شمخ قلبه وقست روحه تعنتا، عزل عن عرش ملكه وجرد من جلاله،","5:21":"وطرد من بين الناس، وماثل عقله الحيوانات، وصار مأواه مع الحمير الوحشية، فأطعموه العشب كالثيران، وابتل جسمه بندى السماء، حتى علم أن الله العلي هو المتسلط في مملكة الناس، وأنه يولي عليها من يشاء.","5:22":"وأنت يابيلشاصر ابنه لم يتواضع قلبك، مع علمك بكل هذا،","5:23":"بل تغطرست على رب السماء، فأحضروا أمامك آنية هيكله لتشرب بها الخمر، أنت ونبَلاء دولتك وزوجاتك ومحظياتك، وسبحت آلهة الفضة والذهب والنحاس والحديد والخشب والحجر التي لا تبصر ولا تسمع ولا تدرك، أما الله الذي بيده روحك وله كل طرقك، فلم تمجده.","5:24":"عندئذ، أرسل من حضرته هذه اليد فخطت هذه الكتابة.","5:25":"وهي: منا منا تقيل وفرسين","5:26":"وتفسيرها منا: أحصى الله أيام ملكك وأنهاه.","5:27":"تقيل: وزنت بالموازين فوجدت ناقصا.","5:28":"فرس: شطرت مملكتك وأعطيت لمادي وفارس».","5:29":"حينئذ أمر بيلشاصر أن يخلعوا على دانيآل الأرجوان ويطوقوا عنقه بقلادة من ذهب ويذيعوا في كل أرجاء البلاد أنه أصبح المتسلط الثالث في المملكة.","5:30":"في تلك الليلة قتل بيلشاصر ملك الكلدانيين،","5:31":"واستولى داريوس المادي على المملكة وهو في الثانية والستين من عمره.","6:1":"وارتأى داريوس أن يولي على المملكة مئة وعشرين حاكما يشرفون على أقاليم المملكة كلها،","6:2":"ونصب عليهم ثلاثة وزراء أحدهم دانيآل، يقدمون لهم حسابا بمدخول خزينة المملكة، فلا يتعرض الملك لخسارة.","6:3":"فأبدى دانيآل تفوقا ملحوظا على سائر الوزراء والحكام، بما يتميز به من روح حاذقة. ونوى الملك أن يوليه شؤون المملكة كلها.","6:4":"فشرع الوزراء والحكام يلتمسون عليه علة اقترفها بحق المملكة فأخفقوا، لأنه كان أمينا لم يرتكب خطأ ولا ذنبا.","6:5":"فقال هؤلاء الرجال: «لا نجد ذنبا نتهم به دانيآل إلا إذا وجدنا علة من نحو شريعة إلهه».","6:6":"عندئذ اجتمع هؤلاء الوزراء والحكام في حضرة الملك قائلين: «لتعش أيها الملك داريوس إلى الأبد.","6:7":"إن جميع وزراء المملكة وقادة الحرس والحكام والمشيرين والولاة قد تداولوا فيما بينهم على إصدار أمر ملكي صارم يعلن فيه: أن كل من يرفع طلبة إلى إله أو إنسان سواك أيها الملك، لمدة ثلاثين يوما، يطرح في جب الأسود.","6:8":"فوقع الآن هذا الأمر أيها الملك واختمه لكي لا يطرأ عليه تغيير، فيكون كشريعة مادي وفارس التي لا تنسخ».","6:9":"وهكذا وقع الملك داريوس الوثيقة والأمر.","6:10":"فلما بلغ دانيآل أمر توقيع الوثيقة مضى إلى بيته وصعد إلى عليته ذات الكوى المفتوحة باتجاه أورشليم، وجثا على ركبتيه ثلاث مرات في اليوم وصلى، وحمد إلهه كمألوف عادته من قبل.","6:11":"فتجمع المتآمرون، ووجدوا دانيآل يبتهل ويتضرع إلى إلهه.","6:12":"فمثلوا في حضرة الملك وتباحثوا في أمره الذي صدر، وقالوا: «ألم توقع أيها الملك أمرا يحظر على كل إنسان رفع طلب إلى إله أو إنسان سواك مدة ثلاثين يوما، ومن يخالف ذلك يطرح في جب الأسود؟» فأجاب الملك: «الأمر صحيح كشريعة مادي وفارس التي لا تنسخ».","6:13":"حينئذ قالوا للملك: «إن دانيآل أحد مسبيي يهوذا قد استهان بك، ولم يأخذ الأمر الذي وقعته بعين الاعتبار، بل ها هو يرفع طلباته لإلهه ثلاث مرات في اليوم».","6:14":"فلما سمع الملك هذا الكلام تولاه غم شديد ووطن النفس على إنقاذ دانيآل، ولكن لم تجده جهوده التي بذلها حتى غروب الشمس في تخليصه.","6:15":"ثم تجمع المتآمرون في حضرة الملك للمرة الثانية وقالوا له: «اعلم أيها الملك أن شريعة مادي وفارس تنص على أن كل نهي أو أمر يوقعه الملك لا يتغير».","6:16":"عند ذلك أمر الملك فأحضروا دانيآل وطرحوه في جب الأسود. وقال الملك لدانيآل: «إن إلهك الذي تعبده دائما هو ينقذك».","6:17":"وأتي بحجر سدوا به فم الجب، وختمه الملك بخاتمه وأختام نبلاء دولته، لئلا يطرأ تغيير على مصير دانيآل.","6:18":"وانطلق الملك إلى قصره وبات تلك الليلة صائما ساهرا، وامتنع عن رؤية محظياته.","6:19":"وعند الفجر باكرا نهض الملك ومضى مسرعا إلى جب الأسود.","6:20":"فلما دنا منه نادى دانيآل بصوت حزين قائلا: «يادانيآل، عبد الله الحي، هل إلهك الذي تعبده دائما استطاع أن ينجيك من الأسود؟»","6:21":"فأجاب دانيآل: «لتعش أيها الملك إلى الأبد.","6:22":"قد أرسل إلهي ملاكه فسد أفواه الأسود فلم تؤذني، لأني وجدت بريئا أمامه، ولم أرتكب سوءا أمامك أيضا أيها الملك».","6:23":"حينئذ فرح الملك جدا وأمر أن يخرج دانيآل من الجب، فأصعدوه ولم يكن قد ناله أي أذى، لأنه آمن بإلهه.","6:24":"ثم أصدر الملك أمره فأحضروا المتآمرين الذين اتهموا دانيآل وطرحوهم في جب الأسود، مع أولادهم ونسائهم. وما كادوا يصلون إلى أسفل الجب حتى بطشت بهم الأسود وهشمت عظامهم.","6:25":"ثم بعث الملك داريوس إلى كل الشعوب والأمم من كل لسان من الساكنين في مملكته برسائل قائلا: «ليكثر سلامكم.","6:26":"قد صدر مني أمر أن يرتعد كل من يقيم في تخوم مملكتي ويخاف أمام إله دانيآل، لأنه هو الإله الحي القيوم إلى الأبد، لا يزول له ملكوت وسلطانه إلى المنتهى.","6:27":"هو ينجي وينقذ ويجري الآيات والعجائب في السماوات والأرض، وهو الذي خلص دانيآل من أنياب الأسود».","6:28":"وحالف النجاح دانيآل في ملك داريوس وفي عهد حكم كورش الفارسي.","7:1":"في السنة الأولى لحكم بيلشاصر ملك بابل رأى دانيآل حلما ورؤى، مرت برأسه وهو مضطجع في فراشه، فدون الحلم وحدث بخلاصة الرؤيا.","7:2":"قال دانيآل: «شاهدت في رؤياي ليلا، وإذا بأربع رياح السماء قد هجمت على البحر الكبير،","7:3":"وما لبث أن صعد من البحر أربعة حيوانات عظيمة يختلف بعضها عن بعض.","7:4":"فكان الأول كالأسد بجناحين كجناحي النسر. وبقيت أنظر إليه حتى اقتلع جناحاه، وانتصب على الأرض واقفا على رجلين كإنسان، وأعطي عقل إنسان.","7:5":"ورأيت حيوانا آخر شبيها بالدب، قائما على جنب واحد، وفي فمه بين أسنانه ثلاث أضلع وقيل له: «انهض وكل لحما كثيرا».","7:6":"ثم رأيت بعد هذا حيوانا آخر مثل النمر، له على ظهره أربعة أجنحة كأجنحة الطائر، وكان لهذا الحيوان أربعة رؤوس، وفوضت إليه سلطات.","7:7":"وشهدت بعد ذلك في رؤى الليل وإذا بحيوان رابع هائل وقوي وشديد جدا، ذي أسنان ضخمة من حديد، افترس وسحق وداس ما تبقى برجليه. وكان يختلف عن سائر الحيوانات التي قبله وله عشرة قرون.","7:8":"وفيما كنت أتأمل القرون إذا بقرن آخر صغير نبت بينها، واقتلعت ثلاثة قرون من أمامه، وكان في هذا القرن عيون كعيون الإنسان وفم ينطق بعظائم.","7:9":"وفيما كنت أنظر، نصبت عروش واعتلى الأزلي كرسيه وكانت ثيابه بيضاء كالثلج، وشعر رأسه كالصوف النقي، وعرشه لهيبا متوهجا وعجلاته نارا متقدة.","7:10":"ومن أمامه يتدفق ويجري نهر من نار، وتخدمه ألوف ألوف الملائكة، ويمثل في حضرته عشرات الألوف. فانعقد مجلس القضاء وفتحت الأسفار.","7:11":"وبقيت أراقب القرن من جراء ما تفوه به من عظائم، حتى قتل الحيوان وتلف جسمه وطرح وقودا للنار.","7:12":"أما سائر الحيوانات فقد جردت من سلطانها، ولكنها وهبت البقاء على قيد الحياة لزمن ما.","7:13":"وشاهدت أيضا في رؤى الليل وإذا بمثل ابن الإنسان مقبلا على سحاب حتى بلغ الأزلي فقربوه منه.","7:14":"فأنعم عليه بسلطان ومجد وملكوت لتتعبد له كل الشعوب والأمم من كل لسان. سلطانه سلطان أبدي لا يفنى، وملكه لا ينقرض.","7:15":"أما أنا دانيآل فقد ران الحزن على روحي في داخلي وروعتني رؤى رأسي.","7:16":"فاقتربت من أحد الواقفين أستفسر منه حقيقة الأمر، فأطلعني على معنى الرؤيا قائلا:","7:17":"«هذه الحيوانات الأربعة العظيمة هي أربعة ملوك يظهرون على الأرض.","7:18":"غير أن قديسي العلي يستولون على المملكة ويتملكونها إلى أبد الآبدين.","7:19":"حينئذ أردت أن أطلع على حقيقة الحيوان الرابع الذي كان يختلف عن سائر الحيوانات، إذ كان هائلا جدا ذا أسنان من حديد ومخالب من نحاس، وقد افترس وسحق وداس ما تبقى برجليه.","7:20":"وعن القرون العشرة النامية في رأسه، وعن القرن الآخر الصغير الذي نبت، فاقتلعت أمامه ثلاثة قرون. هذا القرن ذو العيون الناطق بالعظائم ومنظره أشد هولا من رفاقه.","7:21":"وقد شهدت هذا القرن يحارب القديسين ويغلبهم.","7:22":"إلى أن جاء الأزلي وانعقد مجلس القضاء الذي فيه تبرأت ساحة قديسي العلي، وأزف الوقت الذي فيه امتلكوا المملكة.","7:23":"فأجاب: إن الحيوان الرابع هو رمز للمملكة الرابعة على الأرض، وهي تختلف عن سائر الممالك لأنها تستولي على كل الأرض وتخضعها وتسحقها.","7:24":"أما القرون العشرة من هذه المملكة فهي عشرة ملوك يتولونها، ثم يقوم بعدهم ملك آخر يختلف عن الملوك السالفين، ويخضع ثلاثة ملوك،","7:25":"ويعير العلي وينكل بقديسيه، ويحاول أن يغير الأوقات والقوانين، فيذل القديسين ثلاث سنوات ونصف السنة.","7:26":"ولكن ينعقد مجلس القضاء، فيجرد من سلطانه فيدمر ويفنى إلى المنتهى.","7:27":"وتوهب المملكة والسلطان وعظمة الممالك القائمة تحت كل السماء إلى شعب قديسي العلي، فيكون ملكوت العلي ملكوتا أبديا، وتعبده جميع السلاطين ويطيعونه.","7:28":"إلى هنا ختام الرؤيا. أما أنا دانيآل فقد روعتني أفكاري كثيرا وتغيرت هيئتي، ولكني كتمت الأمر في قلبي».","8:1":"وفي السنة الثالثة من مدة حكم بيلشاصر الملك، ظهرت لي أنا دانيآل رؤيا أخرى بعد الرؤيا الأولى،","8:2":"وكنت آنئذ في شوشان عاصمة ولاية عيلام بجوار نهر أولاي،","8:3":"فرفعت عيني وإذا بي أرى كبشا واقفا عند النهر، وله قرنان طويلان. إنما أحدهما أطول من الآخر، مع أن الأطول نبت بعد الأول.","8:4":"ورأيت الكبش ينطح غربا وشمالا وجنوبا، من غير أن يجرؤ أي حيوان على مقاومته، ولم يكن من منقذ منه، ففعل كما يحلو له وعظم شأنه","8:5":"وبينما كنت متأملا، أقبل تيس من المغرب عبر كل الأرض من غير أن يمسها. وكان للتيس قرن بارز بين عينيه.","8:6":"واندفع بكل شدة قوته نحو الكبش ذي القرنين الذي رأيته واقفا عند النهر.","8:7":"وما إن وصل إليه حتى هجم عليه وضربه وحطم قرنيه، فعجز الكبش عن صده. وطرحه التيس على الأرض وداسه ولم يكن للكبش من ينقذه من يده.","8:8":"فعظم شأن التيس. وعندما اعتز انكسر القرن العظيم ونبت عوضا عنه أربعة قرون بارزة نحو جهات الأرض الأربع.","8:9":"ونما من واحد منها قرن صغير عظم أمره، وامتد جنوبا وشرقا ونحو أرض إسرائيل،","8:10":"وبلغ من عظمته أنه تطاول على ملوك الأرض وقضى على بعضهم وداس عليهم،","8:11":"وتحدى حتى رئيس الجند (أي الله)، وتكبر عليه، وألغى المحرقة الدائمة وهدم الهيكل.","8:12":"وبسبب المعصية سلط على جند القديسين وعلى المحرقة اليومية. وحالفه التوفيق في كل ما صنع فطرح الحق على الأرض.","8:13":"فسمعت قدوسا يتكلم، فيرد عليه قدوس آخر: «كم يطول زمن الرؤيا بشأن المحرقة الدائمة اليومية، ومعصية الخراب، وتسليم الهيكل والجند ليكونوا مدوسين؟»","8:14":"فأجابه: «إلى ألفين وثلاث مئة يوم ثم يتطهر الهيكل».","8:15":"وبعد أن شاهدت أنا دانيآل الرؤيا وطلبت تفسيرا لها، إذا بشبه إنسان واقف أمامي.","8:16":"وسمعت صوت إنسان صادرا من بين ضفتي نهر أولاي قائلا: «ياجبرائيل، فسر لهذا الرجل الرؤيا».","8:17":"فجاء إلي حيث وقفت، فتولاني الخوف وانطرحت على وجهي، فقال لي: «افهم ياابن آدم. إن الرؤيا تختص بوقت المنتهى».","8:18":"وفيما كان يخاطبني وأنا مكب بوجهي إلى الأرض غشيني سبات عميق، فلمسني وأنهضني على قدمي،","8:19":"وقال: «ها أنا أطلعك على ما سيحدث في آخر حقبة الغضب، لأن الرويا ترتبط بميعاد الانتهاء.","8:20":"إن الكبش ذا القرنين الذي رأيته هو ملوك مادي وفارس.","8:21":"والتيس الأشعر هو ملك اليونان، والقرن العظيم النابت بين عينيه هو الملك الأول.","8:22":"وما إن انكسر حتى خلفه أربعة عوضا عنه، تقاسموا مملكته ولكن لم يماثلوه في قوته.","8:23":"وفي أواخر ملكهم عندما تبلغ المعاصي أقصى مداها، يقوم ملك فظ حاذق داهية،","8:24":"فيعظم شأنه، إنما ليس بفضل قوته. ويسبب دمارا رهيبا ويفلح في القضاء على الأقوياء، ويقهر شعب الله.","8:25":"وبدهائه ومكره يحقق مآربه، ويتكبر في قلبه ويهلك الكثيرين وهم في طمأنينة، ويتمرد على رئيس الرؤساء لكنه يتحطم بغير يد الإنسان.","8:26":"ورؤيا الألفين والثلاث مئة يوم التي تجلت لك هي رؤيا حق، ولكن اكتم الرؤيا لأنها لن تتحقق إلا بعد أيام كثيرة».","8:27":"فضعفت أنا دانيآل ونحلت أياما، ثم قمت وعدت أباشر أعمال الملك. وروعتني الرؤيا، ولم أكن أفهمها.","9:1":"في السنة الأولى من حكم داريوس بن أحشويروش من ذرية الماديين، الذي اعتلى عرش مملكة الكلدانيين.","9:2":"في السنة الأولى من ملكه، أدركت أنا دانيآل، من دراسة الأسفار التي دون فيها وحي الرب إلى إرميا، أن عدد السنوات التي قضي بها على خراب أورشليم هو سبعون سنة.","9:3":"فاتجهت بنفسي إلى السيد الرب، أبتهل إليه بالصلاة والتضرعات والصوم وارتداء المسح والتعفر بالرماد.","9:4":"وصليت إلى الرب إلهي واعترفت قائلا: «أيها الرب الإله العظيم المهوب، حافظ العهد والرحمة لمحبيه وعاملي وصاياه.","9:5":"إننا أخطأنا وأثمنا وارتكبنا الشر، وتمردنا وانحرفنا عن وصاياك وأحكامك.","9:6":"ولم نسمع لعبيدك الأنبياء الذين باسمك أنذروا ملوكنا ورؤساءنا وآباءنا وجميع شعب الأرض.","9:7":"لك أيها السيد البر، ولنا الخزي، كما هو حادث اليوم لرجال يهوذا ولأهل أورشليم، ولسائر بني إسرائيل القريبين والبعيدين، المشتتين في كل البلدان التي أجليتهم إليها عقابا لهم على ما اقترفوه من خيانة في حقك.","9:8":"فلنا أيها السيد الخزي، نحن وملوكنا ورؤسائنا وآبائنا، لأننا أخطأنا إليك.","9:9":"إنما للرب إلهنا الرحمة والمغفرة لأننا عصيناك.","9:10":"ولم نطع صوت الرب إلهنا لنسلك في شرائعه التي أعلنها لنا على لسان عبيده الأنبياء.","9:11":"قد تعدى كل شعب إسرائيل على شريعتك، وانحرفوا فلم يسمعوا صوتك، فسكبت علينا اللعنة وما أقسمت أن توقعه بنا، كما نصت عليه شريعة موسى عبد الله، لأننا أخطأنا إليك.","9:12":"وقد نفذت قضاءك الذي قضيت به علينا وعلى قضاتنا الذين تولوا أمرنا، جالبا علينا وعلى أورشليم شرا عظيما لم يحدث له مثيل تحت السماء.","9:13":"وكما ورد في شريعة موسى، أصابنا جميع هذا البلاء، ولم نستعطف وجهك أيها الرب إلهنا تائبين عن آثامنا ومتنبهين لحقك.","9:14":"فأضمرت لنا العقاب وأوقعته بنا لأنك إلهنا البار في كل أعمالك التي صنعتها لأننا لم نستمع إليك.","9:15":"والآن أيها السيد إلهنا، يامن أخرجت شعبك من ديار مصر بقوة مقتدرة، وأشهرت اسمك كما هو حادث اليوم، قد أخطأنا وارتكبنا الشر.","9:16":"فاصرف ياسيد، حسب رحمتك، سخطك وغضبك عن مدينتك أورشليم جبل قدسك إذ من جراء خطايانا وآثام آبائنا أصبحت أورشليم مثار عار لنا عند جميع المحيطين بنا.","9:17":"فأنصت الآن ياإلهنا إلى صلاة عبدك وابتهالاته، وأضيء بوجهك على هيكلك المتهدم، من أجل ذاتك.","9:18":"أرهف أذنك ياإلهي واستمع، وافتح عينيك وشاهد خرائبنا والمدينة التي دعي اسمك عليها، فإننا لا من أجل بر فينا نرفع تضرعاتنا إليك، بل بفضل مراحمك العظيمة.","9:19":"فاستمع أيها السيد واغفر. أصغ أيها السيد وتصرف ولا تبطىء من أجل نفسك ياإلهي، لأن اسمك دعي على مدينتك وعلى شعبك».","9:20":"وبينما كنت أصلي وأعترف بخطيئتي وخطيئة شعبي إسرائيل، وأرفع تضرعاتي أمام الرب إلهي من أجل جبل قدس إلهي،","9:21":"إذا بالملاك جبرائيل الذي عاينته في الرؤيا في البدء، قد طار إلي مسرعا ولمسني، في موعد تقدمة المساء.","9:22":"وأفهمني قائلا: يادانيآل قد جئت لأعلمك الفهم.","9:23":"فمنذ أن شرعت في تضرعاتك صدر إلي الأمر لأجيء إليك وأطلعك على ما تبغي، لأنك محبوب جدا، لهذا تأمل ما أقول وافهم الرؤيا.","9:24":"قد صدر القضاء أن يمضي سبعون أسبوعا على شعبك وعلى مدينة قدسك، للانتهاء من المعصية والقضاء على الخطيئة، وللتكفير عن الإثم، ولإشاعة البر الأبدي وختم الرؤيا والنبوءة ولمسح قدوس القدوسين.","9:25":"لهذا فاعلم وافهم أن الحقبة الممتدة منذ صدور الأمر بإعادة بناء أورشليم إلى مجيء المسيح، سبعة أسابيع، ثم اثنان وستون أسبوعا يبنى في غضونها سوق وخليج. إنما تكون تلك أزمنة ضيق.","9:26":"وبعد اثنين وستين أسبوعا يقتل المسيح، ولكن ليس من أجل نفسه، ويدمر شعب رئيس آت المدينة والقدس، وتقبل آخرتها كطوفان، وتستمر الحرب حتى النهاية، ويعم الخراب المقضي به.","9:27":"ويبرم عهدا ثابتا مع كثيرين لمدة أسبوع واحد، ولكنه في وسط الأسبوع يبطل الذبيحة والتقدمة، ويقيم على جناح الهيكل رجاسة الخراب، إلى أن يتم القضاء، فينصب العقاب على المخرب».","10:1":"وفي السنة الثالثة لحكم كورش ملك فارس، أعلن وحي لدانيآل المدعو بلطشاصر، والوحي دائما حق. وبعد مكابدة مجهدة، أدرك فحوى الوحي وفهم معنى الرؤيا.","10:2":"في ذلك الوقت أنا دانيآل قضيت ثلاثة أسابيع في النوح،","10:3":"لم آكل فيها طعاما شهيا، ولم يدخل فمي لحم أو خمر، ولم أتطيب بدهن.","10:4":"وفي اليوم الرابع والعشرين من الشهر الأول، بينما كنت إلى جوار نهر دجلة الكبير،","10:5":"تطلعت حولي فإذا برجل مرتد كتانا، وحقواه متحزمان بنطاق من ذهب نقي،","10:6":"وجسمه كالزبرجد، ووجهه يتألق كالبرق وعيناه تتوهجان كمصباحي نار، وذراعاه ورجلاه لامعة كالنحاس المصقول، وأصداء كلماته كجلبة جمهور.","10:7":"كنت وحدي أنا دانيآل الذي شاهدت الرؤيا، أما الرجال الذين كانوا معي فلم يروا شيئا. إنما هيمنت عليهم رعدة عظيمة، فهربوا مختبئين.","10:8":"وبقيت أنا وحدي أشهد الرويا العظيمة، وقد تلاشت مني القوة، وتحولت نضارتي إلى ذبول، وفقدت قدرتي.","10:9":"وما إن سمعت أصداء كلماته حتى سقطت على وجهي إلى الأرض يغشاني سبات عميق.","10:10":"وإذا بيد لمستني وأقامتني، وأنا أرتجف على يدي وركبتي","10:11":"وقال لي: «يادانيآل، أيها الرجل المحبوب، افهم الكلام الذي أخاطبك به، وقف على رجليك لأنني قد أرسلت إليك». وعندما قال لي هذا الكلام نهضت مرتعدا.","10:12":"فقال لي: «لا تخف يادانيآل، فمنذ اليوم الأول الذي عزمت فيه على الفهم، وتذللت أمام إلهك، سمعت تضرعاتك، وها أنا جئت تلبية لها.","10:13":"غير أن رئيس مملكة فارس قاومني واحدا وعشرين يوما. فأقبل ميخائيل، أحد كبار الرؤساء لمعونتي، بعد أن حجزت هناك عند ملوك فارس.","10:14":"وقد جئت الآن لأطلعك على ما يصيب شعبك في الأيام الأخيرة، لأن الرويا تختص بالأيام المقبلة».","10:15":"فلما خاطبني بمثل هذا الكلام، أطرقت بوجهي إلى الأرض وصمت،","10:16":"وإذا بشبه بني البشر لمس شفتي، ففتحت فمي وقلت للماثل أمامي: «ياسيدي، قد غلبني الأ لم بسبب الرؤيا، فما امتلكت قوة،","10:17":"فكيف يستطيع عبد سيدي هذا أن يتحدث مع سيدي، وقد نضبت مني القوة، ولم تبق في نسمة؟»","10:18":"فعاد من هو في شبه إنسان ولمسني وشددني،","10:19":"وقال: «لا تخف أيها الرجل المحبوب؛ سلام لك. تقو وتشجع». وحالما كلمني دبت في القوة وقلت: «ليتكلم سيدي لأنك شددتني».","10:20":"فسألني: «هل أدركت لماذا جئت إليك والآن ها أنا أعود لأحارب رئيس فارس، وما إن أنتهي منه حتى يقبل رئيس اليونان.","10:21":"ولكني أطلعك على ما نص عليه في كتاب الحق، ولا أحد يؤازرني ضد هؤلاء سوى حارس شعبكم الملاك ميخائيل».","11:1":"«فقد سبق لي في السنة الأولى من حكم داريوس المادي أن آزرته وشددته.","11:2":"والآن لأكشفن لك الحقيقة، فها ثلاثة ملوك يتولون حكم فارس، يعقبهم رابع يكون أوفرهم ثراء. وبفضل قوة غناه يثير الجميع على مملكة اليونان.","11:3":"ولكن لا يلبث أن يظهر في اليونان ملك عات يتمتع بسلطان عظيم، ويفعل ما يحلو له.","11:4":"ولكن في ذروة قوته تنقسم مملكته إلى أربعة أقسام، فلا تكون لعقبه، ولا تكون في مثل قوة ملكه، بل يتولاها آخرون. أما سلطانه فينقرض.","11:5":"ثم تنمو قوة الجنوب غير أن واحدا من قواد ملك اليونان المنقرض يصبح أكثر قوة منه، ويتسع نفوذه وسلطانه.","11:6":"وبعد سنوات يعقد الملكان معاهدة سلام، تصبح فيها ابنة ملك الجنوب زوجة لملك الشمال، ولكنها تفقد تأثيرها عليه، فلا تتحقق لها ولا لأبيها ولا لابنها ولا لمن آزرها في تلك الأوقات آمال.","11:7":"ويتولى من فرع أصولها (أي أخوها) الملك، فيزحف على رأس جيش ويقتحم حصن ملك الشمال وينكل بهم ويقهرهم.","11:8":"ويسبي إلى مصر آلهتهم مع أصنامهم والآنية النفيسة من الفضة والذهب. ثم يتوقف عن محاربة ملك الشمال لعدة سنوات.","11:9":"ثم يغزو ملك الشمال أرض ملك الجنوب ولكنه يرجع إلى أرضه فاشلا.","11:10":"إلا أن بني ملك الشمال يثورون ويحشدون جيوشا عظيمة، تتقدم كالطوفان عبر أرض إسرائيل، وتهجم على أرض ملك الجنوب حتى تبلغ العاصمة.","11:11":"فينفجر ملك الجنوب غيظا، فيجند جيوشا هائلة ويخرج ويحارب ملك الشمال ويقهر جيوشه","11:12":"ويقضي عليها، ويفني عشرات الألوف، ويشمخ قلبه. غير أن","11:13":"ملك الشمال لا يلبث أن يجند جيشا عرمرما أضخم من الجيش السابق، وبعد سنوات يزحف بقواته الكبيرة وعدته العظيمة.","11:14":"وفي ذلك الحين يتمرد كثيرون على ملك الجنوب، ويثور المتمردون من أبناء شعبك، ولكنهم يخفقون، وذلك لإتمام الرؤيا.","11:15":"ويقبل ملك الشمال ويقيم متاريس الحصار، ويستولي على مدينة محصنة، وتعجز قوات ملك الجنوب وفرقه المنتخبة عن صده، لأنها تفقد كل قوة.","11:16":"أما الملك الغازي فيفعل ما يطيب له، ولا أحد يقدر على مقاومته. ويستولي على الأرض البهية ويخضعها لسلطانه.","11:17":"ويوطد العزم على دخول أرض ملك الجنوب بكل جيوشه، إلا أنه يحمل معه شروط صلح. ويزوج ملك الجنوب من ابنته لتكون له عينا عليه. ولكن خطته لا يحالفها النجاح.","11:18":"فيتحول نحو مدن ساحل البحر ويستولي على كثير منها، غير أن قائدا يرده عنها ويلحق به عار الهزيمة.","11:19":"فيرجع إلى حصون أرضه، فتعترضه العقبات في أثناء عودته فيتعثر ويختفي ذكره.","11:20":"ثم يعتلي العرش بعده من يبعث جباة الجزية إلى أرض إسرائيل، ولكنه في غضون أيام قليلة تصيبه الهزيمة من غير فتنة ولا حرب.","11:21":"ويخلفه حقير لم ينعم عليه بجلال الملك، إنما يحرز العرش فجأة، ويتولى زمام المملكة بالمداهنة.","11:22":"ويمحق جيوشا بأسرها فتندحر أمامه، ومن جملتهم رئيس الكهنة.","11:23":"ومنذ اللحظة التي يبرم فيها عهدا يتصرف بمكر، ويحرز قوة وعظمة بنفر قليل،","11:24":"يقتحم فجأة أخصب البلاد، ويرتكب من الموبقات ما لم يرتكبه آباؤه ولا أسلافه. ويغدق الثراء على أعوانه مما نهبه وغنمه، ويرسم خططا للاستيلاء على الحصون، إنما يحدث هذا إلى أمد وجيز.","11:25":"ويستثير همته ويجند قواته لمحاربة ملك الجنوب بجيش عظيم ويتأهب ملك الجنوب للقتال بجيش ضخم وقوي جدا، ولكنه لا يصمد، لأن أعداءه يتآمرون عليه.","11:26":"ويخونه الآكلون من طعامه الشهي، ويندحر جيشه ويصرع كثيرون.","11:27":"ويضمر هذان الملكان ارتكاب المكائد، وينطقان بالكذب وهما يجلسان على مائدة واحدة، ولا يفلحان لأن موعد حلول قضاء الله بات وشيكا.","11:28":"ويرجع ملك الشمال إلى بلاده بغنى جزيل، وفي قلبه أن يدمر أرض إسرائيل، فيفعل ذلك ثم يعود إلى أرضه.","11:29":"وفي الموعد المقرر يعود ويقتحم أرض الجنوب، ولكن حملته في هذه المرة لا تكون مماثلة للحملتين السابقتين.","11:30":"إذ تنقض عليه سفن حربية من قبرص، فيعتريه يأس ويغلي غيظا على أرض إسرائيل، ويصغى إلى مشورة رافضي العهد المقدس.","11:31":"فتهاجم بعض قواته حصن الهيكل وتنجسه، وتزيل المحر قة الدائمة، وتنصب الرجس المخرب (أي الوثن).","11:32":"ويغوي بالمداهنة المتعدين على عهد الرب. أما الشعب الذين يعرفون إلههم فإنهم يصمدون ويقاومون.","11:33":"والعارفون منهم يعلمون كثيرين، مع أنهم يقتلون بالسيف والنار ويتعرضون للأسر والنهب أياما.","11:34":"ولا يلقون عند سقوطهم إلا عونا قليلا، وينضم إليهم كثيرون نفاقا.","11:35":"ويعثر بعض الحكماء تمحيصا لهم وتنقية، حتى يأزف وقت النهاية في ميقات الله المعين.","11:36":"ويصنع الملك ما يطيب له، ويتعظم على كل إله، ويجدف بالعظائم على إله الآلهة، ويفلح، إلى أن يحين اكتمال الغضب إذ لابد أن يتم ما قضى الله به.","11:37":"ولن يبالي هذا الملك بآلهة آبائه ولا بمعبود النساء، ولا بأي وثن آخر إذ يتعظم على الكل.","11:38":"إنما يكرم إله الحصون بدلا منهم، وهو إله لم يعرفه آباؤه، ويكرمه بالذهب والفضة والحجارة الكريمة والنفائس.","11:39":"ويقتحم القلاع المحصنة باسم إله غريب. وكل من يعترف به يغدق عليه الإكرام، ويوليه على كثيرين، ويقسم الأرض بينهم، أجرة لهم.","11:40":"وعندما تأزف النهاية يحاربه ملك الجنوب، فينقض عليه ملك الشمال كالزوبعة بمركبات وفرسان وسفن كثيرة، ويقتحم دياره كالطوفان الجارف.","11:41":"ويغزو أرض إسرائيل فيسقط عشرات الألوف صرعى، ولا ينجو منه سوى أرض أدوم وأرض موآب والجزء الأكبر من أرض عمون.","11:42":"يبسط يده على الأراضي فلا تفلت منه حتى أرض مصر.","11:43":"ويستولي على كنوز الذهب والفضة وعلى كل ذخائر مصر. ويسير الليبيون والإثيوبيون في ركابه.","11:44":"وتبلغه أخبار من الشرق ومن الشمال، فيرجع بغضب شديد ليدمر ويقضي على كثيرين،","11:45":"وينصب خيمته الملكية بين البحر وأورشليم، ويبلغ نهاية مصيره وليس له من نصير».","12:1":"«وفي ذلك الوقت يقوم الرئيس العظيم الملاك ميخائيل حارس شعبك، وذلك في أثناء ضيق لم يكن له مثيل منذ أن وجدت أمة حتى ذلك الزمان. غير أن كل من كان اسمه مدونا في الكتاب من شعبك ينجو في ذلك الزمان.","12:2":"ويستيقظ كثيرون من الأموات المدفونين في تراب الأرض، بعضهم ليثابوا بالحياة الأبدية وبعضهم ليساموا ذل العار والازدراء إلى الأبد.","12:3":"ويضيء الحكماء (أي شعب الله) كضياء الجلد، وكذلك الذين ردوا كثيرين إلى البر يشعون كالكواكب إلى مدى الدهر.","12:4":"أما أنت يادانيآل فاكتم الكلام، واختم على الكتاب إلى ميعاد النهاية. وكثيرون يطوفون في الأرض وتزداد المعرفة».","12:5":"ثم رأيت أنا دانيآل فإذا باثنين آخرين وقف كل منهما على ضفة من ضفتي النهر،","12:6":"سأل أحدهما الرجل اللابس الكتان الواقف على مياه النهر: «متى ينقضي زمن هذه الأحداث العجيبة؟».","12:7":"فسمعت الرجل اللابس الكتان الواقف فوق مياه النهر يقول، بعد أن رفع يديه نحو السماوات مقسما بالحي إلى الأبد: «تنقضي هذه العجائب بعد ثلاث سنوات ونصف، حين يتم تشتيت قوة الشعب المقدس».","12:8":"فسمعت ما قاله ولكنني لم أفهم، فسألت: «ياسيدي ما هي آخر هذه؟»","12:9":"فأجاب: «اذهب يادانيآل لأن الكلمات مكتومة ومختومة إلى وقت النهاية.","12:10":"كثيرون يتطهرون ويتنقون ويمحصون بالتجارب، أما الأشرار فيرتكبون شرا ولا يفهمون. إنما ذوو الفطنة يدركون.","12:11":"أما الفترة ما بين إزالة المحرقة الدائمة وإقامة رجس المخرب، فهي ألف ومئتان وتسعون يوما.","12:12":"فطوبى لمن ينتظر حتى يبلغ إلى الألف والثلاث مئة والخمسة والثلاثين يوما.","12:13":"وأما أنت فاذهب إلى آخرتك فتستريح، ثم تقوم في نهاية الأيام لتثاب بما قسم لك»."},"Eze":{"1:1":"وحدث في اليوم الخامس من الشهر الرابع العبري، في السنة الثلاثين، فيما كنت بين المسبيين بجوار نهر خابور، أن انفتحت السماوات فشاهدت رؤى من عند الله.","1:2":"في اليوم الخامس من الشهر، في السنة الخامسة لسبي الملك يوياكين،","1:3":"أوحى الرب إلى حزقيال الكاهن ابن بوزي عند جوار نهر خابور، في ديار الكلدانيين، إذ كانت علي يد الرب،","1:4":"فأبصرت ريحا عاصفة تهب من الشمال مصحوبة بسحابة هائلة، ونار متواصلة متوهجة بهالة محيطة من الضياء؛ ومن وسطها يتألق مثل النحاس اللامع البارق من وسط النار.","1:5":"ومن داخلها بدا شبه أربعة كائنات حية تماثل في صورها شبه إنسان،","1:6":"وكان لكل واحد منها أربعة أوجه وأربعة أجنحة.","1:7":"وكانت سيقانها مستقيمة، وأقدامها مشابهة لأقدام العجل، وهي تبرق كبريق النحاس المصقول.","1:8":"وتحت أجنحتها القائمة على جوانبها الأربعة، أيدي بشر، وكان لكل كائن من هذه الكائنات الأربعة أجنحة وأوجه.","1:9":"وكانت أجنحتها تتلامس، وأوجهها لا تدور عند سيرها، بل يسير كل منها ووجهه متجه إلى الأمام.","1:10":"أما أشكال أوجهها، فكان لكل واحد منها وجه إنسان، يحاذيه إلى اليمين وجه أسد، وإلى الشمال وجه ثور، ثم إلى جواره وجه نسر.","1:11":"كانت هذه أشكال أوجهها. وكان لكل منها أربعة أجنحة تمتد من وسط الظهر: اثنان يتصل طرف كل منهما بطرف جناح الكائن الآخر، واثنان يستران أجسامهما.","1:12":"وكان كل واحد منها يتجه إلى الأمام من غير أن يدور، فحيثما يتوجه الروح يتوجهون هم أيضا.","1:13":"أما منظر الكائنات الحية هذه فكان كجمرات نار متقدة، أو مشاعل تجوز جيئة وذهابا بين الكائنات الحية. وكانت النار مضيئة يلمع منها وميض برق.","1:14":"والكائنات الحية تتراكض ذهابا وإيابا في سرعة لمح البرق.","1:15":"وفيما كنت أتأمل في الكائنات الحية، إذا بي أشاهد أربع عجلات، عجلة لكل واحد من الكائنات الحية.","1:16":"أما شكل العجلات وصنعتها فكان كمثل الزبرجد، وهي متشابهة الصورة. وكان منظرها وصنعتها كأنها عجلة داخل عجلة.","1:17":"وإذا سارت فإنها تسير في أي من الاتجاهات الأربعة إلى الأمام، من غير أن تتحول عن اتجاهها.","1:18":"أما أطرها فعالية وهائلة، وجميعها ملأى بالعيون.","1:19":"وكلما تتحرك الكائنات الحية، تتحرك معها العجلات، وكلما ترتفع عن الأرض ترتفع معها العجلات أيضا.","1:20":"وحيثما يتوجه الروح تتوجه أيضا، وترتفع معها عجلاتها، لأن روح الكائنات الحية سار أيضا في العجلات.","1:21":"فإن سارت هذه تسير تلك، وإن توقفت تتوقف، لأن روح الكائنات الحية سار في العجلات أيضا.","1:22":"وانبسط فوق رؤوس الكائنات الحية جلد يشبه البلور المتلأليء الهائل.","1:23":"وامتدت أجنحتها تحت الجلد باستقامة، الواحد نحو الآخر. لكل واحد منها جناحان يستران جسمه من الجانبين.","1:24":"وعندما سارت سمعت رفرفة أجنحتها كهدير مياه غزيرة، كصوت القدير، كصوت جلبة جيش، وعند توقفها كانت ترخي أجنحتها.","1:25":"وصدر صوت من فوق الجلد المنبسط على رؤوسها. وحين تتوقف كانت ترخي أجنجتها.","1:26":"وانتصب فوق الجلد المنبسط على رؤوسها شبه عرش، منظره كحجر اللازورد. ويجلس على شبه العرش من فوق من هو كشبه إنسان.","1:27":"ورأيت ما يبدو من حقويه فما فوق وكأنه نحاس لامع يتوهج في داخله وحواليه. أما ما يبدو من حقويه وما تحت، فكأنه نار، وحواليها يشع بالضياء.","1:28":"وكان منظر اللمعان المحيط به كمنظر قوس قزح في يوم مطير؛ هكذا كان منظر شبه مجد الرب. وعندما أبصرت خررت على وجهي وسمعت صوتا يتكلم.","2:1":"ثم قال لي: «ياابن آدم، قف على قدميك فأخاطبك».","2:2":"وحالما تكلم دخل في الروح وأنهضني على قدمي وسمعته يخاطبني:","2:3":"«ياابن آدم، ها أنا باعثك إلى بني إسرائيل، إلى أمة متمردة عصتني، إذ تعدوا هم وآباؤهم علي إلى هذا اليوم.","2:4":"أنا باعثك إلى الأبناء المتصلبين القساة، فتقول لهم: هذا ما يعلنه الرب.","2:5":"فإن سمعوا، أو أبوا لأنهم شعب عاص فإنهم يعلمون على الأقل أن نبيا بينهم.","2:6":"أما أنت، ياابن آدم، فلا ترهبهم ولا تخش كلامهم، وإن كانوا لك قريسا وشوكا. وأنت ساكن بين عقارب، فلا ترهب كلامهم، ولا تفزع من محضرهم لأنهم شعب متمرد.","2:7":"إنما عليك أن تبلغهم كلامي سواء سمعوا أو أبوا، لأنهم شعب متمرد.","2:8":"والآن ياابن آدم، أصغ لما أخاطبك به. لا تكن متمردا مثل ذلك الشعب المتمرد. افتح فمك وكل ما أطعمك».","2:9":"فنظرت وإذا بيد ممتدة إلي، وفيها درج كتاب.","2:10":"وعندما نشره أمامي رأيت الكتابة تملأه من الداخل والخارج وقد دونت فيه مراث ومناحات وويلات.","3:1":"ثم قال لي: «ياابن آدم، كل ما تجده. كل هذا الدرج وامض وخاطب شعب إسرائيل».","3:2":"ففتحت فمي فأطعمني هذا الدرج،","3:3":"وقال لي: «أطعم جوفك واملأه بهذا الدرج الذي أعطيك إياه». فالتهمته، فكان في فمي في حلاوة العسل.","3:4":"ثم قال لي: «ياابن آدم، انطلق إلى شعب إسرائيل وخاطبهم بكلماتي.","3:5":"فإنك لست مرسلا إلى أمة ذات لهجة غريبة ولغة مبهمة، بل إلى شعب إسرائيل،","3:6":"ولا إلى شعوب كثيرة غريبة اللهجات ومبهمة اللغات لا تفهم كلامهم. حقا لو أرسلتك إلى هؤلاء لسمعوا لك!","3:7":"لكن شعب إسرائيل لا يودون الاستماع لك، لأنهم لا يودون الاستماع لي، لأنهم جميعا معاندون قساة القلوب.","3:8":"ها أنا قد جعلت وجهك صلبا مثل وجوههم، وجبهتك قاسية مثل جباههم.","3:9":"قد جعلت جبهتك في صلابة الماس، أقسى من الصوان، فلا تخف منهم ولا ترتعب من مرآهم لأنهم شعب متمرد».","3:10":"ثم أردف قائلا: «ياابن آدم، استوعب في قلبك كل ما أحدثك به من كلام، واستمع إليه بأذنين مرهفتين.","3:11":"وامض إلى المسبيين من أبناء شعبك وقل لهم: هذا ما يعلنه السيد الرب. سواء سمعوا لك أو أبوا».","3:12":"ثم حملني الروح، فسمعت خلفي صوت زلزلة عنيفة قائلا: «مبارك مجد الرب من مكانه».","3:13":"فكان ذلك صوت أجنحة حين تلامست، وصوت العجلات المجاورة لها، فبدا كجلبة زلزال عنيف.","3:14":"وهكذا حلق بي روح الرب وحملني بعيدا، وقد جاشت حرارة روحي بمرارة نفسي، ولكن كانت يد الرب علي شديدة.","3:15":"ثم أقبلت على المسبيين القاطنين إلى جوار نهر خابور عند تل أبيب، فأقمت هناك حيث يسكنون متحيرا سبعة أيام.","3:16":"وفي ختام السبعة الأيام، أوحى إلي الرب بكلمته قائلا:","3:17":"«ياابن آدم، قد جعلتك رقيبا لشعب إسرائيل، فأصغ إلى كلمتي وأنذرهم بها على لساني.","3:18":"فإذا قلت للشرير: أنت لابد مائت، وأنت لم تنذره ولم تحذره ليرجع عن طرقه الأثيمة فيحيا، فإن ذلك الشرير يموت بذنبه، أما دمه فمن يدك أطلبه.","3:19":"لكن إن أنذرت الشرير ولم يرجع عن شره وعن طرقه الأثيمة، فإنه يموت بذنبه، وتنجو أنت بنفسك.","3:20":"وكذلك إن حاد البار عن بره وارتكب الإثم، ونصبت أمامه معثرة، فإنه يموت. ولأنك لم تنذره فإنه يموت بذنبه ولا تذكر بعد أعماله الصالحة التي قام بها، أما دمه فمن يدك أطلبه.","3:21":"أما إن كنت قد أنذرت البار حتى لا يخطيء، ولم يخطيء، فإنه حتما يحيا لأنه قبل الإنذار، وتنجو أنت بنفسك».","3:22":"ثم كانت هناك علي يد الرب فقال لي: «قم اخرج إلى السهل فأخاطبك».","3:23":"فنهضت ومضيت إلى السهل، وهناك رأيت مجد الرب واقفا، مماثلا لمجد الرب الذي رأيته عند نهر خابور، فانطرحت على وجهي.","3:24":"فدخل في الروح وأقامني على قدمي، ثم قال لي: «اذهب واعتزل في بيتك.","3:25":"وأنت ياابن آدم، ها هم يربطونك بالحبال ويقيدونك فلا تخرج في ما بينهم.","3:26":"وألصق لسانك بحنكك فتبكم وتكف عن تقريعهم لأنهم شعب متمرد.","3:27":"ولكن عندما أخاطبك، أفتح فمك فتقول لهم: هذا ما يعلنه الرب، من يسمع فليسمع، ومن يأب فليمتنع، لأنهم شعب متمرد».","4:1":"أما أنت ياابن آدم فخذ لنفسك لبنة وابسطها أمامك وارسم عليها مدينة أورشليم،","4:2":"وأقم عليها حصارا، وابن برجا، وانصب عليها متراسا، وطوقها بالجيوش، وأحطها من كل جانب بالمجانق،","4:3":"ثم خذ لنفسك صاجا من حديد واجعله سورا من حديد بينك وبين المدينة، وثبت وجهك عليها فتصبح محاصرة وأنت تحاصرها، فتكون هذه علامة لشعب إسرائيل.","4:4":"أما أنت فاتكيء على جانبك الأيسر، وضع عليه إثم شعب إسرائيل، إذ أنك تحمل إثمهم على حسب عدد الأيام التي تتكيء فيها عليه.","4:5":"فإني قد جعلت لك عدد أيام كعدد سنوات إثمهم: ثلاث مئة وتسعين يوما. فتحمل عبء إثم شعب إسرائيل.","4:6":"وحالما تكملها عد فاتكيء على جانبك الأيمن، واحمل إثم شعب يهوذا أربعين يوما. إذ جعلت كل يوم مقابل سنة.","4:7":"ثم ثبت وجهك نحو حصار أورشليم بذراع مكشوفة، وتنبأ عليها،","4:8":"وها أنا أوثقك بحبال لئلا تتقلب من جنب إلى جنب حتى تكتمل أيام حصارك.","4:9":"أما أنت فخذ لنفسك قمحا وشعيرا وفولا وعدسا ودخنا وكرسنة، واعجنها في وعاء واحد، واصنع لنفسك خبزا تأكل منه ثلاث مئة وتسعين يوما كعدد الأيام التي تتكيء فيها على جنبك.","4:10":"ويكون وزن كمية الطعام التي تأكلها في كل يوم تعادل عشرين شاقلا (نحو مئتين وأربعين جراما). تأكل وجبة واحدة في اليوم.","4:11":"وتشرب الماء بالكيل، فلا يزيد عن سدس الهين (نحو ثلثي لتر)، تشرب منه بين حين وآخر.","4:12":"وتأكله ككعك الشعير، بعد أن تخبزه على مشهد منهم فوق براز الإنسان.","4:13":"لأنه هكذا سيأكل أبناء إسرائيل خبزهم النجس بين الأمم الذين أجليهم إليهم».","4:14":"ولكني قلت: «آه، أيها السيد الرب، أنا لم أنجس نفسي أبدا فمنذ حداثتي حتى الآن لم آكل ميتة أو فريسة، ولم يدخل فمي لحم نجس».","4:15":"فقال: «انظر ها أنا أعطيك بعر البقر لتستعيض به عن براز الإنسان لتصنع عليه خبزك.","4:16":"ياابن آدم، ها أنا أبيد مؤونة الخبز في أورشليم، فيأكلون الخبز بالوزن معجونا بالغم، ويشربون الماء بالكيل ممزوجا بالحيرة.","4:17":"إذ يعوزهم الخبز والماء، ويلجأ الواحد إلى أخيه وقد اعترتهم الحيرة فيفنون جميعا بإثمهم.","5:1":"أما أنت ياابن آدم فخذ لنفسك سيفا حادا استخدمه كموسى الحلاق لتحلق رأسك ولحيتك، ثم خذ لنفسك ميزانا واقسم الشعر إلى ثلاثة أثلاث،","5:2":"واحرق بالنار ثلثا في وسط المدينة إذا اكتملت أيام الحصار، ثم تناول ثلثا آخر واضربه بالسيف حول خريطة المدينة المرسومة. أما الثلث الأخير فذره مع الريح، وأنا أستل سيفا خلفه.","5:3":"ولكن احتفظ بكمية قليلة منه وصرها في أطراف ثوبك.","5:4":"كذلك خذ بعضا من الشعر واطرحه في النار ليحترق، فتندلع منه نار على كل شعب إسرائيل».","5:5":"وهذا ما يعلنه السيد الرب: «هذه هي أورشليم التي أقمتها في وسط الشعوب تحيط بها الأراضي،","5:6":"فخالفت أحكامي بأشر مما خالفتها الأمم وسكان الأراضي المحيطة بها، إذ تنكروا لأحكامي، وفرائضي لم يمارسوها.","5:7":"لذلك من حيث أنكم تمردتم أكثر من الأمم المحيطة بكم، ولم تمارسوا فرائضي ولم تعملوا بمقتضى أحكامي، ولا بمقتضى أحكام الأمم التي حولكم.","5:8":"ها أنا أيضا أنقلب عليك ياأورشليم، وأجري عليك قضاء على مشهد من الأمم،","5:9":"فأصنع بك ما لم أصنعه من قبل، وما لن أصنع مثله من بعد، عقابا لك على جميع أرجاسك.","5:10":"إذ يأكل الآباء أبناءهم، والأبناء آباءهم، لأنني أجري فيك قضاء وأذري بقيتك كلها مع كل ريح.","5:11":"لهذا حي أنا يقول السيد الرب، لأنك قد دنست مقدسي بكل أصنامك المكروهة، وبجميع رجاساتك، فأنا أيضا أستأصل، ولا تترَأف عليك عيني ولا أعفو.","5:12":"ثلث سكانك يموتون بالوباء والجوع في وسطك، وثلث ثان يقتل حولك بالسيف، وثلث أخير أشتته بين الأمم وأتعقبه بسيف مسلول.","5:13":"وهكذا أنفس عن غضبي ويخمد سخطي إذ أكون قد انتقمت. وحين يستكين حنقي عليهم يدركون أني أنا الرب الذي أصدرت قضائي في احتدام غيرتي.","5:14":"وأجعلك خرابا وعارا بين الأمم المحيطة بك وأمام كل من يجتاز بك،","5:15":"فتكونين عارا ولعنة وعبرة ومثار دهشة للأمم المحيطة بك حين أنفذ فيك قضائي بغضب وغيظ وتقريعات حانقة. أنا الرب قد تكلمت.","5:16":"وعندما أرسل عليهم سهام الجوع المميتة التي أعدت للتدمير، السهام التي أرسلتها لخرابكم، عندئذ أزيد من الجوع عليكم وأبيد مؤونة خبزكم،","5:17":"وأرسل عليكم المجاعة والوحوش الضارية، فتثكلكم ويعمكم الوباء وسفك الدماء، وأجلب عليكم السيف. أنا الرب قد قضيت»."}};